(function(){
  var C=window.YLT_CFG||{};var books=C.books||(window.GAME_CONFIG&&window.GAME_CONFIG.books)||[];var byId={};for(var i=0;i<books.length;i++)byId[books[i].id]=books[i];
  function acc(id,chs){var b=byId[id];if(!b)return;b.chapters=(b.chapters||[]).concat(chs);}
  acc("b_jingyue",[{"n": 28, "text": "卷二十八\n\n胡、甘草，以排脓清肝，数剂而溃，以八珍加柴胡，补其气血，数剂而愈。 \n春元凌待之，虚而服克伐药，几至危殆。余用托里健脾药而愈。秀才王文远，因劳苦患 \n之，服小柴胡汤而表证散后，用托里药，脓成，针之，而旬日愈。又胡判官，脓清脉弱，以 \n大补之药而已愈，因新婚复发，自用连翘消毒散，致泻痢不止，竟致不救。可见此证，属不足 \n者多矣，非补不可。大抵便毒属肝经，初起坚硬，肝主筋故也。五七日后，当赤软，脓成故 \n也。若尚坚硬，乃元气不能腐化。往往人见坚硬，只欲内消，反服攻散药，多致虚虚之祸， \n前此治者，即其验也。 \n一妇人，两拗肿痛，小腹痞满，小便数，白带时下，寒热往来，小水淋漓。余谓脾气 \n滞而血病，用龙胆泻肝汤渐愈，又用加味逍遥散，六味丸而全愈。 \n一妇人，小腹内如有所梗，两拗并人门俱肿，小便淋涩，经候不调，内热作渴，饮食 \n少思，腹内初如鸡卵而渐大，脉洪数而虚，左关尤甚，属肝胆郁结之证也。用加味归脾汤， \n肝火退，而脾土健，间以逍遥散下芦荟丸而愈。（俱薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>杨梅疮（六十二）\n\n属性：杨梅疮一证，以其肿突红烂，状如杨梅，故尔名之。其在西北人，则名为天泡疮；东南 \n人，又谓之广东疮。凡毒轻而小者，状类茱萸，故名茱萸疮。毒甚而大者，泛烂可畏，形如 \n绵花，故名绵花疮。大都此证，必由淫毒传染而生。盖此淫秽之毒，由精泄之后，气从精道 \n乘虚直透命门，以灌冲脉，所以外而皮毛，内而骨髓，凡冲脉所到之处，则无处不到，此其 \n危害最深最恶。设初起时，去毒不净，或治失其宜，而随至败烂殒命者，盖不少矣。或至二 \n三十年之后，犹然发为疯毒，或至烂头，或至烂鼻，或四肢幽隐之处，臭烂不可收拾，或遗 \n毒儿女，致患终身。其恶如此，静而思之，则有见此恶道，而不为寒心知避者，其愚亦甚矣 \n。故凡治之之法，最当知要，切不可不慎也。亦有不因淫毒传染，偶中湿热而患者，此不过 \n在皮毛肌肉之间，清去湿热，自当全愈，无足虑也。 \n一、今人每逢此患，或畏人知，或畏毒甚，而大用攻击峻利等药，多致邪毒未除，而元气先 \n败，或成劳瘵，或即殒命，或愈久愈甚，以致败坏不能收敛，皆元气先败之故也，余见之多 \n矣。故凡被此病者，切不可惊慌，亦不可专肆攻击，但按法渐解其毒，务使元气毫无损伤， \n则正能胜邪，虽毒无害。若正不胜邪，则微毒亦能杀人。此其要也，不可不察。 \n一、广疮治法，凡其初起而元阳未伤，毒亦未甚，宜速用清利，使从小便利去其毒，惟换肌消 \n毒散为第一，其次则五加皮饮亦妙。或兼火邪者，宜秘万仙遗粮汤。或禀气多弱者，宜茯苓 \n膏。凡此诸药，或十日，或半月，甚者一月，无不见效。一、凡生疮毒者，宜服槐花蕊，至二三 \n升，则毒从小便泄去，可免终身之患，真神方也。有按在下疳疮条中。此疮初起时，多有先 \n下疳，次便毒，而后疮出，是为一套。若便毒势甚，肿痛热秘，而元气素强者，即宜用会脓 \n散，或牡蛎散，先去其毒之大势，而后用前方诸药，亦要着也。一、此疮或久而不愈，或元气素 \n弱者，即宜用会脓散或牡蛎散，先去其毒之大势，而后用前方诸药，亦要着也。一、此疮或久而不愈， \n或元气素弱，或因克伐致虚，但见有正不胜邪之势，则当酌其轻重，或以纯补元气为主，凡脾肾阴阳 \n气血，皆宜随证用方，但使气血得复，则虽毒无害。最忌见不真而执两端，则终归无益，亦 \n是要着。 \n一、饮食宜否，有谓宜忌口者，有谓不宜忌口者，而任其发透，总之亦有其要。盖疮毒初染 \n，毒本未甚，此时，只宜清利，使毒渐消为善。若食发物，则愈发愈多，而毒愈甚矣，此则 \n宜忌之时也。若疮毒已久，元气已弱，脓汁既多，血气既耗，斯时也，非以药食滋补，则日 \n见消败，何以收效。此则不宜忌者也。宜忌不宜忌，是亦宜补不宜补之法耳。使不知辨，安能无误。 \n一、疮生头面，或遍身不便处，欲其速愈，但用点药，则二三日可以脱落，亦神妙者也。但 \n此惟治标之法耳。方在新因。（四十二） \n一、疮毒久蓄，发为疯毒，亦名杨梅痈漏，或蚀筋，或腐骨，溃烂不收，最为恶候，近来治 \n法，惟五宝丹为最效，及徐东皋杨梅痈漏方，或秘传水银膏，宜择用之。 \n立斋曰∶天泡疮，属元气不足，邪气所乘，亦有传染而患。受证在肝肾二经，故多在下 \n体发起，有先筋骨痛而后患者，有先患而后痛者，有疮凸赤作痛，热毒炽甚也。疮微作痛， \n毒将杀也。疮色白而不结痂，阳气虚也。色赤而不结痂，阴血虚也。瘙痒脉虚浮，气不相荣 \n也。瘙痒脉浮数，血不相荣也。臀背间或颈间作痒，膀胱阴虚也。阴器股内作痒，肝经血虚 \n也。阴囊作痒重坠，肝经阴虚湿热也。小便频数，短少色赤，肝经阴虚也。小便频数，短少 \n色白，脾肺气虚也。面目搔痒或变赤，外邪相搏也。眉间痒或毛落，肝胆血燥也。饮食少思 \n，口干饮汤，胃气虚也。饮食不化，大便不实，脾气虚也。清晨或夜间泄泻，脾肾虚也。 \n又《治法》曰∶若表实者，先用荆防败毒散，解散之。里实者，先用内疏黄连汤，通导 \n之。表里俱实者，防风通圣散，双解之。邪热在肝经者，龙胆泻肝汤，清解之。后用换肌消 \n毒散为主，愈后再无筋骨疼痛之患。气虚者，四君子汤。血虚者，四物汤。气血俱虚者，八 \n珍汤。俱加兼证之药治之，自无不愈。若治失其法，有蚀伤眼目，腐烂玉茎，拳挛肢体者， \n但用九味芦荟丸，以清肝火，六味丸，以生肾水，蠲痹消毒散，以养血祛邪，亦有可生者。 \n若服轻粉等药，反收毒于内，以致迭发。或概服防风通圣散，气血愈虚，因而不治者多矣。 \n凡有肿硬或作痛，外用蒜灸，及敷冲和膏，内服补药，并效。 \n一男子，遍身皆患，脉浮而数，以荆防败毒散治之，表证乃退。以仙方活命饮，六剂疮 \n渐愈，兼饮萆 汤，月余而愈。 \n一男子，下部生疳，诸药不应，延及遍身，突肿状似番花，筋挛骨痛，至夜尤甚，此肝 \n肾二经湿热所致。先以导水丸五服，次以龙胆泻肝汤数剂，再与除湿健脾之药，外贴神异膏 \n，吸其脓隔，蒜灸拔其毒而愈。 \n一童子，玉茎患之，延及小腹数枚，作痛发热，以小柴胡汤吞芦荟丸，更贴神异膏，月余而安。 \n一儒者，患前证，先玉茎作痒出水，后阴囊股内小腹胁臂发小 ，或干或脓窠，误服 \n祛风等药，肢体倦怠，恶寒发热，饮食渐减，大便不实，脉见浮弦，两尺浮数，此肾水虚热 \n，肝木乘脾土也。用六味地黄丸、补中益气汤为主，佐以换肌消毒散而愈。 \n一人患此，服攻毒等药，患处凸而色赤作痛，肢体倦怠，恶寒发热，脉浮而虚，此元气 \n复伤，而邪气实也，用补中益气汤，二剂而愈。 \n进士刘华甫，患之数月，用轻粉、朱砂等药，头面背臀各结一块，二寸许，溃而形气消 \n弱，寒热口干，舌燥唇裂，小便淋漓，痰涎上壅，饮食少思。此脾胃伤，诸脏弱，而虚火动 \n也。先用六君子二十余剂，又用补中益气汤加山药、山茱萸、麦门冬、五味服之，胃气复， \n而诸证愈。惟小便未清，痰涎未止，用加减八味丸而痊。 \n一男子，患杨梅疮后，两腿一臂，各溃二寸许一穴，脓水淋漓，少食无睡，久而不愈， \n以八珍汤加茯神、枣仁炒服，每日以蒜捣烂涂患处，灸良久，随贴膏药，数日少可。却用豆 \n豉饼灸之，更服十全大补汤而愈。 \n一妇人，患之皆愈，惟两腿两 各烂一块如掌，兼筋挛骨痛，三载不愈，诸药不应。日 \n晡热甚，饮食少思，以萆 汤，兼逍遥散，倍用茯苓、白术数剂，热止食进。贴神异膏， \n更服八珍汤加牛膝、杜仲、木瓜，三十余剂而痊。 \n一妇人患此，燃轻粉药于被中熏之，致遍身皮塌，脓水淋漓，不能起居，以滑石、黄柏 \n、绿豆粉末等药铺席上，令可卧，更服神功托里散，月余而痊。（俱薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>囊痈（六十三）\n\n属性：立斋曰∶囊痈，属肝肾二经，阴虚湿热下注也。肿痛未作脓者，疏肝导湿。肿硬发热者 \n，清肝降火。已溃者，滋阴托里。大抵此证，属阴道亏，湿热不利所致，故滋阴除湿药不可 \n缺。常治肿痛小便秘涩者，用除湿为主，滋阴佐之。肿痛已退，便利已和者，除湿滋阴药， \n相兼用之。欲其成脓，用托里为主，滋阴佐之，候脓成，即针之，仍用托里滋阴。湿毒已尽 \n者，专用托里。如脓清，或多，或敛迟者，用大补之剂，及豆豉饼灸之。若溃后，虚而不补 \n，少壮者成漏，老弱者不治。脓清作渴脉大者，亦不治。 \n又法曰∶若小便涩滞者，先用分利，以泄其毒，继补阴，以令其自消。若湿热退，而仍 \n肿痛，宜补阴托里，以速其脓。脓肿而便秘者，热毒壅闭也，先用托里消毒散，后用针以泄 \n之，脓去即解。若脓去而肿痛不减者，热毒未解也，用清肝益营汤。口干而小便数者，肾经 \n虚热也，六味丸。内热晡热者，肝经血虚也，四物加参、术。体倦食少者，脾气虚热也，补 \n中益气汤。脓水清稀者，气血俱虚也，十全大补汤。此证虽大溃，而睾丸悬露，治得其法， \n旬日间肉可渐生而愈。若专攻其疮，阴道益虚，则肿者不能溃，溃者不能敛，少壮者成痼疾 \n，老弱者多致不起。亦有患痔久漏，而串及于囊者，当兼治其痔，切忌寒药克伐，亏损胃气 \n。 \n马益卿曰∶囊痈者，湿热下注也。有作脓者，此浊气下流入渗道，因阴道或亏，水道不 \n利而然。脓尽自安，不药可也，惟在善于调摄耳。又有因腹肿渐流入囊，肿甚而囊自裂开， \n睾丸悬挂水出，以麸炭末敷之，外以紫苏包裹，仰卧而养之。痈疽入囊者，予尝治数人，悉 \n以湿热入肝经施治，而用补阴佐之，虽脓溃皮脱，睾丸悬挂，皆不死。 \n一男子患此，未作脓而肿痛，以加味龙胆泻肝汤，二剂少愈，更以四物汤加木通、知母、黄柏而愈。 \n一男子， 肿痛甚，小便涩，发热脉数，以龙胆泻肝汤，倍用车前子、木通、茯苓，四 \n剂势去其半。仍用前汤，止加黄柏、金银花四剂，又减二三，便利如常。唯一处不消，此欲 \n成脓也。再用前汤加金银花、白芷、皂角刺六剂。微肿痛，脉滑数，乃脓已成，令针之，肿 \n痛悉退。投滋阴托里药，及苏叶末敷之而愈。 \n一膏粱之客，阴囊肿胀，小便不利，此中焦积热，乘虚下注，先用龙胆泻肝汤，加黄 \n柏、牛膝，四剂渐愈，后用补阴八珍汤，加柴胡、山栀而愈。后不守禁忌，前证复作，仍用 \n补阴八珍汤、补中益气汤、六味丸而痊。又因劳倦发热，自用四物、黄柏、知母之类，虚证 \n悉具，疮口大开。余谓五脏气血俱虚也，朝用补中益气，夕用六君加当归各五十余剂，疮口 \n始敛，又用六味丸，调补而愈。 \n儒者陈时用，考试不利，一夕饮烧酒入房，其妻不纳，翌日阴囊肿胀 痛，遣人求治 \n，与清肝火除湿热之剂。城门夜闭，不及归服。翌日报云，夜来阴囊悉腐，玉茎下面贴囊者 \n亦腐，此肝火挟酒毒而湿热炽盛也。仍以清肝火除湿之剂加参、 、归、术四剂，腐肉尽 \n脱，睾丸悬挂，用大补气血并涂当归膏，囊茎全复而愈。 \n一男子，醉而入房，阴囊肿胀大如斗，小腹胀闷，小水淋赤，发热口干，痰涎壅盛，此膀胱 \n阴虚，酒毒所乘也。用六味丸料加车前、牛膝作饮，下滋肾丸，诸证顿退。再加五味、麦冬 \n，二剂而愈。却以补中益气加麦冬、五味，调理而瘳。若全用淡渗，复损真阴，决致不起。（俱薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>悬痈（六十四）\n\n属性：立斋曰∶悬痈，谓疮生于玉茎之后，谷道之前，属足三阴亏损之证。轻则为漏，沥尽气 \n血而亡，重则内溃而即殒。大抵此证，原属肝肾阴虚，故不足之人多患之，虽一于补，犹恐 \n不治，况脓成而又克伐，不死何俟。即寒凉之剂，亦不可过用，恐伤胃气。惟制甘草一药， \n不损血气，不动脏腑，其功甚捷，最宜用之，不可忽也。 痛或发热者，清肝解毒。肿痛 \n者，解毒为主。肿痛而小便赤涩者，肝经湿热也，宜分利清肝。不作脓，或不溃者，气血虚也 \n，宜补之。 \n又《治法》曰∶凡初起湿热肿痛，或小便赤涩，宜先以制甘草一二剂，及隔蒜灸，更 \n饮龙胆泻肝汤。 肿痛甚，宜仙方活命饮，以制甘草佐之。若发热肿痛者，以小柴胡汤加 \n车前、黄柏、芎、归。若不成脓，或脓成不溃者，八珍汤补之。若脓已成者，急针之。已溃者 \n，用八珍汤加制甘草、柴胡梢、酒炒黄柏、知母。小便涩而脉有力者，仍用龙胆泻肝汤加制 \n甘草。小便涩而脉无力者，清心莲子饮加制甘草。脓清不敛者，用大补之剂，间以豆豉饼灸 \n之。久而不敛者，用附子饼灸之，并效。欲其生肌收敛，肾虚者，六味地黄丸。血虚者，四 \n物加参、术。气虚者，四君加芎、归。脾虚者，补中益气汤。气血俱虚者，八珍汤，并十全 \n大补汤。若用寒凉消毒则误矣。 \n陈良甫曰∶治谷道前后生痈，谓之悬痈，用粉甘草一两截断，以涧水浸润，炙令透内， \n细锉，用无灰酒煎服。有人患此已破，服两剂，疮即合。 \n一弱人，茎根结核如大豆许，劳则肿痛，先以十全大补汤去桂加车前、麦冬、酒制黄柏 \n、知母少愈，更服制甘草渐愈，仍以四物车前之类而消。 \n一男子患此， 痛发热，以龙胆泻肝汤二剂，及制甘草四剂而溃，再用滋阴之剂而愈。 \n若或脓未成，以葱炒熟敷上，冷即易之，隔蒜灸之亦可。数日不消，或不溃，或溃而不敛， \n以十全大补汤加柴胡梢为主，间服制甘草并效。若不保守，必成漏矣。 \n一儒者，患悬痈，服坎离丸及四物、黄柏知母之类不应。脉浮洪，按之微细，余以为 \n足三阴之虚，用托里散及补阴八珍汤渐愈。又用六味丸、补中益气汤，调补化源，半载而痊 \n。大凡疮疡等证，若肾经火气亢盛，致阴水不能生化，而患阴虚发热者，宜用坎离丸，取其 \n苦寒能化水中之火，令火气衰而水自生。若阳气衰弱，致阴水不能生化，而患阴虚发热者 \n，宜用六味丸，取其酸温能生火中之水，使阳气旺而阴自生。况此证属肾经精气亏损者，十 \n有八九，属肾经阳气亢盛者，十无一二。然江南之人患此者，多属脾经阴血亏损，元气下陷 \n，须用补中益气汤，升补阳气，使阳生而阴长。若嗜欲过多，亏损真阴者，宜用六味丸，补 \n肾经元气，以生精血，仍用补中益气汤，以培脾肺之生气，而滋肾水。经云阴虚者，脾虚也 \n，但多误认为肾经火证，用黄柏知母之类，复伤脾肺，绝其化源，反致不起，惜哉。 \n通府张敬之，患前证，久不愈，日晡热甚，作渴，烦而喘，或用四物汤、黄柏、知母之 \n类，病益甚，肢体倦，少食，大便不实，小便频数。谓余曰∶何也。余曰∶此脾虚之证，前 \n药复伤而然，遂用补中益气汤加茯苓、半夏数剂，饮食渐进，前证渐愈。更加麦冬、五味， \n调理乃痊。经曰∶脾属太阴，为阴土而主生血。故东垣云∶脾虚元气下陷，发热烦渴，肢体 \n倦怠等证，用补中益气汤，以升补阳气而生阴血。若误认为肾虚火盛，而用四物黄柏知母之 \n类，反伤脾胃生气，是虚其虚矣。况黄柏知母乃泻阳损阴之剂，若非膀胱阳火盛，而不能生 \n阴水，以致发热者，不可用也。（俱薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>脱疽（六十五）\n\n属性：立斋曰∶脱疽，以疔患于足，或足趾，重者溃脱，故名之。亦有患于手指者，名曰蛀节 \n疔。重者腐去本节，轻者筋挛。此证固膏粱浓味，酒面炙爆，积毒所致，或不慎房劳，肾水 \n枯竭，或服丹石补药，致有先渴而后患者，有先患而后渴者，皆肾水亏涸，不能制火也。此证 \n情势虽小，其恶甚大，不问肿溃，皆须隔蒜灸之。不痛者，宜明灸之，庶得少杀其毒。凡初 \n发而色黑不溃者，不治。毒延入腹者，不治。色黑不痛者，亦不治。色赤作痛自溃者，可治 \n。若失解其毒，以致肉死色黑者，急斩去之。亦有因修手足口咬等伤而致者，若元气虚弱， \n或犯房事，或外涂寒凉，内服克伐，损伤脾胃，以致患处不溃，或黑延上足，亦多致死。重 \n者须当用脚刀转解周骨，轻拽去之，使筋随骨出，而毒得泄，亦不痛。否则毒筋内断，虽去 \n而仍溃。且偏僻之处，气血罕到，药难导达。况攻毒之剂，必先伤脾胃，反损元气，不若灸 \n法为良。重者，须解去为善。故孙真人云∶在肉则割，在指则截。使不如此，则必致夭殁而 \n害尤甚矣。况患处已坏，虽解不痛，又何惮而不为乎。患者当知之。若女人患此，又多因札 \n缚，血脉不通，遂成死肉，惟当壮其脾胃，行其经络，生其血气则愈。 \n又《治法》曰∶色赤作痛者，元气虚而湿毒壅盛也，先用隔蒜灸，更用解毒药，如活命 \n饮、托里散之属。仍速用补剂，如十全大补汤、加减八味丸，则毒瓦斯不致上侵，元气不致亏 \n损，庶可保生。作渴者，宜滋阴降火。色黑者，不治。 \n崔氏方，治手足甲疽，或因修甲伤肉，或因损足成疮，溃烂上脚，用绿矾置铁板上， \n沸色赤如溶金色者为真，沸定，取出研末，以盐汤洗而搽之。 \n一男子，足趾患之， 痛色赤，发热，隔蒜灸之，更以人参败毒散去桔梗，加金银花 \n、白芷、大黄，二剂痛止。又用十宣散去桔梗、官桂，加天花粉、金银花，数剂而痊。 \n一男子，足趾患之，色紫不痛，隔蒜灸五十余壮，尚不知痛，又明灸百壮始痛，更投仙方 \n活命饮四剂，乃以托里药，溃脱而愈。 \n一膏粱之人，先作渴足热，后足大趾赤痛，六脉洪数而无力，左尺为甚，予谓此足三阴 \n虚证，当滋化源为主。彼固服除湿败毒等剂，元气益虚，色黯延足。余乃朝用补中益气汤， \n夕用补阴八珍汤，各三十余剂，及桑枝灸，溃而脓清，作渴不止。遂朝以前汤送加减八味丸 \n，夕用十全大补汤，三十余剂而痊。是时，同患此证，服败毒之药者，俱不效。 \n一膏粱人，年逾五十，亦患此，色紫黑，脚 痛，喜其饮食如故，动息自宁，为疮疡之 \n善证，尚可治。遂以连翘消毒散六剂，更以金银花、甘草节、栝蒌二十余剂，患指溃脱，再以 \n当归、川芎、连翘、生地、金银花、白芷，二十余剂而愈。 \n一刍荛，左足趾患一泡，麻木色赤，次日趾黑，五日其足黑冷，不知疼痛，脉沉细， \n此脾胃受毒所致。以飞龙夺命丹一服，翌日令割去足上死肉，割后骨始痛而可救。遂以十全 \n大补汤治之而愈。盖死肉乃毒瓦斯盛，而拒绝营气所致。况至阴之下，气血难达。经曰风淫末 \n疾，即此是也。向若攻伐之，则元气愈盛，邪气愈盛，乘虚上侵，必致不救。（俱薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>脚发（六十六）\n\n属性：立斋曰∶脚发之证，属足三阴精血亏损，或足三阳湿热下注。若色赤肿痛而溃脓者，属湿热 \n下注，为可治。若色微赤微肿而脓清者，属精血亏损，为难治。若黑黯不肿痛，不溃脓，烦 \n热作渴，小便淋漓者，阴败末传恶证也，为不治。治法∶湿热下注者，先用隔蒜灸、活命饮 \n，以解壅毒，次服益气汤、六味丸，以补精气。若色黯不痛者，着肉灸、桑枝灸，以行壅滞 \n，助阳气；更用十全大补汤，八味丸，以壮脾土，滋化源，多有生者。若专治其疮，复伤生 \n气，吾未见其生者。 \n阁老靳介庵，脚趾缝作痒，出水肿 ，脚面敷止痒之药不应，服除湿之药益甚。余 \n以为阴虚湿热下注，用六味地黄丸、补中益气汤而愈。 \n大参李北溪，左足赤肿作痛，此足三阳经湿热下注。先用隔蒜灸，与活命饮一剂，其 \n痛顿止，灸患处出水，赤肿顿消。次用托里消毒散四剂，灸患处，出脓而愈。 \n一儒者患此，肿硬色白，两月余矣。此足三阴亏损，为外寒所侵也，用大防风汤，及 \n十全大补汤，兼服而消。后场屋不利，饮食劳倦，前证复作，盗汗内热，饮食不化，便滑肌 \n瘦，此脾土虚寒，而命门火不能相生。用八味丸、益气汤，百余剂，喜其年壮得愈。 \n一男子，脚心发热，作渴引饮，或用四物芩连知柏之类，腹痛作呕，烦热大渴，此足三 \n阴亏损，前药复伤脾胃也。先用六君加炮姜，数剂而脾胃醒，再用补中益气加茯苓、半夏 \n，而脾胃健，乃以加减八味丸，兼服半载而愈。 \n一儒者，脚心发热作痒，以滚汤浸渍而出水，肌体骨立，作渴吐痰，此脾肾虚而水泛为痰 \n也。服益气汤、六味丸年余，元气复而诸证愈。（俱薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>足跟疮（六十七）\n\n属性：立斋曰∶足跟乃督脉发源之所，肾经所过之地。若饮食失节，起居失宜，亏足三阴经， \n则成疮矣。若漫肿寒热，或体倦少食，属脾虚下陷也，用补中益气汤。若晡热作痛，头目不清 \n，属脾虚阴火也，前汤并六味丸。若痰涎上升，或口舌生疮，属肾水干涸也，前汤并加减八 \n味丸。凡此皆当滋其化源，若治其外则误矣。俗云，兔啮疮者，盖猎人被兔咬足跟，或疮久 \n而不敛，必气血沥尽而死。若人脚跟患此，亦终难愈，因名兔啮也。 \n一男子，素不慎起居，内热引饮作渴，体倦两足发热，后足跟作痛。或用清热除湿之剂 \n，更加发肿。又服败毒之药， 赤痛甚。复用清热祛毒，溃裂番张，状如赤榴，热痛如锥， \n内热晡热。此以足三阴亏损，朝用十全大补汤，夕用加减八味丸，外敷当归膏，两月余而愈 \n。其服消毒等药而殁者，不能枚举。 \n太尹陈汝邻，两腿酸软，或赤或白，足跟患肿，或痛或痒后痛，而或如无皮，或如皱裂 \n，日晡至夜，胀痛 热。用补中益气汤，加八味丸料，补其肝肾而愈。 \n一男子，患足跟疮肿痛，服消毒散，搽追蚀药，虚证叠出，形体骨立，自分必死。余用 \n十全大补汤兼山药、山茱萸，两月余而愈。 \n一妇人，两足发热，两跟作痛，日晡热甚。余以为肝肾血虚，用加减逍遥散、六味地黄 \n丸，五十余剂而愈。 \n杨锦衣，脚跟生疮如豆许，痛甚，状似伤寒。以还少丹、内塞散治之，稍可。次因纳宠 \n作痛，反服攻毒药，致血气愈弱，腿膝痿弱而死。盖足跟乃二FS 发源之处，肾经所由之地。 \n若疮口不合，则FS 气不能发生，肾气由此而泄，故为终身之疾。况彼疮先得于虚，复不知戒 \n，虽大补气血，犹恐不及，安可服暴悍攻毒之药，以戕贼之乎。（俱薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>肾藏风疮（六十八）\n\n属性：立斋曰∶肾藏风，属肾虚，风邪乘于 胫，以致皮肤如癣，或渐涎上腿，久则延及遍身 \n。外证则搔痒成疮，脓水淋漓，眼目昏花。内证则口燥舌干，腰腿倦怠，吐痰发热，盗汗体 \n疲。治法∶用六味丸为主，佐以四生散。若脾胃虚弱者，用补中益气汤为主，佐以六味丸、四生散为善。 \n钦天薛循斋，年六十有一，两 患之，脓水淋漓，发热吐痰，四年矣。此肾脏风证也， \n与六味丸、四生散而瘥。年余复作，延及遍身，日晡益甚，痰渴盗汗，唇舌生疮，两目昏赤 \n，皆肾经虚火而水泛为痰也，用加减八味丸而愈。三年后，小便淋沥，茎中涩痛，此思色精 \n不出而内败也，用前丸，及补中益气汤加麦冬、五味而愈。（薛按） \n一、凡肾囊湿痒，抓破成疮，俗名肾上风也。外治之法，但以黄丹、枯矾、生牡蛎，共为末 \n，搽擦即愈。或以蛇床子同白矾煎汤洗之，亦可。 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>疮（六十九）\n\n属性：立斋曰∶ 疮，生于两 ，初起赤肿，久而腐溃，或浸淫瘙痒，破而脓水淋漓。盖因饮 \n食起居，亏损肝肾，或因阴火下流，外邪相搏而致。外 ，属足三阳湿热，可治。内 ，属 \n足三阴虚热，难治。若初起恶寒壮热， 肿作痛者，属湿热，用槟苏散。若漫肿作痛，或不 \n肿不痛者，属阴虚，用补阴八珍汤。若脓水淋漓，体倦食少，内热口干者，属脾虚，用补中 \n益气汤加茯苓、酒炒白芍药。若午后热，或作痛，头目不清者，属阴水，前汤加酒炒黑黄柏 \n，及六味地黄丸。若午后发热，至子时方止，是血虚，前汤加芎、归、熟地。若郁结伤脾而 \n甚者，用归脾汤加柴胡、山栀。若怒动肝火而甚者，用补中益气汤加川芎、山栀、黄芩。若 \n内热口干，肢体倦怠，或痰涎上升，或口舌生疮，属脾肾虚热，用六味地黄丸、补中益气汤 \n。若患处黑黯，肢体畏寒，饮食少思，属脾肾虚败，用八味地黄丸。若误用攻伐，复损胃气 \n，绝其化源，治亦难矣。 \n鸿胪翟少溪，两 生疮，渐至遍身发热，吐痰，口燥咽干，盗汗心烦，溺赤足热，日 \n晡益甚，形体日瘦，此肾经虚火也。用六味丸，不一月，诸证悉退，三月元气平复。 \n陈湖陆懋诚，素因阴虚，过饮入房，发热腿痛似 疮。用发表之剂，两腿肿黯，热气如 \n雾，欲发痉，脉皆洪数，两尺尤大。余曰∶属足三阴虚，酒湿所乘，元气损而邪益甚耳。用 \n十全大补加山药、山茱萸、附子，一剂脉证顿退，却去附子，又二剂全愈。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>天泡疮（七十）\n\n属性：天泡疮，形如水泡，皮薄而泽，或生头面，或生遍身。乃太阴阳明风热所致，故见于皮 \n毛肌肉之间。宜清血凉血，热解则愈。如兼表邪而发热脉数者，宜荆防败毒散。如火盛者， \n或加芩、连、连翘、金银花、玄参之属。如 肿疼痛，脉数，便结者，此表里俱实也，宜 \n防风通圣散双解之。如外多毒水，以金黄散敷之，无有不愈。 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>赤白游风（七十一）\n\n属性：立斋曰∶赤白游风，属脾肺气虚，腠理不密，风热相搏，或寒闭腠理，内热拂郁，或因 \n虚火内动，外邪所乘，或肝火血热，风热所致。）治法∶若风热用小柴胡汤加防风、连翘。血 \n热，用四物汤加柴胡、山栀、丹皮。风热相搏，用荆防败毒散。内热外寒，用加味羌活汤。 \n胃气虚弱，用补中益气汤加羌活、防风，及消风散。血虚，用加味逍遥散。阴虚，逍遥散、 \n六味丸。肝肾虚热，用六味丸，则火自息，风自定，痒自止。若用祛风辛热之剂，则肝血愈 \n燥，风火愈炽，元气愈虚，腠理不闭，风客内淫，肾气受伤，相火翕合，血随火耗，反为难治矣。 \n一男子，秋间发疙瘩，此元气虚而外邪所侵也。先用九味羌活汤二剂，又用补中益汤 \n加羌防而愈。后不慎起居，盗汗晡热，口干唾痰，体倦懒言，用补中益气汤，加减八味丸而愈。 \n一妇人，身如丹毒，搔破脓水淋漓，热渴头晕，日晡益甚，用加味逍遥散而愈。 \n一女子，赤晕如霞，作痒发热，用加味小柴胡汤，加生地、连翘、丹皮而愈。（俱薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>翻花疮（七十二）\n\n属性：立斋曰∶翻花疮者，由疮疡溃后，肝火血燥生风所致。或疮口 肉突出，如菌大小不 \n同，或出如蛇头长短不一治法，当滋肝补气，外涂藜芦膏， 肉自入。须候元气渐复，脓 \n毒将尽，涂之有效，不然虽入而复溃。若误用刀针、蚀药、灸火，其势益甚，或出血不止， \n必致寒热呕吐等证，须大补脾胃为善。 \n判官张承恩，内股患痈将愈，翻出一肉如菌。余曰∶此属肝经风热血燥，当清肝热，养 \n肝血。彼为不然，乃内用降火，外用追蚀而复翻，翻而复蚀，其肉益大，元气益虚，始信余 \n言。遂内用栀子清肝散，外用藜芦膏而痊。 \n一上舍，素膏粱善怒，耳下结一核，从溃，而疮口翻张如菌， 连头痛，或胸胁作胀 \n，或内热寒热。或用清热消毒之药，年余未瘥。余用补中益气汤、六味地黄丸而寻愈。 \n一男子背疮，敛如豆许，翻出肉寸余。用消浊割击法，屡去屡大，此肝经血虚风热。余 \n用加味逍遥散三十余剂，涂藜芦膏而消，又用八珍汤，倍用参 归术而敛。 \n一妇人，素善怒，臂患痈，疮口出肉，长二寸许，此肝肾郁怒，气血虚而风内动也。用 \n加味逍遥散，涂藜芦膏而愈。后因怒患处胀闷，遍身汗出如雨，此肝经风热，风能散气故耳 \n。仍用前散，并八珍汤而愈。（俱薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>痔漏（七十三，附脏毒下血按）\n\n属性：丹溪曰∶漏疮，须先服补药，以生气血，即参 归术芎，大剂为主。外以炮附子为末， \n唾津和为饼，如三钱浓，安疮上，以艾炷灸之。漏大艾炷亦大，漏小艾炷亦小，但灸令微热 \n，不可令痛，干前易之，如因则止，来日如前，再灸直至肉平为效。亦有用附片灸之，以补 \n气血药作膏贴之。 \n立斋曰∶痔，属肝脾肾三经，凡阴经亏损者难治，多成漏证。若肺与大肠二经，风热 \n湿热者，热退自愈。若不守禁忌者，亦成漏证。此因醉饱入房，筋脉横解，精气脱泄，热毒 \n乘虚流注。或淫极强固其精，以致木乘火势而侮金。或炙爆浓味过多，或劳伤元气，阴虚 \n火炽，皆成斯疾。若破而不愈，即成漏矣。有串臀者，有患阴者，有患肠者，有秽从疮口而出 \n者，形虽不同，治颇相似。其肠头肿成块者，湿热也。作痛者，风热也。大便燥结者，火也 \n。溃而为脓者，热胜血也。当各推其所因而治之。 \n《治法》曰∶初起 痛便秘，小便不利者，宜清热凉血，润燥疏风。若气血虚，而为 \n寒凉伤损者，宜调养脾胃，滋补阴精。大便秘涩，或作痛者，润燥除湿。肛门坠痛者，泻火 \n导湿。下坠肿痛而痒者，祛风胜湿。小便涩滞肿痛者，清肝导湿。其成漏者，养元气，补阴 \n精为主。大凡痔漏下血，服凉血药不应者，必因中气虚不能摄血，非补中升阳之药不能愈，切忌 \n寒凉之剂。亦有伤湿热之食，成肠 而下脓血者， \n宜苦寒之剂内疏之。脉弦绝涩者，难治，滑大柔和者，易治。经云∶因而饱食，筋脉横解 \n，肠 为痔。其属肝脾肾也明矣。若有患痔而兼疝，患疝而兼下疳，皆属肝肾不足之变证 \n，但用地黄丸、益气汤，以滋化源为善。若专服寒凉治火者，无不致祸。 \n一男子，患痔成漏，每登厕则痛，以秦艽防风汤加条芩、枳壳，四剂而愈。以四物加升 \n麻、芩、连、荆、防，不复作。 \n一男子，患痔漏，每登厕则肛门下脱作痛，良久方收，以秦艽防风汤，数剂少愈。乃去 \n大黄加黄 、川芎、芍药，而痛止。更以补中益气汤，二十余剂后，再不脱。 \n一儒者，脓血淋漓，口干作渴，晡热便血，自汗盗汗。余谓此肝肾阴虚也，不信。仍服 \n四物芩连知柏之类，食少泄呕。余先用补中益气汤加茯苓、半夏、炮姜，脾胃渐醒。后用六 \n味丸朝夕服，两月余，诸证悉愈。 \n一男子患此，服寒凉之剂，清晨去后不实，食少体倦，口干作渴，小腹重坠。余用补中益气汤而下坠顿止 \n，用四神丸而食进便实，用地黄丸 \n而疮寻愈。（俱薛按） \n一男子，脏毒下血，服寒凉败毒药，不惟不能止，且饮食日减，肢体愈倦，脉数而涩。 \n先以补中益气汤，数剂少止。更以六君子汤加升麻、炮姜，四剂而止。乃去炮姜加芎、归， \n月余脾胃亦愈。尝治积热成风下血者，先以败毒散散之。胃寒气弱者，用四君子汤，或参苓 \n白术散补之，并效。 \n一男子，脏毒下血，脾气素弱，用六君子汤加芎归、枳壳、地榆、槐花，治之而愈。后 \n因谋事血复下，诸药不应。余意，思虑伤脾所致，遂投以归脾汤，四剂而痊。大抵此证所致 \n之由不一，当究其因而治之。丹溪云芎归汤一剂，乃调血之上品。热加赤茯苓、槐花，冷加 \n白茯苓、木香，此则自根自本之论也。虽然血气出于谷气，故大肠下血，以胃药收功，宜四 \n君子汤，或参苓白术散，以枳壳散、小乌沉汤和之，胃气一回，血自循经络矣。 \n凡肠风者，邪气外入，随感随见。脏毒者，蕴积毒久而始见。又云，人惟坐卧风湿，醉 \n饱房劳，生冷停寒，酒面积热，以致营血失道，渗入大肠，此肠风脏毒之所由作也。挟热下 \n血者，清而色鲜。挟冷下血者，浊而色黯。清则为肠风，浊者为脏毒。先便而后血者，其来 \n远。先血而后便者，其来近。治法大要，先当解散脾胃风邪。热则败毒散；冷则不换金正气 \n散，加川芎当归，后随其冷热治之。 \n一妇人，素患痔漏，每因热则下血数滴，以四物汤加黄连，治之即愈。后为大劳，疮发 \n肿痛，经水不止，脉洪大无力。此劳伤血气，火动而然也。用八珍汤加芩、连、蒲黄，二剂 \n而止。后去蒲黄芩连加地骨皮，数剂而安。丹溪曰∶妇人崩中者，由脏府伤损冲任二脉，血 \n气俱虚故也。若劳动过极，脏府俱伤，以致冲任气虚，不能约制经血，故忽然而下，谓之崩 \n中暴下，治宜大补气血之药，举养脾胃，微加镇坠心火之剂，以治其心，补阴泻阳，经自正 \n矣。（俱薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>痔漏（七十三，附脏毒下血按）\n\n属性：枯痔水澄膏 如神千金方 三品锭子 羊胆膏 熊胆膏外 水银枣子膏 蜗牛膏 \n一方∶凡痔疮初起，痛痒不止，以旧布鞋底烘热，频频熨之，冷则再烘再熨，其痛痒则止。 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>痔漏（七十三，附脏毒下血按）\n\n属性：命门灸七壮，治五种痔漏。长强灸，随年壮，治五痔便血最效。 \n一法∶治痔疾大如胡瓜，贯于肠头，发则疼痛僵仆，先以荆芥汤洗之，次以艾灸其上三五壮 \n，若觉一道热气贯入肠中，必大泻鲜血秽血，一时许觉痛甚，后其疾乃愈。 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>跌打损伤（七十四）\n\n属性：凡跌打损伤，或从高坠下，恶血流于内，不分何经之伤，皆肝之所主。盖肝主血也，故 \n凡败血凝滞，从其所属而必归于肝，多在胁肋小腹者，皆肝经之道也。若其壅肿痛甚，或发 \n热自汗，皆当酌其虚实，而以调血行经之药治之。 \n脉法∶如《内经》曰∶肝脉搏坚而长，色不青，当病坠。若搏因血在胁下，令人呕逆。 \n《金匮》云∶寸口脉浮微而涩，然当亡血，若汗出。设不汗出者，当身有疮，被刀斧所伤， \n亡血故也。《脉经》云∶金疮出血太多，其脉虚细沉小者生，浮数实大者死。砍刺出血不止 \n，其脉来大者，七日死，滑细者生。从高颠仆，内有瘀血，腹胀，脉坚强者生，小弱者死。 \n破伤有瘀血在内者，脉坚强实则生，虚小弱则死。若血亡过多者，脉细小则生，浮大数实则死 \n。皆为脉病不相应故也。 \n一、治法∶凡胸满胁胀者，宜行血。老弱者，宜行血活血。腹痛者，宜下血。瘀血不溃，或 \n溃而不敛，宜大补气血。若打扑坠堕稍轻，别无瘀血等证，而疼痛不止者，惟和气血，调经 \n脉，其痛自止。更以养气血，健脾胃，则无有不效。亦有痛伤胃气作呕，或不饮食者，以 \n四君子汤加当归、砂仁之类调之。若有瘀血不先消散，而加补剂，则成实实之祸。设无瘀血 \n而妄行攻利，则致虚虚之祸。故凡此证，须察所患轻重，有无瘀血，及元气虚实，不可概行 \n攻下，致成败证。盖打扑坠堕，皮肉不破，肚腹作痛者，必有瘀血在内，宜以复元活血汤攻 \n之。老弱者，四物汤加红花、桃仁、穿山甲，补而行之。若血去多而烦燥，此血虚也，名曰 \n亡血，宜补其血。如不应，当以独参汤补之。一、凡损伤不问老弱，及有无瘀血停积，俱宜服 \n童便。以酒佐之，推陈致新，其功甚大。若胁胀，或作痛，或发热烦燥，口干喜冷，惟饮热 \n童便一瓯，胜服他药。他药虽亦可取效，但有无瘀血恐不能尽识，反致误人，惟童便不动脏 \n腑，不伤气血，万无一失。尝询之诸营操军，常有坠马伤者，何以愈之。俱对曰，惟服热童 \n便即愈。此其屡试之验亦明矣。然惟胃虚作呕，及中寒泄泻者，不可服。大凡肿痛，或伤损 \n者，以葱捣烂炒热罨之，或用生姜葱白同捣烂，和面炒热罨之尤妙。或用生姜陈酒糟同捣烂 \n，炒热罨之亦可。外治损伤诸方，如秘传正骨丹、没药降圣丹、当归导滞散、黑丸子、本事 \n接骨方、十味没药丸、洗损伤等十余方，俱有妙用，所当详察。 \n立斋曰∶予于壬申年，被重车碾伤，闷瞀良久复苏，胸满如筑，气息不通。随饮热童便 \n一碗，胸宽气利，惟小腹作痛。吾乡银台徐东濠先生，与复元活血汤一剂，便血数升，肿痛 \n悉退，更服养血气药而痊。戊辰年，公事居庸，见覆车被伤者七八人，仆地呻吟，一人未苏 \n，予俱令以热童便灌之，皆得无事。 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>杖疮（七十五）\n\n属性：杖疮一证，凡其甚者，必以瘀血为患。血瘀在外者，浅则砭之，深则刺之，内溃者开之 \n，腐肉者取之。血瘀在内者，宜以活血流气之药和之，甚者利之行之，此治血凝之法也。然 \n其受刑之时，号叫则伤气，忍痛则伤血，悲愤则伤志，血气情志俱伤，虚所必至，若不培补 \n，则羸困日甚矣。况脾主肌肉，脾气受伤，则饮食必减，血脉损坏，则肌肉俱病。故凡即伤 \n之后，但察其虚多滞少者，则宜以参、 、归、术、熟地、甘草之属，专理脾气，以托气血 \n。脾健则元气日复，肌肉自生，可保无虞矣。其有伤筋骨而作痛者，宜没药降圣丹治之。若 \n牙关紧急，或腰背反张者，以玉真散治之并效。总之，此证宜先察其有瘀无瘀，及形气虚实 \n，酌而治之。凡诸变证治法，有未尽者，宜与前跌打损伤条，互参通用。外杖疮四方，见外 \n科方中。 \n文刑部用晦伏阙谏南巡受杖，瘀血已散，坏肉不溃，用托里之药稍溃而脓清，此气血虚也 \n，非大剂参 不能补。文君亦善医，以为恐腹满。予强之，而饮食稍思。遂加大补剂，饮食 \n日进，肉溃脓稠而愈。又治江翰林诸公与文同事者九人，皆先散其瘀血，渐用排脓托里之药 \n俱愈。 \n夏凤北京人，因杖疮臀膝通溃，脓瘀未出，时发昏愦，此脓毒内作而然也。急与开之， \n昏愦愈甚，此虚也。以八珍汤一服少可，数服死肉自腐，顿取之。令用猎蹄汤洗净，以神效 \n当归膏涂贴，再以十全大补汤，两月而愈。若更投破血之剂则危矣。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>破伤风（七十六）\n\n属性：《病机》云∶破伤风者，有因卒暴伤损，风寒袭之，传播经络，致使寒热更作，身体反 \n张，口噤不开，甚者邪气入脏。有因诸疮不瘥，营卫俱虚，肌肉不生，疮眼不合，邪亦能外 \n入于疮，为破伤风之候。有诸疮不瘥，举世皆言，着灸为上，是为热疮而不知火热客毒，逐 \n经为变，不可胜数，微则发热，甚则生风而搐，或角弓反张，口噤目斜。亦有破伤不灸而病 \n此者，因疮着白痂，疮口闭塞，气难通泄，故阳热易为郁结，热甚则生风也。 \n徐用城曰∶此论所因有四，二者因疮口入风，似属外因。一者因灸生热，似属不内外 \n因。一者因疮口闭塞，内热生风，似属内因也。又云∶破伤风证，古方药论甚少，岂非以此 \n疾与中风同论，故不另立条目也。惟河间论与伤寒表里中三法同治，其言病因，有因外伤于 \n风者，有因灸者，有因内热所作者，然与中风相似也。但中风之人，尚可淹延岁月，而破伤 \n风者，犯之多至不救。盖中风有在经、在腑、在脏之异，独入脏者最难治。破伤风，或始而 \n出血过多，或疮早闭合，瘀血停滞，俱是阴虚受病，乃五脏之所主。故此风所伤，始虽在表 \n，即随必传入脏，故多死也。此病或因疮口坦露，或因疮口闭密，皆能为之。若病已十分安 \n全，而忽有此，大抵皆由内气虚而有郁热者，乃得之。若内气壮实而无郁热者，虽害而无所 \n害也。 \n立斋曰∶大法；破伤中风，风热燥甚，怫郁在表，而里气尚平者，必善伸数欠，筋脉拘 \n急，时或恶寒，或筋惕而播，脉浮数而弦，皆表证也。宜以辛热治风之药，开散结滞，是与 \n伤寒表热怫郁，而以升麻汤辛热发散者同也。然凡用辛热开其风热结滞者，宜用寒药佐之， \n则免其药虽中病，而风热转甚也。如治伤寒发热，用麻黄、桂枝，而加黄芩、知母、石膏之 \n类是也。若近世以甘草、滑石、葱、豉寒药，发散甚妙。若表病不已，渐伤入里，里又未太 \n甚，而脉在肌肉者，宜以退风热，开结滞之寒药调之，或微加治风辛热亦得，犹伤寒在半表 \n半里，而以小柴胡和解之意也。若里热已甚，而舌强口噤，项背反张，惊搐惕搦，涎唾稠粘 \n，胸腹满塞，或便溺闭结，或时汗出，脉洪数而弦。然汗出者，由风热甚于里，而表邪已罢 \n，腠理疏泄，心火内盛，故汗出也。法宜除风散结，以寒药下之，后用退风热，开郁滞之 \n寒药调之，热退结散则风自愈矣。凡治此者，亦宜用按摩导引之法，及以药干开牙关，勿令 \n口噤，使粥药得下也。 \n一妇人，臀痈将愈，患破伤风，发热搐搦，脉浮数。予以当归地黄汤治之，彼不信。 \n乃服发散败毒药，果甚，始信而服之。数剂而痊。 \n一男子，背疮未痊敛，以膏药剪孔贴之，患破伤风证而殁。此先失于内补，外邪袭其 \n虚耳。余见此证贴膏药剪孔，欲其通气，而反患破伤风；搽敛药生肌，欲其收口，而反助余 \n毒，以致殁者多矣，可不慎哉。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>破伤风（七十六）\n\n属性：酒 防风汤 蜈蚣散 大芎黄汤 羌活汤 白术防风汤 玉真散外 敷药 \n养血当归地黄汤 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>类破伤风（七十七）\n\n属性：立斋曰∶大凡痈疽溃后，筋糜肉烂，脓血大泄，阳随阴散，或筋脉拘急，恶寒惕搦 \n，甚者舌强口噤，项背反张，痰涎壅盛，便闭汗出，不时发热，此气血俱虚。而变见若此， \n虽与破伤风相类，而主治之法，但当大补血气。若果有风证，亦须以大补气血为主，而兼以治 \n风之药。设若不审是非，而妄药之，则误矣。 \n司徒边华泉，肩患痈而发热，目直或 ，殊类中风，日晡热甚，脉益数，此足三阴 \n气血亏损，虚火妄动也。用参、 、归、术、炙甘草，加酒炒黑黄柏、五味、麦冬、肉桂，四 \n剂而愈，又数剂而敛。 \n一儒者，患腿痈，深蓄于内，肉色不变，久不穿溃，针出脓瘀五碗许，恶证骈臻，全 \n类中风，此脾胃虚而变证也。用六君子汤加当归、炮姜，及圣愈汤，各四剂而安。又劳心不 \n寐，用归脾汤而愈。（薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>斑疹丹毒（七十八）\n\n属性：斑疹一证，虽已有正门详载，然彼以小儿麻 为言。其有非麻 ，而无论大人小儿，忽患 \n斑疹小疮者，此虽与彼相类，而实有小异也。是亦不可不辨而治之，盖多由风热外感之证耳 \n治此之法，脉浮而身热有表证者，惟散风邪为主。脉浮而数者，祛风兼清热。脉沉滑而无 \n表证者，清火为主。脉浮沉俱滑数，而表里兼见者，宜表里双解之。然惟小儿多有此证，须 \n察其表里虚实，酌而治之可也。总之小儿脆弱，宜安里之药多，攻发之药少；秘则微泄之， \n结则微导之，但令邪气不壅而散之易，则证轻而儿自安矣。大抵身温暖者顺，身凉者逆。 \n王海藏曰∶前人云，首尾俱不可下者，何也。曰∶首不可下者，为斑未见于表，下则邪 \n气不得伸越，此脉证有表而无里，故禁首不可下也。尾不可下者，为斑毒已显于外，内无根 \n蒂，大便不秘，本无一切里证，下之则斑气陷逆，故禁尾不可下也。 \n洁古曰∶斑疹之病，其为证各异。发 肿于外者，属少阳三焦相火也，谓之斑。小红靥 \n行皮肤之中不出者，属少阴君火也，谓之疹。凡见斑证，若自吐泻者多吉，慎勿乱治，谓邪 \n气上下俱出也。若斑疹并出者，其邪必甚，小儿难胜，是以多生别证也。然首尾皆不可下。 \n立斋曰∶凡小儿丹毒，遍身俱赤，不从砭治，以致毒瓦斯入腹，则不救。盖此证，乃恶毒 \n热血，蕴蓄于命门，遇相火而合起也。如霞片者，须砭去恶血为善。如肿起赤色，游走不定 \n者，宜先以生麻油涂患处砭之，以泄其毒。凡从四肢起入腹者，不治。虽云丹有数种，治有 \n数法，无如砭之为善。常见患重者，不用砭法，俱不救。 \n一妇人，患斑作痒，脉浮。以消风散，四剂而愈。 \n一妇人，患斑作痒，脉浮数。以人参败毒散，二剂少愈，更以消风散，四剂而安。 \n一男子患斑，色赤紫 痛，发热喜冷，脉沉实。以防风通圣散，一剂顿退，又以防风 \n败毒散加芩、连，四剂而愈。 \n一老人患疹，色微赤，作痒发热。以人参败毒散，二剂少愈，以补中益气汤加黄芩、山栀而愈。 \n一小儿患疹，发热作痛，烦渴，欲以清凉饮下之。诊其脉不实，举指不数，此邪在经 \n络也，不可下，遂以解毒防风汤，二剂而愈。此证小儿多患之，须详审在表在里，及邪之微甚而治之。 \n一儿作痒发热，以犀角散一剂作吐泻，此邪气上下俱出也，毒必自解。少倾吐泻俱止 \n，其疹果消。吐泻后，脉见七至，此小儿和平之脉也，邪已尽矣。不须治，果愈。（俱薛按） \n一男子患丹毒， 痛便秘，脉数而实，服防风通圣散不应，令砭患处，去恶血，仍用前药而愈。 \n一小儿，腿患丹，如霞，游走不定，先以麻油涂患处，砭出恶血，毒即渐散。更以神 \n功托里散，一剂而安。 \n一小儿患丹毒，外势虽轻，内则大便不利，此患在脏也，服大连翘饮，敷神功散而瘥。 \n一小儿遍身皆赤，砭之，投解毒药而愈。尝治小儿丹毒便秘，或烦躁者，服五福化毒 \n丹亦效。（俱薛按） \n一、白虎丹方治，在外科方二九二。 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>瘤赘（七十九）\n\n属性：立斋曰∶《内经》云∶肝主筋而藏血，心裹血而主脉，脾统血而主肉，肺司腠理而主 \n气，肾统骨而主水。若怒动肝火，血涸而筋挛者，自筋肿起，按之如筋，久而或有赤缕，名 \n曰筋瘤。若劳役火动，阴血沸腾，外邪所搏而为肿者，自肌肉肿起，久而有赤缕，或皮俱赤 \n者，名曰血瘤。若郁结伤脾，肌肉消薄，外邪所搏而为肿者，自肌肉肿起，按之实软，名曰 \n肉瘤。若劳伤肺气，腠理不密，外邪所搏，而壅肿者，自皮肤肿起，按之浮软，名曰气瘤。 \n若劳伤肾水，不能荣骨，而为肿者，自骨肿起，按之坚硬，名曰骨瘤。夫瘤者，留也。随气 \n凝滞，皆因脏腑受伤，气血乖违，当求其属，而治其本。大凡属肝胆二经结核，宜八珍加 \n山栀、胆草，以养气血、清肝火；六味丸以养肺金、生肾水。若属肝火血燥，须生血凉血， \n用四物、二地、丹皮、酒炒黑胆草、山栀。若中气虚者，补中益气汤兼服之。若治失其法， \n脾胃亏损，营气虚弱，不能濡于患处，或寒气凝于疮口，营气不能滋养于患处，以致久不生 \n肌而成漏者，悉宜调补脾气，则气血壮而肌肉自生矣。若不慎饮食起居，及七情六淫，或用寒 \n凉蚀药，蛛丝缠，芫花线等法，以治其外，则误矣。 \n按瘤赘一证，如前薛论，已尽其略。然此五瘤之外，又惟粉瘤为最多，盖此以腠理津沫 \n，偶有所滞，聚而不散，则渐以成瘤，是亦粉刺之属，但有浅深耳。深者在皮里则渐成大瘤 \n也。余尝闻之，先辈曰，瘤赘既大，最畏其破。非成脓者，必不可开。开则牵连诸经，漏竭 \n血气，最难收拾，无一可活。及详考薛按所载数人，凡其破溃者，皆至不治，诚信然也，不 \n可不知。兹纪予于三旬之外，忽于臀下肛门前骨际皮里生一小粒，初如绿豆许，不以为意， \n及半年而如黄豆矣，又一年而如皂子，复如栗矣。此时乘马坐椅皆有所碍，而渐至痛矣。然料此 \n非敷药可散，又非煎药可及，使其日渐长大，则如升如斗悬挂腰股间，行动不便，岂不竟成 \n废物乎。抱忧殊甚，谋之识者，皆言不可割刺，恐为祸不少。予熟筹数月，莫敢妄动。然窃 \n计，此时乘小不取，则日后愈大愈难矣，将奈之何。尝见人臀股间受箭伤者，未必即死，此 \n之利害不过如是，遂决意去之。一日饮酒微醺，乘醉以柳叶针刺之，所出者皆如豆腐白皮之 \n属，盖即粉瘤也。刺后顿消，予甚快然。又两日后，则肿如热痈，予以会通膏贴三日，脓溃 \n而愈，予又快然。不两日又肿起，更热更大，予则大惧大悔，谓瘤赘诚不可刺也。然而无奈 \n，复以会通膏贴之，又三日而大溃，则溃出一囊如鱼胞者，然后收口全愈。今愈后数十年， \n此间仍有一小窍，诚险证也。向非予之勇决，则此后不知作何状，使开之再迟则真有不可收 \n拾矣。是以病不早治，则不知所终，此亦可为治病者之鉴。（新按） \n一、刺灸法∶向一人于眼皮下弦，生一小瘤，初如米粒，渐大如豆。其人疑畏，求治于外科 \n，彼用攒针三四枚，翻转眼皮，刺其内膜，少少出血，如此二三次，其瘤日缩，竟得尽消。 \n又一人于手臂上生一瘤，渐大如龙眼，其人用小艾于瘤上灸七壮，竟尔渐消不长，亦善法也。 \n或用隔蒜灸之，亦无不可。一、凡于不便处有生此物者， \n当以此二法酌宜用之。大都筋脉宜灸，血病宜刺，或有以萝卜子、南 \n星、朴硝之类敷而治者，亦可暂消。若欲拔根，无如前法。 \n一、蛛丝缠法∶可治瘤赘，未甚大者，其法最妙。予尝见一人于腹上生一瘤，其大如胡桃， \n一治者取珠丝捻成粗线，缠扎其根。数日其丝渐紧，瘤根渐细，屡易屡细，不十日意尔脱落， \n诚奇法也。可见诸线日松，惟蛛丝日紧，物理之妙，有当格致者如此。然亦缠治宜早，若形 \n势既大，恐不宜也。 \n薛氏按曰∶一男子左腿外侧近臀肿一块，上有赤缕三年矣。饮食起居如常，触破涌出脓 \n血，发热恶寒，此胆经受证，故发于腿外侧。诊其脉，左尺洪数，左关弦洪，此肾水不能生 \n肝木，用补中益气汤、六味地黄丸而愈痊。 \n一男子小腹患之，脓水淋漓，此足三阴之证，用补中益气汤加麦冬、五味，以培脾土， \n用六味地黄丸，以生肾水，更用芦荟丸，以清肝火而敛。 \n一老儒，眉间患之三年，其状如紫桃下坠盖目，按之如水囊，此肝脾之证，脓瘀内溃而 \n然耳。遂刺出血脓，目即开。以炒黑胆草、山栀、芎、归、芍药、柴胡、白术、茯苓等药而愈。 \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>疣（八十）\n\n属性：立斋曰∶疣，属肝胆经，风热血燥，或怒动肝火，或肝客淫气所致。盖肝热水涸，肾气 \n不荣，故精亡而筋挛也。宜以地黄丸，滋肾水以生肝血为善。若用蛛丝缠、螳螂蚀、着艾灸 \n，必致多误。大抵此证与血燥结核相同，故外用腐蚀等法，内服燥血消毒，则精血益虚，肝 \n筋受伤，疮口翻突开张，卒成败证。 \n府庠朱宏仁，年二十，右手背近中指患五疣，中一大者如黄豆，余皆如聚黍，拔之 \n如丝，长三四寸许，此血燥筋缩也。用清肝益荣汤，五十余剂而愈。 \n府庠沈妪文，幼啮指甲，及长不能自禁。余曰，此肝火血燥也。又颈侧常生小疣子，屡 \n散屡发。又臂生一块如绿豆大，若触碎，则如断束缕，扯之则长，纵之则缩，后两鬓发白点， \n求治。余曰∶子素肝病，此部亦属肝胆经也。夫爪为筋之余，胆行人身之侧，正与啮爪生庥 \n等证相应。须滋补肾水，以生肝胆，则诸病自愈矣。乃与六味地黄丸服之二年，白点自退， \n疣亦不生。 \n一男子，小腹中一块，不时攻痛，或用行气化痰等药不应。尤以为血鳖，服行气逐血之 \n剂后，手背结一庥子，渐长寸许，形如鳖状，肢节间如豆大者甚多。彼疑鳖生子，今发于 \n外，亦用行血。虚证悉至，左尺洪数，关脉洪数而弦。余以为肾水不能生肝木，以致肝火血 \n燥而筋挛，用六味地黄丸，生肾水滋肝血，三月余，诸证悉愈。 \n一妇人，左手背，并次指，患五六枚，如熟椹，内热晡热，月经素不及期。余曰∶此因 \n肝脾血虚而有热也，当调补二经，使阴血生而诸证自愈。不信，乃用艾灸手，即肿胀发热， \n手指皆挛，两胁项及胸乳间皆患疣，经行无期。余用加味逍遥散少加炒黑黄连，数剂渐愈。 \n乃去黄连，更佐以归脾汤，各患渐愈。又百余剂，经行如期，再用地黄丸三料而痊。（俱薛按） \n\n\n\n<目录>卷之四十七贤集·外科钤（下）\\外科钤（下）\n\n<篇名>论列方（外科下）\n\n属性：四物汤（补八） 八珍汤（补十九） 一阴煎（新补八） 四顺散（外一五四） 八正散 \n（寒百十五） 五种散（散三九） 五苓散（和一八二） 四生散（外一八六） \n三气饮（新热十七） 十宣散（痘十四） 四七汤（和九七） 五宝丹（外二百五） \n六味丸（补百二十） 四神丸（热一五一） 二神丸（热百五十） 八味丸（补一二一） \n理中汤（热一） 归脾汤（补三二） 生脉散（补五六） 大营煎（新补十四） \n还少丹（补一三五） 右归丸（新补五） 芎归汤（痘十五） 坎离丸（寒一六五） \n内塞散（外二三） 保阴煎（新寒一） 圣愈汤（补九十） 保阴煎（新寒一） \n玉露散（妇八九） 托里散（外三五） 排脓散（外一六二） 率肺散（固六） 宁肺汤 \n（补六二） 连翘汤（外五十） 桔梗汤（外一五一） 犀角散（痘六三） \n射干汤（外一六八） 消风散（散四七） \n漏芦汤（外九五） 化毒丹（外七六） 槟苏散（外一八八） 搜风汤（未人） \n凉膈散（攻十九） 回生丹（外七九） 通关散（因九八） 夺命丹（外七七） \n通气散（外八十） 大黄汤（外一六七） 必效散（外一七二） 积壳散（寒百一） \n承气汤（攻一） 清凉饮（外九十） 会脓散（外二百七） 桃仁汤（外九四） \n槐化蕊（新因四十） 牡蛎散（外二百八） 萆 汤（外二百一） 槐花酒（外百四） \n苦参丸（外八七） 滋肾丸（寒一六三） 导水丸（攻七一） 蜡矾丸（外七四） \n当归丸（外百） 黑丸子（外二三七） 茯苓膏（处二百四） 四君子汤（补一） \n六君子汤（袖五） 仙遗粮汤（外一九八） 小柴胡汤（散十九） 小青能汤（散八） \n大防风汤（补九八） 小乌沉汤（和二一八） 大秦艽汤（和二四五） 大芦荟丸 \n（小百十五） 牡丹皮汤（外一六七） 牡丹皮散（外一六五） \n瓜子仁汤（外一六四） 薏苡仁汤（外一六四） 紫菀茸汤（外一五六） 栀子仁汤（寒十九） \n五加皮（外二百） 制甘草汤（外六八） 余银花散（外四） 仙方活 \n命饮（外一） 人参败毒散（散三六） 神功托里散（外四） 补中益气汤（补三十） 十全 \n大补汤（补二十） 荆防败毒散（痘三一） 参 补肺汤（外三十） 内补黄 汤（外九） \n参苓白术散（补五四） 参术补脾汤（外二九） 人参养营汤（补二一） 人参平 \n肺散（寒三七） 参 内托散（痘七） 九味异功煎（新因二二） \n加味归脾汤（补三三） 当归补血汤（补四四） 加味四物汤（补九） 加味地黄丸（外三九） \n当归川芎汤（外四十） 加味逍遥散（补九三） 附子八物汤（外三六） 加减八味丸（外三八） \n益气养营汤（外三一） 托里当归汤（外十） 托里消毒散（外二） 内托羌活汤（外二二） \n补阴八珍汤（外三二） 加味羌活汤（外四三） 九味羌活汤（散四四） \n清肝益营汤（外八三） 复元活血汤（外二百四十） 当归拈痛汤（寒百三十） 芍药蒺 \n藜煎（新因三五） \n龙胆泻肝汤（寒六三） 加味龙胆泻肝汤（寒六四） 黄连解毒汤（寒一） 普济消 \n毒饮寒（十三） 升麻黄连汤（外四九） 连翘归尾煎（新因三二） 连翘消毒散 \n（外六一） 蠲痹消毒散（外二百二） 栀子清肝汤（寒六十） 芩连消毒饮（寒十四） \n五香连翘汤（外五一） 换肌消毒散（外二百一） 柴胡清肝散（寒五九） 清心莲子饮（寒三二） \n黄连消毒散（外六十） 葛根牛蒡汤（外四五） 白芷胃风汤（外四四） 内疏黄连汤 \n（外九三） 犀角地黄汤（外四六） 犀角升麻汤（外四七） 解毒防风汤（外六三） 秦艽防 \n风汤（外二二一） 神效栝蒌散（外一八一） 独活寄生汤（和二百七十） 防风通圣 \n散（攻十六） 当归导滞散（外二三九） 五利大黄汤（外八九） 五福化毒丹（外七六） \n飞龙夺命丹（外七八） 方脉流气饮（外五四） 牛黄双解散（外二百九） 遇仙无比丸（外一 \n七五） 疮科流气饮（外五五） 加减小续命汤（散五二） 青州白丸子（和百十二） 没药 \n降圣丹（外二三四） 不换金正气散（和二一） 十味没药丸（外二三五） 本事 \n接骨方（外二三三） 葶苈大枣泻肺汤（和百四十） \n秘傅正骨丹（外二三二） 杨梅痈漏方（外二百六） 雄黄解毒散（外一二四） 广 \n疮点药（新因四二） 洗损伤方（外二四九） 杖疮四方（外二五三） \n附子饼（外百十六） 豆豉饼（外百十七） 木香饼（外百十八） 桑枝灸（外百二十） \n猪蹄汤（外一二五） 骑竹马法（外百十四） 百草煎（新因三七） 葱熨法（外一二一） \n针头散（外一四四） 降痈散（新因三六） 神功散（外一三四） 金黄散（外一九五） \n如神散（外一七四） 螵蛸散（新因三八） 冲和膏（外一三八） 太乙膏（外三百八） \n当归膏（外三一四） 火龙膏（外三百二十） 琥珀膏（外三一七） 神异膏（外三百十） \n会通膏（外三百九） 乌金膏（外一四二） 藜芦膏（外一四八） 芜花线（外二二九） \n秘传水银膏（新因五七） \n\n\n\n<目录>卷之四十八大集·本草正（上）\n\n<篇名>山草部\n\n属性：\\x人参\\x（一）（反藜芦） 味甘微苦，微温，气味颇浓，阳中微阴，气虚血虚俱能补。阳气虚竭者， \n此能回之于无何有之乡；阴血崩溃者，此能障之于已决裂之后。惟其气壮而不辛，所以能固气；惟 \n其味甘而纯正，所以能补血。故凡虚而发热，虚而自汗，虚而眩运，虚而困倦，虚而惊惧，虚而短 \n气，虚而遗泄，虚而泻利，虚而头疼，虚而腹痛，虚而饮食不运，虚而痰涎壅滞，虚而嗽血吐血， \n虚而淋沥便闭，虚而呕逆躁烦，虚而下血失气等证，是皆必不可缺者。第欲以气血相较，则人参气 \n味颇轻而属阳者多，所以得气分者六，得血分者四，总之不失为气分之药，而血分之所不可缺者， \n为未有气不至而血能自至者也。故扁鹊曰∶损其肺者益其气，须用人参以益之，肺气既王，余脏之 \n气皆王矣。所以人参之性，多主于气，而凡脏腑之有气虚者，皆能补之。 \n然其性温，故积温亦能成热，若云人参不热则可，云人参之性凉，恐未必然。虽东垣云∶人参、 \n黄为退火之圣药，丹溪云∶虚火可补，参术之类是也，此亦皆言虚火也。而虚火二字，最有关系， \n若内真寒而外假热者，是为真正虚火，非放胆用之，必不可也。然有一等元阴亏乏，而邪火烁于表里， \n神魂躁动，内外枯热，真正阴虚一证，谁谓其非虚火？若过用人参，果能助热。若王节斋云∶阳旺 \n则阴愈消，及《节要》云∶阴虚火动者勿用，又曰∶肺热还伤肺等说，固有此理，亦不可谓其尽非。 \n而近之明哲如李月池辈，皆极不然之，恐亦未必然也。夫虚火二字，最当分其实中有虚，虚中有实， \n阳中有阴，阴中有阳，惟勿以成心而执己见，斯可矣。如必欲彼此是非，是所谓面东方不见西墙， \n皆未得其中也。予请剖之曰∶如龙雷之火，原 \n属虚火，得水则燔，得日则散，是即假热之火，故补阳即消矣。至若亢旱尘飞，赤地千里，得非阳亢 \n阴虚，而亦可以捕阳生阴乎？或必曰∶此正实火也，得寒则已。予曰∶不然。夫炎暑酷烈，热令大 \n行，此为实火，非寒莫解；而干枯燥旱，泉源断流，是谓阴虚，非水莫济，此实火之与阴虚，亦自 \n判然可别。是以阴虚而火不盛者，自当用参为君；若阴虚而火稍盛者，但可用参为佐；若阴虚而火 \n大盛者，则诚有暂忌人参，而惟用纯甘壮水之剂，庶可收功一证，不可不知也。予非不善用人参者， \n亦非畏用而不知人参之能补阴者，盖以天下之理，原有对待，谓之曰阴虚必当忌参固不可，谓之曰 \n阴虚必当用参亦不可，要亦得其中和，用其当而已矣，观者详之。 \n\\x黄 \\x（三） 味甘气平，气味俱轻，升多降少，阳中微阴。生者微凉，可治痈疽。蜜炙性温，能 \n补虚损。因其味轻，故专于气分而达表，所以能补元阳，充腠理，治劳伤，长肌肉。气虚而难汗者 \n可发，表疏而多汗者可止。其所以止血崩血淋者，以气固而血自止也，故曰血脱益气。其所以除泻 \n痢带浊者，以气固而陷自除也，故曰陷者举之。然其性味俱浮，纯于气分，故中满气滞者，当酌用 \n之。 \n\\x白术\\x（二） 味甘辛，气温，气味俱浓，可升可降，阳中有阴，气中有血。其性温燥，故能益气和 \n中，补阳生血，暖胃消谷，益津液，长肌肉，助精神，实脾胃，止呕逆，补劳倦，进饮食，利小水， \n除湿运痰，消浮去胀，治心腹冷痛，胃虚下痢， 癖 瘕。制以人乳，欲润其燥。炒以壁土，欲助 \n其固。佐以黄芩，清热安胎。以其性涩壮气，故能止汗实表。而痈疽得之，必反多脓；奔豚遇之， \n恐反增气；及上焦燥热而气多壅滞者，皆宜酌用之。然冬术甘而柔润，夏术苦而燥烈，此其功用大 \n有不同，不可不为深辨也。若于饥时择肥而甘者嚼而服之，服之久久，诚为延寿之物，是实人所未 \n知。 \n\\x苍术\\x（四） 味苦甘辛，性温而燥，气味俱浓，可升可降、阳也。用此者用其温散燥湿。其性温散， \n故能发汗宽中，调胃进食，去心腹胀疼，霍乱呕吐，解诸郁结，逐山岚寒疫，散风眩头疼，消痰癖 \n气块，水肿胀满。其性燥湿，故治冷痢冷泄，滑泻肠风，寒湿诸疮。与黄柏同煎，最逐下焦湿热痿 \n痹。若内热阴虚，表疏汗出者忌服。 \n然惟茅山者，其质坚小，其味甘醇，补益功多，大胜他术。 \n\\x甘草\\x（五） 味甘气平，生凉炙温，可升可降，善于解毒。反甘遂、海藻、大戟、芫花。其 \n味至甘，得中和之性，有调补之功，故毒药得之解其毒，刚药得之和其性，表药得之助其升，下 \n药得之缓其速。助参 成气虚之功，人所知也；肋熟地疗阴虚之危，谁其晓焉？祛邪热，坚筋骨， \n健脾胃，长肌肉，随气药入气，随血药入血，无往不可，故称国老。惟中满者勿加，恐其作胀；速 \n下者勿入，恐其缓功，不可不知也。 \n\\x黄精\\x（六） 一名救穷草。味甘微辛，性温。能补中益气，安五脏，疗五劳七伤，助筋骨，益脾 \n胃，润心肺，填精髓，耐寒暑，下三虫，久服延年不饥，发白更黑，齿落更生。张华《博物志》言 \n天老曰∶太阳之草名黄精，食之可以长生。太阴之草名钩吻，不可食之，入口立死。此但以黄精、 \n钩吻对言善恶，原非谓其相似也。而陶弘景谓黄精之叶与钩吻相似，误服之害人。苏恭曰∶黄精叶 \n似柳，钩吻蔓生，叶如柿叶，殊非比类。陈藏器曰∶钩吻乃野葛之别名，二物全不相似，不知陶公 \n凭何说此？是可见黄精之内本无钩吻，不必疑也。 \n\\x肉苁蓉\\x（七） 味甘咸，微辛酸，气微温。味重阴也，降也，其性滑。以其味重而甘温，故助相火， \n补精兴阳，益子嗣，治女人血虚不孕，暖腰膝，坚筋骨，除下焦寒痛。以其补阴助阳，故禁虚寒遗 \n沥泄精，止血崩尿血。以其性滑，故可除茎中寒热涩痛，但骤服反动大便。若虚不可攻而大便闭结 \n不通者，洗淡，暂用三四钱，一剂即通，神效。 \n\\x丹参\\x（八） 味微苦、微甘、微涩，性微凉，无毒。反藜芦。能养血活血，生新血，行宿血，故 \n能安生胎，落死胎，血崩带下可止，经脉不匀可调。此心脾肝肾血分之药，所以亦能养阴定志，益 \n气解烦，疗眼疼脚痹，通利关节，及恶疮疥癣，赤眼丹毒，排脓止痛，长肉生肌。 \n\\x还志\\x（九） 味微苦、微辛，气温，阳也，升也。制以甘草汤，浸一宿，晒干炒用。功专心肾， \n故可镇心止惊，辟邪安梦，壮阳益精，强志助力。以其气升，故同人参、甘草、枣仁，极能举陷摄 \n精，交接水火。但可为佐，用不宜多。神气上虚者所宜，痰火上实者当避。 \n\\x巴戟天\\x（十） 味甘微温，阴中阳也。虽曰足少阴肾经之药，然亦能养心神，安五脏，补五 \n劳，益志气，助精强阴。治阴痿不起，腰膝疼痛，及夜梦鬼交，遗精溺浊，小腹阴中相引疼痛等证。 \n制宜酒浸，去心微炒，或滚水浸剥亦可。 \n\\x仙茅\\x（十一） 味辛，温，有小毒，阳也。能助神明，强筋骨，益肌肤，培精血，明耳目， \n填骨髓，开胃消食，助益房事，温利五脏，补暖腰脚。此西域婆罗门僧献方于唐明皇，服之有效， \n久秘而后得传。按许真君书云∶仙茅久服，可以长生。其味甘能养肉，辛能养节，苦能养气，咸能 \n养骨，滑能养肤，酸能养筋，宜和苦酒服之，必效也。然仙茅性热，惟阳弱精寒，禀赋素怯者宜之， \n苦体壮相火炽盛者，服之大能动火，不可不察。凡制用之法，于八九月采得，用竹刀刮去黑皮，切 \n如豆粒，糯米泔浸两宿，去赤汁，用酒拌蒸之，从巳至亥，制之极熟，自无毒矣。然后曝干捣筛， \n熟蜜丸桐子大，每空心酒饮任下二三十丸。忌食牛乳及黑牛肉，恐减药力也。若随群补药中为丸服 \n之，无所不可。 \n\\x天麻\\x（十二） 一名赤箭，一名定风草。味辛，平，阴中有阳。治风虚眩晕头旋，眼黑头痛， \n诸风湿痹，四肢拘挛，利腰膝，强筋骨，安神志，通血脉，止惊恐恍惚，杀鬼精虫毒，及小儿风痫 \n惊气。然性懦力缓，用须加倍，或以别药相佐，然后见功。 \n\\x沙参\\x（十三）（反藜芦） 一名铃儿草。味微甘苦，气味俱轻，性微寒。能养肝气，治多眠，除 \n邪热，益五脏阴气，清肺凉肝，滋养血脉，散风热瘙痒，头面肿痛，排脓消肿，长肌肉，止惊烦， \n除疝痛。然性缓力微，非堪大用。易老云∶人参补五脏之阳，沙参补五脏之阴。特以其甘凉而和， \n补中清火，反而言之，故有是论。若云对待人参，则相去远矣。 \n\\x玄参\\x（十四反藜芦） 味苦甘微咸，气寒。此物味苦而甘，苦能清火，甘能滋阴。以其味甘，故 \n降性亦缓。本草言其惟入肾经，而不知其尤走肺脏。故能退无根浮游之火，散周身痰结热痈，逐颈 \n项咽喉痹毒、瘰 结核，驱 \n男女传尸，烦躁骨蒸，解温疟寒热往来，治伤寒热斑支满，亦疗女人产乳余疾，或肠中血瘕热 ， \n并疗劳伤痰嗽热烦，补肾滋阴，明目解渴。 \n\\x茅根\\x（十五） 即白茅。味甘凉，性纯美，能补中益气，此良药也。善理血病，凡吐血衄血， \n瘀血血闭，及妇人经水不调，崩中漏下。且通五淋，除客热，止烦渴，坚筋骨，疗肺热哕逆喘急， \n解酒毒及黄胆水肿，久服大是益人。若治痈疽疖母，及诸毒诸疮诸血，或用根捣敷，或用此煮汁调 \n敷毒等药，或以酒煮服，无不可也。茅有数种，处处有之，惟白者为胜。春生芽，布地如针，故曰 \n茅针，可以生啖，甚益小儿，功用亦同。 \n\\x湿羊霍\\x（十六） 味甘，气辛，性温，乃手足阳明、少阴，三焦命门药也。主阳虚阳痿，茎 \n中作痛。化小水，益精气，强志意，坚筋骨，暖下部一切冷风劳气，筋骨拘挛。补腰膝，壮真阴， \n及年老昏耄，中年健忘。凡男子阳衰，女子阴衰，艰于子嗣者，皆宜服之。服此之法，或单用浸酒， \n或兼佐丸散，无不可者。制法每择净一斤，以羊脂四两，同炒油尽用之。 \n\\x苦参\\x（十七） 味苦性寒。反藜芦。沉也，阴也，乃足少阴肾经之药。能祛积热黄胆，止梦 \n遗带浊，清小便，利水，除痈肿，明目止泪，平胃气，能令人嗜食，利九窍，除伏热狂邪，止渴醒 \n酒，疗恶疮斑疹疥癞，杀疳虫及毒风烦躁脱眉。炒黄为末，米饮调服，治肠风下血热痢。 \n\\x贝母\\x（十八）（反乌头） 味苦，气平，微寒。气味俱轻，功力颇缓，用须加倍。善解肝脏郁愁， \n亦散心中逆气，祛肺痿肺痈痰脓喘嗽。研末，沙糖为丸，含咽最佳。降胸中因热结胸，及乳痈流痰 \n结核。若足生人面诸疮，烧灰油调频敷。产难胞衣不出，研末用酒和吞。亦除瘕疝、喉痹、金疮， \n并止消渴烦热。赤眼翳膜堪点，时疾黄胆能驱。又如半夏、贝母，俱治痰嗽，但半夏兼治脾肺，贝 \n母独善清金。半夏用其辛，贝母用其苦。半夏用其温，贝母用其凉。半夏性速，贝母性缓。半夏散 \n寒，贝母清热。性味阴阳，大有不同，俗有代用者，其谬孰甚。 \n\\x土贝母\\x（十九）（反乌头） 味大苦，性寒。阴也，降也，乃手太阴、少阳，足阳明、厥阴之药。 \n大治肺痈肺痿、咳 \n喘、吐血衄血，最降痰气，善开郁结，止疼痛，消胀满，清肝火，明耳目，除时气烦热，黄胆淋闭， \n便血溺血，解热毒，杀诸虫，及疗喉痹瘰 ，乳痈发背，一切痈疡肿毒，湿热恶疮，痔漏金疮出血， \n火疮疼痛。为末可敷，煎汤可服。性味俱浓，较之川贝母，清降之功不啻数倍。 \n\\x山慈菇\\x（二十） 一名金灯龙味甘微辛，有小毒。治痈疡疔肿疮 ，瘰 结核，破皮攻毒， \n俱宜醋磨敷之。除 斑，剥人面皮，宜捣汁涂之。并治诸毒蛊毒，蛇虫狂犬等伤，或用酒调服，或 \n干掺之。亦冶风痰痫疾，以茶清研服，取吐可愈。 \n\\x柴胡\\x（二一） 味苦微辛，气平微寒。气味俱轻，升也，阳中之阴。用此者，用其凉散，平 \n肝之热，入肝、胆、三焦、心胞四经。其性凉，故解寒热往来，肌表潮热，肝胆火炎，胸胁痛结， \n兼治疮疡，血室受热。其性散，故主伤寒邪热未解，温疟热盛，少阳头痛，肝经郁证。总之，邪实 \n者可用，真虚者当酌其宜。虽引清气上升，然升中有散，中虚者不可散，虚热者不可寒，岂容误哉。 \n兼之性滑，善通大便，凡溏泄脾薄者，当慎用之。热结不通者，用佐当归、黄芩，正所宜也。愚谓 \n柴胡之性，善泄善散，所以大能走汗，大能泄气，断非滋补之物，凡病阴虚水亏而孤阳劳热者，不 \n可再损营气，盖未有用散而不泄营气者，未有动汗而不伤营血者。营即阴也，阴既虚矣，尚堪再损 \n其阴否？然则用柴胡以治虚劳之热者，果亦何所取义耶？观寇宗 《衍义》曰∶柴胡，《本经》并 \n无一字治劳，今人冶劳方中，鲜有不用者。呜呼！凡此误世甚多。尝原病劳之人，有一种脏本虚损， \n复受邪热者，当须斟酌用之，如《经验方》中治劳青蒿煎之用柴胡，正合宜耳。若或无邪，得此愈 \n甚，虽至死人亦不怨，目击甚多。《日华子》又谓补五劳七伤，《药性论》亦谓治劳乏羸瘦，若此 \n等病，苟无实热，医者执而用之，不死何待。注释本草，一字不可忽，盖万世之后，所误无穷，可 \n不谨哉！观此寇氏之说，其意专在邪热二字，谓但察有邪无邪，以决可用不可用，此诚得理之见， \n而复有非之者，抑又何也？即在王海藏亦曰∶苟无实热而用柴胡，不死何待？凡此所见略同，用者 \n不可不察。 \n\\x桔梗\\x（二二） 一名荠 。味苦微辛，气微凉。气轻于味，阳中有阴，有小毒，其性浮。用此 \n者，用其载药上升，故有舟楫之号，入肺、胆、胸膈、上焦。载散药表散寒邪。载凉药清咽疼喉痹， \n亦治赤目肿痛。载肺药解肺热肺痈，鼻塞唾脓咳嗽。载痰药能消痰止呕，亦可宽胸下气。引大黄可 \n使上升，引青皮平肝止痛。能解中恶蛊毒，亦治惊痫怔忡。若欲专用降剂，此物不宜同用。 \n\\x防风\\x（二三） 味甘辛，气温，升也，阳也。用此者，用其气平散风。虽膀胱脾胃经药，然 \n随诸经之药，各经皆至。气味俱轻，故散风邪，治一身之痛，疗风眼，止冷泪。风能胜湿，故亦去 \n湿，除遍体湿疮。若随实表补气诸药，亦能收汗，升举阳气，止肠风下血崩漏。然此风药中之润剂， \n亦能走散上焦元气，误服久服，反能伤人。 \n\\x细辛\\x（二四）（反藜芦，忌生菜） 味大辛，气温，气味俱浓，升也，阳也，有小毒，用此者， \n用其温散。善 阴分之寒邪，除阴经之头痛，益肝温胆利窍，逐诸风湿痹，风痫疲疟，鼻 不闻香 \n臭，开关通窍，散风浪目疼。口臭牙虫，煎汤含漱。过服亦散真气，不可不知。此味辛甚，故能逐 \n阴分之邪，阴分且然，阳分可知。旧云少阴、厥阴之药，然岂有辛甚而不入阳分者？但阳证忌热， \n用当审之。 \n\\x羌活\\x（二五） 味微苦，气辛微温，升也，阳也。用此者，用其散寒定痛。能入诸经，太阳为 \n最。散肌表之寒邪，利周身项脊之疼痛，排太阳之痈疽，除新旧之风湿。缘非柔懦之物，故能拨乱 \n反正。惟其气雄、大能散逐，若正气虚者忌用之。 \n\\x独活\\x（二六） 味苦，气香，性微凉。升中有降，善行滞气，故入肾与膀胱两经，专理下焦 \n风湿。两足痛痹，湿痒拘挛，或因风湿而齿痛，头眩喘逆，奔豚疝瘕，腰腹疼痛等证，皆宜用之。 \n\\x升麻\\x（二七） 味微苦，气平，气味俱轻浮而升，阳也。用此者，用其升散提气，乃脾、胃、 \n肺与大肠四经之药。善散阳明经风寒，肌表邪热，提元气之下陷，举大肠之脱泄，除阳明温疫表邪 \n，解肤腠风热斑疹。引石膏除齿牙臭烂肿痛，引葱头去阳明表证头疼，佐当归、肉苁蓉可通大便结 \n燥。凡痈疽痘疹，阳虚不能起发，及泻痢崩淋，梦遗脱肛，阳虚下陷之类，用佐补剂，皆所宜也。 \n若上实气壅，诸火炎上，及太阳表证，皆不宜用。 \n且其味苦气散，若血气太虚，及水火无根者，并不可用。 \n\\x前胡\\x（二八） 味苦气寒，降也，阴中微阳。去火痰实热；开气逆结滞，转筋霍乱；除胸中 \n痞满，气喘呕逆，咳嗽烦闷；治伤寒寒热，风热头疼；解婴儿疳热。 \n\\x延胡索\\x（二九） 味苦微辛，气微温，入肝脾二经。善行滞气，破滞血，血中气药。故能止 \n腹痛，通经，调月水淋滞，心气疼痛，破症癖跌扑凝瘀，亦善落胎，利小便，及产后逆血上冲。俱 \n宜以酒煮服，或用酒磨服亦可。然性惟破气逐血，必真有血逆气滞者方可用。若产后血虚，或经血 \n枯少不利，气虚作痛者，皆大非所宜。 \n\\x紫草\\x（三十） 味苦性寒，此手厥阴、足厥阴血分之药。性寒而利，能凉血滑血，通利二便， \n故痘疹家宜用之。凡治痘疹，无论未出已出，但血热毒盛，或紫或黑，而大便秘结者，宜用之。若 \n已出红活，不紫不黑，而大便如常通利者，即不可用。故曾世荣《活幼心书》云∶紫草性寒，小儿 \n脾气实者犹可用，脾气虚者反能作泻。又若古方惟用其茸，亦取其气轻味薄，而有清凉升发之功也。 \n此外，可用以解黄胆，消肿胀，及一切斑疹恶疮，亦以其能利九窍，通水道，去湿凉血而然也。 \n\\x白芨\\x（三一） 味苦涩，性收敛，微寒。反乌头。能入肺止血，疗肺痈肺痿。治痈疽败烂恶 \n疮，刀箭汤火损伤，生肌止痛，俱可为未敷之。凡吐血不能止者，用白芨为末，米饮调服即效。 \n\\x三七\\x（三二） 味甘气温，乃阳明、厥阴血分之药，故善止血散血定痛。凡金刃刀箭所伤， \n及跌扑杖疮血出不止，嚼烂涂之，或为末掺之，其血即止。亦治吐血衄血，下血血痢，崩漏、经水 \n不止，产后恶血不下俱宜自嚼，或为末，米饮送下二三钱。若治虎咬蛇伤等证，俱可服可敷。"}, {"n": 29, "text": "卷二十九\n\n叶之性用与根大同，凡折伤趺扑出血，敷之即止，青肿亦散。 \n\\x白藓皮\\x（三三） 味苦寒，性燥而降，乃手足太阴阳明之药。解热黄、酒黄、急黄、谷黄、 \n劳黄，通关节九窍，利血脉小水，治时行大热饮水，狂躁叫呼，及妇人阴中肿痛，小儿风热惊痫。 \n尤治一切毒风风疮，疥癣赤烂，杨梅疮毒，眉发脱落。此虽善理疮疡，而实为诸黄、风痹要药。 \n\\x秦艽\\x（三四） 味苦，性沉寒，沉中有浮，手足阳明清火药也。治风寒湿痹，利小水，疗通 \n身风湿拘挛，手足不遂，清黄胆，解温疫热母，除口噤牙疼口疮，肠风下血，及虚劳骨蒸发热，潮 \n热烦渴，及妇人胎热，小儿疳热瘦弱等证。 \n\\x地榆\\x（三五） 味苦微涩，性寒而降。既清且涩，故能止吐血衄血，清火明目，冶肠风血痢， \n及妇人崩漏下血，月经不止，带浊痔漏，产后阴气散失；亦敛盗汗，疗热痞，除恶肉，止疮毒疼痛。 \n凡血热者当用，虚寒者不相宜也。作膏可贴金疮；捣汁可涂虎犬蛇虫伤毒，饮之亦可。 \n\\x黄芩\\x（三六） 味苦气寒，气轻于味，可升可降，阴中微阳。枯者善于入肺，实者善入大肠。 \n欲其上者酒炒，欲其下者生用。枯者清上焦之火，消痰利气，定喘嗽，止失血，退往来寒热、风热 \n湿热头痛，解瘟疫，清咽，疗肺痿肺痈，乳痈发背；尤祛肌表之热，故治斑疹鼠 ，疮疡赤眼。实 \n者凉下焦之热，能除赤痢，热蓄膀胱，五淋涩痛，大肠闭结，便血漏血。胎因火盛不安，酌佐砂仁、 \n白术；腹因火滞为痛，可加黄连、浓朴。大肠无火滑泄者，最当慎用。 \n\\x黄连\\x（三七） 味大苦，气大寒。味浓气薄，沉也，降也，降中微升，阴中微阳。专治诸火， \n火在上，炒以酒；火在下，炒以童便；火而呕者炒以姜汁；火而伏者炒以盐汤。同吴茱萸炒，可以 \n止火痛；同陈壁土炒，可止热泻。同枳实用，可消火胀；同天花粉用，能解烦渴。同木香丸，和火 \n滞下痢腹痛；同吴茱萸丸，治胃热吐吞酸水。总之，其性大寒，故惟平肝凉血，肃胃清肠凉胆，止 \n惊痫，泻心除痞满。上可治吐血衄血，下可治肠 便红。疗妇人阴户肿痛，除小儿食积热疳，杀蛔 \n虫。消恶疮痈肿，除湿热郁热。善治火眼，亦消痔漏。解乌附之热，杀巴豆之毒。然其善泻心脾实 \n火，虚热妄用，必致格阳。故寇宗 曰∶虚而冷者，慎勿轻用。王海藏曰∶夏月久血痢，不用黄连， \n阴在内也。景岳曰∶人之脾胃，所以盛载万物，发生万物，本象地而属土。土暖则气行而燥，土寒 \n则气凝而湿，土燥则实，土湿则滑，此天地间不易之至理。黄连之苦寒若此，所以过服芩、连者， \n无不败脾，此其湿滑，亦自明显易见。独因陶弘景《别录》中有调胃浓肠之一言，而刘河间复 \n证之曰∶诸苦寒药多泄，惟黄连、黄柏性冷而燥。因致后世视为奇见，无不谓黄连性燥而浓肠胃， \n凡治泻痢者，开手便是黄连，不知黄连、黄柏之燥，于何见之？，呜呼！一言之谬，流染若此，难 \n洗若此，悖理惑人，莫此为甚。虽曰黄连治痢亦有效者，然必其素禀阳脏，或多纵口腹，湿热为痢 \n者，乃其所宜。且凡以纵肆不节而血气正强者，即或误用，未必杀人，久之邪去亦必渐愈，而归功 \n黄连，何不可也。此外则凡以元气素弱，伤脾患痢，或本无火邪而寒湿动脾者，其病极多，若妄用 \n黄连，则脾肾日败，百无一生。凡患痢而死者，率由此类，可不寒心。余为此言，而人有未必信者， \n多以苦燥二字有未明耳，故余于《传忠录》辨河间条中，复详言若味之理，以后卫生仁者再为赞正， \n庶是非得明，而民生有攸赖矣。道书言服黄连犯猪肉，令人泄泻。 \n\\x胡黄连\\x（三八） 味大苦，大寒。其性味功用，大似黄连。能凉肝明目，治骨蒸劳热，三消，吐 \n血衄血，五心烦热，疗妇人胎热，虚惊热痢，及小儿疳热惊痫。侵人乳点目甚良。 \n\\x知母\\x（三九） 味苦，寒，阴也。其性沉中有浮，浮则入手太阴、手少阴，沉则入足阳明、足厥 \n阴、足少阴也。故其在上，则能清肺止渴，却头痛，润心肺，解虚烦喘嗽，吐血衄血，去喉中腥臭。 \n在中则能退胃火，平消瘅。在下则能利小水，润大便，去膀胱肝肾湿热，腰脚肿痛，并治劳瘵内热， \n退阴火，解热淋崩浊。古书言知母佐黄柏，滋阴降火，有金水相生之义，盖谓黄柏能制膀胱命门阴 \n中之火，知母能消肺金制肾水化源之火，去火可以保阴，见即所谓滋阴也，故洁古、东垣皆以为滋 \n阴降火之要药。继自丹溪而后，则皆用以为补阴，诚大谬矣。夫知母以沉寒之性，本无生气，用以 \n清火则可，用以补阴则何补之有？第其阴柔巽顺，似乎有德，倘元气既亏，犹欲藉此以望补益，是 \n亦犹小人在朝，而国家元气日受其削，有阴移焉而莫之觉者，是不可不见之真而辨之早也。 \n\\x龙腊草\\x（四十） 味大苦，大寒。阴也，沉也，乃足厥阴、少阳之正药。大能泻火，但引以佐使， \n则诸火皆治。故能退骨蒸疳热，除心火惊痫狂躁；胃火烦热黄胆，咽喉肿痛；肝肾膀胱伏火，小水 \n淋闭，血热泻痢；下焦湿热痈肿，疮毒疼痛？妇人血热崩淋；小儿热疳客忤，去目黄睛赤肿痛，杀 \n蛊毒肠胃诸虫，及风热盗汗。凡肝肾有余之火，皆其所宜。 \n\n\n\n<目录>卷之四十八大集·本草正（上）\n\n<篇名>隰草部\n\n属性：\\x地黄\\x（四一） 生地黄，味苦甘，气凉。气薄味浓，沉也，阴也。鲜者更凉，干者微凉。能生血 \n补血，凉心火，退血热，去烦躁骨蒸，热痢下血，止呕血衄血，脾中湿热，或妇人血热而经枯，或 \n上下三消而热渴。总之其性颇凉，若脾胃有寒者，用宜斟酌。 \n熟地黄，味甘微苦，味浓气薄，沉也，阴中有阳。《本草》言其入手足厥、少阴经，大补血衰， \n滋培肾水，填骨髓，益真阴，专补肾中元气，兼疗藏血之经。此虽泛得其概，亦岂足以尽是之妙。 \n夫地黄产于中州沃土之乡，得土气之最浓者也。其色黄，士之色也。其味甘，土之味也。得土之气， \n而曰非太阴、阳明之药，吾弗信也。惟是生者性凉，脾胃喜暖，故脾阳不足者，所当慎用。至若熟 \n则性平，禀至阴之德，气味纯静，故能补五脏之真阴，而又于多血之脏为最要，得非脾胃经药耶？ \n且夫人之所以有生者，气与血耳，气主阳而动，血主阴而静。补气以人参为主，而 术但可为 \n之佐；补血以熟地为主，而芎、归但可为之佐。然在 、术、芎、归，则又有所当避，而人参、熟 \n地，则气血之必不可无。故凡诸经之阳气虚者，非人参不可；诸经之阴血虚者，非熟地不可。人参 \n有健运之功，熟地禀静顺之德。此熟地之与人参，一阴一阳，相为表里，一形一气，互主生成，性 \n味中正，无逾于此，诚有不可假借而更代者矣。 \n凡诸真阴亏损者，有为发热，为头疼，为焦渴，为喉痹，为嗽痰，为喘气，或脾肾寒逆为呕吐， \n或虚火载 \n血于口鼻，或水泛于皮肤，或阴虚而泄利，或阳浮而狂躁，或阴脱而仆地。阴虚而神散者，非熟地 \n之守不足以聚之；阴虚而火升者，非熟地之重不足以降之；阴虚而躁动者，非熟地之静不足以镇之； \n阴虚而刚急者，非熟地之甘不足以缓之。阴虚而水邪泛滥者，舍熟地何以自制？阴虚而真气散失者， \n舍熟地何以归源？阴虚而精血俱损，脂膏残薄者，舍熟地何以浓肠胃？ \n且犹有最玄最妙者，则熟地兼散剂方能发汗，何也？以汗化于血，而无阴不作汗也。熟地兼温 \n剂始能回阳，何也？以阳生于下，而无复不成干也。然而阳性速，故人参少用亦可成功；阴性缓， \n熟地非多难以奏效。而今人有畏其滞腻者，则崔氏何以用肾气丸而治痰浮？有畏其滑湿者，则仲景 \n何以用八味丸而医肾泄？有谓阳能生阴，阴不能生阳者，则阴阳之理，原自互根，彼此相须，缺一 \n不可，无阳则阴无以生，无阴则阳无以化，故《内经》曰∶精化为气，得非阴亦生阳乎？孰谓阳之 \n能生，而阴之不能长也。 \n又若制用之法，有用姜汁拌炒者，则必有中寒兼呕而后可；有用砂仁制者，则必有胀满不行而 \n后可；有用酒拌炒者，则必有经络壅滞而后可。使无此数者，而必欲强用制法，是不知用熟地者正 \n欲用其静重之妙，而反为散动以乱其性，何异画蛇而添足。 \n今之人即欲用之补阴，而必兼以渗利，则焉知补阴不利水，利水不补阴，而补阴之法不宜渗。 \n即有用之补血，而复疑其滞腻，则焉知血虚如燥土，旱极望云霓，而枯竭之阳极喜滋。设不明此， \n则少爪之尚欲兼之以利，又孰敢单用之而任之以多？单用而多且不敢，又孰敢再助以甘而尽其所长？ \n是又何异因咽而废食也。嗟，嗟！熟地之功，其不申于时用者久矣，其有不可以笔楮尽者尚多也， \n予今特表而出之，尚祈明者之自悟焉。 \n\\x牛膝\\x（四二） 味若甘，气微凉，性降而滑，阴也。忌牛肉。酒渍， 咀。走十二经络，助一身 \n元气。主手足血热痿痹，血燥拘挛；通膀胱涩秘，大肠干结，补髓填精。益阴活血；治腰膝酸疼， \n滋须发枯白。其性下走如奔，故能通经闭，破血症，引诸药下降。同麝香用，堕胎尤速。凡脏寒便 \n滑，下元不固者，当忌用之。 \n\\x麦门冬\\x（四三） 味甘微苦，性微寒，降也，阳中阴也。去心用，恐令人烦。其味甘多苦少，故上 \n行心肺，补上焦之津液，清胸膈之渴烦，解火炎之呕吐，退血燥之虚热；益精滋阴，泽肌润结；肺 \n痿肺痈，咳唾衄血；经枯乳汁不行，肺干咳嗽不绝；降火清心，消痰补怯。复脉须仗人参，便滑中 \n寒者勿设。 \n\\x续断\\x（四四） 川者色灰黑，尖瘦多芦，形如鸡脚，皮断而皱者是。味苦而涩，苦重涩轻，气微凉。 \n他产者，味甘微辛涩少。用川者良。凡用此者，用其苦涩。其味苦而重，故能入血分、调血脉，消 \n肿毒乳痈，瘰 痔 ，治金损跌伤，续筋骨血脉。其味涩，故能止吐血衄血，崩淋胎漏，便血尿血， \n调血痢，缩小便，止遗精带浊。佐之以甘，如甘草、地黄、人参、山药之类，其效尤捷。 \n\\x蜀葵子\\x（四五） 味甘性寒。能利小水，通淋闭，消水肿，润大肠，催生落胎，通乳汁，亦治一切疮 \n疥，并瘢疵赤靥。苗叶可作菜茹，古以葵为五菜之主，今不复用之矣。 \n\\x黄葵花\\x 性滑利，与蜀葵大同。若治诸恶疮脓水久不瘥者，用花为末，敷之即愈，为疮家要药。浸 \n油可涂汤火疮。 \n\\x车前子\\x（四六） 即苤苡味甘微咸，气寒，入膀胱、肝经。通尿管热淋涩痛，驱风热目赤翳膜；利 \n水能除湿痹，性滑极善催生，兼治湿热泻痢，亦去心胸烦热。 \n\\x根叶\\x 生捣汁饮，治一切尿血衄血热痢，尤逐气瘾利水。 \n\\x白蒺藜\\x（四七） 味苦微辛微廿，微凉。能破 瘕结聚，止遗溺泄精，疗肺痿肺痈，翳膜目赤，除 \n喉痹癣疥痔瘰癜风，通身湿烂恶疮，乳岩带下俱宜，催生止烦亦用，凉血养血，亦善补阴。用补宜 \n炒热去刺，用凉宜连刺生捣，去风解毒，白者最良。 \n沙苑蒺藜性亦大同。若用固精补肾，止遗沥尿血，缩小便，止烦渴，去燥热，则亦可用此。 \n\\x红花\\x（四八） 味甘微苦微宰，气微凉，阴中微阳。惟入血脉，多用女科。少用可活血引经，多用 \n能破血通瘀。可 \n下死胎，亦疗血晕；达痘疮血热难出，散斑疹血滞不消；润燥活血，止痛通经，亦消肿毒。 \n\\x紫菀\\x（四九） 味苦平微辛。辛能入肺，苦能降气，故治咳嗽上气痰喘。惟肺实气壅，或火邪刑金而致 \n咳唾脓血者，乃可用之。若以劳伤肺肾，水亏金燥而咳喘失血者，则非所宜。观陶氏《别录》谓其 \n补不足，治五劳体虚，其亦言之过也。 \n\\x甘菊花\\x（五十）（白菊花根善利水，捣汁和酒服之，大治癃闭） 味甘色黄者，能养血散风，去头目风 \n热，眩晕疼痛，目中翳膜，及遍身游风风疹。作枕明目，叶亦可用。 \n味苦者性凉，能解血中郁热，清头目，去风热眼目肿痛流浪。根叶辛香，能消痈毒，止疼痛。 \n\\x野菊花\\x（五一） 一名苦薏。根叶茎花皆可同用。味苦辛。大能散火散气，消痈毒疔肿瘰 ，眼目 \n热痛，亦破妇人瘀血。孙氏治痈毒方，用野菊连根叶捣烂酒煎，热服取汗，以渣敷之；或同苍耳捣 \n汁，以热酒冲服。冬月用干者煎服，或为末酒服亦可。 \n\\x \\x（五二） 味苦，气微寒，有小毒。此物气味颇峻，善逐风湿诸毒。用蜜酒层层和洒，九蒸九 \n曝，蜜丸，空心酒吞，多寡随宜。善治中风口眼歪邪，除湿痹腰脚痿痛麻木。生者酒煎，逐破伤风 \n危急如神。散撒麻疔恶毒，恶疮浮肿，虎伤狗咬，蜘蛛虫毒，或捣烂封之，或煎汤，或散敷并良。 \n其扫荡功力若此，似于元气虚者非利。 \n\\x益母草\\x（五三） 子名茺蔚味微苦微辛，微寒，性滑而利。善调女人胎产诸证，故有益母之号。能 \n去死胎，滑生胎，活血凉血行血，故能治产难胎衣不下，子死腹中，及经脉不调，崩中漏下，尿血 \n泻血瘀血等证。然惟血热血滞，及胎产艰涩者宜之，若血气素虚兼寒，及滑陷不固者，皆非所宜， \n不得以其益母之名，谓妇人所必用也。盖用其滑利之性则可，求其补益之功则未也。《本草》言其 \n久服益精轻身，诚不足信。此外如退浮肿，下水气，及打扑瘀血，通大小便之类，皆以其能利也。 \n若治疔肿乳痈，丹毒恶毒，则可捣汁饮之，其渣亦可敷贴。 \n子名茺蔚，功用略同，但子味微甘，稍温，故能凉血补血，亦益阴气明目。 \n\\x瞿麦\\x（五四） 味苦，微寒，降也，性滑利。能通小便，降阴火，除五淋，利血脉。兼凉药亦消眼 \n目肿痛，兼血药则能通经破血下胎。凡下焦湿热疼痛诸病，皆可用之。 \n\\x茵陈\\x（五五） 味苦微辛，气微寒，阴中微阳，入足太阳经。用此者，用其利湿逐热，故能通关节，解 \n热滞，疗天行时疾，热狂头痛，利小水。专治黄胆，宜佐栀子。黄而湿者多肿，再加渗利；黄而燥 \n者干涩，再加凉润。只有阴黄一证，因以中寒不运，此非所宜。又解伤寒瘴疟火热，散热痰风热疼 \n痛。湿热为痢，尤其所宜。 \n\\x青蒿\\x（五六） 味苦微辛，性寒，阴中有阳，降中有散。主肝肾三焦血分之病，疗阴火伏留骨节， \n故善治骨蒸劳热，尸疰鬼气，降火滋阴，润颜色，长毛发，治疟疾寒热，杀虫毒，及恶疮湿疥。生 \n捣可敷金疮，止血止痛。款冬花（五七）味微甘微辛而温，其气浮，阳也，入手太阴经。能温肺气，故 \n疗咳嗽，及肺痈肺痿咳唾脓血。寇宗 曰∶有人病嗽多日，或教以燃款冬花三两于无风处，以笔管 \n吸其烟，满口则咽之，数日果效。 \n\\x麻黄\\x（五八） 味微苦微涩，气温而辛，升也，阳也。此以轻杨之味，而兼辛温之性，故善达肌表，走 \n经铬，大能表散风邪，祛除寒毒，一应瘟疫疟疾，瘴气山岚，凡足三阳表实之证，必宜用之。苦寒 \n邪深入少阴、厥阴筋骨之间，非用麻黄、官桂不能逐也。但用此之法，自有微妙，则在佐使之间， \n或兼气药以助力，可得卫中之汗，或兼血药以助液，可得营中之汗；或兼温药以助阳，可逐阴凝之 \n寒毒；或兼寒药以助阴，可解炎热之瘟邪。此实伤寒阴疟家第一要药，故仲景诸方以此为首，实千 \n古之独得者也。今见后人多有畏之为毒药而不敢用，又有谓夏月不宜用麻黄者，皆不逢可哂也。虽 \n在李氏有云∶若过发则汗多亡阳，若自汗表虚之人用之则脱人元气，是皆过用及误用而然。若阴邪 \n深入，则无论冬夏，皆所最宜，又何过之有？此外如手太阴之风寒咳嗽，手少阴之风热斑疹，足少 \n阴之风水肿胀，足厥阴之风痛目痛，凡宜用散者，惟斯为最。然柴胡、麻黄俱为散邪要药，但阳邪 \n宜柴胡，阴邪宜麻黄，不可不察也。制用之法，须折去粗根，入滚汤中煮三五沸，以 \n竹片掠去浮沫，晒干用之。不尔，令人动烦。 \n\\x麻黄根\\x 味甘，平，微苦微涩。用甘敛药煎服，可以止汗。同牡蛎粉、米粉，或用旧蕉扇杵 \n末，等分，以生绢袋盛贮，用扑盗汗或夏月多汗，用之俱佳。 \n\\x萱草\\x（五九） 一名忘忧，一名宜男，一名鹿葱。萱草者，《诗》作谖草。凡树此玩此者，可解 \n忧思，故名忘忧。烹食其苗，气味如葱，而鹿喜食之，故名鹿葱。妇人佩其花则生男，故名宜男。 \n花叶气味甘而微凉，故能去湿热，利小便赤涩，除烦渴酒湿黄胆；安五脏，利胸膈，令人和悦，亦 \n能明目。 \n根，治沙淋带浊，利水气，解酒疸，宜捣汁服之。治吐血衄血，研汁一大盏，和姜汁细细呷之。 \n治吹乳、乳痈肿痛，须擂酒服，以渣封之。 \n\\x连翘\\x（六十） 味苦微辛，气微寒，气味俱薄，轻清而浮，升也，阳中有阴。入手少阴、手足少阳、 \n阳明。泻心经客热，降脾胃湿热，去寸白、蛔虫，通月水五淋。以其味苦而轻，故善达肌表，散鼠 \n、瘰 、瘿瘤、结热、蛊毒、痈毒、斑疹，治疮疖，止痛消肿排脓，疮家号为圣丹。以其辛而能 \n用，故又走经络，通血凝，气滞结聚，所不可无。 \n\\x旋复花\\x（六一） 味苦甘微辛，阴也，降也，乃手太阴肺经、手阳明大肠经药。开结气，降痰涎， \n通水道，消肿满，凡气壅湿热者宜之。但其性在走散，故凡见大肠不实，及气虚阳衰之人，皆所忌 \n用。 \n\\x鼠粘子\\x（六二） 一名牛蒡子，一名大力子。味苦辛，降中有升。治风毒斑疹诸 ，散疮疡肿毒喉 \n痹，及腰膝凝寒痹滞之气，以其善走十二经而解中有散也。 \n\\x决明\\x（六三） 味微苦微甘，性平微凉，力薄。治肝热风眼，赤而多泪，及肝火目昏，可为佐使， \n惟多服久服，方可得效。或作枕用，治头风，明目，其功胜于黑豆。 \n\\x葶苈\\x（六四） 味苦，大寒，沉也，阴也，气味俱浓，有毒。善逐水气，不减大黄，但大黄能泄血 \n闭，葶苈能泄气 \n闭，气行而水自行也。若肺中水气 满胀急者，非此不能除。然性急利甚，凡涉气虚者，不可轻用。 \n《淮南子》曰∶大戟去水，葶苈愈胀，用之不慎，乃反成病，即此谓也。第此有甜苦二种，虽曰为 \n甜，然亦非真甜，但稍淡耳，稍淡者，其性亦稍缓。 \n\\x夏枯草\\x（六五） 味微苦微辛，气浮而升，阴中阳也。善解肝气，养肝血，故能散结开郁，大治瘰 \n鼠屡，乳痈瘿气，并治头疮目疾。楼全善云∶夏枯草治目珠痛，至夜则甚者，神致；或用苦药点眼 \n反甚者，亦神效。一男子目珠痛，至夜则重，用黄连点之更甚，诸药不效，乃用夏枯草二两，香附 \n二两，甘草四钱，为末，每服一钱半，清茶调服，下咽即疼减，至四五服，良愈也。 \n\\x苍耳子\\x（六六） 一名羊负来味苦微甘。治头风寒痛，风湿周痹，四脸拘挛；去风明目，养血，暖 \n腰膝，及瘰 疮疥，亦治鼻渊。宜炒熟为末，白汤点眼一二钱，久之乃效。忌猪肉、马肉。 \n\\x漏芦\\x（六七） 味微咸，性寒，有小毒。主热毒恶疮，瘰 乳痈痔漏，挑脓长肉，止金疮血出。亦下乳 \n汁、通经脉，消赤眼，利小便，止尿血肠风，淋沥遗溺，及小儿壮热。疗跌扑损伤，可续筋骨。 \n\\x刘寄奴\\x（六八） 味苦，性温。能破瘀血，活新血，通妇人经脉，产后余血，损伤瘀血，下气，止心腹 \n痛，及小便去血，俱可为散，或茶或酒调服。捣敷金疮出血不止，其效尤捷。用治汤火伤大效，但 \n为末掺之。 \n\\x 蓄\\x（六九） 味苦涩。利小便，除黄胆，杀二虫，去下部湿热浸淫阴蚀，疮疥痔漏。煮汁饮之， \n疗小儿蛔虫上攻心腹作痛大效。有《海上歌》云∶心头急痛不能当，我有仙人海上方。 蓄醋煎通 \n口咽，管教时刻即安康。 \n\\x青葙子\\x（七十） 野鸡冠子也味微苦，微寒。能清肝火血热，故治赤眼，退赤障，消翳肿，镇肝明耳目， \n亦去风湿恶疮疥癞。 \n\\x艾\\x（七一） 味微苦，气辛，生用微温，熟用微热。能通十二经，而尤为肝脾肾之药。善于温中逐 \n冷除湿，行血中之气，气中之滞，凡妇人血气寒滞者，最宜用之。故能安胎，止心腹痛，治带下血崩，暖腰膝，止 \n吐血、下 \n痢，辟风寒寒湿瘴疟，霍乱转筋，及一切冷气鬼气，杀蛔虫并下部 疮。或生用捣汁，或熟用煎汤； \n或用灸百病，或炒热敷熨，可通经络；或袋盛包裹，可温脐膝，表里生熟，俱有所宜。 \n\\x佛耳草\\x（七二） 一名鼠曲草。味微酸，性温。大温肺气，止寒嗽，散痰气，解风寒寒热，亦止泄 \n泻。铺艾卷作烟筒，用熏久嗽尤效。 \n\\x蓝靛\\x（七三） 蓝叶气味苦寒微甘。善解百虫百药毒，及治天行瘟疫，热毒发狂，风热斑疹，痈 \n疡肿痛，除烦渴，止鼻衄吐血，杀疳蚀、金疮箭毒。凡以热兼毒者，皆宜捣汁用之。 \n\\x靛青\\x 乃蓝与锻石所成，性与蓝叶稍异，其杀虫止血，敷诸热毒热疮之功，似有胜于蓝叶者。 \n\\x青黛\\x 味微咸而寒，性与靛青大同。解诸热毒虫毒，金疮热疮，或干掺，或以水调敷。若治 \n诸热疮毒，或用马齿苋加青黛同捣敷之。苦治天行头痛，瘟疫热毒，及小儿诸热，惊痫发热，并水 \n研服之。 \n\\x木贼\\x（七四） 味微苦微甘，性温而升，阳也。性亚麻黄，故能发汗解肌，治伤寒疟疾，去风湿， \n散火邪，疗目疾，退翳障，止肠风下血下痢，及妇人崩中带漏，月水不调，亦治风湿疝痛，大肠脱 \n肛。 \n\\x王不留行\\x（七五） 一名金盏银台。味苦，平，性滑利，乃阳明冲任血海药也。治风毒，通血脉， \n疗妇人难产及经滞不调，下乳汁，利小便，除风湿痹痛，止心烦鼻衄，发背痈疽疮 ，游风风疹， \n出竹木刺，及金疮止血，亦能定痛。 \n\\x海金沙\\x（七六） 此草出黔中，七月收其全科，晒干，以杖击之，则细沙自茎叶中落。味甘性寒， \n乃小肠膀胱血分药也。善通利水道，解郁热湿热，及伤寒热狂，小便癃闭肿满，热淋膏浊，血淋石 \n淋、茎中疼痛。解诸热毒。或丸或散皆可用。 \n\\x灯心草\\x（七七） 味淡性平。能通水道涩结癃闭，治五淋，泻肺热，降心火，除水肿，止血，通阴气， \n散肿止渴。但用败席煮服更良。若治喉痹，宜烧灯草灰吹之。若治下疳疮，亦用烧灰，加轻粉、麝 \n香为末掺之。 \n\\x烟\\x（又七七） 味辛气温，性微热，升也，阳也。烧烟吸之，大能醉人，用时惟吸一口或二口，若多 \n吸之，令人 \n醉倒，久而后苏，甚者以冷水一口解之即醒；若见烦闷，但用白糖解之即安，亦奇物也。吸时须开 \n喉长吸咽下，令其直达下焦。其气上行则能温心肺，下行则能温肝脾肾，服后能使通身温暖微汗， \n元阳陡壮。用以治表，善逐一切阴邪寒毒，山岚瘴气，风湿邪闭腠理，筋骨疼痛，诚顷刻取效之神剂 \n也。用以治里，善壮胃气，进饮食，祛阴浊寒滞，消膨胀宿食，止呕哕霍乱，除积聚诸虫，解郁结 \n，止疼痛，行气停血瘀，举下陷后坠，通达三焦，立刻见效。 \n此物自古未闻也，近自我明万历时始出于闽广之间，自后吴楚间皆种植之矣，然总不若闽中者， \n色微黄，质细，名为金丝烟者，力强气胜为优也。求其习服之始，则向以征滇之役，师旅深入瘴地， \n无不染病，独一营安然无恙，问其所以，则众皆服烟，由是遍传，而今则西南一方，无分老幼，朝夕 \n不能间矣。予初得此物，亦甚疑贰，及习服数次，乃悉其功用之捷有如是者，因着性于此。 \n然此物性属纯阳，善行善散，惟阴滞者用之如神，若阳盛气越而多躁多火，及气虚短而多汗者 \n，皆不宜用。或疑其能顷刻醉人，性必有毒，今彼处习服既久，初未闻其妨人者，抑又何耶？盖 \n其阳气强猛，人不能胜，故下咽即醉，既能散邪，亦必耗气，理固然也。然烟气易散，而人气随复， \n阳性留中，旋亦生气，此其耗中有补，故人多喜服而未见其损者以此。后槟榔条中有说，当与此参 \n阅。 \n\n\n\n<目录>卷之四十八大集·本草正（上）\n\n<篇名>芳草部\n\n属性：\\x当归\\x（七八） 味甘辛，气温。气轻味重，可升可降，阴中有阳。其味甘而重，故专能补血，其气 \n轻而辛，故又能行血。补中有动，行中有补，诚血中之气药，亦血中之圣药也。头止血上行，身养 \n血中守，尾破血下流，全活血不走。大约佐之以补则补，故能养营养血，补气生精，安五脏，强形 \n体，益神志，凡有形虚损之病，无所不宜；佐之以攻则通，故能祛痛通便，利筋骨，治拘挛瘫痪燥 \n涩等证。营虚而表不解者，佐以柴、葛、麻、桂等剂，大能散表；卫热而表不敛者，佐以六黄之类， \n又能固表。惟其气辛而动，故欲其静者当避之； \n性滑善行，大便不固者当避之。凡阴中火盛者，当归能动血，亦非所宜；阴中阳虚者，当归能养血， \n乃不可少；若血滞而为痢者，正所当用。其要在动、滑两字。若妇人经期血滞，临产催生，及产后 \n儿枕作痛，俱当以此为君。小儿痘疹惊痫，凡属营虚者，必不可少。 \n\\x川芎\\x（七九） 味辛微甘，气温，升也，阳也。其性善散，又走肝经，气中之血药也。反藜芦。畏 \n硝石、滑石、黄连者，以其沉寒而制其升散之性也。芎、归俱属血药，而芎之散动尤甚于归，故能 \n散风寒，治头痛，破瘀蓄，通血脉，解结气，逐疼痛，排脓消肿，逐血通经。同细辛煎服，治金疮 \n作痛。同陈艾煎服，验胎孕有无。（三四月后，服此微动者，胎也。）以其气升，故兼理崩漏眩运； \n以其甘少，故散则有余，补则不足。惟风寒之头痛，极宜用之，若三阳火壅于上而痛者，得升反甚。 \n今人不明升降，而但知川芎治头痛，谬亦甚矣。多服久服，令人走散真气，能致暴亡，用者识之。 \n\\x芍药\\x（八十 反藜芦） 味微苦微甘略酸，性颇寒。气薄于味，敛降多而升散少，阴也。有小毒。 \n白者味甘，补性多。赤者味苦，泻性多。生者更凉，酒炒微平。其性沉阴，故入血分，补血热之虚， \n泻肝火之实，固腠理，止热泻，消痈肿，利小便，除眼疼，退虚热，缓三消。诸证于因热而致者为 \n宜，若脾气寒而痞满难化者忌用。止血虚之腹痛，敛血虚之发热。白者安胎热不宁，赤者能通经破 \n血。此物乃补药中之稍寒者，非若极苦大寒之比。若谓其白色属金，恐伤肝木，寒伐生气，产后非 \n宜，则凡白过芍药，寒过芍药者，又将何如？如仲景黑神散、芍药汤之类，非皆产后要药耶？用者 \n还当详审。若产后血热而阴气散失者，正当用之，不必疑也。 \n\\x丹皮\\x（八一） 味辛苦，气微凉，气味俱轻，阴中阳也。赤者行性多，白者行性缓，入足少阴及 \n手厥阴经。忌葫蒜。 \n凉骨蒸无汗，散吐衄于血，除产后血滞寒热，祛肠胃蓄血症坚，仍定神志，通月水，治惊搐风 \n痫，疗痈肿住痛。总之，性味和缓，原无补性，但其微凉而辛，能和血凉血生血，除烦热，善行血 \n滞，滞去而郁热自解，故亦退热。用此者，用其行血滞而不峻。 \n\\x白豆蔻\\x（八二） 味辛，气温，味薄气浓，阳也。入脾肺两经，别有清爽之气。散胸中冷滞，温胃口 \n止疼，除呕逆 \n翻胃，消宿食膨胀，治噎膈，除疟疾，解酒毒，祛秽恶，能退翳膜，亦消痰气。欲其速效，嚼咽 \n甚良，或为散亦妙。 \n\\x肉豆蔻\\x（八三） 味苦辛而涩，性温。理脾胃虚冷，谷食不消；治大肠虚冷，滑泄不止。以其气 \n香而辛，故能行滞止痛，和腹胀，治霍乱，调中下气，开胃进食，解酒毒，化痰饮，温胃逐虫，辟 \n诸恶气，疗小儿胃寒伤乳吐泻。以其能固大肠，肠既固则元气不走，脾气自健，故曰理脾胃虚冷， \n而实非能补虚也。面包煨熟用，或锉如豆大，以干面拌炒熟，去面用之尤妙，盖但欲去其油而用其 \n熟耳。 \n\\x草果\\x（八四） 亦名草豆蔻。味辛，性温热，阳也，浮也，入足太阴、阳明。能破滞气，除寒气， \n消食，疗心腹疼痛，解酒毒，治瘴疠寒疟，伤暑呕吐，泻痢胀满，反胃吐酸，开痰饮积聚噎膈，杀 \n鱼肉毒，开郁燥湿，辟除口臭，及妇人恶阻气逆带浊。此有二种，惟建宁所产，辛香气和者佳。宜 \n以面裹微火煨熟用之，或面拌炒熟亦可。滇广者气辛而臭，大能损人元气。 \n\\x破故纸\\x（八五） 味苦辛，气大温，性燥而降。能固下元，暖水脏，治下焦无火，精滑带浊，诸 \n冷顽痹，脾肾虚寒而为溏泄下痢。以其暖肾固精，所以能疗腰膝酸疼，阴冷囊湿，缩小便，暖命门 \n小腹，止腹中疼痛肾泄。以其性降，所以能纳气定喘。惟其气辛而降，所以气虚气短，及有烦渴眩 \n运者，当少避之，即不得已，用于丸中可也。忌羊肉、芸薹。 \n\\x木香\\x（八六） 味苦辛，性温。气味俱浓，能升能降，阳中有阴。行肝脾肺气滞如神，止心腹胁 \n气痛甚捷。和胃气，止吐泻霍乱；散冷气，除胀疼呃逆。治热痢可佐芩、连，固大肠火煨方用。顺 \n其气，症积恶逆自除；调其气，安胎月经亦用。亦治疫疠温疟，亦杀蛊毒鬼精。若下焦气逆诸病， \n亦可缩小便，亦能通秘结，亦能止气逆之动血，亦能消气逆之痈肿。 \n\\x藿香\\x（八七） 味辛微甘，气温。气味惧薄，阳也，可升可降。此物香甜不峻，善快脾顺气，开 \n胃口，宽胸膈，进饮食，止霍乱呕吐，理肺化滞。加乌药等剂，亦能健脾；入四君同煎，能除口臭。 \n亦疗水肿，亦解酒秽。 \n\\x香附\\x（八八） 味苦辛微甘，气温。气味俱浓，阳中有阴，血中气药也。专入肝胆二经，兼行诸经之 \n气。用此者，用其行气血之滞。童便炒，欲其下行；醋炒，则理气痛。开六郁，散寒邪，利三焦， \n行结滞，消饮食痰涎，痞满腹胀，附肿香港脚、止心腹肢体头目齿耳诸痛，疗霍乱吐逆。气滞泄泻， \n及吐血下血尿血，妇人崩中带下，经脉不调，胎前产后气逆诸病。因能解郁，故曰妇人之要药。然 \n其味辛而动，若阴虚躁热而汗出血失者，概谓其要，则大误矣。此外，凡痈疽瘰沥疮疡，但气滞不 \n行者，皆宜用之为要药。 \n\\x砂仁\\x（八九） 味辛微苦，气温。和脾行气，消食逐寒，除霍乱，止恶心。消胀满，安气滞之胎；却 \n腹痛，治脏寒之泻。止小便泄痢，快胸膈开痰。平气逆咳嗽，口齿浮热；止女子崩中，鬼气奔豚。 \n欲其温暖，须用炒研。入肺肾膀胱，各随使引。亦善消化铜铁骨哽。 \n\\x紫苏\\x（九十） 味辛，气温。气味香窜者佳。用此者，用其温散。解肌发汗，祛风寒甚捷；开胃下食， \n治胀满亦佳。顺气宜用，口臭亦辟，除霍乱转筋，祛香港脚，通大小肠，消痰利肺，止痛温中，安胎 \n定喘，解鱼蟹毒，治蛇犬伤。或作羹，或生食俱可。 \n\\x梗\\x 能顺气，其性缓，体虚者可用。 \n\\x子\\x 性润而降，能润大便，消痰喘，除五膈，定霍乱，顺气滞。 \n\\x薄荷\\x（九一） 味辛微苦，气微凉。气味俱轻，升也，阳也。其性凉散，通关节，利九窍，乃手 \n厥阴、太阴经药。清六阳会首，散一切毒风，治伤寒头痛寒热，发毒汗，疗头风脑痛，清头目咽喉 \n口齿风热诸病，除心腹恶气胀满霍乱，下气消食痰，辟邪气秽恶，引诸药入营卫，开小儿之风涎， \n亦治瘰 痈肿疮疥风瘙瘾疹。作菜食之除口气，捣汁含漱，去舌胎语涩，揉叶塞鼻止衄血。亦治蜂 \n螫蛇伤。病新痊者忌用，恐其泄汗阳。 \n\\x荆芥\\x（九二） 味辛苦，气温。气浓味薄，浮而升，阳也。用此者，用其辛散调血。能解肌发表， \n退寒热，清头目，利咽喉，破结气，消饮食，通血脉，行瘀滞，助脾胃，辟诸邪毒瓦斯，醒酒逐湿， \n疗头痛头旋，脊背疼痛，手足筋急， 痹香港脚，筋骨烦疼，风湿疝气，止下血血痢，崩淋带浊。若 \n产后中风强直，宜研末酒服甚妙。捣 \n烂醋调，敷疔疮肿毒最佳，亦鼠 、瘰 、血风、疮疥必用之要药。 \n\\x白芷\\x（九三） 味辛，气温。气浓味轻，升也，阳也。其性温散败毒，逐阳明经风寒邪热，止头痛 \n头风头眩，目痛目痒泪出，散肺经风寒，皮肤斑疹燥痒，治鼻鼽鼻渊，齿痛眉棱骨痛，大肠风秘， \n肠风尿血。其气辛香达表，故治疮疡排脓止痒定痛，托痈疽肺痈瘰 痔痿，长肉生肌。炒黑用之， \n提女人血崩，漏下赤白，血闭阴肿。欲去 斑，宜以生用，可作面脂。亦治蛇伤砒毒，金疮伤损。 \n\\x香薷\\x（九四） 味苦辛，气寒。气轻，能升能降。散暑热霍乱，中脘绞痛，小便涩难，清肺热， \n降胃火，除躁烦，解郁滞。为末水服，可止鼻衄。煮汁顿饮，可除风热转筋，去口臭。湿热水肿者 \n可消，中寒阴脏者须避之。 \n\\x益智\\x（九五） 气味辛温，能调诸气，辟寒气，治客寒犯胃，暖胃和中，去心腹气滞疼痛，理下 \n焦虚寒，温肾气，治遗精余沥梦泄，赤白带浊。及夜多小便者，取二十余枚，研碎，入盐少许，同 \n煎服之，有奇验。此行阳退阴之药，凡脾寒不能进食，及三焦命门阳气衰弱者皆宜之。然其行性多， \n补性少，必兼补剂用之斯善。若单服多服，未免过于散气。 \n\\x郁金\\x（九六） 味苦辛，气温。善下气，破恶血，去血积，止吐血衄血，血淋尿血，及失心癫狂 \n蛊毒。军用治妇人冷气血积，结聚气滞，心腹疼痛，及产后败血冲心欲死，或散或丸，或以韭汁、 \n姜汁、童便、井花水俱可，随宜调服。若治痔漏肿痛，宜水调敷之。耳内肿痛，宜水调灌入，少顷 \n倾出即可愈。 \n\\x姜黄\\x（九七） 味苦辛，性热。善下气破血，除心腹气结气胀，冷气食积疼痛，亦治 瘕血块， \n通月经，产后败血攻心，及扑损瘀血，祛邪辟恶，散风热，消痈肿、功与郁金稍同，而气味则尤烈。 \n\\x泽兰\\x（九八） 味微苦微辛。善清血和血，治吐血衄血，疗妇人产前产后诸血不调，破宿血，除腹 \n痛，清新血，利关节，通水道，除 瘕，消扑损瘀血，并治金疮痈肿疮脓，用在清和，故为妇人要 \n药。 \n\\x 本\\x（九九） 味甘辛，性温。气浓味薄，升也，阳也。疗诸恶风鬼注，除太阳顶巅头痛，大寒 \n犯脑，痛连齿颊，及鼻面皮肤酒 刺，风湿泄泻，冷气腰疼，妇人阴中风邪肿痛。此足太阳经风 \n痫雾露瘴疫之要药。 \n\\x萆茇\\x（一百） 味辛，大热，阳也，浮也。入手足阳明，亦入肝肾。善温中下气，除胃冷，辟阴 \n寒，疗霍乱心腹疼痛，冷痰呕逆吞酸，及虚寒泻痢肠鸣。其味大辛，须同参、术、归、地诸甘温补 \n剂用之尤效。为末搐鼻，可解偏风头痛；揩齿可杀牙痛牙虫。又牛乳煎治唐太宗气痢方，详列痢疾 \n门。 \n\\x良姜\\x（百一） 子名红豆蔻。味辛热，纯阳，浮也。入足太阴阳明。治胃中逆冷，呕吐清水，恶心 \n霍乱，气寒腹痛，解酒毒，消宿食，健脾胃，宽噎膈，除反胃，破冷癖，解瘴疟，疗转筋泻痢。同 \n草豆蔻煎钦，亦治口臭。子名红豆蔻，治用略同。 \n\\x三棱\\x（百二） 气味苦平，能行血中之气。善破积气，逐瘀血，消饮食胀满，气滞腹痛，除 癖 \n瘕，积聚结块，通月水，亦堕胎及产后恶血，扑损瘀血，并治疮肿坚硬。制宜醋浸炒熟入药。此 \n与蓬术稍同，但蓬术峻而此则差缓耳。 \n\\x蓬术\\x（百三） 一名蓬莪术。味苦辛，气温，有小毒。走肝经。善破气中之血。通月经，消瘀血， \n疗跌扑损伤血滞作痛。在中焦攻饮食气滞不消，胃寒吐酸膨胀；在下焦攻奔豚 癖，冷气积聚，气 \n肿水肿。制宜或酒或醋炒用，或入灰火中煨熟捣切亦可。但其性刚气峻，非有坚顽之积不宜用。 \n\\x蛇床子\\x（百四） 味微苦，气辛，性温。乃少阳三焦命门之药。辛能去风，暖能温肾，故可温中 \n下气，和关节，除疼痛，开郁滞，疗阴湿恶疮疥癣，缩小便，去阴汗，止带浊，逐寒疝，漱齿痛。 \n治男子阳痿腰疼，大益阳事；女人阴中肿痛，善暖子宫。男妇阳衰无子，小儿惊痫扑伤俱可服。去 \n皮壳微炒用之。凡治外证瘙痒，肿痛风疮，俱宜煎汤熏洗，亦可为末掺敷，俱宜生用。 \n\n\n\n<目录>卷之四十八大集·本草正（上）\n\n<篇名>蔓草部\n\n属性：\\x天门冬\\x（百五） 味苦微甘，气大寒。味浓气薄，沉也，阴也。入肺肾两经，除虚劳内热。其味 \n苦寒，故上定热喘，下去热淋，苦杀三虫，润滋骨髓，解渴除烦，消痰止嗽，降火保肺，退热滋阴， \n大润血热燥结。虚寒假热， \n脾肾溏泄最忌。使宜贝母、地黄。去皮去心方用。 \n\\x菟丝子\\x（百六） 味甘辛，气微温。其性能固，入肝脾肾三经。先用甜水淘洗净，浸胀，次用酒 \n渍，煮熟晒干，炒之更炒。补髓添精，助阳固泄，续绝伤，滋消渴，缩小便，止梦遗带浊余沥，暖 \n腰膝寒疼，壮气力筋骨，明目开胃，进食肥肌，禁止鬼交，尤安梦寐。汤液丸散，任意可用，古人 \n不入煎剂，亦一失也。欲止消渴，煎汤任意饮之。 \n\\x五味子\\x（百七） 皮甘肉酸，性平而敛；核仁味辛苦，性温而暖，俱兼咸味，故名五味。入肺、 \n肾二经。南者治风寒咳嗽，北者疗虚损劳伤。整用者用其酸，生津解渴，止泻除烦，疗耗散之肺金 \n，滋不足之肾水，能收敛虚火，亦解除酒毒。敲碎者用其辛温，补元阳，壮筋骨，助命门，止霍乱。 \n但感寒初嗽当忌，恐其敛束不散。肝旺吞酸当忌，恐其助木伤土。 \n\\x何首乌\\x（百八） 味甘涩微苦，阴中有阳，性温。此其甘能补，涩能固，温能养阳。虽曰肝肾之药， \n然白者入气分，赤者入血分，凡血气所在，则五阴之脏何所不至？故能养血养神助气，壮筋骨，强 \n精髓，黑须发，亦治妇人带浊失血，产后诸虚等疾。第其性效稍缓，暂服若不甚显，必久服之，诚 \n乃延年益寿，滋生助嗣之良剂。至如断疟疾，安久痢，活血治风，疗痈肿瘰 ，风湿疮疡、及一切 \n冷气肠风宿疾，总由其温固收敛之功，血气固则真元复，真元复则邪自散也。故唐之李翱着有《何 \n首乌传》，即李时珍亦曰此物不寒不燥，功在地黄、门冬之上，诚非诬也。若其制用之法，则有用 \n黑豆层铺，九蒸九晒者；有单用米泔浸三宿，切焙为未而用者；有用壮健人乳拌晒三次，生杵为末 \n而用者。总之，生不如熟，即单用米泔浸透，蒸之极热则善矣，或不必人乳与豆也。服此之后，须 \n忌生萝卜并诸血败血等物。 \n\\x栝蒌仁\\x（百九） 味甘，气寒。气味俱浓，性降而润。能降实热痰涎，开郁结气闭，解消渴，定 \n胀喘，润肺止嗽。但其气味悍劣善动，恶心呕吐、中气虚者不宜用。《本草》言其补虚劳，殊为大 \n谬。 \n\\x天花粉\\x（百十） 即栝蒌根。味苦，性寒。气味颇轻，有升有降，阴中有阳。最凉心肺，善解热渴， \n大降膈上热痰， \n消乳痈肿毒痔 疮疖，排脓生肌长肉，除跌扑瘀血，通月水，除狂热，去黄胆，润枯燥，善解酒毒， \n亦通小肠，治肝火疝痛。 \n\\x金银花\\x（百十一） 一名忍冬。味甘，气平，其性微寒。善于化毒，故治痈疽肿毒疮癣，杨梅风 \n湿诸毒，诚为要药。毒未成者能散，毒已成者能溃。但其性缓，用须倍加。或用酒煮服，或捣汁搀 \n酒顿饮，或研烂拌酒浓敷。 \n若治瘰 、上部气分诸毒，用一两许，时常煎服，极效。 \n\\x葛根\\x（百十二） 味甘，气平寒。气轻于味，浮而微降，阳中微阴。用此者，用其凉散，虽善达诸阳 \n经，而阳明为最。以其气轻，故善解表发汗。凡解散之药多辛热，此独凉而甘，故解温热时行疫疾， \n凡热而兼渴者，此为最良，当以为君而佐以柴、防、甘、桔极妙。尤散郁火，疗头痛，治温疟往来， \n疮疹未透，解酒除烦，生津止渴，除胃中热狂，杀野葛、巴豆、毒箭、金疮等伤。但其性凉，易于 \n动呕，胃寒者所当慎用。 \n\\x茜草\\x（百十三） 亦名过山龙。味苦甘，气微寒。阴中微阳，血中要药。其味苦，故能行滞血； \n其性凉，故能止动血。治劳伤吐衄时来，除虚热漏崩不止，亦通经滞，又疗乳痈，散跌扑血凝瘀聚， \n解蛊毒败血烂肝，凡诸血热血瘀，并建奇功。若女人经血不通，以一两酒煎服之，一日即通，甚效。 \n若气虚不摄血，及脾寒者勿用。 \n\\x土茯苓\\x（百十四） 一名仙遗粮味甘淡，性平。能健脾胃，强筋骨，去风湿，利关节，分水道， \n止泻痢，治拘挛骨痛，疗痈肿喉痹，除周身寒湿恶疮，尤解杨梅疮毒，及轻粉留毒，溃烂疼痛诸证。 \n凡治此者，须忌茶、酒、牛、羊、鸡、鹅，及一应发风动气等物。 \n\\x使君子\\x（百十五） 味甘，气温，有小毒，性善杀虫。治小儿疳积，小便白浊。凡大人小儿有虫 \n病者，但于每月上旬，侵晨空腹食数枚，或即以壳煎汤咽下，次日虫皆死而出也。或云七生七煨食， \n亦良。或云一岁食一枚。食后忌饮热茶，犯之即作泻。凡小儿食此，亦不宜频而多，大约性滑， \n多则能伤脾也。李时珍曰∶凡杀虫药多是苦辛，惟使君子、榧子甘而杀虫，亦异也。但使君子专杀 \n蛔虫，榧子专杀寸白虫耳。 \n\\x牵牛\\x（百十六） 一名黑丑味苦辛，热，气雄烈，性急疾，有毒。下气逐水，通大小便，善走气 \n分，通水道，消气实气滞水肿，攻症积，落胎杀虫，泻虫毒，去湿热痰饮，开气秘气结。古方多为 \n散丸，若用救急，亦可佐群药煎服。然大泄元气，凡虚弱之人须忌之。 \n\\x防己\\x（百十七） 味苦，性寒，阴也，降也。去湿热水肿，利大小便，解诸经热壅肿痛，湿热香港脚， \n通九窍热闭，逐膀胱肝肾湿热，及热毒诸疮、湿热生虫等证。 \n\\x萆 \\x（百十八） 味微甘而淡，气温。能温肾去湿，理阴痿阴寒，失溺白浊，茎中作痛，及四肢 \n瘫痪不随，周身风湿恶疮。性味纯缓，用宜大剂。 \n\\x钩藤\\x（百十九） 味微甘微苦，性微寒。能清手厥阴之火，足厥阴、足少阳之风热，故专理肝风 \n相火之病。凡大人小儿惊痫眩运，斑疹天钓，头旋烦热等证，用之而风静火息，则诸证自除矣。 \n\\x山豆根\\x（百二十） 味大苦，大寒。解诸药热毒，消痈肿疮毒，杀寸白诸虫。含而咽汁，解咽喉 \n痹痛。研末汤服五七分，解内热喘满腹胀。磨汁服，解热厥心痛。研汁涂诸热毒热疮肿痛，及诸虫 \n热毒所伤。 \n\\x威灵仙\\x（百二一） 味微辛微咸，性温，可升可降，阴中阳也。善逐诸风，行气血，走经络，宣 \n通五脏，去腹内冷滞，心膈痰水， 瘕 癖，气块积聚，膀胱宿水，腰膝肢体冷痛，亦疗折伤。此 \n药性利善走，乃治痛风之要药，故崔元亮言其去众风，通十二经脉，朝服暮效。其法采得根，阴干 \n月余，捣末，温酒调服一钱匕，空腹服之；如人本性杀药，可加及六钱，微利两行则减之，病除乃 \n停药。其性甚善，不触诸药，但恶茗及面汤。李时珍曰∶威灵仙辛能泄气，咸能泄水，故于风湿痰 \n饮之病，气壮者服之有捷效。其性大抵峻利，久服恐损真气，气弱者亦不可服之。 \n\\x马兜铃\\x（百二二） 味微苦微辛，性寒气薄，阴中微阳。入手太阴肺经。降肺火，清肺气，除 \n热痰咳嗽，喘急不得卧。多用则作吐。凡蛊毒蛇毒于饮食中得之，咽中如有物，咽不下，吐不出者， \n以此一两煎汤服之，即毒从吐出。若治痔 肿痛，用马兜铃于瓶中烧烟熏病处良。 \n\\x青木香\\x（百二三） 即马兜铃根，亦名土木香味苦微辛，性寒。有毒，能吐能利，不可多服。煮 \n汁服，可吐蛊毒鬼疰诸毒。捣末水调，涂疔肿热毒蛇毒，日三四次，立瘥。亦可敷瘙痒秃疮。 \n\\x白蔹\\x（百二四） 味苦，微寒，性敛。取根捣敷痈毒，及面上疮 、刀箭伤、汤火毒。诸疮不敛， \n生肌止痛，俱宜为末敷之。若为丸散，亦治眼目赤痛，小儿惊痫，妇人阴中肿痛，赤白带下。 \n\\x木通\\x（百二五） 亦名通草。味苦，气寒，沉也，降也。能利九窍，通关节，消浮肿，清火退热， \n除烦渴黄胆，治耳聋目痛，天行时疾，头痛鼻塞目眩，泻小肠火郁，利膀胱热淋，导痰湿呕哕，消 \n痈肿壅滞，热毒恶疮，排脓止痛，通妇人血热经闭，下乳汁，消乳痈血块，催生下胎。若治小水急 \n数疼痛，小腹虚满，宜加葱煎饮。若治喉痹咽痛，宜浓煎含咽。 \n\n\n\n<目录>卷之四十八大集·本草正（上）\n\n<篇名>毒草部\n\n属性：\\x附子\\x（百二六） 气味辛甘，腌者大咸，性大热，阳中之阳也。有毒。畏人参、黄 、甘草、黑豆、 \n绿豆、犀角、童便、乌韭、防风。其性浮中有沉，走而不守。因其善走诸经，故曰与酒同功。能除 \n表里沉寒，厥逆寒噤，温中强阴，暖五脏，回阳气，除呕哕霍乱，反胃噎膈，心腹疼痛，胀满泻痢， \n肢体拘挛，寒邪湿气，胃寒蛔虫，寒痰寒疝，风湿麻痹，阴疽痈毒，久漏冷疮，格阳喉痹，阳虚二 \n便不通，及妇人经寒不调，小儿慢惊等证。大能引火归源，制伏虚热，善助参、 成功，尤赞术、 \n地建效。无论表证里证，但脉细无神，气虚无热者，所当急用。故虞搏曰∶附子禀雄壮之质，有斩 \n关夺将之气，能引补气药行十二经，以追复散失之元阳；引补血药入血分，以滋养不足之真阴；引 \n发散药开腠理，以驱逐在表之风寒。引温暖药达下焦，以祛除在里之冷湿，吴绶曰；附子乃阴证要 \n药，凡伤寒传变三阴，及中寒夹阴，虽身大热而脉沉者必用之；或厥冷脉沉细者，尤急须用之，有 \n退阴回阳之力，起死回生之功。近世阴证伤寒往往疑似而不敢用，直待阴极阳竭而用，已迟矣。且 \n夹阴伤寒，内外皆阴，舍此不用，将何以救之？此二公之言，皆至言也，不可不察。惟孕妇忌服， \n下 \n胎甚速。合葱涎塞耳，亦可治聋。 \n辨制法∶附子制法，稽之古者，则有单用童便煮者，有用姜汁盐水者，有用甘草、黄连者，有数味 \n皆兼而用者，其中宜否，最当详辨。夫附子之性热而刚急，走而不守，土人腌以重盐，故其味咸而 \n性则降。今之所以用之者，正欲用其热性以回元阳，以补脾肾，以行参、 、熟地等功，若制以黄 \n连，则何以藉其回阳？若制以盐水，则反以助其降性。若制以童便，则必不免于尿气，非惟更助其 \n降，而凡脾气大虚者，极易呕哕，一闻其臭，便动恶心，是药未入口，而先受其害，且其沉降尤速， \n何以达脾？惟是姜汁一制颇通，第其以辛助辛，似欠和平，若果直中阴寒等证，欲用其热，此法为 \n良；至若常用而欲得其补性者，不必用此。又若煮法，若不浸胀而煮，则其心必不能熟，即浸胀而 \n煮，及其心熟，则边皮已太熟而失其性矣；虽破而为四，煮亦不匀。且煮者必有汁，而汁中所去之 \n性亦已多矣，皆非制之得法者。制法∶用甘草不拘，大约酌附子之多寡而用。甘草煎极浓甜汤，先 \n浸数日，剥去皮脐，切为四块，又添浓甘草汤再浸二三日，捻之软透，乃咀为片，入锅文火炒至将 \n干，庶得生熟匀等，口嚼尚有辣味，是其度也。若炒太干，则太熟而全无辣味，并其热性全失矣。 \n故制之太过，则但用附子之名耳，效与不效无从验也。其所以必用甘草者，盖以附子之性急，得甘 \n草而后缓；附子之性毒，得甘草而后解；附子之性走，得甘草而后益心脾；附子之性散，得甘草而 \n后调营卫，此无他，亦不过济之以仁而后成其勇耳。若欲急用，以浓纸包裹，沃甘草汤，或煨，或 \n炙，待其柔软，切开，再用纸包频沃，又炙，以熟为度。亦有用面裹而煨者亦通。若果真中阴寒， \n厥逆将危者，缓不及制，则单用炮附，不必更用他制也。 \n辨毒 附子之性，刚急而热，制用失宜，难云无毒，故欲制之得法。夫天下之制毒者，无妙于 \n火，火之所以能制毒者，以能革物之性。故以气而遇火，则失其气，味而遇火，则失其味，刚者革 \n其刚，柔者失其柔。故制附之法，但用白水煮之极熟，则亦全失辣味，并其热性俱失，形如萝卜可 \n食矣，尚何毒之足虑哉？今制之必用甘草者，盖欲存留其性而柔和其刚耳。令人但知附子之可畏， \n而不知太熟之无用也。故凡食物之有毒 \n者，但制造极熟，盒饭无害，即河豚、生蟹之属，诸有病于人者，皆其欠熟而生性之未尽也。故凡 \n食物之有毒者，皆可因此以类推矣。至若药剂之中，有当 炼而用者，又何以然？夫物之经火 者， \n其味皆咸涩，而所以用 者，非欲去其生刚之性，则欲用其咸涩之味，而留性与不留性，则其中各 \n有宜否，故凡当 炼而用者，皆可因此以类推矣。 \n又如药之性毒者，何可不避？即如《本草》所云某有毒、某无毒，余则甚不然之，而不知无药 \n无毒也。故热者有热毒，寒者有寒毒，若用之不当，凡能病患者，无非毒也。即如家常茶饭，本皆 \n养人之正味，其或过用误用，亦能毒人，而况以偏味偏性之药乎？但毒有大小，用有权宜，此不可 \n不察耳。矧附子之性，虽云有毒，而实无大毒，但制得其法，用得其宜，何毒之有？今之人不知其妙， \n且并人参、熟地而俱畏之。夫人参、熟地、附子、大黄，实乃药中之四维，病而至于可畏，势非庸 \n庸所济者，非此四物不可，设若逸巡，必误乃事。令人直至必不得已而后用附子，事已无济矣。事 \n无济则反罪之，将附子诚废物乎？ \n嗟夫！人之所以生者，阳气耳，正气耳。人之所以死者，阴气耳，邪气耳。人参、熟地者，治 \n世之良相也；附子、大黄者，乱世之良将也。兵不可久用，故良将用于暂；乱不可忘治，故良相不 \n可缺。矧夫附子虽烈，而其性扶阳，有非硝、黄之比；硝、黄似缓，而其性阴泄，又非桂、附可例。 \n华元化曰∶得其阳者生，得其阴者死。《内经》曰∶门户不要，是仓廪不藏也。得守者生，失守者 \n死。今之人履芒硝、大黄若坦途，视参、附、熟地为蛇蝎，愚耶？知耶？ \n\\x白附子\\x（百二七）味甘辛，大温，有小毒。其性升，能引药势上行。辟头风诸风，冷气心疼，风 \n痰眩晕，带浊，疗小儿惊风痰搐，及面鼻游风，野斑风刺，去面痕，可作面脂，亦治疥癣风疮，阴 \n下湿痒，风湿诸病。几欲入药，炮而用之。 \n\\x大黄\\x（百二八）味苦，气大寒。气味俱浓，阴中之阴，降也。有毒。其性推陈致新，直走不守。 \n夺土郁壅滞，破积聚坚症，疗瘟疫阳狂，除斑黄谵语，涤实痰，导瘀血，通水道，退湿热，开燥结， \n消痈肿。因有峻烈威风 \n积垢荡之顷刻。欲速者生用，汤泡便吞；欲缓者熟用，和药煎服。气虚同以人参，名黄龙汤；血虚 \n同以当归，名玉烛散。佐以甘草、桔梗，可缓其行；佐以芒硝、浓朴，益助其锐。用之多寡，酌人 \n实虚，假实误用，与鸠相类。 \n\\x常山\\x（百二九）味大苦，性寒，有毒。攻温疟痰疟，及伤寒寒热，痰结气逆，狂痫癫厥。惟胸腹多 \n滞，邪实气壮而病疟者宜之；若老人弱人，俱当忌用。盖此物性悍，善逐痰饮，得甘草则上行发吐， \n得大黄则下行发泻也。亦治鬼毒蛊毒，及头项瘰 鼠 。 \n\\x半夏\\x（百三十）味大辛微苦，气温。可升可降，阳中阴也。有毒。其质滑润，其性燥湿降痰， \n入脾胃胆经。生嚼戟喉，制用生姜。下肺气，开胃健脾，消痰饮痞满，止咳嗽上气，心痛胁痛，除 \n呕吐反胃，霍乱转筋，头眩腹胀，不眠气结，痰核肿突，去痰厥头痛，散风闭喉喑、治脾湿泄泻， \n遗精带浊，消痈疽肿毒，杀蜈蚣蜂虿虫毒。性能堕胎，孕妇虽忌，然胃不和而呕吐不止，加姜汁微 \n炒，但用无妨。若消渴烦热，及阴虚血证，最忌勿加。李时珍曰∶半夏能主痰饮及腹胀者，为其体 \n滑味辛而性温也。滑则能润，辛温能散亦能润，故行湿而通大便，利窍而泄小便，所谓辛走气，能 \n化液，辛以润之是矣。丹溪曰∶二陈汤能使大便润而小便长。 \n摄云∶半夏辛而散，行水而润肾燥。又《局方》用半硫丸治老人虚秘，皆取其滑润也。世俗皆 \n以半夏、南星为性燥，误矣。湿去则土燥，痰涎不生，非二物之性燥也。古方治咽痛喉痹，吐血下 \n血，多用二物，非禁剂也。二物亦能散血，故破伤打扑皆主之。 \n\\x南星\\x（百三一）味苦辛，气温，可升可降，阳中阴也。性烈有毒，姜汁制用。善行脾肺，坠中 \n风实痰，利胸膈，下气，攻坚积，治惊痫，散血堕胎。水磨箍蛇虫咬毒，醋调散肿。破伤风，金疮 \n折伤瘀血，宜捣敷之。功同半夏，酌用可也。 \n\\x胆星\\x（百三二）七制、九制者方佳。降痰因火动如神，治小儿急惊必用。总之，实痰实火壅闭 \n上焦，而气喘烦躁，焦渴胀满者，所当必用。较之南星，味苦性凉，故散解风痰热滞。 \n\\x射干\\x（百三三）味苦，微寒，有毒。阴也，降也。治咳逆上气，喉痹咽疼，散结气不得息，除胸 \n腹邪热胀满，清肝明目，消积痰结核， 癖热疝，降实火，利大肠，消瘀血，通女人经闭。苦酒磨 \n涂，可消肿毒。 \n\\x大戟\\x（百三四）味苦，太寒，有毒。反甘草。性峻利，善逐水邪痰涎，泻湿热胀满，消急痛，破 \n结，下恶血，攻积聚，通二便，杀蛊毒药毒，疗天行瘟疟黄病，及颈腋痈肿。然大能泻肺损真气， \n非有大实坚者，不宜轻用。若中其毒，惟菖蒲可以解之。 \n\\x甘遂\\x（百三五）味苦，性寒，有毒。反甘草。专于行水，能直达水结之处，如水结胸者，非此 \n不除。若留痰留饮宿食，症坚积聚，无不能逐，故善治腹脚阴囊肿胀，去面目浮肿，通二便、泻膀 \n胱湿热，及痰逆癫痫，噎膈痞塞。然性烈伤阴，不宜妄用。 \n\\x芫花\\x（百三六反甘草）味苦，微温，有毒。专逐五脏之水，去水饮寒痰痰癖，胁下痛，咳逆上 \n气，心腹肢体胀满，瘴疟鬼疟，湿毒寒毒，蛊毒肉毒，虫鱼毒，除疝瘕痈肿，逐恶血，消咽肿。根 \n疗疮疥，亦可毒鱼。若捣汁浸线，亦能系落痔疮。惟其多毒，虚者不可轻用。 \n\\x玉簪\\x（百三七）味甘辛，性寒，有小毒。用根捣汁，解一切诸毒，下一切骨哽，涂消痈疡。妇 \n人乳痈初起，但取根擂酒服之，仍以渣敷肿处即消。然性能损齿，故亦可落齿取牙。 \n\\x凤仙花\\x（百三八）味微苦，性微温，有小毒。子名急性子。治产难下胎，消积块，开噎膈，下 \n骨哽。亦善透骨通窍，故又名透骨草。若欲取牙，但用子研末，入砒少许，点疼牙根，即可取之。 \n然此不生虫蠹，即烽蝶亦不近，似非无毒者也。 \n\\x蓖麻子\\x（百三九）味甘辛，性热，有毒。能逐风散毒，疗口眼 斜，失音口噤，肿毒丹瘤，针 \n刺入肉，止痛消肿，追脓拔毒，俱可研贴。若治舌肿喉痹，宜研烂，纸卷烧烟，熏吸立通。催生下 \n胎，可同麝香、巴豆研贴脐中。 \n李时珍曰∶一人病偏风，手足不举，用此油同羊脂、麝香、穿山甲煎膏，日摩数次，兼服搜风 \n养血之药而愈。 \n一人病手臂一块肿痛，用此捣膏贴之，一夜而愈。一人病气郁偏头痛，用此同乳香、食盐捣贴 \n太阳，一夜痛止。一妇产后子肠不收，捣仁贴其丹田，一夜而上。此药外用，屡奏奇效，但内服不 \n可轻率尔。或云捣膏，以筋点于鹅、鸭六畜舌根下，即不能食，点于肛门内，即下血死，其毒可知 \n。凡服篦麻者，一生不得食炒豆，犯之必胀死。 \n\\x续随子\\x（百四十）一名千金子。味辛，性温，有毒。能逐瘀血，消痰饮食积， 瘕 癖，除蛊 \n毒鬼疰，水气冷气，心腹胀满疼痛，腹内诸疾，利大小肠，祛恶滞，及妇人血结血闭瘀血等证。研 \n碎酒服，不过三颗，当下恶物，甚者十粒。若泻多，以酸浆水或薄醋粥食之即止。亦可研涂疥癣恶 \n疮。此物之功，长于逐水杀虫，是亦甘遂、大戟之流也。 \n\\x木鳖子\\x（又百四十）味苦微甘微辛，气雄劣，性大寒，有大毒。〈本草》言其甘温无毒，谬也。 \n今见毒狗者，能毙之于顷刻，使非大毒，而有如是乎？人若食之，则中寒发噤，不可解救。按刘绩 \n《霏雪录》云∶木鳖子有毒，不可食。昔一蓟门人，有两子患痞，食之相继皆死，此不可不慎也。 \n若其功用，则惟以醋磨，甩敷肿毒乳痈，痔漏肿痛，及喉痹肿痛，用此醋漱于喉间，引痰吐出，以 \n解热毒，不可咽下。或同朱砂、艾叶卷筒，熏疥杀虫最效。或用熬麻油擦癣亦佳。 \n\\x番木鳖\\x 味极苦，性大寒，大毒。功用与木鳖大同，而寒烈之性尤甚。 \n\n\n\n<目录>卷之四十九大集·本草正（下）\n\n<篇名>水石草部\n\n属性：\\x石斛\\x（百四一）此药有二种，力皆微薄，圆细而肉实者，味微甘而淡，其力尤薄。《本 \n草》云∶圆细者为上。且谓其益精强阴，壮筋补虚，健脚膝，驱冷痹，却惊悸，定心志。但此物性 \n味最薄，焉能滋补如此？惟是扁大而松，形如钗股者，颇有苦味，用除脾胃之火，去 杂善饥，及 \n营中蕴热。其性轻清和缓，有从容分解之妙，故能退火养阴除烦，清肺下气，亦止消渴热汗。而诸 \n家谓其浓肠胃，健阳道，暖水脏，岂苦凉之性味所能也？不可不辨。 \n\\x菖蒲\\x（百四二）味辛微苦，性温。散风寒湿痹，除烦闷咳逆上气，止心腹痛，霍乱转筋，癫痫 \n客忤，开心气胃气，行滞气，通九窍，益心智，明耳目，去头风泪下，出声音，温肠胃，暖丈夫水 \n脏，妇人血海，禁止小便，辟邪逐鬼，及中恶卒死，杀虫，疗恶疮瘙疥。欲散痈毒，宜捣汁服用， \n渣贴之。若治耳痛，宜作末炒热绢裹 之。亦解巴豆、大戟等毒。 \n\\x蒲黄\\x（百四三）味微甘，性微寒。解心腹膀胱烦热疼痛，利小便。善止典凉血活血，消瘀血，治 \n吐血衄血，痢血尿血。通妇人经脉，止崩中带下，月经不调，妊妇胎漏坠胎，血运血症，儿枕气痛， \n及跌扑血闷。疗疮疡，消舌肿，排脓消毒。亦下乳汁，亦止泄精。凡欲利者，宜生用；欲固者，宜 \n炒熟用。泽泻（百四四（味甘淡微咸，气微寒。气味颇浓，沉而降，阴也，阴中微阳。入足太阳、少阳。 \n其功长于渗水去湿，故能行痰饮，止呕吐泻痢，通淋沥白浊，大利小便，泻伏火，收阴汗，止尿血， \n疗难产疝痛，香港脚肿胀，引药下行。经云∶除湿止渴圣药，通淋利水仙丹。第其性降而利，善耗真 \n阴，久服能损目痿阳。若湿热壅闭 \n而目不明者，此以去湿，故亦能明目。 \n\\x海藻\\x（百四五反甘草）海带、昆布性用略同。味若咸，性微寒，阴也，降也。善降气清热，消 \n膈中痰壅，故善消颈项瘿瘤结核，及痈肿症积，利小便，逐水气，治湿热气急，腹中上下雷鸣，疗 \n偏坠疝气疼痛，消奔豚水气浮肿，及百邪鬼魅热毒。 \n\\x骨碎补\\x（百四六）味微苦，性温平，乃足少阴、厥阴肝肾药也。能活血止血，补折伤，疗骨中 \n斜毒，风热疼痛，及痢后下虚。或远行，或房劳，或外感风湿，以致两足痿弱疼痛，俱宜以四斤丸、 \n补阴药之类佐而用之。成炒熟研末，用猪腰夹煨，空心食之，能治耳鸣，及肾虚久痢牙疼。 \n\n\n\n<目录>卷之四十九大集·本草正（下）\n\n<篇名>竹木部\n\n属性：\\x竹沥\\x（百四七）味甘，性微凉，阴也，降也。治暴中风痰，失音不语，胸中烦热，止烦闷消渴。丹 \n溪曰∶凡风痰、虚痰在胸膈，使人癫狂，及痰在经络四肢、皮里膜外者，非此不达不行。 \n\\x淡竹叶\\x（百四八）味甘淡，气平微凉，阴中微阳，气味俱轻。清上气咳逆喘促，消痰涎，解热 \n狂，退虚热烦躁不眠，壮热头痛，止吐血。专凉心经，亦清脾气。却风热，止烦渴，生津液，利小 \n水，解喉痹，并小儿风热惊痫。 \n\\x淡竹茹\\x（百四九）味甘，微凉。治肺痿唾痰，唾血吐血，衄血尿血，胃热呕哕噎膈，妇人血热 \n崩淋胎动，及小儿风热癫痫，痰气喘咳，小水热涩。 \n\\x天竹黄\\x（百五十）味甘辛，性凉，降也，阴中有阳。善开风痰，降热痰，治中风失音，痰滞胸 \n膈，烦闷癫痫。清心火，镇心气，醒脾疏肝。明眼目，安惊悸。疗小儿风痰急惊客忤，其性和缓， \n最所宜用。亦治金疮，并内热药毒。 \n\\x官桂\\x（百五一）味辛甘，气大热，阳中之阳也。有小毒，必取其味甘者乃可用。桂性热，善于 \n助阳，而尤入血分，四肢有寒疾者，非此不能达。桂枝气轻，故能走表，以其善调营卫，故能治伤 \n寒，发邪汗，疗伤风，止阴汗。 \n肉桂味重，故能温补命门，坚筋骨，通血脉，治心腹寒气，头疼咳嗽鼻 ，霍乱转筋，腰足脐腹疼 \n痛，一切沉寒痼冷之病。且桂为木中之王，故善平肝木之阴邪，而不知善助肝胆之阳气。惟其味甘， \n故最补脾士，凡肝邪克土而无火者，用此极妙。与参、附、地黄同用，最降虚火，及治下焦元阳亏 \n乏。与当归、川芎同用，最治妇人产后血瘀，儿枕腹痛，及小儿痘疹虚寒，作痒不起。虽善堕胎动 \n血，用须防此二证。若下焦虚寒，法当引火归元者，则此为要药，不可误执。 \n\\x丁香\\x（百五二）味大辛，气温，纯阳。入肾、胃、肺脏。能发诸香，辟恶去邪，温中快气。治 \n上焦呃逆翻胃，霍乱呕吐，解酒毒，消 癖奔豚阴寒，心腹胀满冷痛，暖下焦腰膝寒疼，壮阳道， \n抑阴邪，除胃寒泻痢，杀鬼疰蛊毒，疳蚀诸虫，辟口气，坚齿牙，及妇人七情五郁，小儿吐泻，痘 \n疮胃寒，灰白不发。 \n\\x白檀香\\x（百五三）味辛，气温。能散风热，辟秽恶邪气，消肿毒，逐鬼魅。煎服之可散冷气， \n止心腹疼痛，定霍乱，和胃气，开噎膈，止呕吐，进饮食。又治面生黑子，每晚以热水洗拭，磨汁 \n涂之甚良。 \n\\x沉香\\x（百五四）味辛，气微温，阳也，可升可降。其性暖，故能抑阴助阳，扶补相火；其气辛， \n故能通天彻地，条达诸气。除转筋霍乱，和噤口泻痢，调呕逆胃翻喘急，止心腹胀满疼痛，破症癖， \n疗寒痰，和脾胃，逐鬼疰恶气，及风湿骨节麻痹，皮肤瘙痒结气。 \n\\x乌药\\x（百五五）气味辛温，善行诸气，入脾、胃、肝、肾、三焦、膀胱诸经。疗中恶鬼气蛊毒， \n开胸膈，除一切冷气，止心腹疼痛，喘急霍乱，反胃胀满，温肠胃，行宿食，止泻痢，除天行疫瘴， \n气厥头痛，膀胱肾气攻冲心腹，疝气香港脚，痈疽疥癞，及妇人血气，小儿虫积，亦止小便频数，气 \n淋带浊，并猫犬百病，俱可磨汁灌治之。 \n\\x枸杞\\x（百五六）味甘微辛，气温，可升可降。味重而纯，故能补阴；阴中有阳，故能补气，所 \n以滋阴而不致阴衰助阳而能使阳旺。虽谚云∶离家千里，勿食枸杞，不过谓其助阳耳，似亦未必然 \n也。此物微助阳而无动性， \n故用之以助熟地最妙。其功则明耳目，壮神魂，添精固髓，健骨强筋，善补劳伤，尤止消渴。真阴 \n虚而脐腹疼痛不止者，多用神效。 \n\\x地骨皮\\x（百五七）枸杞根也。南者苦味轻，微有甘辛，北者大苦性劣，入药惟南者为佳。其性 \n辛寒，善入血分肝肾三焦胆经。退阴虚血热，骨蒸有汗，止吐血衄血，解消渴，疗肺肾胞中阴虚伏 \n火。煎汤漱口止齿血。凡不因风寒而热在精髓阴分者，最宜此物。凉而不峻，可理虚劳。气轻而辛， \n故亦清肺。假热者勿用。 \n\\x浓朴\\x（百五八）味苦辛，气大温，气味俱浓，阳中之阴，可升可降。有小毒。用此者，用其温 \n降散滞。制用姜汁炒。治霍乱转筋，消痰下气，止咳嗽呕逆吐酸，杀肠脏诸虫，宿食不消，去结水， \n破宿血，除寒湿泻痢，能暖脾胃，善走冷气。总之，逐实邪，泻膨胀，散结聚，治胸腹疼痛之要药。 \n倘本元虚弱，误服脱人真气。孕妇忌用，堕胎须知。 \n\\x枣仁\\x（百五九）味微甘，气平。其色赤，其肉味酸，故名酸枣。其仁居中，故性主收敛而入心。 \n多眠者生用，不眠者炒用。宁心志，止虚汗，解渴去烦，安神养血，益肝补中，收敛魂魄。 \n\\x杜仲\\x（百六十）味甘辛淡，气温平。气味俱薄，阳中有阴。其功入肾。用姜汁或盐水润透，炒 \n去丝。补中强志，壮肾添精，腰痛殊功，足疼立效。除阴囊寒湿，止小水梦遗。因其气温，故暖子 \n宫；因其性固，故安胎气。内热火盛者，亦当缓用。 \n\\x山茱萸\\x（百六一）味酸涩，主收敛，气平微温，阴中阳也。入肝肾二脏。能固阴补精，暖腰膝， \n壮阴气，涩带浊，节小便，益髓兴阳，调经收血。若脾气大弱而畏酸者，姑暂止之，或和以甘草、 \n煨姜亦可。 \n\\x苏木\\x（百六二）味微甘微辛，性温平，可升可降，乃三阴经血分药也。少用则和血活血，多用则 \n行血破血。主妇人月经不调，心腹作痛，血癖气壅。凡产后血瘀，胀闷势危者，宜用五两，水煮浓 \n汁服之。亦消痈肿死血，排脓止痛，及打扑瘀血，可敷。若治破伤风，宜为末酒服，立效。 \n\\x川椒\\x（百六三）味辛，性热，有小毒。本纯阳之物，其性下行，阳中有阴也。主温中下气，开 \n通腠理，散肌表寒 \n邪，除脏腑冷痛，去胸腹留饮，停痰宿食，解郁结，温脾胃，止咳逆呕吐，逐寒湿风痛，疗伤寒温 \n疟，水肿湿疸，除齿痛，暖腰膝，收阴汗，缩小便，温命门，止泄泻下痢，遗精脱肛，杀蛔虫鬼疰 \n蛊毒蛇虫诸毒。久服之能通神明，实腠理，和血脉，坚齿牙，生须发，明耳目，调关节，耐寒暑。 \n若中其毒，惟冷水、麻仁浆可以解之。 \n\\x胡椒\\x（百六四）味辛，性大热，纯阳也。善走气分。温中下气，暖肠胃，消宿食，辟臭恶，除 \n寒食寒痰，寒饮吐水，止反胃呕吐霍乱，虚寒胀满，心腹疼痛，去冷积阴毒，壮肾气，治大肠寒滑 \n冷痢，杀一切虫鱼鳖蕈诸药食阴凝之毒。若治风虫牙痛，须同萆茇为末，熔蜡为细丸，塞孔中即愈。 \n\\x金樱子\\x（百六五）味涩，性平。生者色青酸涩，熟者色黄甘涩，当用其将熟微酸而甘涩者为妙。 \n其性固涩，涩可固阴治脱，甘可补中益气。故善理梦遗精滑，及崩淋带漏，止吐血衄血，生津液， \n安魂魄，收虚汗，敛虚火，益精髓，壮筋骨，补五脏，养血气，平咳嗽，定喘急，疗怔忡惊悸，止 \n脾泄血痢及小水不禁。此固阴养阴之佳品，而人之忽之亦久矣，此后成宜珍之。 \n\\x槐蕊\\x（百六六）味苦，性寒。清心肺脾肝大肠之火，除五内烦热，心腹热疼，疗眼目赤痛热泪。 \n炒香嚼咽，治失音喉痹。止吐血衄血，肠风下血，妇人崩中漏下，及皮肤风热。凉大肠，杀疳虫， \n治痈疽疮毒，阴疮湿痒痔漏，解杨梅恶疮，下疳伏毒，大有神效。 \n\\x柏子仁\\x（百六七）味甘平，性微凉。能润心肺，养肝脾，滋肾燥，安神魂，益志意。故可定惊 \n悸怔忡，益阴气，美颜色，疗虚损，益血止汗，润大肠，利虚秘，亦去百邪鬼魅，小儿惊痫。总之， \n气味清香，性多润滑，虽滋阴养血之佳剂，若欲培补根本，乃非清品所长。 \n\\x枳壳\\x（百六八）即枳实之迟收而大者。较之枳实，其气略散，性亦稍缓，功与枳实大类。但枳 \n实性重，多主下行削坚，而此之气轻，故多主上行破气。通利关节，健脾开胃，平肺气，止呕逆反 \n胃霍乱咳嗽，消痰消食，破心腹结气， 瘕 癖，开胸胁胀满痰滞，逐水肿水湿泻痢，肠风痔漏， \n肛门肿痛。因此稍缓，故可用之束胎安 \n胎，炙热可熨痔肿。虚者少用，恐伤元气。 \n\\x枳实\\x（百六九）味苦微酸，微寒，气味俱浓，阴中微阳。其性沉，急于枳壳。除胀满，消宿食， \n削坚积，化稠痰，破滞气，平咳喘，逐瘀血停水，解伤寒结胸，去胃中湿热。佐白术亦可健脾，佐 \n大黄大能椎荡。能损真元，虚羸勿用。 \n\\x蔓荆子\\x（百七十）味苦辛，气清，性温，升也，阳也。入足太阳、阳明、厥阴经。主散风邪， \n利七窍，通关节，去诸风头痛脑鸣，头沉昏闷，搜肝风，止目睛内痛泪出，明目坚齿，疗筋骨间寒 \n热湿痹拘挛，亦去寸白虫。 \n\\x五加皮\\x（百七一）味辛，性温。除风湿，行血脉，壮筋骨，明目下气。治骨节四肢拘挛，两脚 \n痹痛，风弱五缓，阴痿囊湿，疝气腹痛，小便遗沥，女人阴痒。凡诸浸酒药，惟五加皮与酒相合， \n大能益人，且味美也。仙家重此，谓久服可以长生，故曰∶宁得一把五加，不用金银满车。虽未必 \n然，然亦必有可贵者。 \n\\x川楝子\\x（百七二）味苦，性寒，有小毒，阴也。能治伤寒瘟疫烦热狂躁，利小水，泻肝火，小 \n肠膀胱湿热，诸疝气疼痛，杀三虫疥癞，亦消阴痔。丸散汤药任意可用，甄权言其不入汤使，则失 \n之矣。 \n\\x苦楝根\\x 味大苦。杀诸虫，尤善逐蛔。利大肠，治游风热毒恶疮。苦酒和涂疥癣甚良。 \n\\x女贞子\\x（百七三）味苦，性凉，阴也，降也。能养阴气，平阴火，解烦热骨蒸，止虚汗消渴， \n及淋浊崩漏，便血尿血，阴疮痔漏疼痛。亦清肝火，可以明目止泪。 \n\\x桑白皮\\x（百七四）味甘微辛微苦，气寒。气味俱薄，升中有降，阳中有阴。入手太阴肺脏。气 \n寒味辛，故泻肺火；以其味甘，故缓而不峻。止喘嗽唾血，亦解渴消痰，除虚劳客热头痛。水出高 \n原，故清肺亦能利水。去寸白，杀腹脏诸虫。研汁治小儿天吊惊痫客忤，及敷鹅口疮，大效。作线 \n可缝金疮。既泻肺实，又云补气，则未必然。 \n\\x黄柏\\x（百七五）味苦微辛，气寒，阴中微阳，降也，善降三焦之火。制各以类，但其性多沉， \n尤专肝肾，故曰足少阴本经、足太阳、厥阴之引经也。清胃火呕哕蛔虫，除伏火骨蒸烦热，去肠风 \n热痢下血，逐二便邪火结淋。 \n上可解热渴口疮，喉痹痈疡；下可去足膝湿热，疼痛痿蹶。此其性寒润降，去火最速。丹溪言其制 \n伏龙火，补肾强阴。然龙火岂沉寒可除？水枯岂苦劣可补？阴虚水竭，得降愈亡，扑减元阳，莫此 \n为甚。水未枯而火盛者，用以抽薪则可，水既竭而枯热者，用以补阴实难，当局者慎勿认为补剂。 \n予尝闻之丹溪曰∶火有二∶君火者，人火也，心火也，可以湿伏，可以水灭，可以直折，黄连之属 \n可以制之；相火者，天火也，龙雷之火也，阴火也，不可以水湿折之，当从其性而伏之，惟黄柏之 \n属可以降之。按此议论，若有高见，而实矫强之甚，大是误人。夫所谓从其性者，即《内经》从治 \n之说也。经曰∶正者正治，从者反治。正治者，谓以水制火，以寒治热也。从治者，谓以火济火， \n以热治热也，亦所谓甘温除大热也。岂以黄连便是正治，黄柏便是从治乎？，即曰黄连主心火，黄 \n柏主肾火，然以便血溺血者，俱宜黄连，又岂非膀胱、大肠下部药乎？治舌疮口疮者，俱宜黄柏， \n又岂非心脾上部药乎？总之，黄连、黄柏均以大苦大寒之性，而曰黄连为水，黄柏非水，黄连为泻， \n黄柏为补，岂理也哉？若执此说，误人多矣，误人多矣。 \n\\x栀子\\x（百七六）味苦，气寒。味浓气薄，气浮味降，阴中有阳。因其气浮，故能清心肺之火， \n解消渴，除热郁，疗时疾躁烦，心中懊 ，热闷不得眠，热厥头疼，耳目风热赤肿疼痛，霍乱转筋。 \n因其味降，故能泻肝肾膀胱之火，通五淋，治大小肠热秘热结，五种黄胆、三焦郁火，脐下热郁疝 \n气，吐血衄血，血痢血淋，小腹损伤瘀血。若用佐使，治有不同∶加茵陈，除湿热疸黄；加豆豉， \n除心火烦躁；加浓扑、枳实，可除烦满；加生姜、陈皮，可除呕哕；同玄胡索，破热滞瘀血腹痛。 \n此外如面赤酒 ，热毒汤火，疮疡肿痛，皆所宜用。仲景因其气浮而苦，极易动吐，故用为吐药， \n以去上焦痰滞。丹溪谓其解郁热，行结气。其性屈曲下行，大能降火从小便泄去，人所不知。 \n\\x郁李仁\\x（百七七）味苦辛，阴中有阳，性润而降。故能下气消食，利水道，消面目四肢大腹水 \n气浮肿，开肠中结气滞气，关隔燥涩，大便不逸，破血积食癖。凡妇人、小儿实热结燥者皆可用。 \n\\x诃子\\x（百七八）味苦酸涩，气温。苦重酸轻，性沉而降，阴也。能消宿食膨胀，止呕吐霍乱， \n定喘止嗽，破结气，安久痢，止肠风便血，降痰下气，开滞涩肠，通达津液，疗女人崩中胎漏带浊， \n经乱不常。若久痢肛门急痛，或产妇阴痛者，宜和蜡烧烟熏之，或煎汤熏洗亦可。若痰嗽咽喉不利， \n宜含数枚，咽津殊效。其有上焦元气虚陷者，当避其苦降之性。 \n\\x侧柏\\x（百七九）味苦，气辛，性寒。善清血凉血，止吐血衄血，痢血尿血，崩中赤白，去湿热 \n湿痹，骨节疼痛。捣烂可敷火丹，散 腮肿痛热毒，及汤火伤，止痛灭瘢。炙捣可 冻疮。烧汁涂 \n发，可润而使黑。 \n\\x辛夷\\x（百八十）一名木笔，一名迎春。气味辛温，乃手太阴、足阳明之药。能解寒热憎寒体噤， \n散风热，利九窍，除头风脑痛，眩冒瘙痒，疗面肿引齿疼痛。若治鼻塞涕出，鼻渊鼻鼽鼻疮，及痘 \n后鼻疮，并宜为末，入麝香少许，以葱白蘸药点人数次，甚良。 \n\\x皂角\\x（百八一）气味辛咸，性温，有小毒。善逐风痰，利九窍，通关节，治头风，杀诸虫精物， \n消谷导痰，除咳嗽心腹气结，疼痛胀满，开中风口噤，治咽喉痹塞肿痛，行肺滞，通大肠秘结，堕 \n胎，破坚症，消肿毒，及风癣疥癞。烧烟熏脱肛肿痛。可为丸散，不入汤药。 \n\\x巴豆\\x（百八二）味辛，性热，有大毒，可升可降。善开关窍，破症坚积聚，逐痰饮，杀诸恶毒虫 \n毒蛊毒，通秘结，消宿食，攻脏腑停寒，生冷壅滞，心腹疼痛，泻痢惊痫，诸水气症气，下活胎死 \n胎，逐瘀血血积，及消痈疡疔毒恶疮，去 肉恶肉腐肉，排脓消肿，喉痹牙疼诸证。然其性刚气烈， \n无处不到，故称为斩关夺门之将，若误用之，则有推墙倒壁之虞；若善用之，则有戡乱调中之妙， \n用者所当慎察。 \n\\x密蒙花\\x（百八三）味甘平，性微寒。入肝经，润肝燥，专理目疾。疗青盲，去赤肿多浪，消目 \n中赤脉肤翳，羞明畏日，及小儿疮痘疳气攻目，风热麋烂，云翳遮睛。制用之法，宜蜜酒拌蒸三次， \n日干用 \n\\x雷丸\\x（百八四）味苦，性寒，有小毒。杀三虫，逐蛊毒诸毒，降胃中实热，痰火癫狂，除百邪 \n恶气，并一应血积气聚。 \n\\x大枫子\\x（百八五）味辛，性热，有毒。能治风癣疥癞，攻毒杀虫，亦疗杨梅诸疮。 \n\\x芜荑\\x（百八六）味辛平，性温。主心腹冷气症积疼痛，散肌肤风湿淫淫如虫行，杀三虫，去寸 \n白及诸恶虫毒，疗肠风痔漏恶疮。和猪脂捣涂热疮，和蜜可治湿癣。 \n\\x茯苓\\x（百八七）味甘淡，气平。性降而渗，阳中阴也。有赤白之分，虽《本草》言赤泻丙丁，白 \n入壬癸，然总不失为泄物，故能利窍去湿。利窍则开心益智，导浊生津；去湿则逐水燥脾，补中健 \n胃。祛惊痫，浓肠脏，治痰之本，助药之降。以其味有微甘，故曰补阳，但补少利多，故多服最能 \n损目，久弱极不相宜。若以人乳拌晒，乳粉既多，补阴亦妙。 \n\\x茯神\\x（百八八）附根而生近，故能入心经，通心气，补健忘，止恍惚惊悸。虽《本草》所言如 \n此，然总不外于渗降之物，与茯苓无甚相远也。 \n\\x猪苓\\x（百八九）味微苦、甘，气平，阳牛阴也。性善降渗，入膀胱，肾经。通淋消水肿，除湿 \n利小便。因其苦，故能泄滞，因其淡，故能利窍。亦解伤寒湿热香港脚白浊，亦治妊娠子淋胎肿。 \n\\x桑寄生\\x（百九十）味苦，性凉。主女子血热崩中胎漏，固血安胎，及产后血热诸疾，去风热湿 \n痹，腰膝疼痛、长须眉、坚发齿，凉小儿热毒，痈疳疮癞。 \n\\x琥珀\\x（百九一）味甘淡，性平。安五脏，清心肺，定魂魄，镇癫痫，杀邪鬼精魅，消瘀血痰涎， \n解蛊毒，破 结，通五淋，利小便，明目磨翳，止血生肌，亦合金疮伤损。"}, {"n": 30, "text": "卷三十\n\n\\x松香\\x（百九二）味苦辛，温。治痈疽恶疮，头疡白 ，风湿疥癣。酒煮糊丸，可治历节风痛， \n亦治妇人崩带。煎膏则活血生肌，排脓止痛。塞牙孔杀虫。敷刺入肉中自出。加铜末研掺，大治金 \n疮折伤。 \n\\x乳香\\x（百九三）味苦辛，性温，微热。辟邪恶诸气，治霍乱，通血脉，止大肠血痢疼痛，及妇 \n人气逆血滞，心腹作痛，消痈疽诸毒，托里护心，活血定痛，舒筋脉，疗折伤。煎膏止痛长肉。 \n\\x没药\\x（百九四）味苦，气平。能破血散血，消肿止痛。疗金疮杖疮，诸恶疮，痔漏痈肿。破宿 \n血瘕，及堕胎产 \n后血气作痛。凡治金刃跌坠，损伤筋骨，心腹血瘀作痛者，并宜研烂热酒调服，则推陈致新，无不 \n可愈。 \n\\x阿魏\\x（百九五）味苦辛，性热，有毒。其气辛臭，乃能辟夺臭气，逐瘟疫瘴疟，传尸鬼气恶气。 \n疗霍乱隔噎颓疝，心腹疼痛，杀诸小虫牙虫。破 积，消癖块，除蛊毒，及一切蕈菜牛羊鱼肉诸毒。 \n或散或丸，随意可服。 \n\\x樟脑\\x（百九六）味辛微苦，性热。善通关窍，破滞气。辟中恶邪气，治疥癣，杀虫除蠹，着鞋 \n中，去香港脚。烧烟熏衣筐席簟，除蚤虱壁虱。北方新生小猫极多跳蚤，用此拌面研匀掺擦之，则尽 \n落无遗，亦妙方也。 \n\\x龙脑\\x（百九七）即冰片。味微甘，大辛。敷用者，其凉如冰，而气雄力锐，性本非热，阳中有 \n阴也。善散气散血，散火散滞，通窍辟恶，逐心腹邪气，疗喉痹脑痛，鼻 齿痛，伤寒舌出，小儿 \n风痰，邪热急惊，痘疔黑陷。凡气壅不能开达者，咸宜佐使用之。亦通耳窍，散目热，去目中赤肤 \n翳障，逐三虫，消五痔，疗一切恶疮聚毒，下疳痔漏疼痛。亦治妇人气逆难产，研末少许，新汲水 \n服之则下。以热酒服之则能杀人。凡用此者，宜少而暂，多则走散真气，大能损人。 \n\\x血竭\\x（百九八）味甘咸微涩，性平。善破积血，止痛生肌。疗金疮折伤打损，血瘀疼痛，内伤 \n血逆，妇人血气凝滞，亦能生血补虚，俱可为末酒服，并治一切恶疮癣疥久不合口。然性能引脓， \n不宜多用。 \n\\x芦荟\\x（百九九）味大苦，性大寒。气味俱浓，能升能降。除风热烦闷，清肺胃郁火，凉血清肝 \n明目，治小儿风热急惊癫痫，五疳热毒，杀三虫，及痔漏热疮。军用杀疳蛔。吹鼻治脑疳鼻热鼻痒 \n鼻痔。研末敷虫牙。同甘草敷湿癣杀虫，出黄水极妙。 \n\\x干漆\\x（二百）味辛，性温，有毒。能疗绝伤，续筋骨，杀三虫，去蛔虫，削年深坚结之积滞， \n破日久凝聚之瘀血。用须炒熟入药，不尔损人肠胃。若外着其毒而生漆疮者，惟杉木汤、紫苏汤、 \n蟹汤浴之可解，或用香油调铁锈涂之。 \n\\x苏合油\\x（二百一）味甘辛，性温。能辟邪恶诸气，杀鬼魅蛊毒虫毒，疗癫痫温疟，止气逆疼痛。 \n亦通神明，可除梦魇。 \n\\x孩儿茶\\x（二百二）味苦微涩，性凉。能降火生津，清痰涎咳嗽，治口疮喉痹烦热，止消渴吐血 \n衄血，便血尿血，湿热痢血，及妇人崩淋，经血不止，小儿疳热、口疳热疮、湿烂诸疮，敛肌长肉， \n亦杀诸虫。 \n\n\n\n<目录>卷之四十九大集·本草正（下）\n\n<篇名>谷部\n\n属性：\\x麦芽\\x（二百三）味甘微咸，气温。善于化食和中，破冷气，消一切米面诸果食积，去心腹胀满， \n止霍乱，除烦热，消痰饮，破 结，宽肠下气。病久不食者，可借此谷气以开胃；元气中虚者， \n毋多用此以消肾。亦善催生落胎，单服二两，能消乳肿。其耗散血气如此，而脾胃虚弱、饮食不消 \n方中，每多用之何也？故妇有胎妊者，不宜多服。 \n\\x神面\\x（二百四）味甘，气平。炒黄入药。善助中焦土脏，健脾暖胃，消食下气，化滞调中，逐 \n痰积，破 瘕，运化水谷，除霍乱胀满呕吐。其气腐，故能除湿热；其性涩，故又止泻痢。疗女人 \n胎动因滞，治小儿腹坚因积。若妇人产后欲回乳者，炒研酒服二钱，日二即止，甚验。若闪挫腰痛 \n者，淬酒温服最良。 \n\\x白扁豆\\x（二百五）味甘，气温。炒香用之，补脾胃气虚，和呕吐霍乱，解河豚酒毒，止泻痢温 \n中，亦能清暑治消渴。欲用轻清缓补者，此为最当。 \n\\x薏仁\\x（二百六）味甘淡，气微凉。性微降而渗，故能去湿利水。以其去湿，故能利关节，除脚 \n气，治痿弱拘挛湿痹，消水肿疼痛，利小便热淋，亦杀蛔虫。以其微降，故亦治咳嗽唾脓，利膈开 \n胃。以其性凉，故能清热，止烦渴上气。但其功力甚缓，用为佐使宜倍。 \n\\x绿豆\\x（二百七）味甘，性凉。能清火清痰下气，解烦热，止消渴，安精神，补五脏阴气，去胃 \n火吐逆，及吐血衄血，尿血便血，湿热泻痢肿胀，利小水，疗丹毒风疹，皮肤燥涩，大便秘结，消 \n痈肿痘毒，汤火伤痛，解酒毒鸩毒，诸药食牛马金石毒，尤解砒霜大毒。或用囊作枕，大能明耳目， \n并治头风头痛。 \n\\x粟壳\\x（二百八）味微甘，性多涩。泡去筋膜，醋拌炒用，甚固大肠，久痢滑泻必用，须加甘补 \n同煎。久虚咳嗽劫药，欲用须辨虚实。脱肛遗精，惧所当用，湿热下痢，乃非所宜。 \n\\x麻仁\\x（二百九）即黄麻也，亦名大麻。味甘平，性滑利。能润心肺，滋五脏，利大肠风热结燥， \n行水气，通小便湿热，秘涩五淋，去积血，下气，除风湿顽痹，关节血燥拘挛，止消渴，通乳汁， \n产难催生，经脉阻滞。凡病多燥涩者宜之。若下元不固，及便溏阳痿，精滑多带者，皆所忌用。 \n\n\n\n<目录>卷之四十九大集·本草正（下）\n\n<篇名>果部\n\n属性：\\x艾实\\x（二百十）味甘，气平，入脾肾两脏。能健脾养阴止汤，治腰膝疼痛，强志益神，聪明耳 \n目，补肾固精，治小便不禁，遗精白浊带下，延年耐老。或散丸、或煮食皆妙。但其性缓，难收奇 \n效。 \n\\x杏仁\\x（二一一）味苦辛微甘，味浓于气，降中有升。有毒。入肺胃大肠经。其味辛，故能入肺 \n润肺，散风寒，止头痛，退寒热咳嗽，上气喘急，发表解邪，疗温病香港脚。其味苦，降性最疾，观 \n其澄水极速可知，故能定气逆上冲，消胸腹急满胀痛，解喉痹，消痰下气，除惊痫烦热，通大肠气 \n闭干结，亦杀狗毒。佐半夏、生姜，散风邪咳嗽；佐麻黄发汁，逐伤寒表邪；同门冬、乳酥煎膏， \n润肺治咳嗽极妙；同轻粉研匀油调，敷广疮肿毒最佳。尤杀诸虫牙虫，及头面 斑 。元气虚陷 \n者勿用，恐其沉降太泄。 \n\\x桃仁\\x（二一二）味苦辛微甘，气平，阴中有阳，入手足厥阴经。去皮尖用。善治瘀血血闭，血 \n结血燥，通血隔，破血症，杀三虫，润大便，逐郁滞，止鬼疰血逆疼痛膨胀，疗跌扑损伤。若血枯 \n经闭者，不可妄用。 \n\\x木瓜\\x（二一三）味酸，气温。用此者，用其酸敛，酸能走筋，敛能固脱。入脾肺肝肾四经，亦 \n善和胃。得木味之正，故尤专入肝，益筋走血，疗腰膝无力，香港脚引经所不可缺。气滞能和，气脱 \n能固。以能平胃，故除呕逆霍乱转筋，降痰去湿行水。以其酸收，故可敛肺禁痢，止烦满，止渴。 \n\\x陈皮\\x（二一四）味苦辛，性温散，气实痰滞必用。留白者，微甘而性缓；去白者，用辛而性速。 \n泻脾胃痰浊，肺 \n中滞气，消食开胃，利水通便，吞酸嗳腐，反胃 杂。KT 逆胀满堪除，呕吐恶心皆效。通达上下， \n解酒除虫，表里俱宜，痈疽亦用。尤消妇人乳痈，并解鱼肉诸毒。 \n\\x青皮\\x（二一五）味苦辛微酸，味浓，沉也，阴中之阳。苦能去滞，酸能入肝，又入少阳、三焦、 \n胆腑。削坚癖，除胁痛，解郁怒，劫疝疏肝，破滞气，宽胸消食。老弱虚羸，戒之勿用。 \n\\x槟榔\\x（二一六）味辛涩，微苦微甘，气微温。味浓气薄，降中有升，阴中阳也。能消宿食，解 \n酒毒，除痰癖，宣壅滞，温中快气。治腹胀积聚，心腹疼痛喘急，通关节，利九窍，逐五膈、奔豚、 \n膀胱诸气，杀三虫，除香港脚，疗诸疟瘴疠湿邪。《本草》言其治后重如马奔，此亦因其性温行滞而 \n然。若气虚下陷者，乃非所宜。又言其破气极速，较枳壳、青皮尤甚。若然，则广南之人，朝夕笑 \n噬而无伤，又岂破气极速者？总之，此物性温而辛，故能醒脾利气，味甘兼涩，故能固脾壮气，是 \n诚行中有留之剂。观《鹤林玉露》云∶饥能使之饱，饱能使之饥，醉能使之醒，醒能使之醉。于此 \n四句详之，可得其性矣。其服食之法∶小者气烈，俱以入药。广中人惟能用其大而扁者，以米泔水 \n浸而待用，每一枚切四片，每服一片；外用细锻石以水调如稀糊，亦预制待用。用时以蒌叶一片， \n抹锻石一二分，入槟榔一片，裹而嚼服。盖滨榔得锻石则滑而不涩，锻石、蒌叶得槟榔则甘而不辣。 \n服后必身面俱暖，微汗微醉，而胸腹豁然。善解吞酸，消宿食，辟岚瘴，化痰醒酒下气，健脾开胃 \n润肠，杀虫消胀，固大便，止泻痢。又，服法∶如无蒌叶，即以肉桂，或大茴香，或陈皮俱可代用， \n少抹锻石，夹而食之。然此三味之功，多在锻石、蒌叶，以其能燥脾温胃也，然必得槟榔为助， \n其功始见。此物理相成之妙，若有不可意测者。一、大约此物与烟性略同，但烟性峻勇，用以散表 \n逐寒，则烟胜于此；槟榔稍缓，用以和中暖胃，则此胜于烟。二者皆壮气辟邪之要药，故滇广中人 \n一日不可少也。又，习俗之异，在广西用老槟榔，滇中人用清嫩槟榔，广东人多在连壳腌槟榔，亦 \n各得其宜耳。 \n\\x乌梅\\x（二一七）味酸涩，性温平。下气，除烦热，止消渴吐逆，反胃霍乱，治虚劳骨蒸，解酒 \n毒，敛肺痈肺痿，咳 \n嗽喘急，消痈疽疮毒，喉痹乳蛾，涩肠止冷热泻痢，便血尿血，崩淋带浊，遣精梦泄，杀虫伏蛔，解 \n虫、鱼、马汗、硫黄毒。和紫苏煎汤，解伤寒时气瘴疟，大能作汗。取肉烧存性，研末，敷金疮恶 \n疮，去腐肉弩肉死肌，一夜立尽，亦奇方也。 \n\\x山楂\\x（二一八）味甘微酸，气平，其性善于消滞。用此者，用其气轻，故不甚耗真气。善消宿 \n食痰饮吞酸，去瘀血疼痛，行结滞，驱膨胀，润肠胃，去积块，亦祛颓疝。仍可健脾，小儿最宜。 \n亦发疮疹。妇人产后儿枕痛，恶露不尽者，煎汁入沙糖服之，立效。煮汁洗漆疮亦佳。肠滑者少用 \n之。 \n\\x甜瓜蒂\\x（二一九）一名苦丁香。味苦，性寒，有毒。阴中有阳，能升能降。其升则吐，善涌湿 \n热顽痰积饮，去风热头痛，癫痫喉痹，头目眩晕，胸膈胀满，并诸恶毒在上焦者，皆可除之。其降 \n则泻，善逐水湿痰饮，消浮肿水膨，杀蛊毒虫毒，凡积聚在下焦者，皆能下之。盖其性峻而急，不 \n从上出，即从下出也。若治鼻中 肉，不闻香臭，当同麝香、细辛为末，以绵裹塞鼻中，日一换之， \n当渐消缩。 \n\\x大腹皮\\x（二百二十）味微辛，性微温。主冷热邪气，下一切逆气滞气攻冲心腹大肠，消痰气吞 \n酸痞满，止霍乱，逐水气浮肿，香港脚瘴疟，及妇人胎气恶阻胀闷，并宜加姜盐同煎。凡用时，必须 \n酒洗炒过，恐其有鸩鸟毒也。 \n\\x吴茱萸\\x（二二一）味辛苦，气味俱浓，升少降多，有小毒。能助阳健脾，治胸膈停寒，胀满痞寒， \n化滞消食，除吞酸呕逆霍乱，心腹蓄冷，中恶绞痛，寒痰逆气，杀诸虫鬼魅邪疰，及下焦肝肾膀胱 \n寒疝，阴毒疼痛，止痛泻血痢，浓肠胃，去湿气肠风痔漏，香港脚水肿。然其性苦善降，若气陷而元 \n气虚者，当以甘补诸药制而用之。 \n\n\n\n<目录>卷之四十九大集·本草正（下）\n\n<篇名>菜部\n\n属性：\\x山药\\x（二二三）味微甘而淡，性微涩。所以能健脾补虚，涩精固肾，治诸虚百损，疗五劳七伤。 \n第其气轻性缓，非堪专任，故补脾肺必主参、术，补肾水必君茱、地，涩带浊须破故同研，固遗泄 \n仗菟丝相济诸凡固本丸 \n药，亦宜捣末为糊。总之性味柔弱，但可用为佐使。 \n\\x干姜\\x（二二三）味辛微苦，性温热。生者能散寒发汗，熟者能温中调脾。善通神明，去秽恶， \n通四肢关窍，开五脏六腑，消痰下气，除转筋霍乱，逐风湿冷痹，阴寒诸毒，寒痞胀满，腰腹疼痛， \n扑损瘀血，夜多小便。孙真人曰∶呕家圣药是生姜。故凡脾寒呕吐宜兼温散者，当以生姜煨熟用 \n之。若下元虚冷而为腹疼泻痢，专宜温补者，当以干姜炒黄用之。若产后虚热虚火盛而唾血痢血者， \n炒焦用之。若炒至黑炭，已失姜性矣，其亦有用以止血者，用其黑涩之性已耳。若阴盛隔阳，火不 \n归元，及阳虚不能摄血而为吐血衄血下血者，但宜炒熟留性用之，最为止血之要药。若阴虚内热多 \n汗者，皆忌用姜。 \n\\x大茴香\\x（二二四）味辛，气温，入心肾二脏。气味香甜，能升能降，最暖命门。改善逐膀胱寒 \n滞，疝气腰疼，亦能温胃止吐，调中止痛，除霍乱反胃，齿牙口疾，下气解毒，兼理寒湿香港脚，调 \n和诸馔，逐臭生香。 \n\\x小茴香\\x（二二五）气味略轻，治亦同前。但大茴性更暖，而此则稍温耳。 \n\\x白芥子\\x（二二六）味大辛，气温。善开滞消痰，疗咳嗽喘急，反胃呕吐，风毒流注，四肢疼痛， \n尤能祛辟冷气，解肌发汗，消痰癖疟痞，除胀满极速。因其味浓气轻，故开导虽速而不甚耗气。既 \n能除胁肋皮膜之痰，则他近处者不言可知。善调五脏，亦熨散恶气，若肿毒乳癖痰核初起，研末用 \n醋或水调敷甚效。 \n\\x萝卜子\\x（二二七）味大辛，气温，气味俱浓，降也。善于破气消痰，定喘除胀，利大小便，有 \n推墙倒壁之功。研水搀薄饮之，立吐风痰尽出。胃有气食停滞致成鼓胀者，非此不除。同醋研敷， \n大消肿毒。中气不足，切忌妄用。 \n\\x葱\\x（二二八）味辛，性温。善散风寒邪气，通关节，开腠理，主伤寒寒热，天行时疾头痛，筋骨 \n酸疼，行滞气，除霍乱转筋，奔豚香港脚，阴邪寒毒，阳气脱陷，心腹疼痛，及虫积气积，饮食毒百 \n药毒，利大小便，下痢下血，小儿盘肠内钓，妇人溺血，通乳汁，散乳痈，消痈疽肿毒。捣罨伤寒 \n结胸，及金疮折伤血瘀血出，疼痛不止。涂 犬，亦制蚯蚓毒。 \n\\x蒜\\x（二二九）味辛，性温，有小毒。善理中温胃，行滞气，辟肥腻，开胃进食，消寒气寒痰， \n面积食积，鱼肉诸积，邪痹膨胀，宿滞不安，杀溪毒水毒，蛊毒蛇虫毒。捣烂可灸痈疽，涂疔肿， \n敷蛇虫沙风毒甚良。 \n\\x韭莱\\x（二百三十）味辛甘微涩，性温。善温中，安五脏，和胃气，健脾气，除浊气。开胃进食， \n祛心腹病冷 癖，隔噎滞气，止消渴、泻痢脓血，腹中冷痛，壮肾气，暖腰膝，疗泄精带浊。俱宜 \n常煮食之，大能益人。若欲消胃脘瘀血作痛，及中风痰盛失音，上气喘急，或中饮食药毒，或暴见 \n吐血衄血尿血，打扑瘀血，妇人经滞血逆，上冲心腹，或被狂犬蛇虫恶毒，势在危急者，俱宜捣生 \n韭汁服之，或从吐出，或从内消，皆得愈也。或用煎汤熏产妇血晕，亦可洗肠痔脱肛。 \n\\x韭子\\x（二三一）味辛，性温，阴中阳也。宜炒黄用之。主梦泄遗精尿血，暖腰膝，壮阳道，治 \n鬼交，补肝肾命门，止小便频数遗尿，及妇人白淫白带，阴寒小腹疼痛。 \n\\x百含\\x（二三二）味微甘淡，气平功缓。以其甘缓，故能补益气血，润肺除嗽，定魄安心，逐惊 \n止悸，缓时疫咳逆，解乳痈喉痹，兼治痈疽，亦解蛊毒，润大小便，消气逆浮肿。仲景用之以治百 \n合证者，盖欲藉其平缓不峻，以收失散之缓功耳。虚劳之嗽，用之颇宜。 \n\\x蒲公英\\x（二三三）即黄花地丁。味微苦，气平。独茎一花者是，茎有极者非。入阳明、太阴、 \n少阳、厥阴经。同忍冬煎汁，少加酒服，溃坚消肿，散结核瘰 最佳，破滞气，解食毒，出毒刺俱 \n妙。若妇人乳痈，用水酒煮饮，以渣封之立消。 \n\n\n\n<目录>卷之四十九大集·本草正（下）\n\n<篇名>金石部\n\n属性：\\x金箔\\x（二三四）味辛平，性寒，生者有毒。气沉质重，降也，阴也。能镇心神，降邪火，坠痰 \n涎，疗风热上壅，吐血衄血，神魂飞荡，狂邪躁扰，及小儿惊风癫痫，痰滞心窍，上气咳喘，安魂 \n魄，定心志。凡邪盛于上，宜降宜清者，皆所当用。若阳虚气陷，滑泄清寒音，具当辟之。 \n\\x水银\\x（二三五）性辛寒，有大毒。能利水道，去热毒。同黑铅结砂，则镇坠痰涎；同硫黄结砂， \n则疗劫危疾。极善堕胎，杀诸虫及疥癣癞疮，凡有虫者皆宜之。亦善走经络，透骨髓，逐杨梅疯毒。 \n其他内证，不宜轻用，头疮亦不可用，恐入经洛，必缓筋骨，百药不治也。李时珍曰∶水银乃至阴 \n之精，禀沉着之性，得凡火 炼，则飞腾灵变，得人气熏蒸，则入骨钻筋，绝阳蚀脑，阴毒之物， \n无似之者。而《大明》言其无毒《本经》言其久服神仙，甄权言其还丹元母，《抱朴子》以为长生之 \n药，六朝以下，贪生者服食，致成废笃而丧厥躯，不知若干人矣。方士固不足道，本草其可妄言哉！ \n水银但不可服食尔，而其治病之功，不可掩也。 \n\\x轻粉\\x（二三六）味微辛，性温燥，有大毒。升也，阳也。治痰涎积聚，消水肿鼓胀，直达病所。 \n尤治瘰 诸毒仓，去腐肉，生新肉，杀疮癣疥虫，及鼻上酒 ，风疮瘙痒。然轻粉乃水银加盐矾升 \n炼而成，其以金火之性，燥烈流走，直达骨髓，故善损齿牙。虽善劫痰涎水湿疮毒，涎从齿缝而出， \n邪得劫而暂开，病亦随愈，然用不得法，则金毒窜入经络，留而不出，而伤筋败骨，以致筋挛骨痛， \n痈疮疳漏，遂成废痼，其害无穷。尝见丹家升炼者，若稍失固济，则虽以铁石为鼎，亦必爆裂，而 \n矧以人之脏腑血气乎。陈文中曰∶轻粉下痰而损心气，小儿不可轻用，伤脾败阳，必变他证，初生 \n者尤宜慎之。 \n\\x铜青\\x（二三七）即铜绿。此铜之精华，惟醋制者良， 制者毒也。味酸涩，性收敛。善治风眼 \n烂弦流泪，合金疮，止血，明目，去肤赤 肉，治恶疮、口鼻疳疮。若治走马牙疳，宜同滑石、杏 \n仁等分为末，擦之立愈。 \n\\x朱砂\\x（二三八）味微甘，性寒，有大毒。通禀五行之气，其色属火也，其液属水也，其体属土 \n也，其气属木也，其入属金也，故能通五脏。其入心可以安神而走血脉，入肺可以降气而走皮，入 \n脾可逐痰涎而走肌肉，入肝可行血滞而走筋膜，人肾可逐水邪而走骨髓，或上或下，无处不到。故 \n可以镇心逐痰，祛邪降火，治惊痫，杀虫毒，祛蛊毒鬼魅中恶，及疮疡疥癣之属。但其体重性急， \n善走善降，变化莫测，用治有余，乃其所长，用补不足，及长生久视之说，则皆谬妄不可信也。若 \n同参、 、归、术兼朱砂以治小儿，亦可取效。此 \n必其虚中挟实者乃宜之，否则不可概用。 \n\\x银朱\\x（二三九）乃水银同硫黄升炼而成。味辛，温，有毒。破积滞，劫痰涎，善疗疮癣恶疮， \n杀虫毒蚤虱。惟烧烟熏之，或以枣肉拌烟擦之，其功尤捷。 \n\\x蚕砂\\x（二百四十）味甘，性温。主五脏百病，养神志，安魂魄，通血脉，明耳目，调和五脏。 \n主上盛下虚，痰涎壅盛，头旋吐逆，霍乱反胃，心腹冷痛。升降阴阳，既济水火，久服通神明，杀 \n精魅恶鬼，小儿惊吐，其效如神。研末，糯米糊为丸，枣汤服，最为镇坠神丹也。或以阴阳水送下 \n尤妙。按胡演《丹药秘诀》云，升灵砂法，用新锅安逍遥炉上，以蜜揩锅底，文火下烧，入硫黄 \n二两，熔化，投水银半斤，以铁匙急搅，作青砂头。如有焰起，喷醋解之。待汞不见星，取出细研， \n盛入水火鼎内，盐泥固侪，下以自然火升之，干水十二盏为度，取出如束针纹者，成矣。 \n\\x硫黄\\x（二四一）味苦微酸，性热，有毒。疗心腹冷积冷痛霍乱，咳逆上气，及冷风顽痹寒热， \n腰肾久冷，脚膝疼痛，虚寒久痢滑泄。壮阳道，补命门不足，阳气暴绝，妇人血结，小儿慢惊，尤 \n善杀虫除疥癣恶疮。老人风秘，用宜炼服。亦治阴证伤寒，厥逆烦躁，腹痛脉伏将危者，以硫黄为 \n末，艾汤调服二三钱，即可得睡，汗出而愈。 \n\\x雄黄\\x（二四二）味苦甘辛，性温，有毒。消痰涎，治癫痫岚瘴疟疾寒热，伏暑泻痢，酒癖，头 \n风眩晕。化瘀血。杀精物鬼疰，蛊毒邪气，中恶腹痛，及蛇虺百虫兽毒，疥癞疳虫 疮。去鼻中 \n肉，痈疽腐肉，并鼠屡广疮疽痔等毒。欲逐毒蛇，无如烧烟熏之，其畏遗尤速。 \n\\x自然铜\\x（二四三）味辛平，性凉。能疗折伤，散瘀血，续筋骨，排脓止疼痛，亦镇心神，安惊 \n悸。宜研细水飞用，或以酒磨服。然性多燥烈，虽其接骨之功不可泯，而绝无滋补之益，故用不可 \n多，亦不可专任也。 \n\\x黄丹\\x（二四四）味辛，微咸微涩。性重而收，大能燥湿，故能镇心安神，坠痰降火。治雇乱吐 \n逆，咳嗽吐血，镇惊 \n痫癫狂客忤，除热下气，止疟止痢，禁小便，解热毒，杀诸虫毒，治金疮火疮湿烂，诸疮血溢，止 \n痛生肌长肉，收阴汗，解狐臭，亦去翳障明目。 \n\\x白矾\\x（二四五）味酸涩，性凉，有小毒。所用有四∶其味酸苦，可以涌泄，故能吐下痰涎，治 \n癫痫黄胆。其性收涩，可固脱滑，故能治崩淋带下，肠风下血，脱肛阴挺，敛金疮止血，烧枯用之 \n，能止牙缝出血，辟狐腋气，收阴汗脚汗。其性燥，可治湿邪，故能止泻痢，敛浮肿，汤洗烂弦风 \n眼。其性毒，大能解毒定痛，故可疗痈疽疔肿，鼻 肉，喉痹瘰 ，恶疮疥癣，去腐肉，生新肉， \n及虎犬蛇虫蛊毒。或丸或散，或生或枯，皆有奇效。 \n\\x石脂\\x（二四六）味甘涩，性温平。脂有五色，而今之入药者，惟赤白二种，乃手足阳明、足厥 \n阴、少阴药也。其味甘而温，故能益气调中，其性涩而重，故能收湿固下。调中则可疗虚烦惊悸， \n止吐血衄血，壮筋骨，浓肠胃，除水湿黄胆，痈肿疮毒，排脓长肉，止血生肌之类是也。固下则可 \n治梦泄遗精，肠风泻痢，血崩带浊，固大肠，收脱肛、痔漏阴疮之类是也。又治产难胞衣不出。东 \n垣曰∶胞衣不出，惟涩剂可以下之，即此是也。然脂有五种，虽在《本经》言各随五色补五脏，又 \n云白入气分，赤入血分。第五脂之性味略同，似亦不必强分者。且其性粘如膏，故用固炉鼎甚良。 \n\\x炉甘石\\x（二四七）味甘涩，性温。能止血消肿毒，生肌敛疮口，去目中翳膜赤肿，收湿烂。同 \n龙脑点，治目中一切诸病。宜用片子炉甘，其色莹白，经火 而松腻味涩者为上。制宜炭火 红， \n童便淬七次，研粉，水飞过，晒用。若 后坚硬，不松不腻者，不堪也。 \n\\x蓬砂\\x（二四八）味咸微甘，阴也，降也。消痰涎，止咳嗽，解喉痹，生津液，除上焦湿热噎膈， \n瘕瘀血，退眼目肿痛翳障，口齿诸病，骨哽、恶疮。或为散丸，或噙化咽津俱可。 \n\\x水粉\\x（二四九）即官粉，亦名胡粉。味辛，性寒，有毒。善杀虫堕胎，治痈疽疮毒，湿烂诸疮， \n下疳 溃不收，亦治疥癣狐臭。黑须发。虽亦能坠痰消食，然惟外证所宜，而内伤诸病，似亦不宜 \n用之。 \n\\x密陀僧\\x（二百五十）味咸平，有小毒。能镇心神，消痰涎，治惊痫咳嗽，呕逆反胃，疟疾下痢， \n止血杀虫，消积聚，治诸疮肿毒，鼻 面 汗斑；金疮五痔，辟孤臭，收阴汗香港脚。 \n\\x石宝\\x（二五一）味甘辛，气大寒。气味俱薄，体重能沉，气轻能升，阴中有阳。欲其缓者 用， \n欲其速者生用。用此者，用其寒散清肃，善祛肺胃三焦之火，而尤为阳明经之要药。辛能出汗解肌， \n最逐温暑热证而除头痛；甘能缓脾清气，极能生津止渴而却热烦。邪火盛者不食，胃火盛者多食， \n皆其所长。阳明实热牙疼，太阴火盛痰喘，及阳狂热结热毒，发斑发黄，火载血上，大吐大呕，大 \n便热秘等证，皆当速用。胃虚弱者忌服，阴虚热者禁尝，若误用之，则败阳作泻，必反害人。 \n\\x滑石\\x（二五二）味微甘，气寒，性沉滑，降中有升。入膀胱、大肠经。能清三焦表里之火，利 \n六腑之涩结，分水道，逐凝血，通九窍，行津液，止烦渴，除积滞，实大肠，治泻痢淋秘白浊，疗 \n黄胆水肿香港脚，吐血衄血金疮出血，诸湿烂疮肿痛。通乳亦佳，堕胎亦捷。 \n\\x青礞石\\x（二五三）味微甘微咸，其性下行，降也，阴也，乃肝脾之药。此药重坠，制以硝石， \n其性更利。故能消宿食症积顽痰，治惊痫咳嗽喘急。《宝鉴》言礞石为治痰利惊之圣药，若吐痰在 \n水上，以石末掺之，痰即随水而下，则其沉坠之性可知。杨土瀛谓其功能利痰，然性非胃家所好。 \n而王隐君谓痰为百病母，不论虚实寒热概用滚痰丸，通治百病，岂理也哉？是以实痰坚积，乃其所 \n宜。燃久病痰多者，必因脾虚。人但知滚痰丸可以治痰，而不知虚痰服此，则百无一生矣。 \n\\x朴硝\\x（二五四）味苦咸辛，气寒。阴也，降也，有毒。其性峻速。咸能软坚，推逐陈积，化金 \n石药毒，去六腑壅滞胀急，大小便不通，破瘀血坚症实痰，却湿热疫痢，伤寒胀闭热狂，消痈肿排 \n脓，凡属各经实热，悉可泻除。孕妇忌用，最易堕胎；虚损误吞，伤生反掌。 \n\\x玄明粉\\x（二五五）味辛微甘，性冷，沉也，阴也。降心火，祛胃热，消痰涎，平伤寒实热狂躁， \n去胸膈脏腑宿滞 瘕，通大便秘结，阴火疼痛，亦消痈疽肿毒。 \n\\x海石\\x（二五六）味咸，性微寒，阳中阴也。善降火下气，消食，消热痰，化老痰，除瘿瘤结核， \n解热渴热淋，止痰嗽喘急，消积块，软坚症，利水湿、疝气，亦消疮肿。 \n\\x花蕊石\\x（二五七）此药色如硫黄，黄石中间有淡白点，故名也。李时珍曰∶此药旧无气味，今 \n尝试其气平，其味涩而酸，盖厥阴经血分药也。其功专于止血，能使血化为水，酸以收之也。若治 \n金疮出血，则不必制，但刮末敷之则合，仍不作脓，及治一切损伤失血。又疗妇人恶血血晕，下死 \n胎，落胞衣，去恶血，血去而胎胞自落也。凡入丸散，须用罐固济，火 过，研细，水飞用之。 \n\\x代赭石\\x（二五八）味微甘，性凉而降，血分药也。能下气降痰清火，除胸腹邪毒，杀鬼物精气， \n止反胃吐血衄血，血痹血痢，血中邪热，大人小儿惊痫，狂热入脏，肠风痔漏，脱精遗尿，及妇人 \n赤白带下，难产胞衣不用，月经不止，俱可为散调服。亦冶金疮，生肌长肉。 \n\\x 砂\\x（二五九）味咸苦大辛，性大热，有毒。善消恶肉腐肉生肌，敷金疮生肉，去目翳弩肉， \n除痣魇疣赘，亦善杀虫毒，水调涂之，或研末掺之立愈。《本草》言其消瘀血宿食，破结气，止反 \n胃，肉食饱胀，暖子官，大益阳事。但此物性热大毒，能化五金八石，人之脏腑岂能堪此？故用以 \n治外则可，用以服食则不宜也。若中其毒，惟生绿豆研汁饮一二升，乃可解之。 \n\\x青盐\\x（二百六十）味咸微甘，性凉。能降火消痰明目，除目痛，益肾气，除五脏症结，心腹积 \n聚，吐血尿血，齿牙疼痛出血，杀毒虫，除疥癣诸虫，及斑蝥莞青诸毒。此盐不经火炼而成，其味 \n稍甘，虽性与大盐略同，而滋益之功则胜之。 \n\\x锻石\\x（二六一）味辛，温，有毒。能止水泻血痢，收白带白淫，可倍加茯苓为丸服之。此外如 \n散血定痛，傅痈毒，消结核瘦瘤，恶疮腐肉，白癜 斑 肉，收脱肛阴挺，杀痔漏诸虫，止金疮血 \n出，生肌长肉，或为末可掺，或用醋调敷俱妙。能解酒酸，亦解酒毒。 \n\n\n\n<目录>卷之四十九大集·本草正（下）\n\n<篇名>禽兽部\n\n属性：\\x鸡血\\x（二六二）味咸，性平。主疗痿痹中恶腹痛，解丹毒蛊毒虫毒盐卤毒，及小儿惊风便结， \n亦能下乳，俱宜以热血服之。若马咬人伤，宜以热血浸之。鸡冠血治白癜风，经络风热。涂囟颊， \n治口 不正。卒灌之，治缢死欲绝，及小儿卒惊客忤。和酒服，发痘最佳。涂诸疮癣蜈蚣蜘蛛马啮 \n等毒。若有百虫入耳，宜用热血滴之。 \n\\x鸭血\\x（二六三）味咸微凉，善解诸毒。凡中金银丹石砒霜盐卤毒者，俱宜服此解之。若野葛毒 \n杀人至死，热饮之，入口即解。若溺水死者，灌之即活。蚯蚓咬疮，涂之即愈。 \n\\x虎骨\\x（二六四）味微辛，气平。主百邪恶气，杀鬼精，心腹诸痛，止惊悸，壮筋骨，治肢体毒 \n风拘挛，走注疼痛，辟伤寒温疟，及恶疮鼠痿，犬咬诸毒。头骨作枕，辟恶梦魇魅，置户上，辟鬼 \n祟。寇宗 曰∶风从虎者，风木也，虎金也，木受金制，安得弗从，故可治风病挛急走注，风毒癫 \n厥惊痫诸病。李时珍曰∶虎骨通可用。 \n凡辟邪疗惊痫头风，温疟疮疽，当用头骨；治手足诸风，当用胫骨；治腰背诸风，当用脊骨， \n亦各从其类也。 \n吴球曰∶虎之一身筋节气力皆出前足，故以胫骨为胜。 \n\\x象牙\\x（二六五）味甘，气凉。能清心肾之火，可疗惊悸风狂，骨蒸痰热，鬼精邪气，痈毒诸疮， \n并宜生屑入药煮服。若诸物鲠刺喉中，宜磨水饮之。竹木刺入肌肉，宜刮牙屑和水敷之即出。 \n\\x鹿角胶\\x（二六六）味甘咸，气温。大补虚羸，益血气，填精髓，壮筋骨，长肌肉，悦颜色，延 \n年益寿。疗吐血下血，尿精尿血，及妇人崩淋，赤白带浊，血虚无子，止痛安胎，亦治折跌损伤， \n疮疡肿毒。善助阴中之阳，最为补阴要药。 \n\\x雇茸\\x（二六七）味甘咸，气温。破开涂酥炙黄脆入药。益元气，填真阴，扶衰羸瘦弱，善助精 \n血，尤强筋骨，坚齿牙，益神志。治耳聋目暗，头脑眩运。补腰肾虚冷，脚膝无力，夜梦鬼交，遗 \n精滑泄，小便频数，虚痢尿血， \n及妇人崩中漏血，赤白带下，道家云∶惟有斑龙顶上珠，能补玉堂关下血者，即此是也。若得嫩而 \n肥大如紫茄者，较之鹿角胶，其功力为倍倍。 \n\\x犀角\\x（二六八）味苦辛微甘，气寒。气味俱轻，升也，阳也。其性灵通，长于走散，较诸角为 \n甚。药用黑色，功力在尖。专人阳明，清胃火、亦施他脏。凉心定神镇惊，泻肝明目，能解大热， \n散风毒阳毒，瘟疫热烦。磨汁治吐血衄血下血，及伤寒蓄血，发狂发黄，发斑谵语，痘疮稠密，内 \n热黑陷，或不结痂，亦散疮毒痈疡，脓血肿痛，杀妖狐精魅鬼疰，百毒蛊毒，钩吻、鸩羽、蛇毒， \n辟溪瘴山岚恶气。其性升而善散，故治伤寒热毒闭表，烦热昏闷而汗不得解者，磨尖搀入药中，取 \n汗速如附应。仲景云∶如无犀角，以升麻代之者，正以此两物俱入阳明，功皆升散。今人莫得其解， \n每致疑词，是但知犀角之解心热，而不知犀角之能升散，尤峻速于升麻也。倘中气虚弱，脉细无神， \n及痘疮血虚，真阴不足等证，凡畏汗畏寒畏散者，乃所当忌。或必不得已，宜兼补剂用之。 \n\\x羚羊角\\x（二六九）味咸，性寒。羊本火畜，而此则属木，善走少阳、厥阴二经。故能清肝定风， \n行血行气，辟鬼疰邪毒，安魂魄，定惊狂、祛魇寐，疗伤寒邪热，一切邪毒，中恶毒风，卒死昏不 \n知人，及妇人子痫强痉，小儿惊悸烦闷，痰火不清。俱宜为末，蜜水调服，或烧脆研末，酒调服之。 \n若治肿毒恶疮，磨水涂之亦可。 \n\\x牛黄\\x（二百七十）味苦辛，性凉，气平，有小毒。忌常山。入心肺肝经。能清心退热，化痰凉 \n惊，通关窍，开结滞。 \n治小儿惊痫客忤，热痰口噤，大人癫狂痰壅，中风发痉，辟邪魅中恶，天行疫疾，安魂定魄， \n清神志不宁，聪耳目壅闭，疗痘疮紫色，痰盛躁狂。亦能堕胎，孕妇少用。 \n\\x阿胶\\x（二七一）味甘微辛，气平，微温。气味颇浓，阳中有阴。制用蛤粉妙珠，入肺肝肾三经。 \n其气温，故能扶劳伤，益中气。其性降，故能化痰清肺，治肺痈肺痿，咳唾脓血，止嗽定喘。其性 \n养血，故能止吐血衄血，便血尿血，肠风下痢，及妇人崩中带浊血淋，经脉不调。其味甘缓，故能 \n安胎固漏，养血滋肾，实腠理，止 \n虚汗，托补痈疽肿毒。用惟松脆气清者为佳，坚硬臭劣者不美。 \n\\x熊胆\\x（二七二）味苦，性寒。能退热清心，疗时气黄胆，平肝明目，去翳障，杀蛔蛲，牙虫风 \n痛，及小儿热疳热痰，惊痫螈 ，疳 热痢，俱宜以竹沥化两豆粒许服之，甚良。亦治鼻疮热疮， \n痔漏肿痛，以汤化涂之，少加冰片尤效。欲辨其真，惟取一粟许，置水面，如线而下一道不散者是 \n也。且凡是诸胆，皆能水面辟尘，惟此尤速，乃亦可辨。 \n\\x麝香\\x（二七三）味苦辛，性温。能开诸窍，通经络，透肌骨，解酒毒，吐风痰，消积聚 瘕， \n散诸恶浊气，除心腹暴痛胀急，杀鬼物邪气魇寐，脏腑虫积，蛇虫毒、蛊毒、瘴毒、沙虱毒，及妇 \n人难产，尤善堕胎。用热水研服一粒，治小儿惊痫客忤，镇心安神。疗鼻塞不闻香臭，目疾可去翳 \n膜，除一切恶疮，痔漏肿痛，脓水腐肉，面 斑疹。凡气滞为病者，俱宜用之。若鼠咬虫咬成疮， \n但以麝香封之则愈。欲辨真假，但置些须于火炭上，有油滚出而成焦黑炭者，肉类也，此即香之本 \n体。若燃火而化白灰者，木类也，是即假搀。 \n\n\n\n<目录>卷之四十九大集·本草正（下）\n\n<篇名>虫鱼部\n\n属性：\\x龙骨\\x（二七四）味甘，平，性收涩。其气入肝肾，故能安神志，定魂魄，镇惊悸，涩肠胃，逐 \n邪气，除夜梦鬼交，吐血衄血，遗精梦泄，收虚汗，止泻痢，缩小便，禁肠风下血尿血，虚滑脱肛 \n，女子崩淋带浊，失血漏胎，小儿风热惊痫。亦疗肠痈脏毒，内疽阴蚀，敛脓敛疮，生肌长肉，涩 \n可去脱，即此属也。制须酒煮焙干，或用水飞过，同黑豆蒸熟晒干用之。 \n\\x海螵蛸\\x（二七五）即乌贼鱼骨味咸，性微温，足厥阴、少阴肝肾药也。咸走血，故专治血病，疗 \n妇人经枯血闭，血崩血淋，赤白带浊，血 气瘕，吐血下血，脐腹疼痛，阴蚀疮肿，亦治痰疟，消 \n瘿气，及丈夫阴中肿痛，益精固精，令人有子，小儿下痢脓血，亦杀诸虫，俱可研末饮服。尤治眼 \n中热泪，磨翳去障，并宜研末和蜜点之。为末可敷小儿疳疮痘疮，臭烂脓湿，下疳等疮，跌打出血， \n汤火诸疮。烧灰存性酒服，治妇人阴户嫁 \n痛。同鸡子黄，涂小儿童舌鹅口。同蒲黄末，敷舌肿出血如泉。同槐花末吹鼻，止衄血。同麝香吹 \n耳，治KT 耳耳聋。乌贼鱼善补益精气，尤治妇人血枯经闭。 \n\\x牡蛎\\x（二七六）味微咸微涩，气平。用此者，用其涩能固敛，咸能软坚。专入少阴肾脏，随药 \n亦走诸经。能解伤寒温疟寒热往来，消瘀血，化老痰，去烦热，止惊痫心脾气痛，解喉痹咳嗽，疝 \n瘕积块，痢下赤白，涩肠止便，禁鬼交遗沥，止滑精带下，及妇人崩中带漏，小儿风痰虚汗。同熟 \n地，固精气，禁遗尿。同麻黄根，敛阴汗。同杜仲，止盗汗。同白术，燥脾利湿。同大黄，善消痈 \n肿。同柴胡，治胁下硬痛。同天花茶，消上焦瘿瘤瘰 结核。 \n\\x穿山甲\\x（二七七）味咸平，性微寒。能通经络，达腠理，除山岚瘴气疟疾，风痹强直疼痛，疗 \n小儿五邪惊啼，妇人鬼魅悲泣，下乳汁，消痈肿，排脓血，除疮疥痔漏，通窍杀虫。佐补药行经， \n善发痘疮。或炮焦投入煎剂，或烧灰存性，酒服方寸匕。亦可用傅恶疮。 \n\\x青鱼胆\\x（二七八）味苦，性寒。其色青，故入肝胆二经。能消赤目肿痛，点暗目，可吐喉痹痰 \n涎，涂热疮恶疮，亦消鱼骨之鲠。 \n\\x白花蛇\\x（二七九）即蕲蛇也。味甘咸，性温，有毒。诸蛇鼻俱向下，惟此蛇鼻向上，而龙头虎 \n口，黑质白花，胁有方胜纹二十四个，口有四长牙，尾上有一佛指甲者是。用宜去头尾各三寸，以 \n防其毒。春秋酒浸三宿，夏一宿，冬五宿，火炙，去尽皮骨，取肉焙干，密封藏之，久亦不坏。诸 \n蛇之性皆窜，而此蛇尤速，故善于治风，能透骨髓，走脏腑，彻肌肤，无所不到。疗中风湿痹，骨 \n节疼痛，手足拘挛，不能行立，暴风瘙痒，破伤风，大风癞癣，及小儿惊风搐搦，瘰 杨梅，风毒 \n恶疮，俱为要药。凡服蛇酒药者，切忌见风。 \n\\x珍珠\\x（二百八十）味微甘微咸。能镇心明目，去翳磨障。涂面可除 斑，令人润泽好颜色。亦 \n除小儿惊热，安魂魄。为末可敷痘疔痘毒。 \n\\x龟板\\x（二八一）味微甘微咸，性微寒，阴也。能治痰疟，破症坚，祛湿痹伤寒劳投，骨中寒热， \n消五痔阴蚀诸疮。 \n下甲能补阴血，清阴火，续筋骨，退劳热，疗腰脚酸痛，去瘀血，止血痢漏下赤白，利产难，消痈毒。 \n烧灰可敷小儿头疮难燥，妇人阴疮， 疮，亦治脱肛，龟板膏，功用亦同龟板，而性味浓浓，尤属 \n纯阴。能退孤阳阴虚劳热，阴火上炎。吐血衄血，肺热咳喘，消渴烦扰，热汗惊悸，谵妄狂躁之要 \n药。然性禀阴寒，善消阳气，凡阳虚假热，及脾胃命门虚寒等证，皆切忌之，毋混用也。若误用， \n久之则必致败脾妨食之患。 \n\\x僵蚕\\x（二八二）味辛咸，性温，有小毒。辛能散，咸能降，毒能攻毒。轻浮而升，阳中有阴。 \n故能散风痰，去头风，消结核瘰 ，辟痰疟，破症坚，消散风热喉痹危证，尤治小儿风痰急惊客忤， \n发痘疮，攻痘毒，止夜啼，杀三虫，妇人乳汁不通，崩中带下。为末可敷丹毒疔肿，拔根极效。灭 \n头面 斑，及诸疮瘢痕，金疮痔 ，小儿疳蚀，牙龈溃烂，重舌木舌，及大人风虫牙痛，皮肤风疹 \n瘙痒。 \n\\x蟾蜍\\x（二八三）俗名癞虾蟆。眉间有两囊，遍身有颗磊，其中俱有蟾酥，行极迟缓，不能跳跃， \n亦不解鸣者是也。此物受土气之精，上应月魄，赋性灵异，穴土食虫，能制蜈蚣。入足阳明胃经。 \n消癖气积聚，破坚症肿胀，治五疳八痢、及小儿劳瘦疳热，杀疳虫，消痈肿鼠 ，阴疽恶疮。若治 \n破伤风，宜同花椒剁烂，入酒煮熟饮之，通身汗出即愈。亦解 犬毒。烧灰油调，敷有虫诸恶顽疮， \n极效。又治瘟毒发斑危剧者，去肠生捣一二枚，绞汁饮之，无不即瘥，或烧灰汤送亦良。 \n\\x蟾酥\\x 味辛麻，性热，有毒。主治发背痈疽疔肿一切恶毒。若治风虫牙痛，及齿缝出血，以纸捻 \n醮少许点齿缝中，按之即止。 \n\\x水蛭\\x（二八四）味咸苦，性微寒，有毒。能逐恶血瘀血、破血症积聚，通经闭，和水道，堕胎。 \n咂赤白游疹，痈疽肿毒，及折伤跌扑瘀血不散。制用之法，当取田间啮人腹中有血者佳。须晒干细 \n锉，以微火炒黄熟方可用，或以冬收猪脂煎令焦黄用之亦可。不尔入腹则活，最能生子害人。若受 \n其害，惟以田泥水或黄土水饮数升，则必尽下，盖此物得土气即随土而走也。或以牛羊热血二一升， \n同猪脂饮之亦下也。 \n\\x鳖甲\\x（二八五）味咸，气平，此肝脾肾血分药也。能消 瘕坚积，疗温疟，除骨节间血虚劳热， \n妇人血症恶血，漏下五色，经脉不通，治产难，能堕胎，及产后寒热阴脱，小儿惊痫，斑痘烦喘， \n亦消疮肿肠痈，扑损瘀血，敛溃毒，去阴蚀痔漏恶肉。然须取活鳖大者，去肉，用醋煮干，炙燥用 \n之。若诸煮熟肋骨露出者不堪用。 \n\\x蜈蚣\\x（二八六）一名即蛆，赤足者良。味辛，温，有毒。能啖诸蛇，杀诸蛇虫鱼鬼疰诸毒，去 \n三虫，攻瘰 便毒，痔 丹毒，亦疗小儿惊风脐风，丹毒秃疮。然此虫性毒，故能攻毒，不宜轻用。 \n若入药饵，须去头足，以火炙熟用之。 \n\\x蝉蜕\\x（二八七）味微甘微咸，性微凉。此物饮风吸露，气极清虚，故能疗风热之证，亦善脱化， \n故可疗痘疮壅滞，起发不快。凡小儿惊痫，壮热烦渴，天吊口噤，惊哭夜啼，及风热目昏翳障，疔 \n肿疮毒，风疹痒痛，破伤风之类，俱宜以水煎服。或为末，以井花水调服一钱，可治喑哑之病。 \n\\x斑蝥\\x（二八八）味辛，性热，有大毒、能攻鼠 瘰 疮疽，破血积疝瘕，堕胎元，解疔毒、 \n犬毒、沙虱蛊母、轻粉毒，亦傅恶疮，去死肌败肉。制用之法，须去翅足，同糯米炒熟，然后可用。 \n或同麸炒，或同醋煮皆可。若中其毒，惟黑豆、绿豆汁、靛汁、黄连、浓茶、葱汁可以解之。 \n\\x蜂房\\x（二八九）味微甘微咸，有毒。疗蜂毒肿毒。合乱发、蛇蜕烧灰，以酒服二方寸匕，治恶 \n疽附骨疽疔肿诸毒，亦治赤白痢，遗尿失禁，阴痿。煎水可洗狐尿疮、乳痈、蜂螫恶疮，及热病后 \n毒瓦斯冲目。漱齿牙，止风虫牙痛。炙研，和猪脂，涂瘰 成 。 \n\\x五灵脂\\x（二百九十）味苦，气辛，善走厥阴，乃血中之气药也。大能行血行气，逐瘀止痛，凡 \n男子女人有血中气逆而腹胁刺痛，或女人经水不通，产后血滞，男子疝气，肠风血痢，冷气恶气， \n心腹诸痛，身体血痹，胁肋筋骨疼痛，其效甚捷。若女人血崩，经水过多，赤带不止，宜半炒半 \n生，酒调服之。亦治小儿气逆癫痫，杀虫毒，解药毒，行气极速。但此物气味俱浓，辛膻难当，善 \n逐有余之滞，凡血气不足者，服之大损真气，亦 \n善动吐，所当避也。制用之法，当用酒飞去砂石，晒干入药。 \n\\x全蝎\\x（二九一）味甘辛，有毒。蝎生东方，色青属木，足厥阴肝经药也。故治中风诸风，开 \n风痰，口眼 斜，半身不遂，语言蹇涩， 疟，耳聋，疝气，风疮瘾疹，小儿风痰惊痫，是亦冶风 \n之要药。 \n\\x文蛤\\x（二九二）即五倍子。味酸涩，性微凉，能敛能降。故能降肺火，化痰涎，生津液，解 \n酒毒。治心腹疼痛，梦泄遗精，疗肿毒喉痹。止咳嗽消渴，呕血失血，肠风脏毒，滑泄久痢，痔 \n下血不止。解蛊毒虫毒，妇人崩淋带浊，子肠不收，小儿夜啼，脱肛，俱可为散服之。若煎汤用， \n可洗赤眼湿烂，皮肤风湿癣癞，肠痔脱肛。为末，可敷金疮折伤，生肌敛毒。 \n\\x百药煎\\x（二九三）即五倍子酿造者。味酸涩微甘，功用与五倍子颇同。但经酿造而成，其气稍 \n浮，其味稍甘而纯，故用以清痰解渴止嗽，及收敛耗散诸病，作丸噙化为尤佳，及治下焦滑泄诸病， \n亦更优也。 \n\\x蜗牛\\x（二九四）负壳而行者。味咸，性寒，有小毒。能清火解热。生研汁饮，消喉痹，止消渴 \n鼻衄，通耳聋，治肿毒痔漏，疗小儿风热惊痫。加麝香捣罨脐间，大利小便，亦敷脱肛。及治蜈蚣 \n虿毒，俱宜研烂敷之。无壳者，名蜒岫。治热疮痈毒肿痛。少入冰片，研涂痔漏脱肛热痛最良，解 \n蜈蚣毒尤捷。 \n\\x蚯蚓\\x（二九五）味咸，性寒，沉也，阴也，有毒。能解热毒，利水道。主伤寒瘅疟，黄胆消渴， \n二便不遍。杀蛇瘕三虫，伏尸鬼疰蛊毒，射罔药毒。疗癫狂喉痹，风热赤眼，KT 耳鼻 ，瘰 ， \n阴囊热肿，脱肛。去泥，盐化为水，治天行瘟疫，大热狂躁，或小儿风热癫狂急惊，饮汁最良。亦 \n可涂丹毒漆疮。炒为末服，可去蛔虫，亦可敷蛇伤肿痛，蜘蛛伤毒。入葱管化汁，可治耳聋及蚰蜒 \n入耳。若中蚯蚓毒者，惟以盐汤浸洗，或饮一杯，皆可解之。粪名六一泥，可涂火疮 腮热毒，亦 \n止消渴，解瘟疫烦热狂躁，利小水，通五淋热闭疼痛。 \n\\x桑螵蛸\\x（二九六）即螳螂育子房也。深秋作房，粘着桑枝之上，房长寸许，大如拇指，其内重 \n重有隔，每房有子如蛆卵子是也。味甘微咸，性平。能益气益精，助阳生子，疗男子虚损，阴痿梦 \n遗，疝瘕遗尿，治女人血闭腰 \n痛，通五淋，利水道。炮熟空心食之，可止小便不禁。 \n\n\n\n<目录>卷之四十九大集·本草正（下）\n\n<篇名>人部\n\n属性：\\x童便\\x（二九七）味咸，气寒，沉也，阴也。咸走血，故善清诸血妄行，止呕血咳血衄血，血闷热 \n狂，退阴火，定喘促，降痰滞，解烦热，利大小两便，疗阳暑中 声喑，扑损瘀血晕绝，难产胎衣 \n不下，及蛇犬诸虫毒伤。若假热便溏，胃虚作呕者，俱不可妄用。 \n\\x紫河车\\x（二九八）一名混沌衣。味甘咸，性温。能补男妇一切精血虚损，尤治癫痫失志，精神 \n短少，怔忡惊悸，肌肉羸瘦等证，此旧说也。但此物古人用少，而始于陈氏《本草》，自后丹溪复 \n称其功，遂为时用。予于初年，亦惑于以人补人之说，尝制用之，及用之再三，则无所奇效。且制 \n用之法，若生捣之，则补不宜生，若炖熟烘熟，则亦犹肉 之类耳。又尝见有以酒煮而食之者，后 \n必破腹泄泻，总亦因其性滑也。近复有以纯酒煮膏，去 收贮，而日服其膏者，较前诸法似为更善。 \n然其既离毛里，已绝生气，既无奇效，又胡忍食之，以残厥子之先天。东方朔曰∶铜山西崩，洛钟 \n东应。此母子自然之理，不可不信，故并述此以劝人少用可也。 \n\\x血余\\x（二九九）味微苦，性温气盛，升也，阴中阳也。在古药性不过谓其治咳嗽，消瘀血，止 \n五淋、赤白痢疾，疗大小便不通，及小儿惊痫，治哽噎、痈疽疔肿，烧灰吹鼻，可止衄血等证。然 \n究其性味之理，则自阴而生，自下而长，血盛则发盛，最得阴阳之生气。以火炮制，其色甚黑，大 \n能壮肾，其气甚雄，大能补肺。此其阴中有阳，静中有动，在阴可以培形体，壮筋骨，托痈痘；在 \n阳可以益神志，辟寒邪，温气海，是诚精气中最要之药，较之河车、鹿角胶阴凝重着之辈，相去远 \n矣。凡补药中，自人参、熟地之外，首当以此为亚。 \n\\x人中白\\x（三百） 味咸， \n性微凉。能降火清痰，消瘀血，止吐血衄血，退劳热，清肺痈肺痿，心膈烦热。烧研为末，大治诸湿溃烂，下疳恶疮， \n口齿疳蚀，虫 肿痛，汤火诸疮，及诸窍出血，生肌长肉，善解热毒。或生用为末亦可。 \n\n\n\n<目录>卷之五十德集·新方八阵\n\n<篇名>新方八略引\n\n属性：药不执方，合宜而用，此方之不必有也。方以立法，法以制宜，此方之不可无也。夫方 \n之善者，得其宜也。得其宜者，可为法也。方之不善者，失其宜也。失其宜者，可为鉴也。 \n第法有善不善，人有知不知，必善于知方者，斯可以执方，亦可以不执方，能执方能不执方 \n者，非随时之人不能也。此方之所不可废者，正欲以启发其人耳。余因选古方之得宜者共若 \n干首，列为八阵，已不为不多矣。第以余观之，若夫犹有未尽，因复制新方八阵，此其中有 \n心得焉，有经验焉，有补古之未备焉。凡各方之下，多附加减等法，及分两之数，俱有出入 \n不一者，正以见方之不可执也。八阵之中，如攻方、寒方之不多及者，以古法既多，不必更 \n为添足也。大都方宜从简，而余复冗之，不尤鄙乎？正意在冗中求简耳，此制方之意也。然 \n用方之意，则犹有说焉∶夫意贵圆通，用嫌执滞，则其要也。若但圆无主，则杂乱生而无不 \n可矣，不知疑似间自有一定不易之道，此圆通中不可无执持也；若执一不反，则偏 \n生而动相左矣。不知倏忽间每多三因难测之变，此执持中不可无圆活也。圆活宜从三思，执 \n持须有定见，既能执持，又能圆活，其能方能圆之人乎，而人其为谁哉！ \n\n\n\n<目录>卷之五十德集·新方八阵\\新方八略引\n\n<篇名>一、补略\n\n属性：一、补方之制，补其虚也。凡气虚者，宜补其上，人参、黄 之属是也。精虚者，宜补 \n其下，熟地、枸杞之属是也。阳虚者，宜补而兼暖，桂、附、干姜之属是也。阴虚者，宜补 \n而兼清，门冬、芍药、生地之属是也。此固阴阳之治辨也。其有气因精而虚者，自当补精以 \n化气；精因气而虚者，自当补气以生精。又有阳失阴而离者，不补阴何以收散亡之气？水失 \n火而败者，不补火何以苏垂寂之阴？此又阴阳相济之妙用也。故善补阳者，必于阴中求阳， \n则阳得阴助，而生化无穷；善补阴者，必于阳中求阴，则阴得阳升，而源泉不竭。余故曰∶ \n以精气分阴阳，则阴阳不可离；以寒热分阴阳，则阴阳不可混，此又阴阳邪正之离合也。故 \n凡阳虚多寒者，宜补以甘温，而清润之品非所宜；阴虚多热者，宜补以甘凉，而辛燥之类不 \n可用。知宜知避，则不惟用补，而八方之制，皆可得而贯通矣。 \n\n\n\n<目录>卷之五十德集·新方八阵\\新方八略引\n\n<篇名>二、和略\n\n属性：一、和方之制，和其不和者也。凡病兼虚者，补而和之。兼滞者，行而和之。兼寒者， \n温而和之。兼热者，凉而和之，和之为义广矣。亦犹土兼四气，其于补泻温凉之用，无所不 \n及，务在调平元气，不失中和之为贵也。故凡阴虚于下而精血亏损者，忌利小水，如四苓、 \n通草汤之属是也。阴虚于上而肺热干咳者，忌用辛燥，如半夏、苍术、细辛、香附、芎、归 \n、白术之属是也。阳虚于上，忌消耗。如陈皮、砂仁、木香、槟榔之属是也。阳虚于下者， \n忌沉寒。如黄柏、知母、栀子、木通之属是也。大便溏泄者，忌滑利。如二冬、牛膝、苁蓉 \n、当归、柴胡、童便之属是也。表邪未解者，忌收敛。如五味、枣仁、地榆、文蛤之属是也 \n。气滞者，忌闭塞。如黄 、白术、薯蓣、甘草之属是也。经滞者，忌寒凝。如门冬、生地 \n、石斛、芩、连之属是也。凡邪火在上者不宜升，火得升而愈炽矣。沉寒在下者不宜降，阴 \n被降而愈亡矣。诸动者不宜再动，如火动者忌温暖，血动者忌辛香，汗动者忌苏散，神动者 \n忌耗伤，凡性味之不静者皆所当慎，其于刚暴更甚者，则又在不言可知也。诸静者不宜再静 \n，如沉微细弱者脉之静也，神昏气怯者阳之静也，肌体清寒者表之静也，口腹畏寒者里之静也 \n。凡性味之阴柔者，皆所当慎，其于沉寒更甚者，又在不言可知也。夫阳主动，以动济动， \n火上添油也。不焦烂乎？阴主静，以静益静，雪上加霜也。不寂灭乎？凡前所论，论其略耳， \n而书不尽言，言不尽意，能因类而广之，则存夫其人矣。不知此义，又何和剂之足云。 \n\n\n\n<目录>卷之五十德集·新方八阵\\新方八略引\n\n<篇名>三、攻略\n\n属性：一、攻方之制，攻其实也。凡攻气者攻其聚，聚可散也。攻血者攻其瘀，瘀可通也。攻 \n积者攻其坚，在脏者可破、可培，在经者可针、可灸也。攻痰者攻其急，真实者暂宜解标， \n多虚者只宜求本也。但诸病之实有微甚，用攻之法分重轻。大实者，攻之未及，可以再加； \n微实者，攻之太过，每因致害，所当慎也。凡病在阳者，不可攻阴，病在胸者，不可攻脏。 \n若此者，邪必乘虚内陷，所谓引贼入寇也。病在阴者，勿攻其阳。病在里者勿攻其表，若此 \n者，病必因误而甚，所谓自撤藩蔽也。大都治宜用攻，必其邪之甚者也。其若实邪果甚，自 \n与攻药相宜，不必杂之补剂。盖实不嫌攻，若但略加甘滞，便相牵制；虚不嫌补，若但略加 \n消耗，偏觉相妨。所以寒实者最不喜清，热实者最不喜暖。然实而误补，不过增病，病增者 \n可解；虚而误攻，必先脱元，元脱者，无治矣。是皆攻法之要也。其或虚中有实，实中有虚 \n，此又当酌其权宜，不在急宜攻、急宜补者之例。虽然，凡用攻之法，所以除凶剪暴也，亦 \n犹乱世之兵，必不可无，然惟必不得已乃可用之。若或有疑，宁加详慎。盖攻虽去邪，无弗 \n伤气，受益者四，受损者六。故攻之一法，实自古仁人所深忌者，正恐其成之难，败之易耳 \n。倘任意不思，此其人可知矣。 \n\n\n\n<目录>卷之五十德集·新方八阵\\新方八略引\n\n<篇名>四、散略\n\n属性：一、用散者，散表证也。观仲景太阳证用麻黄汤，阳明证用升麻葛根汤，少阳证用小柴 \n胡汤，此散表之准绳也。后世宗之，而复不能用之，在不得其意耳。盖麻黄之气，峻利而勇 \n。凡太阳经阴邪在表者，寒毒既深，非此不达，故制用此方，非谓太阳经药必须麻黄也。设 \n以麻黄治阳明、少阳之证，亦寒无不散，第恐性力太过，必反伤其气，岂谓某经某药必不可 \n移易，亦不过分其轻重耳。故如阳明之升麻、干葛，未有不走太阳、少阳者。少阳之柴胡， \n亦未有不入太阳、阳明者。但用散之法，当知性力缓急，及气味寒温之辨，用得其宜，诸经 \n无不妙也。如麻黄、桂枝，峻散者也；防风、荆芥、紫苏，平散者也；细辛、白芷、生姜， \n温散者也；柴胡、干葛、薄荷，凉散者也；羌活、苍术，能走经去湿而散者也；升麻、川芎 \n，能举陷上行而散者也。第邪浅者，忌峻利之属；气弱者，忌雄悍之属；热多者，忌温燥之 \n属；寒多者，忌清凉之属。凡热渴烦躁者喜干葛，而呕恶者忌之；寒热往来者宜柴胡，而泄 \n泻者忌之；寒邪在上者，宜升麻、川芎，而内热炎升者忌之。此性用之宜忌，所当辨也。至 \n于相配之法，则尤当知要，凡以平兼清，自成凉散；以平兼暖，亦可温经；宜大温者，以热 \n济热；宜大凉者，以寒济寒。此其运用之权，则毫厘进退，自有伸缩之妙，又何必胶柱刻舟 \n，以限无穷之病变哉！此无他，在不知仲景之意耳。 \n\n\n\n<目录>卷之五十德集·新方八阵\\新方八略引\n\n<篇名>五、寒略\n\n属性：一、寒方之制，为清火也，为除热也。夫火有阴阳，热分上下。据古方书，咸谓黄连清 \n心，黄芩清肺，石斛、芍药清脾，龙胆清肝，黄柏清肾。今之用者，多守此法，是亦胶柱法 \n也。大凡寒凉之物，皆能泻火，岂有凉此而不凉彼者，但当分其轻清重浊，性力微甚，用得 \n其宜则善矣。夫轻清者，宜以清上。如黄芩、石斛、连翘、天花之属是也。重浊者，宜于清 \n下。如栀子、黄柏、龙胆、滑石之属也。性力之浓者，能清大热。如石膏、黄连、芦荟、苦 \n参、山豆根之属也。性力之缓者，能清微热。如地骨皮、玄参、贝母、石斛、童便之属也。 \n以攻而用者，去实郁之热。如大黄、芒硝之属也。以利而用者，去癃闭之热。如木通、茵陈 \n、猪苓、泽泻之属也。以补而用者，去阴虚枯燥之热。如生地、二冬、芍药、梨浆、细甘草 \n之属也。方书之分经用药者，意正在此，但不能明言其意耳。然火之甚者，在上亦宜重浊； \n火之微者，在下亦可轻清。夫宜凉之热，皆实热也。实热在下，自宜清利；实热在上，不可 \n升提。盖火本属阳，宜从阴治，从阴者宜降，升则反从其阳矣。经曰∶高者抑之，义可知也 \n。外如东垣有升阳散火之法，此以表邪生热者设，不得与伏火内炎者并论。 \n\n\n\n<目录>卷之五十德集·新方八阵\\新方八略引\n\n<篇名>六、热略\n\n属性：一、热方之制，为除寒也。夫寒之为病，有寒邪犯于肌表者，有生冷伤于脾胃者，有阴 \n寒中于脏腑者，此皆外来之寒，去所从来，则其治也，是皆人所易知者。至于本来之寒，生 \n于无形无响之间，初无所感，莫测其因，人之病此者最多，人之知此者最少，果何谓哉？观 \n丹溪曰∶气有余便是火。余续之曰∶气不足便是寒。夫今人之气有余者，能十中之几？其有 \n或因禀受，或因丧败，以致阳气不足者，多见寒从中生，而阳衰之病，无所不致。第其由来 \n者渐，形见者微，当其未觉也，孰为之意？及其既甚也，始知治难。矧庸医多有不识，每以 \n假热为真火，因复毙于无形无响者，又不知其几许也，故惟高明见道之士，常以阳衰根本为 \n忧，此热方之不可不预也。 \n凡用热之法，如干姜能温中，亦能散表，呕恶无汗者宜之。肉桂能行血，善达四肢，血 \n滞多痛者宜之。吴茱萸善暖下焦，腹痛泄泻者极妙。肉豆蔻可温脾肾，飧泄滑利者最奇。胡 \n椒温胃和中，其类近于荜拨。丁香止呕行气，其暖过于豆仁。补骨脂性降而散闭，故能纳气 \n定喘，止带浊泄泻。制附子性行如酒，故无处不到，能救急回阳。至若半夏、南星、细辛、 \n乌药、良姜、香附、木香、茴香、仙茅、巴戟之属，皆性温之当辨者。然用热之法，尚有其 \n要∶以散兼温者，散寒邪也；以行兼温者，行寒滞也；以补兼温者，补虚寒也。第多汗者忌 \n姜，姜能散也。失血者忌桂，桂动血也。气短气怯者忌故纸，故纸降气也。大凡气香者，皆 \n不利于气虚证。味辛者，多不利于见血证，所当慎也。是用热之概也。 \n至于附子之辨，凡今之用者，必待势不可为，不得已然后用之，不知回阳之功，当用于 \n阳气将去之际，盒饭渐用，以望挽回。若用于既去之后，死灰不可复然矣，尚何益于事哉。 \n但附子性悍，独任为难，必得大甘之品如人参、熟地、炙甘草之类，皆足以制其刚而济其勇 \n，以补倍之，无往不利矣。此壶天中大将军也，可置之无用之地乎？但知之真而用之善，斯 \n足称将将之手矣。 \n\n\n\n<目录>卷之五十德集·新方八阵\\新方八略引\n\n<篇名>七、固略\n\n属性：一、固方之制，固其泄也。如久嗽为喘，而气泄于上者，宜固其肺。久遗成淋，而精脱 \n于下者，宜固其肾。小水不禁者，宜固其膀胱。大便不禁者，宜固其肠脏。汗泄不止者，宜 \n固其皮毛。血泄不止者，宜固其营卫。凡因寒而泄者，当固之以热；因热而泄者，当固之以 \n寒。总之，在上者在表者，皆宜固气，气主在肺也；在下者在里者，皆宜固精，精主在肾也 \n。然虚者可固，实者不可固；久者可固，暴者不可固。当固不固，则沧海亦将竭；不当固而 \n固，则闭门延寇也。二者俱当详酌之。 \n\n\n\n<目录>卷之五十德集·新方八阵\\新方八略引\n\n<篇名>八、因略\n\n属性：一、因方之制，因其可因者也。凡病有相同者，皆可按证而用之，是谓因方。如痈毒之 \n起，肿可敷也；蛇虫之患，毒可解也；汤火伤其肌肤，热可散也；跌打伤其筋骨，断可续也 \n，凡此之类，皆因证而可药者也。然因中有不可因者，又在乎证同而因不同耳。盖人之虚实 \n寒热，各有不齐，表里阴阳，治当分类。故有宜于此而不宜于彼者，有同于表而不同于里者 \n。所以病虽相类，而但涉内伤者，盒饭于血气中酌其可否之因，不可谓因方之类，尽可因之 \n而用也。因之为用，有因标者，有因本者，勿因此因字而误认因方之义。 \n\n\n\n<目录>卷之五十一德集·新方八阵\n\n<篇名>补阵\n\n属性：\\x大补元煎\\x 治男妇气血大坏，精神失守危剧等证。此回天赞化，救本培元第一要方。本 \n方与后右归饮出入互思。 \n人参（补气补阳，以此为主，少则用一、二钱，多则用一、二两） 山药（炒，二钱） 熟地（ \n补精补阴，以此为主，少则用二、三钱，多则用二、三两） 杜仲（二钱） 当钱（二、三钱，若泄泻 \n者，去之） 山茱萸（一钱，如畏酸吞酸者，去之） 枸杞（二、三钱） 炙甘草（一、二钱） \n水二钟，煎七分，食远温服。如元阳不足多寒者，于本方加附子、肉桂、炮姜之类，随 \n宜用之；如气分偏虚者，加黄 、白术；如胃口多滞者，不必用；如血滞者，加川芎，去山 \n茱萸；如滑泄者，加五味、故纸之属。 \n\\x左归饮\\x 此壮水之剂也。凡命门之阴衰阳胜者，宜此方加减主之。此一阴煎、四阴煎之主方也。 \n熟地（二、三钱，或加至一、二两） 山药（二钱） 枸杞（二钱） 炙甘草（一钱） 茯苓（一钱半） 山 \n茱萸（一、二钱，畏酸者，少用之） \n水二钟，煎七分，食远服。如肺热而烦者，加麦冬二钱；血滞者，加丹皮二钱；心热而 \n躁者，加玄参二钱；脾热易饥者，加芍药二钱；肾热骨蒸多汗者，加地骨皮二钱；血热妄动 \n者，加生地二、三钱；阴虚不宁者，加女贞子二钱；上实下虚者，加牛膝二钱以导之；血虚 \n而燥滞者，加当归二钱。 \n\\x右归饮\\x 此益火之剂也，凡命门之阳衰阴胜者，宜此方加减主之。此方与大补元煎出入 \n互用。如治阴盛格阳，真寒假热等证，宜加泽泻二钱，煎成用凉水浸冷服之尤妙。 \n熟地（用如前） 山药（炒，二钱） 山茱萸（一钱） 枸杞（二钱） 甘草（炙，一、二钱） 杜仲（姜 \n制，二钱） 肉桂（一、二钱） 制附子（一、二、三钱） \n水二钟，煎七分，食远温服。如气虚血脱，或厥或昏，或汗或运，或虚狂，或短气者， \n必大加人参、白术，随宜用之；如火衰不能生土，为呕哕吞酸者，加炮干姜二、三钱；如阳 \n衰中寒，泄泻腹痛，加人参、肉豆蔻，随宜用之；如小腹多痛者，加吴茱萸五、七分；如淋 \n带不止，加破故纸一钱；如血少血滞，腰膝软痛者，加当归二、三钱。 \n\\x左归丸\\x 治真阴肾水不足，不能滋养营卫，渐至衰弱，或虚热往来，自汗盗汗，或神不 \n守舍，血不归原，或虚损伤阴，或遗淋不禁，或气虚昏运，或眼花耳聋，或口燥舌干，或腰 \n酸腿软，凡精髓内亏，津液枯涸等证，俱速宜壮水之主，以培左肾之元阴，而精血自充矣。宜此方主之。 \n大怀熟（八两） 山药（炒，四两） 枸杞（四两） 山茱萸肉（四两） 川牛膝（酒洗，蒸熟，三两，精 \n滑者，不用） 菟丝子（制，四两） 鹿胶（敲碎，炒珠，四两） 龟胶（切碎，炒珠，四两，无火者，不必用） \n上先将熟地蒸烂，杵膏，加炼蜜丸，桐子大。每食前用滚汤或淡盐汤送下百余丸。 \n如真阴失守，虚火炎上者，宜用纯阴至静之剂，于本方去枸杞、鹿胶，加女贞子三两， \n麦冬三两；如火烁肺金，干枯多嗽者，加百合三两；如夜热骨蒸，加地骨皮三两；如小水不 \n利不清，加茯苓三两；如大便燥结，去菟丝，加肉苁蓉三两；如气虚者，加人参三、四两； \n如血虚微滞，加当归四两；如腰膝酸痛，加杜仲三两，监水炒用；如脏平无火而肾气不充者 \n，加破故纸三两，去心莲肉、胡桃肉各四两，龟胶不必用；上凡五液皆主于肾，故凡属阴分 \n之药，无不皆能走肾，有谓必须导引者，皆见之不明耳。 \n\\x右归丸\\x 治元阳不足，或先天禀衰，或劳伤过度，以致命门火衰，不能生土，而为脾胃 \n虚寒，饮食少进，或呕恶膨胀，或番胃噎膈，或怯寒畏冷，或脐腹多痛，或大便不实，泻痢 \n频作，或小水自遗，虚淋寒疝，或寒侵溪谷而肢节痹痛，或寒在下焦而水邪浮肿。总之，真 \n阳不足者，必神疲气怯，或心跳不宁，或四体不收，或眼见邪崇，或阳衰无子等证，俱速宜 \n益火之原，以培右肾之元阳，而神气自强矣，此方主之。 \n大怀熟（八两） 山药（炒，四两） 山茱萸（微炒，三两） 枸杞（微炒，四两） 鹿角胶（炒珠，四两） \n菟丝子（制，四两） 杜仲（姜汤炒，四两） 当归（三两，便溏勿用） 肉桂（二两，渐可加至四两） \n制附子（自二两，渐可加至五、六两） \n上丸法如前，或丸如弹子大。每嚼服二、三丸。以滚白汤送下，其效尤速。 \n如阳衰气虚，必加人参以为之主，或二、三两，或五、六两，随人虚实，以为增减。盖 \n人参之功，随阳药则入阳分，随阴药则入阴分，欲补命门之阳，非加人参不能捷效。如阳虚 \n精滑，或带浊便溏，加补骨脂酒炒三两；如飧泄肾泄不止，加北五味子三两，肉豆蔻三两， \n面炒去油用；如饮食减少，或不易化，或呕恶吞酸，皆脾胃虚寒之证，加干姜三、四两，炒 \n黄用；如腹痛不止，加吴茱萸二两，汤泡半日，炒用；如腰膝酸痛，加胡桃肉连皮四两；如 \n阴虚阳痿，加巴戟肉四两，肉苁蓉三两，或加黄狗外肾一、二付，以酒煮烂捣入之。 \n\\x五福饮\\x 凡五脏气血亏损者，此能兼治之，足称王道之最。 \n人参（随宜，心） 熟地（随宜，肾） 当归（二、三钱，肝） 白术（炒，一钱半，肺） 炙甘草（一钱，脾） \n水二钟，煎七分，食远温服。或加生姜三、五片。凡治气血俱虚等证，以此为主。或宜 \n温者，加姜、附；宜散者，加升麻、柴、葛，左右逢源，无不可也。 \n\\x七福饮\\x 治气血俱虚，而心脾为甚者。 \n即前方加枣仁二钱，远志三、五分，制用。 \n\\x一阴煎\\x 此治水亏火胜之剂，故曰一阴。凡肾水真阴虚损，而脉证多阳，虚火发热，及 \n阴虚动血等证，或疟疾伤寒屡散之后，取汗既多，脉虚气弱，而烦渴不止，潮热不退者，此 \n以汗多伤阴，水亏而然也，皆宜用此加减主之。 \n生地（二钱） 熟地（三、五钱） 芍药（二钱） 麦冬（二钱） 甘草（一钱） 牛膝（一钱半） 丹参（二钱） \n水二钟，煎七分，食远温服。如火盛躁烦者，入真龟胶二、三钱，化服；如气虚者，间 \n用人参一、二钱；如心虚不眠多汗者，加枣仁、当归各一、二钱；如汗多烦躁者，加五味子 \n十粒，或加山药、山茱萸；如见微火者，加女贞子一、二钱；如虚火上浮，或吐血、或衄血 \n不止者，加泽泻一、二钱，茜根二钱，或加川续断一、二钱，以涩之亦妙。 \n\\x加减一阴煎\\x 治证如前而火之甚者，宜用此方。 \n生地 芍药 麦冬（各二钱） 熟地（三、五钱） 炙甘草（五、七分） 知母 地骨皮（各一钱） \n水二钟，煎服。如躁烦热甚便结者，加石膏二、三钱；如小水热涩者，加栀子一、二钱 \n；如火浮于上者，加泽泻一、二钱，或黄芩一钱；如血燥血少者，加当归一、二钱。 \n\\x二阴煎\\x 此治心经有热，水不制火之病，故曰二阴。凡惊狂失志，多言多笑，或疡疹烦 \n热失血等证，宜此主之。 \n生地（二、三钱） 麦冬（二、三钱） 枣仁（二钱） 生甘草（一钱） 玄参（一钱半） 黄连（或一、二钱） \n茯苓（一钱半） 木通（一钱半） \n水二钟，加灯草二十根，或竹叶亦可，煎七分，食远服。如痰胜热甚者，加九制胆星一 \n钱，或天花粉一钱五分。 \n\\x三阴煎\\x 此治肝脾虚损，精血不足，及营虚失血等病，故曰三阴。凡中风血不养筋，及 \n疟疾汗多，邪散而寒热犹不能止，是皆少阳、厥阴阴虚少血之病，微有火者，宜一阴煎；无 \n火者，宜此主之。 \n当归（二、三钱） 熟地（三、五钱） 炙甘草（一钱） 芍药（酒炒，二钱） 枣仁（二钱） 人参（随宜） \n水二钟，煎七分，食远服。如呕恶者，加生姜三、五片；汗多烦躁者，加五味子十四粒 \n；汗多气虚者，加黄 一、二钱；小腹隐痛，加枸杞二、三钱；如有胀闷，加陈皮一钱；如 \n腰膝筋骨无力，加杜仲、牛膝。 \n\\x四阴煎\\x 此保肺清金之剂，故曰四阴。治阴虚劳损，相火炽盛，津枯烦渴，咳嗽吐衄多热等证。 \n生地（二、三钱） 麦冬（二钱） 白芍药（二钱） 百合（二钱） 沙参（二钱） 生甘草（一 \n钱） 茯苓（一钱半） \n水二钟，煎七分，食远服。如夜热盗汗，加地骨皮一、二钱；如痰多气盛，加贝母二、 \n三钱，阿胶一、二钱，天花粉亦可；如金水不能相滋，而干燥喘嗽者，加熟地三、五钱；如 \n多汗不眠，神魂不宁，加枣仁二钱；如多汗兼渴，加北五味十四粒；如热甚者，加黄柏一、 \n二钱，盐水炒用，或玄参亦可，但分上下用之；如血燥经迟，枯涩不至者，加牛膝二钱；如 \n血热吐衄，加茜根二钱；如多火便燥，或肺干咳咯者，加天门冬二钱，或加童便亦可；如火 \n载血上者，去甘草，加炒栀子一、二钱。 \n\\x五阴煎\\x 凡真阴亏损，脾虚失血等证，或见溏泄未甚者，所重在脾，故曰五阴。忌用润 \n滑，宜此主之。 \n熟地（五、七钱，或一两） 山药（炒，二钱） 扁豆（炒，二、三钱） 炙甘草（一、二钱） 茯苓（一 \n钱半） 芍药（炒黄，二钱） 五味子（二十粒） 人参（随宜用） 白术（炒，一、二钱） \n水二钟，加莲肉去心二十粒，煎服。 \n\\x大营煎\\x 治真阴精血亏损，及妇人经迟血少，腰膝筋骨疼痛，或气血虚寒，心腹疼痛等证。 \n当归（二、三钱，或五钱） 熟地（三、五、七钱） 枸杞（二钱） 炙甘草（一、二钱） 杜仲（二钱） \n牛膝（一钱半） 肉桂（一、二钱） \n水二钟，煎七分，食远温服。如寒滞在经，气血不能流通，筋骨疼痛之甚者，必加制附 \n子一、二钱方效；如带浊腹痛者，加故纸一钱炒用；如气虚者，加人参、白术；中气虚寒呕 \n恶者，加炒焦干姜一、二钱。 \n\\x小营煎\\x 治血少阴虚，此性味平和之方也。 \n当归（二钱） 熟地（二、三钱） 芍药（酒炒，二钱） 山药（炒，二钱） 枸杞（二钱） 炙甘草（一钱） \n水二钟，煎七分，食远温服。如营虚于上，而为惊恐怔忡，不眠多汗者，加枣仁、茯神 \n各二钱；如营虚兼寒者，去芍药，加生姜；如气滞有痛者，加香附一、二钱，引而行之。 \n\\x补阴益气煎\\x 此补中益气汤之变方也。治劳倦伤阴，精不化气，或阴虚内乏，以致外感 \n不解，寒热 疟，阴虚便结不通等证。凡属阴气不足而虚邪外侵者，用此升散，无不神效。 \n人参（一、二、三钱） 当归（二、三钱） 山药（酒炒，二、三钱） 熟地（三、五钱或一、二两） \n陈皮（一钱） 炙甘草（一钱） 升麻（三、五分，火浮于上者，去此不必用） 柴胡（一、二钱，如无外 \n邪者，不必用） \n水二钟，加生姜三、五、七片，煎八分，食远温服。 \n\\x举元煎\\x 治气虚下陷，血崩血脱，亡阳垂危等证，有不利于归、熟等剂，而但宜补气者，以此主之。 \n人参 黄 （炙，各三、五钱） 炙甘草（一、二钱） 升麻（五、七分，炒用） 白术（炒，一、二钱） \n水一钟半，煎七、八分，温服。如兼阳气虚寒者，桂、附、干姜随宜佐用。如兼滑脱者 \n，加乌梅二个，或文蛤七、八分。 \n\\x两仪膏\\x 治精气大亏，诸药不应，或以克伐太过，耗损真阴。凡虚在阳分而气不化精者 \n，宜参术膏；若虚在阴分而精不化气者，莫妙于此。其有未至大病而素觉阴虚者，用以调元，尤称神妙。 \n人参（半斤或四两） 大熟地（一斤） \n上二味，用好甜水或长流水十五碗，浸一宿，以桑柴文武火煎取浓汁。若味有未尽，再 \n用水数碗煎 取汁，并熬稍浓，乃入瓷罐，重汤熬成膏，入真白蜜四两或半斤收之，每 \n以白汤点服。若劳损咳嗽多痰，加贝母四两亦可。 \n\\x贞元饮\\x 治气短似喘，呼吸促急，提不能升，咽不能降，气道噎塞，势剧垂危者。常人 \n但知为气急，其病在上，而不知元海无根，亏损肝肾，此子午不交，气脱证也，尤为妇人血 \n海常亏者最多此证，宜急用此饮以济之，缓之，敢云神剂。凡诊此证，脉必微细无神，若微 \n而兼紧，尤为可畏。倘庸众不知，妄云痰逆气滞，用牛黄、苏合及青、陈、枳壳破气等剂，则速其危矣。 \n熟地黄（七、八钱，甚者一、二两） 炙甘草（一、二、三钱） 当归（二、三钱） \n水二钟，煎八分，温服。如兼呕恶或恶寒者，加煨姜三、五片；如气虚脉微至极者，急 \n加人参随宜；如肝肾阴虚，手足厥冷，加肉桂一钱。 \n\\x当归地黄饮\\x 治肾虚腰膝疼痛等证。 \n当归（二、三钱） 熟地（三、五钱） 山药（二钱） 杜仲（二钱） 牛膝（一钱半） 山茱萸（一钱） 炙甘 \n草（八分） \n水二钟，煎八分，食远服。如下部虚寒，加肉桂一、二钱，甚者仍加附子；如多带浊， \n去牛膝，加金樱子二钱，或加故纸一钱；如气虚者，加人参一、二钱，枸杞二、三钱。 \n\\x济川煎\\x 凡病涉虚损，而大便闭结不通，则硝、黄攻击等剂必不可用；若势有不得不通 \n者，宜此主之。此用通于补之剂也，最妙最妙。 \n当归（三、五钱） 牛膝（二钱） 肉苁蓉（酒洗去咸，二、三钱） 泽泻（一钱半） 升麻（五、七分或 \n一钱） 枳壳（一钱，虚甚者不必用） \n水一钟半，煎七、八分，食前服。如气虚者，但加人参无碍；如有火，加黄芩；如肾虚 \n，加熟地。 \n\\x地黄醴\\x 治男妇精血不足，营卫不充等患，宜制此常用之。 \n大怀熟（取味极甘者，烘、晒干以去水气，八两） 沉香（一钱，或白檀三分亦可） 枸杞（用 \n极肥者，亦烘、晒以去润气，四两） \n上约每药一斤，可用高烧酒十斤浸之，不必煮，但浸十日之外，即可用矣。凡服此者， \n不得过饮。服完又加酒六七斤，再浸半月，仍可用。 \n\\x归肾丸\\x 治肾水真阴不足，精衰血少，腰酸脚软，形容憔悴，遗泄阳衰等证。此左 \n归、右归二丸之次者也。 \n熟地（八两） 山药（四两） 山茱萸（肉四两） 茯苓（四两） 当归（三两） 枸杞（四两） 杜仲（盐 \n水炒，四两） 菟丝子（制，四两） \n炼蜜同熟地膏为丸，桐子大。每服百余丸，饥时，或滚水或淡盐汤送下。 \n\\x赞化血余丹\\x 此药大补气血，故能乌须发，壮形体，其于培元赞育之功，有不可尽述者。 \n血余（八两） 熟地（八两，蒸捣） 枸杞 当归 鹿角胶（炒珠） 菟丝子（制） 杜仲（盐水炒） \n巴戟（肉，酒浸，剥，炒干） 小茴香（略炒） 白茯苓（乳拌蒸熟） 肉苁蓉（酒洗，去鳞甲） \n胡桃肉（各四两） 何首乌（小黑豆汁拌蒸七次，如无黑豆，或人乳、牛乳拌蒸俱妙，四两） 人 \n参（随便用，无亦可） \n上炼蜜丸服。每食前用滚白汤送下二、三钱许。精滑者，加白术、山药各三两；便溏者， \n去苁蓉，加补骨脂酒炒四两；阳虚者，加附子、肉桂。 \n\\x养元粉\\x 大能实脾养胃气。 \n糯米（一升，水浸一宿，沥干，漫火炒熟） 山药（炒） 芡实（炒） 莲肉（各三两） 川椒（去 \n目及闭口者，炒出汗，取红末二、三钱） \n上为末。每日饥时，以滚水一碗，入白糖三匙化开，入药末一、二两调服之。或加四君 \n、山楂肉各一、二两更妙。 \n\\x玄武豆\\x \n羊腰子（五十个） 枸杞（二斤） 补骨脂（一斤） 大茴香（六两） 小茴香（六两） 肉苁蓉（十二两，大 \n便滑者去之） 青盐（八两，如无苁蓉，此宜十二两） 大黑豆（一斗，圆净者，淘洗净） \n上用甜水二斗，以砂锅煮前药七味，至半干，去药渣，入黑豆，匀火煮干为度。如有余 \n汁，俱宜拌渗于内。取出用新布摊晾晒干，瓷瓶收贮。日服之，其效无穷。如无砂锅，即铁 \n锅亦可。若阳虚，加制附子一、二两更妙。 \n\\x蟠桃果\\x 治遗精虚弱，补脾滋肾最佳。 \n芡实（一斤，炒） 莲肉（去心，一斤） 胶枣肉（一斤） 熟地（一斤） 胡桃肉（去皮，二斤） \n上以猪腰六个，掺大茴香蒸极熟，去筋膜，同前药末捣成饼。每日服二个，空心食前用 \n滚白汤或好酒一、二钟下。此方凡人参、制附子俱可随意加用。 \n\\x王母桃\\x 培补脾肾，功力最胜。 \n白术（用冬术腿片味甘者佳，苦者勿用。以米泔浸一宿，切片，炒） 大怀熟（蒸捣，上二 \n味等分） 何首乌（九蒸） 巴戟（甘草汤浸，剥，炒） 枸杞子（上三味减半） \n上为末，炼蜜捣丸，龙眼大。每用三、四丸，饥时嚼服，滚汤送下。或加人参，其功尤大。 \n\\x休疟饮\\x 此止疟最妙之剂也。若汗散既多，元气不复，或以衰老，或以弱质，而疟有不 \n能止者，俱宜用此，此化暴善后之第一方也。其有他证，加减俱宜如法。 \n人参 白术（炒） 当归（各三、四钱） 何首乌（制，五钱） 炙甘草（八分） \n水一钟半，煎七分，食远服。渣再煎。或用阴阳水各一钟，煎一钟， 亦如之。俱 \n露一宿，次早温服一钟，饭后食远再服一钟。如阳虚多寒，宜温中散寒者，加干姜、肉桂之 \n类，甚者，或加制附子；如阴虚多热，烦渴喜冷，宜滋阴清火者，加麦冬、生地、芍药，甚 \n者加知母，或加黄芩；如肾阴不足，水不制火，虚烦虚馁，腰 脚软，或脾虚痞闷者， \n加熟地、枸杞、山药、杜仲之类，以滋脾肾之真阴；如邪有未净而留连难愈者，于此方加柴 \n胡、麻黄、细辛、紫苏之属，自无不可；如气血多滞者，或用酒、水各一钟，煎服，或服药后饮酒数杯亦可。 \n\n\n\n<目录>卷之五十一德集·新方八阵\n\n<篇名>和阵\n\n属性：\\x金水六君煎\\x 治肺肾虚寒，水泛为痰，或年迈阴虚，血气不足，外受风寒，咳嗽呕恶， \n多痰喘急等证，神效。"}, {"n": 31, "text": "卷三十一\n\n当归（二钱） 熟地（三、五钱） 陈皮（一钱半） 半夏（二钱） 茯苓（二钱） 炙甘草（一钱） \n水二钟，生姜三、五、七片，煎七、八分，食远温服。如大便不实而多湿者，去当归， \n加山药；如痰盛气滞，胸胁不快者，加白芥子七、八分；如阴寒盛而嗽不愈者，加细辛五、 \n七分；如兼表邪寒热者，加柴胡一、二钱。 \n\\x六安煎\\x 治风寒咳嗽，及非风初感，痰滞气逆等证。 \n陈皮（一钱半） 半夏（二、三钱） 茯苓（二钱） 甘草（一钱） 杏仁（一钱，去皮尖，切） 白芥子（五 \n、七分，老年气弱者不用） \n水一钟半，加生姜三、五、七片，煎七分，食远服。凡外感风邪咳嗽而寒气盛者，多不 \n易散，宜加北细辛七、八分或一钱；若冬月严寒邪甚者，加麻黄、桂枝亦可；若风胜而邪不 \n甚者，加防风一钱，或苏叶亦可；若头痛鼻塞者，加川芎、白芷、蔓荆子皆可；若兼寒热者 \n，加柴胡、苏叶；若风邪咳嗽不止，而兼肺胃之火者，加黄芩一、二钱，甚者再加知母、石 \n膏，所用生姜，只宜一片；凡寒邪咳嗽痰不利者，加当归二、三钱，老年者尤宜；若气血不 \n足者，当以金水六君煎与此参用；凡非风初感，痰胜而气不顺者，加藿香一钱五分；兼胀满 \n者，加浓朴一钱，暂开痰气，然后察其寒热虚实而调补之。若气虚猝倒，及气平无痰者，皆 \n不可用此。 \n\\x和胃二陈煎\\x 治胃寒生痰，恶心呕吐，胸膈满闷嗳气。 \n干姜（炒，一、二钱） 砂仁（四、五分） 陈皮 半夏 茯苓（各一钱半） 甘草（炙，七分） \n水一钟半，煎七分，不拘时温服。 \n\\x苓术二陈煎\\x 治痰饮水气停蓄心下，呕吐吞酸等证。 \n猪苓（一钱半） 白术（一、二钱） 泽泻（一钱半） 陈皮（一钱） 半夏（二、三钱） 茯苓（一钱半） 炙 \n甘草（八分） 干姜（炒黄，一、二钱） \n水一钟半，煎服。如肝肾兼寒者，加肉桂一、二钱。 \n\\x和胃饮\\x 治寒湿伤脾，霍乱吐泻，及痰饮水气，胃脘不清，呕恶胀满腹痛等证。此即平 \n胃散之变方也。凡呕吐等证，多有胃气虚者，一闻苍术之气，亦能动呕，故以干姜代之。 \n陈皮 浓朴（各一钱半） 干姜（炮，一、二钱） 炙甘草（一钱） \n水一钟半，煎七分，温服。此方凡藿香、木香、丁香、茯苓、半夏、扁豆、砂仁、泽泻 \n之类，皆可随宜增用之。若胸腹有滞而兼时气寒热者，加柴胡。 \n\\x排气饮\\x 治气逆食滞胀痛等证。 \n陈皮（一钱五分） 木香（七分或一钱） 藿香（一钱五分） 香附（二钱） 枳壳（一钱五分） 泽泻（二钱） \n乌药（二钱） 浓朴（一钱） \n水一钟半，煎七分，热服。如食滞者，加山楂、麦芽各二钱；如寒滞者，加焦干姜、吴 \n茱萸、肉桂之属；如气逆之甚者，加白芥子、沉香、青皮、槟榔之属；如呕而兼痛者，加半 \n夏、丁香之属；如痛在小腹者，加小茴香；如兼疝者，加荔枝核，煨熟捣碎，用二、三钱。 \n\\x大和中饮\\x 治饮食留滞积聚等证。 \n陈皮（一、二钱） 枳实（一钱） 砂仁（五分） 山楂（二钱） 麦芽（二钱） 浓朴（一钱半） 泽 \n泻（一钱半） \n水一钟半，煎七、八分，食远温服。胀甚者，加白芥子；胃寒无火或恶心者，加炮干姜 \n一、二钱；疼痛者，加木香、乌药、香附之类；多痰者，加半夏。 \n\\x小和中饮\\x 治胸膈胀闷，或妇人胎气滞满等证。 \n陈皮（一钱五分） 山楂（二钱） 茯苓（一钱半） 浓朴（一钱五分） 甘草（五分） 扁豆（炒，二钱） \n水一钟半，加生姜三、五片，煎服。如呕者，加半夏一、二钱；如胀满气不顺者，加砂 \n仁七、八分；如火郁于上者，加焦栀子一、二钱；如妇人气逆血滞者，加紫苏梗、香附之属 \n；如寒滞不行者，加干姜、肉桂之属。 \n\\x大厘清饮\\x 方在寒阵五。 \n\\x小厘清饮\\x 治小水不利，湿滞肿胀，不能受补等证，此方主之。 \n茯苓（二、三钱） 泽泻（二、三钱） 薏仁（二钱） 猪苓（二、三钱） 枳壳（一钱） 浓朴（一钱） \n水一钟半，煎七、八分，食前服。如阴虚水不能达者，加生地、牛膝各二钱；如黄胆者 \n，加茵陈二钱；如无内热而寒滞不行者，加肉桂一钱。 \n\\x解肝煎\\x 治暴怒伤肝，气逆胀满阴滞等证。如兼肝火者，宜用化肝煎。 \n陈皮 半夏 浓朴 茯苓（各一钱半） 苏叶 芍药（各一钱） 砂仁（七分） \n水一钟半，加生姜三、五片，煎服。如胁肋胀痛，加白芥子一钱；如胸膈气滞，加枳壳 \n、香附、藿香之属。 \n\\x二术煎\\x 治肝强脾弱，气泄湿泄等证。 \n白术（炒，二钱或三钱） 苍术（米泔浸，炒，一、二钱） 芍药（炒黄，二钱） 陈皮（炒，一钱五 \n分） 炙甘草（一钱） 茯苓（一、二钱） 浓朴（姜汤炒，一钱） 木香（六、七分） 干姜（炒黄，一、二钱） \n泽泻（炒，一钱半） \n水一钟半，煎七分，食远服。 \n\\x廓清饮\\x 治三焦壅滞，胸膈胀满，气道不清，小水不利，年力未衰，通身肿胀，或肚腹 \n单胀，气实非水等证。 \n枳壳（二钱） 浓朴（一钱半） 大腹皮（一、二钱） 白芥子（五、七分或一、二钱） 萝卜子（生捣， \n一钱，如中不甚胀，能食者，不必用此） 茯苓（连皮用，二、三钱） 泽泻（二、三钱） 陈皮（一钱） \n水一钟半，煎七分，食远温服。如内热多火，小水热数者，加栀子、木通各一、二钱； \n如身黄，小水不利者，加茵陈二钱；如小腹胀满，大便坚实不通者，加生大黄三、五钱；如 \n肝滞胁痛者，加青皮；如气滞胸腹疼痛者，加乌药、香附；如食滞者，加山楂、麦芽。 \n\\x扫虫煎\\x 治诸虫上攻，胸腹作痛。 \n青皮（一钱） 小茴香（炒，一钱） 槟榔 乌药（各一钱半） 细榧肉（三钱，敲碎） 吴茱萸（一钱） \n乌梅（二个） 甘草（八分） 朱砂 雄黄（各五分，俱为极细末） \n上将前八味，用水一钟半，煎八分，去 ，随入后二味，再煎三、四沸，搅匀，徐 \n徐服之。如恶心作吐，加炒干姜一、二钱，或先啖牛肉脯少许，俟一茶顷，顿服之更妙。 \n\\x十香丸\\x 治气滞寒滞诸痛。 \n木香 沉香 泽泻 乌药 陈皮 丁香 小茴香 香附（酒炒） 荔核（煨焦，各等分） 皂 \n角（微火烧烟尽） \n为末，酒糊丸。弹子大者，磨化服；丸桐子大者，汤引下。 疝之属，温酒下。 \n\\x芍药枳术丸\\x 治食积痞满，及小儿腹大胀满，时常疼痛，脾胃不和等证。此方较之枳术 \n丸，其效如神。 \n白术（二两，面炒） 赤芍药（二两，酒炒） 枳实（一两，面炒） 陈皮（一两） \n荷叶汤煮黄老米粥为丸，桐子大。米饮或滚白汤任下百余丸。如脏寒，加干姜炒黄者五 \n钱或一、二两；如脾胃气虚，加人参一、二两。 \n\\x苍术丸\\x 治寒湿在脾，泄泻久不能愈者。 \n云苓（四两） 白芍药（炒黄，四两） 炙甘草（一两） 川椒（去闭口者，炒去汗） 小茴香（炒，各 \n（一两） 浓朴（三两，姜汁炒） 真茅山苍术（八两，米泔浸一宿，切，炒。如无，即以好白术代之） \n破故纸（酒浸二日，晒干，炒香，四两） \n上为末，糯米糊为丸，桐子大。每食远清汤送下七、八十丸。 \n\\x贝母丸\\x 消痰热，润肺止咳，或肺痈肺痿，乃治标之妙剂。 \n贝母一两为末，用砂糖或蜜和丸，龙眼大。或噙化，或嚼服之。若欲劫止久嗽，每贝母 \n一两，宜加百药煎、蓬砂、天竺黄各一钱佐之尤妙。如无百药煎，即醋炒文蛤一钱亦可，或 \n粟壳亦可酌用。若治肺痈，宜加白矾一钱，同贝母丸服如前，最妙。 \n\\x括痰丸\\x 治一切停痰积饮，吞酸呕酸，胸胁胀闷疼痛等证。 \n半夏（制，二两） 白芥子（二两） 干姜（炒黄，一两） 猪苓（二两） 炙甘草（五钱） 陈皮（四两，切 \n碎，用盐二钱入水中拌浸一宿，晒干） \n上为末，汤浸蒸饼为丸，绿豆大。每服一钱许，滚白汤送下。如胸胁疼痛者，加台乌药二两。 \n\\x神香散\\x 治胸胁胃脘逆气难解，疼痛呕哕胀满，痰饮膈噎，诸药不效者，惟此最妙。 \n丁香 白豆蔻（或砂仁亦可） \n二味等分为末。清汤调下五、七分，甚者一钱，日数服不拘。若寒气作痛者，姜汤送下。 \n\n\n\n<目录>卷之五十一德集·新方八阵\n\n<篇名>攻阵\n\n属性：\\x吐法\\x 此方可代瓜蒂、三圣散之属。凡邪实上焦，或痰或食，或气逆不通等证，皆可以此法吐之。 \n用萝卜子捣碎，以温汤和搅，取淡汤徐徐饮之，少顷即当吐出。即有吐不尽者，亦必从 \n下行矣。又法，以萝卜子为末，温水调服一匙，良久吐涎沫愈。 \n一法，用盐少许，于热锅中炒红色，乃入以水，煮至将滚未滚之际，搅匀，试其滋味稍 \n淡，乃可饮之。每用半碗，渐次增饮，自然发吐，以去病为度而止。一法，凡诸药皆可取吐 \n，但随证作汤剂，探而吐之，无不可也。 \n\\x赤金豆\\x 亦名八仙丹。治诸积不行。凡血凝气滞，疼痛肿胀，虫积结聚 坚，宜此 \n主之。此丸去病捷速，较之硝、黄、棱、莪之类过伤脏气者，大为胜之。 \n巴霜（去皮膜，略去油，一钱半） 生附子（切，略炒燥，二钱） 皂角（炒微焦，二钱） 轻粉（一 \n钱） 丁香 木香 天竺黄（各三钱） 朱砂（二钱为衣） \n上为末，醋浸蒸饼为丸，萝卜子大，朱砂为衣。欲渐去者，每服五、七丸。欲骤行者， \n每服一、二十丸。用滚水，或煎药，或姜、醋、茶、蜜、茴香、史君煎汤为引送下。若利多 \n不止，可饮冷水一、二口即止。盖此药得热则行，得冷则止也。如治气湿实滞鼓胀，先用红 \n枣煮熟，取肉一钱许，随用七、八丸，甚者一、二十丸，同枣肉研烂，以热烧酒加白糖少许 \n送下。如治虫痛，亦用枣肉加服，止用清汤送下。 \n\\x太平丸\\x 治胸腹疼痛胀满，及食积气积血积，气疝血疝，邪实秘滞痛剧等证。此方借些 \n陈皮 浓朴 木香 乌药 白芥子 草豆蔻 三棱 蓬术（煨） 干姜 牙皂（炒断烟） \n泽泻（各三钱） \n以上十一味俱为细末。 \n巴豆（用滚汤泡去皮心膜，称足一钱，用水一碗，微火煮至半碗，将巴豆捞起，用乳钵 \n研极细，仍将前汤搀入研匀，然后量药多寡，入蒸饼浸烂捣丸，前药如绿豆大。每用三分， \n或五分，甚者一钱。） \n上随证用汤引送下。凡伤食停滞，即以本物汤下；妇人血气痛，红花汤或当归汤下；气 \n痛，陈皮汤；疝气，茴香汤；寒气，生姜汤；欲泻者，用热姜汤送下一钱。未利，再服。利 \n多不止，用冷水一、二口即止。 \n\\x敦阜丸\\x 治坚顽食积停滞肠胃，痛剧不行等证。 \n木香 山楂 麦芽 皂角 丁香 乌药 青皮 陈皮 泽泻（各五钱） 巴霜（一钱） \n上共为末，用生蒜头一两研烂，加熟水取汁，浸蒸饼捣丸，绿豆大。每服二、三十丸， \n随便用汤引送下。如未愈，徐徐渐加用之。 \n\\x猎虫丸\\x 治诸虫积胀痛黄瘦等病。 \n芜荑 雷丸 桃仁 干漆（炒烟尽） 雄黄（微炒） 锡灰 皂角（烧烟尽） 槟榔 使君子 \n（各等分） 轻粉（减半） 细榧肉（加倍） \n汤浸蒸饼为丸，绿豆大。每服五、七分，滚白汤下，陆续服之。如虫积坚固者，加巴豆霜与轻粉同。 \n\\x百顺丸\\x 治一切阳邪积滞。凡气积血积，虫积食积，伤寒实热秘结等证，但各为汤引， \n随宜送下，无往不利。 \n川大黄（锦纹者，一斤） 牙皂角（炒微黄，一两六钱） \n上为末，用汤浸蒸饼捣丸，绿豆大。每用五分，或一钱，或二、三钱，酌宜用引送下，或用蜜为丸亦可。 \n\n\n\n<目录>卷之五十一德集·新方八阵\n\n<篇名>散阵\n\n属性：\\x一柴胡饮\\x 一为水数，从寒散也。凡感四时不正之气，或为发热，或为寒热，或因劳因 \n怒，或妇人热入血室，或产后经后因冒风寒，以致寒热如疟等证，但外有邪而内兼火者，须 \n从凉散，宜此主之。 \n柴胡（二、三钱） 黄芩（一钱半） 芍药（二钱） 生地（一钱半） 陈皮（一钱半） 甘草（八分） \n水一钟半，煎七、八分，温服。如内热甚者，加连翘一、二钱随宜；如外邪甚者，加防 \n风一钱佐之；如邪结在胸而痞满者，去生地，加枳实一、二钱；如热在阳明而兼渴者，加天 \n花粉或葛根一、二钱；热甚者，加知母、石膏亦可。 \n\\x二柴胡饮\\x 二为火数，从温散也。凡遇四时外感，或其人元气充实，脏气素平无火，或 \n时逢寒胜之令，本无内热等证者，皆不宜妄用凉药，以致寒滞不散，则为害非浅，宜此主之。 \n陈皮（一钱半） 半夏（二钱） 细辛（一、二钱） 浓朴（一钱半） 生姜（三、五、七片） 柴胡（一钱半， \n或二、三钱） 甘草（八分） \n水一钟半，煎七、八分，温服。如邪盛者，可加羌活、白芷、防风、紫苏之属，择而用 \n之；如头痛不止者，加川芎一、二钱；如多湿者，加苍术；如阴寒气胜，必加麻黄一、二钱 \n，或兼桂枝，不必疑也。 \n\\x三柴胡饮\\x 三为木数，从肝经血分也。凡人素禀阴分不足，或肝经血少，而偶感风寒者 \n，或感邪不深，可兼补而散者，或病后产后感冒，有不得不从解散，而血气虚弱不能外达者，宜此主之。 \n柴胡（二、三钱） 芍药（一钱半） 炙甘草（一钱） 陈皮（一钱） 生姜（三、五片） 当归（二钱。溏泄 \n者，易以熟地） \n水一钟半，煎七、八分，温服。如微寒咳呕者，加半夏一、二钱。 \n\\x四柴胡饮\\x 四为金数，从气分也。凡人元气不足，或忍饥劳倦，而外感风寒，或六脉紧 \n数微细，正不胜邪等证，必须培助元气，兼之解散，庶可保全，宜此主之。若但知散邪，不 \n顾根本，未有不元气先败者，察之，慎之！ \n柴胡（一、二、三钱） 炙甘草（一钱） 生姜（三、五、七片） 当归（二、三钱，泻者少用） 人参 \n（二、三钱或五、七钱，酌而用之） \n水二钟，煎七、八分，温服。如胸膈滞闷者，加陈皮一钱。 \n\\x五柴胡饮\\x 五为土数，从脾胃也。脾土为五脏之本，凡中气不足而外邪有不散者，非此 \n不可。此与四柴胡饮相表里，但四柴胡饮止调气分，此则兼培血气以逐寒邪，尤切于时用者 \n也，神效不可尽述。凡伤寒疟疾痘疮，皆所宜用。 \n柴胡（一、二、三钱） 当归（二、三钱） 熟地（三、五钱） 白术（二、三钱） 芍药（钱半，炒用） \n炙甘草（一钱） 陈皮（酌用，或不必用） \n水一钟半，煎七分，食远热服。寒胜无火者，减芍药，加生姜三、五、七片，或炮干姜 \n一、二钱，或再加桂枝一、二钱则更妙；脾滞者，减白术；气虚者，加人参随宜；腰痛者， \n加杜仲；头痛者，加川芎；劳倦伤脾阳虚者，加升麻一钱。 \n\\x正柴胡饮\\x 凡外感风寒，发热恶寒，头疼身痛， 疟初起等证，凡血气平和，宜从 \n平散者，此方主之。 \n柴胡（一、二、三钱） 防风（一钱） 陈皮（一钱半） 芍药（二钱） 甘草（一钱） 生姜（三、五片） \n水一钟半，煎七、八分，热服。如头痛者，加川芎一钱；如热而兼渴者，加葛根一、二 \n钱；如呕恶者，加半夏一钱五分；如湿胜者，加苍术一钱；如胸腹有微滞者，加浓朴一钱； \n如寒气胜而邪不易解者，加麻黄一、二、三钱，去浮沫服之，或苏叶亦可。 \n\\x麻桂饮\\x 治伤寒瘟疫阴暑疟疾，凡阴寒气胜而邪有不能散者，非此不可。无论诸经四季 \n，凡有是证，即宜是药，勿谓夏月不可用也。不必浓盖，但取津津微汗透彻为度。此实麻黄 \n桂枝二汤之变方，而其神效则大有超出二方者，不可不为细察。 \n官桂（一、二钱） 当归（三、四钱） 炙甘草（一钱） 陈皮（随宜用，或不用亦可） 麻黄（二、三 \n钱） \n水一钟半，加生姜五、七片或十片，煎八分，去浮沫，不拘时服。若阴气不足者，加熟 \n地黄三、五钱；若三阳并病者，加柴胡二、三钱；若元气大虚，阴邪难解者，当以大温中饮 \n更迭为用。 \n\\x大温中饮\\x 凡患阳虚伤寒，及一切四时劳倦寒疫阴暑之气，身虽炽热，时犹畏寒，即在 \n夏月，亦欲衣披覆盖，或喜热汤，或兼呕恶泄泻，但六脉无力，肩背怯寒，邪气不能外达等 \n证，此元阳大虚，正不胜邪之候。若非峻补托散，则寒邪日深，必致不救，温中自可散寒， \n即此方也。服后畏寒悉除，觉有躁热，乃阳回作汗佳兆，不可疑之畏之。此外，凡以素禀薄 \n弱之辈，或感阴邪时疫，发热困倦，虽未见如前阴证，而热邪未甚者，但于初感时，即速用 \n此饮，连进二、三服，无不随药随愈，真神剂也。此方宜与理阴煎、麻桂饮相参用。 \n熟地（三、五、七钱） 冬白术（三、五钱） 当归（三、五钱，如泄泻者，不宜用，或以山药代 \n之） 人参（二、三钱，甚者一两，或不用亦可） 炙甘草（一钱） 柴胡（二、三、四钱） 麻黄（一、 \n二、三钱） 肉桂（一、二钱） 干姜（炒熟，一、二钱，或用煨生姜三、五、七片亦可） \n水二钟，煎七分，去浮沫，温服，或略盖取微汗。如气虚，加黄 二、三钱；如寒甚阳 \n虚者，加制附子一、二钱；头痛，加川芎或白芷、细辛；阳虚气陷，加升麻；如肚腹泄泻， \n宜少减柴胡，加防风、细辛亦可。尝见伤寒之治，惟仲景能知温散，如麻黄、桂枝等汤是也 \n；亦知补气而散，如小柴胡之属是也。至若阳根于阴，汗化于液，从补血而散，而云腾致雨 \n之妙，则仲景犹所未及，故予制此方，乃邪从营解第一义也，其功难悉，所当深察。 \n\\x柴陈煎\\x 治伤风兼寒，咳嗽发热，痞满多痰等证。 \n柴胡（二、三钱） 陈皮（一钱半） 半夏（二钱） 茯苓（二钱） 甘草（一钱） 生姜（三、五、七片） \n水一钟半，煎七分，食远温服。如寒胜者，加细辛七、八分；如风胜气滞者，加苏叶一 \n钱五分；如冬月寒甚者，加麻黄一钱五分；气逆多嗽者，加杏仁一钱；痞满气滞者，加白芥子五、七分。 \n\\x柴芩煎\\x 治伤寒表邪未解，外内俱热，泻痢烦渴喜冷，气壮脉滑数者，宜此主之。及疟 \n痢并行，内热去血，兼表邪发黄等证。 \n柴胡（二、三钱） 黄芩 栀子 泽泻 木通（各二钱） 枳壳（一钱五分） \n水二钟，煎八分，温服。如疟痢并行，鲜血纯血者，加芍药二钱，甘草一钱；如湿胜气 \n陷者，加防风一钱。 \n\\x柴苓饮\\x 治风湿发黄，发热身痛，脉紧，表里俱病，小水不利，中寒泄泻等证。 \n柴胡（二、三钱） 猪苓 茯苓 泽泻（各二钱） 白术（二、三钱） 肉桂（一、二、三钱） \n水一钟半，煎服。如寒邪胜者，加生姜三、五片；如汗出热不退者，加芍药一、二钱。 \n\\x柴胡白虎煎\\x 治阳明温热，表邪不解等证。 \n柴胡（二钱） 石膏（三钱） 黄芩（二钱） 麦冬（二钱） 细甘草（七分） \n水一钟半，加竹叶二十片，煎服。 \n\\x归葛饮\\x 治阳明温暑时证，大热大渴，津液枯涸，阴虚不能作汗等证。 \n当归（三、五钱） 干葛（二、三钱） \n水二钟，煎一钟，以冷水浸凉，徐徐服之，得汗即解。 \n\\x柴葛煎\\x 方在因阵十八。 \n治瘟毒表里俱热。 \n\\x秘传走马通圣散\\x 治伤寒阴邪初感等证。此方宜用于仓卒之时，其有质强而寒甚者俱可用。 \n麻黄 炙甘草（各一两） 雄黄（二钱） \n上为细末。每服一钱，热酒下，即汗。或加川芎二钱。 \n\\x秘传白犀丹\\x 发散外感瘟疫痈毒等证。 \n白犀角 麻黄（去节） 山茨菇 玄明粉 血竭 甘草（各一钱） 雄黄（八分） \n上共为末，用老姜汁拌丸，如枣核大，外以红枣去核，将药填入枣内，用薄纸裹十五层 \n，入砂锅内炒令烟尽为度，取出去枣肉，每药一钱，入冰片一分，麝香半分，研极细，瓷罐 \n收贮。用时以角簪蘸麻油粘药点眼大角。轻者只点眼角，重者仍用些须吹鼻，男先左，女先 \n右，吹点皆同。如病甚者，先吹鼻，后点眼。点后蜷足坐起，用被齐项暖盖半炷香时 \n，自当汗出邪解。如汗不得出，或汗不下达至腰者不治。 \n又一制法，将前药用姜汁拌作二丸，以乌金纸两层包定，外捣红枣肉如泥，包药外约半 \n指浓，晒干，入砂锅内，再覆以砂盆，用盐泥固缝，但留一小孔以候烟色，乃上下加炭火， \n先文后武，待五色烟尽，取出去枣肉，每 过药一钱，止加冰片二分，不用麝香。忌生冷、 \n面食、鱼腥、七情。 \n上药，凡伤寒瘟疫，及小儿痘毒壅闭，痈毒，吼喘，及阴毒冷气攻心，或妇人吹乳，或 \n眼目肿痛，鼻壅闭塞，并皆治之。 \n\\x归柴饮\\x 治营虚不能作汗，及真阴不足，外感寒邪难解者，此神方也。如大便多溏者， \n以冬术代当归亦佳。 \n当归（一两） 柴胡（五钱） 炙甘草（八分） \n水一钟半，煎服。或加生姜三、五片。或加陈皮一钱。或加人参。 \n\n\n\n<目录>卷之五十一德集·新方八阵\n\n<篇名>寒阵\n\n属性：\\x保阴煎\\x 治男妇带浊遗淋，色赤带血，脉滑多热，便血不止，及血崩血淋，或经期太早 \n，凡一切阴虚内热动血等证。 \n生地 熟地 芍药（各二钱） 山药 川续断 黄芩 黄柏（各一钱半） 生甘草（一钱） \n水二钟，煎七分，食远温服。如小水多热，或兼怒火动血者，加焦栀子一、二钱；如夜 \n热身热，加地骨皮一钱五分；如肺热多汗者，加麦冬、枣仁；如血热甚者，加黄连一钱五分 \n；如血虚血滞，筋骨肿痛者，加当归二、三钱；如气滞而痛，去熟地，加陈皮、青皮、丹皮 \n、香附之属；如血脱血滑，及便血久不止者，加地榆一、二钱，或乌梅一、二个，或百药煎 \n一、二钱，文蛤亦可；如少年，或血气正盛者，不必用熟地、山药；如肢节筋骨疼痛或肿者 \n，加秦艽、丹皮各一、二钱。 \n\\x加减一阴煎\\x 方在补阵九。 \n治水亏火胜之甚者。 \n\\x抽薪饮\\x 治诸凡火炽盛而不宜补者。 \n黄芩 石斛 木通 栀子（炒） 黄柏（各一、二钱） 枳壳（钱半） 泽泻（钱半） 细甘草（三分） \n水一钟半，煎七分，食远温服。内热甚者，冷服更佳。如热在经络肌肤者，加连翘、天 \n花粉以解之；热在血分大小肠者，加槐蕊、黄连以清之；热在阳明头面，或躁烦便实者，加 \n生石膏以降之；热在下焦，小水痛涩者，加草龙胆、车前以利之；热在阴分，津液不足者， \n加门冬、生地、芍药之类以滋之；热在肠胃实结者，加大黄、芒硝以通之。 \n\\x徙薪饮\\x 治三焦凡火，一切内热，渐觉而未甚者，先宜清以此剂。其甚者，宜抽薪饮。 \n陈皮（八分） 黄芩（二钱） 麦冬 芍药 黄柏 茯苓 牡丹皮（各一钱半） \n水一钟半，煎七分，食远温服。如多郁气逆伤肝，胁肋疼痛，或致动血者，加青皮、栀子。 \n\\x大厘清饮\\x 治积热闭结，小水不利，或致腰腿下部极痛，或湿热下利，黄胆，溺血，邪 \n热蓄血腹痛淋闭等证。 \n茯苓 泽泻 木通（各二钱） 猪苓 栀子（或倍之） 枳壳 车前子（各一钱） \n水一钟半，煎八分，食远温服。如内热甚者，加黄芩、黄柏、草龙胆之属；如大便坚硬胀 \n满者，加大黄二、三钱；如黄胆小水不利，热甚者，加茵陈二钱；如邪热蓄血腹痛者 \n，加红花、青皮各一钱五分。 \n\\x清流饮\\x 治阴虚挟热泻痢，或发热，或喜冷，或下纯红鲜血，或小水痛赤等证。 \n生地 芍药 茯苓 泽泻（各二钱） 当归（一、二钱） 甘草（一钱） 黄芩 黄连（各半钱） 枳壳 \n（一钱） \n水一钟半，煎服。如热甚者，加黄柏；小水热痛者，加栀子。 \n\\x化阴煎\\x 治水亏阴涸，阳火有余，小便癃闭，淋浊疼痛等证。 \n生地黄 熟地黄 牛膝 猪苓 泽泻 生黄柏 生知母（各二钱） 绿豆（三钱） 龙胆草（钱半） \n车前子（一钱） \n水二钟，加食盐少许，用文武火煎八分，食前温服，或冷服。若水亏居多，而阴气大有 \n不足者，可递加熟地黄，即用至一、二两亦可。 \n\\x茵陈饮\\x 治挟热泄泻热痢，口渴喜冷，小水不利，黄胆湿热闭涩等证。 \n茵陈 焦栀子 泽泻 青皮（各三钱） 甘草（一钱） 甘菊花（二钱） \n用水三、四钟，煎两钟，不时陆续饮之。治热泻者，一服可愈。 \n\\x清膈煎\\x 治痰因火动，气壅喘满，内热烦渴等证。 \n陈皮（钱半） 贝母（二、三钱，微敲破） 胆星（一、二钱） 海石（二钱） 白芥子（五、七分） 木通 \n（二钱） \n水一钟半，煎七分，温服。如火盛痰不降者，加童便一小钟；如渴甚者，加天花粉一钱 \n；如热及下焦，小水不利者，加栀子一钱半；如热在上焦，头面红赤，烦渴喜冷者，加生石 \n膏二、三钱；如痰火上壅而小水不利者，加泽泻一、二钱；如痰火闭结，大便不通而兼胀满 \n者，加大黄数钱，或朴硝一、二钱，酌宜用之。 \n\\x化肝煎\\x 治怒气伤肝，因而气逆动火，致为烦热胁痛，胀满动血等证。 \n青皮 陈皮（各二钱） 芍药（二钱） 丹皮 栀子（炒） 泽泻（各钱半，如血见下部者，以甘草 \n代之） 土贝母（二、三钱） \n水一钟半，煎七、八分，食远温服。如大便下血者，加地榆；小便下血者，加木通，各 \n一钱五分；如兼寒热，加柴胡一钱；如火盛，加黄芩一、二钱；如胁腹胀痛，加白芥子一钱 \n；胀滞多者，勿用芍药。 \n\\x安胃饮\\x 治胃火上冲，呃逆不止。 \n陈皮 山楂 麦芽 木通 泽泻 黄芩 石斛 \n水一钟半，煎七分，食远服。如胃火热甚，脉滑实者，加石膏。 \n\\x玉女煎\\x 治水亏火盛，六脉浮洪滑大，少阴不足，阳明有余，烦热干渴，头痛牙疼，失 \n血等证，如神、如神。若大便溏泄者，乃非所宜。 \n生石膏（三、五钱） 熟地（三、五钱或一两） 麦冬（二钱） 知母 牛膝（各钱半） \n水一钟半，煎七分，温服或冷服。如火之盛极者，加栀子、地骨皮之属亦可；如多汗多 \n渴者，加北五味十四粒；如小水不利，或火不能降者，加泽泻一钱五分，或茯苓亦可；如金 \n水俱亏，因精损气者，加人参二、三钱尤妙。 \n\\x太清饮\\x 治胃火烦热，狂斑呕吐等证。可与白虎汤出入酌用。 \n知母 石斛 木通（各一钱半） 石膏（生用，五、七钱） \n水一钟半，煎七分，温服或冷服。或加麦门冬。 \n\\x绿豆饮\\x 凡热毒劳热，诸火热极不能退者，用此最妙。 \n用绿豆不拘多寡，宽汤煮糜烂，入盐少许，或蜜亦可。待冰冷，或浓或稀或汤，任意饮 \n食之，日或三、四次不拘。此物性非苦寒，不伤脾气，且善于解毒除烦，退热止渴，大利小 \n水，乃浅易中之最佳最捷者也。若火盛口甘，不宜浓味，但略煮半熟，清汤冷冻饮料之，尤善除烦清火。 \n\\x玉泉散\\x 亦名一六甘露散。治阳明内热，烦渴头痛，二便闭结，温疫斑黄，及热痰喘嗽 \n等证。此益元散之变方也，其功倍之。 \n石膏（六两，生用） 粉甘草（一两） \n上为极细末。每服一、二、三钱，新汲水或热汤，或人参汤调下。此方加朱砂三钱亦妙。 \n\\x悉尼浆\\x 解烦热，退阴火，此生津止渴之妙剂也。 \n用清香甘美大梨，削去皮，别用大碗盛清冷甘泉，将梨薄切浸于水中，少顷，水必甘美 \n，但频饮其水，勿食其 ，退阴火极速也。 \n\\x滋阴八味丸\\x 治阴虚火盛，下焦湿热等证。此方变丸为汤，即名滋阴八味煎。 \n山药（四两） 丹皮（三两） 白茯苓（三两） 山茱萸（肉，四两） 泽泻（三两） 黄柏（盐水炒，三两） \n熟地黄（八两，蒸捣） 知母（盐水炒，三两） \n上加炼蜜捣丸，梧桐子大。或空心，或午前，用滚白汤，或淡盐汤送下百余丸。 \n\\x约阴丸\\x 治妇人血海有热，经脉先期或过多者，或兼肾火而带浊不止，及男妇大肠血热便红等证。 \n当归 白术（炒） 芍药（酒炒） 生地 茯苓 地榆 黄芩 白石脂（醋 粹） 北五味 \n丹参 川续断（各等分） \n上为末，炼蜜丸服。火甚者，倍用黄芩；兼肝肾之火甚者，仍加知母、黄柏各等分；大 \n肠血热便红者，加黄连、防风各等分。 \n\\x服蛮煎\\x 此方性味极轻极清，善入心肝二脏，行滞气，开郁结，通神明，养正除邪，大有奇妙。 \n生地 麦门冬 芍药 石菖蒲 石斛 川丹皮（极香者） 茯神（各二钱） 陈皮（一钱） 木通 \n知母（各一钱半） \n水一钟半，煎七分，食远服。如痰胜多郁者，加贝母二钱；痰盛兼火者，加胆星一钱五 \n分；阳明火盛，内热狂叫者，加石膏二、三钱；便结胀满多热者，玄明粉二、三钱调服，或 \n暂加大黄亦可；气虚神困者，加人参随宜。 \n\\x约营煎\\x 治血热便血，无论脾胃、小肠、大肠、膀胱等证，皆宜用此。 \n生地 芍药 甘草 续断 地榆 黄芩 槐花 荆芥穗（炒焦） 乌梅（二个） \n水一钟半，煎七分，食前服。如下焦火盛者，可加栀子、黄连、龙胆草之属；如气虚者 \n，可加人参、白术；如气陷者，加升麻、防风。 \n\n\n\n<目录>卷之五十一德集·新方八阵\n\n<篇名>热阵\n\n属性：\\x四味回阳饮\\x 治元阳虚脱，危在顷刻者。 \n人参（一、二两） 制附子（二、三钱） 炙甘草（一、二钱） 炮干姜（二、三钱） \n水二钟，武火煎七、八分，温服，徐徐饮之。 \n\\x六味回阳饮\\x 治阴阳将脱等证。 \n人参（一、二两或数钱） 制附子（二、三钱） 炮干姜（二、三钱） 炙甘草（一钱） 熟地（五钱，或 \n一两） 当归身（三钱，如泄泻者，或血动者，以冬术易之，多多益善） \n水二钟，武火煎七、八分，温服。如肉振汗多者，加炙黄 四、五钱或一两，或冬白术 \n三、五钱；如泄泻者，加乌梅二枚，或北五味二十粒亦可；如虚阳上浮者，加茯苓二钱；如 \n肝经郁滞者，加肉桂二、三钱。 \n\\x理阴煎\\x 此理中汤之变方也。凡脾肾中虚等证，宜刚燥者，当用理中、六君之类；宜温 \n润者，当用理阴、大营之类。欲知调补，当先察此。此方通治真阴虚弱，胀满呕哕，痰饮恶 \n心，吐泻腹痛，妇人经迟血滞等证。又凡真阴不足，或素多劳倦之辈，因而忽感寒邪，不能 \n解散，或发热，或头身疼痛，或面赤舌焦，或虽渴而不喜冷冻饮料，或背心肢体畏寒，但脉见无 \n力者，悉是假热之证。若用寒凉攻之必死，宜速用此汤，照后加减以温补阴分，托散表邪， \n连进数服，使阴气渐充，则汗从阴达，而寒邪不攻自散，此最切于时用者也，神效不可尽述 \n熟地（三、五、七钱或一、二两） 当归（二、三钱或五、七钱） 炙甘草（一、二钱） 干姜（炒 \n黄色，一、二、三钱）或加肉桂（一、二钱） \n水二钟，煎七、八分，热服。此方加附子，即名附子理阴煎；再加人参，即名六味回阳 \n饮。治命门火衰，阴中无阳等证。若风寒外感，邪未入深，但见发热身痛，脉数不洪，凡内 \n无火证，素禀不足者，但用此汤加柴胡一钱半或二钱，连进一、二服，其效如神；若寒凝阴 \n盛而邪有难解者，必加麻黄一、二钱，放心用之，或不用柴胡亦可，恐其清利也。此寒邪初 \n感温散第一方，惟仲景独知此义。第仲景之温散，首用麻黄、桂枝二汤，余之温散，即以理 \n阴煎及大温中饮为增减，此虽一从阳分，一从阴分，其迹若异，然一逐于外，一托于内，而 \n用温则一也。学人当因所宜，酌而用之。若阴胜之时，外感寒邪，脉细恶寒，或背畏寒者， \n乃太阳少阴证也，加细辛一、二钱，甚者再加附子一、二钱，真神剂也。或并加柴胡以助之 \n亦可。若阴虚火盛，其有内热不宜用温，而气血俱虚，邪不能解者，宜去姜、桂，单以三味 \n加减与之，或只加人参亦可。若治脾肾两虚，水泛为痰，或呕或胀者，于前方加茯苓一钱半 \n，或加白芥子五分以行之；若泄泻不止及肾泄者，少用当归，或并去之，加山药、扁豆、吴 \n茱萸、破故纸、肉豆蔻、附子之属；若腰腹有痛，加杜仲、枸杞；若腹有胀滞疼痛，加陈皮 \n、木香、砂仁之属。 \n\\x养中煎\\x 治中气虚寒，为呕为泄者。 \n人参（一、二、三钱） 山药（炒，二钱） 白扁豆（炒，二、三钱） 炙甘草（一钱） 茯苓（二钱） 干 \n姜（炒黄，一、二钱） \n水二钟，煎七分，食远温服。如嗳腐气滞者，加陈皮一钱，或砂仁四分；如胃中空虚觉 \n馁者，加熟地三、五钱。 \n\\x温胃散\\x 治中寒呕吐，吞酸泄泻，不思饮食，及妇人脏寒呕恶，胎气不安等证。 \n人参（一、二、三钱，或一两） 白术（炒，一、二钱，或一两） 扁豆（二钱，炒） 陈皮（一钱，或不 \n用） 干姜（炒焦，一、二、三钱） 炙甘草（一钱） 当归（一、二钱，滑泄者勿用） \n水二钟，煎七分，食远温服。如下寒带浊者，加破故纸一钱；如气滞或兼胸腹痛者，加 \n藿香、丁香、木香、白豆蔻、砂仁、白芥子之属；如兼外邪及肝肾之病者，加桂枝、肉桂， \n甚者加柴胡；如脾气陷而身热者，加升麻五、七分；如水泛为痰而胸腹痞满者，加茯苓一、 \n二钱；如脾胃虚极，大呕大吐不能止者，倍用参术，仍加胡椒二、三分许，煎熟徐徐服之。 \n\\x五君子煎\\x 治脾胃虚寒，呕吐泄泻而兼湿者。 \n人参（二、三钱） 白术 茯苓（各二钱） 炙甘草（一钱） 干姜（炒黄，一、二钱） \n水一钟半，煎服。 \n\\x六味异功煎\\x 治证同前而兼微滞者。 \n即前方加陈皮一钱。此即五味异功散加干姜也。 \n\\x参姜饮\\x 治脾肺胃气虚寒，呕吐咳嗽气短，小儿吐乳等证。 \n人参（三 五钱或倍之） 炙甘草（三、五分） 干姜（炮，五分或一、二钱，或用煨生姜三、五 \n片） \n水一钟半，煎七、八分，徐徐服之。此方或陈皮，或荜茇，或茯苓，皆可酌而佐之。 \n\\x胃关煎\\x 治脾肾虚寒作泻，或甚至久泻，腹痛不止，冷痢等证。 \n熟地（三、五钱，或一两） 山药（炒，二钱） 白扁豆（炒，二钱） 炙甘草（一、二钱） 焦干姜（一 \n、二、三钱） 吴茱萸（制，五、七分） 白术（炒，一、二、三钱） \n水二钟，煎七分，食远温服。泻甚者，加肉豆蔻一、二钱，面炒用，或破故纸亦可；气 \n虚势甚者，加人参随宜用；阳虚下脱不固者，加制附子一、二、三钱；腹痛甚者，加木香七 \n、八分，或加浓朴八分；滞痛不通者，加当归二、三钱；滑脱不禁者，加乌梅二个，或北五 \n味子二十粒；若肝邪侮脾者，加肉桂一、二钱。 \n\\x佐关煎\\x 治生冷伤脾，泻痢未久，肾气未损者，宜用此汤以去寒湿，安脾胃。此胃关煎之佐者也。 \n浓朴（炒，一钱） 陈皮（炒，一钱） 山药（炒，二钱） 扁豆（炒，二钱） 炙甘草（七分） 猪苓（二钱） \n泽泻（二钱） 干姜（炒，一、二钱） 肉桂（一、二钱） \n水一钟半，煎服。如腹痛甚者，加木香三、五分，或吴茱萸亦可；如泻甚不止者，或破 \n故纸，或肉豆蔻，皆可加用。 \n\\x抑扶煎\\x 治气冷阴寒，或暴伤生冷致成泻痢，凡初起血气未衰，脾肾未败，或胀痛，或 \n呕恶，皆宜先用此汤。此胃关煎表里药也，宜察虚实用之。其有寒湿伤脏，霍乱邪实者，最宜用此。 \n浓朴 陈皮 乌药（各一钱五分） 猪苓（二钱） 泽泻（二钱） 炙甘草（一钱） 干姜（炮，一、二钱） \n吴茱萸（制，五、七分） \n水一钟半，煎七分，食远温服。如气滞痛甚者，加木香五、七分，或砂仁亦可；如血虚 \n多痛者，加当归二钱；如寒湿胜者，加苍术一钱半。 \n\\x四维散\\x 治脾肾虚寒，滑脱之甚，或泄痢不能止，或气虚下陷，二阴血脱不能禁者，无出此方之右。 \n人参（一两） 制附子（二钱） 干姜（炒黄，二钱） 炙甘草（一、二钱） 乌梅肉（五分或一钱，酌其 \n味之微甚，随病患之意而用之。或不用此，即四味回阳饮也） \n上为末，和匀，用水拌湿，蒸一饭顷，取起烘干，再为末。每服一、二钱，温汤调下。 \n\\x镇阴煎\\x 治阴虚于下，格阳于上，则真阳失守，血随而溢，以致大吐大衄，六脉细脱， \n手足厥冷，危在顷刻而血不能止者，速宜用此，使孤阳有归，则血自安也。如治格阳喉痹上 \n热者，当以此汤冷服。 \n熟地（一、二两） 牛膝（二钱） 炙甘草（一钱） 泽泻（一钱半） 肉桂（一、二钱） 制附子（五、七分 \n，或一、二、三钱） \n水二钟，速煎服。如兼呕恶者，加干姜炒黄一、二钱；如气脱倦言而脉弱极者，宜速速 \n多加人参，随宜用之。 \n\\x归气饮\\x 治气逆不顺，呃逆呕吐，或寒中脾肾等证。 \n熟地（三、五钱） 茯苓（二钱） 扁豆（二钱） 干姜（炮） 丁香 陈皮（各一钱） 藿香（一钱五分） \n炙甘草（八分） \n水一钟半，煎七分，食远温服。中气寒甚者，加制附子；肝肾寒者，加吴茱萸、肉桂，或加当归。 \n\\x暖肝煎\\x 治肝肾阴寒，小腹疼痛，疝气等证。 \n当归（二、三钱） 枸杞（三钱） 茯苓（二钱） 小茴香（二钱） 肉桂（一、二钱） 乌药（二 \n钱） 沉香（一钱，或木香亦可） \n水一钟半，加生姜三、五片，煎七分，食远温服。如寒甚者，加吴茱萸、干姜；再甚者，加附子。 \n\\x寿脾煎\\x 一名摄营煎。治脾虚不能摄血等证。凡忧思郁怒积劳，及误用攻伐等药，犯损 \n脾阴，以致中气亏陷，神魂不宁，大便脱血不止，或妇人无火崩淋等证，凡兼呕恶，尤为危 \n候，速宜用此，单救脾气，则统摄固而血自归源。此归脾汤之变方，其效如神。若犯此证而 \n再用寒凉，则胃气必脱，无不即毙者。 \n白术（二、三钱） 当归（二钱） 山药（二钱） 炙甘草（一钱） 枣仁（钱半） 远志（制，三、五分） 干 \n姜（炮，一、二、三钱） 莲肉（去心，炒，二十粒） 人参（随宜一、二钱，急者用一两） \n水二钟，煎服。如血未止，加乌梅二个，凡畏酸者不可用，或加地榆一钱半亦可；滑脱 \n不禁者，加醋炒文蛤一钱；下焦虚滑不禁，加鹿角霜二钱为末，搅入药中服之；气虚甚者， \n加炙黄 二、三钱；气陷而坠者，加炒升麻五、七分，或白芷亦可；兼溏泄者，加补骨脂一 \n钱炒用；阳虚畏寒者，加制附子一、二、三钱；血去过多，阴虚气馁，心跳不宁者，加熟地 \n七、八钱，或一、二两。 \n\\x三气饮\\x 治血气亏损，风寒湿三气乘虚内侵，筋骨历节痹痛之极，及痢后鹤膝风痛等症。 \n当归 枸杞 杜仲（各二钱） 熟地（三钱，或五钱） 牛膝 茯苓 芍药（酒炒） 肉桂（各一钱） \n北细辛（或代以独活） 白芷 炙甘草（各一钱） 附子（随宜一、二钱） \n水二钟，加生姜三片，煎服。如气虚者，加人参、白术随宜；风寒胜者，加麻黄一、二 \n钱。此饮亦可浸酒，大约每药一斤，可用烧酒六、七升，浸十余日，徐徐服之。 \n\\x五德丸\\x 治脾肾虚寒，飧泄 溏等证，或暴伤生冷，或受时气寒湿，或酒湿伤脾，腹痛 \n作泄，或饮食失宜，呕恶痛泄，无火等证。 \n补骨脂（四两，酒炒） 吴茱萸（制，二两） 木香（二两） 干姜（四两，炒） 北五味（二两，或以肉 \n豆蔻代之，面炒用。或用乌药亦可） \n汤浸蒸饼丸，桐子大。每服六、七十丸，甚者百余丸，滚白汤或人参汤，或米汤俱可下 \n。腹痛多呕者，加胡椒二两更妙。 \n\\x七德丸\\x 治生冷伤脾，初患泻痢，腹胀疼痛，凡年壮气血未衰，及寒湿食滞，凡宜和胃 \n者，无不神效。此即佐关煎之偏裨也。 \n台乌药 吴茱萸（制） 干姜（炒黄） 苍术（炒，各二两） 木香 茯苓（各一两） 补骨脂（炒，四两） \n神曲糊丸，桐子大。每服七、八十丸，或百丸，滚白汤送下。 \n\\x复阳丹\\x 治阴寒呕吐泄泻，腹痛寒疝等证。 \n附子（制） 炮姜 胡椒 北五味（炒） 炙甘草（各一两） 白面（二两，炒熟） \n上为末，和匀，入温汤捣丸，桐子大。每服一钱，随证用药引送下。 \n\\x黄芽丸\\x 治脾胃虚寒，或饮食不化，或时多胀满泄泻，吞酸呕吐等证。此药随身常用甚妙。 \n人参（二两） 焦干姜（三钱） \n炼白蜜为丸，芡实大。常嚼服之。 \n\\x一气丹\\x 治脾肾虚寒，不时易泻腹痛，阳痿怯寒等证。此即参附汤之变方也。 \n人参 制附子（各等分） \n炼白蜜丸，如绿豆大。每用滚白汤送下三、五分，或一钱。凡药饵不便之处，或在途次，随带此丹最妙。 \n\\x九气丹\\x 治脾肾虚寒如五德丸之甚者。 \n熟地（八两） 制附子（四两） 肉豆蔻（面炒，二两） 焦姜 吴茱萸 补骨脂（酒炒） 荜茇（炒） \n五味子（炒，各二两） 粉甘草（炒，一两） \n炼白蜜为丸，或山药糊丸，如桐子大。每服六、七十丸、或百丸，滚白汤下。如气虚者 \n，加人参，或二两，或四两，尤妙甚。 \n\\x温脏丸\\x 治诸虫积既逐而复生者，多由脏气虚寒，宜健脾胃以杜其源，此方主之。 \n人参（随宜用，无亦可） 白术（米泔浸炒） 当归（各四两） 芍药（酒炒焦） 茯苓 川椒（ \n去合口者，炒出汗） 细榧肉 使君子（煨，取肉） 槟榔（各二两） 干姜（炮） 吴茱萸（汤炮一 \n宿，炒，各一两） \n上为末，神曲糊为丸，桐子大。每服五、七十丸，或百丸，饥时白汤下。如脏寒者，加 \n制附子一、二两；脏热者，加黄连一、二两。 \n\\x圣术煎\\x 治饮食偶伤，或吐或泻，胸膈痞闷，或胁肋疼痛，或过用克伐等药，致伤脏气 \n，有同前证而脉无力，气怯神倦者，速宜用此，不得因其虚痞虚胀而畏用白术，此中虚实之 \n机，贵乎神悟也。若痛胀觉甚者，即以此煎送神香散最妙。若用治寒湿泻痢呕吐，尤为圣药。 \n白术（用冬术味甘佳者，五、六、七、八钱，炒，或一、二两） 干姜（炒） 肉桂（各一、二钱） \n陈皮（酌用，或不用） \n水一钟半，煎七分，温热服。若治虚寒泻痢呕吐等证，则人参、炙甘草之类，当任意加 \n用；若治中虚感寒，则麻黄、柴胡亦任意加用。 \n\n\n\n<目录>卷之五十一德集·新方八阵\n\n<篇名>固阵\n\n属性：\\x秘元煎\\x 治遗精带浊等病。此方专主心脾。 \n远志（八分，炒） 山药（二钱，炒） 芡实（二钱，炒） 枣仁（炒，捣碎，二钱） 白术（炒） 茯苓 \n（各钱半） 炙甘草（一钱） 人参（一、二钱） 五味（十四粒，畏酸者去之） 金樱子（去核，二钱） \n水二钟，煎七分，食远服。此治久遗无火，不痛而滑者，乃可用之。如尚有火觉热者， \n加苦参一、二钱；如气大虚者，加黄 一、二、三钱。 \n\\x固阴煎\\x 治阴虚滑泄，带浊淋遗，及经水因虚不固等证。此方专主肝肾。 \n人参（随宜） 熟地（三、五钱） 山药（炒，二钱） 山茱萸（一钱半） 远志（七分，炒） 炙甘草（一 \n、二钱） 五味（十四粒） 菟丝子（炒香，二、三钱） \n水二钟，煎七分，食远温服。如虚滑遗甚者，加金樱子肉二、三钱，或醋炒文蛤一钱， \n或乌梅二个；如阴虚微热而经血不固者，加川续断二钱；如下焦阳气不足，而兼腹痛溏泄者 \n，加补骨脂、吴茱萸之类，随宜用之；如肝肾血虚，小腹痛而血不归经者，加当归二、三钱 \n。如脾虚多湿，或兼呕恶者，加白术一、二钱；如气陷不固者，加炒升麻一钱；如兼心虚不 \n眠，或多汗者，加枣仁二钱，炒用。 \n\\x菟丝煎\\x 治心脾气弱，凡遇思虑劳倦即苦遗精者，宜此主之。 \n人参（二、三钱） 山药（炒，二钱） 当归（钱半） 菟丝子（制炒，四、五钱） 枣仁（炒） 茯苓（各钱 \n半） 炙甘草（一钱或五分） 远志（制，四分） 鹿角霜（为末，每服加入四、五匙） \n上用水一钟半，煎成，加鹿角霜末调服，食前。或加白术一、二钱。 \n\\x惜红煎\\x 治妇人经血不固，崩漏不止，及肠风下血等证。 \n白术 山药 炙甘草 地榆 续断（炒） 芍药（炒） 北五味（十四粒） 荆芥穗（炒） 乌梅（二枚） \n水一钟半，煎七分，食远服。如火盛者，加黄连、黄芩；如脾虚兼寒，脾泄者，加破故纸、人参。 \n\\x苓术菟丝丸\\x 治脾肾虚损，不能收摄，以致梦遗精滑困倦等证。 \n白茯苓 白术（米泔洗，炒） 莲肉（去心，各四两） 五味（二两，酒蒸） 山药（炒，二两） \n杜仲（酒炒，三两） 炙甘草（五钱） 菟丝子（用好水淘净，入陈酒浸一日，文火煮极烂，捣为饼，焙干为末，十两） \n上用山药末以陈酒煮糊为丸，桐子大。空心滚白汤或酒下百余丸。如气虚神倦，不能收 \n摄者，加人参三、四两尤妙。 \n\\x固真丸\\x 治梦遗精滑。 \n菟丝子（一斤，淘洗净，用好酒浸三日，煮极熟，捣膏，晒干。或用净白布包蒸亦佳） 牡 \n蛎（ ，四两） 金樱子（去子，蒸熟，四两） 茯苓（酒拌蒸晒，四两） \n上蜜丸，空心好酒送下三钱，或盐汤亦可。 \n\\x粘米固肠糕\\x 治脾胃虚寒，或因食滞气滞，腹痛泄泻久不止者，多服自效。 \n用白糯米滚汤淘洗，炒香熟为粉，每粉一两，加干姜末炒熟者二分半，白糖二钱，拌匀 \n，于饥时用滚水调服一、二两。如有微滞者，加陈皮炒末二分，或砂仁末一分俱妙。一法用 \n陈老米粉亦妙。此与古方固类四十九泄泻经验方大同小异，并补阵养元粉略同。 \n\\x玉关丸\\x 治肠风血脱，崩漏带浊不固，诸药难效者，宜用此丸兼煎药治之。及泻痢滑泄 \n不能止者，亦宜用此。 \n白面（炒熟，四两） 枯矾（二两） 文蛤（醋炒黑，二两） 北五味（一两，炒） 诃子（二两，半生半炒） \n上为末，用熟汤和丸，梧子大。以温补脾肾等药随证加减煎汤送下，或人参汤亦可。如 \n血热妄行者，以凉药送下。 \n\\x巩堤丸\\x 治膀胱不藏，水泉不止，命门火衰，小水不禁等证。 \n熟地（二两） 菟丝子（酒煮，二两） 白术（炒，二两） 北五味 益智仁（酒炒） 故纸（酒炒） \n附子（制） 茯苓 家韭子（炒，各一两） \n上为末，山药糊丸，如桐子大。每服百余丸，空心滚汤，或温酒下。如兼气虚，必加人参一、二两更妙。 \n\\x敦阜糕\\x 治久泻久痢，肠滑不固妙方，及妇人带浊最佳。 \n白面（炒黄，二两） 冬白术（炒黄，一两） 破故纸（炒，五钱） \n上共为末。临服时加白糖，随宜用清滚汤，食前调服如糕法。如胃寒者，每一两加干姜 \n炒末五分或一钱；如气有不顺，或痛，或呕，每末一两，加丁香一钱；如滑泄不禁者，每两 \n加栗壳末炒黄一钱。若以作丸，则宜三味等分用，即名敦阜丸。 \n\n\n\n<目录>卷之五十一德集·新方八阵\n\n<篇名>因阵\n\n属性：\\x逍遥饮\\x 治妇人思郁过度，致伤心脾冲任之源，血气日枯，渐至经脉不调者。 \n当归（二、三钱） 芍药（钱半） 熟地（三、五钱） 枣仁（二钱，炒） 茯神（钱半） 远志（制，三、五 \n分） 陈皮（八分） 炙甘草（一钱） \n水二钟，煎七分，食远温服。如气虚者，加人参一、二钱；如经水过期兼痛滞者，加酒 \n炒香附一、二钱。 \n\\x决津煎\\x 治妇人血虚经滞，不能流畅而痛极者，当以水济水，若江河一决而积垢皆去， \n宜用此汤，随证加减主之。此用补为泻之神剂也。如气虚者，宜少用香、陈之类，甚者不用亦可。 \n当归（三、五钱，或一两） 泽泻（一钱半） 牛膝（二钱） 肉桂（一、二、三钱） 熟地（二、三钱或五 \n、七钱，或不用亦可） 乌药（一钱，如气虚者，不用亦可） \n水二钟，煎七、八分，食前服。如呕恶者，加焦姜一、二钱；如阴滞不行者，非加附子 \n不可；如气滞而痛胀者，加香附一、二钱，或木香七、八分；如血滞血涩者，加酒炒红花一 \n、二钱；如小腹不暖而痛极者，加吴茱萸七、八分；如大便结涩者，加肉苁蓉一、二、三钱 \n，微者以山楂代之。 \n\\x五物煎\\x 治妇人血虚凝滞，蓄积不行，小腹痛急，产难经滞，及痘疮血虚寒滞等证，神 \n效。此即四物汤加肉桂也。 \n当归（三、五、七钱） 熟地（三、四钱） 芍药（二钱，酒炒） 川芎（一钱） 肉桂（一、二、三钱） \n水一钟半，煎服。兼胃寒或呕恶者，加干姜炮用；水道不利，加泽泻或猪苓；气滞者， \n加香附或丁香、木香、砂仁、乌药；阴虚疝痛者，加小茴香；血瘀不行，脐下若覆杯，渐成 \n积块者，加桃仁或酒炒红花；痘疮血虚寒胜，寒邪在表者，加细辛、麻黄、柴胡、紫苏之属。 \n\\x调经饮\\x 治妇人经脉阻滞，气逆不调，多痛而实者。 \n当归（三、五钱） 牛膝（二钱） 山楂（一、二钱） 香附（二钱） 青皮 茯苓（各一钱半） \n水二钟，煎七分，食远服。如因不避生冷而寒滞其血者，加肉桂、吴茱萸之类；如兼胀 \n闷者，加浓朴一钱，或砂仁亦可；如气滞者，加乌药二钱，或痛在小腹者，加小茴香一钱半。 \n\\x通瘀煎\\x 治妇人气滞血积，经脉不利，痛极拒按，及产后瘀血实痛，并男妇血逆血厥等证。 \n归尾（三、五钱） 山楂 香附 红花（新者，炒黄，各二钱） 乌药（一、二钱） 青皮（钱半） 木 \n香（七分） 泽泻（钱半） \n水二钟，煎七分，加酒一、二小钟，食前服。兼寒滞者，加肉桂一钱，或吴茱萸五分； \n火盛内热，血燥不行者，加炒栀子一、二钱；微热血虚者，加芍药二钱；血虚涩滞者，加牛 \n膝；血瘀不行者，加桃仁三十粒，去皮尖用，或加苏木、玄胡索之类，瘀极而大便结燥者， \n加大黄一、二、三钱，或加芒硝、蓬术亦可。 \n\\x胎元饮\\x 治妇人冲任失守，胎元不安不固者，随证加减用之。或间日，或二、三日，常服一、二剂。 \n人参（随宜） 当归 杜仲 芍药（各二钱） 熟地（二、三钱） 白术（钱半） 炙甘草（一钱） 陈皮 \n（七分，无滞者，不必用） \n水二钟，煎七分，食远服。如下元不固而多遗浊者，加山药、补骨胎、五味之类；如气 \n分虚甚者，倍白术，加黄 。但 、术气浮，能滞胃口，倘胸膈有饱闷不快者，须慎用之； \n如虚而兼寒多呕者，加炮姜七、八分，或一、二钱；如虚而兼热者，加黄芩一钱五分，或加 \n生地二钱，去杜仲；如阴虚小腹作痛，加枸杞二钱；如多怒气逆者，加香附无妨，或砂仁亦 \n妙；如有所触而动血者，加川续断、阿胶各一、二钱；如呕吐不止，加半夏一、二钱，生姜三、五片。 \n\\x固胎煎\\x 治肝脾多火多滞而屡堕胎者。 \n黄芩（二钱） 白术（一、二钱） 当归 芍药 阿胶（各钱半） 陈皮（一钱） 砂仁（五分） \n水一钟半，煎服。 \n\\x凉胎饮\\x 治胎气内热不安等证。 \n生地 芍药（各二钱） 黄芩 当归（各一、二钱） 甘草（生，七分） 枳壳 石斛（各一钱） 茯苓（钱半） \n水一钟半，煎七分，食远温服。如热甚者，加黄柏一、二钱。 \n\\x滑胎煎\\x 胎气临月，宜常服数剂，以使易生。 \n当归（三、五钱） 川芎（七分） 杜仲（二钱） 熟地（三钱） 枳壳（七分） 山药（二钱） \n水二钟，煎八、九分，食煎温服。如气体虚弱者，加人参、白术，随宜用之；如便实多 \n滞者，加牛膝一、二钱。 \n\\x殿胞煎\\x 治产后儿枕疼痛等证如神。 \n当归（五、七钱或一两） 川芎 炙甘草（各一钱） 茯苓（一钱） 肉桂（一、二钱或五、七分） \n水一钟，煎八分，热服。如脉细而寒或呕者，加干姜炒黄色一、二钱；如血热多火者， \n去肉桂，加酒炒芍药一、二钱；如脉弱阴虚者，加熟地三、五钱；如气滞者，加香附一、二 \n钱，或乌药亦可；腰痛，加杜仲一、二钱。 \n\\x脱花煎\\x 凡临盆将产者，宜先服此药催生最佳，并治产难经日，或死胎不下俱妙。 \n当归（七、八钱或一两） 肉桂（一、二钱或三钱） 川芎 牛膝（各二钱） 车前子（钱半） 红花（一 \n钱，催生者，不用此味亦可） \n水二钟，煎八分，热服，或服后饮酒数杯亦妙。若胎死腹中，或坚滞不下者，加朴硝三 \n、五钱即下；若气虚困剧者，加人参随宜；若阴虚者，必加熟地三、五钱。 \n\\x九蜜煎\\x 治产后阳气虚寒，或阴邪入脏，心腹疼痛，呕吐不食，四肢厥冷。此与大岩蜜 \n汤略同而稍胜之。 \n当归 熟地（各三钱） 芍药（酒炒焦） 茯苓（各钱半） 炙甘草 干姜（炒） 肉桂 北细辛（各 \n一钱） 吴茱萸（制，五分） \n水二钟，煎服。 \n\\x清化饮\\x 治妇人产后因火发热，及血热妄行，阴亏诸火不清等证。 \n芍药 麦冬（各二钱） 丹皮 茯苓 黄芩 生地（各二、三钱） 石斛（一钱） \n水一钟半，煎七分，食远温服。如觉骨蒸多汗者，加地骨皮一钱半；热甚而渴或头痛者 \n，加石膏一、二、三钱；下热便涩者，加木通一、二钱，或黄柏、栀子皆可随证用之；如兼 \n外邪发热，加柴胡一、二钱。愚按∶丹溪云∶芍药酸寒，大伐发生之气，产后忌用之。此亦 \n言之过也。夫芍药之寒，不过于生血药中稍觉其清耳，非若芩、连辈之大苦大寒者也。使芍 \n药犹忌如此，则他之更寒者，尤为不可用矣。余每见产家过慎者，或因太暖，或因年力方壮 \n，而饮食药饵太补过度，以致产后动火者，病热极多。若尽以产后为虚，必须皆补，岂尽善 \n哉！且芍药性清，微酸而收，最宜于阴气散失之证，岂不为产后之要药乎？不可不辨也。 \n\\x毓麟珠\\x 治妇人气血俱虚，经脉不调，或断续，或带浊，或腹痛，或腰酸，或饮食 \n不甘，瘦弱不孕，服一、二斤即可受胎。凡种子诸方，无以加此。 \n人参 白术（土炒） 茯苓 芍药（酒炒，各二两） 川芎 炙甘草（各一两） 当归 熟地（蒸 \n捣，各四两） 菟丝子（制，四两） 杜仲（酒炒） 鹿角霜 川椒（各二两） \n上为末，炼蜜丸，弹子大。每空心嚼服一、二丸，用酒或白汤送下，或为小丸吞服亦可 \n。如男子制服，宜加枸杞、胡桃肉、鹿角胶、山药、山茱萸、巴戟肉各二两；如女人经迟腹 \n痛，宜加酒炒破故、肉桂各一两，甚者再加吴茱萸五钱，汤泡一宿炒用；如带多腹痛，加破 \n故一两，北五味五钱，或加龙骨一两，醋 用；如子宫寒甚，或泄或痛，加制附子、炮干姜 \n随宜；如多郁怒，气有不顺，而为胀为滞者，宜加酒炒香附二两，或甚者再加沉香五钱；如 \n血热多火，经早内热者，加川续断、地骨皮各二两，或另以汤剂暂清其火，而后服此，或以 \n汤引酌宜送下亦可。 \n\\x赞育丹\\x 治阳痿精衰，虚寒无子等证妙方。 \n熟地（八两，蒸捣） 白术（用冬术，八两） 当归 枸杞（各六两） 杜仲（酒炒） 仙茅（酒蒸一 \n日） 巴戟肉（甘草汤炒） 山茱萸 淫羊藿（羊脂拌炒） 肉苁蓉（酒洗去甲） 韭子（炒黄，各 \n四两） 蛇床子（微炒） 附子（制） 肉桂（各二两） \n上炼蜜丸服。或加人参、鹿茸亦妙。 \n\\x柴归饮\\x 治痘疮初起，发热未退，无论是痘是邪，疑似之间，均宜用此平和养营之剂以 \n为先着。有毒者可托，有邪者可散，实者不致助邪，虚者不致损气。凡阳明实热邪盛者，宜 \n升麻葛根汤；如无实邪，则悉宜用此增减主之。 \n当归（二、三钱） 芍药（或生或炒，一钱半） 柴胡（一钱或钱半） 荆芥穗（一钱） 炙甘草（七分或一钱） \n水一钟半，煎服。或加生姜三片。血热者，加生地；阴虚者，加熟地；气虚脉弱者，加 \n人参；虚寒者，加炮姜、肉桂；火盛者，加黄芩；热渴者，加干葛；腹痛者，加木香、砂仁 \n；呕恶者，加炮姜、陈皮；若治麻疹，或以荆芥易干葛；阴寒盛而邪不能解者，加麻黄、桂枝。 \n\\x疏邪饮\\x 治痘疹初起发热，凡血气强盛，无藉滋补者，单宜解邪，用此方为主，以代升 \n麻葛根汤及苏葛汤等方，最为妥当。 \n柴胡（倍用） 芍药（倍用，酒炒） 苏叶 荆芥穗 炙甘草（减半） \n水一钟半，煎服。无火者，加生姜三片；火盛内热者，加黄芩；渴者，加干葛。 \n\\x凉血养营煎\\x 治痘疮血虚血热，地红热渴，或色燥不起，及便结溺赤，凡阳盛阴虚等证，悉宜用此。 \n生地黄 当归 芍药 生甘草 地骨皮 紫草 黄芩 红花 \n水一钟半，煎服。量儿大小加减用之。渴，加天花粉；肌热无汗，加柴胡；热毒甚者， \n加牛蒡子、木通、连翘之属；血热毒不透者，加犀角。 \n\\x柴葛煎\\x 治痘疹表里俱热，散毒养阴，及瘟疫等证。 \n柴胡 干葛 芍药 黄芩 甘草 连翘 \n水一钟半，煎服。 \n\\x搜毒煎\\x 解痘疹热毒炽盛，紫黑干枯，烦热便结纯阳等证。 \n紫草 地骨皮 牛蒡子（杵） 黄芩 木通 连翘 蝉蜕 芍药（等分） \n水一钟半，煎服。渴者，加天花粉、麦门冬；阳明热甚，头面牙龈肿痛者，加石膏、知 \n母；大肠干结实，脐腹实胀者，加大黄、芒硝；血热妄行者，加犀角、童便；小水热闭者， \n加山栀、车前子；兼表热者，加柴胡。 \n\\x六物煎\\x 治痘疹血气不充，随证加减用之，神效不可尽述。并治男妇气血俱虚等证。 \n炙甘草 当归 熟地（或用生地） 川芎（三、四分，不宜多） 芍药（俱随宜加减） 人参（或有 \n或无，随虚实用之。气不虚者不必用） \n上咀，用水煎服。如发热不解，或痘未出之先，宜加柴胡以疏表，或加防风佐之；如见 \n点后，痘不起发，或起而不贯，或贯而浆薄，均宜单用此汤，或加糯米、人乳、好酒、肉桂 \n、川芎以助营气；如气虚痒塌不起，加穿山甲炒用；如红紫血热不起，宜加紫草或犀角；如 \n脾气稍滞者，宜加陈皮、山楂；如胃气虚寒多呕者，加干姜炒用，或加丁香；如腹痛兼滞者 \n，加木香、陈皮；表虚气陷不起，或多汗者，加黄 ；气血俱虚，未起未贯而先痒者，加肉 \n桂、白芷；如元气大虚，寒战切牙泄泻，宜去芍药，加黄 、大附子、干姜、肉桂。 \n\\x六气煎\\x 治痘疮气虚，痒塌倒陷，寒战切牙，并治男妇阳气虚寒等证。 \n黄 （炙） 肉桂 人参 白术 当归 炙甘草 \n上咀，水煎服。加减法照前六物煎。 \n\\x九味异功煎\\x 治痘疮寒战切牙倒陷，呕吐泄泻，腹痛虚寒等证。用代陈氏十二味异功散等方。 \n人参（二、三钱） 黄 （炙，一、二钱） 当归 熟地（各二、三钱） 炙甘草（七分或一钱） 丁香 \n（三、五分或一钱） 肉桂（一钱） 干姜（炮，一、二钱） 制附子（一、二钱） \n上量儿大小加减，用水一钟半，煎七分，徐徐与服之。如泄泻腹痛，加肉豆蔻面炒一钱 \n，或加白术一、二钱。 \n\\x透邪煎\\x 凡麻疹初热未出之时，惟恐误药，故云未出之先，不宜用药，然解利得宜，则 \n毒必易散而势自轻减，欲求妥当，当先用此方为主。 \n当归（二、三钱） 芍药（酒炒，一、二钱） 防风（七、八分） 荆芥（一钱） 炙甘草（七分） 升麻（三分） \n水一钟半，煎服。如热甚脉洪滑者，加柴胡一钱。此外，凡有杂证，俱可随宜加减。牛 \n膝煎 截疟大效。凡邪散已透，而血气微虚者，宜此主之。 \n牛膝（二钱） 当归 陈皮（各三钱） \n上用好酒一钟，浸一宿，次早加水一钟，煎至八分，温服。 \n\\x何人饮\\x 截疟如神。凡气血俱虚，久疟不止，或急欲取效者，宜此主之。 \n何首乌（自三钱以至一两，随轻重用之） 当归（二、三钱） 人参（三、五钱或一两，随宜） 陈 \n皮（二、三钱，大虚者，不必用） 煨生姜（三斤，多寒者用三、五钱） \n水二钟，煎八分，于发前二、三时，温服之。若善饮者，以酒一钟，浸一宿，次早加水 \n一钟煎服亦妙。再煎不必用酒。 \n何首乌（一两，制） 当归 甘草 半夏 青皮 陈皮 柴胡（各三钱） \n上用井水、河水各一钟，煎一钟， 亦如之，同露一宿。次早温服一钟，饭后食远再服一钟。 \n\\x木贼煎\\x 凡疟疾形实气强，多湿多痰者，宜此截之，大效。 \n半夏 青皮（各五钱） 木贼 浓朴（各三钱） 白苍术 槟榔（各一钱） \n用陈酒二钟，煎八分，露一宿，于未发之先二时，温服。 \n\\x牙皂散\\x 治胃脘痛剧，诸药不效者，服此如神。 \n用牙皂烧存性，以烟将尽为度，研末，用烧酒调服一钱许即效。 \n\\x荔香散\\x 治疝气痛极。凡在气分者，最宜用之，并治小腹气痛等证，神效。又心腹久痛方如后。 \n荔枝核（炮微焦） 大茴香（等分，炒） \n上为末，用好酒调服二、三钱。如寒甚者，加制过吴茱萸减半用之；凡心腹胃脘久痛， \n屡触屡发者，惟妇人多有之，用荔枝核一钱，木香八分，为末，每服一钱，清汤调服，数服除根。 \n\\x豕膏\\x 《内经》曰∶痈发于嗌中，名曰猛疽，猛疽不治，化为脓，脓不泻，塞咽，半日 \n死；其化为脓者，泻则合豕膏，冷食，三日已。此必以猪板油炼净服之也。又万氏方∶治肺 \n热暴喑。用猪脂一斤，炼过入白蜜一斤，再炼少顷，滤净冷定，不时挑服一匙，即愈。按∶ \n此方最能润肺润肠，凡老人痰嗽不利，及大肠秘结者，最宜用之。 \n又，《千金》方∶治关格闭塞。用猪脂、姜汁各二升，微火煎至三升，加酒五合和煎，分服之。 \n愚意先以当归半斤，浓煎取汁，炼过猪脂一斤，同炼去其水气，乃入白蜜一斤，再炼少 \n顷，滤净收贮，不时挑服，用治老人之秘结，及噎膈闭结等证，必无不妙。如果阳气不行者 \n，仍加生姜四两，同当归煎入；或宜酒者，以酒送服亦可。或气有不利者，加杏仁二两，去 \n皮尖，同前煎入皆妙；或有滞者，当以饧代蜜更妙；是即《内经》所谓以辛润之也。 \n\\x罨伤寒结胸法\\x 凡病伤寒结胸，其有中气虚弱，不堪攻击内消者，须以此法外罨之，则 \n滞行邪散，其效如神。 \n葱白头 生姜 生萝卜（此味加倍。如无，以子代之） \n上用葱姜各数两，萝卜倍之，共捣一处炒热，用手巾或白布包作大饼。罨胸前胀痛处。 \n此药须分二包，冷则轮换罨之，无不实时开通，汗出而愈。但不宜太热，恐炮烙难受也。 \n又法∶以大蒜一、二十头，捣烂，摊浓纸或薄绢上，贴于胀处，少顷即散。用治一切胀 \n痛，无不神妙。 \n\\x连翘金贝煎\\x 治阳分痈毒，或在脏腑肺膈胸乳之间者，此方最佳，甚者连用数服，无有不愈。 \n金银花 贝母（土者更佳） 薄公英 夏枯草（各三钱） 红藤（七、八钱） 连翘（一两或五、七钱） \n用好酒二碗，煎一碗服。服后暖卧片时。火盛烦渴乳肿者，加天花粉；若阳毒内热，或 \n在头项之间者，用水煎亦可。 \n\\x连翘归尾煎\\x 治一切无名痈毒，丹毒流注等毒，有火者最宜用之。 \n连翘（七、八钱） 归尾（三钱） 甘草（一钱） 金银花 红藤（各四、五钱） \n用酒煎服如前。如邪热火盛者，加槐蕊二、三钱。 \n\\x桔梗杏仁煎\\x 此桔梗汤之变方也。治咳嗽吐脓，痰中带血，或胸膈隐痛，将成肺痈者，此方为第一。 \n桔梗 杏仁 甘草（各一钱） 阿胶 金银花 麦冬 百合 夏枯草 连翘（各二钱） 贝母（三 \n钱） 枳壳（钱半） 红藤（三钱） \n水二钟，煎八分，食远服。如火盛兼渴者，加天花粉二钱。 \n\\x当归蒺藜煎\\x 治痈疽疮疹血气不足，邪毒不化，内无实热而肿痛淋漓者，悉宜用之。此 \n与芍药蒺藜煎相为奇正也，当酌其详。 \n当归 熟地 芍药（酒炒） 何首乌（各二钱） 炙甘草 防风 川芎 荆芥穗 白芷（各一钱） \n白蒺藜（炒，捣碎，三钱或五钱） \n上或水或酒，用二钟煎服，然水不如酒。或以水煎服后，饮酒数杯以行药力亦可。阳虚 \n不能化毒者，加桂枝，甚者再加干姜、附子；气虚不化者，加黄 、人参；毒陷不能外达者 \n，加穿山甲或皂刺。 \n\\x芍药蒺藜煎\\x 治通身湿热疮疹，及下部红肿热痛诸疮，神效。外以螵蛸粉敷之。 \n龙胆草 栀子 黄芩 木通 泽泻（各钱半） 芍药 生地（各二钱） 白蒺藜（连刺捶碎，五钱，甚者一两） \n水二钟，煎八分，食远服。如火不甚者，宜去龙胆、栀子，加当归、茯苓、薏仁之属； \n如湿毒甚者，加土茯苓五钱，或一、二两。 \n\\x降痈散\\x 治痈疽诸毒，消肿止痛散毒，未成者即消，已成者敛毒速溃可愈。若阳毒炽盛 \n薄荷（辛佳者，用叶） 野菊花（连根叶各一握） 土贝母（半之） 茅根（一握） \n上干者可为末，鲜者可捣烂，同贝母研匀，外将茅根煎浓汤去 ，用调前末，乘热 \n敷患处，仍留前剩汤炖暖，不时润于药上。但不可用冷汤，冷则不散不行，反能为痛 \n。约敷半日即宜换之，真妙方也。 \n后方∶凡疽毒坚顽深固，及结核痰滞，宜用此方。 \n脑荷（倍用） 生南星 土贝母 朴硝（各等分） 锻石（风化者，亦倍用或倍倍用之） \n上同为末，用盐卤调杵稠粘，敷患处，经宿，干即易之，不必留头，若脓成者留头亦可 \n。或炒热摊绢上，隔绢贴之亦可。或用麻油调，或用热茅根汤调亦可。若欲止痛速效，加麝 \n香或冰片少许更妙。 \n\\x百草煎\\x 治百般痈毒诸疮，损伤疼痛，腐肉肿胀，或风寒湿气留聚，走注疼痛等证，无不奇效。 \n百草（凡田野山间者，无论诸品，皆可取用，然犹以山草为胜，辛香者佳。冬月可用干 \n者，须预为收采之） \n上不论多寡，取以多，煎浓汤，乘热熏洗患处，仍用布帛蘸熨良久，务令药气蒸透，然 \n后敷贴他药，每日二、三次不拘，但以频数为善。盖其性之寒者，可以除热；热者，可以散 \n寒；香者，可以行气；毒者，可以解毒，无所不用，亦无所不利。汤得药性则汤气无害，药 \n得汤气则药力愈行。凡用百草以煎膏者，其义亦此。此诚外科中最要最佳之法，亦传之方外 \n人者也。若洗水鼓肿胀，每次须用草二、三十斤，煎浓汤二、三锅，用大盆盛贮，以席簟遮 \n风熏洗良久，每日一次或二次，内服廓清饮分利等剂妙甚。 \n\\x螵蛸散\\x 治湿热破烂，毒水淋漓等疮，或下部、肾囊、足股肿痛，下疳诸疮，无不神效 \n。又海藏治下疳方，在《外科》下疳门。 \n海螵蛸（不必浸淡） 人中白（或人中黄， 砂亦可，等分） \n上为细末。先以百草多煎浓汤，乘热熏洗，后以此药掺之。如干者，以麻油或熬熟猪油 \n，或蜜水调敷之；若肿而痛甚者，加冰片少许更妙；若湿疮脓水甚者，加密陀僧等分，或 \n过官粉亦可，或 制炉甘石更佳。 \n\\x肠痈秘方\\x 凡肠痈生于小肚角，微肿而小腹隐痛不止者是。若毒瓦斯不散，渐大内攻而溃 \n，则成大患，急宜以此药治之。 \n先用红藤一两许，以好酒二碗，煎一碗。午前一服，醉卧之。午后用紫花地丁一两许， \n亦如前煎服。服后痛必渐止为效，然后服后末药除根神妙。 \n当归（五钱） 蝉蜕 僵蚕（各二钱） 天龙 大黄（各一钱） 石HT FS （五钱，此草药也） \n老蜘蛛（二个，捉放新瓦上，以酒盅盖定，外用火 干存性） \n上共为末。每空心用酒调送一钱许，日逐渐服，自消。 \n\\x槐花蕊\\x 治杨梅疮、下疳神方。 \n凡绵花疮毒及下疳初感，或毒盛经久难愈者，速用新槐蕊拣净，不必炒，每食前用清酒 \n寒凉败脾之虑，此经验神方也。如不能饮，即用滚水、盐汤俱可送下，但不及酒送之效捷也。 \n\\x飞丹散\\x 治寒湿风湿脚腿等疮。 \n飞丹 人中黄（白更妙） 轻粉 水粉（各等分） \n为末，凡湿烂者可以干掺，外用油纸包盖。若干陷者，以猪骨髓或猪油调贴之。先以百 \n草煎汤，乘热熏洗，然后贴之，日洗数次妙。 \n绵花疮点药 \n杏仁（取霜） 轻粉（真者） \n二味等分为末，敷于疮上，二、三日即痂脱而落。 \n又武定侯方，用雄黄钱半，杏仁三十粒去皮，轻粉一钱，同为末，用雄猪胆汁调敷之。 \n二、三日即愈，百发百中，天下第一方。 \n\\x鸡子黄连膏\\x 治火眼暴赤疼痛，热在肤腠，浅而易解者，用此点之，数次可愈。若热由 \n内发，火在阴分者，不宜外用凉药，非惟不能去内热，而且以闭火邪也。用鸡子一枚，开一 \n小窍，单取其清，盛以瓷碗，外用黄连一钱，研为粗末，掺于鸡子清上，用箸彻底速打数百 \n，使成浮沫，约得半碗许，即其度矣。安放少顷，用箸拨开浮沫，倾出清汁，用点眼 ，勿 \n得紧闭眼胞，挤出其药，必热泪涌出，数次即愈。内加冰片少许尤妙。若鸡子小而清少者， \n加水二、三匙同打亦可。 \n\\x金露散\\x 治赤目肿痛，翳障诸疾。 \n天竺黄（择辛香者用） 海螵蛸（不必浸洗） 月石（各一两） 朱砂（飞） 炉甘石（片子者佳 \n，淬童便七次，飞净，各八钱） \n上为极细末，瓷瓶收贮。每用时旋取数分，研入冰片少许。诸目疾皆妙。若内外 障， \n取一钱许，加珍珠八厘，胆矾三厘。内珍珠须放豆腐中蒸熟用。若烂弦风眼，每一钱加铜绿 \n、飞丹各八厘；如赤眼肿痛，每一钱加乳香、没药各半分。 \n\\x二辛煎\\x 治阳明胃火，牙根口舌肿疼不可当，先用此汤漱之，漱后敷以二香散，或仍服 \n清胃等药以治其本。 \n北细辛（三钱） 生石膏（一两） \n上二味，用水二碗，煎一碗，乘热频漱之。 \n\\x冰玉散\\x 治牙疳牙痛，口疮齿衄喉痹。 \n生石膏（一两） 月石（七钱） 冰片（三分） 僵蚕（一钱） \n上为极细末，小瓷瓶盛贮，敷之吹之。 \n\\x冰白散\\x 治口舌糜烂，及走马牙疳等证。 \n人中白（倍用之） 冰片（少许） 铜绿（用醋制者） 杏仁（二味，等分） \n上为细末，敷患处。此方按之古法，有以人中白七分，与枯矾三分同用者。又有以蜜炙 \n黄柏，与人中白等分，仍加冰片同用者，是皆可师之法，诸当随宜用之。 \n\\x代匙散\\x 治喉痹。 \n月石 石膏（各一钱） 脑荷（五分） 胆矾（五分） 粉草（三分） 僵蚕（炒，五分） 冰片（一分） 皂角 \n（炙烟尽，五分） \n上为细末，用竹管频吹喉中。加牛黄五分更佳。 \n\\x三香散\\x 治牙根肿痛。 \n丁香 川椒（取红，等分） 冰片（少许） \n上为末，敷痛处。如无川椒，以荜茇代之亦可。 \n\\x固齿将军散\\x 治牙痛牙伤，胃火糜肿，久之牢牙固齿。 \n锦纹大黄（炒微焦） 杜仲（炒半黑，各十两） 青盐（四两） \n上为末，每日清晨擦漱，火盛者咽之亦可。 \n\\x熏疥方\\x \n朱砂 雄黄 银朱（各三分，同研） 大枫子 木鳖子（各三个） \n上将大枫、木鳖先捣碎，乃入前三味拌匀，外以干艾铺卷成筒，约长二寸许足矣。凡熏 \n时，须将全身疥痂悉行抓破，熏之始效。后五、六日，复熏一筒，无不悉愈。 \n\\x杖丹膏\\x \n猪板油（半斤） 黄占（二两） 轻粉（三钱） 水银（三钱） 冰片（三分） \n先将水银、轻粉同研细，俟猪油熬熟，去滓，先下黄占熔化，后入末药，搅匀收贮，以 \n水浸二、三时，令出火毒。用竹纸摊贴，觉热即换，轻者即愈，重者不过旬日。 \n\\x银朱烟\\x 治头发生虱，及诸疮之有虫者。 \n用银朱四、五分，揩擦浓纸上，点着，置一干碗中，上用一湿碗露缝覆之，其烟皆着于 \n湿碗之上，乃用纸揩擦发中，覆以毡帽，则虮虱皆尽矣。此烟以枣肉和捻作饼，或作丸，或 \n擦于猪鸡熟肝之间，用点诸疮癣之有虫者。及虫蚀肛门者，以绵裹枣丸纳肛门中一宿，无不 \n神效，须留绵带在外，以便出之。 \n\\x雷火针\\x 治风寒湿毒之气留滞经络，而为痛为肿不能散者。 \n五月五日取东引桃枝，去皮，两头削如鸡子尖样，长一、二寸许。针时以针向灯上点着 \n，随用纸三、五层，或布亦可，贴盖患处，将热针按于纸上，随即念咒三遍，病深者再燃再 \n刺之，立愈。咒曰∶天火地火，三昧真火，针天天开，针地地裂，针鬼鬼灭，针人人得长生 \n，百命消除，万病消灭。吾奉太上老君急急如律令。 \n又雷火针新方，乃以药为针者，其法更妙。 \n白芷 独活 川芎 细辛 牙皂 穿山甲（炮，倍用） 丁香 枳壳 松香 雄黄 乳香 \n没药 杜仲 桂枝（各一钱） 硫黄（二钱） 麝香（不拘） 熟艾（二、三两） \n上捣为粗末，和匀，取艾铺底，掺药于上，用上好皮纸卷筒，先须用线绊约两头，防其 \n伸长，然后加纸再捍，务令极实，粗如鸡子尖样，是其度也。乃用鸡子清尽刷外层，卷而裹 \n之，阴干。用法如前。一方有巴豆仁八分，斑蝥三钱，去头、足、翅用。 \n\\x疥癣光\\x 治疥疮，搽上即愈。癣疮亦妙。 \n松香（一钱） 水银 硫黄 枯矾（各二钱） 樟脑（各二钱，此或一钱） 麻油 \n上先将松香、水银加麻油少许，研如糊，后入三味，研细如膏，擦之神效。 \n\\x鹅掌风四方\\x （附录） \n猪胰（一具，去油，勿经水） 花椒（三钱） \n上用好酒温热，将二味同浸二、三日，取胰，不时擦手，微火烘之，自愈。 \n又方∶用白砒三钱，打如豆粒，以麻油一两熬砒至黑，去砒用油擦手，微火烘之，不过二、三次即愈。 \n又方∶用葱五、六根，椎破，再用花椒一把，同入瓷瓦罐中，入醋一碗，后以滚汤冲入 \n，熏洗数次即愈。 \n又方∶用谷树叶煎汤温洗，以火烘干，随用柏白油擦之，再以火烘干，少顷又洗又烘， \n如此日行三次，不过三、五日即愈。 \n\\x秘传水银膏\\x 擦治杨梅风毒溃烂危恶，多年不愈者，经验神方。 \n黄柏 黄连（各一钱） 川大黄（五分，三味另研） 雄璜 胆矾 青黛 儿茶 铜青（各三分） \n轻粉 枯矾（各四分） 大枫子（去油，取净霜五分，黑者勿用） 珍珠（一分半，生用） 冰片（一分） \n半，二味另研） 人言（人壮者七厘，弱者半分，中者六厘） \n上十四味为极细末，分作三分，每分约一钱八分。 \n\\x番打麻\\x 另为末。若疮重而人壮能食者，每分用五分；人弱不起者，每分用三分；中者 \n四分。以末入前药各分内研匀。 \n水银 人健者，每分用一两，或八、九钱；中者，或五、六钱；卧床不起而极弱者，只 \n可用三钱，决不可再多矣。 \n上先将麻、汞并前药各一分，俱入盏内，再入真芝麻油少许，用手指研开，务使汞药混 \n为一家，渐次增油，久研，以不见汞星为度，大约如稀糊可矣。一、擦法∶用此药擦手足四 \n腕动脉处，每药一分，务分擦三日，每日早晚各擦一次，每次以六、七百数为度，擦完用布 \n包之。擦药时，凡周身略有破伤处，俱用无麝膏药贴之，膏药须浓摊，每二日一换，换时不 \n可经风，常须避帐幔中，冬月须用浓被暖炕，他时亦须常暖，南方则多用被褥盖垫可也。擦 \n至七日，毒必从齿缝中发出，口吐臭涎。若口齿破烂出血，但用甘草、蜂房煎汤，候冷漱解 \n，不可咽下。轻者只以花椒汤漱之亦可。擦处必皮破，不可畏疼而少擦也。忌盐十余日，多 \n更好，并鱼腥、生冷、沙气、发风等物一个月，尤忌房事。外如牛肉、烧酒、团鱼之类，须 \n忌二、三年。惟荞麦面、羊肉则终身忌之。治杨梅疮初发者，五六日可愈。但每分用汞四、 \n五钱足矣。若治蛀干疳疮，或咽喉溃烂，或遍身牛皮疮癣，俱照前中治法。若治久烂 疮， \n烂处难擦，则擦脚心，俱照前中治法，亦布包贴膏如前。一、自擦起之日，即当服后败毒散 \n，至七日后，发口则止。 \n\\x二十四味败毒散\\x（随前水银膏） \n当归 川芎 生地 熟地 芍药 牛膝 防风 荆芥 白芷 防己 忍冬 桔梗 羌活 \n独活 白鲜皮 薏仁 连翘 木通 陈皮 粉草 黄柏 知母 栀子 黄连"}, {"n": 32, "text": "卷三十二\n\n上每帖加土茯苓干者四两，鲜者须半斤，用水六碗，煎三碗，分三次，每日早、午、晚 \n各服一碗。上方后四味，须察其人阴阳寒热，酌而用之。 \n按∶上水银膏方，凡用此者，其于筋骨经络无处不到，既能追毒，亦善杀虫。若用治大 \n麻风证，必有奇效，但未经试，故表诸此，以俟后人试用之。或于大风条择煎剂之相宜者同 \n用尤妙。倘获济人，其幸多矣。 \n\\x 疮隔纸膏\\x \n黄占（五两） 飞丹 铅粉（各四两） 轻粉 乳香 没药（各二钱） 冰片（三分） 麻油（春夏二两， \n秋冬三两） \n上先将占油煎五、六沸，下乳、没，再二、三服，下轻粉，随下丹粉，槐柳枝搅十余沸 \n，取起冷定，后下冰片搅匀，瓶盛，浸水中一宿出火毒。先以苦茶洗疮净，将膏用薄油纸刺 \n孔浓摊，间日番背面贴之，三日一换，三贴即可愈。 \n\\x收疮散\\x 治湿烂诸疮，肉平不敛，及诸疮毒内肉既平，而口有不收者，皆宜用此，最妙。 \n滑石（飞，一两） 赤石脂（飞，五钱） 粉甘草（三钱） \n上为末，干掺，或用麻油调敷。或加枯矾一钱，痒者极宜。若痒甚者必有虫，先用水银 \n三、四钱，同松香二钱研匀后，拌前药和匀敷之。 \n\n\n\n<目录>卷之五十二图集·古方八阵\n\n<篇名>古方总目\n\n属性：（以下总列共一十三卷） \n\n\n\n<目录>卷之五十二图集·古方八阵\\古方总目\n\n<篇名>附古方条序\n\n属性：愚按∶古方之散列于诸家者，既多且杂，或互见于各门，或彼此之重复，欲通其用，涉 \n猎固难，欲尽收之，徒资莠乱，今余采其要者，类为八阵，曰补、和、攻、散、寒、热、固 \n、因；八阵之外，复列有妇人、小儿、痘疹、外科之四方。且于诸方之中，仍以类聚，庶乎 \n奇正罗列，缓急并陈，或舍短可以就长，或因此可以校彼，慧眼所及，朗如日星，引而伸之 \n，触类而长之，因古人之绳墨，得资我之变通，医中之能事，斯亦先几一着也，凡我同志， \n其加省焉。 \n一曰补阵 存亡之几，几在根本，元气既亏，不补将何以复，故方有补阵。 \n二曰和阵 病有在虚实气血之间，补之不可，攻之又不可者，欲得其平，须从缓治，故 \n方有和阵。 \n三曰攻阵 邪固疾深，势如强寇，速宜伐之，不可缓也，故方有攻阵。 \n四曰散阵 邪在肌表，当逐于外，拒之不早，病必日深，故方有散阵。 \n五曰寒阵 阳亢伤阴，阴竭则死，或去其火，或壮其水，故方有寒阵。 \n六曰热阵 阴极亡阳，阳尽则毙，或祛其寒，或助其火，故方有热阵。 \n七曰固阵 元气既伤，虚而且滑，漏泄日甚，不尽不已，故方有固阵。 \n八曰因阵 病有相同，治有相类，因证用方，亦有不必移易者，故方有因阵。 \n附列四方 古方于八阵之外，其有未尽者，如妇人有经脉胎产之异，小儿有养育惊疳之 \n异，痘疹有出没变化之异，外科有经脏表里之异，随几应变，治有不同，故并列方目于下。 \n\n\n\n<目录>卷之五十三图集·古方八阵\n\n<篇名>补阵\n\n属性：\\x四君子汤\\x 治脾胃虚弱，饮食少思，或大便不实，体瘦面黄，或胸膈虚痞，吞酸痰嗽， \n或脾胃虚弱，善患疟痢等证。 \n人参 白术 茯苓（各二钱） 炙甘草（一钱） \n加姜、枣，水煎服。或加粳米百粒。 \n\\x加味四君汤\\x 治痔漏下血，面色痿黄，怔忡耳鸣，脚软气弱，及一切脾胃气虚，口淡， \n食不知味，又治气虚不能摄血，以致下血不禁。 \n人参 白术（炒） 茯苓 炙甘草 黄 （炙） 白扁豆（炒） \n上水煎服。或为末，每服三钱，滚汤调服。 \n\\x生附四君汤\\x 方在小儿。治脾胃虚寒吐泻。 \n\\x五味异功散\\x 治脾胃虚寒，饮食少思，呕吐，或久患咳嗽，面浮气逆腹满等证。 \n人参 白术（炒） 茯苓 炙甘草 陈皮（各一钱） 此即四君子汤加陈皮也 \n上加姜、枣，水煎服。 \n\\x六君子汤\\x 治脾胃虚弱，饮食少思，或久患疟痢，或食饮难化，或呕吐吞酸，或咳嗽喘 \n促若虚火等证，须加炮姜，其功尤速。 \n即前四君子汤加陈皮、半夏各一钱五分。 \n\\x加味六君汤\\x 治一切脾胃虚弱泄泻，及伤寒病后米谷不化，肠中虚滑，发渴微痛久不瘥 \n者，及治小儿脾疳泻痢。 \n人参 白术 黄 山药 甘草 白茯苓（各一两） 砂仁 浓朴 肉豆蔻（面裹煨，各七钱） \n上每服一两，用水煎服；或为细末，用米汤调服二钱，不拘时。 \n\\x香砂六君子汤\\x 治过服凉药，以致食少作呕，或中气虚滞，恶心胀满等证。 \n人参 白术 茯苓 半夏 陈皮（各一钱） 砂仁（炒） 藿香（各八分） 炙甘草（六分） \n上姜水煎服。 \n（《局方》）\\x四物汤\\x 治血虚营弱，一切血病，当以此为主。 \n熟地黄 当归（各三钱） 川芎（一钱） 芍药（二钱） \n水二钟，煎服。 \n（薛氏）\\x加味四物汤\\x \n即前方加山栀、柴胡、丹皮。 \n（《正传》）\\x加味四物汤\\x 治血热阴虚诸痿，四肢软弱不能举动。 \n当归（一钱） 五味子（九粒） 熟地（三钱） 麦冬 黄柏 苍术（各一钱） 白芍药 川芎（各七分半） \n人参 黄连（各五分） 杜仲（七分半） 牛膝（足不软者不用） 知母（各三分） \n水二钟，煎一钟，空心温服。酒糊丸服亦可。 \n（东垣）\\x加减四物汤\\x 方在寒阵。治肠风下血。 \n（《保命》）\\x柴胡四物汤\\x 治日久虚劳，微有寒热，脉滑而数者。 \n当归 熟地 芍药 川芎（各钱半） 柴胡（八分） 人参 黄芩 半夏 甘草（各三钱） \n加生姜三片，水煎服。 \n（万氏）\\x柴胡四物汤\\x 方在痘疹。治疹后余热。 \n\\x奇效四物汤\\x 方在妇人。治肝经虚热血崩。 \n\\x增损四物汤\\x 方在妇人。治脾虚不摄，去血不止。 \n（《元戎》）\\x四物汤\\x 方在攻阵。治血虚脏结。 \n（《良方》）\\x加减四物汤\\x 方在妇人。治妇人血积。 \n\\x四物二连汤\\x 方在妇人。治妇人阴虚内热。 \n（《局方》）\\x八珍汤\\x 治气血两虚，调和阴阳。 \n即前四君子、四物汤相合也。本方加黄柏、知母，即名补阴八珍汤，方见外科三二。 \n\\x十全大补汤\\x 治气血俱虚，恶寒发热，自汗盗汗，肢体困倦，眩晕惊悸，晡热作渴，遗 \n精白浊，二便见血，小便短少，便泄闭结，喘咳下坠等证。 \n即前八珍汤加黄 、肉桂各一钱。 \n（《局方》）\\x人参养营汤\\x 治脾肺俱虚，恶寒发热，肢体瘦倦，食少作泻，口干心悸自汗等证。 \n人参 黄 当归 白术 炙甘草 桂心 陈皮（各一钱） 熟地 五味 茯苓（各七分） 白 \n芍（钱半） 远志（五分） \n加姜、枣，水煎服。 \n（《金匮》）\\x小建中汤\\x 治虚劳里急，腹痛失精，四肢酸疼，手足烦热，咽干口燥等证。 \n炙甘草 桂枝 生姜（各三两） 大枣（十二枚） 芍药（六两） 胶饴（一升） \n上六味，以水七升，煮取三升，去渣，纳胶饴，更上微火消解，温服一升，日三服。呕 \n家不可用建中汤，以甜故也。 \n按∶此即桂枝汤加胶饴也。今方俱改两为钱，而以阿胶代胶饴，殊失本方之妙矣。 \n（《金匮》）\\x大建中汤\\x 治胸中大寒痛，呕不能饮食，腹中寒气上冲，上下疼痛不可触近。 \n人参（二两） 蜀椒（二合，炒去汗） 干姜（四两） 胶饴 \n上三味，以水四升，煮取二升，去滓，纳胶饴一升，微火煎取一升半，分二次温服，如 \n（《局方》）\\x十四味大建中汤\\x 治阳虚气血不足，腰脚筋骨疼痛，及荣卫失调，积劳虚损， \n形体羸瘠，短气嗜卧，渐成劳瘵者。 \n人参 白术 茯苓 甘草（炙） 川芎 当归 白芍 熟地 黄 肉桂 附子（炮） 麦 \n冬半夏（汤洗） 肉苁蓉（酒浸，各等分） \n上咀。每服五钱，水二钟，姜三片，枣二枚，煎八分，空心温服。 \n\\x八味大建中汤\\x 治中气不足，手足厥冷，小腹挛急，或腹满不食，阴缩多汗，腹中寒痛 \n，唇干精出，寒热烦冤，四体酸痛，及无根失守之火出于肌表，而为疹为斑，厥逆呕吐等证。 \n人参 甘草（炙，各一钱） 黄 （炙） 当归 芍药（酒炒） 桂心（各二钱） 半夏 附子（制， \n各二钱半） \n上咀。每服五钱，水二钟，姜三片，枣二枚，煎七分，食前服。人参建中汤 治虚劳自汗。 \n即前小建中汤加人参二两，煎法同。 \n\\x黄 建中汤\\x 治诸虚羸瘠百病。 \n即前小建中汤加黄 一两五钱，煎法同。 \n\\x当归建中汤\\x 治妇人血虚自汗。 \n即前小建中汤加当归二两，煎法同。 \n\\x三味建中汤\\x 治表虚自汗。 \n芍药（二钱） 甘草（一钱） 官桂（五分） \n姜三片，枣一枚，水煎服。 \n（东垣）\\x补中益气汤\\x 治劳倦伤脾，中气不足，清阳不升，外感不解，体倦食少，寒热疟 \n痢，气虚不能摄血等证。 \n人参 黄 （炒） 白术（炒） 甘草（炙，各钱半） 当归（一钱） 陈皮（五分） 升麻 柴胡（各三分） \n上加姜、枣，水煎，空心午前服。 \n（东垣）\\x调中益气汤\\x 治湿热所伤，体重烦闷，口失滋味，或痰嗽稠粘，寒热不调，体倦少食等证。 \n黄 （一钱） 人参 炙甘草 苍术（各五分） 橘红 木香 柴胡 升麻（各二分） \n水煎，空心服。一方有白芍三分，五味十五粒。 \n\\x归脾汤\\x 治思虑伤脾，不能摄血，致血妄行，或健忘怔忡，惊悸盗汗，嗜卧少食，或大 \n便不调，心脾疼痛，疟痢郁结，或因病用药失宜，克伐伤脾以致变证者，最宜用之。 \n人参 黄 白术 茯苓 枣仁（各二钱） 远志 当归（各一钱） 木香 炙甘草（各五分） \n水二钟，加圆眼肉七枚，煎七分，食远服。 \n愚意此汤之用木香，特因郁结疼痛者设，如无痛郁等证，必须除去木香，以避香燥，岂 \n不于气虚血动者为尤善乎。又远志味辛，气升而散，凡多汗而躁热者，亦宜酌用。 \n\\x加味归脾汤\\x 治脾经血虚发热等证。 \n即前方加柴胡、山栀各一钱。 \n\\x人参汤\\x 治吐血咯血后宜服，并治吐血不止。 \n人参（一两），为细末）五更时用鸡蛋清调如稀糊。每用二钱，茶匙抄服，服讫却卧，参尽则 \n效。愚意此方固佳，其或有恶腥者，但以真牛乳稀调炖熟，或温饮之，凡无火及微火者岂不 \n更妙。一方治吐衄咯血不止，用人参为末，以鸡子清投新汲水搅匀，调服一、二钱。 \n\\x独参汤\\x 治诸气虚气脱，及反胃呕吐喘促，粥汤入胃即吐，凡诸虚证垂危者。 \n用人参二两，水一升，煮取四合，乘热顿服，日再进之。兼以人参煮粥食之尤妙。 \n\\x夺命散\\x 治伤寒瘴疾阴阳不明，或误用药致病愈困，烦躁发渴，及妇人胎前产后受热瘴疾。 \n上党人参（七钱） \n水二钟，煎一钟，去渣，连罐浸新汲水中取冷，一服而尽，若鼻上有汗滴尤妙。 \n（严氏）\\x参附汤\\x 治真阳不足，上气喘急，呃逆自利，脐腹疼痛，手足厥冷，呕恶不食， \n自汗盗汗，气短头晕等证。 \n人参 制附子 \n用须参倍于附，或等分，不拘五钱或一两，酌宜用姜，水煎服。《良方》有丁香十五粒 \n，名加减参附汤。 \n\\x参归汤\\x 此即团参散，见小儿门十。亦名人参汤，见妇人门七七。治心虚盗汗。 \n人参 当归等分） \n上先用猪心一枚，破作数片，煎汤澄取清汁，煎药服。 \n\\x参术膏\\x 治中气虚弱，诸药不应，或因用药失宜，耗伤元气，虚证蜂起，但用此药补其 \n中气，诸证自愈。 \n人参 白术（等分） \n用水煎膏，化服之。一方用白术一斤，人参四两，切片，以流水十五碗浸一宿，桑柴文 \n、武火煎取浓汁，再用重汤熬膏，入真白蜜收之，每以白汤点服。 \n\\x参术汤\\x 治气虚颤掉，泄泻呕吐等证。 \n人参 白术 黄 （各二钱） 白茯苓 陈皮 炙甘草（各一钱） \n甚者加制附子一钱。 \n水二钟，煎八分，食远服。 \n（仲景）\\x术附汤\\x 一名白术附子汤。治中寒中气不足，四肢逆冷，口噤，牙关紧急，痰盛 \n脉弱，风虚头眩，头重苦极，不知食味。 \n白术（二两） 炙甘草（一两） 附子（一两半，炮去皮） \n每用五六钱，姜五片，枣一枚，水一钟半，煎七分，食远温服。或用此化苏合丸，连进三服效。 \n（《济生》）\\x术附汤\\x 治寒湿腰痛重冷，小便自利。 \n白术 附子（制，各一两） 杜仲（炒，半两） \n上咀。每服四钱，入姜煎服。 \n（严氏）\\x 附汤\\x 治气虚阳弱，虚汗倦怠。 \n黄 （蜜炙） 制附子（等分） \n每服四钱，水一钟，姜五片，煎六分，食远服。 \n（《宝鉴》）\\x当归补血汤\\x 治血气损伤，或因误攻致虚，肌热口渴，目赤面红，脉大而虚， \n重按全无，及病因饥饱劳役者。 \n黄 （炙，一两） 当归（酒洗，三钱） \n水一钟半，煎八分，食远服。 \n（《济生》）\\x黄 汤\\x 治喜怒惊恐房劳，致阴阳偏虚者，或自汗盗汗不止。 \n黄 （蜜炙） 熟地 白茯苓 天门冬 麻黄根 肉桂 龙骨（各一钱） 小麦（炒） 五味子 \n防风（各八分） 当归 炙甘草（各七分） \n水二钟，姜三片，煎服。如冷汗，加熟附子二片，发热自汗，加石斛一钱。 \n（《良方》）\\x黄 汤\\x 方在妇人。安胎，治腹痛。 \n（魏氏）\\x大补黄 汤\\x 治虚弱自汗。 \n人参 白茯苓 肉苁蓉 熟地（各一钱） 黄 白术 当归 山茱萸 防风（各八分） 炙甘 \n草肉桂（各四分） 五味子（十一粒） \n水一钟半，加姜三片，枣一枚，煎七分，不拘时服。 \n（东垣）\\x神效黄 汤\\x 治浑身或头面手足麻木不仁，目紧缩小，及羞明畏日，视物不明。 \n黄 （二钱） 人参（八分） 炙甘草 蔓荆子 芍药（各一钱） 陈皮（五分） \n水煎，临卧热服。如麻木不仁，虽有热证，不得用黄柏，但加黄 。 \n\\x黄 六一汤\\x 治阴阳俱虚盗汗。 \n黄 （蜜炙，六钱） 炙甘草（一钱） \n水一钟半，煎八分，食远服。 \n\\x玉屏风散\\x 治表虚自汗。 \n黄 （蜜炙） 防风（各一钱） 白术（炒，二钱） \n水一钟，姜三片，煎服。 \n（《良方》）\\x润神散\\x 治劳瘵憎寒壮热，口干咽燥，自汗疲倦烦躁。 \n人参 麦门冬 黄 桔梗 淡竹叶 炙甘草（等分） \n上每服一两，水煎服。如自汗，加小麦同煎。 \n\\x当归六黄汤\\x 方在寒阵。治阴虚血热盗汗神效。 \n\\x参苓散\\x 治睡中汗出。 \n人参 酸枣仁 白茯苓（各等分） \n上为细末，每服三钱，食远米饮调下。大人小儿皆可服。 \n（《和剂》）\\x参苓白术散\\x 治脾胃虚弱，饮食不进，呕吐泄泻，或久泻或大病后，调助脾胃。 \n人参 山药（炒） 白扁豆（去皮，姜汁炒） 莲肉（去心，各一斤半） 白术（二斤，米泔浸炒） \n桔梗（炒黄色） 砂仁 薏仁（炒） 白茯苓（去皮） 炙甘草（各一斤） \n上为细末，每服二钱，米汤调下。或加姜、枣水煎服。或炼蜜丸，桐子大，每服七、八 \n十丸，空心米饮、白汤任下。 \n\\x七味白术散\\x 方在小儿。治脾虚热渴。 \n（《医录》）\\x生脉散\\x 治热伤元气，肢体倦怠，气短口渴，汗出不止，或金为火制，水失所 \n生，而致咳嗽喘促，肢体痿弱，脚软眼黑等证。 \n人参（五钱） 麦冬 五味子（各三钱） \n水煎服。此方以生脉为名，故俗医之治脉脱者每多用此，是岂知脉脱由阳气，岂麦冬、 \n五味之所宜乎？见亦浅矣。 \n\\x五味子汤\\x 治喘促，脉伏而数，或虚烦作渴。 \n五味子（一钱） 人参 麦冬 杏仁 橘红（各一钱五分） \n水二钟，姜三片，枣二枚，煎八分，无时服。 \n（陈氏）\\x五味子汤\\x 治肾水枯涸，口燥舌干。 \n五味子 麦门冬（各一两） 黄 （炒，三两） 人参（二两） 粉草（炙，五钱） \n上每服五钱，水煎，日夜服数剂。 \n\\x人参胡桃汤\\x 治喘急不能卧。 \n人参（钱半） 胡桃肉（五枚，泡去皮） \n水一钟半，姜三片，枣一枚，煎八分，食后温服。 \n（丹溪）\\x琼玉膏\\x 治虚劳干咳嗽，或好酒者久嗽尤效。 \n人参（十二两） 白茯苓（十五两） 白蜜（五斤，熬去沫） 琥珀 沉香（各五钱） 大生地（十斤，以 \n银石器杵取自然汁） \n上先以地黄汁同蜜熬沸，搅匀，用密绢滤过，将人参等为极细末，和蜜汁入瓷、银瓶内 \n，用绵纸十余层加箬封扎瓶口，入砂锅或铜锅，以桑柴火，长流水没瓶煮三昼夜，取出换油 \n蜡纸扎口，悬浸井中半日以出火气，提起仍煮半日，以去水气，然后收藏。每日清晨及午后 \n，取三匙，用温酒一两许调服，或白汤亦可。制须净室，忌鸡、犬、妇人。本方原无琥珀、 \n沉香二味，乃 仙加入者，云奇效异常，今并录其方。 \n\\x补肺汤\\x 治劳嗽。 \n人参 黄 北五味 紫菀（各七分半） 熟地黄 桑白皮（各钱半） \n水二钟，煎八分，入蜜少许，食远温服。 \n（杨氏）\\x宁肺汤\\x 治荣卫俱虚，发热自汗，咳嗽痰涎，肺气喘急，唾脓。 \n人参 茯苓 当归 白芍药 白术 甘草（炙） 川芎 熟地黄 麦门冬 五味 桑白皮 \n（各七分） 阿胶（炒，一钱） \n水二钟，姜二片，紫苏五叶，煎八分，食远服。 \n（《圣惠》）\\x宁肺散\\x 方在固阵。 \n治久嗽，收涩之剂。 \n\\x凤髓汤\\x 治咳嗽，大能润肺。 \n牛髓（一斤， 骨中者） 白蜜（半斤） 干山药（四两，炒） 杏仁（四两，去皮尖，研如泥） \n胡桃仁（去皮，四两，另研） \n上将牛髓、白蜜用砂锅熬沸，以绢滤去渣，盛瓷瓶内，将杏仁等三味同入瓶内，以纸密 \n封瓶口，重汤煮一日夜，取出冷定。每空心以白汤化服一二匙。 \n（《良方》）\\x蜜酥煎\\x 治咳嗽胸痛，上气喘壅。此为邪搏于肺，气不宣通，故咳而喘，气上 \n逆，面目浮肿。此方非独治嗽，兼补虚损，去风燥，悦肌肤，妇人服之尤佳。 \n白沙蜜（一升） 牛酥（一升） 杏仁（三升，去皮尖，研如泥） \n上将杏仁于瓷盆中用水研取汁五升，以净铜锅先倾汁三升，熬减其半，又倾汁二升，再 \n以微火熬减至一升许，即入蜜、酥二味煎熟，其药乃成，贮于净瓷器中。每日三次，以温酒 \n或米饮、白汤调服一匙，服至七日，唾色变白，二七唾稀，三七嗽止。 \n\\x醍醐膏\\x 治一切咳血肺疾。 \n用好牛酥五斤，熔三遍，凝取当出醍醐，含服一合即瘥。 \n（《良方》）\\x黄 散\\x 治嗽久劳嗽唾血。 \n黄 （蜜炙） 糯米（炒） 阿胶（炒，等分） \n上为细末。每服二钱，米饮调下。 \n（《拔萃》）\\x五味黄 散\\x 治咳嗽咯血成劳，眼睛疼痛，四肢困倦，脚膝无力。 \n五味子 人参 芍药 甘草（各五分） 黄 桔梗（各钱半） 熟地 麦冬（各一钱） \n水二钟，煎八分，食后温服。 \n\\x黄 益损汤\\x 治男妇诸虚百损，五劳七伤，骨蒸潮热，百节疼痛，盗汗惊惕，咽燥唇焦 \n，憔瘦少力，咳嗽多痰，咯吐衄血，寒热往来，颊赤昏倦少食，服热药则热烦躁满，服寒药 \n则膈满腹痛，及大病后荣卫不调，或妇人产后血气未足，俱宜服此。 \n人参 黄 当归 熟地黄 白术 川芎 芍药 麦冬 甘草 茯苓 山药 五味子 \n木香 石斛 肉桂 丹皮（等分） \n上咀。每服一两，水一钟半，姜五片，枣二枚，小麦五十粒，乌梅一个，煎七分，食前服。 \n（《元戎》）\\x地黄散\\x 治衄血往来久不愈。 \n生地黄 熟地黄 地骨皮 枸杞子 \n上等分，焙干为细末，每服二钱，蜜汤调下，不拘时。 \n（《良方》）\\x柔脾汤\\x 治虚热吐血、衄血、汗出。 \n甘草（炒） 白芍药（炒） 黄 （炒，各半两） 熟地黄（两半） \n上每服五、七钱，水煎服。世治吐血并用竹茹、地黄、藕汁、童便，此亦不可拘泥。如 \n阳乘于阴，血得热则流散，经水沸溢，理宜凉解，以大黄、犀角之类；如阴乘于阳，所谓天 \n寒地冻，水凝成冰，须当温散，宜干姜、肉桂，或理中汤之类。 \n（东垣）\\x麦门冬饮子\\x 治吐血久不愈者。 \n麦门冬 黄 （各一钱） 人参 归身 生地（各五分） 五味子（十粒） \n上 咀。水煎服。 \n（《拔萃》）\\x麦门冬饮子\\x 治脾胃虚，气促气弱，精神短少，衄血吐血，气虚不能摄血者。 \n麦冬 当归 芍药 紫菀（各一钱） 人参 黄 （各八分） 甘草（五分） 五味子（九粒） \n水二钟，煎一钟，食后服。 \n（《家抄》）\\x麦门冬饮\\x 方在寒阵。 \n治虚火咳嗽，阴虚劳损。 \n\\x麦门冬汤\\x 方在寒阵。 \n治肺热咳嗽见血。 \n（万氏）\\x麦门冬汤\\x 方在痘疹。 \n治表邪内热咳嗽。 \n\\x麦门冬散\\x 治鼻衄。 \n麦门冬 生地（各一钱） 白芍药 蒲黄（各二钱） \n水二盏，姜三片，煎八分，食后温服。 \n\\x旋神饮\\x 治劳瘵憎寒壮热，口干咽燥，自汗烦躁，咳嗽唾血，瘦剧困倦。 \n人参 白术 黄 当归 熟地黄 麦门冬 白芍药 茯神 白茯苓 莲肉 五味子 \n炙甘草 桔梗 半夏曲（各五分） \n水一钟半，红枣一枚，乌梅一个，煎七分，食远服。如嗽，加阿胶；胸满，加木香，以 \n湿纸包，炮用，或加沉香亦可；如不思饮食，加扁豆炒用。 \n（《医统》）\\x养心汤\\x 治体质素弱，或病后思虑过多，心虚惊悸不寐。 \n归身 生地 熟地 茯神（各一钱） 人参（钱半） 麦冬（钱半） 枣仁 柏子仁（各八分） 炙甘草 \n（四分） 五味子（十五粒） \n加灯心、莲子，水煎八分服。 \n（钱氏）\\x养心汤\\x 方在小儿。治心虚惊痫。 \n\\x正心汤\\x 治七情五志久逆，心风妄言妄笑，不知所苦。 \n人参 当归（酒洗） 生地黄 茯神（各一钱） 羚羊角（镑为末） 枣仁（炒，研） 甘草（炙） \n远志（制，各八分） \n水一钟半，莲子七枚，煎七分，入羚羊角末、麝香半分，和匀，食后临卧服。 \n\\x开心散\\x 治好忘。后定志丸稍胜于此（百十六）。 \n人参 远志（各二钱半） 石菖蒲（一两） 白茯苓（二两） \n上为细末，每服一钱，食后米饮调下。 \n（《局方》）\\x茯苓补心汤\\x 治心虑过多，心神溃乱，烦躁不寐。 \n白茯苓 白茯神 麦门冬 生地黄 当归 半夏曲 陈皮（各一钱） 甘草（五分） \n上加竹叶、灯心，同煎服。 \n\\x酸枣仁汤\\x 治病后气血俱虚，内亡津液，烦热，诸虚不眠者。 \n枣仁（微炒） 人参（各一钱） 麦冬（三钱） 竹茹（一钱） \n加龙眼肉五枚，煎服，无时。 \n（《秘传》）\\x酸枣仁汤\\x 治心肾水火不交，精血虚耗，痰饮内蓄，怔忡恍惚，夜卧不安。 \n枣仁（炒） 远志 黄 白茯苓 莲肉（去心） 当归 人参 茯神（各一钱） 陈皮 炙甘 \n草（各五分） \n水一钟半，加生姜三片，枣一枚，煎七分，日一服，临卧一服。 \n（仲景）\\x酸枣仁汤\\x 治虚劳虚烦不得眠。 \n酸枣仁（二升） 甘草（一两） 知母 茯苓 川芎（各二两） （《深师方》仍有生姜二两） \n上五味，以水八升，煮酸枣仁得六升，纳诸药再煮取三升，分温三服。 \n（钱氏）\\x酸枣仁汤\\x 方在小儿。 \n治心肺虚热烦躁。 \n\\x远志汤\\x 治心虚烦热，夜卧不宁，及病后虚烦。 \n远志（黑豆、甘草同煮） 黄 当归 麦冬 枣仁（炒） 石斛（各钱半） 人参 茯神（各七 \n分） 甘草（五分） \n水二钟，煎八分，食远服。烦甚者，加竹叶、知母。 \n\\x远志饮子\\x 治心劳虚寒，梦寐惊悸。 \n远志肉 茯神 人参 当归（酒浸） 枣仁 黄 肉桂（各一两） 炙甘草（五钱） \n上 咀。每服一两，水一钟半，姜五片煎服，无时。 \n（东垣）\\x圣愈汤\\x 治血虚心烦，睡卧不宁，或五心烦热。 \n人参 川芎 当归 熟地黄（酒拌蒸） 生地黄（酒拌） 黄 （炙，各一钱） \n上水煎服。 \n\\x益荣汤\\x 治思虑过度，心血耗伤，怔忡恍惚不寐。 \n人参（一钱） 芍药 枣仁 柏子仁（各五分） 当归 黄 茯神（各一钱） 紫石英（五分） 远志 \n甘草 木香（各三分） \n水一钟半，姜三片，枣一枚，煎八分服。 \n（《元戎》）\\x逍遥散\\x 治肝脾血虚，及郁怒伤肝，少血目暗，发热胁痛等证。 \n当归 芍药 白术 茯神 甘草 柴胡（各等分） \n上姜、水煎服。 \n（薛氏）\\x加味逍遥散\\x 治肝脾血虚，发热，小水不利。 \n即前逍遥散加丹皮、栀子各七分。 \n\\x生姜汁煎\\x 治噎食不下，咽喉闭塞，胸膈烦闷。 \n生姜汁 白蜜 牛酥（各五两） 人参 百合（各二两） \n上入铜铫中，以慢火熬膏，每用一二匙，用人参百合汤调下，或咽下。 \n（《局方》）\\x胃风汤\\x 治风冷乘虚入客肠胃，水谷不化，泄泻注下，及肠胃湿毒，下如豆汁 \n，或下瘀血，日夜无度。 \n人参 白术 茯苓 当归 川芎 白芍药 肉桂（等分） \n上为粗散，每服二钱，入粟米数粒同煎，食前服。 \n此方名为治风而实非治风，乃补血和血，益胃气之药，下血痢而挟虚者，实可倚仗，出 \n太阳桂苓汤例药也。 \n（《选要》）\\x十宝汤\\x 治冷痢虚甚，下物如鱼脑，三服愈。 \n黄 （炙，四钱） 熟地黄 人参 白术 白芍药 当归 茯苓 半夏 五味子 肉桂（各一 \n钱） 甘草（炙，五分） \n水一钟，姜三片，乌梅一个，煎七分，食远服。 \n《良方》\\x当归黄 汤\\x 治妊娠下痢，腹痛小便涩。 \n当归（炒） 黄 （各一两） 糯米（一合） \n水二钟，煎一钟，温服。 \n（《局方》）\\x大防风汤\\x 治足三阴亏损，寒湿外邪乘虚内侵，患鹤膝、附骨等疽，不问已溃 \n未溃，宜先用此。及治痢后脚膝软痛，不能动履，名曰痢后风。此药祛风顺气，活血壮筋骨 \n，行履如故。 \n人参 白术 防风 羌活（各二钱） 黄 （一钱） 熟地 杜仲（各二钱） 官桂 甘草（炙，各五 \n分） 白芍 牛膝 附子（各一钱） 川芎（钱半） \n水煎服。一方有当归，无官桂，加姜七片。 \n（河间）\\x地黄饮子\\x 治舌喑不能言，足废不能行，此谓少阴气厥不至，急当温之，名曰痱 \n证。凡阴虚有二，有阴中之水虚，有阴中之火虚，此治火虚之剂。 \n熟地 巴戟（去心） 山茱萸 肉苁蓉（酒浸） 附子 石斛 五味 石菖蒲 茯苓 远志 \n官桂 麦门冬 \n上等分，每服五钱，入薄荷少许，姜、枣煎服。 \n\\x金樱膏\\x 治虚劳遗精、白浊最效。 \n金樱子（经霜后采红熟者，撞去刺，切开去核，捣碎煮之，滤榨净汁用，熬成膏） 人参 \n桑螵蛸（新瓦焙燥） 山药（各二两） 杜仲（姜汁炒） 益智仁（各一两） 薏仁 山茱萸 芡实 \n枸杞（各四两） 青盐（三钱） \n上咀。用水同熬二次，去渣，熬成膏，将金樱膏对半和匀，空心白汤下三、四匙。 \n\\x心虚白浊歌\\x \n白浊皆因心气虚，不应只作肾虚医。 \n四君子汤加远志，一服之间见效奇。 \n\\x劫劳汤\\x 方在妇人。治虚劳咳嗽，盗汗发热。 \n\\x益气补肾汤\\x 治气虚眩晕。 \n人参 黄 （各一钱二分） 白术（二钱） 白茯苓（一钱） 山药 山茱萸（各钱半） 炙甘草（五分） \n水二钟，枣二枚，煎八分，食前服。 \n（《元戎》）\\x当归酒\\x 治血虚头痛欲裂。 \n当归（一两）好酒（一升），煮取六合服之。 \n\\x人参丸\\x 宁心益智，安神固精。 \n人参 茯苓 茯神 枣仁 远志 益智 牡蛎（各五钱） 朱砂（二钱半） \n为末，枣肉丸服。 \n（《千金》）\\x人参固本丸\\x 治脾虚烦热，金水不足，及肺气燥热，作渴作嗽，或小便短少赤 \n色，涩滞如淋，大便燥结，此阴虚有火之圣药也。 \n人参（二两） 天冬（炒） 麦冬（炒） 生地黄 熟地黄（各四两） \n蜜丸，桐子大。每服五、六十丸，空心温酒或淡盐汤下。 \n中寒之人不可服。如欲作膏，俟煎成，外加白蜜四两。 \n\\x团参丸\\x 治吐血咳嗽服凉药不得者。团参散方在小儿。 \n人参 黄 飞罗面（各一两） \n上为细末，滴水和丸，桐子大。每服五、七十丸，茅根汤下。 \n\\x天王补心丹\\x 宁心保神，固精益血，壮力强志，令人不忘，去烦热，除惊悸，清三焦， \n解干渴，育养心气。此方之传，未考所自。《道藏》偈云∶昔志公和尚日夜讲经，邓天王悯 \n其劳者也，锡之此方，因以名焉。 \n生地黄（四两，洗净） 人参 玄参（炒） 丹参（炒） 远志（炒） 桔梗（各五钱） 白茯苓（五钱） \n五味（炒） 当归（酒洗） 麦冬（炒） 天冬（炒） 柏子仁（炒） 酸枣仁（炒，各一两） \n上为细末，炼蜜为丸，每两分作十丸，金箔为衣。每服一丸，灯心枣汤化下，食远临卧 \n服。或作小丸亦可。 \n《类方》∶如前方，内多黄连二两（酒炒）。 \n《医统》方∶此较前多百部、菖蒲、杜仲三味。 \n生地黄（二两，用砂仁五钱、茯苓一两同煮，去砂仁不用） 人参 玄参 丹参 远志 柏 \n子仁（炒） 枣仁（炒） 白茯神 杜仲（制） 百部（各一两） 归身（一两六钱） 天冬 麦冬（各一两 \n二钱） 桔梗（八钱） 五味 石菖蒲（各五钱） \n《得效》方用熟地，不用生地，余如《医统》，又外加茯苓、炙甘草，共一十八味，分 \n两俱各等分。 \n按∶上方惟前十三味者，乃《道藏经》本方。此外各有不同，亦惟随宜择用可也。 \n《百一》\\x补心神效丸\\x \n黄 （蜜炙） 茯神 人参（各四两） 远志（制，二两） 熟地黄（三两） 枣仁（炒） 柏子仁（另 \n研） 五味子（各二两） 朱砂（一两，另研） \n上为末，炼蜜丸，桐子大。每服五十丸，米饮、温酒任下。盗汗不止，麦麸汤下；梦遗 \n失精，人参龙骨汤下；卒暴心痛，乳香汤下；虚烦发热，麦门冬汤下；吐血，人参汤下；大 \n便下血，地榆汤下；小便出血，茯苓车前子汤下；中风不语，薄荷生姜汤下；风痫痰气，防 \n风汤下。 \n（《局方》）\\x平补镇心丹\\x 治心血不足，时或怔忡，夜多乱梦，如堕岸谷。常服安心肾，益 \n荣卫。 \n人参 龙齿（各二两五钱） 白茯苓 茯神 麦冬 五味（各一两二钱半） 车前子 远志（制） \n天冬 山药（姜汁炒） 熟地（酒蒸，各一两半） 朱砂（两半，为衣） 枣仁（炒，三钱） \n炼蜜丸，桐子大。每服八、九十丸，早晚米饮或温酒下。一方有肉桂一两二钱五分。一 \n方有当归、柏子仁、石菖蒲。 \n（《集验》）\\x柏子养心丸\\x 治心劳太过，神不守舍，合眼则梦，遗泄不常。 \n柏子仁（鲜白不油者，以纸包槌去油） 白茯神 酸枣仁 生地黄 当归身（各二两） 五味 \n子辰砂（细研） 犀角（镑） 甘草（各半两） \n上为末，炼蜜丸如芡实大，金箔为衣。午后临卧各津嚼一丸。 \n（古庵）\\x心肾丸\\x 治水火不济，心下怔忡，夜多盗汗，便赤梦遗。 \n牛膝（酒浸） 苁蓉（酒浸） 熟地黄（各二两） 菟丝子（酒煮，三两） 人参 黄 （蜜炙） 当 \n归（酒浸） 山药（炒） 鹿茸（酥炙） 附子（炮去皮脐） 茯神 五味子 龙骨（ ） 远志（甘 \n草汤浸剥，姜汁炒，各一两） \n上为细末，酒煮面糊丸，桐子大。每服百丸，空心枣汤或清汤送下。 \n（《济生》）\\x远志丸\\x 治心神恍惚不宁，梦泄遗精。 \n人参 茯神 白茯苓 龙齿 远志（姜汤浸炒） 石菖蒲（各二两） \n蜜丸，桐子大，朱砂为衣。每服七、八十丸，空心盐汤下。 \n\\x宁志丸\\x 治怔忡惊悸癫痫。（《得效》）宁志丸，方在和阵，与此稍同。 \n人参 枣仁（酒浸） 茯苓 柏子仁 当归 远志（酒浸） 茯神 石菖蒲 琥珀（各五钱） \n乳香 朱砂（各三钱） \n上为末，炼蜜丸，桐子大。每服三、五十丸，食后枣汤下。 \n\\x宁志膏\\x 治因惊失志。 \n人参 枣仁（泡去皮，纸炒） 朱砂（各半两） 滴乳香（一钱，另研） \n上为末，炼蜜丸，弹子大。每服十丸，薄荷汤下。 \n\\x定志丸\\x 治心气不足，惊悸恐怯，或语鬼神，喜笑，及目不能近视，反能远视，乃阳气 \n不足也，宜此方主之。此方与前开心散小异。 \n人参 茯苓（各二两） 菖蒲 远志（制，各一两） \n炼蜜丸，桐子大，朱砂为衣。每服五、七十丸，米饮下。 \n（《拔萃》）\\x八物定志丸\\x 补心神，安魂魄，去热除痰。 \n人参（一两半） 石菖蒲 茯神 远志（制，各一两） 麦门冬 白术（各五钱） 朱砂（一钱） 牛黄 \n（二钱，另研） \n上为细末，炼蜜丸，桐子大，朱砂为衣。每服五十丸，米饮下。一方有茯苓一两。 \n\\x十四友丸\\x 治惊悸怔忡。 \n人参 黄 当归 生地黄 远志 茯神 茯苓 枣仁（泡去皮，隔纸炒） 阿胶（炒） \n龙齿 紫石英 薄荷 朱砂（各一两） \n上为末，炼蜜丸，桐子大。每服五、七十丸，食后临卧枣汤下。 \n（《秘验》）\\x琥珀多寐丸\\x 治健忘恍惚，神虚不寐。 \n真琥珀 真羚羊角（细镑） 人参 白茯神 远志（制） 甘草（等分） \n上为细末，猪心血和炼蜜丸，芡实大，金箔为衣。每服一丸，灯心汤嚼下。 \n（《金匮》）\\x六味地黄丸\\x 即《金匮》肾气丸，亦名地黄丸。治肾水亏损，小便淋闭，头目 \n眩晕，腰腿酸软，阴虚发热，自汗盗汗，憔悴瘦弱，精神疲困，失血失音，水泛为痰，病为 \n肿胀，壮水制火之剂也。 \n熟地黄（八两，蒸捣） 山茱萸 山药（炒，各四两） 丹皮 泽泻 白茯苓（各三两） \n上为细末，和地黄膏加炼蜜为丸，桐子大。每服七、八十丸，空心食前滚白汤，或淡盐 \n汤任下。此方用水煎汤，即名六味地黄汤，下八味丸亦同。 \n（崔氏）\\x八味地黄丸\\x 治命门火衰，不能生土，以致脾胃虚寒，饮食少思，大便不实，或 \n下元冷惫，脐腹疼痛等证。王太仆曰∶益火之源以消阴翳，即此谓也。即前六味地黄丸加肉 \n桂、制附子各一两。 \n（陈氏）\\x加减八味丸\\x 治肾水不足，虚火上炎，发热作渴，口舌生疮，或牙根溃蚀，咽喉 \n疼痛，寝汗憔悴等证。 \n此临川陈自明方。李氏云∶凡发背之热，未有不自肾虚而得之者，必须五更服加减八味 \n丸。即前六味丸加肉桂一两、五味子四两炒用。纳泽泻切片，蒸五次焙用。一方五味止用一两。 \n（《良方》）\\x益阴肾气丸\\x 治阴虚潮热盗汗，烦热作渴，筋骨疼痛，月经不调等证。即前六 \n味丸加当归、生地各四两，五味子二两。 \n（薛氏）\\x加减《金匮》肾气丸\\x 治脾肾阳虚，不能行水，小便不利，腰重脚肿，或肚腹肿 \n胀，四肢浮肿，或喘急痰盛，已成臌证，其效如神。此证多因脾胃虚弱，或治失其宜，元气 \n复伤而变此证。若非速救肾中之火，则阳气不充于下，何以生土？土虚又何以制水？此必用之 \n剂也，苟不知此，必不能救。若病在燃眉，当变丸为汤治之。 \n熟地（四两，酒拌蒸） 山药 山茱萸 川牛膝 丹皮 泽泻 车前子 肉桂（各一两） 白茯 \n苓（三两） 附子（制，五钱） \n上为末，炼蜜同地黄膏捣丸，桐子大。每服七、八十丸，空心米饮下。 \n（丹溪）\\x滋阴大补丸\\x 治诸虚不足，腰腿疼痛，行步无力。壮元阳，益肾水。 \n熟地（二两） 山药（炒） 牛膝（各两半） 山茱萸 杜仲 巴戟肉 白茯苓 五味子 小茴香 \n（炒） 肉苁蓉（酒洗去甲，新瓦焙干） 远志（甘草汤煮，晒干，各一两） 石菖蒲 枸杞（各五钱） \n上为末，红枣肉和或炼蜜为丸，桐子大。每服七、八十丸，空心淡盐汤或温酒任下。 \n\\x大造丸\\x 方在寒阵。治阴虚血热诸证。 \n（《秘方》）\\x全鹿丸\\x 此药能补诸虚百损，五劳七伤，攻效不能尽述。人制一料服之，可以 \n延年一纪。其法须四人共制一鹿，分而服之，逾年又共制之，四人共制四年，则每人得一全 \n鹿。若一人独制一料，恐久留变坏，药力不全矣。 \n中鹿一只 缚杀之，退去毛，将肚杂洗净，同鹿肉加酒煮熟，将肉横切，焙干为末；取 \n皮同杂仍入原汤熬膏，和药末、绞肉加炼蜜和捣为丸。其骨须酥炙为末，同入之。 \n人参 白术（炒） 茯苓 炙甘草 当归 川芎 生地黄 熟地黄 黄 （蜜炙） 天门冬 \n麦门冬 枸杞 杜仲（盐水炒） 牛膝（酒拌蒸） 山药（炒） 芡实（炒） 菟丝（制） 五味子 \n锁阳（酒拌蒸） 肉苁蓉 破故（酒炒） 巴戟肉 胡芦巴（酒拌蒸） 川续断 覆盆子（酒拌 \n蒸） 楮实子（酒拌蒸） 秋石 陈皮（上各一斤） 川椒（去目，炒） 小茴香（炒） 沉香 青盐（各半斤） \n上先须精制诸药为末，和匀一处，候鹿胶成就，和捣为丸，桐子大，焙干。用生黄绢作 \n小袋五十条，每袋约盛一斤，悬置透风处，用尽一袋，又取一袋。阴湿天须用火烘一二次为 \n妙。每服八、九十丸，空心临卧姜汤、盐汤、白汤任下，冬月温酒亦可。 \n（《青囊》）\\x仙传斑龙丸\\x 壮精神，除百病，养气血，补百损，老人虚人常服，延年益寿。 \n昔蜀中有道士酣歌酒肆曰∶尾闾不禁沧海竭，九转金丹都慢说，惟有斑龙顶上珠，能补玉堂 \n关下血。真人仲源索方传世。 \n鹿角胶 鹿角霜 柏子仁 菟丝子（制） 熟地黄（各八两） 白茯苓 补骨脂（各四两） \n上将胶先溶化，量入无灰酒打糊丸，桐子大。每服六、七十丸，空心淡盐汤或酒任下。 \n（《秘验》）\\x斑龙二至百补丸\\x 此药固本保元，生精养血，培复天真，大补虚损，益五内， \n除骨蒸，壮元阳，多子嗣，充血脉，强健筋骸，美颜色，增延寿算，聪明耳目，润泽髭须， \n真王道奇品之方，功难尽述也。 \n鹿角（五十两为则） 取新角连脑骨者佳，锯长二寸许，用米泔浸一宿，刷洗净，同后药入坛煮胶。 \n黄精（八两） 枸杞 怀熟地 菟丝子（淘洗净） 金樱子（去毛、子，各四两） 天门冬（去心） \n麦门冬（去心） 川牛膝 龙眼肉 楮实子（各二两） \n以上十味，同角入金华好坛，层层放实，以新汲淡水入坛平肩，用蜜梭布四层包口，以 \n新砖压之，置大锅中井字架上，以木甑盖好，重汤煮三日夜，毋得间断火候。傍用小锅烧滚 \n水，不时添注坛内，并锅水勿使干涸。日足取起，滤去滓，将汁用罗底绢绞出，入净砂锅内 \n，文火熬成膏，约一斤半，外炼蜜二斤，滴水成珠，搀入调和后药，杵合为丸。 \n鹿角霜（十两） 人参（五两） 黄 （蜜炙） 芡实（炒） 白茯苓 山药（炒） 山茱萸 生地黄 \n（酒洗，饭上蒸过） 知母（盐水炒，各四两） 北五味子（一两） \n夏月加川黄柏四两，炒褐色。 \n以上十味为细末，用前膏和匀，木杵捣丸，桐子大。空心淡盐汤送下百余丸，随用煮熟 \n莲肉或干枣数枚压之，俾纳丹田也。 \n（《正传》）\\x鹿角胶丸\\x 治血气亏损，两足痿弱，不能行动，久卧床祷者，神效。 \n鹿角胶（一斤） 鹿角霜 熟地（各半两） 当归（四两） 人参 牛膝 菟丝子（制） 白茯苓（各三 \n两） 白术 杜仲（各二两） 虎胫骨（酥炙） 龟板（酥炙，各一两） \n上为末，先将鹿角胶用无灰酒二钟溶化，加炼蜜捣丸，桐子大。每服百丸，空心盐姜汤下。 \n\\x鹿茸丸\\x 治香港脚腿腕生疮，及阴虚下元痿弱，咳嗽等证。 \n鹿茸（酥炙，另捣成泥） 五味子 当归 熟地黄（各等分） \n酒糊和丸，桐子大。每服四、五十丸，温酒或盐汤任下。 \n（《集验》）\\x鹿茸丸\\x 治诸虚劳倦。补心肾，益气血。 \n鹿茸（酥炙） 熟地黄 当归 枸杞 枣仁（炒） 附子（制） 牛膝 远志（姜汁浸炒） 山 \n药沉香 肉苁蓉（酒浸，各二两） 麝香（五分） \n炼蜜丸，桐子大。每服五十丸，盐汤下。 \n（《三因》）\\x鹿茸丸\\x 治失志伤肾，肾虚消渴，小便无度。 \n鹿茸（酥炙） 麦门冬 熟地黄 黄 （炙） 五味 肉苁蓉 鸡内金（酒炒） 山茱萸 破 \n故纸（炒，各七钱） 茯苓 人参 牛膝（酒浸） 玄参 地骨皮（各半两） \n上为末，炼蜜丸，桐子大。每服七、八十丸，米饮下。 \n（《本事》）\\x麋茸丸\\x 治肾虚腰痛，不能转侧。 \n麋茸（鹿茸亦可） 菟丝子（制，各一两） 舶茴香（五钱） \n上为末，以羊肾二对，用酒煮烂，去膜，研如泥，和丸，桐子大，阴干。如太干，以酒 \n糊佐之。每服三、五十丸，温酒或盐汤下。 \n（杨氏）\\x还少丹\\x 治脾肾虚寒，饮食少思，发热盗汗，遗精白浊，真气亏损，肌体瘦弱等证。 \n熟地黄（二两） 山药 山茱萸 杜仲（姜汤炒） 枸杞（二两） 牛膝（酒浸） 远志（姜汁浸炒） \n肉苁蓉（酒浸） 北五味 川续断 楮实子 舶茴香 菟丝子（制） 巴戟肉（余各一两） \n上为细末，炼蜜丸，桐子大。每服五十丸，空心盐酒下。 \n（《局方》）\\x无比山药丸\\x 治诸虚损伤，肌肉消瘦，耳聋目暗。常服壮筋骨，益肾水，令人不老。 \n山药（二两） 菟丝子（三两，酒浸煮） 五味（拣净，六两） 肉苁蓉（四两，切片酒浸，焙） 杜仲 \n（三两，酒炒） 牛膝（一两，酒浸蒸） 熟地 泽泻 山茱萸 茯苓 巴戟肉 赤石脂（各一两） \n上为细末，炼蜜和丸，桐子大。每服三、五十丸，食前温酒或米饮下。 \n\\x还元丹\\x 一名延年益寿不老丹。此药大补元气，服一月自觉异常，功效不可尽述。按， \n此方为阴虚血热者宜之，诸阳虚者不可用。 \n何首乌（半斤，用米泔水浸软，竹刀刮去皮，分四制。忌铁器，以砂锅、瓦器盛酒拌芝麻 \n蒸一次，晒干；又用羊肉一斤切片拌蒸一次，晒干；再用酒拌蒸一次，黑豆拌蒸一次，各晒 \n干） 熟地 生地（酒浸焙，各三两） 天冬 麦冬（各末，一两） 人参（五钱） 地骨皮（童便浸晒） \n白茯苓（酒浸晒干取末，各一两） \n上取乳汁六两，白蜜十两，同炼一器中，合前末为膏，瓷器取贮，勿令泄气。不拘时服 \n一、二匙，沸汤嗽咽之。 \n（《经验》）\\x养荣丸\\x 治男妇气血两虚，精神短少，脾胃不足，形体羸瘦。 \n人参 白术（土炒） 当归 熟地黄 黄 芍药 山药（各一两） 远志（制） 生地黄 山 \n茱萸（各半两） 白茯苓（二两） 陈皮（八钱） \n上为细末，用鸭一只，取血入炼蜜和丸，桐子大。每服八、九十丸，食前淡盐汤送下，或酒亦可。 \n\\x三才丸\\x \n天门冬 熟地黄 人参（等分） \n上为末，炼蜜丸服。 \n\\x七珍至宝丹\\x 补血生精，泻火益水，强筋骨，黑须发，补益之功甚大。 \n何首乌（赤、白各半斤，酒浸软，竹刀刮去皮，同牛膝蒸） 川牛膝（半斤，净，用黑豆三升 \n，同何首乌层层拌铺甑内，蒸极熟，取出去豆，与何首乌共捣如泥） 白茯苓（一斤，用人乳五 \n升煮干为度） 赤茯苓（一斤，用牛乳五升煮干为度） 当归（四两，酒浸，焙干） 枸杞（四两） 破 \n故（炒香） 菟丝子（制，各半两） \n炼蜜为丸，鸡头子大。每服一丸，日进三服，空心温酒、午后姜汤、临卧盐汤送下。 \n（《百一》）\\x补髓丹\\x 治老人虚弱肾伤，腰痛不可屈伸。 \n杜仲（十两） 补骨脂（用芝麻五两同炒，以芝麻黑色无声为度，去麻不用，十两） 鹿茸（四两， \n燎去毛，酒浸炙） \n上为末，用胡桃肉三十个，浸去皮，捣为膏，入面少许，煮糊为丸，桐子大。每服百丸 \n，温酒、盐汤任下。 \n\\x枸杞子丸\\x 治肾虚精滑，补精气。 \n甘州枸杞 黄精（九蒸九晒） \n上二味等分，相和捣作饼子，焙干为末，炼蜜丸，桐子大。每服百余丸，空心温酒送下。 \n（《局方》）\\x青娥丸\\x 治肾虚腰痛，益精助阳，乌须壮脚力，妇人随证用引吞送，神效。 \n破故纸（四两，炒香） 杜仲净（八两，姜汤炒） 胡桃肉（十两） \n上为末，用蒜四两，捣膏和丸，桐子大。每服三、五十丸，空心温酒送下。一法不用蒜 \n，以酒糊为丸，或炼蜜为丸，服者更佳。按，此方可加巴戟肉、大茴香各四两为尤妙。或再 \n加肉苁蓉亦可。 \n（《良方》）\\x加味青娥丸\\x 补诸虚不足，滋益阴阳，美容颜，健腰膝，止腰痛尤效。 \n破故（炒） 小茴（盐水炒） 胡芦巴（炒，各四两） 杜仲（三两，姜汁炒） 胡桃肉（二十五个） \n莲蕊（一两） 青盐（ ，五钱） 穿山甲（酥炙，三钱五分） \n上为末，将胡桃肉捣烂，加酒煮面糊为丸，桐子大。每服三十丸，空心温酒下。 \n\\x十补丸\\x 方在热阵。治肾脏虚冷等证。 \n（《保命》）\\x煨肾丸\\x 治肾肝虚损，骨痿不能起床，筋弱不能收持，及脾损谷不化，善益精 \n缓中消谷。 \n杜仲（姜汤炒） 牛膝 萆 白蒺藜 防风 菟丝子（制） 胡芦巴 肉苁蓉（酒浸） 破 \n故纸（酒炒，各等分） 官桂（减半） \n上将猪腰子制如食法，捣烂加炼蜜和杵千余为丸，桐子大。每服五、七十丸，空心用温 \n酒送下。治腰痛不起甚效。 \n（《局方》）\\x煨肾散\\x 治肾虚腰痛。 \n杜仲（姜汁炒） 花椒（炒出汁） 食盐（少许） \n上为末，以猪腰子一枚，薄批作五、七片，以椒盐淹去腥水，掺杜仲末三钱在内，以薄 \n荷包，外加湿纸二、三层，煨熟食之，酒下。 \n\\x安肾丸\\x 方在热阵。治肾经积冷，下元衰弱。 \n\\x小安肾丸\\x 方在热阵。治肾气虚寒，多溺，腰膝沉重。 \n\\x石刻安肾丸\\x 方在热阵。治真气虚惫，梦遗便数，脚膝软弱。 \n\\x红铅丸\\x 一名一气丹。一名人精妙合丸。 \n紫河车（用头产壮盛男胎者一具，以银针挑去紫血，米泔水洗净，用酒、醋炖烂焙干） \n人乳（以瓷罐盛晒干者四两。或以茯苓末一两收晒至五两者亦可） 秋石（以童男女小便炼成 \n者，四两） 红铅（亦名先天梅子，五钱，此室女初次经血。扣算女子年岁，凡五千四十八日，即 \n女子天癸将至之日，须预备锡船候取，以茯苓未收渗晒干；或以丝绵渗取，用乌梅煎汤洗下 \n，去水晒干亦可） \n上为细末，炼蜜为丸，每丸重七厘。此药俗传云以人补人，得先天之气，神妙不可尽述 \n，每丸价一两。 \n\\x打老儿丸\\x \n熟地 山药（炒，各五两） 牛膝（酒洗） 巴戟（枸杞汤洗，炒） 楮实子（去浮者） 枸杞 \n石菖蒲 远志肉（甘草汤制） 白茯苓（去筋） 杜仲（盐水炒） 北五味（蜜水拌蒸一二时，捣 \n饼焙干） 山茱萸（上各四两） 小茴香 续断（各三两） 肉苁容（切片酥炒，五两） \n上为末，炼蜜丸，桐子大。每服五、六十丸，空心、午前、临睡，或酒或盐汤下百余丸。 \n\\x肉苁蓉丸\\x 治肾虚耳聋。 \n肉苁蓉（酒浸，焙） 菟丝子（酒浸煮，研） 山茱萸 白茯苓 熟地黄 人参 官桂 防 \n风芍药 黄 （各五钱） 附子（炮） 羌活 泽泻（各二钱半） 羊肾（一对薄切，去筋膜，炙干） \n炼蜜丸，桐子大。每服三、五十丸，空心温酒下。 \n\\x四味肉苁蓉丸\\x 方在固阵。治小便不禁。 \n\\x黄 丸\\x 治虚风羸瘦，心神虚烦，筋脉拘挛，疼痛少睡。 \n黄 （炙） 人参 熟地黄 白茯苓 薏苡仁 山茱萸（各一两） 枣仁 羌活（去芦） 当归 \n羚羊角屑 枸杞子 桂心（各七钱半） 防风 远志（各半两） \n上为细末，炼蜜和丸，梧子大。每服七、八十丸，温酒下，不拘时。 \n\\x二丹丸\\x 治风邪健忘，和血养神定志，内安心神，外华腠理。 \n丹参 天门冬 熟地黄（各一两半） 麦门冬 白茯苓 甘草（各一两） 人参 丹皮 远志（各半两） \n上为细末，炼蜜和丸，桐子大，以朱砂半两为衣。每服五、七十丸，加至百丸，空心煎 \n愈风汤送下。 \n（《海藏》）\\x益血丹\\x 治大便燥，久虚亡血。 \n当归（酒浸，焙） 熟地黄（等分） \n上为末，炼蜜丸，弹子大。细嚼酒下一丸。 \n（《集要》）\\x四神丸\\x 治禀赋虚弱，小便频数不禁。 \n五味子 菟丝饼（各四两） 熟地黄（六两） 肉苁蓉（一斤，去甲） \n上为末，酒煮山药糊丸，桐子大。每服五十丸，空心盐汤下。 \n（《局方》）\\x虎骨四斤丸\\x \n宣州木瓜（去穣） 天麻（去芦） 肉苁蓉（洗净） 牛膝（焙干，各一斤） 附子（炮去皮脐，二 \n两） 虎骨（酥炙，一两） \n上先将前四味用无灰酒五升浸，春秋五日，夏三日，冬十日，取出焙干，入附子、虎骨 \n，共为末，用前浸药酒打面糊丸，梧子大。每服五十丸，食前盐汤送下。 \n\\x加味四斤丸\\x 治肝肾二经气血不足，足膝酸痛，步履不随，如受风寒湿毒以致香港脚者， \n最宜服之。 \n虎胫骨（一两，酥炙） 乳香（另研） 没药（另研，各五钱） 川乌（炮去皮，一两） 肉苁蓉 牛 \n膝（各一两半） 天麻（一两） 木瓜（一斤，去穣，蒸） \n上各为末，先将木瓜、苁蓉捣膏，加酒糊和杵丸，桐子大。每服七、八十丸，空心温酒 \n或盐汤任下。 \n（《三因》）\\x加味四斤丸\\x 治肾虚肺热，热淫于内，致筋骨痿弱，不能收持。 \n肉苁蓉（酒洗） 牛膝（酒洗） 天麻 木瓜 鹿茸（酥炙） 熟地黄 五味（酒浸） 菟丝子 \n（酒煮，等分） \n上为末，炼蜜丸，桐子大。每服五十丸，食前温酒或米饮送下。刘宗浓曰∶按此方云∶ \n热淫于内，而用温补，何也？然阴血衰弱，血不养筋，筋缓不能自收持。今阳燥热淫于内， \n故用此以养阳滋阴，阴实则水升火降矣。 \n\\x金刚丸\\x 治肾损骨痿不能起床，宜此益精。 \n萆 杜仲（姜汁炒） 肉苁蓉（酒洗） 菟丝子（制） \n上用酒煮猪腰子捣丸，桐子大。每服五、七十丸，空心温酒送下。 \n\\x人参膏\\x \n用人参十两，细切，以活水二十盏浸透，入银石器内，桑柴火缓缓煎取十盏，滤汁，再 \n以水十盏，煎渣取汁五盏，并入前汁，合煎成膏，瓷瓶收贮。随证作汤使调服。丹溪云∶多 \n欲之人肾气衰惫，咳嗽不止，用生姜橘皮煎汤，化膏服之。浦江郑兄，五月患痢，又犯房室 \n，忽发昏运，不知人事，手撒目暗，自汗如雨，喉中痰鸣，声如拽锯，小便遗失，脉大无伦 \n，此阴亏阳绝之证也。予令急煎大料人参膏，仍与灸气海十八壮，右手能动。再二壮，唇口 \n微动。遂与膏服一盏半，夜后服三盏，眼能动。尽三斤，方能言而索粥，尽五斤而痢止，至 \n十斤而全安。若作风治则误矣。一人背疽，服内托十宣药已，多脓出，作呕，发热，六脉沉 \n数有力，此溃疡所忌也。遂用大料人参膏，入竹沥饮之，参尽十六斤，竹伐百余竿而安。后 \n经旬余，值大风拔木，疮复起有脓，中有红线一道，过肩胛抵右肋。予曰∶急作参膏，以芎 \n归橘皮作汤，入竹沥、姜汁饮之，尽三斤而疮溃，调理乃安。若痈疽溃后，气血俱虚，呕逆 \n不食，变证不一者，以参 归术等分，煎膏服之最妙。 \n\n\n\n<目录>卷之五十四书集·古方八阵\n\n<篇名>和阵\n\n属性：（《局方》）\\x二陈汤\\x 治痰饮呕恶，风寒咳嗽，或头眩心悸，或中脘不快，或因生冷，或饮 \n酒过多，脾胃不和等证。 \n陈皮 半夏（制，各三钱） 茯苓（二钱） 炙甘草（一钱） \n水二钟，姜三五片，枣一枚，煎八分，食远服。 \n\\x加减二陈汤\\x 治呕吐吞酸，胃脘痛，呃逆。 \n即前方加丁香九粒，气滞甚者，可加一二钱。 \n（丹溪）\\x加味二陈汤\\x 治食郁瘀滞，胸膈不快。 \n苍术（米泔浸） 白术（炒） 橘红 半夏（泡） 茯苓 川芎 香附（各八分） 枳壳 黄连（ \n姜炒） 甘草（各五分，水盏半，煎八分，食前稍热服。 \n\\x二术二陈汤\\x 治一切呕吐清水如注。 \n苍术（土炒） 白术（炒） 陈皮 半夏（制） 茯苓（各一钱） 炙甘草（五分） \n水一钟半，姜三片，枣一枚，煎八分，稍热服。虚寒者加人参、煨干姜；痰饮，加南星 \n，倍半夏；宿食，加神曲、砂仁。 \n（《宣明》）\\x黄芩二陈汤\\x 治热痰。 \n黄芩 陈皮 半夏 茯苓（等分） 甘草（减半） \n水一钟半，姜三片，煎七分，食远服。 \n（《辨疑》）\\x柴葛二陈汤\\x 治一切疟、暑、湿、劳、食等证。 \n柴胡 干葛 陈皮 半夏 茯苓 甘草 白术 苍术（制） 川芎 黄芩（各等分，若阴疟 \n除此味） \n水二钟，姜三片，煎服。内干葛、川芎、苍术，乃发散之剂，若久疟及发散过者除之。 \n阳分汗多，加人参、黄 ，去干葛；阴分虚者，加酒炒芍药、当归、生地；久疟，微邪潮热 \n，加四君子汤，去祛邪之药；若欲截疟，加常山、槟榔、青皮、贝母各一钱。 \n\\x桂附二陈汤\\x 方在热阵。治寒疟厥冷。 \n（《金匮》）\\x小半夏汤\\x 治呕吐，谷不得下，及心下有饮者。 \n半夏（一升） 生姜（半斤） \n上二味，以水七升，煮取一升半，分温再服。《局方》用半夏五钱，生姜二钱半，水一 \n钟半，煎服。 \n（《金匮》）\\x小半夏加茯苓汤\\x 治卒呕吐，心下痞，膈间有水，眩悸者。 \n即前方加茯苓三两，煎法同。 \n（《金匮》）\\x大半夏汤\\x 治胃反不受食，食入即吐。《外台》云∶治呕而心下痞硬者。 \n半夏（二升，洗完用） 人参（三两） 白蜜（一斤） \n上三味，以水一斗二升，和蜜扬之二百四十遍，煮药取三升半，温服一升，余分再服。 \n（《御药》）\\x大半夏汤\\x 一名橘皮汤。治痰饮及脾胃不和。 \n半夏 陈皮 白茯苓（各二钱） \n水二钟，姜五片，煎八分，温服。 \n\\x茯苓半夏汤\\x 治呕吐哕，心下坚痞，膈间有水，痰眩惊悸，及小儿等病。 \n白茯苓（二两） 半夏（五钱） \n上每服三、五、七钱，姜、水煎服。 \n（《宣明》）\\x橘皮半夏汤\\x 治痰涎壅嗽久不已者，常服润燥解肌热止嗽。 \n陈皮（五钱） 半夏（制，二钱半） \n水一钟半，加生姜三、五片，煎七分，温服。 \n（《灵枢》）\\x秫米半夏汤\\x 久病不寐者神效，世医鲜用之。 \n秫米（一升） 半夏（五合） \n上用千里长流水八升，扬之万遍，取清者五升，煮秫米、半夏，炊以苇薪，令竭至一升 \n半，去渣，饮汁一小杯，日三服。其新病者，覆杯即卧，汗之即已；久病者，三日已也。 \n（东垣）\\x半夏白术天麻汤\\x 治眩晕，及足太阴痰厥头疼。 \n半夏（钱半） 白术 神曲（炒，各一钱） 麦芽 陈皮（各钱半） 人参 黄 茯苓 苍术 天 \n麻泽泻（各五分） 黄柏（二分） 干姜（三分） \n上 咀。每服半两，水二钟，煎八分，食远热服。 \n（《金匮》）\\x黄芩半夏生姜汤\\x 治干呕而利者。 \n黄芩 生姜（各三两） 炙甘草 芍药（各二两） 半夏（半升） 大枣（十二个） \n上六味，以水一斗，煮取三升，去滓，温服一升，日再夜一服。 \n（东垣）\\x平胃散\\x 治脾胃不思饮食，心腹胁肋胀满刺痛，呕哕恶心，吞酸噫气，体重节痛 \n，自利霍乱，噫膈反胃等证。 \n浓朴（姜制炒） 陈皮（去白，各五两） 苍术（去皮，米泔浸炒，八两） 炙甘草（三两） \n本方加人参、茯苓各二两，即名参苓平胃散。 \n上为末。每服二钱，水二钟，姜三片，枣二枚，煎七分，去渣温服。或去姜枣，入盐一 \n小捻，单以沸汤点服亦可。如小便不利，加茯苓、泽泻；如饮食不化，加神曲、麦芽、枳实 \n；如胃中气痛，加木香、枳实或枳壳；如脾胃困倦，加人参、黄 ；如有痰，加半夏；如便 \n硬腹胀，加大黄、芒硝；如脉大内热，加黄连、黄芩。 \n\\x调气平胃散\\x 治胃气不和，胀满腹痛。 \n浓朴（制） 陈皮 木香 乌药 白豆蔻 砂仁 白檀香（各一钱） 甘草（五分） 苍术（钱半） \n藿香（一钱二分） \n水一钟半，生姜三片，煎八分，食远温服。 \n（钱氏）\\x益黄散\\x 治脾土虚寒，寒水反来侮土而呕吐不食，或肚腹作痛，或大便不实，手足逆冷等证。 \n陈皮（一两） 青皮 诃子肉（炮去皮） 炙甘草（各半两） 丁香（二钱） \n上每服四钱，水煎服。 \n\\x藿香正气散\\x 治外感风寒，内停饮食，头疼寒热，或霍乱泄泻，痞满呕逆，及四时不正 \n之气，疟痢伤寒等证。 \n藿香 紫苏 桔梗 白芷 大腹皮（各一钱） 陈皮 半夏 茯苓 甘草 白术 浓朴（各八分） \n水二钟，姜三片，枣一枚，煎八分，热服取汗。 \n\\x不换金正气散\\x 治脾气虚弱，寒邪相搏，痰停胸膈，致发寒热，或作疟疾，或受山岚瘴气等毒。 \n浓朴（姜制） 藿香 半夏 苍术（米泔浸） 陈皮（各一钱） 甘草（炙，五分） \n姜、枣、水煎服。 \n（陈氏）\\x不换金正气散\\x 治感冒风寒，或伤生冷，或瘴疟，或疫疠。 \n苍术（米泔浸炒） 浓朴（姜汁炒，各四两） 橘红（三两） 炙甘草 半夏（制） 藿香（各二两） \n人参 木香（湿纸裹煨） 白茯苓（各一两） \n上每服一两，姜、枣、水煎服。 \n（徐氏）\\x正气散\\x 正胃气，进饮食，退寒疟、食疟、瘴气，脾胃滞者，用之为宜。 \n藿香 草果（各二两） 半夏（制） 陈皮 浓朴 砂仁 炙甘草（各一两） \n上为末。每服三钱，加生姜七片，枣三枚同煎，俟疟未发前，和渣服。 \n（《济生》）\\x大正气散\\x 治脾胃不和，为风寒湿气所伤，心腹胀闷，有妨饮食。 \n白术 陈皮（各二钱） 半夏（制） 藿香叶 浓朴（姜炒） 桂枝 枳壳 槟榔 干姜（炮，各 \n钱） 甘草（炙，五分） \n水一钟半，姜三片，枣一枚，煎七分，不时温服。 \n（东垣）\\x升阳益胃汤\\x 治秋燥令行，湿热少退，脾胃虚弱，怠惰嗜卧，体重节痛，四肢不 \n收，口苦舌干，饮食不消，大便不调，小便频数，兼见肺病，洒淅恶寒，惨惨不乐，面色恶 \n而不和，乃阳气不伸故也，当升阳益胃。《良方》无黄 、甘草、半夏、芍药四味。 \n人参 炙甘草 半夏（脉涩者宜用，各一钱） 黄 （二钱） 白术（三分） 白芍 防风 羌活 \n独活（各五分） 柴胡 茯苓（小便利者勿用） 泽泻（不淋者勿用，各三分） 陈皮（四分） 黄连（二分）。 \n上 咀。每服三钱，渐加至五钱，生姜五片，枣二枚，水三钟，煎一钟，早饭、 \n午饭之间温服。忌语话一二时，及酒湿助火之物。服药后，如小便毕而病反增，是不宜利小 \n便也，当去茯苓、泽泻。若得喜食增食，初一二日间不可太饱，恐药力尚浅，胃气再伤，不 \n得转运也。或用美食以助药力而滋胃气，慎不可淡食以损药力而助邪气之沉降也。亦可小役 \n形体，使胃气升发，切勿大劳，致令复伤，但以胃气安静为尤善。 \n\\x海藏白术汤\\x 治风湿恶寒脉缓。 \n白术 防风 甘草 \n上 咀，加生姜煎服。 \n（《济生》）\\x白术汤\\x 治五脏受湿，咳嗽痰多，气喘身重，脉濡细。 \n白术 橘红 半夏 茯苓（各二钱） 炙甘草（一钱） \n水一钟半，姜五片，煎七分，食远服。 \n（《良方》）\\x三味白术汤\\x 方在妇人。治妊娠内热心痛。 \n（《良方》）\\x四味白术汤\\x 方在妇人。治妊娠胃虚恶阻。 \n\\x白术散\\x 治自汗盗汗极效。 \n白术（半斤） \n上将白术切成小块，用浮麦一升，水一斗，同煮干，如白术尚硬，再加水煎透烂，取起 \n切片，焙干为末，每服二三钱，仍用浮麦煎汤，食远调服。如治小儿，以炒黄 煎汤，量儿 \n大小与服。忌萝卜、辛辣炙爆之物，乳母尤忌。 \n（《宣明》）\\x白术散\\x 方在固阵。治虚风多汗痿弱。 \n（《良方》）\\x白术散\\x 方在妇人。治妊娠伤寒内热等证。 \n\\x调胃白术散\\x 治脾胃不和，腹胀泄泻，身面浮肿。 \n白术 茯苓（各二钱） 陈皮 白芍药（炒） 泽泻 槟榔（各一钱） 木香（五分） \n水二钟，姜三片，煎八分，食远服。如肿不退，倍加白术，并枳实麸炒一钱。 \n\\x白术芍药汤\\x 治脾经受湿水泄，体重微满，困弱无力，不欲饮食，或暴泄无数，水谷不 \n化，宜此和之。 \n白术（炒） 芍药（炒，各一两） 甘草（炒，半两） \n上每用一两，水煎服。 \n（草窗）\\x白术芍药散\\x 治痛泻要方。 \n白术（炒，三两） 芍药（炒，二两） 陈皮（炒，两半） 防风（一两） \n上或煎，或丸，或散，皆可用。久泻者加炒升麻六钱。 \n（《金匮》）\\x苓桂术甘草汤\\x 病痰饮者，当以温药和之。 \n凡心下有痰饮，胸胁支满，目眩，此方主之。 \n茯苓（四两） 桂枝 白术（各三两） 甘草（二两） \n上以水六升，煮取三升，温分三服，小便则利。 \n\\x神术散\\x 治伤寒头痛身热等证。 \n苍术（二钱） 川芎 本 甘草（各一钱） \n水二钟，姜三片，煎一钟，不拘时服。 \n（《局方》）\\x神术散\\x 方在散阵。治四时瘟疫，头疼发热。 \n（海藏）\\x神术汤\\x 治风湿恶寒脉紧。 \n苍术 防风 甘草 \n上 咀。加葱白煎服。治刚 汗者，加羌活，或独活、麻黄。 \n（《约说》）\\x沉香降气散\\x 治阴阳壅滞，气不升降，胸膈痞塞，或留饮吞酸，胁下妨闷。 \n沉香（二钱八分） 砂仁（七钱半） 香附子（去毛，盐水炒，六两二钱五分） 炙甘草（五钱五分） \n上为极细末。每服二钱，入盐少许，沸汤调，不拘时服，或淡姜汤亦可。 \n（《和剂》）\\x苏子降气汤\\x 治心腹胀满，喘促气急，消痰进食。 \n苏子（炒） 半夏曲 前胡 当归 陈皮 浓朴（制，各八分） 桂 甘草（各三分） \n水二钟，姜三片，煎七分，不拘时服。 \n（《医林》）\\x小降气汤\\x 治浊气在上，痰涎壅盛。 \n家紫苏 台乌药 白芍 陈皮（各二钱） 炙甘草（五分） \n水一钟半，生姜三片，枣一枚，煎七分，食远服。 \n（《统旨》）\\x木香顺气散\\x 治气滞腹痛胁痛。 \n木香 香附 槟榔 青皮 陈皮 枳壳 砂仁 浓朴（制） 苍术（各一钱） 炙甘草（五分） \n水二钟，姜三片，煎八分，食远服。 \n（《局方》）\\x木香调气散\\x \n木香 白檀香 白豆蔻 丁香（各二钱） 炙甘草 藿香（各八钱） 砂仁（四钱） \n上为末。每服二钱，入盐少许，沸汤点服。 \n\\x流气饮子\\x 治三焦气壅，五脏不和，胸膈痞满，肩背攻痛，呕吐气喘，痰盛浮肿等证。 \n即外科方脉流气饮。 \n木香（磨汁） 槟榔 青皮 陈皮 枳壳 乌药 大腹皮 枳实 茯苓 紫苏 桔梗 防 \n风黄 当归 川芎 芍药 甘草 半夏（制，各（等分） \n水一钟半，姜三片，枣一枚，煎服。 \n（《和剂》）\\x二十四味流气饮\\x 调营卫，利三焦，行痞滞，消肿胀。 \n紫苏 陈皮 青皮 浓朴（制） 炙甘草 香附（炒，各四两） 木通（二两） 大腹皮 丁香皮 \n槟榔 肉桂 木香 草果 莪术（炮） 藿香（各一两半） 麦冬 人参 白术 赤茯苓 木瓜 \n白芷 半夏 枳壳（炒） 石菖蒲（各一两） \n上每服三钱，姜四片，枣二枚，水煎服。 \n\\x七气汤\\x 治七情之气郁结于中，心腹绞痛不可忍，及不能饮食。 \n半夏（制，五两） 人参 肉桂 甘草（炙，各一两） \n上每服三、五钱，水一钟半，姜三片，煎八分服。 \n（《三因》）\\x七气汤\\x 治如前。按此方即《局方》四七汤也。（在后） \n半夏（五两，制） 茯苓（四两） 浓朴（三两） 紫苏（二两） \n上每服三、五钱，姜七片，枣二枚，水煎服。 \n\\x加味七气汤\\x \n即前七气汤加浓朴、茯苓各等分。 \n（《局方》）\\x七气汤\\x 治七情郁结，脏气互相刑克，阴阳不和，挥霍撩乱，吐泻交作。 \n半夏（制） 浓朴 芍药 茯苓（各二钱） 人参 肉桂 橘红 紫苏（各一钱） \n水二钟，加姜、枣煎服。 \n（《指迷》）\\x七气汤\\x 治七情相干，阴阳不得升降，气道壅滞，攻冲作疼，积聚 瘕胀满等证。 \n半夏 甘草（各七分半） 香附（钱半） 青皮 陈皮 桔梗 官桂 藿香 益智 莪术（煨，各一钱） \n上每服三、五钱，姜三片，枣一枚，水煎服。《统旨》七气汤有三棱、玄胡索、姜黄、 \n草豆蔻，无半夏、桔梗。《济生》大七气汤有三棱，无半夏。 \n\\x四磨饮\\x 治诸逆气。 \n沉香 乌药 枳实 槟榔 \n上四味，用白汤共磨服，或下养正丹尤佳。一方用白酒磨。《济生方》用人参，无枳实 \n。本方加木香，即名五磨饮。 \n《济生》\\x疏凿饮\\x 治水气通身浮肿，喘呼气急，烦渴，大小便不利。 \n泽泻 茯苓皮 木通 商陆 大腹皮 槟榔 羌活（去芦） 秦艽（去芦） 椒目 赤小豆（炒） \n上 咀。每服六、七钱，水一钟半，姜五片，煎服。 \n《良方》\\x浓朴汤\\x 治心腹胀满。此病气壅实者之治法也。 \n浓朴（四、五钱，姜汁炒） \n加生姜五、七片，水煎，温服。或间用沉香降气散。 \n\\x木香宽中散\\x 治七情伤于脾胃，以致胸膈痞满，停痰气逆，或成五膈之病。 \n青皮 陈皮 丁香（各四两） 浓朴（制，一斤） 甘草（炙，五两） 白豆蔻（二两） 香附（炒） 砂 \n仁木香（各三两） \n上为末。每服二钱，姜、盐汤调服。若脾胃虚损之证，不可过服，或与六君子兼用之。 \n（《良方》）\\x木香分气饮\\x 治气滞留注四肢，腹急中满，胸膈胁肋膨胀，虚气上冲，小便臭浊。 \n木香 猪苓 泽泻 赤茯苓 半夏 枳壳 槟榔 灯草 苏子（等分） \n上 咀。每服一两，水一钟半，煎八分，入麝香末少许，食远服。 \n（《良方》）\\x人参木香散\\x 治水气病。 \n人参 木香 茯苓 滑石 琥珀 海金沙 枳壳 槟榔 猪苓 甘草（等分） \n上 咀。每服一两，生姜三片，水一钟半，煎七分，日进三服，不拘时。 \n\\x消导宽中汤\\x 治气滞食滞，水肿胀满。 \n白术（一钱半） 枳实（麸炒） 浓朴（姜制） 陈皮 半夏 茯苓 山楂 神曲（炒） 麦芽（ \n炒） 萝卜子（炒，各一钱） \n水一钟半，姜三片，煎八分，食远服。小便不利，加猪苓、泽泻。 \n\\x化滞调中汤\\x 治食滞胀满。 \n白术（钱半） 人参 白茯苓 陈皮 浓朴（姜汁炒） 山楂 半夏（各一钱） 神曲（炒） 麦芽 \n（炒，各八分） 砂仁（七分） \n水一钟半，姜三片，煎七分，食前服。胀甚者，加萝卜子炒用一钱，面食伤者尤宜用。 \n（索矩）\\x三和汤\\x 治脾湿肿满。 \n陈皮 浓朴（姜炒） 白术 槟榔（各一钱） 紫苏（七分） 海金沙 木通（各五分） \n水一钟半，姜三片，枣一枚，煎七分，食远服。 \n（《宝鉴》）\\x导滞通经汤\\x 治脾湿气不宣通，面目手足浮肿。 \n木香 白术 桑白皮 陈皮（各五钱） 茯苓（一两） \n上 咀。每服七八钱，水一钟半，煎八分，食前温服。 \n（《良方》）\\x导水茯苓汤\\x 治水肿，头面手足遍身肿如烂瓜之状，按而塌陷，胸腹喘满，不 \n能转侧安睡，饮食不下，小便秘涩，溺出如割，或如黑豆汁而绝少，服喘嗽气逆诸药不效者 \n，用此即渐利而愈。 \n赤茯苓 麦门冬（去心） 泽泻 白术（各三两） 桑白皮 紫苏 槟榔 木瓜（各一两） 大腹 \n皮陈皮 砂仁 木香（各七钱半） \n上 咀。每服一、二两，水二钟，灯草一、二十根，煎八分，食煎服。如病重者 \n可用药五两，再倍加麦冬及灯草半两，以水一斗，于砂锅内熬至一大碗，再下小铫内煎至一 \n钟，五更空心服， 再煎。连进此三服，自然小水通利，一日添如一日。 \n\\x健脾散\\x 和中健胃，消食快气。 \n人参 白术（炒） 丁香 藿香 砂仁（炒） 肉果（煨） 神曲（炒） 炙甘草（等分） \n上为细末。每服二钱，不拘时，橘皮汤下。 \n\\x参术健脾汤\\x 治脾虚兼滞胀满。 \n人参 白茯苓 陈皮 半夏 砂仁 浓朴（姜制，各一钱） 白术（二钱） 甘草（三分） \n水一钟半，姜三片，煎七分，食远服。加神曲、麦芽、山楂，消胀尤佳。 \n（《三因》）\\x当归散\\x 水肿之疾，多由火不养土，土不制水，故水气盈溢，脉道闭塞，渗透 \n经络，发为浮肿、心腹胀满之证。 \n当归 桂心 木香 赤茯苓 木通 槟榔 赤芍药 牡丹皮 陈皮 白术（各一钱半） 木瓜（一片） \n水二钟，加紫苏五叶，煎八分，不拘时服。 \n\\x当归活血散\\x 治瘀血胀满。 \n赤芍药 归尾（酒洗） 生地黄（各钱半） 桃仁（去皮尖，炒） 红花（酒洗） 香附（童便浸， \n各一钱） 川芎 牡丹皮 玄胡索 蓬术（炮，各八分） 三棱（炮） 青皮（各七分） \n水一钟半，煎七分，食前服。 \n（《局方》）\\x五皮散\\x 治风湿客于脾经，以致面目虚浮，四肢肿满，心腹膨胀，上气急促， \n兼治皮水、胎水。 \n五加皮 地骨皮 大腹皮 茯苓皮 生姜皮（等分） \n上咀。每服三钱，水一大钟，煎七分，热服无时。 \n（《澹寮》）\\x五皮散\\x 治病后身面四肢浮肿，小便不利，脉虚而大。此由诸气不能营运，散 \n漫于皮肤肌腠之间，故令肿满，此药最宜。 \n大腹皮 陈皮 生姜皮 桑白皮（炒） 赤茯苓皮（各等分） \n上 咀。每服五、六钱，水一大钟，煎八分，不拘时温服，日三次。忌生冷、油 \n腻、坚硬之物。 \n\\x沉香琥珀丸\\x 治水肿一切小便不通难治之证。 \n沉香 郁李仁（去皮） 葶苈（炒，各两半） 琥珀 杏仁（去皮尖） 紫苏 赤茯苓 泽泻（各 \n半两） 橘红 防己（各七钱半） \n上为细末，炼蜜丸，梧子大，以麝香为衣。每服二十五丸，渐加至五、七十丸，空心人 \n参汤送下，量虚实增减。 \n\\x法制陈皮\\x 消食化气，宽利胸膈，美进饮食。 \n茴香（炒） 甘草（炙，各二两） 青盐（炒，一两） 干姜 乌梅肉（各半两） 白檀香（二钱半） \n上六味，共为末，外以广陈皮半斤，汤浸去白，净取四两，切作细条子。用水一大碗， \n煎药末三两，同陈皮条子一处慢火煮，候陈皮极软，控干，少时用余剩干药末拌匀，焙干。 \n每服不拘多少，细嚼温姜汤下，无时。 \n（《家秘》）\\x祛痛散\\x 治诸般心气痛，或气滞不行，攻刺心腹，痛连胸胁，小肠吊疝，及妇 \n人血气刺痛。此方屡用，无不神效。 \n青皮 五灵脂（去石） 川楝子 穿山甲 大茴香（各二钱） 良姜（香油炒） 玄胡索 没药 \n槟榔（各钱半） 沉香（一钱） 木香（钱二分） 砂仁（少许） \n上咀，用木鳖子仁一钱二分，同前药炒令焦燥，去木鳖不用，共为细末。每服一钱，加 \n盐一星，用酒或滚水送下。 \n\\x调痛散\\x 治脾痛气膈。 \n木香 丁香 檀香 大香附 台乌药 莪术 肉桂 片姜黄 白生姜 白豆蔻 砂仁 \n炙甘草（等分） \n上咀。每服二钱半，加紫苏四叶，煎汤服。 \n\\x丁香止痛散\\x 方在热阵。治心痛。 \n（《良方》）\\x乌药散\\x 治血气壅滞，心腹作痛。 \n乌药 莪术（醋浸炒） 桂心 桃仁 当归 青皮 木香（等分） \n上为末。每服二钱，热酒调下。 \n（《奇效》）\\x手拈散\\x 治心脾气痛。 \n延胡索 五灵脂 草果 没药（等分） \n上为细末。每服二三钱，不拘时，热酒调下。 \n（《良方》）\\x游山散\\x 治心脾痛。此药极奇，叶石林游山，见一小寺颇整洁，问僧所以仰给 \n者，则曰∶素无田产，亦不苦求，只货数药以赡，其脾疼药最为流布。有诗云∶ \n草果玄胡索，灵脂并没药。 \n酒调一、二钱，一似手拈却。 \n上等分为末。每服三钱，不拘时温酒调下。 \n\\x舒筋汤\\x 一名如神汤。治闪肭血滞，腰腹 痛，及产后血滞作痛者更妙。 \n当归 玄胡索 桂心（等分） \n上为细末。每服二钱，不拘时温酒调服。一方加杜仲、牛膝、桃仁、续断亦可。 \n（丹溪）\\x玄桂丸\\x 治死血留胃脘，当心作痛。 \n玄胡索（一两半） 官桂 红花 红曲 滑石（各五钱） 桃仁（三十粒） \n上为细末，汤浸蒸饼为丸，绿豆大。每服四十丸，姜汤下。 \n（洁古）\\x枳术丸\\x 治痞积，消食强胃。 \n枳实（去瓤，麸炒，一两） 白术（麸炒，二两） \n上为末，荷叶裹烧饭为丸，桐子大。每服五十丸，白术汤下。但久服之，令人胃气强实 \n，不复伤也。东垣橘皮枳术丸，即前方加陈皮一两，半夏二两，即名橘半枳术丸。 \n\\x香砂枳术丸\\x 破滞气，消宿食，开胃进食。 \n木香 砂仁（各五钱） 枳实（麸炒，一两） 白术（米泔浸炒，二两） \n上制，服如枳术丸法。 \n\\x曲 枳术丸\\x 治强食多食，心胸满闷不快。 \n神曲（炒） 麦 （炒） 枳实（麸炒，各一两） 白术（二两） \n上制，服如枳术丸法。 \n（东垣）\\x木香人参生姜枳术丸\\x 开胃，进饮食。 \n木香（三钱） 人参（五钱） 干生姜（二钱半） 陈皮（四钱） 枳实（一两，炒） 白术（一两半） \n上为细末，荷叶烧饭为丸，桐子大。每服三、五十丸，食前温水下。 \n（《直指》）\\x加味枳术丸\\x 治脾胃虚弱，食积气滞，胸腹胀满。常服进食宽中，和畅脾胃。 \n白术（泔浸土炒，二两） 枳实（麸炒，一两） 神曲（炒） 麦芽（炒） 陈皮 山楂 香附（炒， \n（各一两） 砂仁（炒，半两） \n如前法丸服。 \n（丹溪）\\x枳实丸\\x 专治食积癖块。 \n枳实 白术 山楂 麦芽 神曲 半夏（各一两） 苍术 陈皮（各五钱） 木香（钱半） 姜黄（三钱） \n荷叶蒸饭为丸，桐子大。每服百丸，食后姜汤下。 \n（《医统》）\\x大健脾丸\\x 又名百谷丸。徐东皋曰∶此方健脾养胃，滋谷气，除湿热，宽胸膈 \n，去痞满。久服强中益气，百病不生。 \n人参 白茯苓（饭上蒸） 广陈皮（各二两） 枳实（饭上蒸） 青皮（米醋洗） 半夏曲（炒） \n山楂肉（饭上蒸，各一两） 白术（土炒，三两） 谷芽（炒，一两六钱） 白豆蔻（炒） 广木香（各五钱） \n川黄连（一两六钱，同吴茱萸五钱浸炒赤色，去茱萸） \n上为末，用长流水煮荷叶老米粥捣丸，绿豆大。每服百丸，食前白汤下。愚按∶此方虽 \n佳，但脾多畏寒，若非有火，当去黄连，或仍加炮姜一、二两为妙。 \n（杨氏）\\x启脾丸\\x 治脾胃不和，气不升降，中满痞塞，心腹膨胀，肠鸣泄泻，不思饮食。 \n人参 白术 陈皮 青皮（去瓤） 神曲（炒） 麦芽（炒） 砂仁 浓朴 干姜（各一两） 甘 \n草（两半，炙） \n炼蜜为丸，弹子大。每服一丸，食前细嚼，米饮下。 \n\\x和中丸\\x 治久病厌厌不能食，而脏腑或秘或溏，此皆胃虚所致。常服之，和中理气，消 \n痰积，去湿滞，浓肠胃，进饮食。 \n白术（麸炒，二两四钱） 浓朴（姜制，二两） 陈皮（一两六钱） 半夏（汤泡，一两） 槟榔（五钱） \n枳实（五钱） 炙甘草（四钱） 木香（二钱） \n上用生姜自然汁浸蒸饼为丸，桐子大。每服三、四十丸，食远温水送下。 \n（东垣）\\x和中丸\\x 开胃进食。 \n人参 白术（各三钱） 干姜（炮） 甘草（炙） 陈皮（各一钱） 木瓜（一枚） \n上为末，蒸饼为丸，桐子大。食前白汤下三、五十丸。"}, {"n": 33, "text": "卷三十三\n\n\\x养胃进食丸\\x 治脾胃虚弱，心腹胀满，面色痿黄，肌肉消瘦，怠惰嗜卧，或不思食。常 \n服滋养脾胃，进饮食，消痰涎，辟风寒湿冷邪气。 \n人参 白茯苓 白术（泔浸，炒） 浓朴（姜炒，各二两） 神曲（二两半炒） 大麦 （ \n炒） 橘红（各一两半） 甘草（炙，一两） 苍术（坚小而甘者，米泔浸去皮，五两，炒） \n上九味，为末，水面糊丸，桐子大。每服三、五十丸，食前米汤或姜汤送下。 \n\\x消食丸\\x 治一切食积停滞。 \n山楂 神曲（炒） 麦芽（炒） 萝卜子 青皮 陈皮 香附（各二两） 阿魏（一两，醋浸另研） \n汤泡蒸饼为丸，桐子大。每服五十丸，食远姜汤下。 \n（《济生》）\\x导痰汤\\x 治一切痰涎壅盛，或胸膈留饮，痞塞不通。 \n陈皮 半夏 茯苓 甘草 南星 枳壳（炒） \n上等分，每服六钱，水二钟，姜五片，或十片，煎七分，食后服。 \n（海藏）\\x五饮汤\\x 一留饮，在心下。二 饮，在胁下。三痰饮，在胃中。四溢饮，在 \n膈上。五流饮，在肠间。凡此五饮，以酒后饮冷过多所致。 \n旋复花 人参 橘红（炒） 枳实 浓朴（姜汁炒） 半夏 茯苓 泽泻 白术 猪苓（各八 \n分） 前胡 桂心 芍药 炙甘草（各五分） \n水二钟，姜十片，煎八分，不拘时服。饮酒伤者，加葛根、砂仁。 \n《外台》\\x茯苓饮\\x 治胸有停痰宿水，自吐出水后，心胸间虚，气满不能食。消痰气，令能食。 \n茯苓 人参 白术（各三两） 枳实（二两） 陈皮（二两半） 生姜（四两） \n上六味，水六升，煮取一升八合，分温三服，如人行八、九里进之。 \n\\x茯苓饮子\\x 治痰迷心窍，怔忡不止。 \n陈皮 半夏 茯苓 茯神 麦冬（各钱半） 沉香 甘草（各五分） \n上水一钟半，姜五片，煎七分服。 \n\\x千缗汤\\x 治痰喘不得卧，人扶而坐，一服即安。 \n半夏（泡，七个） 炙甘草 皂角（炙，各一寸） 生姜（一指大） \n水一钟半，煎七分，不拘时服。 \n\\x玉液汤\\x 治七情所伤，气郁生涎，随气上逆，头目眩晕，心 忪悸，眉棱骨痛。 \n半夏（大者六钱，汤泡七次，切片） \n上作一服，水钟半，姜十片，煎七分，入沉香末少许，不拘时温服。 \n（《局方》）\\x四七汤\\x 治七情之气结成痰涎，状如破絮，或如梅核，在咽喉之间，咯不出， \n咽不下，此七情所为也。或中脘痞满，气不舒快，痰饮呕恶，皆治之。 \n半夏（汤泡，钱半） 茯苓（一钱二分） 苏叶（六分） 浓朴（姜制，九分） \n水一钟半，生姜七片，红枣二枚，煎八分，不时服。 \n（《得效》）\\x加味四七汤\\x 治心气郁滞，豁痰散惊。 \n半夏（制，二钱半） 浓朴（制） 茯苓（各一钱半） 苏叶 茯神（各一钱） 远志 石菖蒲 甘草 \n（各五分） \n水二钟，加姜、枣煎服。 \n（《玉机》）\\x泽泻汤\\x 治心下有支饮，苦眩冒。 \n泽泻（五钱） 白术（二钱） \n水二钟，煎七分，食远温服。 \n\\x朱砂消痰饮\\x 治痰迷心窍，惊悸怔忡。 \n胆星（五钱） 朱砂（二钱半，另研） 麝香（二分，另研） \n上为末，临卧姜汤调下一钱。 \n（《深师》）\\x消饮丸\\x 治停饮胸满呕逆，腹中水声，不思饮食。 \n白术（二两，炒） 茯苓（五钱） 枳实（炒） 干姜（炮，各七钱） 上为细末，蜜丸，桐子大。 \n温水下三十丸。 \n（《秘方》）\\x星香丸\\x 治诸般气嗽生痰。 \n南星（矾水泡一宿） 半夏（制同上，共泡之） 香附（皂角水浸一周时，各二两） 陈皮（去 \n白，四两） \n上不见火为末，姜汁糊丸。每服五十丸，临卧姜汤送下。 \n\\x祛痰丸\\x 治风痰头旋恶逆，胸膈不利。 \n南星（生） 半夏（生） 赤茯苓 橘红 干姜（炮，等分） \n上为细末，面糊丸，梧子大。每服五、七十丸，不拘时，米饮送下。 \n\\x天花丸\\x 亦名玉壶丸。治消渴引饮无度。 \n人参 天花粉（各等分） \n上为细末，炼蜜丸，桐子大。每服三、五十丸，麦门冬汤下。 \n（《局方》）\\x玉壶丸\\x 治风痰头痛，亦治诸痰。 \n南星（生） 半夏（生，各一两） 天麻（五钱） 白面（三两）上为末，水和为丸，桐子大。每服 \n三、五十丸，用水一大盏，煎沸入药，煮令药浮即熟，漉出放温，别用生姜汤下。 \n一方∶用南星、半夏各二两俱制，天麻、白矾各五钱，共为末，以姜汁糊丸，如胡椒大 \n。每服三十丸，白汤下。 \n\\x玉液丸\\x 治风热痰涎壅盛，利咽膈，清头目，止咳嗽，除烦热。 \n半夏（汤泡，焙为细末） 枯矾（研细，各十两） 寒水石（ 赤为末，水飞，三十两） \n上研匀，面糊丸，桐子大。每服三十丸，食后淡姜汤下。 \n（洁古）\\x玉粉丸\\x 治气痰咳嗽。 \n南星 半夏（各一两，俱汤浸） 橘红（二两） \n上为末，汤浸蒸饼为丸，桐子大。每服五、七十丸，人参、生姜汤任下，食后。 \n（《瑞竹》）\\x杏仁丸\\x 治久嗽，及老人咳嗽，喘急不已，睡卧不得，服此立效。 \n杏仁（去皮尖，炒） 胡桃肉（去皮） \n上等分，研为膏，加炼蜜丸，如弹子大。每服一丸，食后细嚼，姜汤下。 \n\\x许学士神术丸\\x 治痰饮。此足阳明、太阳治湿发散之剂也。 \n茅山苍术（一斤，米泔浸一宿，去皮切片，焙干为末） 生油麻（五钱，水二盏研细取浆） 大 \n枣（十五个，煮取肉，研，旋入麻浆拌和药） \n上三味，和丸，桐子大，日干。每服五、七十丸，空心温酒下。 \n（《三因》）\\x曲术丸\\x 治中脘宿食留饮，酸蜇心痛，嘈杂，口吐清水。 \n神曲（炒，三两） 陈皮（一两） 苍术（米泔浸三宿，切炒，一两半） \n上为末，生姜汁别煮神曲糊为丸。姜汤送下。 \n（《百一》）\\x三仙丸\\x 治一切湿痰痰饮，胸膈烦满，痰涎不利，头目不清。 \n南星 半夏 香附（各等分） \n上南星、半夏以滚汤泡过为末，用生姜自然汁和，不可太软，用楮叶或荷叶包住，外以 \n蒲包再包， 之令发黄色，晒干收用。须五六月内造如 之法。每制丸药，用 \n药二两，香附一两，同为细末，面糊为丸，绿豆大。每服四、五十粒，食后姜汤下。 \n\\x青州白丸子\\x 治男妇风痰壅盛，手足瘫痪，呕吐涎沫，牙关紧急，痰喘麻木，及小儿惊风呕吐。 \n半夏（七两） 南星（三两） 白附子（二两） 川乌（半两，俱生用） \n上俱研，罗为细末，用生绢袋盛，以瓷盆盛井花水摆洗粉出，未出者，以手揉摆，再擂 \n再摆，以尽为度。然后日晒夜露，每日一换新水，搅而复澄，春五，夏三，秋七，冬十日， \n去水晒干，白如玉片。以糯米粉作稀糊丸，如绿豆大。每服二十丸，生姜汤下，无时。如瘫 \n痪，用酒下；小儿惊风，薄荷汤下五、七丸。 \n（《局方》）\\x琥珀寿星丸\\x \n天南星（一斤） 朱砂（二两，研） 琥珀（一两，研） \n上先掘地坑，深二尺，用炭火五斤，于坑内烧热红，取出炭扫净，以好酒一升浇之。将 \n南星乘热下坑内，用盆急盖，以泥壅护，经一宿取出，焙干为末，同二味和匀，用生姜汁打 \n面糊丸，如桐子大。每服五十丸，煎人参汤空心送下，日三服。 \n一方用琥珀四两，朱砂一两，仍用猪心血三个，和药末内加糊为丸，如前服。 \n（《指迷》）\\x茯苓丸\\x 治人有臂痛，手足不能举，或时左右转移。此伏痰在内，中脘停滞， \n脾气不能流行，上与气搏，脾属四肢而气不下，故上行攻臂，其脉沉细者是也。但治其痰， \n则臂痛自止。及妇人产后发喘，四肢浮肿者，用此则愈。此治痰第一方也。 \n半夏（制，二两） 茯苓（一两） 枳壳（炒，半两） 风化硝（一钱半） \n上为末，姜汁煮糊丸，桐子大。每服三、五十丸，姜汤下。累有人为痰所苦，夜间两臂 \n常觉抽掣，两手战掉，至于茶钟亦不能举，随服随效。 \n又简易方∶治痰饮流注疼痛。止用大半夏二两，风化硝一两，为末，以姜汁煮糊丸，桐 \n子大。姜汤下十五丸。痰在上，临卧服；在下，食前服。 \n（丹溪）\\x白螺丸\\x 治痰饮积胃脘痛。 \n白螺蛳壳（墙上年久者，烧） 滑石（炒） 苍术 山栀 香附 南星（各一两） 枳壳 青皮 \n木香 半夏 砂仁（各五钱） \n上为末，生姜汁浸蒸饼为丸，绿豆大。每服三、四十丸，姜汤下。春，加川芎；夏，加 \n黄连；冬，加吴茱萸，各五钱。 \n（丹溪）\\x润下丸\\x 降热痰甚妙。 \n半夏（二两，根据橘红制） 南星（根据橘红制） 炙甘草 黄芩 黄连（各一两） 橘红（半斤，以水 \n化盐五钱拌匀，煮干，焙） \n上为末，蒸饼丸，绿豆大。每服五、七十丸，白汤下。 \n（《集成》）\\x润下丸\\x 治胸膈停痰，降痰甚妙。 \n橘红（一斤，盐五钱，同水浸煮干） 甘草（炙，一两） \n上为末，汤浸蒸饼丸，绿豆大。每服五十丸，白汤下。 \n（《丹溪》）\\x黄栝蒌丸\\x 治食积作痰，壅滞喘急。 \n栝蒌仁 半夏 山楂 神曲（炒，等分） \n上为末，栝蒌汁丸。姜汤下五十丸。 \n（《丹溪》）\\x杏仁萝卜子丸\\x 治气壅痰盛咳嗽。 \n杏仁 萝卜子（炒，各一两） \n上为末，粥糊丸，桐子大。每服五十丸，白汤下。 \n（《金匮》）\\x陈皮汤\\x 治呕吐呃逆。 \n陈皮（四两） 生姜（半斤） \n水七升，煮取三升，温服一升，下咽即愈。 \n（《本事》）\\x竹茹汤\\x 治胃热呕吐。 \n半夏（姜汁制） 干葛（各三钱） 甘草（二钱） \n上为末。每服二钱，水一钟，姜三片，竹茹一弹许，枣一枚，同煎七分，去 温服。 \n\\x橘皮竹茹汤\\x 治吐利后，胃虚膈热，呃逆者。 \n人参 竹茹 橘红（各二钱） 甘草（炙，一钱） \n水一钟半，生姜五片，枣一枚，煎八分温服。 \n\\x二汁饮\\x 治反胃。 \n甘蔗汁（二分） 姜汁（二分） \n二味和匀，每温服一碗，日三服则吐止。 \n（东垣）\\x葛花解酲汤\\x 治饮酒太过，痰逆呕吐，心神烦乱，胸膈痞塞，手足颤摇，饮食减 \n少，小便不利。 \n人参 白术 茯苓 砂仁 白豆蔻 葛花（各一钱） 青皮 陈皮 猪苓 泽泻（各七分） 神 \n曲木香（各五分） \n水二钟，生姜五片，煎七分，食远稍热服。取微汗，酒病去矣。或为末，姜醋汤调服二、三钱亦可。 \n《金匮》\\x猪苓散\\x 治呕吐，病在膈上，思水者。 \n猪苓 茯苓 白术（等分） \n上三味，杵为散。饮服方寸匕，日三服。 \n《大全》\\x人参散\\x 治脾胃虚寒，霍乱吐泻，心烦腹痛，饮食不入。 \n人参 当归 浓朴 橘红（各二钱） 干姜（炮） 炙甘草（各五分） \n加枣一枚，水煎服。 \n《澹寮》\\x六和汤\\x 治夏秋暑湿伤脾，或饮冷乘风，多食瓜果，以致客寒犯胃，食留不化 \n，遂成痞膈霍乱呕吐，及广南夏月瘴疾寒热等证。 \n半夏 人参 炙甘草 砂仁 杏仁（各一钱） 赤茯苓 扁豆（炒） 藿香 木瓜（各二钱） \n上 咀。每服五钱，水二钟，生姜三片，枣一枚，煎，温服。 \n一方有白术、香薷、浓朴各一钱，名六和半夏汤。 \n《良方》\\x丁香散\\x 治藿乱呕吐不止。 \n丁香（五分） 藿香 枇杷叶（拭去毛，各二钱） \n上 咀。水一钟半，姜一片，煎六分，热服。 \n《局方》\\x丁香半夏丸\\x 治胃寒呕吐吞酸。 \n丁香（一两） 红豆（炒） 半夏（制） 白术（炒，各二两） 陈皮（三两） \n上为末，姜汁打糊丸，胡椒大。每服二、三十丸，姜汤下。 \n《局方》\\x半夏丁香丸\\x 治脾胃宿冷，胸膈停痰，呕吐恶心，吞酸噫腐，心腹痞满，不思饮食。 \n肉豆蔻 丁香 木香 藿香 人参 陈皮（去白，各二钱） 半夏（制，三两） \n上为细末，姜汁煮糊丸，桐子大。每服三十丸，姜汤下。 \n《和剂》\\x大七香丸\\x 治脾胃虚冷，心膈噎塞，渐成隔气，及脾泄泻痢，反胃呕吐。 \n香附（二两） 麦芽（炒，一两） 砂仁 藿香 官桂 甘草 陈皮（各二两半） 丁香（三两半） 甘 \n松乌药（各六钱半） \n上为末，蜜丸，弹子大。每服一丸，嚼啐，盐酒、盐汤任下。忌生冷、肥腻。 \n《良方》\\x许仁则半夏丸\\x 治胃冷呕逆不食。 \n半夏（洗去滑，一斤） 小麦面（一斤） \n上水和丸，弹子大，水煮熟。初服四、五丸，二服加至十四、五丸，旋煮间服之。 \n（万氏）\\x定喘汤\\x 治诸喘久不愈。按此方必风痰在肺者乃可用，他则忌之。 \n白果（三七枚，去壳切碎，炒） 款冬花 桑白皮（蜜炒） 麻黄 制半夏（各三钱） 苏子（二钱） \n黄芩（微炒） 杏仁（各钱半） 甘草（一钱） \n水三钟，煎二钟，作二次服。不拘时，徐徐饮。 \n歌曰∶诸病原来有药方，惟愁 喘最难当。麻黄桑杏寻苏子，白果冬花用更良， \n甘草黄芩同半夏，水煎百沸不须姜。病患遇此仙丹药，服后方知定喘汤。 \n《局方》\\x人参定喘汤\\x 治肺气上喘，喉中有声，坐卧不安，胸膈紧痛，及治肺感寒邪，咳嗽声重。 \n人参 麻黄 阿胶 半夏曲 五味子 粟壳 甘草（各八分） 桑白皮（钱半） \n水二钟，姜三片，煎八分，食后服。 \n《良方》\\x百合汤\\x 治肺气壅滞，咳嗽喘闷，多渴，腰膝浮肿，小便淋沥。 \n百合 赤茯苓 陈皮 桑白皮 紫苏 大腹皮 枳壳 马兜铃 人参 猪苓 炙甘草 麦冬（各一钱） \n上分二服。每服水一钟半，姜一片，枣一枚，煎七分，不拘时温服。 \n《局方》\\x五虎汤\\x 治风寒所感，热痰喘急。 \n麻黄（七分） 细茶（八分） 杏仁（去皮尖，一钱） 石膏（一钱半） 甘草（四分） \n水一钟半，姜三片，枣一枚，煎服。 \n《三因》\\x神秘汤\\x 治上气喘急不得卧。 \n人参（一钱） 陈皮 桔梗 紫苏（各钱半） 五味子（十五粒） \n水一钟半，煎七分，食远温服。 \n《直指》\\x神秘汤\\x 治水气作喘。 \n人参 陈皮 桔梗 紫苏 半夏 桑白皮 槟榔（各一钱） 炙甘草（五分） 五味子（十五粒） \n水二钟，姜三片，煎八分，食远温服。 \n\\x萝卜子汤\\x 治积年上气喘促，唾脓血不止，而气实者宜之。 \n萝卜子（一合，研碎） \n水煎，食后服，其效如神。 \n《三因》\\x葶苈大枣泻肺汤\\x 治上气喘急，身与面目俱浮，鼻塞声重，不闻香臭，胸膈胀满，将成肺痈。 \n甜葶苈（炒，研细，三钱） 大枣（十枚，去核） \n水二钟，先煎大枣至一钟，去枣入葶苈，煎至八分，食后服，须先服小青龙汤二服方用此。 \n\\x苏子煎\\x 治上气咳嗽。 \n苏子 杏仁 生姜汁 生地黄汁 白蜜（各一斤） \n上将苏子捣烂，以二汁和之，绢绞取汁，又捣又和，如此六、七次则味尽，乃去 \n，以蜜和之，置铜器中，于汤上煎之如饴。每服二匙，日三次，夜一、二次，病愈即止。 \n《医林》\\x杏仁煎\\x 治喘嗽。 \n杏仁（去皮尖，炒） 胡桃肉（去皮） \n上等分，研膏，炼蜜丸，弹子大。每服一丸，临卧细嚼，姜汤送下。一方以胡桃肉三枚 \n，姜三片，临卧嚼服，饮汤三、四口，再嚼再饮就卧，止嗽无痰。 \n《良方》\\x杏仁膏\\x 治咳嗽喘急，喉中枯燥如物塞，兼唾血不止。 \n杏仁（二两，去皮尖，炒研如膏） 真酥（三两） 阿胶（二两，研炒为末） 生姜汁（一合） 白蜜（五 \n合） 苏子（二两，微炒研膏） \n上和匀，银锅内慢火熬成膏。每服一匙，不拘时，米饮调下。 \n《良方》\\x前胡散\\x 治心胸烦热不利，咳嗽涕唾稠粘。 \n前胡 桑白皮 麦门冬 贝母（各钱半） 甘草（炙，五分） 杏仁（去皮尖，一钱） \n水一钟半，姜三片，煎七分，温服。 \n《济生》\\x百花膏\\x 治咳嗽不已，或痰中有血。 \n百合（蒸，焙干） 款冬花（等分） \n上为细末，炼蜜丸，龙眼大。临卧细嚼一丸，姜汤下。 \n《本事》\\x枳壳散\\x 治心下痞闷作痛，嗳气如败卵。 \n枳壳 白术（各五钱） 香附（一两） 槟榔（二钱） \n上为细末。每服二钱，米饮调下，日二、三服，不拘时。 \n\\x保和汤\\x 治中染瘴气，发热呕吐，腹满不食。 \n浓朴（姜制） 半夏（制） 大腹皮（黑豆水洗） 橘红（各八分） 柴胡 枳壳 甘草（各五分） \n生姜（三钱，煨） \n水煎温服。 \n\\x十味保和汤\\x 治胃虚气滞作嗳。 \n人参 白术 茯苓 半夏（制） 陈皮（各一钱） 藿香 香附 砂仁（各六分） 炙甘草 木香（各三钱） \n水一钟半，姜三片，枣二枚，煎七分，食前温服。 \n（丹溪）\\x六郁汤\\x 能解诸郁。 \n香附（二钱） 橘红 苍术 抚芎 半夏（炮，各一钱） 赤茯苓 栀子（炒，各七分） 炙甘草 \n砂仁（各五分） \n水一钟，姜三片，煎八分，温服。气郁，加乌药、木香、槟榔、紫苏、干姜，倍砂仁、 \n香附；湿郁，加白术；热郁，加黄芩，倍栀子；痰郁，加南星、枳壳、小皂荚；血郁，加桃 \n仁红花、丹皮；食郁，加山楂、神曲、麦芽。 \n《局方》\\x三和散\\x 治七情气结，脾胃不和，心腹痞满，大便秘涩。 \n羌活 苏叶 木瓜 大腹皮 沉香（各一钱） 木香 槟榔 陈皮 白术 川芎 炙甘草（各七分半） \n上咀，分二服，每服水一钟，煎六分，不拘时服。 \n（丹溪）\\x生韭饮\\x 治食郁久则胃脘有瘀血作痛，大能开提气血。 \n生韭（捣取自然汁一盏，加温酒一、二杯同服） \n上先以桃仁连皮细嚼数十枚，后以韭汁送下。 \n《三因》\\x温胆汤\\x 治气郁生涎，梦寐不宁，怔忡惊悸，心虚胆怯，变生诸证。 \n半夏（汤泡） 枳实 竹茹（各一两） 陈皮（一两五钱） 茯苓（七钱） 炙甘草（四钱） \n每服四、五钱，生姜七片，枣一枚，水一钟半，煎七分，食远温服。一方有远志一两。 \n\\x十味温胆汤\\x 治证同前，兼治四肢浮肿，饮食无味，心虚烦闷，坐卧不安，梦遗精滑等证。 \n半夏（汤泡） 枳实（麸炒） 陈皮（各二钱） 白茯苓（钱半） 人参 熟地 枣仁（炒） 远志（ \n制） 五味（各一钱） 炙甘草（五分） \n水二钟，生姜五片，枣一枚，煎八分，不拘时服。 \n\\x越鞠丸\\x 治六郁胸膈痞满，或吞酸呕吐，饮食不和，疮疥等证。 \n香附 山楂 神曲（炒） 麦芽（炒） 抚芎 苍术 栀子（炒，各等分） \n上为末，水调神曲糊丸，桐子大。每服五、七十丸，滚汤下。丹溪越鞠丸，无山楂、麦芽。 \n\\x流气丸\\x 治五积六聚， 瘕痞块，留饮之疾。是皆郁气客于肠胃之间，皮肤之下， \n久而停留，变而为痞。此药能通滞气，和阴阳，消旧饮，虽年高气弱，亦可缓缓服之。 \n木香 小茴香 橘红 菖蒲 青皮 广术（炮） 槟榔 萝卜子 神曲（炒） 麦芽（炒） \n枳壳（麸炒） 补骨脂（炒） 砂仁 荜澄茄（各一两） \n上为末，面糊丸，桐子大。每服五十丸，细嚼白豆蔻仁一枚，食后白汤送下。 \n（严氏）\\x五膈散\\x 治五膈五噎。 \n人参 白术 甘草 白豆蔻 半夏 桔梗 干姜 荜澄茄 木香 杵头糠 沉香（各三分） \n枇杷叶（五片，炙，去毛） \n水二钟，姜七片，煎七分，温服。 \n《局方》\\x五膈宽中散\\x 治七情四气伤于脾胃，以致阴阳不和，遂成膈噎，一切气逆并治。 \n青皮 陈皮（各五钱） 香附（童便浸炒） 浓朴（姜汁炒） 甘草（各六钱） 白豆蔻 砂仁 丁 \n香木香（各一钱） \n上为细末。每服二钱，姜盐汤点服。 \n《选要》\\x十膈散\\x 治十般膈气。风、冷、气、热、痰、食、水、忧、思、喜。 \n人参 白术 茯苓 炙甘草 陈皮 枳壳（麸炒） 神曲（炒） 麦芽 干姜（炮） 官桂 \n诃子（煨） 三棱（炮） 莪术（炮，各一两） 浓朴（姜炒） 槟榔 木香（磨，各半两） \n上为细末。每服二钱，入盐少许，白汤调服。如脾胃不和，腹满胀闷，用水一钟，姜五 \n片，枣一枚，盐少许，煎七分服。 \n《局方》\\x五噎散\\x 治胸膈痞闷，诸气结聚，胁肋胀满，痰逆恶心，不进饮食。 \n白术 南星（制） 半夏曲 枳壳（麸炒） 青皮 草果 麦芽 大腹皮 干姜 丁香（各一 \n钱） 甘草（五分） \n水一钟半，姜五片，煎七分，不拘时服。 \n\\x嘉禾散\\x 一名谷神散。治脾胃不和，胸膈痞闷，气逆生痰，不进饮食，五膈五噎。 \n白茯苓 砂仁 薏仁（炒仁） 枇杷叶（去毛，姜炙） 桑白皮（炒） 沉香（磨汁） 五味子 \n白豆蔻 炙甘草 丁香 人参 白术（各五分） 木香（磨汁） 青皮 陈皮 杜仲（姜汁炒） \n谷芽（炒） 藿香 大腹皮（洗） 石斛（酒炒） 半夏曲（炒） 神曲（炒） 随风子 槟榔各三分） \n上水二钟，姜三片，枣二枚，煎八分，食远服。五噎，入柿干一个；膈气吐逆，入薤白 \n三寸，枣五枚同煎。 \n《局方》\\x人参豆蔻汤\\x 治嗝噎，宽中顺气。 \n人参 炙甘草 白豆蔻 石菖蒲（各五分） 白术 陈皮 半夏曲 萝卜子（炒研） 当归 \n浓朴（各八分） 藿香 丁香（各三分） \n水一钟半，姜三片，粟米一撮，煎七分服。 \n《良方》\\x紫苏子饮\\x 治嗝噎上气咳逆。因怒未定，便夹气饮食，或食饮毕便怒，以致食 \n与气相逆，遂成隔噎之候。 \n真苏子 诃子（煨） 萝卜子（微炒） 杏仁（去皮尖，麸炒） 人参（各一钱） 木香（五分） 青 \n皮炙甘草（各二钱） \n上咀。水一钟半，姜三片，煎七分服。 \n\\x枇杷叶煎\\x 治五噎立效。 \n枇杷叶（拭去毛尖） 橘红（各三钱） 生姜（半两） \n水一钟半，煎七分，作二次温服。 \n《统旨》\\x补气运脾汤\\x 治中气不运，噎塞。 \n人参（二钱） 白术（三钱） 黄 （一钱，炙） 橘红 茯苓（各钱半） 砂仁（八分） 甘草（炙，五分） \n水一钟半，姜一片，枣一枚，煎八分，食远服。 \n\\x利膈散\\x 治胸痹膈塞不通。 \n人参 白术 陈皮 赤茯苓 前胡（各一钱） 干姜 桂心 诃子 甘草（各五分） \n水一钟半，姜五片，煎七分，频频服之效。 \n《发明》\\x人参利膈丸\\x 治胸中不利，痰逆喘满，利脾胃壅滞，治隔噎圣药。按此方必隔 \n噎而大便秘结者乃可用。 \n人参 当归 藿香（各一两） 木香 槟榔（各七钱） 枳实（炒） 甘草（各八钱） 浓朴（姜炒） \n大黄（酒浸，各二两） \n上为末，滴水丸，桐子大。温水送下三十丸。 \n\\x草豆蔻丸\\x 治酒积胃口痛，咽膈不通。 \n草豆蔻（煨） 白术（各二两） 麦芽（煨） 神曲（炒） 黄芩 半夏（炮，各五钱） 枳实（炒，二 \n两） 橘红 青皮（各三钱） 干姜（二钱） 炒盐（五分） \n汤浸蒸饼为丸，绿豆大。每服百丸，煎白汤下。按∶此方当去黄芩，庶乎不滞。 \n（东垣）\\x清暑益气汤\\x 治暑热蒸人，四肢倦怠，胸满气促，肢节疼痛，身热而烦，小便黄 \n数，大便溏泻，自汗口渴，不思饮食。 \n人参 黄 升麻 苍术（各一钱） 白术（炒） 神曲（炒，各五分） 陈皮 炙甘草 黄柏 \n麦冬 当归（各五分） 干葛 五味 泽泻 青皮（各三分） \n水煎温服。 \n《局方》\\x香薷饮\\x 治一切暑热腹痛，或霍乱吐利烦心等证。按此方惟治阳暑，阴暑不宜用。 \n香藿（一斤） 浓朴（制） 白扁豆（炒，各半斤） \n每服五钱，水一钟半，煎八分，不拘时温服。 \n\\x五物香薷饮\\x 治一切暑毒腹痛，霍乱吐泻，或头痛昏愦等证。 \n香薷 茯苓 白扁豆 浓朴 炙甘草（各一钱） \n上为咀。水一钟半，煎服。本方加黄连，即名黄连香薷饮。 \n《百一》\\x十味香薷饮\\x 治伏暑身体倦怠，神昏头重吐泻等证。 \n香薷（二钱） 人参 黄 白术 茯苓 浓朴（姜炒） 陈皮 白扁豆（炒，各一钱） 木瓜 \n炙甘草（各五分） \n水二钟，煎七分，食远温服。 \n\\x黄连香薷饮\\x 治阳暑中热。 \n黄连（四两） 香薷（一斤） 浓朴（半斤） \n每服四钱，如前煎服。 \n（《局方》）\\x缩脾饮\\x 解伏暑，除烦渴，消暑毒，止吐泻霍乱。 \n白扁豆（炒） 干葛（各二两，一作干姜） 炙甘草 乌梅肉 砂仁 草果（各四两） \n上 咀。每服四钱，水煎冷服。 \n（《局方》）\\x七味渗湿汤\\x 治寒湿所伤，身体重着，如坐水中，小便或赤涩，大便溏泄。因 \n坐卧湿地，或阴雨之所袭也。 \n炙甘草 苍术 白术（各一钱） 茯苓 干姜（各二钱） 丁香 橘红（各二分半） \n水一钟半，姜三片，枣一枚，煎七分，食前服。 \n\\x清热渗湿汤\\x 方在寒阵。治湿热浮肿，小水不利。 \n（《金匮》）\\x防己黄 汤\\x 治风湿脉浮，身重，汗出恶风者。 \n防己 黄 （去芦，各一两） 甘草（炙，半两） 白术（七钱半） \n上 咀。每用五钱，生姜四片，枣一枚，水盏半，煎八分，温服，良久再服。喘 \n者，加麻黄半两；胃中不和，加芍药；气上冲者，加桂枝；下有陈寒者，加细辛。服后当如 \n虫行皮中，从腰下如冰，后坐被上，又以一被绕腰下，温令微汗瘥。 \n（《百一》）\\x除湿汤\\x 治中湿身体重着，腰腿酸疼，大便溏，小便或涩或利。 \n半夏曲 苍术 浓朴 茯苓（各钱半） 陈皮（七分） 藿香 炙甘草（各五分） \n水二钟，姜七片，枣一枚，煎七分，食远服。 \n\\x羌活胜湿汤\\x 治外伤湿气，一身尽痛者。此方通治湿证。 \n羌活 独活（各二钱） 本 防风（各钱半） 蔓荆子 川芎 炙甘草（各五分） \n水二钟，煎八分，食后温服。如身重腰痛沉沉然，经有寒也，加酒防己五分，附子五分。 \n（东垣）\\x升阳除湿汤\\x 治脾胃虚弱，不思饮食，肠鸣腹痛，泄泻无度，小便黄，四肢困弱。 \n升麻 柴胡 羌活 防风 半夏 益智仁 神曲 泽泻（各五分） 麦 面 陈皮 猪 \n苓甘草（各三分） 苍术（一钱） \n上 咀。作一服，水三大盏，生姜三片，枣二枚，煎至一盏，去 ，空心服。 \n（《拔萃》）\\x升阳除湿防风汤\\x 治下痢下血，大便秘滞，里急后重，数至圊而不能便，或下 \n白脓。慎勿利之，举其阳则阴自降矣。 \n防风（二钱） 白术 白茯苓 白芍药（各一钱） 苍术（酒浸去皮，炒，四钱） \n上先将苍术用水一钟半，煎至一钟，入诸药同煎至八分，食前服。 \n（《三因》）\\x白术酒\\x 治中湿骨节疼痛。 \n白术（一两） \n用酒三盏，煎一盏，不拘时频服。不能饮酒者，以水代之。 \n（《仲景》）\\x五苓散\\x 治暑热烦躁，霍乱泄泻，小便不利而渴，淋涩作痛，下部湿热。 \n白术 猪苓 茯苓（各七钱半） 肉桂（五钱） 泽泻（一两二钱半） \n古法为细末，每服二钱，白汤调下，日三服。今法以水煎服。 \n\\x加减五苓散\\x 治湿热黄胆，小水不利。 \n即前五苓散去肉桂，加茵陈各等分。 \n\\x加味五苓散\\x 治湿胜身痛，小便不利，体痛发渴。此太阳经解表渗利之剂，治风湿、寒湿药也。 \n即前五苓散加羌活。 \n（《金匮》）\\x茵陈五苓散\\x 治黄胆。 \n茵陈蒿末（十分） 五苓散（五分） \n上和匀，先食饮方寸匕，日三服。 \n\\x柴胡茵陈五苓散\\x 治伤寒、温湿、热病发黄，小便赤黑，烦渴发热。此以汗下太早，湿 \n热未除，以致遍身发黄，尝用此治之甚效。 \n五苓散（一两） 加茵陈（半两） 车前子（一钱） 木通 柴胡（各一钱半） \n上分二服，用水一钟半，灯草五十茎，煎服。连进数服，小便清利而愈。因酒后者，加干葛二钱。 \n\\x四苓散\\x \n即前五苓散去肉桂。 \n（仲景）\\x猪苓汤\\x 治伤寒下后，脉浮发热，渴欲饮水，小便不利，及少阴病下利，咳而呕 \n，渴，心烦不得眠者。 \n猪苓（去皮） 茯苓 阿胶 滑石 泽泻（各一两） \n上五味，以水四升，先煮四味取二升，去滓，纳阿胶烊尽，服七合，日三服。 \n\\x茯苓汤\\x 治湿热泄泻，或饮食泄泻。 \n茯苓 白术（炒，各五钱） \n上用水煎，食前服。一方有芍药等方，名白术散。 \n\\x胃苓汤\\x 治脾湿太过，泄泻不止。 \n陈皮 浓朴 甘草 苍术 白术 茯苓 泽泻 猎苓 肉桂（各等分） \n每服五、六钱，姜五片，枣二枚，水煎服。 \n\\x橘半胃苓汤\\x 治呕吐泄泻，胀满不下，食不知味。 \n橘红 半夏（制，各一钱） 苍术（米泔浸炒） 白术（炒） 浓朴 炙甘草 人参 茯苓 泽 \n泻茅根（各二钱） 姜汁（数匙） \n水二钟，煎一钟，入姜汁再煎一、二沸，陆续饮之。 \n\\x柴苓汤\\x 治身热烦渴泄泻。 \n白术 茯苓 泽泻 柴胡 猪苓 黄岑 \n上水煎服。 \n\\x加减柴苓汤\\x 治诸疝。此和肝肾、顺气、消疝、治湿之剂。 \n柴胡 甘草 半夏 茯苓 白术 泽泻 猪苓 山栀（炒） 山楂 荔核（煨，各等分） \n上 咀。水二钟，姜三片，煎八分，食前服。 \n《局方》\\x真人养脏汤\\x 治大人小儿冷热不调，下痢赤白，或如脓血、鱼脑，里急后重， \n脐腹 痛；或脱肛坠下，酒毒便血，并治之。 \n人参 当归 诃子 肉豆蔻（面煨） 炙甘草 木香（各一钱） 芍药 白术（各三钱） 肉桂（五 \n分） 粟壳（蜜炙，二钱） \n水二钟，煎八分，食远服。脏寒者，加附子一钱。 \n《良方》\\x草果散\\x 治中寒泄泻，腹痛无度。 \n浓朴（姜汁炒，二两） 肉豆蔻（面煨） 草豆蔻（煨，各十个） \n上每服三钱，姜、水煎服。 \n《经验》\\x大橘皮汤\\x 治湿热内甚，心腹胀满，水泻，小便不利。 \n橘皮 槟榔（各一钱） 滑石 茯苓 猪苓 泽泻 白术（各二钱） 官桂 甘草（各五分） \n水一钟半，生姜三片，煎八分，食远服。 \n\\x消食导气饮\\x 治凡遇气怒便作泄泻，此必因怒挟食所致。其有脾土本虚，不胜肝气者， \n此方主之。 \n人参 白术 茯苓 炙甘草 川芎 半夏 青皮 陈皮 枳实 香附 神曲 砂仁 木 \n香上酌虚实增减用 \n水一钟半，姜三片，煎七分，食远温服。 \n《外台》\\x黄芩汤\\x 治干呕下利。 \n黄芩 人参 干姜（各三两） 桂枝（一两） 半夏（半升） 大枣（十二枚） \n上六味，以水七升，煮取三升，温分三服。 \n\\x秘传斗门方\\x 治毒痢脏腑撮痛，脓血赤白，或下血片，日夜不息，及噤口恶痢，里急后 \n重，全不进食，久渴不止，他药不能治者，立见神效。 \n干姜（炒，四钱） 粟壳（蜜炙，八钱） 地榆 甘草（炙，各六钱） 白芍药（炒，三钱） 黑豆（炒 \n，去皮，一两半） \n上 咀，可分三、四帖，用水一钟半，煎七分，食远热服。 \n\\x治痢简易八方\\x \n《外台秘要》方∶治痢下白脓不止。用白面一味炒熟，捣筛，煮米粥内方寸匕食之。此 \n疗泻痢日至百行，药所不及者也。 \n《千金方》∶治痢。用薤白一握，细切，煮粥食之。 \n《圣惠方》∶治赤白痢疾。以葱一握，切，和米煮粥，空腹食之。 \n《千金翼方》∶用鸡子以醋煮极熟，空腹食之，治久痢赤白。 \n又方∶用干姜于火内烧焦黑，不可成炭，放瓷瓶中闭冷，为末。每服一钱，米饮调下。 \n炙鸡散∶治脾胃气虚，肠滑下痢。用黄雌鸡一只，制如食法，以炭火炙之，捶扁，用盐 \n醋刷遍，又炙，令极熟而燥。空腹食之。 \n一方 治热毒下血，痢久不已。用当归、黄连各三钱，乌梅五个，水煎八分，空心服。 \n《类方》\\x曲术丸\\x 治暑湿暴泻，壮脾温胃，及治饮食所伤，胸膈痞闷。 \n神曲（炒） 苍术（米泔浸一宿，切，炒，等分） \n上为细末，面糊丸，桐子大。每服七、八十丸，米饮下，不拘时。 \n《局方》\\x戊己丸\\x 治脾经受湿，泻痢不止，米谷不化，脐腹刺痛。 \n黄连（炒） 吴茱萸（炮炒） 白芍药（各五两） \n一方∶黄连四两，吴茱萸二两，芍药三两。 \n上为细末，面糊丸，桐子大。每服七十丸，空心食前米饮下。 \n《圣惠》\\x双荷散\\x 治卒暴吐血。 \n藕节（七节） 荷叶顶（七个） \n上入蜜一匙，擂细，水二钟，煎八分，温服；或为末，蜜汤调下二钱亦妙。 \n《直指》\\x侧柏散\\x 治内损失血，饮酒太过，劳伤于内，气血妄行，血如涌泉，口鼻皆出 \n，须臾不救，服此即安。又治男妇九窍出血。 \n人参 荆芥穗（烧灰，各一钱） 侧柏叶（蒸干，一两半） \n上为末。每服三钱，入飞罗面三钱，拌匀，汲水调粘，啜服。 \n\\x地黄煎\\x 治吐血，忧患内伤，胸膈疼痛，及虚劳唾血百病，久服佳。 \n用生地黄一斤，捣取汁，于银锅或砂锅微火煎一、二沸，入白蜜一斤，再煎至三升，每 \n服半升，日三服。 \n一方∶用生地黄汁一升，生姜汁一合，和匀。温服，日三、四次。 \n一方∶治虚劳吐血。用生地黄五斤捣，以好酒五升煮，去渣服。 \n《局方》\\x枇杷叶散\\x 治暑毒攻心，呕吐鲜血。 \n香薷（二钱） 浓朴 甘草 麦门冬 木瓜 茅根（各一钱） 陈皮 枇杷叶 丁香（各五分） \n上为末。每服二钱，姜、水煎服。 \n\\x阿胶散\\x 治肺燥咳嗽不已，及唾血。 \n阿胶（炒） 白芨（各二钱） 天门冬 北五味子 人参 生地黄 茯苓（各一钱） \n上以白芨为细末，余药用水一钟半，入蜜二匙，秫米百粒，生姜五片，同煎熟，入白芨 \n末调，食后温服。 \n《良方》\\x阿胶散\\x 方在妇人。安胎补血气。 \n（钱氏）\\x阿胶散\\x 方在小儿。治小儿咳嗽喘急。 \n\\x绿云散\\x 治吐血。 \n柏叶 人参 阿胶（炒珠） 百合 \n上等分为末。每服二钱，不拘时，糯米饮调下。 \n《简易》\\x黑神散\\x 治一切吐血，及伤酒食醉饱，低头掬损，吐血致多，并血热妄行，口 \n鼻俱出，但声未失，无有不效。 \n百草霜 不拘多少，村居者佳。 \n上研细。每服二钱，糯米煎汤下。喜凉水者，以新汲水调服；衄血者，用少许吹鼻。皮 \n破出血或炙疮出血，掺之即止。 \n《局方》\\x黑神散\\x 方在妇人。治产后恶露不尽，胎衣不下，攻心腹痛。 \n\\x天门冬丸\\x 治吐血咯血，大能润肺止嗽。 \n天门冬（一两） 贝母 杏仁（各七钱，炒） 白茯苓 阿胶 甘草（各五钱） \n上为细末，炼蜜丸，芡实大。每噙化一丸，津咽下。 \n\\x发灰散\\x 治起居所伤，小便尿血，或忍尿脬转，脐下急痛，小便不通，又治肺疽心衄， \n内崩吐血，舌上出血。 \n乱发（烧灰。即血余也） \n上每服二钱，以米醋汤调服。 \n\\x棕灰散\\x 治大肠下血不止，或妇人崩漏下血。 \n败棕 不拘多少，烧灰存性，为细末。 \n每服二钱，空心好酒或清米饮调服。 \n《宝鉴》\\x平胃地榆汤\\x 治邪陷阴分，则阴结便血。 \n陈皮 浓朴 苍术 甘草 地榆 人参 白术 当归 芍药 升麻 干葛 茯苓 神曲 \n干姜（炒） 香附（各等分） \n上咀。每服五钱，加姜、枣煎，空心服。 \n（海藏）\\x愈风汤\\x 一名举卿古拜散。治一切失血，筋脉紧急，产后或汗后搐搦。 \n荆芥穗（为细末） \n上先炒大豆黄卷，以酒沃之，去黄卷取净汁，调前末三、四钱服之。轻者一服，重者二 \n、三服即止。气虚者忌服。童便调亦可。 \n《局方》\\x小乌沉汤\\x 治气逆便血不止。 \n乌药（一两） 炙甘草 香附（醋炒，四两） \n上为末。每服二钱，食前盐汤下。 \n\\x除湿和血汤\\x 治阳明经湿热虚陷，便血腹痛。 \n当归身（酒拌） 牡丹皮 生地黄 熟地黄 黄 （炙） 炙甘草（各一钱） 白芍药（钱半） 生 \n甘草 升麻 陈皮 秦艽 苍术 肉桂（各五分） \n水二钟，煎八分，空心，候宿食消尽热服。 \n\\x驱疟饮\\x 治诸疟久疟不愈者。 \n草果 青皮 陈皮 人参 茯苓 半夏（制） 浓朴 苍术（炒） 槟榔 白术 甘草（各一 \n钱） 良姜（五分） \n水二钟，枣二枚，乌梅一个，煎八分，食远服。 \n\\x祛疟饮\\x 三发后，火盛气强者，可因其衰而减之，立效。 \n贝母（去心） 紫苏（各一钱） 橘红 山楂肉 枳实（各钱半） 槟榔（八分） 柴胡（七分） 甘草（ \n炙，三分） 知母（去毛净，盐酒炒过，五钱） \n上用水二钟，煎一钟，又将滓再煎，至八分，并一处，露过宿，临发日早温服一半，未 \n发前一时许再温服后半。 \n\\x截疟饮\\x 《史崇质传》云∶得之四明胡君，屡试屡验。 \n黄 （炙，一钱六分） 人参 白术 白茯苓 橘红 砂仁 草果 五味子（各一钱） 甘草（七 \n分） 乌梅（三枚） \n水二钟，姜三片，枣二枚，煎一钟，温服。 \n《济生》\\x万安散\\x 治一切疟病之初，邪盛气壮者，进此药以逐邪取效。若气虚胃弱及妊妇，皆不宜用。 \n苍术 浓朴（姜炒） 陈皮 槟榔 常山（酒浸） 甘草（炙，各一钱半） \n上咀。水一钟半，煎八分，露一宿，临发早，温服。忌热物。 \n《济生》\\x鳖甲饮子\\x 治疟疾久不愈，胁下痞满，腹中结块，名曰疟母。 \n鳖甲（醋炙） 川芎 黄 草果仁 槟榔 白术 橘红 白芍药 甘草 浓朴（制，等分） \n上 咀。每服五七钱，水一钟，姜七片，枣一枚，乌梅少许，煎七分，温服无时。 \n《济生》\\x清脾饮\\x 治瘅疟脉来弦数，但热不寒，或热多寒少，口苦咽干，小便赤涩。 \n浓朴（制） 青皮 白术 草果仁 柴胡 茯苓 黄芩 半夏 甘草（各等分） \n每服四、五钱，水一钟半，姜三片，枣一枚，未发前服。忌生冷、油腻。寒多者，可加 \n肉桂；热多者，可加黄连。 \n《局方》\\x草果饮\\x 治诸疟通用。 \n草果 川芎 白芷 苏叶 青皮 陈皮 良姜 炙甘草 \n上等分， 咀。每服五钱，水一钟半，煎七分，温服，留滓服并煎。当发日，进 \n三服，不以时。加姜煎，亦治寒疟。 \n《简易》\\x七宝饮\\x 治一切疟疾，不拘寒热，鬼疟、食疟。 \n常山 草果 槟榔 浓朴（姜制） 青皮 陈皮 甘草（各一钱） \n上用酒、水各一钟，共煎一钟，将滓亦如前再煎一钟，各另放，俱露一宿，至次日当发 \n清晨，面东先服头服，少顷，再饮二服，大有神效。 \n《简易》\\x四兽饮\\x 治诸疟，和胃消痰。 \n人参 白术 茯苓 甘草（炙减半） 陈皮 半夏 草果 乌梅（各等分） 大枣（三枚） 生姜（五片） \n上咀，以盐少许，腌食顷，湿纸浓裹，慢火煨香熟，每服四、五钱，水一钟半， \n煎七分，温服。 \n《局方》\\x常山饮\\x 治疟疾发散不愈，渐成痨瘵。 \n知母 常山 草果 乌梅肉（各一斤） 良姜（二十两） 炙甘草（一斤） \n上咀。每服五钱，姜五片，枣一枚，水煎服。 \n（丹溪）\\x截疟丹\\x \n雄黄（一两） 人参（五钱） \n上为末，于端午日用粽子尖丸，桐子大。每服一丸，发日早，面东，井花水吞之。忌诸热味。 \n《集成》\\x截疟常山饮\\x \n常山 草果 穿山甲（炙） 甘草（炙） 槟榔 知母 乌梅 \n上等分，用水、酒各一钟，煎至一钟，露一宿，发前二时温服。如吐则顺之。 \n《宝鉴》\\x交加饮子\\x 治痰、食、瘴气、虚寒等疟。 \n肉豆蔻 草豆蔻（各二个，一煨一生） 浓朴（二钱，半炒半生） 大甘草（二寸，半生半炙） 生 \n姜（一两，半生半煨） \n上水一钟半，煎八分，发日空心服，未愈再服。 \n\\x柴平汤\\x 治脉濡湿疟，一身尽痛，手足沉重，寒多热少。 \n柴胡 人参 半夏 黄芩 甘草 陈皮 浓朴 苍术 \n水二钟，加姜、枣煎服。 \n《局方》\\x人参养胃汤\\x 治外感风寒，内伤饮食，寒热头痛，身体拘急，山岚瘴气，疫疠疟疾等症。 \n半夏 浓朴（姜制） 橘红（各八分） 藿香 草果 茯苓 人参（各五分） 苍术（一钱） 炙甘草（三分） \n姜七片，乌梅一个，水煎服。 \n\\x和解散\\x 治瘴病初作，胸腹满闷，头眩发热。 \n浓朴（姜汁炒） 陈皮（各二两） 甘草（四两，炒） 本 桔梗（各三两） 苍术（半斤米泔浸一 \n宿，二两） \n上为粗末。每服五、七钱，水钟半，姜三片，枣一枚，煎七分，热服。日三服，夜一服 \n。此药不拘伤风伤寒，初作未分证候，任服之，大能助胃祛邪，和解百病。 \n\\x槟榔煎\\x 治山岚瘴气，寒热呕吐腹满，不思饮食。 \n槟榔 苍术 浓朴（姜制） 陈皮 草果（各一钱） 甘草（一寸） 煨生姜（一块） \n水一钟半，枣三枚，煎八分，食远热服。 \n\\x屠酥酒\\x 辟山岚瘴气，瘟疫等气。 \n麻黄 川椒（去合口者） 细辛 防风 苍术（制） 干姜 肉桂（去粗皮） 桔梗（等分） \n上为粗末，绢囊贮浸酒中，密封瓶口，三日后可服。每日空心服一、二杯。冒露远行， \n辟诸邪气，但不宜多饮使醉。 \n\\x降椒酒\\x 辟一切瘴气，寻常宜饮之。 \n降真香（二两，细锉） 川椒（一两，去合口者） \n上用绢囊贮浸无灰酒中，约二斗许，每日饮数杯，百邪皆不能犯，兼治风湿香港脚，疝气 \n冷气，及背面恶寒、风疾有效。 \n《局方》\\x省风汤\\x 治中风挟热挟痰，口噤，口眼歪斜，挛急疼痛，风盛痰实。 \n防风 南星（生用，各二钱） 半夏（浸洗，生用） 黄芩 甘草（各一钱） \n水二钟，生姜五片，煎八分，不拘时服。此药同导痰汤合服尤妙。 \n《局方》\\x八风散\\x 治风气上攻，头目昏眩，肢体拘急烦疼，或皮肤风疮痒痛，及寒壅不 \n调，鼻塞声重。 \n藿香（去土，半斤） 前胡（去芦） 白芷（各一斤） 黄 （炙） 甘草（炙） 人参（各二斤） 羌活 \n防风（各三斤） \n上为细末。每服二钱，水一钟，入薄荷少许，煎七分，食后温服。或用腊茶清调服一钱 \n亦可。小儿虚风，用腊茶清调下半钱，更量儿大小加减服。 \n\\x防风当归汤\\x 治发汗过多，发热，头摇口噤，脊背反张，太阳兼阳明证也，宜去风养血。 \n防风 当归 川芎 熟地黄（等分） \n每服一两，水二钟，煎一钟，温服。 \n\\x顺风匀气散\\x 治中风中气，半身不遂，口眼 斜，先宜服此。 \n白术 人参 天麻（各五分） 沉香 白芷 青皮 甘草（各四分） 紫苏 木瓜（各三分） 乌药（一钱半） \n水一钟半，姜三片，煎七分，食远服。 \n《易简》\\x星香汤\\x 治中风痰盛，服热药不得者。凡痰厥气厥，身热面赤者，宜服之。 \n南星（八钱） 木香（一钱） \n上作二帖。水二钟，生姜十片，煎七分，不拘时服。 \n《济生》\\x八味顺气散\\x 治气厥、身冷似中风。凡患中风者，先服此药顺气，次进治风药。 \n人参 白术 茯苓 青皮 陈皮 白芷 台乌（各一两） 甘草（半两） \n上咀。每服三钱，水一盏，煎七分，温服。 \n《机要》\\x大秦艽汤\\x 治中风外无六经之形证，内无便溺之阻隔，血弱不能养筋，故手足 \n不能运动，舌强不能言语，宜养血而筋自愈。 \n当归 芍药 白术 生地 熟地 川芎 甘草 茯苓 防风 白芷 独活 羌活 黄芩 \n（各七分） 秦艽 石膏（各一钱） 细辛（五分） \n春、夏加知母一钱。 \n水二钟，煎一钟，温服。如遇天阴，加生姜七片；如心下痞，加枳实五分。按∶此汤自 \n河间、东垣而下，俱用为中风之要药。夫既无六经之外证，而胡为用羌、辛、防、芷等药？ \n既内无便溺之阻隔，而何用石膏、秦艽、黄芩之类？其为风寒痛痹而血虚有火者，乃宜此方耳。 \n《拔萃》\\x养血当归地黄汤\\x 治中风少血偏枯，筋脉拘挛疼痛。 \n当归 川芎 熟地黄 芍药 本 防风 白芷（各一钱） 细辛（五分） \n水一钟半，煎八分，食远温服。 \n\\x薏苡仁汤\\x 治中风流注，手足疼痛，麻痹不仁，难以伸屈。 \n薏苡仁 当归 芍药 麻黄 官桂 苍术（米泔浸，切，炒） 甘草 \n水一钟半，生姜七片，煎八分，食前服。自汗，去麻黄；有热，减官桂。 \n\\x涤痰汤\\x 治中风痰迷心窍，舌强不能言。 \n南星（制） 半夏（泡七次，各二钱半） 枳实（麸炒） 茯苓（各一钱） 橘红（一钱半） 石菖蒲 \n人参（各一钱） 竹茹（七分） 甘草（五分） \n水一钟半，生姜五片，煎八分，食后服。 \n\\x清心散\\x 治风痰不开。 \n青黛 硼砂 薄荷（各二钱） 牛黄 冰片（各三分） \n上为细末。先以蜜水洗舌，后以姜汁擦舌，将药末蜜水调稀擦舌本上。 \n《简易》\\x虎骨散\\x 治半身不遂，肌肉干瘦为偏枯。忌用麻黄发汗，恐枯津液，惟此方润 \n筋去风。 \n当归 乌蛇肉（各二两） 赤芍药 白术 续断 本 虎骨（各一两） \n上为细末。每服二钱，食后温酒调下。若骨中烦疼，加生地黄一两；若脏寒自利，加天雄半两。 \n\\x虎骨散\\x 治风毒走注，疼痛不定，少得睡卧。 \n虎胫骨（醋炙） 龟板（醋炙，各二两） 血竭（另研） 没药（另研） 自然铜（醋粹） 赤芍药 \n当归 苍耳子（炒） 骨碎补（去毛） 防风（各七钱半） 牛膝（酒浸） 天麻 槟榔 五加皮 \n羌活（各一两） 白附子（炮） 桂心 白芷（各半两） \n上为细末。每服二钱，温酒调下，不拘时。 \n\\x交加散\\x 治螈 ，或战振，或产后不省人事，口吐痰涎。 \n当归 荆芥穗（等分） \n上为细末。每服二钱，水一钟，酒少许，煎七分，灌服，神效。 \n《良方》\\x交加散\\x 方在妇人。 \n治经脉结聚不调，腹中撮痛。 \n（洁古） 四白丹 清肺气，养魂魄，以中风多昏冒，气不清利也，兼能下强骨髓。 \n白术 白茯苓 人参 川芎 甘草 砂仁 香附 防风（各半两） 白芷（一两） 白檀香 藿 \n香（各钱半） 知母 细辛（各二钱） 羌活 薄荷 独活（各二钱半） 麝香（一钱，另研） 牛黄 片脑 \n（各五分，另研） 甜竹叶 \n上为末，炼蜜为丸，每两作十丸。临睡嚼一丸，煎愈风汤送下。上清肺气，下强骨髓。 \n\\x续断丹\\x 治中风寒湿，筋挛骨痛。 \n续断 萆 （酒浸） 牛膝（酒浸） 干木瓜 杜仲（炒，各二两） \n上为末，炼蜜和丸，每两作四丸。每服一丸，细嚼温酒下，不拘时。 \n《济生》\\x 丸\\x 治中风口眼 斜，时吐涎沫，语言蹇涩，手足缓弱。 草（ \n生于沃壤间带猪气者是） \n五月五日或六月六日采叶洗净，不拘多少，九蒸九晒，每蒸用酒蜜洒之，蒸一饭顷。九 \n蒸毕，日干为末，炼蜜丸，桐子大。每服百丸，空心温酒、米饮任下。 \n一方∶每 草一斤，加四物料各半两，川乌、羌活、防风各二钱，丸服。 \n\\x蠲痹汤\\x 治周痹及手足冷痹，脚腿沉重，或身体烦疼，背项拘急。 \n当归 赤芍药（煨） 黄 姜黄 羌活（各钱半） 甘草（五分） \n水二钟，姜三片，枣二枚，不拘时服。 \n\\x三痹汤\\x 治血气凝滞，手足拘挛，风痹等疾皆效。 \n人参 黄 当归 川芎 熟地黄 白芍药 杜仲（姜汁炒） 续断 桂心 牛膝 细辛 \n白茯苓 防风 秦艽 独活 甘草（等分） \n水二钟，姜三片，枣一枚，煎七分，不拘时服。 \n\\x加味五痹汤\\x 治五脏痹证。 \n人参 白芍药（煨） 茯苓 川芎（或倍之） 当归（各一钱） 五味子（十五粒） 细辛（七分） 甘 \n草（五分） 白术（一钱，脾痹倍用） \n水二钟，姜一片，煎八分，食远服。肝痹，加枣仁、柴胡；心痹，加远志、茯神、麦冬 \n、犀角；脾痹，加浓朴、枳实、砂仁、神曲；肺痹，加紫菀、半夏、杏仁、麻黄；肾痹，加 \n独活、官桂、杜仲、牛膝、黄 、萆 。 \n\\x人参散\\x 治肝脾气逆，胸胁引痛，眠卧多惊，筋脉挛急，此药镇肝去邪。 \n人参（二两） 杜钟（炒） 黄 （炙） 枣仁（微炒） 茯神（各一两） 五味子 细辛（去苗） 熟 \n地黄 秦艽 羌活（去芦） 芎 丹砂（细研，各半两） \n上为细末，入丹砂再研匀，每服一钱，不拘时，温酒调下，日三服。 \n\\x六味茯苓汤\\x 治肢体手足麻痹，多痰唾，眩冒者。 \n半夏（制） 赤茯苓 橘红（各二钱） 枳壳（麸炒） 桔梗（去芦） 甘草（炙，各一钱） \n水二钟，姜五片，煎八分，不拘时服。 \n\\x枳实散\\x 治心痹胸中气坚急，心微痛，气短促，咳唾亦痛，不能饮食。 \n枳实（麸炒） 桂心 细辛 桔梗（各七钱半） 青皮（一两） \n上 咀。每服三钱，水一钟，生姜一钱半，煎六分，不拘时服。 \n\\x紫苏子汤\\x 治肺痹心胸满塞，上气不下。 \n紫苏子（炒，八两） 半夏（汤泡，五两） 橘红 桂心（各三两） 人参 白术 甘草（炙，各二两） \n上 咀。每服四、五钱，水一钟，生姜五片，枣二枚，煎七分，不拘时温服。 \n\\x除湿蠲痛汤\\x 治风湿痛痹。 \n羌活 茯苓 泽泻 白术（各一钱半） 陈皮（一钱） 甘草（四分） 苍术（米泔浸炒，二钱） \n水二钟，煎八分，入姜汁、竹沥各二、三匙。痛在上者，加桂枝、威灵仙、桔梗；痛在 \n下者，加防己、木通、黄柏、牛膝。 \n\\x桂心散\\x 治风邪走注疼痛。 \n桂心 漏芦 芎 威灵仙 白芷 当归 木香 白僵蚕（炒） 地龙（去土炒干，各半两） \n上为细末。每服二钱，温酒调下，不拘时。 \n\\x湿郁汤\\x 治雨露所袭，或岚气所侵，或坐卧湿地，或汗出衣衫湿郁，其状身重而痛，倦 \n怠嗜卧，遇阴寒则发，脉沉而细缓者是也。 \n苍术（三钱） 白术 香附 橘红 浓朴（姜汁炒） 半夏（制） 白茯苓 抚芎 羌活 独活 \n（各一钱） 甘草（五分） \n生姜五片，水煎服。 \n\\x趁痛散\\x \n乳香 没药 桃仁 红花 当归 羌活 地龙（酒炒） 牛膝（酒洗） 甘草 香附（童便 \n洗） 五灵脂（酒炒） \n上为末。每服二钱，酒调服。或加酒炒芩、檗。 \n\\x秦艽地黄汤\\x 治风热血燥，筋骨作痛。 \n秦艽 生地黄 当归 川芎 白芍药 甘草 防风 荆芥 升麻 白芷 蔓荆子 大力 \n子（蒸） 羌活（各一钱） \n上水煎服。 \n\\x活络饮\\x 治风湿痹痛，诸药不效。 \n当归 白术 川芎 羌活 独活（各一钱） 甘草（五分） \n水一钟半，姜五分，煎七分，温服。 \n《宝鉴》\\x独活寄生汤\\x 治肾虚卧冷，寒湿当风，腰脚疼痛。 \n独活（一钱） 杜仲（炒） 细辛 桑寄生 人参 当归 川芎 芍药 茯苓 牛膝 甘草 \n桂心 熟地黄 防风 秦艽 \n水一钟半，姜三片，煎七分，空心服。 \n\\x透经解挛汤\\x 治风热筋挛骨痛。 \n穿山甲（三钱，炮） 荆芥 红花 苏木 羌活 当归 蝉蜕（去土） 防风 天麻 甘草（各 \n七分） 白芷（一钱） 连翘 川芎（各五分） \n上酒、水各半煎服。 \n\\x熏蒸方\\x 治肾气衰弱，或肝脾肾三经受风寒湿气，停于腿膝经络，致成脚痹疼痛。宜用 \n此药和荣卫、通经络，是亦治痹之法。 \n花椒（一撮） 葱（三大茎，切） 盐（一把） 小麦麸（约四、五升） 酒（一盏） 醋（不拘多少，以拌 \n前件，至润为度） \n上放铜器内炒令极热，摊卧褥下，将患脚熏蒸其上，盖以衣被，稳卧一时，要汗出为度 \n，勿见风。或加姜、桂亦妙。 \n\\x熏洗痛风法\\x 治手足冷痛如虎咬者。 \n上用樟木屑一斗，以急流水一担煮沸，将樟木屑入大桶内，用前汤泡之，桶边放一兀凳 \n，桶内安一矮凳，令病患坐桶边，放脚在桶内，外以草荐一领围之，勿令汤气入眼，恐致坏 \n眼。其功甚捷。 \n\\x愈风丹\\x 治足三阴亏损，风邪所伤，肢体麻木，手足不随等证。 \n羌活（十四两） 当归 熟地 生地（各一斤） 杜仲（七两） 天麻 萆 （另研细） 牛膝（酒浸 \n焙干） 玄参（各六两） 独活（五两） 肉桂（三两） \n炼蜜丸，桐子大。每服五、七十丸，或百丸，空心食前，温酒或白汤下。 \n\\x易老天麻丸\\x 治诸风肢节麻木，手足不随等证。 \n天麻（酒浸三日，焙干） 牛膝（制同前） 萆 （各六两，另研末） 当归（二十两） 附子（制， \n一两） 羌活（十两） 生地（一斤） \n丸服如前法。一方有玄参（六两） 杜仲（七两） 独活（五两） \n按∶此方与前愈风丹大同，但生地性凉，恐滞经络，宜改用熟地为妥。且以六十四两之 \n诸药，而佐以一两之附子，果能效否？此最少亦宜四两或六两方可也。 \n\\x愈风燥湿化痰丸\\x 治历节风，湿痰壅滞，昼夜疼痛无休者。 \n白术（炒） 苍术（米泔浸） 杜仲（姜汁炒，各二两） 牛膝（酒浸） 川芎 薏仁 巴戟 破 \n故（炒，各一两） 当归 牙皂（瓦炒） 防风 羌活 生地 独活 防己 天麻 南星 半夏 \n陈皮 木香 沉香 川乌 僵蚕 全蝎（各五钱） \n上为末，酒糊丸，桐子大。每服百丸，空心、食前酒送下，日二次，食干物压之。 \n\\x活络丹\\x 治中风手足不用，日久不愈，经络中有湿痰死血者。 \n草乌（炮，去皮） 川乌（炮，去皮脐） 胆星（各六两） 地龙（去土焙干） 乳香（去油） 没 \n药（各二两，二钱） \n蜜丸，桐子大。每服二、三十丸，温酒、茶清任下。 \n（东垣）\\x开结导饮丸\\x 治饮食不消，心下痞闷，腿脚肿痛。 \n白术（炒） 陈皮（炒） 泽泻 茯苓 神曲（炒） 麦芽（炒） 半夏（制，各一两） 枳实（炒） \n青皮 干姜（各五钱） 如有积块者，加巴霜钱半 \n为末，汤浸蒸饼为丸，梧子大。每服四、五丸或十丸，温水下。此内伤饮食，脾胃之气 \n不能营运上升，则注为香港脚，故用此以导引行水化脾气也。 \n\\x换骨丹\\x 通治诸风痹痛，兼治鹤膝风。此与后史国公浸酒方大同。 \n虎骨（酥炙） 防风 牛膝 当归 羌活 独活 败龟板 秦艽 萆 晚蚕砂 松节（各 \n一两） 枸杞（一两半） 茄根（洗净，二两） \n酒糊丸服，或酒浸、或为末服亦可。 \n《局方》\\x换腿丸\\x 治足三阴经虚，为风寒热湿所侵，发为挛痹，纵缓疼痛，上攻胸胁， \n下至脚膝，足心发热，行步艰难。 \n薏仁 南星 防己 防风 石斛 槟榔 萆 石南叶 羌活 木瓜（各四两） 牛膝（酒 \n浸） 当归 天麻 续断（各一两） 黄 （一两半） \n上为末，酒糊丸，梧子大。每服五、七十丸，空心、盐酒下。 \n\\x史国公浸酒方\\x 一名万病无忧酒。治诸风五痹，左瘫右痪，四肢顽麻，口眼歪斜，骨节 \n酸痛，诸般寒湿风气，效难尽述。 \n当归 鳖甲（炙） 羌活 萆 秦艽 防风（去芦） 牛膝 晚蚕砂 松节（各二两） 枸杞 \n（五两） 干茄根（八两，饭上蒸熟） 虎胫骨（酒浸一日。焙干，酥炙） \n用无灰酒一斗，绢袋盛药入酒内，封十日可服。取饮时，不可面向坛口，恐药气冲人头 \n面。饮酒不可间断。饮尽，将药渣晒干为末，米糊丸，桐子大，空心酒下五十丸。忌发风动气等物。 \n《类方》\\x煨肾散\\x 治腰痛。 \n人参 当归 杜仲 肉苁蓉 破故纸 巴戟 鹿角霜 秋石（等分） \n为末，用猪腰子一个，洗净血水，淡盐 过，劈开两半，勿令断，中间细细花开 \n，用前药掺入，另用稀绢裹，线缚定，外用小砂罐入酒少许，用纸封固，毋令泄药气，煮腰 \n子候熟取食之，仍饮醇酒三杯，立愈。 \n\\x调荣活络饮\\x 治失力闪腰，或跌扑瘀血，及大便不通，腰痛。 \n当归 牛膝 杏仁（研如泥） 大黄（各二钱） 生地 芍药 红花 羌活（各一钱） 桂枝（三分） \n川芎（一钱半） \n水一钟半，煎八分，食前温服。 \n\\x胡桃汤\\x 治肾虚腰痛。 \n胡桃肉 补骨脂 杜仲（各四两。一作各四钱） \n上 咀，分二帖。用水二钟，煎七分，空心服。 \n《良方》\\x鸡鸣散\\x 治香港脚第一品药，不问男女皆可服。如感风湿流注，脚痛不可忍，筋 \n脉浮肿者，并宜服之，其效如神。 \n槟榔（七枚） 橘红 木瓜（各一两） 吴茱萸 苏叶（各三钱） 桔梗（去芦） 生姜（连皮，各半两） \n上 咀。用水三大碗，慢火煎至一碗半，取渣再入水二碗，煎取一小碗，两汁相 \n和，安置床头。次日五更，分作三、五次冷服之，冬月略温亦可，服了用干物压下，如服不 \n尽，留次日渐渐服之亦可。服药至天明，当下黑粪水，即是肾家所感寒湿之毒瓦斯也。至早饭 \n时，必痛住肿消，只宜迟吃饭，使药力作效。此药并无所忌。 \n\\x茱萸木瓜汤\\x 治香港脚冲心，闷乱不识人，手足脉欲绝。 \n吴茱萸（半两） 干木瓜（一两） 槟榔（二两） \n上 咀。每服八钱，水一钟半，生姜五片，煎八分，不拘时温服。 \n\\x立效散\\x 治香港脚攻心。此方消肿甚效，及治暴肿。 \n槟榔（七枚） 生姜（二两） 陈皮 吴茱萸 紫苏 木瓜（各一两） \n上水三升，煎一升，分作二服。 \n（丹溪）\\x防己饮\\x 治香港脚。 \n白术 木通 防己 槟榔 川芎 甘草梢 犀角 苍术（盐水炒） 生地黄 黄柏（酒炒，等分） \n上水煎服。大便实，加桃仁；小便涩，加牛膝；有热，加黄芩、黄连；大热及时令热， \n加石膏；有痰，加竹沥、姜汁。 \n\\x紫苏散\\x 治香港脚上气，心胸壅闷，不得眠卧。 \n苏叶 桑白皮 赤茯苓 槟榔 木瓜（各一两） 炙甘草 紫菀 前胡（去芦） 杏仁（去皮尖） \n百合（各七钱） \n上 咀。每服八钱，水一钟半，生姜五片，煎八分。不拘时温服。 \n《三因》\\x紫苏子汤\\x 治香港脚阴阳交错，上重下虚，中满喘急，呕吐自汗。 \n苏子（炒） 半夏（制，各一钱） 前胡 浓朴（姜汁炒） 甘草（炒） 归身（各七分） 陈皮 肉 \n桂（各四分） \n水一钟半，姜三片，煎七分，不拘时服。 \n《济生》\\x槟榔汤\\x 治一切香港脚，散气疏壅。 \n槟榔 香附 陈皮 苏叶 木瓜 五加皮 甘草（炙，各七分） \n上 咀。水一钟半，生姜三片，煎服。 \n\\x加减槟榔汤\\x 治一切香港脚、脚弱，名曰壅疾，贵在疏通，春夏尤宜服之。 \n槟榔 橘红 苏叶（各一两） 甘草（炙，半两） \n上每服五、七钱，水一钟半，生姜五片，煎八分，不拘时温服。如脚痛不已者，加木香 \n、五加皮；妇人脚痛，加当归；室女脚痛，多是肝血滞实，宜加赤芍药；中满不食，加枳实 \n；痰厥或吐，加半夏；腹痛大便不通，用此汤下青木香丸，或加大黄；小便不利，加木通； \n转筋者，加吴茱萸；脚肿而痛者，加大腹皮、木瓜；脚痛而热，加地骨皮。 \n\\x槟榔散\\x 治香港脚冲心，烦闷不识人。 \n槟榔 茴香 木香（各半两） \n上 咀。每服五钱，以童便一钟，煎七分。不拘时温服。 \n《活人》\\x桑白皮散\\x 治香港脚盛发，上气喘促，两脚浮肿，小便赤涩，腹胁胀满，气急坐卧不得。 \n桑白皮 郁李仁（各一两） 赤茯苓（二两） 木香 防己 大腹子（各一两半） 苏子 木通 槟 \n榔青皮（各七钱半） \n上每服三、五钱，姜三片，水煎服。 \n\\x木香散\\x 治香港脚冲心，烦闷，脐下气滞。 \n木香（半两） 槟榔 木通（各一两） \n上 咀。每服八钱，水一钟半，生姜五片，葱白七寸，煎八分，不拘时温服。 \n\\x木通散\\x 治香港脚遍身肿满，喘促烦闷。 \n木通（去皮） 苏叶 猪苓（各一两） 桑白皮 赤茯苓 槟榔（各二两） \n上 咀。每服五、七钱，水一钟半，生姜五片，葱白七寸，煎一钟，不拘时温服。 \n\\x人参桂心散\\x 治香港脚呕逆，心烦不能饮食。 \n人参（去芦） 赤茯苓 槟榔 麦门冬 橘红（各一两） 桂心（七钱半） \n上 咀。每用八钱，水一钟半，加生姜七片，煎服。 \n\\x橘皮汤\\x 治香港脚痰壅呕逆，心胸满闷，不思饮食。 \n橘红 人参（去芦） 苏叶（各一两） \n上 咀。每服八钱，水一钟半，生姜五片，煎一钟，不拘时温服。 \n《集验》\\x半夏散\\x 治香港脚烦闷呕逆，心胸壅闷，不能饮食。 \n半夏（泡七次，切） 桂心（各七钱半） 赤茯苓 人参（去芦） 橘红 前胡（去芦） 槟榔（各 \n一两） 苏叶（一两半） \n上 咀。每服五、七钱，水一钟半，生姜七片，淡竹茹二钱，煎七分，温服无时。 \n\\x大腹皮散\\x 治诸香港脚浮肿，心腹痞闷，小便不利。 \n大腹皮（三两） 木瓜 苏子 槟榔 荆芥穗 乌药 橘红 苏叶（各一两） 萝卜子（半两） 沉 \n香枳壳（麸炒） 桑白皮（各两半） \n上 咀。每服八钱，水一钟半，姜五片，煎八分，温服。《御医药方》加木通、 \n白茯苓、炒茴香、炙甘草四味，即名沉香大腹皮散。 \n《活人》\\x大腹子散\\x 治风毒香港脚，肢节烦疼，心神壅闷。 \n大腹子 紫苏 木通 桑白皮 羌活 木瓜 荆芥 赤芍药 青皮 独活（各一两） 枳壳（二两） \n上每服四钱，水一盏，姜五片，葱白七寸煎，空心温服。 \n\\x地黄汤\\x 治穿心香港脚。 \n熟地黄（四两） 当归（二两） 芍药 川芎 牛膝（酒浸） 三奈（各一两） 杜仲（半两，姜汁炒） \n上 咀。每服一两，水一钟半，煎八分，不拘时温服。 \n\\x木瓜汤\\x 治香港脚。 \n木瓜 大腹 紫苏 木香 羌活 炙甘草（各一钱） 茯苓 陈皮（各八分） \n水一钟半，煎八分，食前服。 \n\\x沉香汤\\x 治香港脚攻心，烦闷气促，脚酸疼。 \n沉香 木通 槟榔（各五分） 吴茱萸（三分） 赤芍（一钱半） 紫苏（一钱） \n水一钟半，生姜三片，煎八分，不拘时温服。 \n\\x续断丸\\x 治风湿流注，四肢浮肿，肌肉麻痹。 \n川续断 当归 萆 附子 防风 天麻（各一两） 乳香 没药（各半两） 川芎（七钱半） \n上为细末，炼蜜丸，桐子大。每服四十丸，空心温酒或米饮下。 \n《本事》\\x续断丸\\x 治肝肾风寒气弱，脚不可践地，脚瘠疼痛，风毒流注下部，行止艰难 \n，小便余沥。此药补五脏内伤，调中益气，凉血，强筋骨。 \n杜仲（五两） 五加皮 防风 薏仁 羌活 续断 牛膝（酒浸，各三两） 萆 （四两） 生地黄 \n（五两） \n上为末，用好酒三升，化青盐三两，用木瓜半斤去皮、子，以前盐、酒煮成膏，和药为 \n丸，梧子大。每服五、七十丸，空心食前，温酒、盐汤任下。 \n《保命》\\x牛膝丸\\x 治肾肝虚损，骨痿不能起于床，筋弱不能收持，宜益精缓中。 \n牛膝（酒浸） 萆 杜仲（炒） 白蒺藜 防风 菟丝子（酒煮） 肉苁容（酒浸，等分） \n官桂（减半） \n上为末，酒煮猪腰子捣和丸，桐子大。每服五、七十丸，空心温酒送下。 \n《本事》\\x酒浸牛膝丸\\x 治腰脚筋骨酸软无力。 \n牛膝（三两，炙黄） 川椒（去合口者） 虎骨（真者，醋炙黄，各半两） 附子（一枚，炮去皮脐） \n上 咀，用生绢作袋盛药，以煮酒一斗，春秋浸十日，夏七日，冬十四日，每日 \n空心饮一大盏。酒尽出药为末，醋糊丸，每服二、三十丸，空心温酒、盐汤任下。忌动风等物。 \n\\x茱萸丸\\x 治香港脚入腹，喘急欲死。 \n吴茱萸（泡） 木瓜（等分） \n上为末，酒糊丸，梧子大。每服五、七十丸至百丸，空心酒饮任下。或以木瓜蒸烂，研 \n膏丸服尤妙。此方内加大黄，名三将军丸。 \n（东垣）\\x健步丸\\x 治脚膝无力，屈伸不得，腰背腿脚沉重，行步艰难。 \n防己（酒洗，一两） 羌活 柴胡 滑石（炒） 炙甘草 天花粉（酒洗，各五钱） 防风 泽泻 \n（各三钱） 苦参（酒洗） 川乌（各一钱） 肉桂（五分） \n上为细末，酒糊丸，桐子大。每服七、八十丸，煎愈风汤空心送下。 \n\\x调元健步丸\\x 治阴虚血少，湿热兼行，足履无力。 \n当归（酒洗） 川黄柏（盐酒炒） 枸杞（各二两） 牛膝（三两，盐酒浸） 白芍药（微炒） 白茯 \n苓白术（炒） 苍术 陈皮（各一两） 炙甘草（三钱） 木瓜 五加皮（各八钱） 川续断（七钱） 泽泻 \n防己（各五钱） \n蜜丸，桐子大。空心盐汤送下七、八十丸，或百丸。 \n《三因》\\x胜骏丸\\x 治元气不足，为寒湿之气所袭，腰足挛拳，或脚面连指走痛无定，筋 \n脉不伸，行步不随。常服益真气，壮筋骨。 \n附子（炮制） 当归 天麻 牛膝 木香 枣仁（炒） 熟地（酒蒸） 防风（各二两） 木瓜（四 \n两） 羌活 乳香（各半两） 全蝎（炒） 甘草（炙） 没药（各一两） 麝香（二钱） \n上为末，用生地黄三斤，以无灰酒四升煮干，晒二日，杵烂如膏，入前末和匀，杵千余 \n下，每两作十丸。每服一、二丸，细嚼临卧酒下。作小丸服亦可。 \n\\x神应养真丹\\x 治厥阴经为四气所袭，脚膝无力，或右痪左瘫，半身不遂，手足顽麻，语 \n言蹇涩，气血凝滞，遍身疼痛。 \n当归（酒浸片时，捣） 熟地黄（酒蒸，捣） 川芎 芍药 羌活 天麻 菟丝子（酒制） \n木瓜（等分） \n上为末，入地黄、当归二膏，加蜜捣丸，桐子大。每服百丸，空心酒下，盐汤亦可。 \n\\x透骨丹\\x 专治香港脚。 \n川乌（炮） 羌活 沉香 乳香（另研） 川芎 槟榔 木瓜（各一两） 木香（一两半） 白茯苓 \n（二两） \n上为末，曲糊丸，梧子大。食前姜汤下六、七十丸。 \n《本事》\\x虎骨酒\\x 去风，补血益气，壮筋骨，强脚力。 \n虎胫骨（真者） 萆 仙灵脾 薏苡仁 牛膝 熟地黄（各二两） \n上锉细，绢袋盛，浸酒二斗，饮了一盏入一盏，可得百日。妇人去牛膝。 \n《活人》\\x薏仁酒\\x 治脚痹。 \n薏苡仁 牛膝（各二两） 海桐皮 五加皮 独活 防风 杜仲（各一两） 熟地黄（一两半） 白 \n术（半两） \n上为粗末，以生绢袋盛，用好酒五升浸，春秋冬二七日，夏月分作数帖，逐帖浸酒用之 \n。每日空心服一盏或半盏，日三、四服，常令酒气不绝。久服觉皮肤下如有虫行，即风湿气散。 \n\\x椒艾囊\\x 治香港脚极效，及避一切香港脚风气毒瓦斯。 \n艾叶（揉，半斤） 川椒（一斤，净） 草乌（二两，为粗末） \n上三味，和匀，用布袱铺如棉褥，裹足底及足胫，即用火踏，下加微火，烘踏于上，使 \n椒艾之气得行于足，自然寒湿风毒诸气皆得消散，立能止痛。痛止后，仍要三二日一为之， \n或夜卧包之，达旦去之。用此方法，无不效者。 \n（丹溪）\\x敷香港脚方\\x 治香港脚肿痛。 \n芥菜子 白芷（等分） \n上为末，姜汁和敷痛处。 \n\\x芜荑散\\x 治大人小儿蛔咬心痛不可忍，或吐青黄绿水涎沫，或吐虫出，发有休止，此蛔 \n心痛也，宜此主之。 \n芜荑 雷丸（各半两） 干漆（捶碎，炒大烟尽，一两） \n上为细末。每服三钱，用温水七分钟调和服，不拘时，甚者不过三服。小儿每服五分。 \n《直指》\\x芜荑散\\x 取诸虫。 \n鸡心槟榔 芜荑（各三钱） 木香（一钱） \n上为末，作一服，先以酸石榴根煎汤，俟五更时，乃嚼炙肉引虫头向上，然后以石榴根 \n汤调药温服，虫自软困而下。 \n\\x榧子煎\\x 治寸白虫，化为水。 \n细榧子（四十九枚，去壳） \n以砂糖水半盏，用砂锅煮干，熟食之，每月上旬平旦空心服七枚，七日服尽，虫化为水 \n，永瘥。一方以百枚食尽佳；不能食者，尽五十枚。经宿，虫消自下。并治三虫，神效方也。 \n\\x圣效方\\x 治寸白虫神效。 \n槟榔（半两） 南木香（二钱） \n上为细末。每服三钱，浓米饮调下。须五更空心，先嚼炙肉，只咽汁下咽，吐其肉，随 \n即服药，辰巳间当虫下，尽去病根，此方简易屡验。 \n（仲景）\\x乌梅丸\\x 治胃寒吐蛔、蛔厥等证。 \n乌梅（三十个） 人参 黄柏（炙） 细辛 附子（炮） 桂枝（各六钱） 黄连（炒，一两六钱） 干 \n姜（一两） 当归（酒浸） 川椒（去目及闭口者，各四钱，《撮要》作各四两） \n上研末，先将乌梅用酒蒸烂捣膏，加炼蜜丸，桐子大。每服一、二十丸，日三服。忌生 \n冷滑物。或用理中汤下。成无己曰∶肺欲收，急食酸以收之；乌梅之酸，以收肺气。脾欲缓 \n，急食甘以缓之；人参之甘，以缓脾气。寒淫于内，以辛润之；当归、桂、椒、细辛之辛， \n以润内寒。寒淫所胜，平以辛热；姜、附之辛热以胜寒。蛔得甘则动，得苦则安，黄连、黄 \n柏之苦以安蛔。 \n《济生》\\x乌梅丸\\x 方在固阵。治大便下血。 \n\\x神授散\\x 方在因阵。治传尸痨虫。 \n《宝鉴》\\x川楝散\\x 治诸疝、小肠气。 \n木香 小茴香（盐炒，各一两） 川楝子（一两，用巴豆十五粒打破，同炒黄，去巴豆不用） \n上为末。空心酒下二钱。 \n\\x荔核散\\x 治疝气阴核肿大，痛不可忍。 \n大茴香（炒） 沉香 木香 青盐 食盐（各一钱） 川楝肉 小茴香（各二钱） 荔枝核（十四枚， \n用新者，烧焦裂） \n上为细末。每三钱，食前热酒调服。 \n《经验》\\x苍术散\\x 治下元虚损，偏坠，肾茎痛楚。 \n真茅山苍术（六斤，分六制，一斤用老米泔水浸二日夜；一斤酒浸二日，切片晒干；一斤 \n用斗子青盐半斤，同炒黄色，不用盐；一斤用小茴香四两，同炒黄色，去茴香不用；一斤用 \n大茴香四两，同炒如前；一斤用桑椹二斤，取汁拌制，晒干） \n上为细末。每服三钱，空心酒下。 \n《宝鉴》\\x天台乌药散\\x 治小肠疝气，牵引脐腹疼痛。 \n乌药 木香 茴香（炒） 良姜（炒） 青皮（各半两） 槟榔（二个） 川楝子（十个） 巴豆（七十粒） \n上将巴豆微打破，同川楝子加麸炒黑，去麸及巴豆不用，其余共为细末。每服一钱，温 \n酒下，甚者姜酒下。 \n《百选》\\x桃仁膏\\x 治气血凝滞，疝气，膀胱小肠气，痛不可忍。 \n桃仁（炒，去皮尖） 大茴香（炒） \n上等分为末。每服二钱，葱白二寸煨熟，蘸药细嚼，空心热酒下。 \n《局方》\\x守效丸\\x 治 疝不痛者之要药。 \n苍术 南星 白芷 川芎 山楂 半夏 枳实（一云橘核） \n上等分为末，姜汁糊丸，桐子大。每服七、八十丸，盐汤下。有寒，加茱萸；有热，加 \n山栀子；又或加青皮、荔枝核。 \n\\x来复丹\\x 治伏暑泄泻，里寒外热，其效如神，及治诸腹痛疝气，小儿惊风。 \n硝石（一两，同硫黄为末，入瓷盘内，用微火炒，以柳枝搅结砂子，火不可大，恐伤药力 \n；再研极细，名二气末） 舶上硫黄（一两） 五灵脂（澄去砂） 橘红 青皮（各二两，一作各二钱） \n太阴玄精石（一两） \n上为末，醋糊丸，豌豆大。每服三十丸，空心米饮下。伏暑闷乱，紫苏汤下。大人疝气 \n诸痛，悉宜服之。小儿惊风欲绝，研碎，米汤下。 \n《卫生》\\x润肠汤\\x 治大便燥结不通。 \n生地黄 生甘草 熟地黄 当归尾 大黄（煨，各五钱） 桃仁 麻子仁（各一钱） 红花（五分） \n上用水二盏，煎一盏，空心服。 \n\\x通幽汤\\x 治大便燥结坚黑，腹痛。 \n熟地 生地 归梢 红花 桃仁泥 大黄（各一钱） 升麻（二分） \n水一钟半，煎服。古方加麻仁、甘草，即名润燥汤。 \n（东垣）\\x导滞通幽汤\\x 治幽门不通，气不升降，大便闭塞。凡脾胃初受热中，多有此证， \n治在幽门，以辛润之。 \n升麻梢 桃仁泥 归身（各一钱） 炙甘草 红花（各三分） 熟地 生地（各五分） \n水二钟，煎一钟，调槟榔末五分，稍热服。 \n（河间）\\x浓朴汤\\x 治大便气秘不通，不能饮食，小便清利者，谓之虚秘，此汤主之。盖实 \n秘者物也，虚秘者气也。 \n浓朴（一钱半） 白术（二钱） 半夏 枳壳 陈皮 甘草（各一钱） \n水一钟半，姜三片，枣三枚，煎八分，食远服。如不通，加大黄一钱。 \n《会编》\\x皂角散\\x 治大小便关格不通，经三、五日者。 \n大皂角（烧存性） \n上为末。米汤调下。又以猪脂一两煮熟，以汁及脂俱食之。又宜以八正散加槟榔、枳壳 \n、朴硝、桃仁、灯心、茶叶煎服。 \n《良方》\\x三仁丸\\x 治大肠有热，津液竭燥，大便涩。 \n柏子仁 松子仁 火麻仁（各一两） \n上研匀，用黄蜡半两溶化和丸，桐子大。每服二十丸，食前米饮下；未快，加数服之。 \n\\x脾约丸\\x 方在攻阵。通大便秘结。 \n（东垣）\\x润肠丸\\x 治胃中伏火，大便秘涩不通，不思饮食，或风结血秘，皆须润燥和血疏 \n风，则自通矣。 \n归梢 大黄（煨） 羌活（各五钱） 麻仁 桃仁（去皮尖，各一两） \n上以二仁另研为泥，外为细末，炼蜜为丸，桐子大。每服三、五十丸，空心白汤送下。 \n一方有皂角仁、秦艽各五钱。 \n《济生》\\x苁蓉润肠丸\\x 治发汗利小便，致亡津液，大腑秘结，老人虚人宜服。 \n肉苁蓉（酒浸，焙，二两） 沉香（一两，另研） \n上为末，取麻子仁捣烂，和水取汁打糊丸，桐子大。每服七、八十丸，空心米饮或酒送下。 \n\\x益血润肠丸\\x 治老人大便燥结。 \n熟地黄（六两） 杏仁（炒，去皮尖） 麻仁（各三两，以上三味同杵膏） 枳壳（麸炒） 橘红（各 \n二两） 肉苁蓉（酒洗去甲） 阿胶（炒，各一两） 苏子 荆芥（各一两） 当归（三两） \n上以后七味为末，同前三味膏和杵千余下，仍加炼蜜丸，桐子大。每服五、六十丸，空 \n心白汤或酒下。 \n\\x搜风顺气丸\\x 治痔漏风热闭结，老人燥秘等证。 \n车前子（两半） 大麻子（微炒，二钱） 大黄 （五钱，半生半熟） 牛膝（酒浸） 郁李仁 菟丝子 \n（酒浸） 枳壳 山药（各二钱） \n上为末，炼蜜丸，桐子大。每服三十丸，温酒下。 \n《圣惠》\\x搜风顺气丸\\x 治风气香港脚，凡老人小儿血热风热而大便秘结者宜服。 \n车前子（两半） 大麻仁（微炒，去壳） 郁李仁（炮，去皮） 菟丝子（酒浸煮） 牛膝（酒浸 \n一宿） 干山药（各一两） 白槟榔（一两） 枳壳（麸炒） 防风 独活（各八钱） 大黄（五钱，半生半熟） \n炼蜜丸，小豆大。茶酒汤任下，早晚各一服。 \n\\x地髓汤\\x 治死血作淋，痛不可忍，及五淋小便不通，茎中痛甚欲死。一名牛膝膏，又名苦杖散。 \n牛膝（不拘多少） \n或用一两捶碎。以水二钟，煎浓汁一钟，去渣，日三服。又法入麝香少许，空心服。或 \n单以酒煎亦可。 \n\\x牛膝膏\\x 治死血作淋。 \n桃仁（去皮尖） 归尾（酒洗，各一两） 生地黄（酒洗） 赤芍药（各两半） 川芎（五钱） 牛膝（ \n去芦，四两，酒浸一宿） \n上 咀。用好水十钟，炭火慢煎至二钟，入麝香少许，分四次空心服。如夏月， \n须用冷水换浸之，则不坏。 \n《经验》\\x琥珀散\\x 治老人虚人小便不通，淋涩。 \n琥珀（为末） 人参（煎汤） \n空心，以人参汤调服琥珀末一钱。 \n\\x导赤散\\x 方在寒阵。利小肠热涩。 \n万全\\x木通汤\\x 治小便难而黄。 \n木通 赤茯苓 车前叶 滑石（各二钱） 瞿麦（一钱） \n水一钟半，煎七分，食前服。 \n\\x葱白汤\\x 治小便卒暴不通，小腹胀急，气上冲心，闷绝欲死。此由暴气乘膀胱，或因惊 \n忧气无所伸，冲逆胞系，郁闭不流。 \n陈皮（三两） 葵子（一两） 葱白（三茎） \n上 咀。用水五升，煮取二升，分三服。一云每服五钱，葱白三茎，水煎服。 \n（东垣）\\x清肺饮子\\x 治渴而小便不利，邪热在上焦气分也。"}, {"n": 34, "text": "卷三十四\n\n茯苓 猪苓 泽泻（各一钱半） 车前子 琥珀 木通 瞿麦 蓄（各一钱） 通草 \n灯心（各五分） \n水二钟，煎一钟，食远服。 \n\\x半夏丸\\x 治湿痰流注、白浊，神效。 \n半夏（制） 猪苓（等分） \n上为末，神曲糊丸服。按∶此方与《本事》猪苓丸同意，详固阵。 \n《良方》\\x醍醐膏\\x 治消渴。 \n白砂蜜（五斤） 砂仁（为末，半两） 乌梅（一斤，捶碎。用水四大碗，煎一碗，去渣） \n上入砂锅，慢火熬赤色成膏，取下放冷，加白檀细末三钱，麝香一字，搅匀，以瓷器收 \n贮密封。冬月沸汤调服，夏月凉水亦可。 \n\\x无择养荣汤\\x 治五疸虚弱，脚软心悸，口淡耳鸣，微发寒热，气急，小便白浊，当作虚劳治之。 \n人参 黄 白术 当归 甘草（炙） 桂心 陈皮（各一两） 白芍药（三两） 生地黄 茯苓 \n（各五钱） 五味子 远志（各三钱） \n上咀。每服一两，水一钟半，姜三片，枣三枚，煎七分，食前服。 \n《纲目》\\x绿矾丸\\x 治黄胖。 \n绿矾（六两，以米醋于铁杓内炒七次，干为度，放地上出火气） 南星（炒黄色） 神曲（一两， \n炒黄色） 大皂角（一斤，铁锅水煮烂，揉出声，胶净汁入锅，入枣肉再熬成胶和药） 红枣 \n（六两，蒸，去皮核，入皂角汁纳熬胶） \n上前三味为细末，以皂角枣胶捣丸，桐子大。每服五丸，清晨下床时用姜汤下，夜卧上 \n床时再服五丸。忌油腻煎炒。如身上发红斑，急煎枣汤解之自愈。 \n《简易》\\x济众方\\x 治心气不宁，怔忡惊悸，清上膈风热痰饮。 \n白石英 朱砂（等分） \n上为细末。每服五分，金银汤调下。 \n\\x抱胆丸\\x 治男妇一切癫痫风狂，或因惊恐畏怖所致，及妇人产后惊气入心，并室女经脉 \n通时惊邪蕴结，气实上盛者，累效。 \n水银（二两） 黑铅（一两半） 朱砂（细研） 乳香（细研，各一两） \n上将黑铅入铫子内溶化，下水银结成砂子，次下朱砂、乳香，乘热用柳木槌研匀，丸鸡 \n豆子大。每服一丸，空心井花水吞下。病者得睡，切莫惊动，觉来即安，再一丸可除根。 \n\\x灵苑辰砂散\\x 治风痰诸痫，狂言妄走，精神恍惚，思虑迷乱，乍歌乍哭，饮食失常 \n，疾发仆地，吐沫戴眼，魂魄不守。 \n辰砂（光明佳者，二两） 枣仁（微炒） 乳香（明者，各半两） \n上为细末。先令病患随量恣饮沉醉，但勿令吐，居静室中，将前药都作一服，用温酒一 \n钟调匀，令顿饮之。如量浅者，但随量取醉。服药讫，便令安卧，病浅者半日至一日，病深 \n者卧三两日，只令家人潜伺之，察其鼻息匀调，切勿唤觉，亦不可惊触使觉，必待其自醒， \n即神魂定矣。万一惊寤，则不可复治。吴正肃公少时心病，服此一剂，五日方寤，遂瘥。 \n\\x归神丹\\x 治五痫诸风，痰壅惊悸，神不守舍。 \n人参 当归 枣仁 白茯苓（各二两） 朱砂（大块者） 琥珀 远志（姜汤制） 龙齿（各一两） \n金箔 银箔（各二十片） \n上为末，酒糊丸，桐子大。每服三、五十丸，麦门冬汤下。 \n《得效》\\x宁志丸\\x 治心风癫痫，服此一料，其病顿减。 \n朱砂（佳者，一两） 人参 白茯苓 当归 石菖蒲 乳香（另研） 枣仁（浸去皮，取仁炒 \n香熟，各五钱） \n上将朱砂用熟绢一小片包裹线扎，以 猪心一枚，竹刀切开，纸拭去血，入朱砂 \n包定，再用线缚外，以竹箬重裹，麻皮扎紧，用无灰酒二升同入砂罐煮，酒尽，取出朱砂另 \n研；将猪心用竹刀细切，砂盆内研烂，拌入药末，再加煮熟净枣肉四两捣，桐子大，留少朱 \n砂为衣。每服五、七十丸，人参汤下。 \n\\x人参琥珀丸\\x 治癫痫。 \n人参 琥珀（另研） 茯神 白茯苓 石菖蒲（小者） 远志（酒浸，各半两） 乳香（另研） \n朱砂（水飞） 枣仁（温酒浸半日，去壳，纸上炒香，各二钱半） \n上为末，炼蜜丸，桐子大。每服三、五十丸，食后温酒送下，日再服。如不能饮者，枣 \n汤下。此可常服。 \n《集验》\\x秘方半夏丸\\x 治心风癫狂。张德明传，其内人失心狂数年，服此药而愈，后再 \n作，服人参琥珀丸而安。 \n半夏（一两，用生姜汁煮三、五十沸，取出切作块，更煮令熟，焙干为末） 麝香（一钱，研） \n水银（半两） 生薄荷（一大握，用水银研如泥） \n上药同薄荷泥更研千百下，丸如芥子。每服十五丸，金银汤临卧服，三日再服。 \n\\x神应丹\\x 治诸痫。 \n辰砂（佳者，不拘多少） \n上研细，猪心血和匀，以蒸饼裹剂蒸熟，就热取出，丸桐子大。每服一丸，人参汤下， \n食后临卧服。 \n（杨氏）\\x五痫神应丸\\x 治癫痫潮发，不问新久。 \n白附子（炮，半两） 半夏（二两，汤洗） 南星（姜制） 乌蛇（酒浸） 白矾（生，各一两） 全蝎 \n（炒，二钱） 蜈蚣（半条） 白僵蚕（炒，一两半） 麝香（三字，研） 皂角（二两，捶碎，用水半升揉汁 \n去渣，同白矾一处熬干为度，研） 朱砂（飞，二钱半） \n上为细末，生姜汁煮面糊为丸，桐子大。每服三十丸，生姜汤食后送下。 \n《局方》\\x牛黄清心丸\\x 治心志不定，神气不宁，惊恐癫狂，语言谵妄，虚烦少睡，甚至 \n弃衣登高，逾垣上屋，或小儿风痰上壅，抽搐发热，或急惊痰盛发搐，目反口噤，烦躁等证。 \n牛黄（一两，二钱） 白术 麦门冬 枯黄芩（各两半） 人参 神曲 蒲黄（炒，各二两半） 山药 \n（七两） 炙甘草（五两） 杏仁（去皮尖，炒黄色。另研） 桔梗（各二两二钱） 大豆黄卷（微炒） 当 \n归肉桂（各一两七钱） 阿胶 白蔹（各七钱半） 白茯苓（一两二钱） 川芎 防风 麝香 冰片（各 \n五钱） 羚羊角（镑，一两） 犀角（镑，二两） 雄黄（八钱，飞） 干姜（炮，七钱） 大枣（百枚，蒸熟去 \n皮，研膏） 金箔（一千四百张，内四百为衣） \n上另研为末，炼蜜与枣杵匀，每两作十丸，用金箔为衣。每服一丸，温水化下。 \n《医统》\\x牛黄丸\\x 治癫狂风痫心风，神不守舍，时发无常，仆地吐涎，不自知觉。 \n牛黄 珍珠 麝香（各五分） 朱砂 龙齿（各另研） 犀角 琥珀（各二钱） 天门冬（去心） \n麦门冬（去心） 人参 茯苓（各四钱） 水银（五分） 防风 黄芩 知母 龙胆草 石菖蒲 白芍 \n药全蝎 甘草（各五钱） 蜂房（三钱） 金箔 银箔（各七十片） \n上为末，共和匀，炼蜜和捣千杵，丸如梧桐子大。每服十五丸，食后临卧新竹叶汤下。 \n（万氏）\\x牛黄清心丸\\x 方在小儿。治心热神昏。 \n（钱氏）\\x牛黄丸\\x 方在小儿。治小儿痰涎风痫。 \n《杂着》\\x牛黄丸\\x 方在小儿。治小儿惊痫，痰涎壅盛。 \n\\x三味牛黄丸\\x 方在小儿。治小儿惊热疳积。 \n\\x苏合香丸\\x 治中气，或卒暴气逆心痛，鬼魅恶气等证。 \n麝香 沉香 丁香 白檀香 香附 荜拨 白术 诃子（煨去皮） 朱砂（水飞） 青木香 \n乌犀角（各二两） 熏陆香 龙脑（各一两） 安息香（二两，另为末，用无灰酒一升熬膏） 苏合油 \n（二两，入安息香膏内） \n上为细末，用安息香膏并炼蜜，每两作十丸，熔黄蜡包裹为善。每用温水化服一丸。或 \n丸如桐子大，每服四、五丸。 \n\\x龙脑鸡苏丸\\x 治上焦之火，除烦解劳，安吐血衄血，清五脏虚烦，神志不定，上而酒毒 \n膈热消渴，下而血滞五淋血崩等疾。 \n麦冬（四两） 甘草（一两半） 龙脑薄荷叶（一斤） 阿胶（炒） 人参（各二两） 黄 （炙，一两） 生 \n地（六两，另为末） 木通 银柴胡（各二两，此二味用沸汤浸一日夜，绞取汁） \n上用好白蜜二斤，先煎一两沸，却入地黄末，不住手搅，徐加木通、柴胡汁，慢火熬成 \n膏，然后加前诸药末和丸，如豌豆大。每服二十丸，随证用引送下。如室女虚劳，寒热潮作 \n，用人参柴胡汤下。一方如前，有黄连一两。 \n\\x九还金液丹\\x 方在小儿。 \n治男妇小儿中风惊风，痰盛气急。 \n《良方》\\x香橘汤\\x 治七情内伤，胸膈不快，腹胁胀痛。 \n香附（炒） 半夏（制） 橘红（各三钱） 甘草（炙，一钱） \n水一钟半，生姜五片，红枣二枚，煎八分。食远服。 \n《良方》\\x分气紫苏饮\\x 治腹胁疼痛，气促喘息。 \n苏叶 桔梗（去芦） 桑白皮 草果仁 大腹皮 白茯苓 陈皮 炙甘草（各一钱半） \n水一钟半，生姜三片，入盐少许，煎八分，食前服。 \n《本事》\\x枳实散\\x 治男子两胁疼痛。 \n枳实（一两） 白芍药（炒） 雀脑芎 人参（各半两） \n上为细末。姜枣汤调服二钱，酒亦可，食前，日三服 \n《济生》\\x推气散\\x 治右胁疼痛，胀满不食。 \n片姜黄 枳壳（麸炒） 桂心（各五钱） 甘草（炙，二钱） \n上为细末。每服二钱，姜、枣汤食远调服。 \n\\x白术丸\\x 治息积病，胁下满闷，喘息不安，呼吸引痛，不可针炙，宜导引，服此药。 \n白术（炒） 枳实（麸炒） 官桂各一两半） 人参（二两） 陈皮 桔梗（醋炒） 炙甘草（各一两） \n上为细末，炼蜜丸如桐子大。每服五、七十丸，不拘时，温酒送下，日三服。 \n\n\n\n<目录>卷之五十五宇集·古方八阵\n\n<篇名>攻阵\n\n属性：（仲景）\\x大承气汤\\x 治阳明太阴伤寒，谵语，五六日不大便，腹满烦渴，并少阴舌干口燥 \n，潮热脉实者。刘河间加甘草，名三一承气汤。 \n大黄（四两） 浓朴（半斤） 枳实（五枚） 芒硝（三合） \n上以水一斗，先煮浓、枳二物取五升，去滓，纳大黄，煮取二升，去滓，纳芒硝，更上 \n微火一两沸。分温再服，得下，余勿服。 \n（仲景）\\x小承气汤\\x 治病在太阴，无表证，汗后潮热狂言，腹胀脉实，六七日不大便，喘满者。 \n即前大承汤减去芒硝。 \n（仲景）\\x调胃承气汤\\x 治太阳、阳明不恶寒，反恶热，大便秘结，日晡潮热者。凡阳明病 \n有一证在经者，当解肌；入腑者，当攻下。 \n大黄 芒硝 甘草（各五钱，此从近法） \n每服三、五钱，水一大盏，煎七分，温服。 \n（仲景）\\x桃仁承气汤\\x 治伤寒蓄血，小腹急，大便黑而不通。 \n桃仁（十二枚，去皮尖） 官桂 甘草（各一钱） 芒硝（三钱） 大黄（半两或一两，此从近法） \n上 咀，作一服或分二服。水一大盏，煎七分，温服。 \n《良方》\\x桃仁承气汤\\x 治瘀血小腹作痛，大便不利，或谵语口干，漱水不咽，遍身黄色 \n，小便自利，或血结胸中硬满，心下手不可近，或寒热昏迷，其人如狂。 \n桃仁（半两，去皮尖） 大黄（炒，一两） 甘草（二钱） 肉桂（一钱） \n上姜、水煎，发日五更服。 \n\\x当归承气汤\\x 治燥热里热，火郁为病，或皮肤枯燥，或咽干鼻干，或便溺结 ，通宜此方。 \n当归 大黄（各四钱） 甘草 芒硝（各二钱） \n上 咀。入姜煎服。 \n（仲景）\\x大柴胡汤\\x 表证未除，里证又急，汗下兼行用此。 \n柴胡（半斤） 半夏（半升） 黄芩 芍药（各三两） 生姜（五两，切） 枳实（四枚） 大黄（二两） 大枣 \n（十二枚，擘） \n上七味，以水一斗二升，煮取六升，去滓再煎。温服一升，日三服。 \n（陶氏）\\x六一顺气汤\\x 以代大小承气、大柴胡、大陷胸等汤之神药也。此汤治伤寒热邪传 \n里，大便结实，口燥咽干，怕热谵语，揭衣狂走，斑黄阳厥，潮热自汗，胸胁满硬，脐腹疼 \n痛等证，效不尽述。 \n大黄 枳实 黄芩 浓朴 柴胡 甘草 芍药 芒硝 \n水煎服。欲峻者，大黄后入。凡伤寒过经，及老弱或血气两虚之人，或妇人产后，有下 \n证，或有下后不解，或表证尚未除而里证又急，不得不下者，用此汤去芒硝下之则吉。盖恐 \n硝性峻急，故有此戒。经云∶转药孰紧？有芒硝者紧也。今之庸医，不分当急下、可少与、 \n宜微和胃气之论，一概用大黄、芒硝乱投汤剂下之，因兹枉死者多矣。仲景云∶荡涤伤寒热 \n积皆用汤液，切禁丸药，不可不知也。 \n（仲景）\\x大陷胸汤\\x 治大结胸手不可按。 \n大黄（四钱） 芒硝（三钱） 甘遂末（二分，此从近数） \n用水一钟半，先煎大黄至一钟，纳芒硝，煎一二沸去 ，纳甘遂末和匀服，得利则 \n止。此药极峻，必不得已而用之。原方用大黄六两、芒硝一升、甘遂末一钱，水六升，如 \n前法煮二升，分二服。得快利，止后服。 \n\\x小陷胸汤\\x 方在寒阵。 \n治小结胸，正在心下，按之则痛，脉浮滑者。 \n（河间）\\x大黄汤\\x 治泻痢湿热邪盛，脓血稠粘，里急后重，日夜无度者。 \n大黄（一两） \n上细锉，好酒二大盏浸半日。煎至一盏半，去大黄，分二服，顿服之。痢止，一 \n服；如未止，再服，以利为度，服芍药汤以和之。痢止，再服黄芩汤和之，以撤其毒。 \n《外科》\\x大黄汤\\x 方在外科。 \n治肠痈小腹坚肿。 \n《金匮》\\x大黄甘草汤\\x 治食已即吐。按此汤必下焦胀实，大便秘结不通，而格拒吐食者 \n方可用之。若因胃虚而食已即吐者，此则大非所宜，用者不可误认。 \n大黄（四两） 甘草（一两） \n上二味，以水三升，煮取一升，分温再服。 \n《金匮》\\x大黄硝石汤\\x 治黄胆腹满，小便不利而赤，自汗出，表和里实者宜用之。 \n大黄 黄柏 硝石（各四两） 栀子（十五枚） \n上四味，以水六升，煮取二升，去滓，纳硝，更煮取一升，顿服。 \n《金匮》\\x栀子大黄汤\\x 治酒疸心中懊 ，或热痛。 \n栀子（十四枚） 大黄（一两） 枳实（五枚） 豉（一升） \n上用水六升，煮取二升，分温三服。 \n（河间）\\x防风通圣散\\x 治诸风潮搐，手足螈 ，小儿急惊便结，邪热暴甚，肌肉蠕动，一 \n切风热疥痢等疾。 \n防风 川芎 当归 芍药 麻黄 连翘 蒲荷叶 大黄 芒硝（各五钱） 石膏 黄芩 桔 \n梗（各一两） 滑石（三两） 甘草（二两） 荆芥 白术 栀子（各二钱半） \n上为末。每服二钱，水一大钟，生姜三片，煎六、七分，温服。《医统》方各五分，用 \n水二钟煎服。痰嗽加半夏；闭结加大黄二钱；破伤风加羌活、全蝎各五分。此方有四∶贾同 \n知方无芒硝；崔宣武方无芒硝，有缩砂；《疠疡机要》有白芷、蒺藜、鼠粘子、甘草。 \n\\x双解散\\x 方在痘疹。治痘疹表里俱实。 \n\\x牛黄双解散\\x 方在外科。治便痈热毒，大小便秘。 \n《局方》\\x凉膈散\\x 泻三焦六经诸火。 \n大黄 朴硝 甘草（各一钱） 连翘（一钱半） 栀子 黄芩 蒲荷（各五分） \n水一钟半，加竹叶七片，煎八分，入蜜一匙，和匀服。 \n（东垣）\\x凉膈散\\x 方在痘疹。 \n解痘疹内热良方。 \n（陶氏）\\x黄龙汤\\x 治热邪传里，胃有燥粪结实，心下硬痛而下利纯清水，身热谵语发渴。 \n此非内寒而利，乃因汤药而利也，名曰积热利证，宜急下之。身有热者，宜用此汤；身无热 \n者，宜六一顺气汤。医家有不识此证者，便呼为漏底伤寒，即用热药止之者，是犹抱薪救火 \n也，误人多矣。 \n大黄 芒硝（老弱者去此） 浓朴 甘草 人参 当归 \n水一钟半，生姜三片，枣二枚，煎服。 \n《良方》\\x黄龙汤\\x 方在妇人。治妊妇感冒风寒，热入胞宫，寒热如疟。 \n（钱氏）\\x黄龙汤\\x 方在小儿。治小儿感冒发热，或寒热往来。 \n（子和）\\x玉烛散\\x 治血虚有滞，或妇人经候不通，腹胀作痛。此四物汤对调胃承气汤也。 \n当归 川芎 芍药 地黄 大黄 芒硝 甘草（各等分） \n上 咀。水煎服。甚者倍用大黄。 \n\\x四顺清凉饮子\\x 治大人小儿血脉壅实，脏腑生热，面赤烦渴，睡卧不宁，大便秘结。 \n大黄 当归 芍药 甘草（各等分） \n上 咀。水煎服。 \n《元戎》\\x四物汤\\x 治脏结秘涩。 \n当归 熟地黄 川芎 白芍药 大黄（煨） 桃仁（各等分） \n上用水煎，或丸服亦可。 \n（仲景）\\x抵当汤\\x 治伤寒热在下焦，少腹硬满，其人发狂，小便自利，下血乃愈，以 \n太阳病瘀热在里也。 \n水蛭（三十条，熬） 虻虫（三十个，熬，去翅尾） 桃仁（二十个，去皮尖） 大黄（三两，酒浸） \n上四味为末。以水五升，煮取三升。又，抵当丸，亦即此四味。 \n（仲景）\\x十枣汤\\x 治悬饮内痛。 \n芫花（醋拌经宿，炒微黑勿焦） 大戟（长流水煮半时，晒干） 甘遂（面裹煨，各等分） \n上为细末。先以水一钟半，煮大枣十枚至八分，去枣纳药末，强人一钱，弱人五分，平 \n旦服之，不下更加五分，快下，徐以糜粥补之。 \n（洁古）\\x三化汤\\x 治中风外有六经之形证，先以续命汤主之；内有便溺之阻格，此方主之。 \n浓朴（姜制） 大黄 枳实 羌活（各等分） \n上 咀。每服一两，水煎服。微利则止。 \n《选要》\\x透膈汤\\x 治脾胃不和，中脘气滞，胸膈满闷，噎塞不通，胁肋胀痛，痰涎呕逆，饮食不下。 \n木香 白豆蔻 砂仁 槟榔 枳壳（麸炒） 浓朴（姜汁炒） 半夏（制） 青皮 橘红 甘 \n草大黄 朴硝（各一钱） \n水一钟半，姜三片，红枣一枚，煎八分，食远服。 \n《金匮》\\x因陈蒿汤\\x 治伤寒发黄，及谷疸。发热不食，大小便秘，或食即头眩，是为谷疸。 \n茵陈（九钱） 大黄（四钱半） 山栀（一钱半） \n上作二服，每服水二钟，煎八分，食远温服。 \n《河间》\\x芍药汤\\x 下血调气。经曰∶溲而便脓血，气行而血止，行血则便自愈，调气则后重除。 \n芍药（一两） 当归 黄连（各五钱） 木香 甘草（炙） 槟榔（各二钱） 大黄（三钱） 官桂（一钱半） \n黄芩（五钱） \n上咀。每服半两，水二钟，煎一盏，食后温服。如血痢，则渐加大黄；如汗后脏毒，加 \n黄柏半两，根据前服。 \n愚按∶此汤乃河间之心方，然惟真有实热者可用，若假热假实者，误服则死。 \n\\x枳实大黄汤\\x 治湿滞香港脚。 \n羌活（钱半） 当归（一钱） 枳实（五分） 大黄（酒煨，三钱） \n水一钟半，煎八分，食前空心温服，以利为度。 \n\\x羌活导滞汤\\x 治风湿实滞香港脚。 \n羌活 独活（各半两） 防己 当归（各三钱） 枳实（麸炒，二钱） 大黄（酒煨，一两） \n上每服五、七钱，水一钟半，煎至七分，温服，量虚实加减，微利则已。 \n\\x牛黄泻心汤\\x 治心经实热，狂言妄语，神志不安。 \n牛黄（另研，一两） 冰片（另研，一分） 朱砂（另研，二钱） 大黄（生，一两） \n上为细末，和匀。每服一、二钱，冷姜汤或蜜水调下。 \n《宣明》\\x三棱散\\x 治积聚、 瘕， 癖不散，坚满痞闷，食不下。 \n三棱 白术（炒，各二两） 蓬术 当归（各五钱） 木香 槟榔（各三钱） \n上为末。每服三钱，沸汤调下。 \n\\x三棱丸\\x 治血 血瘕，食积痰滞。 \n莪术（醋浸炒） 三棱（各三两） 青皮 麦芽（炒） 半夏（各一两） \n上共享好醋一钟，煮干焙为末，醋糊丸，桐子大。每服四十丸，淡醋汤下。痰积，姜汤下。 \n\\x三圣膏\\x 贴积聚 块。 \n锻石（十两） 官桂（半两，为末） 大黄（一两，绵纹者，为末） \n上将锻石细筛过，炒红，急用好醋熬成膏，入大黄、官桂末搅匀，以瓷器收贮，用泊纸或 \n柿漆纸摊贴患处，火烘熨之。 \n《良方》\\x桃仁煎\\x 治血瘕。 \n桃仁 大黄（炒，各一两） 虻虫（半两，炒黑） 朴硝（一两） \n上为末，以醇醋一钟，瓷器中煮三分，下前三味，不住手搅，煎至可丸，乃下朴硝，丸 \n如桐子大。不吃晚食，五更初温酒下五丸，日午下秽物，如未见，再服。仍以调气血药补之 \n。立齐曰∶向在毗陵，一妇人小便不通，脐腹胀甚。予诊之曰∶此血瘕也。用前药一服，腹 \n痛，下瘀血血水即愈。此药猛烈大峻，气血虚者，斟酌与之。 \n\\x穿山甲散\\x 治 痞瘀血，心腹作痛。 \n穿山甲（炒焦） 鳖甲（醋炙） 赤芍药 大黄（炒） 干漆（炒烟尽） 桂心（各一两） 川芎 \n芫花（醋炒） 归尾（各半两） 麝香（一钱） \n上为末。每服一钱，酒调下。 \n（子和）\\x禹功散\\x 泻水之剂。 \n黑丑（头末，四两） 茴香（一两，炒） 或加木香（一两） \n上为细末。以生姜自然汁调一、二钱，临卧服。 \n（子和）\\x浚川散\\x 治一切痰饮，十种水气。 \n甘遂（面裹煨） 芒硝（各二钱） 郁李仁（一钱） 大黄 牵牛末（各三钱） \n上为末，滴水丸，桐子大。每服五十丸，温水下。 \n\\x稀涎散\\x 吐顽痰。 \n牙皂（炙，去皮弦，一钱） 藜芦（五分） \n上为细末。每服五分或一、二钱，浆水调下。牙关不开者灌之。 \n\\x大异香散\\x 治积聚胀满。 \n三棱 蓬术 青皮 陈皮 枳壳（炒） 藿香 香附 半夏曲 桔梗 益智（各一钱半） 炙 \n甘草（五分） \n上分二帖，水二钟，姜三片，枣一枚，煎七分。食远服。 \n《经验》\\x流金膏\\x 治一切火痰咳逆等证。 \n白石膏（微 研细） 大黄（锦纹者，捶碎，酒浸半日，蒸晒九次，各二两） 黄芩（酒洗） \n橘红（各两半） 连翘 川芎 桔梗 贝母（各一两） 胆星 苏州薄荷 香附（各五钱） \n上为极细末，炼蜜丸，弹子大。午后临卧细嚼一丸。忌酒面诸湿热物。按此方当去川芎 \n、桔梗，效必更速。 \n（子和）\\x通经散\\x 治妇人气逆血闭。 \n陈皮（去白） 当归（各一两） 甘遂（以面包勿令透水，煮百余滚，取出用冷水浸过，去面 \n焙干，一两） \n上为细末。每服三钱，温汤调下，临卧服。 \n《外台》\\x苦楝汤\\x 治蛔虫。 \n苦楝根东引不出土者，刮去皮土，取内白皮二两，水三碗，煎一碗半，去 ，以晚 \n米三合煮糜粥。空心先以炙肉一片嚼之，引虫向上，次吃药粥一、二口，少顷又吃，渐渐加 \n至一碗，其虫下尽而愈。 \n《宣明》\\x三花神佑丸\\x 治一切沉积痰饮，变生诸病，或气血壅滞，湿热郁结，走注疼痛 \n，风痰胀满等证。子和神佑丸用黑丑一两，无轻粉。 \n黑丑（取头落末，二两） 大黄（一两） 芫花（醋浸炒） 大戟（醋浸炒） 甘遂（面裹煨，各五钱） \n轻粉（一钱） \n上为细末，滴水为丸，小豆大。初服五丸，每服加五丸，温水下，日三服，以快利为度 \n。欲速下者，宜八、九十丸或百余丸。凡痞满甚者，以痰涎壅盛，顿攻不开，则转加痛闷， \n须渐进之，初服止三丸，每加二丸，至快利即止。 \n\\x木香槟榔丸\\x 杀下诸虫。 \n槟榔（一两） 木香 鹤虱 贯众 锡灰 干漆（烧烟尽） 使君子（各五钱） 轻粉（一钱） 雷丸 \n巴豆仁（各二钱半） \n面糊丸，麻子大。每服二十丸，五更粥饮下，或煎菖蒲石榴汤下。 \n《宝鉴》\\x木香槟榔丸\\x 治一切气滞，心腹痞满，胁肋胀闷，大小便涩秘不通。 \n木香 槟榔 青皮（去瓤） 陈皮（去白） 枳壳（麸炒） 蓬术（煨切） 黄连（各一两） 黄柏 \n（去皮） 香附（炒） 大黄（炒，各三两） 黑丑（取头落末，四两） \n滴水为丸，豌豆大。每服三、五十丸，食远姜汤送下，以微利为度。 \n\\x遇仙丹\\x 追虫逐积，消 利痰，万病可除。 \n黑丑（头末） 槟榔（各一斤） 大黄（半斤） 三棱 莪术（醋炙，各四两） 木香（二两） \n上为末，用大皂角去子打碎，煎浓汤去滓，煮面糊为丸，桐子大。每服四、五十丸，以 \n强弱为加减，五更茶清下，如未通，再饮温茶助之。下虫积恶物尽了，白粥补之。 \n\\x备急丸\\x 治胃中停滞寒冷之物，心腹作痛如锥，及胀满下气，并卒暴百病，中恶客忤， \n口噤卒死皆治之。易老名独行丸。《脾胃论》名备急大黄丸。 \n巴霜 大黄 干姜（俱为末） \n上等分，和匀炼蜜丸，石臼内杵千余下如泥，丸如小豆大。夜卧时温水下一丸，气实者 \n加一、二丸，如卒病，不计时候服。如卒死口噤，即斡口折齿灌之。司空裴秀亦作散用，用 \n其急也。孕妇忌用。 \n《和剂》\\x神保丸\\x 治心膈痛，腹痛，血痛，肾气胁下痛，大便不通，气噎，宿食不消。 \n木香 胡椒（各二钱半） 干蝎（七枚） 巴豆（十粒，去皮心研） \n上为末，汤浸蒸饼丸，麻子大，朱砂三钱为衣。每服五丸，用柿蒂汤，或姜、醋、茶、 \n蜜、茴香、木香等汤，随宜送下。 \n《宝藏》\\x感应丸\\x 治宿食积滞腹痛，胸膈痞闷，疼痛吐泻。 \n南木香 肉豆蔻 丁香（各两半） 干姜（炮，一两） 巴霜（七十粒） 百草霜（二两） 杏仁（一百四 \n十粒，去皮尖，研） \n上先将前四味为末，后入三味同研匀，外用好黄蜡六两溶化，以绢滤净，更用好酒一升 \n，于银、石器内煮蜡数沸，倾出，其蜡自浮，听用。凡春夏修合，先用香油一两，铫内熬令 \n香熟，次下酒蜡四两，同化成汁，就铫内乘热拌和前药成剂，分作小锭，油纸裹放，旋丸服 \n之。若秋冬须用香油一两五钱。每服三十丸，空心姜汤下。 \n\\x大金花丸\\x 治中外诸热，淋秘溺血，嗽血，衄血，头痛骨蒸，咳嗽肺痿。 \n黄连 黄芩 黄柏 栀子 大黄（各等分） \n上为细末，滴水丸，小豆大。每服三十丸，凉水、茶清任下。本方去大黄，倍加栀子， \n名栀子金花丸。 \n《千金》\\x大硝石丸\\x 治痞积。 \n硝石（六两） 大黄（八两，另研） 人参 甘草（各三两） \n上为细末，用好陈醋三升，以瓷器微火熬丸。每入醋一升，先入大黄，不住手搅使微沸 \n，尽一刻又入一升，再熬微干，又下一升，并下余药再熬，使可丸，如鸡子黄大，每服一丸 \n，白汤化下；或丸如桐子大，每服三、五十丸。服后当下如鸡肝，或如米泔赤黑色等物乃效 \n。下后忌风冷，宜软粥将息。 \n（东垣）\\x枳实导滞丸\\x 治伤湿热之物，不得旋化而作痞满，闷乱不安。 \n黄芩 茯苓 白术 黄连（各三钱） 枳实（热炒） 神曲（各五钱，炒） 泽泻（二钱） 大黄（煨，一两） \n上为末，汤浸蒸饼为丸。食远白汤下五十丸。 \n《秘方》\\x化滞丸\\x 理诸气，化诸积。夺造化，有通塞之功；调阴阳，有补泻之妙。久坚 \n沉痼者，磨之自消；暴滞积留者，导之自去。此与邓山房感应丸略同，但彼方犹有沉香、檀 \n香、砂仁、香附四味。 \n南木香 丁香 青皮 橘红 黄连（各二钱半） 莪术（煨） 三棱（各五钱） 半夏曲（三钱） \n上八味，共为细末。 \n巴豆（去壳，滚汤泡去心膜，用好醋浸少顷，慢火熬至醋干，用六钱研细，入前药，又 \n研匀，再入后乌梅膏。巴豆若干，止用梅四钱五分） 乌梅肉（焙干为末，用五钱，以米醋调 \n略清，慢火熬成膏，和入前药） \n上和匀，用白面八钱调浓糊丸，萝卜子大。每服五、七丸，壮人十丸，五更空心用陈皮 \n汤下。不欲通者，以津下。知所积物，取本汁冷下。停食饱闷，枳壳汤下。因食，吐不止， \n以津咽下即止。妇人血气痛，当归汤下。赤痢，冷甘草汤下。白痢，冷干姜汤下。心痛，石 \n菖蒲汤下。诸气痛，生姜陈皮汤下。肠气，茴香酒下。若欲推荡积滞，热姜汤下，仍加数丸 \n；未利，再服。利多不止，饮冷水一、二口即止。此药得热即行。得冷即止。小儿疳积，量 \n大小饮汤下。妊娠勿服。 \n\\x化铁丹歌\\x \n八梅十六豆，一豆管三椒；青陈各半两，丁木不相饶。 \n将来研作末，醋打面糊调；丸如黍米大，日晒要坚牢。 \n五分或三分，强弱或儿曹。任意作引下，是铁也能消。 \n\\x陈米三棱丸\\x 消积聚，去米面五谷等积。 \n陈仓米（一两，用新巴豆五枚去壳，同米慢火炒，巴豆焦色，去豆不用） 陈皮 三棱（煨） \n砂仁 麦芽（各二钱） 南香木（一钱） \n上为末，醋糊丸，绿豆大。每服十五丸至二十丸，食远姜汤下。 \n《局方》\\x温白丸\\x 治心腹积聚， 癖痞块，大如杯碗，胸胁胀满，呕吐，心下坚结 \n，旁攻两胁，如有所碍，及一切诸风，身体顽麻，三十六种遁尸注忤，十种水病，痞塞心痛 \n，腹中一切诸疾，但服此药，无不除愈。 \n川乌（制，二两） 皂角（炙，去皮弦） 吴茱萸（汤泡一宿，炒） 石菖蒲 柴胡 桔梗（去 \n芦，炒） 浓朴（姜制） 紫菀 人参 黄连（去须） 茯苓 干姜（炮姜） 肉桂 川椒（去目， \n炒） 巴霜（各五钱，另研） \n上为末，入巴豆研匀，蜜丸，桐子大。每服三丸。姜汤下。按∶此方与海藏万病紫菀丸 \n大同，但彼多羌活、独活、防风三味，止用巴霜二钱，而群药更倍，随证用引送下，与此为稍异也。 \n洁古治法∶肝积肥气，温白丸加柴胡、川芎；心积伏梁，温白丸加菖蒲、黄连、桃仁， \n脾积痞气，温白丸加吴茱萸、干姜。肺积息奔，温白丸加人参、紫菀；肾积奔豚，温白丸加 \n丁香、茯苓、远志。 \n（陈氏）\\x温白丸\\x 方在小儿。 \n驱风豁痰定惊。 \n（丹溪）\\x阿魏丸\\x 治内积。 \n阿魏（醋煮作糊） 糖球子（各一两） 黄连（六钱） 连翘（五钱） \n上为末，阿魏糊丸，桐子大。每服二、三十丸，白汤送下。 \n《医林》\\x阿魏丸\\x 治诸般积聚， 瘕痞块。 \n山楂肉 南星（皂角水浸） 半夏 麦芽（炒） 神曲（炒） 黄连（各一两） 连翘 阿魏（醋 \n浸） 栝蒌仁 贝母（各五钱） 风化硝 石咸 萝卜子（炒） 胡黄连（各二钱半） \n上为末，姜汤浸蒸饼为丸，桐子大。每服五十丸，食远姜汤下。 \n\\x守病丸\\x \n此药名为守病，朱砂加上雄黄，硼砂轻粉要相当，去皮巴霜半两。 \n砂合济有功，乳香五钱随良。蜜丸一粒放毫光，取下多年积胀。 \n《简易》\\x胜红丸\\x 治脾积气滞，胸膈满闷，气促不安，呕吐清水，丈夫酒积，妇人脾血 \n积，小儿食积并治。 \n三棱 蓬术（各醋煮） 青皮 陈皮 干姜 良姜（各一两） 香附（二两，炒） \n上为末，醋糊丸，桐子大。每服三、四十丸，姜汤下。 \n《御院》\\x助气丸\\x 治三焦痞塞，胸膈饱闷，气不流通，蕴结成积， 癖气块，并皆治之。 \n三棱（炮） 莪术（炮，各一两） 青皮 橘红 白术（各五钱） 木香 槟榔 枳壳（各三钱） \n上为末，糊丸桐子大。每服五十丸，米汤下。 \n《局方》\\x三黄丸\\x 治三焦积热，咽喉肿闭，心膈烦躁，小便赤涩，大便秘结。 \n黄芩 黄连 大黄（各等分） \n炼蜜丸，桐子大。每服四、五十丸，白汤送下，或淡盐汤亦可。此方为汤，即名泻心汤。 \n（东垣）\\x雄黄圣饼子\\x 治一切酒食伤脾，积聚满闷等证。 \n巴豆（百枚，去膜油） 雄黄（半两） 白面（十两，炒，罗过） \n上二味为细末，同面和匀，用新汲水搅和作饼如手大，以水煮之，候浮于汤上，看硬软 \n捏作小饼子。每服五、七饼，加至十饼、十五饼，嚼食一饼利一行，二饼利二行。食前茶酒任下。 \n（河间）\\x舟车丸\\x 治一切水湿蛊腹，痰饮癖积，气血壅满，不得宣通，风热郁痹，走注疼 \n痛，及妇人血逆气滞等证。 \n黑丑（头末，四两） 甘遂（面裹煨） 芫花 大戟（但醋炒，各一两） 大黄（二两） 青皮 陈皮 \n木香 槟榔（各五钱） 轻粉（一钱） 取虫加芜荑半两。 \n上为末，水糊丸，如小豆大。空心温水下，初服五丸，日三服，以快利为度。服法如前三花神佑丸。 \n（子和）\\x导水丸\\x \n大黄 黄芩（各二两） 滑石 黑丑（头末，各四两） \n加法∶甘遂一两，去湿热腰痛，泄水湿肿满，久病则加；白芥子一两，去遍身走注疼痛 \n宜加；朴硝一两，退热散肿毒止痛，久毒宜加；郁李仁一两，散结滞，通关节，润肠胃，行 \n滞气，通血脉宜加；樟柳根一两，去腰腿沉重宜加。 \n上为细末，滴水丸，桐子大。每服五十丸，或加至百丸，临卧温水下。 \n（子和）\\x神芎丸\\x 治心经积热，风痰壅滞，头目赤肿，疮疖咽痛，胸膈不利，大小便秘， \n一切风热等证。 \n大黄（生） 黄芩（各二两） 黑丑（头末，生） 滑石（各四两） 黄连 川芎 薄荷叶（各半两） \n滴水丸，桐子大。每服五十丸，食后温水下。《局方》无黄连。 \n《三因》\\x小胃丹\\x 上可去胸膈之痰，下可利肠胃之痰。 \n芫花 大戟（俱醋炒） 甘遂（面裹煨，各一两） 大黄（酒拌蒸，一两半） 黄柏（炒褐色，二两） \n上为细末，粥丸，麻子大。每服十丸，温水下。 \n\\x清气化痰丸\\x \n南星 半夏（各八两，用皂角、白矾、生姜各三两，水十碗煮至五碗，取汤浸星、夏二日 \n，却煮至无白点为度，晒干听用） 橘红 槟榔（各二两） 木香 沉香（各一两） 苍术（米泔浸炒，四两） \n上为末，姜汁糊丸。淡盐汤、白汤任下。 \n（丹溪）\\x清气化痰丸\\x 治上焦痰火壅盛，咳嗽烦热口渴，胸中痞满。 \n南星（制，三两） 半夏（制） 黄连 黄芩（各五两） 栝蒌仁 杏仁（去皮尖） 茯苓（各四两） \n枳实（炒） 陈皮（各六两） 甘草 \n上为细末，姜汁煮糊丸，桐子大。每服五十丸，姜汤下。 \n\\x法制清气化痰丸\\x 顺气快脾，化痰消食。 \n南星（去皮） 半夏（各四两，用皂角、白矾、干姜各四两，入水五碗，煎至三碗，去 \n，却入南星、半夏浸二日，再煮至星、夏俱无白点为度，晒干，加后药） 陈皮 青皮 \n苏子（炒） 神曲（炒） 麦芽（炒） 萝卜子（炒，另研） 杏仁（去皮尖，炒） 葛根 山楂 香附（各二两） \n上为末，汤泡蒸饼丸，桐子大。每服五、七十丸，临卧、食后茶汤下。 \n（隐君）\\x滚痰丸\\x 治一切湿热食积等痰，窠囊老痰。一方礞石止用五钱，外加百药煎五钱 \n，乃能收敛周身痰涎，聚于一处，然后利下，所以甚效。 \n礞石（硝 金色，一两） 大黄（酒蒸） 黄芩（去朽者，各半斤） 沉香（五钱） \n上为细末，滴水为丸，桐子大。每服三、五十丸，量人强弱加减。凡服滚痰丸之法，必 \n须临卧就床，用热水一口许，只送过咽，即便仰卧，令药徐徐而下；服后须多半日勿饮食起 \n坐，必使药气除逐上焦痰滞恶物，过膈入腹，然后动作，方能中病。或病甚者，须连进二、 \n三次，或壮人病实者，须多至百丸，多服无妨。 \n（子和）\\x朱砂滚涎丸\\x 治五痫。 \n朱砂 白矾（生） 硝石 赤石脂（等分） \n上为细末，研蒜膏为丸，绿豆大。每服三、五十丸，食后荆芥汤下。 \n（丹溪）\\x青礞石丸\\x 解食积，去湿痰，重在风化硝。 \n南星（二两，切片，用白矾末五钱，水浸一二日，晒干。又云一两） 半夏（一两，汤泡切片 \n，以皂角水浸一日，晒干） 黄芩（姜汁炒） 茯苓 枳实（炒，各一两） 礞石（二两，捶碎，焰硝 \n二两同入小砂罐内，瓦片盖之，铁线缚定，盐泥固济，晒干，火 红，候冷取出） 法制硝（ \n同莱菔水煮化，去卜，绵滤令结，复入腊月牛胆内风化之。或只用风化硝一两） \n上为末，神曲糊丸，桐子大。每服三、五十丸，白汤下。 \n又方∶半夏（二两） 白术 礞石（各一两） 黄芩（五钱） 茯苓 陈皮（各七钱半） 风化硝（二钱） \n上为末，丸同前。 \n（节斋）\\x化痰丸\\x 润燥开郁，降火消痰，治老痰郁痰结成粘块，凝滞喉间，肺气不清，或 \n吐咯难出。皆因火邪炎上，凝滞于心肺之分，俱宜开郁降火消痰，缓而治之，庶可效耳。 \n天门冬（去心） 黄芩（酒炒） 海粉（另研） 栝蒌仁（另研） 橘红（各一两） 连翘 香附（ \n淡盐水浸炒） 桔梗（各五钱） 青黛（另研） 芒硝（另研，各三钱） \n上为细末，炼蜜入姜汁少许捣丸，龙眼大。噙嚼一丸，清汤送下，或丸如绿豆大，淡姜 \n汤送下五六十丸。此等老痰，大约饮酒人多有之，酒气上蒸，肺与胃脘皆受火邪，故结而成 \n痰。此方天冬、黄芩泻肺火，海石、芒硝咸以软坚，栝蒌润肺消痰，香附、连翘开郁降火， \n青黛去郁火，故不用辛燥等药。 \n《医林》\\x辰砂化痰丸\\x 治风化痰，安神定志，止嗽除坚。 \n辰砂（另研） 明矾（另研，各五钱） 南星（制，一两） 半夏曲（三两） \n上为细末，姜汁糊丸，绿豆大，朱砂为衣。每服三十丸，食后姜汤下。 \n《三因》\\x控涎丹\\x 凡人忽患胸背手足腰胯疼痛，牵引钓动，时时走易不定，不可忍者， \n或手足冷痹，气脉不通，是皆痰涎在心膈上下，故为此证。 \n真白芥子 紫大戟（去皮） 甘遂（面裹煨，各等分） \n上为末，糊丸，桐子大。临卧淡姜汤或温水下五、七丸至十丸。痰甚者，量加之。 \n《医林》\\x乌巴丸\\x 治胸膈久为顽痰所害，面色青白浮肿，不思饮食，遍身疼痛，夜间气 \n壅不得睡，往来寒热，手足冷痛，不得转侧，屡用痰药坠之不下，取之不出，此是顽痰坚滞 \n，宜此药利下之则愈，未利再服。 \n乌梅肉（二两） 巴霜（五粒，去油） \n上用水二碗，砂锅内将乌梅肉煮烂，候水稍干，入巴豆，将竹片搅如稠糊，取出捣为丸 \n，桐子大。每服七丸、九丸、十丸、十一丸、或十五丸，姜汤下，不拘时。 \n《御药》\\x吐痰方\\x 治胸中有痰瘀癖者。 \n用白矾一两，水二升，煮一升，入蜜一合，更煮少时。温服。须臾即吐，如未吐，再饮 \n热水一盏，吐痰为效。 \n\\x人参利膈丸\\x 方在和阵。 \n治痰逆嗝噎圣药。 \n《和剂》\\x青木香丸\\x 治胸膈噎塞，气滞不行，肠中水声，呕哕痰逆，不思饮食，宽中和膈。 \n黑丑（炒香，取头末，十二两） 破故（炒） 荜茇（各四两） 木香（二两） 槟榔（用酸粟米饭裹 \n，湿纸包，火煨令纸焦，去饭，四两） \n上为末，滴水为丸，绿豆大。每服三、四十丸，茶汤、热水任下。 \n\\x消痞核桃\\x \n莪术（酒洗） 当归（酒洗） 白芥子 急性子（各四两，俱捣碎） 皮硝 海粉（各八两） 大核桃（百枚） \n上先以群药入砂锅内，宽水煮一二沸，后入大核桃重五钱者百枚，同煮一日夜，以重一 \n两为度，取起晾干。先用好膏药一个，掺阿魏一钱，麝香半分，量痞大小贴住，以热手磨擦 \n。每空心服前桃一个，三日后二个，以至三个。服完后，须四物汤之类，数帖即愈。 \n\\x熨痞方\\x \n一层用麝香二、三分掺肉上。二层阿魏一、二钱。三层芒硝一、二两铺盖于上。 \n上先用荞麦面和成条，量痞大小围住，铺药于内，以青布盖之，随烧热砖四、五块，轮 \n流布上熨之，觉腹中气行宽快，即是痞消之兆。以手烘热摩之亦妙。内须服调养气血之药。 \n\\x开结导饮丸\\x 方在和阵。 \n治饮食不消，心下痞闷，腿脚肿痛。 \n《局方》\\x犀角丸\\x 除三焦热邪，及痰涎壅滞，肠胃燥涩，大小便难。 \n黄连（去须） 犀角（镑，各十两） 人参（二十两） 大黄（八十两） 黑丑（炒捣，取头末，六十两） \n上为细末，炼蜜丸，梧子大。每服十五丸至二十丸，临卧汤下，更量虚实加减。 \n《河间》\\x犀角丸\\x 治癫痫发作有时，扬手掷足，口吐痰涎，不省人事，暗倒屈伸。 \n犀角末（半两） 赤石脂（三两） 朴硝（二两） 白僵蚕 薄荷（各一两） \n上为末，面糊丸，梧子大。每服二、三十丸，温水下，日三服，不拘时。如觉痰多，即 \n减其数。忌油腻炙爆。 \n\\x麻仁丸\\x 治大便秘结，胃实能食，小便热赤者。 \n芝麻（四两，研取汁） 杏仁（四两，去皮尖，研如泥） 大黄（五两） 山栀（十两） \n上为末，炼蜜入麻汁和丸，桐子大。每服五十丸，食前白汤下。 \n《局方》\\x脾约丸\\x 此即仲景麻人丸。仲景曰∶趺阳脉浮而涩，浮则胃气强，浮涩则小便 \n数，浮涩相搏，大便则难，其脾为约，麻人丸主之。亦名润肠丸。治脏腑不和，津液偏渗于 \n膀胱，以致小便利，大便秘结者。 \n大黄（蒸） 杏仁（去皮尖，炒） 浓朴 麻仁（各四两） 枳实（二两） \n炼蜜丸，桐子大。每服二十丸，白滚汤下，日三服，渐加，以和为度。 \n《局方》\\x七宣丸\\x 治风气结聚，宿食不消，心腹胀满，胸膈痞塞，风毒肿气连及头面， \n大便秘涩，小便时数，脾胃气壅，不能饮食。东垣云∶治在脉则涩，在时则秋。 \n柴胡 枳实 诃子肉 木香（各五两） 炙甘草（四两） 桃仁（炒，去皮尖，六两） 大黄（蒸，十五两） \n上为末，炼蜜丸，桐子大。每服二十丸，食远米饮下，渐加至、四五十丸，以利为度。 \n觉病退，止服。 \n《局方》\\x七圣丸\\x 治风气壅盛，痰热结搏，心烦面赤，咽干口燥，肩背拘急，胸膈胀满 \n，腹胁痞闷，腰膝沉重，大便闭结，小便赤涩。东垣曰∶治在脉则弦，在时则春。 \n木香 槟榔 川芎 肉桂 羌活（各五钱） 郁李仁（炮去皮） 大黄（半生半熟，各一两） \n上为末，炼蜜丸，小豆大。每服十五丸至二十丸，食后临卧白汤下。 \n《三因》\\x红丸子\\x 消食疟。 \n胡椒（一两） 阿魏一钱，醋化） 青皮（炒，三两） 莪术 三棱（醋煮一伏时，各二两） \n上为末，另用陈仓米末同阿魏醋煮糊丸，桐子大，炒土朱为衣。每服七十丸，姜汤下。 \n\\x追虫丸\\x 取一切虫积。 \n黑丑（头末） 槟榔（各八钱） 雷丸（醋炙） 南木香（各二钱） \n上为末，用茵陈二两，大皂角、苦楝皮各一两，煎浓汁丸，绿豆大。壮大人每服四钱， \n小人弱人或一钱五分，量人虚实，于五更时用砂糖水吞下，待追去恶毒虫积二、三次，方以粥补之。 \n《医林》\\x化虫散\\x \n雷丸（二粒） 槟榔（二枚） 鹤虱（一钱） 使君子（七枚） 轻粉（少许） \n上为末，分二服。候晚刻以精猪肉一两切成片，用皂角浆泡一宿，至五更慢火炙熟，乃 \n以香油拭肉上，候温，取前药一服擦肉上，略烘过食之。至巳时虫下了，乃进饮食。 \n\\x万应丸\\x 下诸虫。 \n槟榔（五两） 大黄（半斤） 黑丑（头末，四两） 皂角（不蛀者，十条） 苦楝根皮（一升） \n上先将苦楝皮、皂角二味，用水二大碗熬成膏子，搜和前三味为丸，桐子大，以沉香、 \n雷丸、木香各一两为衣，先用沉香衣、后用雷丸、木香衣。每服三钱，四更时用砂糖水送下。 \n\\x妙应丸\\x 一名剪红丸。杀诸虫。 \n大黄 牵牛（头末） 槟榔（各三两） 雷丸 锡灰（各五钱） 大戟（三钱） 鹤虱 使君子（煨） \n茴香 贯众（各二钱半） 轻粉（少许） 苦楝根（一两） \n上为细末，用皂角煎膏丸服。每服五、六十丸，随弱强加减，五更初茶清下。如未通， \n再吃温茶助之。下虫积尽了，白粥补之。 \n《运气》\\x五瘟丹\\x 治瘟疫火证。 \n黄芩 黄柏 黄连 山栀 香附 紫苏 甘草梢 大黄 \n上以前七味生为末，用大黄三倍煎浓汤，去滓和药，丸如鸡子大，朱砂、雄黄为衣，贴 \n以金箔。每用一丸，取泉水七碗浸化，可服七人。前药甲己年以甘草梢为君，乙庚年黄芩为 \n君，丙辛年黄柏为君，丁壬年山栀为君，戊癸年黄连为君。为君者，多一倍也。余四味同香 \n附、紫苏为臣者，减半也。 \n\\x大青丸\\x 治时行瘟病发热，上膈结热。 \n薄荷 栀子 黄芩 黄连 甘草（各三钱） 连翘（六钱） 大黄 玄明粉（各八钱） \n上为细末，以青蒿自然汁为丸，绿豆大，雄黄为衣。每服五、六十丸，白滚汤下。若治 \n杂病发热者，以朱砂或青黛为衣。 \n\\x朱砂丸\\x 治卒时中恶垂死。 \n朱砂（研） 附子（炮去皮脐） 雄黄（明者，各一两） 麝香（一分，另研） 巴豆（二十粒，去油） \n上研匀，炼蜜和捣为丸，麻子大。每服三丸，不拘时粥饮下。如不利，更加三丸至七丸 \n，以利为度。 \n\\x李氏八毒赤丸\\x 治一切邪崇鬼疰，服之即愈。 \n雄黄 朱砂 矾石 附子（炮） 藜芦 牡丹皮 巴豆（各一两） 蜈蚣（一条） \n上为末，炼蜜丸，如小豆大。每服五、七丸，凉水送下，无时。《卫生宝鉴》云∶副使 \n许可道宿驿中，夜梦一妇人于胁下打一拳，遂痛不止，而往来寒热，不能食，乃鬼击也。《 \n名医录》云李子豫八毒赤丸，名为杀鬼杖子。遂与药三粒，卧时服，明旦下清水二斗而愈。 \n又陈庆玉子，因昼卧水仙庙，梦得一饼食之而心腹痞满，病及一年，诸治不效。余诊之，问 \n其始末，因思此疾既非外感，又非内伤，惟八毒赤丸颇为相当。遂与五七丸，下清黄涎斗余 \n，渐得气调，后以别药理之，数月而愈。 \n（仲景）\\x瓜蒂散\\x 治伤寒头不痛，寸脉微浮，胸中痞硬，气上冲咽喉不息者，此为胸 \n有寒也，当吐之。 \n瓜蒂（熬黄） 赤小豆（等分） \n上二味，各别捣筛为散，然后合之。取一钱匕，以香豉一合，用热汤七合煮作稀糜，去 \n滓取汁和散，温顿服之。不吐者，少少再加，得快吐乃止。诸亡血虚家不可与瓜蒂散。 \n（子和）\\x独圣散\\x 吐积蓄痰涎。 \n甜瓜蒂（不拘多少，微炒） \n为细末。每服一、二钱，齑汁调服。膝痛加全蝎，头痛加郁金服，吐之。 \n\\x茶调散\\x 吐除痰积。 \n瓜蒂（二钱） 好茶（一钱） \n上为末。每服二钱，齑汁调服。 \n（陈氏）\\x独圣散\\x 方在外科。 \n治疮疡气血凝滞。 \n《良方》\\x独圣散\\x 方在妇人。 \n治妊娠伤触动胎，腹痛下血。 \n（钱氏）\\x独圣散\\x 方在痘疹。 \n治痘疮倒靥陷伏。 \n\\x木通散\\x 凡男子妇人胁肋苦痛。 \n木通（去节） 青皮 萝卜子（炒） 茴香 川楝子（取肉，用巴豆半两同炒黄，去巴豆，各 \n一两） 滑石（另研） 莪术 木香（各半两） \n上为细末。每服三钱，不拘时，用葱白汤调服，甚者不过三服。 \n《金匮》\\x大黄附子汤\\x 治寒气内积，胁下偏痛。 \n大黄（三两） 附子（三枚，炮） 细辛（二两） \n上三味，用水五升，煮取二升，分温三服。若强人煮取二升半，分温三服。服后如人行 \n四、五里，更进一服。 \n《金匮》\\x外台走马汤\\x 治中恶心痛，腹胀，大便不通。 \n巴豆（二枚，去皮心，熬） 杏仁（二枚） \n上二味，以绵缠令碎，热汤二合捻取白汁，饮之当下。通治飞尸鬼击病。老小量用。 \n\n\n\n<目录>卷之五十六宇集·古方八阵\n\n<篇名>散阵\n\n属性：（仲景）\\x麻黄汤\\x 治太阳经伤寒，发热无汗，恶寒及身痛。此峻逐阴邪之方也。 \n麻黄 桂枝（各三两） 甘草（一两） 杏仁（七十个） \n上四味，以水九升，先煮麻黄减二升，去沫，纳诸药，煮取三升半，去 。温服八 \n合，覆取微汗。 \n\\x麻黄加术汤\\x 治风湿。 \n即前方加白术四两。 \n（仲景）\\x麻黄附子细辛汤\\x 治少阴伤寒，始得之，脉虽沉而反发热者，此阴分之表证也， \n宜此主之。并治寒气厥逆，头痛，脉沉细者。 \n麻黄（去节） 细辛（各二两） 附子（一枚，炮去皮，切八片） \n上三味，以水一斗，先煮麻黄减二升，去上沫，纳药煮取三升，去滓，温服一升，日三服。 \n《金匮》\\x麻黄杏仁薏苡甘草汤\\x 治风湿一身尽痛，发热，日晡剧者。因汗出当风，或久伤取冷所致。 \n麻黄（去节，汤泡） 薏仁（各半两） 甘草（炙，一两） 杏仁（十个，去皮尖，炒） \n上每服四钱，水一盏半，煮八分，温服取微汗，避风。 \n（仲景）\\x麻黄附子甘草汤\\x 治少阴伤寒，二、三日，无别证，用此微发其汗，并治风湿通身浮肿。 \n麻黄（去节） 甘草（炙，各三两） 附子（一枚，炮去皮） \n上三味，以水七升，先煮麻黄一两沸，去上沫，纳诸药，煮取三升，去滓，温服一升，日三服。 \n《金匮》\\x麻黄甘草汤\\x 治腰以上水肿者，宜此汗之。 \n麻黄（半两） 甘草（二钱半） \n上咀。用水二钟，先煮麻黄三、四沸，去沫，入甘草，再煎至八分，食远热服取汗。有 \n人患气喘，积久不瘥，遂成水肿，服此效。 \n（仲景）\\x大青龙汤\\x 治伤寒头痛发热，无汗而烦躁。 \n麻黄（三钱） 桂枝 生姜（各一钱） 杏仁（五枚） 甘草（五分） 大枣（一枚，此非古数） 石膏（半鸡 \n子大一块） \n水一钟半，煎分二服。 \n（仲景）\\x小青龙汤\\x 治伤寒表不解，心下有水气，呕哕而咳，发热，或渴，或利，或小水 \n不利，小腹满而喘，并治肺经受寒，咳嗽喘急，宜服此以发散表邪。 \n麻黄（去节） 桂枝 芍药 甘草 细辛 干姜（各三两） 半夏 五味（各半升） \n上八味，以水一斗，先煮麻黄减二升，去上沫，纳诸药，煮取三升，温服一升。按∶上 \n方乃仲景古法，今当随证轻重，酌宜用之。 \n（仲景）\\x桂枝汤\\x 治太阳经伤风，发热，自汗，恶风。 \n桂枝 芍药 生姜（各三两） 甘草（二两） 大枣（十二枚） \n上以水七升，微火煮取三升，去滓，适寒温服一升。服已须臾，食热稀粥一升余以助药 \n力，温覆一时许，令遍身微似有汗者佳，不可令如水流漓，病必不除。 \n\\x桂枝加黄 汤\\x 治黄胆脉浮者，当以汗解之。 \n即前桂枝汤加黄 二两。 \n\\x桂枝加大黄汤\\x \n即前桂枝汤内加大黄一两。 \n\\x栝蒌桂枝汤\\x 治 。 \n即前桂枝汤加栝蒌根二两。 \n（仲景）\\x桂枝人参汤\\x 治太阳伤寒，表里不解，协热下利者。 \n桂枝（去皮） 炙甘草（各四两） 白术 人参 干姜（各三两） \n上五味，以水九升，先煮四味取五升，后纳桂枝，更煮取三升。温服一升，日再夜一服。 \n（仲景）\\x桂枝麻黄各半汤\\x 治太阳伤寒如疟状，发热恶寒，不能得汗，热多寒少而身痒者。 \n桂枝（去皮） 麻黄（去节） 芍药 甘草（炙） 生姜（切，各一两） 大枣（四枚，擘） 杏仁（二 \n十四个，汤浸，去皮尖） \n上七味，以水五升，先煮麻黄一、二沸，去上沫，内诸药，煮取一升八合，去滓。温服六合。 \n\\x桂枝附子汤\\x 方在热阵。治伤寒风湿身痛。 \n\\x桂枝甘草汤\\x 方在热阵。治过汗心悸。 \n\\x桂枝葛根汤\\x 方在痘疹。解散寒邪。 \n（仲景）\\x柴胡桂枝汤\\x 治伤寒发热，微恶寒，支节烦疼，微呕，心下支结，外证未去者。 \n柴胡（四两） 桂枝（去皮） 人参 黄芩 芍药 生姜（各一两半） 甘草（炙，一两） 半夏（二合 \n半） 大枣（六枚，擘） \n上九味，以水七升，煮取三升，去滓，温服。 \n（仲景）\\x小柴胡汤\\x 治邪在肝胆半表半里之间，寒热往来，喜呕，或日晡发热，胁痛耳聋 \n，郁怒 疟等证。 \n柴胡（半斤） 半夏（半升） 人参 黄芩 生姜 甘草（各三两） 大枣（十二枚，擘） \n上七味，以水一斗二升，煮取六升，去滓，再煎取三升，温服一升，日三服。若胸中烦 \n而不呕，去半夏、人参，加栝蒌实一枚；若渴者，去半夏，加人参合前成四两半，栝蒌根四 \n两；若腹中痛者，去黄芩，加芍药三两；若胁下痞硬，去大枣，加牡蛎四两；若心下悸 \n，小便不利者，去芩，加茯苓四两；若不渴，外有微热者，去人参，加桂三两，温覆取微汗 \n愈；若咳者，去人参、大枣、生姜，加五味子半升，干姜二两。 \n按∶上方乃汉时古数也，今方改用柴胡（二、三钱） 半夏 黄芩（各一、二钱） 人参（二、三 \n钱） 甘草（五、七分） \n上加姜、枣，水煎服。 \n（薛氏）\\x加味小柴胡汤\\x 亦名柴胡栀子散。治乳母肝火发热，致儿为患，及风热生痰等证。 \n即前方加丹皮、栀子。 \n《良方》\\x加味小柴胡汤\\x 治伤寒胁痛，及少阳厥阴热疟。 \n即前方小柴胡汤加枳壳（面炒）、牡蛎粉 \n加姜三片，枣二枚，水二钟，煎服。 \n\\x加减小柴胡汤\\x 治脉弦，寒热，腹中痛。 \n即前小柴胡汤去黄芩，加芍药。 \n加姜、枣，水煎服。 \n\\x柴胡石膏汤\\x 治少阳阳明外感挟火，头痛口干，身热恶寒拘急。 \n柴胡（二钱） 石膏（三钱） 甘草（一钱） \n上用姜、水煎服。气虚者，加人参。 \n\\x大柴胡汤\\x 方在攻阵。治表证未除，里证又急，汗下兼行，宜此。 \n\\x柴平汤\\x 方在和阵。治湿疟一身尽痛。 \n\\x柴苓汤\\x 方在和阵。治身热烦渴泄泻。 \n\\x加减柴苓汤\\x 方在和阵。治诸疝。和肝肾，顺气除湿。 \n（仲景）\\x四逆散\\x 治阳气亢极，血脉不通，四肢厥逆，在臂胫之下者。若是阴证，则上过 \n于肘，下过于膝，以此为辨，乃不当用此也。 \n柴胡 芍药 甘草 枳壳（各等分） \n为细末。每服二钱，米饮调下，日三服。嗽加五味子、干姜各五分；悸者，加桂五分； \n腹痛，加附子一枚炮令坼；泄利下重者，浓煎韭白汤调服。 \n（仲景）\\x葛根汤\\x 治太阳伤寒，项背强几几，无汗恶风，及太阳阳明合病下利者。此即桂 \n枝汤加麻黄、葛根也。 \n葛根（四两） 麻黄（去节） 生姜（各三两） 桂（去皮） 芍药 甘草（炙，各二两） 大枣（十二枚 \n上七味， 咀。以水一斗，先煮麻黄、葛根减二升，去沫，纳诸药，煮取三升， \n去滓，温服一升，覆取微似汗，不须啜粥，余如桂枝法将息及禁忌。 \n\\x升麻葛根汤\\x 治伤寒阳明经证，目痛鼻干不眠，无汗恶寒发热，及小儿疮疹疫疠等证。 \n升麻 葛根 芍药 甘草（各等分） \n水二钟，煎一钟，寒多，热服；热多，温服。 \n\\x柴葛解肌汤\\x 此《槌法》加减方。治足阳明证，目痛鼻干不眠，头疼，眼眶痛，脉微洪者。 \n柴胡 干葛 甘草 黄芩 芍药 羌活 白芷 桔梗 \n水二钟，姜三片，枣二枚，槌法加石膏末一钱煎之，热服。本经无汗恶寒者去黄芩，冬 \n月，加麻黄；他时，加苏叶。 \n\\x葛根葱白汤\\x 治伤寒已汗未汗，头痛。 \n葛根 芍药 川芎 知母（各二钱） 生姜（二钱） 葱白（五寸） \n水二钟，煎一钟服。 \n\\x连须葱白汤\\x 治伤寒已汗未汗，头痛如破。 \n连须葱白（切，半片） 生姜（二两） \n水三钟，煎一钟半，分二服。 \n《局方》\\x参苏饮\\x 治四时感冒伤寒，头痛发热，恶寒无汗，及伤风咳嗽声重，涕唾稠粘 \n，潮热往来。此药解肌宽中，孕妇伤寒、痘疹并治。 \n人参 苏叶 干葛 前胡 陈皮 枳壳 半夏 茯苓（各八分） 木香 桔梗 甘草（各五分） \n水二钟，姜五片，枣一枚，煎八分，热服。 \n\\x加减参苏饮\\x 方在痘疹。治痘疹初热见点，解利之药。 \n\\x败毒散\\x 亦名人参败毒散。治四时伤寒瘟疫，憎寒壮热，风湿风眩项强，身体疼痛，不 \n问老少皆可服。或岭南烟瘴之地，疫疠时行，或处卑湿，香港脚痿弱等证，此药不可缺，日三 \n服，以效为度。 \n人参 茯苓 枳壳 甘草 川芎 羌活 独活 前胡 柴胡 桔梗（各等分） \n水一钟半，姜三片，煎服；或为细末，沸汤点服。 \n\\x加味败毒散\\x 方在外科。解利足三阳热毒，寒热如疟。 \n\\x荆防败毒散\\x 方在痘疹。发散痘疹俱可用。 \n《局方》\\x五积散\\x 治感冒寒邪，头疼身痛，项背拘急，恶寒呕吐，肚腹疼痛，及寒湿客 \n于经络，腰脚骨髓酸痛，及痘疮寒胜等证。 \n当归 麻黄 苍术 陈皮（各一钱） 浓朴（制） 干姜（炮） 芍药 枳壳（各八分） 半夏（炮） \n白芷（各七分） 桔梗 炙甘草 茯苓 肉桂 人参（各五分） 川芎（四分） \n水二钟，姜三片，葱白三茎，煎八分，不拘时服。 \n又歌曰∶痢后遍生脚痛风，《局方》五积自能攻。 \n就中或却麻黄去，酒煮多多服见功。 \n\\x十神汤\\x 治时气瘟疫，感冒风寒，发热憎寒，头痛咳嗽无汗。此药不拘阴阳两感，一切发散宜此。 \n紫苏 干葛 升麻 芍药（各一钱） 麻黄 川芎 甘草（各八分） 白芷 陈皮 香附（各六分） \n水二钟，姜三片，煎服。 \n（东垣）\\x升阳散火汤\\x 治胃虚血虚，因寒邪郁遏阳气，以致肌表俱热如火，扪之烙手。此 \n火郁发之之剂也。 \n升麻 葛根 羌活 独活 芍药 人参（各五分） 防风 炙甘草（各三分） 生甘草（二分） 柴 \n胡（八分） \n水一钟半，加生姜三片，煎服。忌生冷。 \n\\x升阳益胃汤\\x 方在和阵。治秋燥行令，阳气渐衰，恶寒体倦。 \n\\x圣散子\\x 治一切山岚瘴气，时行瘟疫，伤寒风湿等疾，有非常之功，如李待诏所谓内寒 \n外热，上实下虚者，此药尤效通神。宋嘉 中，黄州民病疫瘴大行，得此药痊活者不可胜纪 \n，苏东坡撰文勒石以广其传，圣散子之功益着。徽州郑尚书在金陵，用此方治伤寒，活人甚 \n众。故知其大能发散寒湿，驱除瘴疟，实有超凡之效也。 \n苍术（制） 防风 浓朴（姜炒） 猪苓 泽泻（煨，各二两） 白芷 川芎 赤芍药 藿香 \n柴胡（各半两） 麻黄 升麻 羌活 独活 枳壳 吴茱萸（泡） 细辛 本 茯苓（各七钱） 石 \n菖蒲 草豆蔻 良姜（各八钱） 甘草（二两半） 大附子（一枚） \n上为粗末。每服三钱，水二钟，枣一枚，煎八分，稍热服。 \n（易老）\\x九味羌活汤\\x 一名羌活冲和汤。治四时不正之气，感冒风寒，憎寒壮热，头疼身 \n痛，口渴，人人相似者，此方主之。 \n羌活 防风 苍术（各一钱） 白芷 川芎 生地 黄芩 甘草（各钱半） 细辛（七分） \n水二钟，姜三片，枣一枚，煎八分，热服取汗。有汗者，去苍术，加白术；渴者，加葛 \n根、石膏。 \n\\x六神通解散\\x 方在寒阵。治发热头痛，脉洪身热无汗。 \n《局方》\\x消风百解散\\x 治四时伤寒，头痛发热，及风寒咳嗽，鼻塞声重，或喘急。 \n荆芥穗 麻黄 白芷 苍术 陈皮（各一钱） 甘草（五分） \n水一钟半，加姜、葱煎八分，热服。嗽甚者，加乌梅一个。 \n《局方》\\x消风散\\x 一名人参消风散。治风热上攻，头目昏眩，鼻塞声重，及皮肤顽麻，瘾疹瘙痒等证。 \n荆芥穗 炙甘草 人参 川芎 防风 羌活 蒲荷 蝉蜕（炒） 僵蚕（炒） 茯苓（各二钱） \n陈皮 浓朴（各一钱） \n上为末。每服二、三钱，茶清调服，疮癣温酒下。 \n（子和）\\x风消散\\x \n照前方，但无荆芥、防风、薄荷、甘草四味。 \n\\x二味消风散\\x 治皮肤瘙痒不能忍。 \n苏州薄荷叶 蝉蜕（去头足土，各等分） \n上为末。食远温酒调下二钱。 \n《大旨》\\x黄芩半夏汤\\x 专治寒包热，兼治表里。 \n黄芩（酒炒） 半夏 麻黄 紫苏 桔梗 枳壳 杏仁 甘草（等分） \n水二钟，姜三片，枣二枚，煎八分，食远服。天寒，加桂枝。 \n《金匮》\\x续命汤\\x 治中风肢体不收，口不能言，冒昧不知痛处，拘急不能转侧，并治但伏 \n不得卧，咳逆上气，面目浮肿。 \n麻黄（去节） 人参 当归 石膏 桂枝 川芎 干姜 甘草（各三两） 杏仁（四十枚，去皮尖） \n上九味，以水一斗，煮取四升，温服一升。当小汗，薄覆脊，凭几坐，汗出则愈。不汗 \n更服。无所禁忌，勿当风。 \n《千金》\\x小续命汤\\x 通治八风五痹痿厥等证，又于六经分别随证加减用之。 \n麻黄（去节） 人参（去芦） 黄芩（去腐） 芍药 甘草（炙） 川芎 白术 防己 杏仁（ \n去皮尖，炒） 官桂（各一两） 防风（一两半） 附子（炮去皮脐，半两） \n上 咀。每服五钱，用水一钟半，加姜五片，枣一枚，煎八分，温服。春夏，加 \n石膏、知母、黄芩；秋冬，加官桂、附子、芍药。可随证增减诸药用。 \n附云岐子加减法∶如精神恍惚，加茯苓、远志；心烦多惊，加犀角；骨节间烦疼有热者 \n，去附子，倍芍药；骨间冷痛，倍用桂枝、附子；燥闷、小便涩，去附子，倍芍药，入竹沥 \n一合煎；脏寒下痢，去防己、黄芩，倍附子、白术一两；热痢，减去附子；脚弱，加牛膝、 \n石斛各一两；身痛，加秦艽一两；腰痛，加桃仁、杜仲各半两；失音，加杏仁一两；自汗者 \n，去麻黄、杏仁，加白术；春，加麻黄一两；夏，加黄芩七钱；秋，加当归四两；冬，加附子半两。 \n《千金》\\x大续命汤\\x \n即前方《金匮》续命汤去人参，加黄芩、荆沥。《元戎》方用竹沥。 \n\\x续命煮散\\x 补虚消风，通经络，行气血，除螈 疼痛。 \n人参 熟地黄 当归 川芎 芍药 防风 荆芥 独活 细辛 葛根 甘草 远志 半 \n夏（各五钱） 桂心（七钱半） \n上每服一两，水二钟，生姜三片，煎八分，温服。汗多者，加牡蛎粉一钱半。 \n《宝鉴》\\x秦艽升麻汤\\x 治中风手足阳明经，口眼 斜，四肢拘急，恶风寒。 \n升麻 葛根 甘草（炙） 芍药 人参（各半两） 秦艽 白芷 防风 桂枝（各三钱） \n每服一两，水二钟，连须葱白头三茎，煎至一钟，食后稍热服，避风寒卧，得微汗即止。 \n\\x愈风汤\\x 治中风诸证，当服此药，以行导诸经，则大风悉去，纵有微邪，只从此药加减 \n治之。若初觉风动，服此不致倒仆，此乃治未病之要药也。 \n羌活 甘草 防风 当归 蔓荆子 川芎 细辛 黄 枳壳 人参 麻黄 白芷 甘 \n菊薄荷 枸杞子 知母 地骨皮 独活 秦艽 黄芩 芍药 苍术 生地黄（各四两） 肉桂（一两） \n上 咀。每服一两，水二钟，生姜三片，煎七分，空心临卧服。空心一服，吞下 \n二丹丸，谓之重剂；临卧一服，吞下四白丹，谓之轻剂。假令一气之微汗，用愈风汤三两， \n加麻黄一两，作四服，加姜五、七片，空心服，以粥投之，得微汗则佳；如一旬之通利，用 \n愈风汤三两，加大黄一两，亦作四服，每服加生姜五、七片，临卧煎服，得利为度。又洁古 \n羌活愈风汤∶即同前方加柴胡、杜仲、半夏、浓朴、防己、白茯苓、前胡、熟地黄、石膏等 \n九味，共三十三味，云治肝肾虚，筋骨弱，言语艰难，精神昏愦，风湿内弱，风热体重，或 \n瘦而一肢偏枯，或肥而半身不遂。心劳则百病生，心静则万邪息，此药能安心养神，调阴阳 \n，无偏胜。 \n景岳曰∶中风一证，病在血分，多属肝经，肝主风木，故名中风，奈何自唐宋名家以来 \n，竟以风字看重，遂多用表散之药。不知凡病此者，悉由内伤，本无外感，既无外感而治以 \n发散，是速其危耳。若因其气血留滞，而少佐辛温以通行经络则可，若认为风邪，而必用取 \n汗以发散则不可。倘其中亦或有兼表邪而病者，则诸方亦不可废，故择其要者详录之，亦以 \n存古人之法耳。 \n\\x胃风汤\\x 治虚风能食，牙关紧急，手足搐挛，胃风面肿。 \n白芷（一钱二分） 升麻（二钱） 葛根 苍术 蔓荆子 当归（各一钱） 甘草（炙） 柴胡 本 \n羌活 黄柏 草豆蔻 麻黄（各五分） \n水二钟，姜三片，枣二枚，煎八分，温服。 \n\\x地黄散\\x 治中风四肢拘挛。 \n干地黄 甘草（炙） 麻黄（去节，各一两） \n上 咀。用酒三升，水七升，煎至四升，去 ，分作八服。日进二服，不拘时。 \n（东垣）\\x羌活附子汤\\x 治冬月犯寒，脑痛齿亦痛，名曰脑风。 \n羌活 苍术（各五分） 制附子（炮） 麻黄 防风 白芷 僵蚕 黄柏（各七分） 升麻 甘草 \n（各二分） 黄 （三分） 佛耳草（无嗽不用） \n水一钟半，煎八分，温服。一方有细辛。 \n《宝鉴》\\x羌活附子汤\\x 方在热阵。治呃逆。 \n\\x羌活胜风汤\\x 治两眼眵多 燥，紧涩羞明，赤脉贯晴，头痛鼻塞，肿胀涕泪，脑 \n颠沉重，眉骨酸疼，外翳如云雾丝缕，秤星螺盖。 \n羌活 防风 荆芥穗 白芷 独活 柴胡 薄荷叶 白术 桔梗 前胡 枳壳 甘草 \n川芎 黄芩（各五分） \n水二钟，煎一钟，热服。 \n《圣惠》\\x川芎散\\x 治偏正头风疼痛。 \n川芎 羌活 细辛 香附 槐花 甘草（炙） 石膏（各半两） 荆芥穗 薄荷 菊花 茵陈 \n防风（各一两） \n上为末。每服二钱，食后茶清调服。忌动风物。 \n《玉机》\\x川芎散\\x 治风热头痛不清及目病。 \n川芎（三分） 羌活 防风 本 升麻 甘草（各一钱） 柴胡（七分） 黄芩（炒） 黄连（各四钱） \n生地（二钱） \n上为末。每服一、二钱，茶清调下。 \n《局方》\\x川芎茶调散\\x 治伤风上攻，偏正头痛，鼻塞声重。 \n薄荷叶（二两） 川芎 荆芥穗（各一两） 羌活 白芷 甘草（各五钱） 细辛 防风（各二钱半） \n上为细末。每服二钱，食后茶清调下。 \n《局方》\\x神术散\\x 治四时瘟疫伤寒，发热恶寒，头疼，项强身痛，及伤风头痛，鼻塞声重，咳嗽。 \n苍术 本 白芷 细辛 羌活 川芎 炙甘草（各一钱） \n水一钟半，姜三片，葱白三寸，煎服。 \n《良方》\\x天香散\\x 治年久头风不得愈者。 \n南星（制） 半夏（制） 川乌（去皮） 白芷（各二钱） \n上作一服，水二钟，加生姜自然汁小半盏，煎一盏。食远服。 \n《直指》\\x芎芷散\\x 治风壅头痛。 \n川芎 白芷 荆芥穗 软石膏 \n上为末，每服一钱，食后沸汤调下。 \n\\x芎辛导痰汤\\x 治痰厥头痛。 \n川芎 细辛 南星 橘红 茯苓（各钱半） 半夏（二钱） 枳实 甘草（各一钱） \n水一钟半，姜七片，煎八分，食后服。 \n《奇效》\\x上清散\\x 治头痛，眉骨痛，眼痛不可忍者。 \n川芎 郁金 芍药 荆芥穗 芒硝（各半两） 蒲荷叶（一钱） 片脑（半钱） \n上为细末。每用一字，鼻内搐之。一方有乳香、没药各一钱。 \n《本事》\\x透顶散\\x 治偏正头风，夹脑风，并一切头风，不问年深日近。 \n细辛（表白者，三茎） 瓜蒂（七个） 丁香（三粒） 糯米（七粒） 脑子 麝香（各一豆许） \n上将脑、麝另研极细，却将前四味亦另研细末，然后并研令匀，用瓷罐盛之，谨闭罐口 \n。用时随左右搐之一大豆许，良久出涎则安。 \n\\x菊花散\\x 治风热上攻，头痛不止。 \n甘菊花 旋复花 防风 枳壳 羌活 蔓荆子 石膏 甘草（各一钱） \n水一钟半，姜五片，煎七分，不拘时服。 \n《宝鉴》\\x如圣散\\x 治眼目、偏痛、头风。 \n麻黄（烧灰，半两） 盆硝（二钱半） 麝香 脑子（各少许） \n上为细末搐之。 \n\\x点头散\\x 治偏正头痛。 \n川芎（一两） 香附（四两，炒去毛） \n上为细末。每服二钱，食后茶清调服。 \n（东垣）\\x清空膏\\x 治偏正头痛年深不愈者。善疗风湿热上壅头目，及脑痛不止。若除血虚 \n头痛者，非此所宜。 \n川芎（五钱） 柴胡（七钱） 黄连（酒炒） 防风 羌活（各一两） 炙甘草（一两半） 细挺子黄芩（一 \n两，一半炒，一半酒洗） \n上为细末。每服二钱匕，热茶调如膏，抹在口内，少用白汤送下，临卧。如若头痛，每 \n服加细辛二分；如太阴脉缓有痰，名曰痰厥头痛，减羌活、防风、川芎、甘草，加半夏一两五钱。 \n\\x愈风饼子\\x 治头风疼痛。 \n川乌（炒，半两） 川芎 甘菊 白芷 防风 细辛 天麻 羌活 荆芥 薄荷 \n上为细末，水浸蒸饼为剂，捏作饼子。每服三、五饼，细嚼茶酒任下，不拘时。 \n《本事》\\x治八般头风\\x \n草乌尖 细辛（等分） 黄丹（少许） \n上为细末，用苇管搐入鼻中。 \n《百一》\\x都梁丸\\x 治风吹项背，头目昏眩，脑痛，及妇人胎前产后伤风头痛。 \n白芷（大块白者，沸汤泡切） \n上为末，炼蜜丸，弹子大。每用一丸，细嚼荆芥点茶下。 \n《和剂》\\x三 汤\\x 治感冒风寒，鼻塞声重，语音不出，咳嗽喘急，胸满多痰。 \n麻黄（连节） 杏仁（连皮尖） 生甘草 \n上咀。每服五钱，姜三、五片，水煎，食远服。若憎寒恶风，欲取汗解，加桔梗、荆芥 \n，白五 汤，治咽痛。 \n《局方》\\x华盖散\\x 治肺受风寒，头痛发热，咳嗽痰饮。 \n麻黄（去节） 苏子 桑白皮 杏仁（去皮尖，炒） 赤茯苓 橘红（各一钱） 甘草（五分） \n水二钟，姜五片，枣一枚，煎八分，食后服。 \n冲和散 治感冒风湿，头目不清，鼻塞声重，倦怠欠伸出泪。 \n苍术（四两，米泔浸炒） 荆芥 甘草（炙，八钱） \n上为末。姜汤调服二钱。 \n\\x金沸草散\\x 治肺感寒邪，鼻塞声重，咳嗽不已，憎寒发热，无汗恶风，或热壅膈间，唾浊痰甚。 \n旋复花 麻黄 荆芥（各一钱） 前胡 半夏 芍药（各八分） 甘草（炙，五分） \n水二钟，姜三片，枣一枚，煎八分，食远服。 \n《三因》\\x旋复花汤\\x 治风寒暑湿伤肺，喘嗽大甚，坐卧不宁。 \n旋复花 前胡 甘草 茯苓 半夏曲 杏仁 麻黄 荆芥穗 五味子 赤芍药（各等分） \n上每服五钱，加姜、枣水煎。有汗者勿服。 \n《良方》\\x旋复花汤\\x 治风痰呕逆，饮食不下，头目昏闷等证。 \n旋复花 枇杷叶 川芎 细辛 赤茯苓（各一钱） 前胡（一钱半） \n上加姜、枣水煎服。 \n《医林》\\x桑皮散\\x 治上焦热壅，咳嗽连声，血腥并气不得透。 \n桑皮 柴胡 前胡 紫苏 薄荷 枳壳 桔梗 赤茯苓 黄芩 炙甘草（等分） \n上咀。每服七、八钱，水一钟半，煎七分，食远温服。 \n《简易》\\x苏陈九宝汤\\x 治老人小儿素有喘急，遇寒暄不常，发则连绵不已，咳嗽哮吼，夜不得卧。 \n麻黄 紫苏 薄荷 桂枝 桑白皮 大腹皮 陈皮 杏仁 甘草（各六分） \n水一钟半，姜三片，乌梅一个，煎七分服。 \n《局方》\\x羌活散\\x 治风邪壅滞，鼻塞声重，头目昏眩，遍身拘急，肢节烦痛，天阴愈觉不安者。 \n羌活 麻黄 防风 细辛 川芎 菊花 枳壳 蔓荆子 前胡 白茯苓 甘草 石膏 \n黄芩（等分） \n水一钟半，姜三片，煎服。 \n\\x羌活散\\x 治风痹手足不仁。 \n羌活 防己 防风 枣仁 当归 川芎（各一两） 附子（炮去皮脐） 麻黄（去根节） 天麻 \n各（一两半） 黄松节 薏仁（各二两） 荆芥（一握） \n上为细末，每服二钱，不拘时温酒调下。 \n《得效》\\x芎芷香苏散\\x 散风消痰，理香港脚。 \n川芎 甘草（二钱） 苏叶 干葛 白茯苓 柴胡（各半两） 半夏（六钱） 枳壳（炒，三钱） 桔梗 \n（生，二钱半） 陈皮（三钱半） \n每服三钱，水一钟，姜三片，枣一枚，煎八分，不拘时温服。 \n《金匮》\\x越婢汤\\x 治风水恶风，一身悉肿，脉浮不渴，续自汗出，无大热。 \n麻黄（一两） 石膏（半斤） 生姜（三两） 甘草（二两） 大枣（十五枚） \n上五味，以水六升，先煮麻黄去上沫，纳诸药，煮取三升。分温三服。恶风者，加附子 \n一枚；风水，加白术四两。（《古今录验》方）即名越婢加术汤。 \n《金匮》\\x越婢加半夏汤\\x 治肺胀咳喘上气，目如脱状，脉浮大者。 \n麻黄（六两） 石膏（半斤） 生姜（三两） 甘草（二两） 大枣（十五枚） 半夏（半斤） \n上六味，以水六升，先煮麻黄去上沫，纳诸药，煮取三升，分温三服。 \n\\x当归汤\\x 治肺痹上气，闭塞胸中，胁下支满，乍作乍止，不得饮食，唇干舌燥，手足冷痛。 \n当归（焙） 防风（去叉） 黄 （各二两） 人参 细辛 黄芩（去腐，各一两） 桂心（三两） 柴 \n胡（八两） 半夏（汤炮，五两） 杏仁（去皮尖，炒，五十个） 麻黄（去根节，水煮二三沸，掠去沫 \n，晒干，一两） \n上 咀。每服五、七钱，水一钟，姜七片，枣二枚，煎七分，不拘时温服，日三夜二。 \n\\x羌活胜湿汤\\x 方在和阵。治外伤湿气，一身尽痛。 \n《局方》\\x乌药顺气散\\x 治风气攻注，四肢骨节疼痛，遍体顽麻，瘫痪香港脚，语言蹇涩， \n痿弱等证。先宜服此以疏气道，然后随证用药。 \n乌药 麻黄 白芷 川芎 桔梗 橘红 枳壳（麸炒） 甘草（炙） 僵蚕（炒，各一两） 干 \n姜（炮，五钱） \n上每服五钱，姜、水煎服。 \n\\x通关散\\x 方在因阵。搐鼻取嚏，开通牙关。 \n\\x神效左经丸\\x 治诸风寒湿痹，麻木不仁，肢体手足疼痛，极效。 \n苍术（米泔浸） 草乌（去皮） 葱白 干姜（各四两） \n上四味，捣烂装入瓶内按实，密封瓶口，安于暖处，三日取出晒干，入后药。按∶此方 \n当加当归六两更佳。 \n金毛狗脊 本 白芷 破故纸（酒浸，焙干） 抚芎 小茴香（炒） 穿山甲（炮） 牛膝 \n（酒浸，各三两） 川乌（炮） 木瓜 白附子 虎胫骨（酥炙） 乳香（炙） 没药（炙，各一两，另研） \n上为末，酒糊丸，小豆大。每服三、四十丸，空心酒下。 \n《三因》\\x麻黄左经汤\\x 治风寒暑湿四气流注足太阳经，腰足挛痹，关节重痛，憎寒发热 \n，无汗恶寒，或自汗恶风头痛。 \n麻黄（去节） 干葛 细辛 防风 桂心 羌活 苍术 防己（酒拌） 茯苓 炙甘草（各一钱一分） \n水二钟，姜三片，枣一枚，煎八分，食前服。 \n《三因》\\x半夏左经汤\\x 治足少阳经为四气所乘，以致发热，腰胁疼痛，不食，热闷烦心 \n，腿痹纵缓。 \n半夏（制） 干葛 细辛 柴胡 防风 桂心 干姜（炮） 白术 麦冬 黄芩 茯苓 炙 \n甘草（各一钱） \n水二钟，姜三片，枣一枚，煎八分，食前服。 \n《三因》\\x大黄左经汤\\x 治四气流注足阳明经，致腰脚肿痛不可行，大小便秘，或恶饮食 \n，喘满自汗，呕吐腹痛。 \n大黄（煨） 细辛 羌活 前胡 杏仁（去皮尖，炒） 浓朴（制） 枳壳 黄芩 茯苓 炙 \n甘草（各一钱） \n水二钟，姜三片，枣二枚，煎八分，食前服。 \n《千金》\\x第一麻黄汤\\x 治恶风毒瓦斯，脚弱无力，顽痹，四肢不仁，失音不能言，毒瓦斯冲 \n心。有人病此者，但一病相当，即服此第一方，次服第二、第三、第四方。 \n麻黄（一两） 大枣（十二枚） 茯苓（三两） 杏仁（三十枚） 防风 当归 白术 川芎 升麻 芍 \n药黄芩 桂心 麦冬 甘草（各二两） \n上 咀。以水九升，清酒二升，合煮取二升半，分四服，日三夜一。覆令小汗， \n粉之，莫令见风。 \n《千金》\\x第二独活汤\\x \n独活（四两） 熟地黄（三两） 生姜（五两） 葛根 桂心 甘草 芍药 麻黄（各二两） \n上 咀。以水八升，清酒二升，合煎取二升半，分四服，日三夜一。脚弱者，特 \n忌食瓠子、蕺菜，犯之则一世不愈。 \n《千金》\\x第三兼补浓朴汤\\x 并治诸气咳嗽，逆气呕吐。 \n浓朴 川芎 桂心 熟地黄 芍药 当归 人参（各二两） 黄 甘草（各三两） 吴茱萸（二 \n升） 半夏（七两） 生姜（一斤） \n上 咀。以水二斗，煮猪蹄一具，取汁一斗二升，去上肥腻，入清酒三升，合煮 \n取三升，分四服。相去如人行二十里久，更进服。 \n《千金》\\x第四风引独活汤\\x 兼补方。 \n独活（四两） 茯苓 甘草（各三两） 升麻（一两半） 人参 桂心 防风 芍药 当归 黄 \n干姜 附子（各二两） 大豆（二升） \n上 咀。以水九升，清酒三升，合煮三升半，分四服，相去如人行二十里久，更进服。 \n\\x独活汤\\x 治香港脚阳虚寒胜，经气不行，顽肿不用，如神。 \n独活 麻黄（去节） 川芎 熟附子 牛膝 黄 （炙） 人参 当归 白芍药 白茯苓 \n白术 杜仲（炒） 干姜 肉桂 木香 甘草（炙，等分）"}, {"n": 35, "text": "卷三十五\n\n上 咀。每服五、七钱，水一钟半，姜三片，枣三枚，煎八分，食前温服。 \n\\x追毒汤\\x 治肝脾肾三经为风寒热湿毒瓦斯上攻，阴阳不和，四肢拘挛，上气喘满，小便秘 \n涩，心热烦闷，遍身浮肿，脚弱不能行步。 \n半夏（汤泡七次） 黄 （去芦） 甘草（炙） 当归（去芦） 人参（去芦） 浓朴（姜制） 独活（去芦） 橘 \n红（各一两） 熟地黄 枳实（麸炒） 芍药 麻黄（去节，各二两） 桂心（三两） \n上 咀。每服八钱，水一钟半，生姜七片，枣三枚，煎八分，食前温服，日三夜一。 \n《局方》\\x排风汤\\x 治风虚冷湿，邪气入脏，狂言妄语，精神错乱，及五脏风邪等证。 \n防风 白术 当归（酒浸） 芍药 肉桂 杏仁 川芎 白藓皮 甘草（炙，各一钱） 麻黄 \n（去节） 茯苓 独活（各三钱） \n上分二服，水二钟，姜三片，煎七分，食远服。 \n\\x阳毒升麻汤\\x 治阳毒，赤斑狂言，吐脓血。 \n升麻（一钱半） 犀角（磨） 射干 黄芩 人参 甘草（各八分） \n水一盏半，煎八分，纳犀角汁和匀服。 \n\\x栝蒌根汤\\x 治风温大渴。 \n栝蒌根 干姜 防风 人参 甘草（各一钱） 石膏（三钱） 水一盏半，煎八分服。 \n\\x再造散\\x 治伤寒头痛发热，恶寒无汗，用表药而汗不出，脉无力者。此以阳虚不能作汗 \n，名曰无阳。若医不识此，复用麻黄等药，及覆逼取汗，误杀者多矣。 \n人参 黄 川芎 甘草 熟附子 桂枝 细辛 羌活 防风 煨生姜 夏月热甚，或加石膏 \n水一钟半，枣二枚，煎八分，温服。 \n《本事》\\x枳壳煮散\\x 治悲哀烦恼伤肝，两胁骨痛，筋脉紧，腰脚重滞，筋急不能举动， \n此药大治胁痛。 \n枳壳（麸炒，四两） 细辛 川芎 桔梗 防风（各二两） 葛根（一两半） 甘草（一两） \n上咀。每服七、八钱，水一钟半，姜、枣同煮，食煎温服。 \n\\x柴胡疏肝散\\x 治胁肋疼痛，寒热往来。 \n陈皮（醋炒） 柴胡（各二钱） 川芎 枳壳（麸炒） 芍药（各一钱半） 甘草（炙，五分） 香附（一钱半） \n水一钟半，煎八分，食前服。 \n《本事》\\x桂枝散\\x 治因惊伤肝，胁骨疼痛不已。 \n枳壳（一两，小者） 桂枝（半两） \n上为细末。每服二钱，姜、枣汤调下。 \n（河间）\\x葛根汤\\x 治寒邪在经，胁下疼痛不可忍。 \n葛根 桂枝 川芎 细辛 防风（各一钱） 麻黄 枳壳 芍药 人参 炙甘草（各八分） \n上咀。水一钟半，姜三片，煎八分，食远温服。 \n\\x升麻汤\\x 治无汗而喘，小便不利，烦渴发斑。 \n升麻 苍术 麦门冬 麻黄（各一钱） 黄芩 大青（各七分） 石膏（一、二钱） 淡竹叶（十片） \n水二钟，煎八分，温服。 \n（仲景）\\x柴胡桂枝干姜汤\\x 治伤寒五、六日，汗下后，但头汗出，往来寒热，心烦者，邪未解也。 \n柴胡（半斤） 桂枝（三两） 干姜（二两） 栝蒌根（四两） 黄芩（三两） 牡蛎（ ，二两） 甘草（炙，二 \n两） \n上七味，以水一斗二升，煮取六升，去滓，再煎取三升，温服一升，日三服。初服微烦 \n，再服汗出便愈。 \n\n\n\n<目录>卷之五十七宇集·古方八阵\n\n<篇名>寒阵\n\n属性：\\x黄连解毒汤\\x 亦名解毒汤。治火热狂躁烦心，口干舌燥，热之甚者，及吐下后热不解， \n脉洪喘急等证。 \n黄连 黄芩 黄柏 栀子（各等分） \n上每服五钱，水二钟，煎服。 \n（仲景）\\x白虎汤\\x 治伤寒脉浮滑，此表有热，里有邪，宜用此以解内外之热，及一切中暑 \n烦热，热结斑黄，狂躁大渴等证。 \n石膏（一斤，碎） 知母（六两） 甘草（二两） 糯米（六合） \n上四味，以水一斗，煮米熟去滓。温服一升，日三服。本方加苍术，即名苍术白虎汤。 \n（仲景）\\x白虎加人参汤\\x 此即人参白虎汤。亦名化斑汤。仲景法即于前白虎汤内加人参三 \n两，用治服桂枝汤大汗出后，大烦渴不解，脉洪大者。今近代止用人参二钱，石膏五钱，知 \n母二钱，甘草一钱，糯米一撮，以治赤斑口燥烦躁，暑热脉虚等证。又河间名为人参石膏汤 \n，用治膈消烦热，但分两加倍于今方。 \n《活人》\\x白虎加桂枝汤\\x 治疟但热不寒，及有汗者。 \n知母 桂枝 甘草（炙） 粳米（各一钱） 石膏（一钱） \n上咀。水一钟半，煎八分，温服。 \n（仲景）\\x竹叶石膏汤\\x 治阳明汗多而渴，鼻衄，喜水，水入即吐，及暑热烦躁等证。 \n石膏（一两） 竹叶（二十片） 半夏 甘草（各二钱） 麦冬 人参（各三钱） 粳米（一撮，此系今方 \n，分两非仲景旧法） \n水二钟，姜三片，煎服。一方云∶石膏二钱，人参一钱，其他以降序之，用者当酌宜也。 \n\\x六味竹叶石膏汤\\x 治胃火盛而作渴。 \n石膏（ ，倍用之） 淡竹叶 桔梗 薄荷叶 木通 甘草（各一钱） \n水煎服。 \n\\x竹叶黄 汤\\x 治胃虚火盛作渴。 \n淡竹叶（二钱） 人参 黄 生地黄 当归 川芎 麦冬 芍药 甘草 石膏（ ） 黄芩（炒，各一钱） \n水煎服。按此方之用，当去川芎为善。外科仍有半夏。 \n《宣明》\\x桂苓甘露饮\\x 治阳暑发热烦躁，水道不利等证。 \n滑石（飞，四两） 石膏 寒水石 白术（各二两） 茯苓 泽泻（各一两） 肉桂 猪苓（各五钱） \n甘草（二两，炙） \n上为末。每服三钱，温汤调下。 \n（子和）\\x桂苓甘露饮\\x 治证同前，脉虚而渴者当用此。 \n滑石（一两） 人参 白术 茯苓 甘草 石膏 寒水石 干葛 泽泻（各一两） 官桂 木香 藿香（各一钱） \n上为末。每服三钱，白汤调下。 \n《千金》\\x甘露饮\\x 治男妇小儿胃中客热，口舌生疮，咽喉肿痛，牙龈肿烂，时出脓血， \n及脾胃受湿，瘀热在内，或醉饱多劳，湿热相搏，致生胆病，身面皆黄，或身热而肿，大小便不调。 \n枇杷叶（拭去毛） 生地黄 熟地黄 天门冬 麦门冬 黄芩 石斛 茵陈 枳壳（各一钱） \n炙甘草（五分） \n上作一服，水二钟，煎七分，食后服。《本事方》无麦冬、茵陈，有山豆根、犀角屑， \n治口齿证大有神效。 \n\\x三黄石膏汤\\x 治疫疠大热而躁。 \n石膏（生，三钱） 黄芩 黄柏 黄连（各二钱） 豆豉（半合） 麻黄（八分） 栀子（五枚，打碎） \n水二盏，煎一盏，连进三、四盏则愈。 \n\\x羌活升麻汤\\x 治暑月时行瘟热，病宜清热解毒，兼治内外者。 \n羌活 升麻 葛根 人参 白芍药 黄芩（各一钱） 黄连 石膏 甘草 生地黄 知母（各七分） \n水二钟，姜三片，枣一枚，煎八分，温服。 \n（东垣）\\x普济消毒饮\\x 治疫疠憎寒壮热，头面肿盛，目不能开，上喘，咽喉不利，口干舌 \n燥，俗云大头瘟病，诸药不效。元泰和二年，东垣制以济人，所活甚众，时人皆曰天方。 \n黄芩（酒炒） 黄连（酒炒，各五钱） 人参（三钱） 橘红 玄参 生甘草 桔梗 柴胡（各二钱） \n薄荷叶 连翘 鼠粘子 板蓝根 马屁勃（各一钱） 白僵蚕（炒） 升麻（各七分） \n上为细末。半用汤调，时时服之；半用蜜丸噙化，服尽良愈。或加防风、川芎、当归、 \n薄荷、细辛，水二钟，煎一钟，食远稍热服。如大便硬，加酒蒸大黄一、二钱以利之； \n或热肿甚者，以砭针刺出其血。 \n\\x芩连消毒饮\\x 治天行时疫，大头病发热恶寒，颈项肿，脉洪痰痹等证。 \n柴胡 桔梗 羌活 防风 黄芩 黄连 连翘 枳壳 荆芥 白芷 川芎 射干 甘草 \n水一钟半，姜三片，煎服。有痰者，加竹沥、姜汁调服；如秘结热甚者，先加大黄煎服 \n，利二三行后，根据本方加人参、当归调理。 \n（河间）\\x六神通解散\\x 治发热头痛，脉洪身热无汗。《槌法》有川芎、羌活、细辛三味。 \n麻黄 甘草（各一钱） 黄芩 苍术（各二钱） 石膏 滑石（各钱半） 豆豉（十粒） \n水二钟，加葱、姜同煮一钟，温服。 \n（仲景）\\x小陷胸汤\\x 治小结胸，正在心下，按之则痛，脉浮滑者。 \n半夏（三钱） 黄连（钱半） 栝蒌仁（二钱，此非古数） \n上先以水二钟，煎栝蒌至一钟半，乃入二药同煎至八分，温服。原方用黄连一两，半夏 \n半升，栝蒌实一枚，水六升，如法煮二升，分三服。 \n\\x鸡子清饮\\x 治热病五、六日，壮热之甚，大便秘结，狂言欲走者。 \n鸡子（二枚，取清） 芒硝（细研） 寒水石（细研，各二、三钱） \n上以用新汲水一盏调药末，次下鸡子清搅匀，分二服。按∶此法似不若以悉尼浆调二药服之更妙。 \n（仲景）\\x黄连阿胶汤\\x 治少阴伤寒，二、三日以上，心中烦不得卧。 \n黄连（四两） 黄芩（一两） 芍药（二两） 阿胶（三两） 鸡子黄（二枚） \n上以水五升，先煮前三味，取二升，去滓，纳胶烊尽，小冷，纳鸡子黄搅令相得。温服 \n七合，日三服。 \n\\x栀子仁汤\\x 治发热潮热，狂躁面赤咽痛。 \n栀子 赤芍 大青 知母（各一钱） 升麻 柴胡 黄芩 石膏 杏仁 甘草（各二钱） 豆豉（百粒） \n水煎温服。一方无豆豉。又六味栀子仁汤在外科八。 \n（仲景）\\x栀子豆豉汤\\x 治伤寒烦热懊 。可为吐剂。 \n栀子（十四枚，擘） 香豉（四合） \n上用水四升，先煮栀子得二升半，内豉再煮取一升半，去滓，分二服。温进一服，得吐者，止后服。 \n（仲景）\\x栀子浓朴汤\\x 治伤寒下后，余邪未清，心烦腹满，起卧不安者。 \n栀子（十四枚，擘） 浓朴（四两，姜炙） 枳实（四两，炒） \n以上三味，用水三升半，煮取一升半，去滓，分二服。温进一服，得吐，止后服。 \n（仲景）\\x栀子干姜汤\\x 治伤寒以丸药大下之，身热不去，微烦者。若病患旧有微溏者不可用。 \n栀子（十四枚，擘） 干姜（三两） \n上二味，以水三升半，煮取一升半，去滓，分二服。温进一服，得吐者，止后服。 \n（仲景）\\x栀子柏皮汤\\x 治伤寒身黄发热者。 \n栀子（十五枚） 甘草（一两） 黄柏（二两） \n上三味，以水四升，煮取一升半，去滓，分温再服。 \n\\x解瘟疫热毒\\x \n瘟疫八、九日后，已经汗下不退，口渴咽干，欲饮水者，以蚯蚓粪名六一泥不拘多少， \n擂新汲水饮之，或用晚蚕砂亦可。其热甚者，用新青布以冷水浸过，略挤干，置患人胸上， \n以手按之良久，布热即易之，须臾，当汗出如水，或作战汗而解。夏月极热用此法，他时不可用。 \n\\x漏芦丹麻汤\\x 方在外科。治时毒头面红肿。 \n\\x黄连香薷饮\\x 方在和阵。治伤暑中热。 \n《局方》\\x泻心汤\\x 治心火。 \n用川黄连去须，为极细末。每服一字，或五分，或一钱，或汤或散，临卧服。 \n（仲景）\\x甘草泻心汤\\x 亦名半夏泻心汤。呕而肠鸣，心下痞者，此方主之。此方辛入脾而 \n散气，半夏、干姜之辛以散结；气苦入心而泄热，黄连、黄芩之苦以泄痞热；脾欲缓，急食 \n甘以缓之，人参、甘草、大枣之甘以缓之也。 \n半夏（半升，洗） 黄连（一两） 干姜 黄芩 甘草（炙） 人参（各三两） 大枣（十二枚，擘） \n上七味，以水一斗，煮取六升，去滓，再煮取三升，温服一升，日三服。 \n（仲景）\\x生姜泻心汤\\x 治伤寒汗解之后，胃中不和，心下痞硬，干噫食臭，胁下有水 \n气，腹中雷鸣下利者。 \n生姜（四两，切） 甘草（炙） 人参 黄芩（各三两） 干姜（一两） 黄连（一两） 半夏（半升，洗） \n大枣（十二枚，擘） \n上八味，以水一斗，煮取六升，去滓，再煎取三升，温服一升，日三服。此方无生姜， \n即名半夏泻心汤。 \n（仲景）\\x大黄黄连泻心汤\\x 治太阳伤寒汗下后，色微黄，心下痞，按之濡，其脉关上浮者。 \n大黄（二两） 黄连（一两） \n上二味，以微沸汤二升渍之，须臾，绞去滓，分温再服。 \n（仲景）\\x附子泻心汤\\x 治伤寒汗下后，心下痞，而复恶寒汗出者。 \n大黄（一两） 黄连 黄芩（各二两） 附子（一枚，炮去皮，破八片，别煮取汁） \n上前三味，以麻沸汤二升渍之，须臾，绞去滓，纳附子汁，分温再服。 \n\\x清心莲子饮\\x 治热在气分，口干作渴，小便淋浊，或口舌生疮，咽疼烦躁。 \n黄芩 麦冬 地骨皮 车前子（炒） 甘草（各钱半） 人参 黄 石莲子 柴胡 茯苓（各一钱） \n上每服五钱，水煎服。 \n《良方》\\x加味通心饮\\x 治诸疝内热胀痛，及小便不利。 \n木通 栀子仁 黄芩 瞿麦 连翘 枳壳 川楝子 甘草（等分） \n上咀。每服五钱，水一钟半，灯心二十根，车前草五茎，煎七分，温服。 \n\\x清心汤\\x 治心受热邪，狂言叫骂，动履失常。 \n黄连 黄芩 栀子 连翘 薄荷 甘草 芒硝 大黄（等分） \n水一钟半，竹叶二十片，煎八分，温服。 \n\\x外科清心汤\\x 方在外科。治疮疡肿痛发热。 \n《局方》\\x人参清肺汤\\x 治肺胃虚热，咳嗽喘急，坐卧不安，年久劳嗽唾痰。 \n人参 杏仁（去皮尖，炒） 阿胶（各一钱） 粟壳（蜜炒，一钱半） 炙甘草 桑白皮 知母 \n地骨皮 乌梅肉（各五分） \n水二钟，枣一枚，煎八分，食远服。 \n\\x人参平肺散\\x 治心火克肺金，传为咳嗽喘呕，痰涎壅盛，胸膈痞满，咽喉不利。 \n人参 天冬 黄芩 地骨皮 陈皮 青皮 茯苓（各八分） 知母（一钱） 五味（二十粒） 甘草 \n（炙，五分） 桑白皮（炒，一钱半） \n水二钟，姜三片，煎八分，食远服。 \n\\x黄芩清肺饮\\x 治肺热小便不利，宜用此清之。 \n栀子（二钱） 黄芩（一钱） \n水煎服，如不利，加盐豉二十粒。 \n\\x清肺汤\\x 方在痘疹。治麻疹咳嗽甚者。 \n（东垣）\\x清肺饮子\\x 方在和阵。治邪热在气分，渴而小便不利。 \n（万氏）\\x清肺饮\\x 方在痘疹。治痘疹肺热喘嗽。 \n\\x泻白散\\x 治肺火，大肠火，喘急等证。 \n甘草（一钱） 桑白皮 地骨皮（各二钱） \n上为末。水调服。 \n\\x五味泻白散\\x 方在因阵。治眼目风热，翳膜外障。 \n《正传》\\x麦门冬汤\\x 治病后火热乘肺，咳嗽有血，胸胁胀满，上气喘急，五心烦热而渴。 \n天冬 麦冬 桑白皮（各七分） 紫菀茸 贝母（各六分） 桔梗 甘草（各五分） 淡竹叶 生地 \n（各一钱） 五味（九粒） \n水一钟半，枣一枚，煎服。 \n《类方》\\x麦门冬汤\\x 治肺热气衰血焦，发落好怒，唇口亦甚。 \n麦门冬 远志（甘草煮，去心） 人参 黄芩 生地黄 茯神 石膏（ ，各一两） 甘草（炙，半两） \n上 咀。每服一两，水煎服。 \n（万氏）\\x麦门冬汤\\x 方在痘疹。治表邪麻疹，火热嗽甚。 \n《家抄》\\x麦门冬饮\\x 治虚劳咳嗽，午后嗽多者是也。 \n川芎 当归 生地黄 白芍药 麦门冬 黄柏 知母（各一钱） 桑白皮（八分） 五味子（十五粒） \n水二钟，姜一片，枣一枚，煎八分，食后服。 \n《宣明》\\x麦门冬饮子\\x 治膈消胸满心烦，气多血少，津液不足，为消渴。 \n麦门冬 生地黄 人参 五味子 甘草（炙） 茯神 天花粉 知母 干葛（等分） \n上咀。每服一两，竹叶十四片，水煎服。 \n\\x二母散\\x 治肺热咳嗽，及疹后嗽甚者。 \n贝母（去心，童便洗） 知母（等分） 干生姜（一片） \n上水煎服。或为末，每服五分，或一钱，沸汤下。 \n（陈氏）\\x二母散\\x 方在妇人。治产后热血上攻，咳嗽喘促。 \n《家抄》\\x黄芩知母汤\\x 治夏月火嗽有痰，面赤烦热。 \n黄芩 知母 桑白皮 杏仁 山栀 天花粉 贝母 桔梗 甘草（等分） \n水二钟，煎八分，食远服。 \n《医林》\\x桑白皮汤\\x 治肺气有余，火炎痰盛作喘。 \n桑白皮 半夏 苏子 杏仁 贝母 山栀 黄芩 黄连（各八分） \n水二钟，姜三片，煎八分，温服。 \n（海藏）\\x紫菀散\\x 治嗽中有血，虚劳久嗽肺痿。 \n紫菀 阿胶 知母 贝母（各钱半） 人参 甘草 茯苓 桔梗（各一钱） 五味子（十二粒） \n水二钟，煎八分，食后服。 \n（东垣）\\x清胃散\\x 治醇酒浓味，或补胃热药太过，以致牙痛不可忍，牵引头脑，满面发热 \n，或齿龈溃烂，喜冷恶热，此阳明之火也，宜用此方。 \n生地（钱半） 升麻 当归 丹皮（各一钱） 黄连（钱半，夏月倍之） \n水煎服。 \n\\x加味清胃散\\x \n即前方加犀角、连翘、甘草。 \n《秘验》\\x清胃饮\\x 治一切风热湿痰牙痛床肿，血出动摇。 \n石膏 栀子 黄连 黄芩 当归 生地 白芍 苍术（各一钱） 青皮（八分） 细辛 藿香 \n荆芥穗（各六分） 升麻（五分） 丹皮 甘草（各四分） \n水二钟，煎八分，食后缓缓含饮之，效。 \n（钱氏）\\x泻黄散\\x 治脾火。 \n山栀（一两） 石膏（五钱） 藿香（七钱） 防风（四钱） 甘草（三钱） \n上 咀，蜜、酒拌，略炒香，为细末。每服二钱，水一钟，煎清汁饮。 \n\\x和中汤\\x 治虚火嘈杂。 \n人参 白术 茯苓 陈皮 半夏（各一钱） 甘草（五分） 黄连（姜炒，钱半） 大枣（二枚） \n水一钟半，加粳米一撮，煎八分，温服。 \n（薛氏）\\x柴胡清肝散\\x 治肝胆三焦风热疮疡，或怒火憎寒发热，或疮毒结于两耳、两胁前 \n后，或胸乳小腹下及股足等证。 \n柴胡 黄芩（炒，各钱半） 山栀（炒） 川芎 人参（各一钱） 甘草（五分） 连翘 桔梗（各八分） \n水一钟半，煎服。 \n\\x栀子清肝散\\x 治肝胆三焦风热，耳内作痒，或生疮出水，或胁肋胸乳作痛，寒热往来。 \n栀子 柴胡 丹皮（各一钱） 当归 川芎 芍药 牛蒡子（炒） 茯苓（各七分） 白术 甘草 \n（各五分） \n上水煎服。一方无白术。 \n《原机》\\x芍药清肝散\\x 治眵多 ，紧涩羞明，赤脉贯晴，脏腑秘结。 \n白术 川芎 防风 羌活 桔梗 滑石 石膏 芒硝（各三分） 黄芩 薄荷 荆芥 前胡 \n炙甘草 芍药（各二分半） 柴胡 山栀 知母（各二分） 大黄（四分） \n水煎，食远热服。 \n《良方》\\x龙胆泻肝汤\\x 亦名龙胆汤。治肝经湿热，小便赤涩，或胁胀口苦寒热，凡肝经 \n有余之证宜服之。 \n龙胆草（酒拌炒） 人参 天冬 麦冬 生甘草 黄连（炒） 山栀 知母（各五分） 黄芩（七 \n分） 柴胡（一钱） 五味（三分） \n水一钟半，煎服。 \n\\x七味龙胆泻肝汤\\x 治肝火内炎，如前诸证。 \n柴胡梢 泽泻 车前子 木通 龙胆草 归梢 生地（各等分） \n上 咀。水二钟，煎一钟。空心稍热服。 \n（薛氏）\\x加味龙胆泻肝汤\\x 治肝经湿热，或囊痈下疳便毒，小便涩滞，或阴囊作痛，小便短少。 \n龙胆草（酒炒，一钱） 车前子（炒） 当归尾 木通 泽泻（大人倍用） 甘草 黄芩 生地 \n山栀（大人倍用） \n上水煎。若治小儿，子母同服。 \n\\x当归六黄汤\\x 治盗汗之圣药。 \n当归 黄 （蜜炙，各二钱） 生地黄 熟地黄 黄连 黄芩 黄柏（各一钱） \n水二钱，煎服。 \n\\x正气汤\\x 治阴分有火盗汗。 \n黄柏（炒） 知母（炒，各二钱） 炙甘草（六分） \n水一钟半，煎八分，食远热服。 \n（仲景）\\x芍药甘草汤\\x 治伤寒脉浮，自汗出，小便数，心烦，微恶寒，脚挛急，足温者。 \n白芍药 甘草（炒，各四两） \n上二味，以水三升，煮取一升半，去滓，分温再服。 \n\\x生地黄煎\\x 治阴火盗汗。 \n生地 当归 黄 （炙） 甘草（炙） 麻黄根 浮小麦 黄连 黄芩 黄柏（各钱） \n水一钟半，煎八分，食远服。 \n《宝鉴》\\x石膏散\\x 治阳明风热头痛。 \n石膏 川芎 白芷（等分） \n上为细末。每服四钱，热茶清调下。 \n《本事》\\x荆芥散\\x 治头风。 \n荆芥 石膏（ ，等分） \n上为细末。每服二钱，姜三片，连须葱白三寸，水一钟，煎七分，食远服。 \n\\x双玉散\\x 治热痰咳嗽喘急，烦渴头痛。 \n石膏 寒水石（等分） \n上为极细末。每服三钱，人参汤或随证用引调下。 \n《玄珠》\\x秘方茶调散\\x 治风热上攻，头目昏痛，及头风热痛不可忍。 \n小川芎（一两） 细芽茶 薄荷（各三钱） 白芷（五钱） 荆芥穗（四钱） 片芩（二两，酒拌炒三次， \n不可令焦） \n头巅及脑痛，加细辛、 本、蔓荆子（各三钱）。上为细末。每服二、三钱，用茶清调下。 \n\\x天花散\\x 治消渴。 \n天花粉 生地黄 麦门冬 干葛（各二钱） 五味子 甘草（各一钱） \n上作二服，水一钟半，粳米百粒，煎八分，食远服。 \n（钱氏）\\x地骨皮散\\x 治壮热作渴。 \n地骨皮 茯苓 甘草 柴胡 人参 知母 半夏（等分） \n上 咀。每服一两，水煎服。 \n\\x玉泉丸\\x 治烦热口渴。 \n人参 麦门冬 黄 （蜜炙） 茯苓 乌梅肉（焙） 甘草（各一两） 天花粉 干葛（各两半） \n上为末，蜜丸，弹子大。每服一丸，温汤嚼下。 \n《宣明》\\x清膈导痰汤\\x 治胃火浓味，膈上热痰，咯吐不出，咳唾稠粘。 \n黄芩 贝母（各一钱） 天花粉 栝蒌仁 白茯苓 白术（各八分） 桔梗 甘草 陈皮（各五分） \n石膏 朴硝（各钱半） \n水一钟半，加竹叶二十片，揉烂，同煎八分，食远服。 \n\\x生铁落饮\\x 治痰火热狂，坠痰镇心。 \n生铁（四十斤） 入火烧赤沸，砧上锤之，有花出如兰如蛾，纷纷落地者，是名铁落。用水二 \n斗，煮取一斗，用以煎药。 \n石膏（三两） 龙齿（研） 茯苓 防风（去芦，各一两半） 玄参 秦艽（各一两） \n上 咀。入铁汁中煮取五升，去 ，入竹沥一升，和匀。温服二合，无时， \n每日约须五服。 \n\\x大连翘饮\\x 治风热热毒，大小便不利，及小儿痘后余毒，肢体患疮，或丹瘤等毒，游走不止。 \n连翘 山栀（炒） 黄芩 滑石 柴胡 荆芥 防风 甘草 当归 赤芍 木通 瞿麦 蝉蜕（各等分） \n上量大小，水煎服。 \n《局方》\\x犀角地黄汤\\x 治劳心动火，热入血室，吐血衄血，发狂发黄，及小儿疮痘血热 \n等证。景岳云∶此方治伤寒血燥血热，以致温毒不解，用此取汗最捷，人所不知。盖以犀角 \n之性，气锐能散。仲景云∶如无犀角，以升麻代之，此二味可以通用，其义盖可知矣。 \n生地（四钱） 芍药 丹皮 犀角（镑，各钱半） \n如欲取汗退热，必用尖生磨搀入之方妙。 \n上 咀。水一钟半，煎八分，加犀角汁服。或入桃仁去皮尖七粒同煎，以治血证。 \n《良方》\\x犀角地黄汤\\x \n即前方加黄连、黄芩各一钱。 \n《拨萃》\\x犀角地黄汤\\x 治一切血热失血，三焦血热便秘等证。 \n犀角（磨汁） 生地（二钱） 黄连 黄芩（各一钱） 大黄（三钱） \n水二钟，煎一钟，入犀角汁，和匀，温服。 \n《外科》\\x犀角地黄汤\\x 方在外科。治胃火血热妄行。 \n《良方》\\x生地黄散\\x 治血热小便出血。 \n生地黄（二钱） 黄芩（炒，五钱） 阿胶（炒） 柏叶（炒，各一钱） \n上水煎服。 \n\\x生地黄饮子\\x 治诸见血，吐血衄血，下血溺血，皆属热证。 \n生地 熟地 枸杞 黄 芍药 天冬 甘草 地骨皮 黄芩（各等分） \n上咀。每服七钱，水二钟，煎八分，食远服。如脉微身凉恶风者，加桂五分，吐血者多如此。 \n\\x茜根散\\x 治衄血不止，心神烦闷。 \n茜根 黄芩 阿胶（炒珠） 侧柏叶 生地黄（各二钱） 甘草（炙，一钱） \n水一钟半，姜三片，煎七分，食远服。 \n\\x人参五味子汤\\x 方在外科。治虚损肺痿等证。 \n\\x二神散\\x 治男妇吐血，或血崩下血。 \n陈槐花（二两，炒焦） 百草霜（五钱） \n上为细末。每服三钱，茅根煎汤调下。治下血，宜空心服之。舌上忽然肿破出血，宜此掺之。 \n《良方》\\x四生丸\\x 治吐血衄血。阳乘于阴，血热妄行，宜服此药。 \n生荷叶 生艾叶 生侧柏叶 生地黄（等分） \n上捣烂如鸡子大丸。每服一丸，水二盏，滤去 服。陈日华云∶先公尝游灵石寺， \n见一僧呕血，明年到寺，问呕血者何如？主僧云得服四生丸遂愈。自得此方，屡用有效。愚 \n意前证，乃内热暴患者宜用之，若人病本元不足，须补脾以资化源，否则虚火上炎，金反受克，获生鲜矣。 \n《济生》\\x鳖甲地黄汤\\x 治虚劳烦热，怔忡羸瘦。 \n鳖甲（醋炙） 熟地 人参 白术 当归 麦门冬 茯苓 石斛 柴胡 秦艽（各一钱） 肉 \n桂甘草（炙，各六分） \n水二钟，姜五片，乌梅一个，煎七分，不拘时服。 \n《局方》\\x黄 鳖甲煎\\x 治虚劳客热，肌肉消瘦，烦热心悸盗汗，少食多渴，咳嗽有血。 \n黄 （蜜炙） 鳖甲（醋浸炙，去裙） 人参 知母 桑白皮 紫菀 桔梗 甘草（炙，各五 \n分） 地骨皮 秦艽 柴胡 生地 芍药（各七分） 天门冬 白茯苓（各八分） 肉桂（四分） \n水一钟半，煎八分，食后温服。 \n\\x地黄膏\\x 滋阴降火，养血清肝退热。 \n鲜地黄（以十斤为则，捣汁，和众药汁同煎） 当归身（一斤） 芍药（半斤） 枸杞（半斤） 天门 \n冬麦门冬（各六两） 川芎 丹皮（各二两） 连肉（四两） 知母 地骨皮（各三两） 人参 甘草（各一两） \n上将众药用水二斗，煎一斗，去滓净，和生地黄汁同熬成膏服之 \n《局方》\\x秦艽扶羸汤\\x 治肺痿骨蒸劳嗽，或寒热往来，声哑自汗，体虚怠惰。 \n人参 秦艽 当归 鳖甲（醋炙） 紫菀茸 地骨皮 柴胡 甘草（各五分） \n水一钟半，姜五片，大枣、乌梅各一枚，煎七分，食远服。 \n\\x退热汤\\x 治急劳烦热，口干憎寒，饮食不得。 \n柴胡 龙胆草 青蒿 知母（炒） 麦冬 甘草（各一钱） \n上用童便一钟半，葱白三寸，薤白三茎、桃、柳枝各五寸。同浸一宿，平旦煎一钟， \n空心顿服，至夜再服。 \n《良方》\\x团鱼丸\\x 治骨蒸劳嗽累效。 \n贝母 前胡 知母 杏仁（各一两） 柴胡（半两） 团鱼（二个） \n上药与鱼同煮熟，取肉连汁食之。将药焙干为末，再以团鱼骨甲煮汁一盏，和药丸桐子 \n大。每服二、三十丸，煎黄 六一汤空心送下。病既安，仍服黄 六一汤调理。 \n《良方》\\x地榆散\\x 治肠风热证下血。 \n地榆 黄芩 黄连 栀子 茜根 茯苓（等分） \n上 咀。每服五钱，入韭白五寸同煎。食远温服。 \n《良方》\\x四味地榆散\\x 一名泼火散。治中暑昏迷不省人事，并治血痢。 \n地榆 赤芍药 黄连（去须） 青皮（等分） \n上为末，每服三钱，浆水调服，或新汲水亦可。若治血痢，以水煎服。 \n《本事》\\x槐花散\\x 治肠风脏毒下血。 \n槐花（炒） 侧柏叶（杵） 荆芥穗 枳壳（麸炒） \n上各等分，为末。每服二钱，空心米饮调下，或用煎汤。亦名槐花汤。 \n《外科》\\x槐花散\\x 方在外科。治肠风脏毒下血。 \n（东垣）\\x加减四物汤\\x 治肠风下血。 \n当归 川芎 生地 侧伯叶（各八分） 枳壳（麸炒） 荆芥穗 槐花（炒） 甘草（各四分） 地 \n榆条芩 防风（各六分） 乌梅（肥者，三枚） \n水二钟，姜三片，煎八分，空心温服。 \n《局方》\\x枳壳汤\\x 治大便肠风下血。 \n枳壳（二两，炒黄） 大黄连（一两，同槐花四两炒焦，去花不用） \n水二钟，浓煎，空心温服。 \n\\x枳壳散\\x 治便血，或妇人经候不调，手足烦热，胸膈不利。 \n枳壳（麸炒） 半夏曲 赤芍药 柴胡（各一钱） 黄芩（一钱半） \n水二钟，姜三片，枣一枚，煎八分，食远服。 \n《济生》\\x小蓟饮子\\x 治下焦结热，溲血崩淋等证。 \n生地（四两） 小蓟根 滑石 蒲黄（炒） 藕节 淡竹叶 山栀 炙甘草（各五钱） \n上 咀。每服五、六钱，水一钟半，煎八分，空心温服。 \n（仲景）\\x黄连汤\\x 治伤寒胸中有热，胃中有邪气，腹中痛，欲呕吐者。 \n黄连 甘草（炙） 干姜 桂枝（去皮，各三两） 人参（二两） 半夏（半升） 大枣（十二枚） \n上七味，以水一斗，煮取六升，去滓，温服一升，日三服，夜二服。 \n\\x黄连汤\\x 治便后下血，腹不痛，名温毒下血。 \n黄连 当归（各二钱） 甘草（五分） \n水二钟，煎八分，食后服。 \n（仲景）\\x黄芩汤\\x 治太阳与少阳合病，自下利。 \n黄芩（三两） 炙甘草 芍药（各二两） 大枣（十二枚） \n上四味，以水一斗，煮取三升，去滓，温服一升，日再服，夜一服。若呕者，加半夏半升，生姜三两。 \n《外台》\\x黄芩汤\\x 方在和阵。治干呕下利。 \n《直指》\\x黄芩汤\\x 治心肺蕴热，口疮咽痛膈闷，小便淋浊不利。 \n黄芩 黄连 栀子 生地 麦冬 木通 泽泻 甘草（各等分） \n上每服一两，水一钟半，煎八分，食前服。 \n\\x黄 散\\x 治热痢下赤脓，心腹烦热疼痛。 \n黄 当归 龙骨（各七钱半） 生地黄（五钱） 黄连（去须微炒，一两） 黄柏 黄芩 犀角屑 \n地榆（各半两） \n上为细末。每服二钱，不拘时，粥饮调下。 \n（河间）\\x黄芩芍药汤\\x 治泻痢腹痛，或身热炽后重，脉洪数，脓血稠粘，及阴虚内热，衄 \n吐血者。此方即前仲景之黄芩汤，但分两不同。 \n黄芩 白芍（各二钱） 甘草（一钱） \n水一钟半，煎八分，温服。腹痛甚者，加桂二分；脓血甚者，加当归、黄连各一钱。一 \n方芍药用六钱。 \n《局方》\\x木香化滞汤\\x 治痢下赤白，腹中 痛，里急后重，多热多滞者宜之。 \n木香 甘草（各七分） 人参 陈皮 黄连 泽泻 槟榔（各一钱） 白术 枳壳（麸炒） 浓朴 \n白芍药 茯苓（各钱半） \n水二钟，煎八分，食前服。 \n\\x清热渗湿汤\\x 治湿热浮肿，肢节疼痛，小水不利。 \n黄柏（盐水炒，二钱） 黄连 茯苓 泽泻（各一钱） 苍术 白术（各钱半） 甘草（五分） \n水二钟，煎八分服。如单用渗湿，去黄连、黄柏，加橘皮、干姜。 \n（河间）\\x益元散\\x 一名六一散。一名天水散。治中暑身热烦渴，小水不利。河间云∶治痢 \n之圣药，分利阴阳，去湿热，其功大矣。 \n粉甘草（一两） 桂府滑石（飞，六两） \n上为极细末。每服二、三钱，新汲水调下。一方加辰砂三钱，名朱砂益元散；一方加牛 \n黄，治烦而不得眠。 \n《局方》\\x香连丸\\x 治热泻痢疾，赤白脓血，湿热侵脾，里急后重。 \n黄连（净，十两，切如豆粒，用净吴茱萸五两，二味用热水拌和，入瓷罐内置热汤中炖 \n一日，同炒至黄连紫黄色为度，去茱萸不用） 木香（每制净黄连一两，用木香钱半） \n上为末，醋糊丸，桐子大。每服七十丸，食前，空心米饮下。 \n《良方》\\x六神丸\\x 治食积兼热，赤白痢疾，或腹痛不食，或久而不止。 \n神曲（为糊） 麦芽（炒） 茯苓 枳壳（麸炒） 木香（煨） 黄连（炒焦黑，等分） \n上为末，以神曲糊为丸，桐子大。每服五、七十丸，白汤送下。 \n\\x八正散\\x 治心经蕴热，脏腑秘结，小便赤涩，淋闭不通，及血淋等证。 \n车前子 木通 滑石（飞） 山栀 大黄（煨） 瞿麦 蓄 \n加灯心、竹叶，水煎服。 \n\\x五淋散\\x 治膀胱有热，水道不通，淋沥不止，脐腹急痛，或尿如豆汁，或如砂石，膏淋 \n、尿血并皆治之。 \n茵陈 淡竹叶（各一钱） 木通 滑石 甘草（各钱半） 栀子（炒） 赤芍药 赤茯苓（各二钱） \n水二钟，煎一钟，食前服。 \n《局方》\\x薷苓汤\\x 治夏月暑泻欲成痢者。 \n香薷 黄连（姜汁炒） 浓朴（姜炒） 扁豆（炒） 猪苓 泽泻 白术 茯苓（等分） \n上咀。每服五、六钱，水钟半，姜三片，煎七分服。 \n《局方》\\x太平丸\\x 治泄泻。 \n黄连（同吴茱萸炒，去茱萸不用） 芍药（炒，减半） \n上为末，老米糊丸服。同干姜炒，加阿胶一半为丸，名驻车丸。 \n《本事》\\x火府丹\\x 治心经积热，小便淋涩，黄胆烦渴。 \n生地黄（二两，杵膏） 木通 黄芩（炒，各一两） \n上以二味为末，加蜜丸桐子大。每服五、七十丸，木通汤下。许学士云∶一卒病渴，日 \n饮水斗许，不食者三月，心中烦闷。时在十月，余谓心经有伏热，与火府丹数服。越二日来 \n谢，云∶当日三服，渴止；又三服，饮食如故。此本治淋，用以治渴，可谓通变也。 \n\\x真珠粉丸\\x 治精滑白浊。 \n黄柏 真蛤粉（各一斤） 真珠（三两，一方代以青黛亦效） \n上为末，水糊丸，桐子大。每服百丸，空心温酒下，或加樗皮、滑石、青黛俱好。 \n《局方》\\x导赤散\\x 治心火及小肠热证，小便赤涩而渴。 \n生地 木通 生甘草（各等分） \n入竹叶二十片，水煎服。一方加人参、麦门冬。 \n\\x赤茯苓汤\\x 治膀胱实热，小便不通，口干，咽肿不利。 \n赤茯苓 猪苓 木通 车前子 瞿麦 葵子 黄芩 滑石 枳实 甘草（各等分） \n水一钟半，姜三片，煎八分，食前服。 \n《济生》\\x葵子汤\\x 治膀胱实热，腹胀，小便不通，口舌干燥。 \n葵子（微炒） 猪苓 赤茯苓 枳实 瞿麦 木通 黄芩 车前子 滑石（各一钱） 甘草（五分） \n上用水一钟半，姜煎，空心服。 \n\\x牛膝汤\\x 治砂石淋涩。 \n牛膝（一合） 麝香（少许） \n上用水煎牛膝去滓，入麝香服之。鄞县耿梦得之内患淋，下砂石剥剥有声，甚为苦楚， \n一服而愈。 \n\\x三味牛膝汤\\x 治小便不通，茎中痛，及妇人血热内结，腹坚痛。 \n牛膝（根叶一握，生用） 当归（一两） 黄芩（去黑心，半两） \n上咀。每服一两许，水一钟半，煎七分，食远服，日三。 \n\\x海金沙散\\x 治膏淋。 \n海金沙 滑石（各一两） 甘草（二钱半） \n上为细末。每服二钱，灯草汤空心调下。 \n\\x茵陈汤\\x 治黄胆发热，大小便涩。 \n茵陈 栀子仁（各二钱） 赤茯苓 葶苈（各钱半） 枳实 甘草（各五分） \n水一钟半，姜三片，煎八分，食前服。 \n《活人》\\x茯苓渗湿汤\\x 治黄胆湿热，呕吐而渴，身目俱黄，小便不利，食少而热。 \n白茯苓 泽泻 茵陈 青皮 陈皮 防己（各五分） 栀子 黄芩（各八分） 黄连 枳实（各七 \n分） 苍术 白术（各一钱） \n上水煎服。 \n（东垣）\\x当归拈痛汤\\x 治湿热为病，肢节烦疼，肩背沉重，胸膈不利，手足遍身流注疼痛，热肿等证。 \n羌活 黄芩 炙甘草 茵陈（各五钱） 人参 苦参 升麻 干葛 苍术（各二钱） 防风 归 \n身白术 知母 猪苓 泽泻（各一钱半） \n上 咀。每服一两，水煎空心服，临睡再服。 \n《活人》\\x犀角散\\x 治香港脚冲心，烦喘闷乱，头痛口干，坐卧不得。 \n犀角屑 枳壳（麸炒） 沉香（各七钱半） 槟榔 紫苏（茎叶） 麦门冬 赤茯苓（各一两） 木 \n香防风（各半两） 石膏（生用，研，二两） \n上 咀。每服八钱，以水一钟半，煎八分，去 ，入淡竹沥一合，更煎一、二沸。不拘时温服。 \n（东垣）\\x清燥汤\\x 治六七月间湿热成痿，肺金受邪，腰以下痿软，瘫痪不能动，行走不正，两足欹侧。 \n柴胡 酒黄柏 黄连 麦冬（各三分） 生地 人参（各一钱） 炙甘草 猪苓 白茯苓 橘红 \n神曲 泽泻（各五分） 白术 苍术（各八分） 黄 （钱半） 知麻（三分） 五味子（九粒） \n上 咀。每服半两，水二盏，煎一盏，稍热空心服。 \n\\x苍术汤\\x 治湿热腰腿疼痛。 \n苍术（三钱） 柴胡（二钱） 黄柏 防风（各一钱） \n上用水煎，空心服。 \n（丹溪）\\x二妙散\\x 治湿热在经，筋骨疼痛，如有气，加气药；如血虚，加补血药；如痛甚 \n，加姜汁热辣服之。 \n黄柏（炒） 苍术（去皮，炒制，等分） \n上为末。捣生姜煎沸汤调服。此二物皆有雄壮之气，如气实者，加少酒佐之。此即《集 \n要》二神汤，各三钱半，用水煎，空心服。 \n一方以二妙为君，加甘草、羌活（各二钱） 陈皮、芍药（各一钱） 威灵仙（酒炒，五分） 为末，服之佳。 \n\\x加味二妙丸\\x 治两足湿痹，疼痛如火燎，从两足跗热起，渐至腰胯，或麻痹痿软，皆是 \n湿热为病，此方主之。 \n归尾 川牛膝 川萆 防己 龟板（酥炙，各一两） 苍术（米泔浸炒，四两） 黄柏（二两， \n酒浸，晒干） \n酒煮面糊为丸，桐子大。每服百丸，空心姜、盐汤送下。 \n（《丹溪》）\\x苍术黄柏丸\\x 治湿热，食积，痰饮，流注，香港脚。 \n苍术（盐水炒） 黄柏（盐水炒） 防己 南星 川芎 白芷 犀角 槟榔（等分） \n上为末，酒糊丸服。血虚，加牛膝、龟板；肥人，加痰药。 \n《正传》\\x虎胫骨丸\\x 治两足痿弱软痛，或如火焙，从足踝下上冲腿膝等证因热所成者，经验。 \n牛膝 归尾（各二两） 龟板（酥炙） 虎胫骨（酥炙） 防己（各一两） 苍术（米泔浸一宿） 黄 \n檗（酒浸日晒，各四两） \n上为细末，面糊为丸，桐子大。每服百余丸，空心姜、盐汤送下。一方加炮附子五钱。 \n（河间）\\x苦参丸\\x 治血虚风热着痹。 \n苦参（二两，取粉） 丹参（炙） 沙参 人参 防风（去叉） 五加皮 蒺藜（炒去刺） 乌蛇 \n（酒浸取肉） 蔓荆子 龟板（酥炙） 虎骨（酥炙） 玄参（各一两） \n上为细末，用不蛀皂角一斤锉碎，以水三升挪取汁，于无油铁器熬成膏，加炼蜜 \n四两和丸，桐子大。 \n每服十五丸至二十丸，食后良久，夜卧共三服，荆芥薄荷酒下。 \n（陈氏）\\x苦参丸\\x 方在外科。 \n治遍身瘙痒，癣疥疮疡。 \n（钱氏）\\x苦参丸\\x 方在痘疹。治痘后溃烂，疮毒疥癞。 \n\\x朱砂凉膈丸\\x 治上焦虚热，肺脘咽膈有气如烟抢上。 \n黄连 山栀（各一两） 人参 茯苓（各半两） 朱砂（三钱，另研） 冰片（五分，另研） \n上为细末，炼蜜为丸，桐子大，朱砂为衣。熟水送下五、七丸，日进三服。食后。 \n（东垣）\\x朱砂安神丸\\x 一名黄连安神丸。治心神烦乱，发热怔忡不寐，或寐中惊悸头运等证。 \n生地 朱砂（另飞为衣） 当归（各一钱） 甘草（五分） 黄连（一钱半） \n汤浸蒸饼为丸，黍米大。每服十五丸至二十丸，津液咽之，或食后用温水、凉水送下亦可。 \n（钱氏）\\x安神丸\\x 治热渴心闷，脉实颊赤口燥。 \n麦冬 马牙硝 白茯苓 寒水石 山药 甘草（各五钱） 朱砂（一两） 龙脑（一字） \n上为末，炼蜜丸，芡实大。每服一丸，沙糖水化下。 \n《秘旨》\\x安神丸\\x 方在小儿。治心虚惊悸。 \n\\x十味安神丸\\x 方在小儿。治虚惊。 \n\\x七味安神丸\\x 方在小儿。治心热多惊。 \n《集验》\\x龙脑安神丸\\x 治男妇小儿五积癫痫，不论远近，发作无时，但服此药，无不痊愈。 \n龙脑（研） 麝香（研） 牛黄（研，各三钱） 犀角屑 人参 茯神 麦冬 朱砂（飞，各二两） \n桑白皮（炒） 地骨皮 甘草（炙，各一两） 马牙硝（二钱） 金箔（三十五片） \n为细末，炼蜜丸，弹子大，金箔为衣。寒用热水，热用凉水，不拘时化下一丸，小儿半 \n丸。如病二、三年者，日进三服。若男妇虚劳，喘嗽发热者，用新汲水化下，其喘满痰嗽立止。 \n（万氏）\\x龙脑安神丸\\x 方在小儿。治惊痰，及痘中昏闷谵妄。 \n\\x抑青丸\\x 治肝火。 \n黄连（姜汁炒） \n上单用一味为末，粥丸，温水下。 \n（钱氏）\\x抑青丸\\x 方在小儿。治肝热急惊搐搦。 \n\\x泻青丸\\x 治肝胆火，并小儿急惊发搐，眼赤睛疼。 \n龙胆草 当归 川芎 防风 羌活 山栀 大黄（等分） \n炼蜜为丸，桐子大。每服五十丸。 \n\\x泻金丸\\x 治肺火。 \n用黄芩为末，滴水丸。白汤下。 \n（丹溪）\\x茱连丸\\x 治湿热吐酸。 \n黄连（陈壁土炒，二两） 黄芩（制同，一两） 陈皮 苍术（米泔浸） 吴茱萸（煮少时，浸半 \n日，晒干，各一两） 或加桔梗 茯苓各一两。 \n上为末，神曲糊丸，绿豆大。每服二、三十丸，食后津液送下。 \n\\x左金丸\\x 治肝火胁肋刺痛，或发寒热，或头目作痛，淋秘、泄泻，一切肝火等证。 \n黄连（六两，炒） 吴茱萸（一两，汤泡片时，炮干用） \n上为末，粥丸，梧子大。白术、陈皮煎汤下三、四、五十丸。 \n\\x大补丸\\x 治阴火。 \n黄柏（盐酒炒褐色） \n米粥丸。血虚，四物汤送下；气虚，四君子汤送下。 \n\\x大造丸\\x 此方治阴虚血热，能使耳目聪明，须发乌黑，有夺造化之功，故名大造。亦治 \n心风失志，虚劳水亏等证。 \n紫河车（头生壮盛者一具，以米泔洗净，少加酒，蒸极烂捣膏，以山药末收，烘干用； \n或洗净即以新瓦上焙干用） 败龟板（自死者，酥炙，二两） 黄柏（盐酒炒，两半） 杜仲（酥炙， \n两半） 牛膝（酒洗，一两二钱） 天门冬 麦门冬（各一两二钱） 熟地（二两半，用砂仁末六钱，茯 \n苓二两一块，同稀绢包，入好酒煮七次，去茯苓不用） 夏加五味子七钱 \n上除熟地黄另杵外，共为末，用酒煮米糊同熟地膏捣丸，桐子大；或蜜丸亦可。每服八 \n、九十丸，空心临卧盐汤、姜汤任下，冬月酒下。妇人，加当归二两，去龟板；男子遗精白 \n浊，妇人带下，加牡蛎一两半。 \n（丹溪）\\x大补阴丸\\x 降阴火，补肾水。 \n黄柏（盐酒炒） 知母（盐酒炒，各四两） 熟地（酒洗，蒸，捣烂） 龟板（酥炙黄，各六两） \n上为细末，用猪脊髓蒸熟，和炼蜜同捣为丸，桐子大。每服五、六十丸，空心姜、盐、酒送下。 \n《秘传》\\x大补天丸\\x 治男妇虚损劳伤，形体羸乏，腰背疼痛，遗精带浊。 \n紫河车（初胎者一具，米泔洗净，入小砂罐内，加水一碗煮沸，候冷取起，放竹篮中， \n四围用纸糊密，烘干为末，入群药和匀） 黄柏（蜜炒） 知母（乳炒） 龟板（酥炙，各三两） \n怀熟地（五两，捣） 牛膝（酒洗） 肉苁蓉（酒洗） 麦门冬 山药（炒） 虎胫骨（酥炙） 黄 （ \n蜜炙） 茯神（各两半） 杜仲（制） 何首乌（制） 人参 白芍药（冬月一两） 枸杞（各二两） 生 \n地（酒洗，沙锅煮烂，捣） 天门冬 当归（酒洗） 北五味（各一两） 冬加干姜（半两，炒黑） \n上为细末，用猪脊髓三条蒸熟，同炼蜜和捣为丸，桐子大。每服八十丸，空心淡盐汤下，冬月酒下。 \n\\x大补地黄丸\\x 治精血枯涸燥热。 \n黄柏（盐酒炒） 熟地（酒蒸，各四两） 当归（酒洗） 山药（炒） 枸杞（各三两） 知母（盐酒 \n炒） 山茱萸 白芍药（各二两） 生地（二两半） 肉苁蓉（酒浸） 玄参（各两半） \n上为末，炼蜜丸，桐子大。每服七、八十丸，空心淡盐汤送下。 \n（丹溪）\\x补阴丸\\x 一名虎潜丸。降阴火，滋肾水。 \n黄柏（制） 知母（制） 熟地（酒洗，各三两） 龟板（酥炙，四两） 白芍（酒炒） 当归 牛膝 \n（各二两） 虎胫骨（酥炙） 锁阳（酥炙） 陈皮（各两半） \n上为细末，酒煮羯羊肉为丸，桐子大。冬加干姜半两。每服五、六十丸，姜盐汤，或酒下。 \n（节斋）\\x补阴丸\\x \n黄柏 知母（俱酒炒） 龟板（各三两） 熟地（五两） 锁阳 枸杞 天冬 白芍（各二两） 五味 \n（一两） 干姜（五钱） \n炼蜜入猪脊髓三条捣丸，桐子大。每服八、九十丸，空心淡盐汤送下，冬月用酒。 \n\\x三补丸\\x 治三焦火热。 \n黄连 黄芩 黄柏 \n滴水丸，桐子大。白汤送下，或淡盐汤亦可。 \n（东垣）\\x滋肾丸\\x 降肾火。桂与火邪同体，此寒因热用法也。凡不渴者，病在下焦，宜用 \n之。《良方》云∶或肾虚足热，小便不利，肚腹肿胀，皮肤胀裂，眼睛突出，此神剂也。 \n黄柏（二两，酒拌，阴干） 知母（同上） 肉桂（二钱） \n为细末，熟水为丸。百沸汤空心送下二百丸。 \n\\x加味虎潜丸\\x 治诸虚不足，腰腿疼痛，行步无力。壮元气，滋肾水。 \n熟地黄（八两） 人参 黄 （炙） 当归 杜仲（酥炙） 牛膝（酒蒸） 锁阳（酒洗） 龟板（ \n酥炙） 菟丝子（制） 茯苓 破故纸（炒） 黄柏（蜜水炒） 知母（酒炒） 虎骨（酥炙，各一两） \n山药（炒） 枸杞（各二两） \n上炼蜜加猪脊髓酒蒸熟同捣丸，桐子大。每服百余丸，空心淡盐汤，或酒任下。 \n加味坎离丸 生精养血，升水降火。 \n川黄柏（八两，分四分，用清酒、盐水、人乳、蜜水各浸二两，晒干，炒褐色） 熟地（八两， \n用茯苓四两打碎，砂仁二两，三味同入绢袋中，好酒三瓶煮干，去茯苓、砂仁，止用地黄） \n知母（八两，盐酒浸炒） 白芍（酒浸一日，晒干） 当归 川芎（各四两） \n上为末，同铺筐中，日晒夜露，三日为度，炼蜜丸，桐子大。每服八、九十丸，空心盐 \n汤，冬月温酒任下。 \n\\x三才封髓丹\\x 降心火，益肾水。 \n天门冬 熟地黄 人参（各一两） 黄柏（炒褐色，三两） 砂仁（炒，半两） 甘草（炙，七钱） \n上为末，面糊丸，桐子大。每服五、七十丸，以肉苁蓉五钱，切片酒浸一宿，次日煎三 \n、四沸，空心送下。 \n\\x当归龙荟丸\\x 治肝经实火，大便秘结，小便涩滞，或胸膈作痛，阴囊肿胀，凡肝经实火 \n皆宜用之，及一切躁扰狂越，惊悸不宁等证。 \n当归 龙胆草 栀子仁 黄连 黄柏 黄芩（各一两） 芦荟 大黄 青黛（各五钱） 木香（二 \n钱半） 麝香（五分，另研） \n上为末，神曲糊丸，桐子大。每服二、三十丸，姜汤、白汤任下。 \n《良方》\\x芦荟丸\\x 治疳癖肌肉消瘦，发热潮热，饮食少思，口干作渴，或肝火食积，口 \n鼻生疮，牙龈蚀烂等证。 \n芦荟 胡黄连 黄连（炒焦） 木香 白芜荑（炒） 青皮（各五钱） 当归 茯苓 陈皮（各两 \n半） 甘草（炒，七钱） \n上为末，米糊丸，桐子大。每服七、八十丸，米汤下。 \n\\x大芦荟丸\\x 方在小儿。治小儿肝脾疳积发热。 \n\\x加减芦荟丸\\x 方在小儿。治证同前。 \n\\x三圣丸\\x 治嘈杂神效。 \n白术（四两，炒） 橘红（炒，一两） 黄连（炒，五钱） \n上为细末，神曲糊丸，绿豆大。每服五、六十丸，姜汤下。 \n\\x术连丸\\x 治嘈杂。 \n白术（四两，土炒） 黄连（一两，姜汁炒） \n上为末，神曲糊丸，黍米大。每服百余丸，姜汤下。 \n\\x软石膏丸\\x 治嘈杂嗳气。 \n软石膏（ ） 半夏（制） 南星（制） 香附子（炒） 栀子仁（炒，各等分） \n上为细末，米粥丸，桐子大。每服五、七十丸，姜汤下。 \n\\x地榆丸\\x 治血痢下血极效。 \n地榆（微炒） 当归（微炒） 阿胶（糯米炒） 黄连（去须） 诃子（取肉炒） 木香（晒干） \n乌梅肉（各半两） \n上为细末，炼蜜丸，梧子大。每服三、五十丸，空心，或食前，陈米饮吞下。 \n槐角丸 治五种肠风下血，并痔漏脱肛。 \n槐角（炒） 黄芩 地榆 当归 防风 枳壳（麸炒） \n上等分，为细末，米酒、面糊丸，桐子大。每服五、六十丸，空心清米饮送下，极效。 \n一方有乌梅肉。 \n《御药》\\x阿胶丸\\x 治肠风下血。 \n黄连 阿胶（炒珠） 赤茯苓（等分） \n上将连、茯为末，阿胶用酒熬化，和末，众手为丸。食前米汤送三、五十丸。或共为末 \n糊丸亦可。 \n\\x聚金丸\\x 治酒毒大肠蓄热下血。 \n黄芩 防风（各二两） 黄连（四两，半生半酒炒） \n上为末，醋糊丸，梧子大。每服七、八十丸，空心米饮下。 \n\\x脏连丸\\x 治远年近日肠风脏毒下血。 \n大鹰爪黄连（半斤） 槐米（二两） 枳壳（一两） 防风 粉草 槐角 香附 牙皂 木香（各五钱） \n上用陈仓米三合，同香附一处为末，外药共为细末，用猪大脏约长二尺，洗净，装入米 \n、附缚定，量用水二大碗，沙锅炭火煮，干即添水，漫火煮烂如泥，取起和药捣匀，丸桐子 \n大。每空心米饮下七、八十丸。忌面、蒜、生冷、煎炙之物。一料病痊。 \n《局方》\\x酒蒸黄连丸\\x 治一切热泻便血，并伏暑发热，解酒毒。 \n黄连（半斤，用净酒二升，浸以丸器，置甑上蒸至烂，取出晒干） \n上为末，滴水丸。每服五十丸，食前温水下。 \n\\x黄连丸\\x 治肠红便血，痔疮肿痛。 \n黄连 吴茱萸（等分） \n上二味，用滚汤同漉过，罨一、二日，同炒拣开，各另为末，米糊丸，桐子大。每服二 \n、三钱。粪前红，服茱萸丸；粪后红，服黄连丸，俱酒上。此与左金丸稍同。 \n\\x猪脏丸\\x 方在外科。治大便痔漏下血。 \n\\x保和丸\\x 方在小儿。治饮食酒积停滞。 \n\\x四顺清凉饮\\x 方在攻阵。治脏腑血热，烦渴秘结。 \n（仲景）\\x白头翁汤\\x 治热痢下重者。 \n白头翁（二两） 黄连 黄柏 秦皮（各三两） \n上四味，以水七升，煮取二升，去滓。温服一升，不愈，再服一升。 \n\n\n\n<目录>卷之五十八宙集·古方八阵\n\n<篇名>热阵\n\n属性：（仲景）\\x理中丸\\x 即名人参理中汤。治太阴即病，自利不渴，阴寒腹痛，短气咳嗽，霍乱 \n呕吐，饮食难化，胸膈噎塞，或疟疾瘴气瘟疫，中气虚损，久不能愈，或中虚生痰等证。 \n人参 白术（炒） 干姜（炒） 炙甘草（各三两） \n上四味，捣筛为末，蜜丸，鸡子黄大。以沸汤数合和一丸研碎，温服之，日三、四，夜 \n二服；腹中未热，益至三、四丸。然不及汤，汤法以四物根据数切，用水八升，煮取三升，去 \n渣，温服一升，日三服。原论加减法，详在霍乱门述古条中。宾按∶上方两数，乃汉时权度 \n，今后世所用，惟每味数钱，而甘草半之，酌宜可也。 \n\\x附子理中汤\\x 治证如前，而中气虚寒，腹痛甚者。又或入房腹痛，手足厥冷，或食冷犯寒等证。 \n即前方加制附子一、二、三钱，随宜用之。其有寒甚势急者，不妨生用，或炮用亦可。 \n外科附子理中汤有芍药、茯苓，无甘草、干姜。 \n\\x附子理中丸\\x 治阴寒肾气动者。 \n即前附子理中汤去白术，炼蜜丸服。 \n\\x理中加丁香汤\\x 治中脘停寒，喜辛物，入口即吐即哕。 \n即前附子理中汤加丁香十粒，甚或兼痛者，可加至一、二钱。若以理中加木香，即名木香理中汤。 \n\\x加味理中汤\\x 治脾肺俱虚，咳嗽不已。 \n人参 白术 茯苓 炙甘草 陈皮 半夏 干姜 细辛 北五味（等分） \n上咀。每服三钱，姜三片，枣一枚，煎七分，食远服。 \n《局方》\\x胡椒理中汤\\x 治肺胃虚寒，气不宣通，咳喘逆气，虚痞噎闷，胁腹满痛，短气 \n不能饮食，呕吐痰水不止。 \n白术（五两） 干姜 炙甘草 胡椒 良姜 荜茇 陈皮 细辛 款冬花（去梗，各四两） \n上 咀。每服五、七钱，水一钟半，煎七分，食远温服。或炼蜜丸，桐子大。每 \n服三、五十丸，白汤、温酒、米饮任下，无时，每日二服。 \n《选方》\\x八味理中丸\\x 治脾胃虚寒，饮食不化，胸膈痞闷，或呕吐泄泻。 \n人参 干姜（炒，各一两） 白术（四两，炒） 白茯苓 麦芽（炒，二两） 甘草（炙） 神曲（炒） \n砂仁（炒，各一两半） \n上为细末，炼蜜为丸，每丸重一钱。空心服一丸，姜汤嚼下。 \n\\x枳实理中丸\\x 治伤寒寒实结胸。 \n人参 白术 茯苓 甘草 干姜（各二两） 枳实（十六片） \n上为细末，炼蜜丸，鸡子黄大。每服一丸，热汤化下，连进二、三服。 \n\\x理中化痰丸\\x 治脾胃虚寒，痰涎内停，呕吐少食，或大便不实，饮食难化，咳唾痰涎。 \n此中气虚弱，不能统涎归源也。 \n人参 白术（炒） 干姜（炮） 茯苓（各二两） 炙甘草（一两） 半夏（制，三两） \n姜汤煮面糊丸，桐子大。每服四、五十丸，白汤送下。 \n\\x治中汤\\x 治脾胃不和，呕逆霍乱，中满虚痞，或泄泻。此即理中汤加青皮、陈皮也。 \n人参 白术 干姜（炮） 炙甘草 青皮 陈皮（等分） \n上每服五钱，水煎服。如呕，加半夏。 \n\\x丁香温中汤\\x 治同前。 \n即前治中汤加丁香、去半夏。 \n《良方》\\x温胃汤\\x 治忧思结聚，脾肺气凝，元阳受损，大肠与胃气不平，胀满上冲，饮 \n食不下，脉虚而紧满。 \n附子（制） 浓朴 当归 白芍药 人参 甘草（炙） 陈皮（各一钱） 干姜（炮，一钱） 川椒 \n（去合口，炒出汗，三分） \n水一钟半，姜三片，煎一钟，食远服。 \n（东垣）\\x温胃汤\\x 治服寒药多，致脾胃虚弱，胃脘痛。 \n白豆蔻 人参 泽泻（各三分） 益智 砂仁 浓朴 甘草 干姜 姜黄（各四分） 黄 陈 \n皮（各七分） \n上为细末。每服三钱，水一盏，煎至半盏，食前温服。 \n（仲景）\\x四逆汤\\x 又名通脉四逆汤。治伤寒阴证自利，里寒外热，脉沉身痛而厥。 \n甘草（炙，二两） 干姜（炮，三两） 附子（一枚，破八片，生用） \n上 咀。以水三升，煮取一升二合，分二次温服，其脉即出者愈。面色赤者，加 \n葱九茎；腹中痛者，去葱，加芍药二两；呕者，加生姜二两；咽痛者，加桔梗一两；利止脉 \n不出者，加人参一两。 \n（仲景）\\x四逆加人参汤\\x 治伤寒恶寒，脉微而复利。即于前方内加人参一两。 \n（仲景）\\x四逆加猪胆汁汤\\x 治伤寒吐下后，汗出而厥，四肢拘急，脉微欲绝者。 \n即于四逆汤内加入猪胆汁半合。 \n（仲景）\\x茯苓四逆汤\\x 治伤寒汗下后，病仍不解，烦躁者。 \n茯苓（六两） 人参（一两） 甘草（炙，二两） 干姜（一两半） 附子（一枚，生用，去皮，切八片） \n上五味，以水五升，煮取三升，去渣，温服七合，日三服。 \n\\x茱萸四逆汤\\x 治厥阴中寒，小腹痛甚。 \n吴茱萸（汤泡） 附子（炮） 干姜（各二钱） 炙甘草（钱半） \n水一钟半，煎七分，热服。 \n（韩氏）\\x茵陈四逆汤\\x 治发黄脉沉细迟，肢体逆冷，腰以上自汗。 \n茵陈（二两） 炙甘草（一两） 干姜（炮，两半） 附子（一个，炮，作八片） \n上分四帖，水煎服。 \n（仲景）\\x当归四逆汤\\x 治伤寒手足厥寒，脉细欲绝者，或下利脉大，肠鸣者，虚也。及其 \n人内有久虚者，宜当归四逆加吴茱萸生姜汤主之。 \n当归 桂枝 芍药 细辛（各三两） 甘草 通草（各二两） 大枣（二十五枚，擘） \n上七味，以水八升，煮取三升，去滓，温服一升，日三服。 \n\\x四逆散\\x 方在散阵。治阳邪亢热，血脉不通，四肢厥逆。 \n（仲景）\\x附子汤\\x 治少阴病，得之一二日，口中和，其背恶寒者，当灸之，附子汤主之， \n并治少阴病身体痛，手足寒，骨节痛，脉沉者。 \n附子（二枚，去皮，破八片） 人参（二两） 白术（四两） 芍药 茯苓（各三两） \n上五味，以水八升，煮取三升，去渣，温服一升，日三服。 \n《三因》\\x附子汤\\x 治风寒湿痹，骨节疼痛，皮肤不仁，肌肉重着，四肢缓纵。 \n附子（生） 白芍药 桂心 甘草 白茯苓 人参 干姜（各三两） 白术（一两） \n上 咀。每服四钱，水煎服。 \n\\x生附汤\\x 治寒湿腰痛。 \n附子（生用） 白术 茯苓 牛膝 浓朴 干姜 炙甘草（各一钱） 苍术 杜仲（姜炒，各二钱） \n水二钟，生姜三片，红枣二枚，煎八分，食前服。 \n\\x参附汤\\x 方在补阵。治元阳不足，喘急呃逆，呕恶厥冷等证。 \n（仲景）\\x术附汤\\x 方在补阵。治中寒中气不足，逆冷，痰盛，口噤等证。 \n\\x 附汤\\x 方在补阵。治气虚阳弱，虚汗倦怠。 \n《济生》\\x术附汤\\x 方在补阵。治寒湿腰冷重痛，小便自利。 \n《金匮》\\x桂枝附子汤\\x 治伤寒八九日，风湿相搏，身体疼烦，不能转侧，不呕不渴，脉 \n浮虚而涩者。 \n桂枝（四两，去皮） 生姜（三两，切） 附子（三枚，炮，去皮，各破八片） 甘草（三两，炙） 大枣 \n（十二枚，擘） \n上五味，以水六升，煮取二升，去渣，分温三服。 \n《金匮》\\x白术附子汤\\x 治伤寒八九日，风湿相搏，身体疼烦，不能转侧，不呕不渴，脉 \n虚浮而涩，若大便坚，小便自利者，去桂枝，此方主之。 \n白术（二两） 附子（一枚，炮，去皮） 甘草（炙，一两） 生姜（一两半，切） 大枣（六枚） \n上五味，以水三升，煮取一升，去滓，分温三服。一服觉身痹，半日许再服。三日服都 \n尽，其人如冒状，勿怪，即是术、附并走皮中，逐水气未得除故耳。 \n《金匮》\\x甘草附子汤\\x 治风湿相搏，骨节疼烦，掣痛不得屈伸，近之则痛剧，汗出短气 \n，小便不利，大便反快，恶风不欲去衣，或身微肿者，此主之。 \n甘草（炙） 白术（各二两） 附子（二枚，炮，去皮） 桂枝（四两，去皮） \n上四味，以水六升，煮取三升，去渣，温服一升，日三服。初服得微汗则解，能食。汗 \n后复烦者，服五合。恐一升多者，服六、七合为妙。 \n《良方》\\x姜附汤\\x 治霍乱转筋，手足厥冷，或吐逆身冷，脉微急，用此药救之。此即仲景干姜附子汤。 \n干姜（一两） 附子（一个，生用） \n上每服半两，水煎。外科姜附汤有人参、白术。 \n\\x生姜附子汤\\x 治岭南瘴厉，内虚发热，或寒热往来，呕痰吐逆，头疼身痛，或汗多烦躁 \n引饮，或自利小便赤，兼主卒中风。 \n附子（一枚，如法制，分四服） \n上每服水一钟，生姜十片，煎六分，微温服。 \n\\x干姜附子汤\\x 治瘴毒阴证发热，或烦躁，手足冷，鼻尖冷，身体重痛，舌上胎生，引饮 \n烦渴，或自利呕吐，汗出恶风。 \n大附子（一枚，制，分四服） \n上每服加炮干姜二钱同煎，温服；热甚者，冷服。 \n《宝鉴》\\x羌活附子汤\\x 治呃逆。 \n羌活 附子 干姜（炮） 茴香（各一钱） 木香（五分） \n水钟半，枣二枚，煎服。《三因方》木香作丁香。 \n（仲景）\\x芍药甘草附子汤\\x 治发汗病不解，反恶寒者，虚故也。 \n芍药 甘草（炙，各三两） 附子（一枚，炮，去皮，切八片） \n上三味，以水五升，煮取一升五合，去渣，分温服。 \n《活人》\\x附子八味汤\\x 治气虚中寒，香港脚等症。 \n附子（炮，去皮脐） 人参 干姜（炮） 芍药 茯苓 甘草（炙） 桂心（各二两） 白术（四两） \n上每服五、七钱，水一钟半，煎七分，食前温服。又方去桂心，加干熟地黄三两。 \n\\x六物附子汤\\x 方在外科。治四气流注太阴，四肢骨节烦疼，浮肿，小水不利。 \n\\x小建中汤\\x 方在补阵。治虚劳里急，腹痛失精，四肢酸疼，咽干口燥等证。 \n《局方》\\x大建中汤\\x 方在补阵。治阳虚气血不足，腰脚筋骨疼痛。 \n\\x八味大建中汤\\x 方在补阵。治中气不足，厥逆呕吐，挛急阴缩，腹痛虚火等证。 \n\\x三建汤\\x 治元阳素虚，寒邪外攻，手足厥冷，六脉沉微，大小便数滑，凡中风潮涎，不 \n省人事，伤寒阴证，皆可用之。 \n大附子 大川乌 天雄（各制用，三钱） \n上用水二钟，姜十片，煎一钟，不拘时，或温服，或冷服。自汗加桂、浮小麦；气逆加 \n沉香；胃冷加丁香、胡椒。 \n（仲景）\\x炙甘草汤\\x 一名复脉汤。治伤寒脉结代，心动悸。 \n炙甘草（四两） 生姜 桂枝（去皮，各三两） 人参 阿胶（各二两） 生地黄（一斤） 麦冬（去心， \n半斤） 麻子仁（半斤） 大枣（十二枚，擘） \n上九味，以清酒七升，水八升，先煮八味，取三升，去渣，内胶烊尽，温服一升，日三服。 \n（仲景）\\x桂枝甘草汤\\x 治发汗过多，其人叉手自冒心，心下悸，欲得按者。 \n桂枝（四两，去皮） 甘草（二两） \n上二味，以水三升，煮取一升，去渣，顿服。 \n（陶氏）\\x回阳返本汤\\x 治阴盛格阳，阴极发躁，渴而面赤，欲坐泥水中，脉则无力，或脉 \n全微欲绝者。服后脉微出者生，顿出者死。 \n人参 制附子 炮姜 炙甘草 五味子 麦冬 陈皮 腊茶 \n面戴阳者，下虚也，加葱七茎，黄连少许，用澄清泥浆水一钟煎之。临服入蜜五匙，顿 \n冷服之，取汗为效。 \n\\x华佗救脱阳方\\x 治寒中三阴，口噤失音，四肢强直，挛急疼痛，似乎中风，及厥逆唇青 \n，囊缩无脉，或卒倒尸厥脱阳等证。 \n先急用葱白一握，微捣碎，炒热，用布包熨脐下，以二包更替熨之。甚者仍灸气海、关 \n元二、三十壮。脉渐出，手足渐温，乃可生也。 \n次用附子一个，重一两者，切八片，白术、干姜各五钱，木香二钱，同用水二钟，煎一 \n钟，候冷灌服，须臾，又进一服，或煎服回阳等汤。 \n（仲景）\\x旋复代赭石汤\\x 治伤寒若汗或吐下解后，心下痞硬，噫气不除者。 \n旋复花 甘草（炙，各三两） 人参（二两） 生姜（五两，切） 代赭石（一两） 大枣（十二枚，擘） \n半夏（半升，洗） \n上七味，以水一斗，煮取六升，去滓，再煎取三升，温服一升，日三服。 \n（仲景）\\x浓朴生姜甘草半夏人参汤\\x 治发汗后腹胀满。 \n浓朴（去皮尖） 生姜（切，各半斤） 半夏（半升，洗） 人参（一两） 甘草（二两，炙） \n上五味，以水一斗，煮取三升，去滓，温服一升，日三服。 \n《简易》\\x十味锉散\\x 治中风血弱，臂痛连及筋骨，举动艰难。 \n附子（三两，炮） 当归 黄 （炙） 白芍药（各二两） 川芎 防风 白术（各两半） 肉桂（一两） \n熟地 茯苓（各七钱半） \n上 咀。每服五、七钱，水钟半，姜八片，枣三枚，煎八分，食后、临卧服。 \n《奇效》\\x芎术汤\\x 治寒湿头痛，眩运痛极。 \n川芎 附子（生，去皮脐） 白术（各三钱） 桂心（去皮） 甘草（各一钱） \n水一钟半，生姜七片，枣二枚，煎八分，食远服。 \n\\x正元散\\x 治眩晕阳虚。 \n红豆（炒） 干姜（炮，各三钱） 人参 白术 炙甘草 茯苓（各二两） 附子（炮，去皮脐） \n川芎 山药（姜汁炒） 乌药 干葛（各一两） 川乌（炮，去皮脐） 肉桂（各五钱） 黄 （炙，两半） \n陈皮（二钱） \n上 咀。每服三钱，水一钟，姜三片，枣一枚，入盐少许，煎服。 \n《金匮》\\x生姜半夏汤\\x 治胸中似喘不喘，似呕不呕，似哕不哕，彻心中愦愦然无奈者。 \n半夏（半升） 生姜汁（一升） \n上二味，以水三升，煎半夏取二升，纳生姜汁，煮取一升半，小冷，分四服，日三夜一 \n服。病止，停后服。 \n《金匮》\\x半夏干姜散\\x 治干呕，或吐逆痰延。 \n半夏（制） 干姜（炙，等分） \n上二味杵为散。取方寸匕，用浆水一升半，煎取七合，去 ，顿服之。 \n（仲景）\\x甘草干姜汤\\x 治少阴伤寒，小便色白，吐逆而渴，动气因下反剧，身虽有热反倦 \n，及肺痿吐涎沫而不咳，口不渴，小便数，遗尿，肺中冷，土虚不能制下，眩晕，多涎唾等 \n证。杨仁斋曰∶治男女诸虚出血，胃寒不能引气归元，无以收约其血者。《良方》名姜草汤 \n，治阴盛于阳，寒而呕血。 \n甘草（炙，四两） 干姜（炮，二两） \n上咀。以水三升，煮取一升五合，分温再服。仁斋曰∶等分，每服三钱，食前煎服。 \n\\x橘皮干姜汤\\x 治恶心呕哕。 \n人参 干姜 肉桂（各一钱） 陈皮 通草（各钱半） 甘草（五分） \n水一钟半，煎八分服。 \n《金匮》\\x橘皮汤\\x 亦名生姜橘皮汤。治干呕哕，若手足厥者。 \n橘皮（四两） 生姜（半斤） \n上二味，以水七升，煮取三升，温服一升，下咽即愈。 \n（万氏）\\x橘皮汤\\x 方在痘疹。行滞消痰，止呕吐。 \n《金匮》\\x橘皮竹茹汤\\x 治哕逆。 \n橘皮（二斤） 竹茹（二升） 生姜（半斤） 甘草（五两） 人参（一两） 大枣（三十枚） \n上六味，以水一斗，煮取三升，温服一升，日三服。 \n\\x小半夏汤\\x 方在和阵。治呕吐及心下有饮者。 \n《三因》\\x丁香散\\x 治呃逆。 \n丁香 柿蒂（各一钱） 炙甘草 良姜（各五分） \n上为末。热汤点服二钱，不拘时。 \n\\x丁香煮散\\x 治翻胃呕逆。 \n丁香 石莲肉（各十四枚） 北枣（七枚，切碎） 生姜（七片） 黄秫米（半合，洗） \n水一碗半，同煮稀粥，去药啜粥。 \n《简易》\\x丁香散\\x 治反胃呕逆，粥食不下。 \n大附子（一枚，坐于砖石上，四面着火，渐渐逼热，淬入生姜汁中，浸少时，如法再淬， \n约尽姜汁半碗许为度，去皮焙干为末） 丁香（二钱，研） \n二味匀和，每服二钱，水一钟，粟米同煎七分服。 \n（杨氏）\\x丁香茯苓汤\\x 治脾胃虚寒，宿食留滞，痞塞疼痛，气不升降，以致呕吐涎沫，或 \n呕酸水，不思饮食。 \n半夏（制） 橘红 茯苓（各一两半） 丁香 附子（制） 肉桂 砂仁（各五钱） 干姜（炮） 木 \n香（各一两） \n每服四钱，水一钟半，姜七片，枣一枚，煎七分服。 \n《良方》\\x丁香柿蒂散\\x 治吐利，或病后胃中虚寒呃逆。凡呃逆至七、八声相连，收气不回者难治。 \n丁香 柿蒂 炙甘草 良姜（各五分） 人参 半夏 陈皮 茯苓（各一钱） 生姜（二钱） \n水二钟，煎热服。 \n《宝鉴》\\x丁香柿蒂散\\x 治呃逆呕吐。 \n丁香 柿蒂 青皮 陈皮（各等分） \n水一钟半，姜五片，煎服。 \n（严氏）\\x柿蒂汤\\x 治胸满呃逆不止。 \n柿蒂 丁香（各二钱） \n加生姜五片，水煎服。《家珍》方有人参一味。 \n《百一》\\x安脾散\\x 治胃气先逆，饮食过伤，忧思蓄怨，宿食癖积，冷冻饮料寒痰，动扰脾胃 \n，不能消磨，致成斯疾。女人由血气虚损，男子皆由下元虚惫。有食罢即吐，有朝食暮吐， \n暮食朝吐，所吐酸黄臭水，皆是脾败，惟当速治，迟则发烦渴，大便秘，水饮不得入口而危矣。 \n南木香（磨汁） 橘红 人参 白术 草果（面煨） 茯苓 甘草（炙） 丁香 胡椒（各两半） \n高良姜（一两，用陈壁土三合，以水二碗同煮干，切片） \n上咀。每服五钱，水一钟半，入盐少许，煎七分，食远温服。或为细末，每服五钱，用盐米汤调下。 \n《三因》\\x补脾汤\\x 治脾胃虚寒，泄泻腹满，气逆呕吐，饮食不消。 \n人参 白术 茯苓 浓朴（炒） 陈皮（各一钱） 干姜（炒） 甘草（炙） 草果 麦芽（炒，各八分） \n水一钟半，煎七分，空心温服。 \n《三因》\\x养胃汤\\x 治脾胃虚寒，呕逆恶心，腹胁胀疼，肠鸣泄泻。 \n藿香 浓朴（炒） 半夏（制） 茯苓（各钱半） 草果 陈皮 人参 白术（炒，各一钱） 附子 \n（制，八分） 甘草（炙，五分） \n水一钟半，姜三片，枣二枚，煎七分，食远服。 \n\\x胃爱散\\x 治脾胃久虚，中焦气滞，或冷涎上壅，呕吐恶心，或胸膈疼痛，不思饮食，或泄泻不止。 \n人参（一两） 白术 茯苓 黄 （炙，各三钱） 丁香 甘草（炙，各二钱） 肉果（三个，煨） \n干姜（炒，半两） \n上用白米炒熟四两，同研为末。每服二、三钱，用姜汤或人参汤调服。或为 咀 \n，每药五、七钱，加炒米一两，煎服亦可。 \n（东垣）\\x藿香安胃散\\x 治脾胃虚弱，不能进食，呕吐吞酸，腹痛不能腐熟。 \n藿香 人参 陈皮（各一钱） 丁香（五分） 生姜（十片） \n水一钟半，煎七分，食远服。 \n《良方》\\x七味人参丸\\x 治胃冷兼虚，呕逆不食，服许仁则半夏丸不效，可服此药。方见和阵。 \n人参 白术（炒，各五两） 浓朴（姜制） 北细辛（各四两） 生姜 橘皮（各三两） 桂心（二两） \n上为末，炼蜜丸，桐子大。米饮下十丸，渐加至二十丸。 \n\\x甘露汤\\x 治反胃呕吐不止，饮食减少。常服之，快利胸膈，调养脾胃，进饮食。徐东皋 \n曰∶常州一富人病反胃，往京口甘露寺设水陆，泊舟岸下，梦一僧持汤一碗与之，饮罢犹记 \n其香味，便觉胸膈少快，早入寺，知客供汤，乃是梦中所饮者，胸膈尤快，遂求其方，合数 \n十服后，疾遂瘥，名曰观音应梦散。予得之，常以待宾，易名曰甘露汤。又在临汀疗一人愈 \n，甚勿忽之。 \n干饧糟（头柞者，用六分） 生姜（用四分） \n上和匀捣烂作饼，或焙或晒干，每十两入炙甘草二两，同研为末。每服二钱，用沸汤入 \n盐少许调，不拘时服。 \n《金匮》\\x茯苓泽泻汤\\x 治胃反吐而渴欲饮水者。《外台》治消渴脉绝反胃者。 \n茯苓（半斤） 泽泻 生姜（各四两） 甘草 桂枝（各二两） 白术（三两） \n上五味，以水一斗，煮取三升，纳泽泻再煮，取二升半，温服八合，日三服。 \n（仲景）\\x茯苓甘草汤\\x 治水饮停蓄心下，甚者作悸作利。 \n茯苓 桂枝（各二两） 甘草（炙，一两） 生姜（三两） \n上四味，以水四升，煮取二升，去滓，分温三服。 \n\\x草豆蔻汤\\x 和中调气，治呕吐。 \n草豆蔻 藿香（各五分） 陈皮 枳壳（各七分） 白术 山药（各一钱） 桂心 丁香（各二分） \n水一钟半，姜五片，枣二枚，粟米少许，煎七分，食前温服。 \n\\x大顺散\\x 治冒暑伏热，引饮过多，以致寒湿伤脾，阴阳气逆，霍乱吐泻，脏腑不调等证。 \n干姜 肉桂 杏仁（各四两） 甘草（三两） \n上先将甘草微炒黄，次入干姜同炒，令姜裂，又入杏仁同炒，令杏仁不作声为度，却同 \n肉桂研罗一处。每用二、三钱，以水一钟，煎数滚，温服。如烦躁者，以井花水调服，不拘 \n时。此方加附子，即名附子大顺散。 \n\\x四顺附子汤\\x 治霍乱转筋吐泻，手足逆冷，六脉沉绝，气少不语，身冷汗出。 \n附子（生） 白干姜（炮） 人参 甘草（炙，各一两） \n上 咀。每服四、五钱，水钟半，煎七分，食远服。 \n《医林》\\x附子粳米汤\\x 治霍乱四逆，多呕少吐者。 \n中附子（一枚，制） 半夏（制，两半） 干姜（炒） 甘草（炙，各一两） 大枣（十枚） 粳米（五合） \n上 咀。每服八钱，水钟半，煎米熟，去 服。 \n\\x冷香饮子\\x 治伤暑 ，霍乱腹痛烦躁，脉沉微或伏。 \n附子（炮） 陈皮（各一钱） 草果 甘草（炙，各钱半） \n水一钟半，姜十片，煎八分，井水炖冷服。 \n《集成》\\x冷香汤\\x 治夏秋水湿，恣食生冷，阴阳相干，遂成霍乱，脐腹刺痛，胁肋胀满 \n，烦躁引饮无度，或感瘴虚热，胸膈不利，或呕或泄并宜。 \n良姜 白檀香 草豆蔻（面包煨） 附子（制） 炙甘草（各一钱） 丁香（七粒） \n水一钟半，煎七分，用井水浸冷，于呕吐时服之效。或为细末，水调生面糊丸，如芡实 \n大，每服一丸，新汲水磨下亦可。 \n《直指》\\x木瓜汤\\x 治吐泻不已，转筋扰乱。 \n木瓜（一两） 茴香（微炒，二钱半） 吴茱萸（半两，汤泡） 炙甘草（二钱） \n上 咀，分二服。加姜五片，紫苏十叶，空腹急煎服之。《良方》有生姜二钱五 \n分，无茴香、甘草，名木瓜煎。 \n《三因》\\x诃子散\\x 治老幼霍乱，一服即效。 \n诃子（炮，去核） 炙甘草 浓朴（姜制） 干姜（炮） 神曲（炒） 良姜（炒） 茯苓 麦芽 \n（炒） 陈皮 草豆蔻（等分） \n上为细末。每服二钱，当病发不可忍时，用水煎，入盐少许服之。 \n\\x霍乱三方\\x 治霍乱泻利不止，转筋入腹欲死者。 \n用生姜三两，捣烂，入酒一升，煮三、四沸，顿服。 \n一方∶凡霍乱吐泻不能服药，急用胡椒四十粒，以饮吞之。 \n一方∶凡霍乱吐泻不止，用艾一把，水三升，煮一升，顿服之。 \n《千金》\\x霍乱方\\x 治霍乱干呕不止。 \n以薤叶煎一升，服三次立愈。 \n\\x干霍乱二方\\x 凡欲吐不吐，欲下不下，呕恶不止者，谓之干霍乱。 \n一方∶用盐一两，生姜半两，捣，同炒令色变，以水一碗煎，热服。 \n一方∶用丁香十四粒为末，以热汤一盏调服。 \n《金匮》\\x苓桂术甘汤\\x 治心下有痰饮，胸胁支满，目眩。 \n茯苓（四两） 桂枝 白术（各三两） 甘草（二两） \n上水六升，煮取三升，分三服，小便即利。 \n\\x姜术汤\\x 治心下停饮怔忡。 \n白姜 白术 白茯苓 半夏曲（各一钱） 官桂（三分） 甘草（五分） \n水一钟半，枣三枚，煎服。 \n\\x韩氏温中汤\\x 凡病患两手脉沉迟或紧，是皆胃中寒也；若寸脉短少及力少于关尺者，此 \n阴盛阳虚也，或胸膈满闷，腹中胀满，身体拘急，手足厥冷，急宜温之。 \n丁皮 丁香（各五分） 浓朴 干姜 陈皮 白术（各一钱） \n水钟半，加葱白、荆芥穗同煎。 \n（东垣）\\x浓朴温中汤\\x 治脾胃寒滞，心腹胀满，或见疼痛。 \n浓朴（姜炒） 橘红 干姜（各一钱） 茯苓 草豆蔻 木香 甘草（各五分） \n水煎，温服。 \n大正气散 方在和阵。治风寒湿气伤脾，心腹胀闷，有妨饮食。 \n\\x强中汤\\x 治生冷寒浆有伤脾胃，遂成胀满，有妨饮食，甚则腹痛。 \n人参 橘红 青皮 丁香（各二钱） 白术（钱半） 附子（炮，去皮脐） 草豆蔻 干姜（炮，各 \n一钱） 浓朴（姜汁炒） 甘草（炙，各五分） \n水钟半，姜三片，红枣二枚，煎七分，不拘时服。呕，加半夏；若伤面食，加莱菔子一钱。 \n《三因》\\x强中丸\\x 治胃脘虚寒，痰饮留滞，痞塞不通，气不升降。《局方》温中化痰丸 \n，即此方不用半夏。 \n高良姜 干姜（炮） 陈皮 青皮（各一两） 半夏（制，二两） \n上为细末，生姜汁煮糊丸，桐子大。每服三十丸，姜汤下。 \n\\x三生饮\\x 此治中风，乃行经治痰之剂，斩关夺门之将，必用人参驱驾其邪而补助真气， \n乃可用之，否则恐反为害。 \n生南星（一两） 生川乌（去皮，半两） 生附子（去皮，半两） 木香（二钱） \n每用一两，加人参一两，同煎服。 \n（严氏）\\x三生丸\\x 治痰厥头痛。 \n南星 半夏 白附子（等分） \n上为末，姜汁浸蒸饼丸，小豆大。每服四十丸，食后姜汤下。 \n\\x五生丸\\x 治风痫。 \n川乌头 附子（各生用，去皮脐） 南星（生） 半夏（生） 干姜（生，各半两） \n上为细末，醋煮大豆汁作面糊和丸，桐子大。每服五丸，冷酒送下，不拘时。 \n《局方》\\x温中化痰丸\\x 治停痰留饮。 \n陈皮 青皮 良姜 干姜（等分） \n上为细末，醋煮糊丸，桐子大。每服三十丸，空心米饮送下。 \n《宝鉴》\\x温胃化痰丸\\x 治膈内有寒，脾胃伤饮，胸膈不快，痰涎不已。 \n半夏（制，三两） 白术 陈皮 干姜（炮，各一两） \n上为末，姜汁糊丸，桐子大。姜汤下二十丸。 \n《局方》\\x倍术丸\\x 治五饮吞酸等证。一曰留饮，停水在心下；二曰 饮，水在两胁 \n；三曰痰饮，水在胃中；四曰溢饮，水溢在膈；五曰流饮，水在胁间，沥沥有声，皆由饮水 \n过多，或饮冷酒所致。 \n白术（炒，二两） 桂心 干姜（炒，各一两） \n上为末，蜜丸。每服二十丸，温米饮下，加至三、五十丸，食前服。"}, {"n": 36, "text": "卷三十六\n\n《发明》\\x丁香半夏丸\\x 治心下停饮冷痰。 \n丁香 半夏（制，各一两） 人参 干姜（炮） 细辛（各五钱） 槟榔（三钱） \n上为细末，姜汁糊丸，桐子大。每服三十丸，姜汤下。 \n《局方》\\x丁香五套丸\\x 治胃气虚弱，三焦痞塞，不能宣行水谷，故痰饮聚结，呕吐恶心 \n，胀满不食。 \n丁香 木香 青皮 橘红（各半两） 白术 茯苓 良姜 干姜（各一两） 南星（制） 半夏（ \n制，各二两） \n上为末，汤浸蒸饼丸，桐子大。每服七十丸，温汤下。 \n《三因》\\x复元丹\\x 治脾肾虚寒，发为水肿，四肢虚浮，心腹坚胀，小便不通，两目下肿。 \n附子（炮，二两） 南木香（煨） 茴香（炒） 川椒（炒出汗） 浓朴（制） 独活 白术（炒） \n橘红 吴茱萸（炒） 桂心（各一两） 泽泻（一两半） 肉豆蔻（煨） 槟榔（各半两） \n上为末，糊丸桐子大。每服五十丸，紫苏汤不拘时送下。 \n（薛氏）\\x加减金匮肾气丸\\x 方在补阵。治脾肾阳虚，不能制水，为肿为胀。 \n《济生》\\x实脾散\\x 治阴水发肿，宜先实脾土。 \n附子（制） 炮干姜 浓朴 木香 大腹皮 草果仁 木瓜（各钱半） 甘草（炙，五分） \n水二钟，姜五片，枣一枚，煎七分，不拘时服。 \n（严氏）\\x实脾散\\x \n即前方加白术、茯苓。 \n《简易》\\x腹胀方\\x \n凡肚腹胀满不能用药者，以独蒜煨熟去皮，绵裹纳下部中，冷即易之。又治关格胀满， \n大小便不通，亦用上法，气立通。又方∶用生姜如指大一块，煨熟，以绵裹乘热纳下部中，冷即易之。 \n\\x丁香止痛散\\x 治心痛不可忍。 \n丁香（半两） 良姜（二两） 茴香（炒） 甘草（各两半） \n上为细末。每服二钱，不拘时沸汤点服。 \n\\x胜金散\\x 治卒心痛。 \n桂枝 玄胡索（炒） 五灵脂 当归（各半两） \n上为末，炼蜜丸，桐子大。每服二十丸，食前陈皮汤送下。 \n《良方》\\x铁刷散\\x 治心脾积痛，妇人血气刺痛，酒病恶心，肠滑泄泻。 \n良姜（炒，二两） 茴香（炒七钱） 苍术（制） 甘草（炙，各二两八钱） \n上为末。每服二钱，空心姜、盐汤调下。 \n《局方》\\x蟠葱散\\x 治男妇脾胃虚冷，滞气不行，攻刺心腹，痛连胸胁，膀胱小肠寒疝气 \n疝，及妇人血气刺痛。 \n苍术（米泔浸，切） 炙甘草（各八钱） 三棱（煨） 蓬术（煨） 茯苓 青皮（各六钱） 丁皮 \n砂仁（去壳） 槟榔（各四钱） 延胡索（三钱） 干姜（炒） 肉桂（各二钱） \n上每服五钱，水一盏，入连根葱白一茎，煎七分，空心热服；或为末，用葱汤调服二、三钱。 \n《宝鉴》\\x沉香桂附丸\\x 治中气虚寒，饮食不美，阴盛阳虚，脏腑积冷，心腹疼痛，胁肋 \n膨胀，腹中雷鸣，便利无度，面色不泽，手足厥冷，及下焦阳虚，疝气疼痛不可忍，腰屈不 \n能伸，喜热熨稍缓等证。 \n附子（炮，去皮脐） 川乌（制同） 沉香 肉桂 干姜（炮） 良姜（炮） 茴香（炒） 吴茱 \n萸（泡，各一两） \n上为末，醋煮面糊丸，桐子大。每服五、七十丸，食前米饮下，日二服。忌生冷。 \n\\x椒附丸\\x 治小肠虚冷，小腹痛，小便频而清白。 \n椒红（炒） 附子（炮） 龙骨 桑螵蛸（炙） 山茱萸 鹿茸（酒蒸，焙，各等分） \n上为末，酒糊丸，桐子大。每服六十丸，空心盐汤下。 \n\\x大沉香丸\\x 治寒气攻冲，心腹刺痛，亦治卒暴心痛。 \n沉香 干姜（炮） 姜黄 桂心 檀香（各二两） 甘松（洗，焙） 白芷 天台乌药 甘草（各 \n半斤） 香附（一斤） 白豆蔻（三两） \n上为末，炼蜜和丸，弹子大。每服一丸，细嚼，生姜汤下，不拘时。 \n《辨疑》\\x桂附二陈汤\\x 治寒疟寒多热少，腰足厥冷。 \n附子（炮） 肉桂 半夏（制） 白茯苓 陈皮 炙甘草 \n上 咀。每服五、六钱，水一钟半，姜三片，枣一枚，煎服。 \n\\x扶阳助胃汤\\x 罗谦甫治崔运使长男云卿，年二十五，体肥养浓，常食凉物寒药，以致秋 \n间疟发，复用水吞砒石等药，反增吐泻，中气愈虚，延至次年四月，复因劳怒，前证大作。 \n诊其脉得弦细而微，手足稍冷，面色青黄，食少痞闷呕酸，气促汗出。予思《内经》云∶中 \n气不足，溲便为之变，肠为之苦鸣。下气不足，则为痿厥心 。又曰∶寒气客于肠胃之 \n间，则卒然而痛。非大热之剂不能愈，遂制此方。 \n附子（炮，去皮脐，二钱） 干姜（炮，钱半） 草豆蔻 益智仁 拣参 甘草（炙） 官桂 白 \n芍药（各一钱） 吴茱萸 陈皮 白术（各五分） \n上 咀。水二盏，枣二枚，姜三片，煎八分，食前温服。三服后，大势去，痛减 \n半。至秋灸中脘以助胃气，次灸气海百余壮，生发元气。明年复灸三里二七壮，亦助胃气， \n引气下行。仍慎加调摄，一年而平复。 \n\\x五味沉附汤\\x 治虚寒无阳，胃弱干呕。 \n熟附子 干姜（炮，各一钱） 白术 炙甘草（各钱半） 沉香（五分） \n水盏半，姜五斤，煎七分，食前服。 \n二味沉附汤 治瘴疾上热下寒，腿足寒厥。 \n沉香（磨汁） 附子（制，各三钱） \n水一钟半，生姜三片，煎八分，去 ，入沉香汁放冷服。此药主上热下寒。《全集 \n》云∶沉水真正铁角沉香，其味甘辛者，为美；辛辣者，性热。附子降气敛阳。治阴毒冷瘴 \n，只一服而回生起死，真可以夺化功。 \n《济生》\\x七枣汤\\x 治瘴疟，或因感冒风寒，或者五脏气虚，阴阳相搏，寒多热少，或但 \n寒不热，皆可服。 \n大附子（一枚，制，分四服。又方∶用川乌代附子，以水调陈壁土为糊，浸泡七次） \n水二钟，姜七片，枣七枚，煎一钟，当发日早晨空心温服，仍吃枣子三、五枚，忌如常。 \n\\x冷汤\\x 治瘴毒内寒外热，咽嗌间烦躁不解。 \n人参（半两） 大附子（一钱） 甘草（炙，三寸） 淡竹叶（十四片） 大枣（五枚） \n水煎，温服，或冷服。甚者，宜倍用人参、附子，不可拘此常数。 \n\\x生姜煎\\x 治瘴如疟，憎寒壮热。 \n老生姜（一大块，打破，湿纸包，煨熟） \n上用水一钟，煎半钟，热服取微汗 \n\\x芎附散\\x 治五种痛痹，自腿臂间发作不定者。 \n小川芎 附子（炮，去皮） 黄 防风 白术 当归（酒洗） 熟地 桂心 甘草 柴胡（等分） \n水二钟，姜三片，枣二枚，煎八分，空心服。 \n《局方》\\x参附渗湿汤\\x 治坐卧湿地，雨露所袭，身重脚弱，关节疼痛，发热恶寒，小便 \n不利，大便溏泄。 \n人参 白术 茯苓 甘草 附子（炮） 干姜（炮） 桂枝 芍药（等分） \n水二钟，姜三片，枣一枚，煎八分。不拘时服。 \n\\x七味渗湿汤\\x 方在和阵。治寒湿所伤，身体重着，小便赤涩，大便溏泄。 \n\\x熨背散\\x 治胸痹心背疼痛气闷。 \n乌头 细辛 附子 羌活 川椒 桂心（各一两） 川芎（一两二钱） \n上为末，以少醋拌匀，或炒热，或用帛裹微火炙令暖以熨背上，取瘥乃止。忌生冷如常 \n服。按∶此方当用气，惟诸辛香者佳，附子似不必用。 \n\\x温中法曲丸\\x 治脾痹发咳呕汁。 \n法曲（炒） 枳实（面炒） 白茯苓 吴茱萸（汤浸，炒） 桂心 浓朴（姜制） 当归 甘草 \n（炙，各三两） 人参 麦冬 干姜（炮） 细辛 附子（炮） 桔梗（炒，各一两） 麦芽（微炒，五合） \n上为细末，炼蜜丸，桐子大。每服七十丸，食前熟水下，日三。 \n（丹溪）\\x龙虎丹\\x 治走注疼痛，或麻木不仁，或半身疼痛。 \n草乌 苍术 白芷（各一两） \n上为末，水拌发热过，再入乳香二钱，当归、牛膝各半两，酒糊丸，弹子大。酒化下。 \n\\x活络丹\\x 方在和阵。治中风手足不用，日久不愈，经络中有湿痰死血者。 \n《济生》\\x二至丸\\x 治老人虚弱，肾气虚损，腰痛不可屈伸。 \n附子（炮，去皮脐） 桂心 杜仲（制） 补骨脂（炒，各一两） 鹿角霜 鹿角（镑） 鹿茸（ \n酒炙） 青盐（另研，各半两） \n上为末，酒煮糊丸，桐子大。每服七十丸，空心用胡桃肉细嚼，盐汤或盐酒送下。如畏 \n热药者，去附子，加肉苁蓉。 \n《三因》\\x肾着汤\\x 治肾虚身重，腰冷如在水中，不渴，小便自利，食饮如故，腰下重痛如带五千钱。 \n茯苓 白术（各四两） 炙甘草 干姜（炮，各二两） \n上 咀。每服四钱，水煎，空心冷服。一方用姜四两，术二两；《良方》每服有 \n杏仁五分，治妊娠脚肿。 \n（韩氏）\\x茵陈附子汤\\x 治发黄，服四逆汤，身冷汗不止者。 \n附子（二个，各作八片） 干姜（炮，二两半） 茵陈（一两半） \n上用水煎，分作三服。 \n（韩氏）\\x小茵陈汤\\x 治发黄，脉沉细，四肢及遍身冷。 \n附子（一个，炮作八片） 炙甘草（一两） 茵陈（二两） \n上用水二升，煮一升，分作三服。 \n（韩氏）\\x茵陈橘皮汤\\x 治身黄，脉沉细数，热而手足寒，喘、呕、烦躁不渴者。 \n茵陈 橘皮 生姜（各一两） 白术（二钱半） 半夏 茯苓（各五钱） \n上用水四升，煮取二升，放温，分作四服。 \n\\x五鬲散\\x 方在和阵。治五鬲、五噎。 \n\\x十鬲散\\x 方在和阵。治十般鬲气。 \n\\x五噎散\\x 方在和阵。治诸气结聚，胸膈痞闷，痰逆恶心，饮食不进。 \n《良方》\\x白术圣散子\\x 治一切泻痢久不瘥，并妇人产后痢疾。 \n白术 砂仁 当归 肉豆蔻 干姜（炮） 陈皮 炙甘草 石榴皮 诃子 芍药（炒，等分） \n上 咀。每服五钱，水一钟半，入乳香一豆大，煎八分，食前服。 \n（仲景）\\x吴茱萸汤\\x 呕而胸满，干呕吐涎沫，头痛，及食谷欲呕者，此方主之。 \n吴茱萸（一升） 人参（三两） 生姜（六两） 大枣（十枚，擘） \n上四味，以水五升，煮取三升，温服七合，日三服。 \n《良方》\\x吴茱萸汤\\x 治冒暑伏热，腹痛泻痢，或饮食过度，霍乱吐泻，或食冷冒寒，或 \n忍饥大怒，或因舟车伤动胃气，令人吐泻并作，转筋逆冷等证，迟则不救。 \n吴茱萸 木瓜 食盐（各半两） \n上同炒令焦，先用瓷瓶盛水三升，煮百沸入药，煎至二升以下，倾一盏，或冷或热，随 \n病患之便服之。若卒无前药，止用盐一撮，醋一盏，同煎八分，温服。或盐、梅咸酸等物皆可用。 \n\\x吴茱萸散\\x 治肠痹寒湿内聚，腹痛满气急，大便飧泄。 \n炮干姜 炙甘草 吴茱萸 肉豆蔻（面裹煨） 砂仁 神曲（炒，各一钱） 白术 浓朴（姜 \n制） 陈皮（各二钱） 一方有良姜 \n上为末。每服二钱，空心米饮调下。 \n（海藏）\\x吴茱萸丸\\x 治下痢脏腑不调，胀满腹痛，水谷不化，怠惰嗜卧，时时下痢，乃阴湿证也。 \n吴茱萸（两半，汤洗，炒） 神曲（炒，五两） 白术（炒，四两） 肉桂 干姜（炮，各二两半） 川 \n椒（去目，炒，一两） \n上为末，糊丸，桐子大。米饮下三、五十丸，食前服。 \n（杨氏）\\x八味汤\\x 治脾胃虚寒，气滞不行，心腹刺痛，脏腑虚滑。 \n人参 当归 炮姜 吴茱萸（汤泡七次） 肉桂 丁香 木香 陈皮（各一钱） \n上 咀。水一钟半，煎七分，温服无时。按∶此汤味太刚烈，当加炙甘草方妙。 \n（仲景）\\x真武汤\\x 治少阴伤寒，腹痛，小便不利，四肢沉重疼痛，自下利者，此为有水气 \n，其人或咳，或小便利，或下利，或呕者。 \n茯苓 芍药 生姜（各三两） 白术（二两） 附子（一枚，炮去皮，切八片） \n上五味，以水八升，煮取三升，去滓，温服七合，日三服。若咳者，加五味子半升，细 \n辛、干姜各一两；小便利者，去茯苓；下利者，去芍药，加干姜二两；呕者，去附子，加生 \n姜足前成半斤。 \n《良方》\\x九宝丹\\x 调理脾胃，止泄泻。 \n人参 白术（炒） 茯苓 炙甘草 干姜（炮） 木香 藿香（去土） 诃子（去核） 肉豆蔻 \n（面炒，各一钱） \n水一钟半，加姜煎，食远服。 \n《济生》\\x四柱散\\x 治本元气虚，真阳耗散，脐腹冷痛，泄泻不止。 \n人参 附子（炮） 白茯苓 木香（各一两） \n上 咀，每服五、七钱，水一钟半，煨姜五片，盐少许，食远煎服。滑泄不止， \n加肉豆蔻、诃子，名六桂散；《活人》有白术，无诃子。 \n（仲景）\\x白通汤\\x 治少阴病下利。 \n葱白（四茎） 干姜（一两） 附子（一枚，生用，去皮，破八片） \n上三味，以水三升，煮取一升，去滓，分温再服。 \n白通加猪胆汁汤，即于前方加人尿五合，猪胆汁一合，治少阴下利，无脉，干呕而烦者 \n。服汤后，脉暴出者死，微续者生。 \n（仲景）\\x桃花汤\\x 治少阴伤寒，下利便脓血。 \n赤石脂（一斤，一半筛末，一半全用） 干姜（一两） 粳米（一升） \n上三味，以水七升，煮米令熟，去滓，温服七合，内所筛赤石脂细末方寸匕，搅匀服之 \n，日三服。若一服愈，余勿服。 \n（洁古）\\x浆水散\\x 治暴泻如水，周身汗出，一身尽冷，脉微而弱，气少不能语者，甚者加吐，即为急证。 \n半夏（一两，制） 附子（制） 炮姜 肉桂 甘草（各五钱） 良姜（二钱半） \n上为末。每服三钱，浆水一钟半，煎至半钟，热服。 \n《澹寮》\\x附子茴香散\\x 治气虚积冷，心腹绞痛，泄泻食少。 \n人参 白术 茯苓 炙甘草（各七分） 附子（制） 炮姜（各五分） 茴香 肉豆蔻（各四分） 木 \n香（三分） 丁香（五粒） \n水一钟半，煎七分，食远服。 \n《本事》\\x五味子散\\x 治肾泄，在侵晨及五更作泻，饮食不进，不时去后。 \n五味子（炒，二两） 吴茱萸（炒，一钱） \n上为末。每服二钱，白汤调下。为丸尤效。 \n《本事》\\x二神丸\\x 治脾胃虚寒，不思饮食，泄泻不止。 \n肉豆蔻（生用，二两） 破故纸（炒，四两） \n上为末，用大肥枣四十九枚，入生姜片四两同煮，以枣烂为度，去姜，取枣肉捣药为丸 \n，桐子大。每服五、六十丸，白汤下。 \n（薛氏）\\x四神丸\\x 治脾肾虚寒，大便不实，饮食不思，及泄痢腹痛等症。 \n破故（炒，四两） 肉豆蔻（面煨） 五味子（各二两） 吴茱萸（汤浸，炒，一两） \n上为末，用大枣百枚，同姜八两煮烂，取肉捣丸，桐子大。每服七、八十丸，空心食前 \n白汤下。按∶此丸不宜用枣，但以姜汁煮面糊为丸更佳。 \n《澹寮》\\x四神丸\\x 治脾肾泄，清晨溏泻。 \n破故（炒，四两） 肉豆蔻（二两） 木香（半两） 小茴香（炒，一两） \n上为末，姜煮枣肉为丸，桐子大。白汤送下。 \n《医林》\\x四神丸\\x 治寒疝胀痛不已。 \n荜澄茄 木香（各半两） 吴茱萸（半酒浸，半醋浸） 香附（各一两） \n上为末，糊丸，桐子大。每服七、八十丸，空心盐汤或乳香葱汤任下。 \n《集要》四神丸 方在补阵。治小便频数不禁。 \n\\x五味子丸\\x 治下元虚寒，火不生土，以致命门不暖，关门不闭，名曰肾泄，亦名脾肾泄。 \n人参 白术（炒） 北五味子（炒） 破故（炒，各三两） 山药（炒） 白茯苓（各两半） 吴茱萸 \n（汤泡，炒） 川巴戟（去心，炒） 肉果（面煨，各一两） 龙骨（ ，五钱） \n上为末，酒糊丸，桐子大。每服百余丸，食前白汤或米汤任下。 \n《得效》\\x荜茇丸\\x 治滑泄中寒者宜之。 \n荜茇 川姜（炮） 丁香（不见火） 附子（炮，去皮脐） 良姜 胡椒 吴茱萸（汤浸，炒， \n各一两） 山茱萸 草豆蔻（去皮，各半两） \n煮枣肉丸，桐子大。每服五、六十丸，食前陈米饮下，日三服。 \n《局方》\\x肉豆蔻丸\\x 治脾胃虚弱，胀满，水谷不消，脏腑滑泄。 \n肉豆蔻（面煨） 苍术（制） 干姜（炮） 浓朴（制） 陈皮（各四两） 炙甘草 茴香（炒） 肉 \n桂川乌（炮，去皮脐） 诃子肉（各二两） \n上用汤浸蒸饼为丸，梧子大。每服七、八十丸，食前白滚汤下。 \n（陈氏）\\x肉豆蔻丸\\x 方在小儿。治肠滑泻痢。 \n《济生》\\x诃梨勒丸\\x 治大肠虚冷，泄泻不止，腹胁引痛，饮食不化。 \n诃梨勒（面裹煨） 附子（炮） 肉豆蔻（面裹煨） 木香 吴茱萸（汤泡，炒） 龙骨（生用） \n白茯苓（去皮） 荜茇（各，等分） \n上为细末，生姜汁煮面糊为丸，梧子大。每服七十丸，空心米饮下。 \n《良方》\\x浓朴丸\\x 治寒中洞泄，实滞胀满等证。 \n浓朴（炒） 干姜（炒，等分） \n上水拌炒为末，水糊丸，桐子大。每服五十丸，米饮下。 \n《百一》\\x缩脾丸\\x 治滑泄不禁。 \n白术（炒） 浓朴（姜炒） 赤石脂 肉豆蔻（面煨） 干姜（炒，各一两） 附子（制） 荜茇 \n神曲（炒，各五钱） \n上为细末，醋糊丸，桐子大。每服五、七十丸，空心米饮下。 \n《三因》\\x桂香丸\\x 治脏腑虚寒，为风寒所搏，冷滑注下不禁，危笃者累效。 \n附子 肉豆蔻（面煨） 白茯苓（各一两） 桂心 干姜（炒） 木香（各半两） 丁香（二钱半） \n上为末，面糊丸，桐子大。空心米饮下五、七十丸。 \n《宝鉴》\\x陈曲丸\\x 磨积，止泻痢，治腹中冷痛。 \n陈曲（一两半） 人参 白术（炒） 当归（炒） 干姜 肉桂 甘草（炙） 浓朴（制，各半两） \n上为末，炼蜜丸，桐子大。每服三、五十丸，温酒或淡醋汤任下，日二服。 \n（杨氏）\\x萆 厘清饮\\x 治真元不足，下焦虚寒，或服寒凉刮药过多，小便白浊，频数无度 \n，澄如膏糊等证。 \n益智仁 川萆 石菖蒲 乌药（各等分） \n上 咀。每服五、六钱，水一钟，入盐一捻，煎七分，食前温服。一方加茯苓、甘草。 \n\\x益志汤\\x 治肾经亏损，遗精白浊，四肢烦倦，时发蒸热等证。 \n鹿茸（酥炙） 巴戟肉 枸杞子 熟地黄 苁蓉（酒浸） 牛膝（酒浸） 附子（炮，去皮脐） \n桂心（不见火） 山茱萸 白芍药 炙甘草 防风（各等分） \n上每服三钱，水一盏，姜五分，盐少许同煎，空心服。 \n《局方》\\x安肾丸\\x 治肾经积冷，下元衰惫，目暗耳鸣，四肢无力，夜梦遗精，小便频数 \n，脐腹撮痛，食少体瘦，神困健忘。常服壮元阳，益肾水。 \n肉桂（去粗皮，不见火） 川乌（炮，去皮脐，各一斤） 白术 山药 茯苓 肉苁蓉（酒浸 \n，炙） 巴戟（去心） 破故（炒） 萆 桃仁（面炒） 石斛（炙） 白蒺藜（炒去刺，各三斤） \n上为末，炼蜜丸，桐子大。每服三、五十丸，温酒或盐汤下，空心食前服。疝气，茴香 \n汤下。《三因》安肾丸无茯苓、肉桂二味。 \n\\x小安肾丸\\x 治肾气虚乏，下元冷惫，夜多漩溺，体瘦神倦，腰膝沉重，泄泻肠鸣，眼目 \n昏暗，牙齿蛀痛。 \n川楝子（一斤，用香附子、川乌各一斤，加盐四两，水四升同煮，候干去香附、川乌不用 \n，取川楝切焙） 小茴（十一两） 熟地（八两） 川椒（四两，去闭口者，微炒出汗） \n上为末，酒糊丸，桐子大。每服二、三十丸，空心临卧，盐汤或酒任下。 \n（西蜀）\\x石刻安肾丸\\x 治真气虚惫，脚膝软弱，夜梦遗精，小便滑数。 \n附子（制） 肉桂 川乌（制） 川椒（去目，微炒出汗） 菟丝（制） 巴戟（制） 破故（酒 \n炒） 赤石脂（ ） 远志（制） 茯神 茯苓 苍术（米泔浸炒） 山茱萸 杜仲（制） 石斛 \n胡芦巴（炒） 柏子仁 韭子（微炒） 小茴（酒炒） 肉苁蓉（酒浸） 川楝子（酒蒸，去核，各二 \n两） 鹿茸（制，一两） 青盐（四钱） 山药（四两，作糊） \n上为末，酒煮山药糊丸，桐子大。每服七、八十丸，空心盐汤或白汤下。 \n《元戎》\\x小已寒丸\\x 一名强中丸。治脾胃积冷中寒，洞泄倦怠，不思饮食。进食，止自 \n汗，浓肠胃。见《肘后》，甚验。 \n艾叶（四两） 苍术（一两，炒） 吴茱萸（炒） 陈皮（炒，各二两） \n上用米醋二升浸一宿，漉出曝干，再于原醋内拌匀，炒令紫色，焙干为末，稀糊丸，桐 \n子大。每服三、五十丸，空心食前，温酒、盐汤、米汤、白汤任下。 \n《局方》\\x大已寒丸\\x 治脏腑虚寒，心腹 痛，肠鸣泄泻，自利自汗，米谷不化 \n，手足厥冷，阴盛阳衰等证。 \n荜茇 肉桂（各四两） 干姜（炮） 良姜（各六两） \n水煮面糊为丸，桐子大。每服二、三十丸，食前米饮下。 \n《元戎》\\x大已寒丸\\x 治诸沉寒冷秘等证。 \n吴茱萸 官桂 干姜 良姜 乌头 附子 \n上为末，醋糊丸，桐子大。每服三、五十丸，米饮下，空心食前，日二服。无所忌。 \n（海藏）\\x巳寒丸\\x 此丸不僭上而阳生于下。治阴证服四逆辈，胸中发躁而渴者，或数日大 \n便秘，小便赤涩，服此丸，上不燥，大小便自利。 \n肉桂 附子（炮） 乌头（炮） 良姜 干姜 芍药 茴香（各等分） \n上为末，米糊丸，桐子大。空心温水下五、七十丸，或八、九十丸，食前亦可。酒醋糊 \n丸亦可。海藏云∶已寒上五味虽热，以芍药、茴香润剂引而下之，阴得阳而化，故大小便自 \n通，如得春和之阳，冰自消矣。 \n\\x十补丸\\x 治肾脏虚冷，面黑足寒，耳聋膝软，小便不利等证。 \n附子（炮） 五味（各二两） 山药 山茱萸 丹皮 桂心 鹿茸（制） 茯苓 泽泻（各一两） \n炼蜜丸，桐子大。每服六、七十丸，盐汤下。 \n《百选》\\x十补丸\\x 治小肠寒疝。 \n附子（一大枚，制） 胡芦巴 木香 巴戟天 川楝肉 玄胡索 官桂 荜澄茄 大茴香 \n破故纸（炒，各一两） \n上为末，酒煮糯米粉糊为丸，桐子大，朱砂为衣。空心酒下五十丸。 \n《集成》\\x神应散\\x 治寒疝诸疝，心腹痛不可忍，散气开郁。 \n玄胡索 胡椒 小茴香（等分） \n上为末。每服二钱，酒调下。 \n《金匮》\\x当归生姜羊肉汤\\x 治寒疝腹中痛，及胁痛里急者。 \n当归（三两） 生姜（五两） 羊肉（一斤） \n上三味，以水八升，煮取三升，温服七合，日三服。若寒多者，加生姜成一斤；痛多而 \n呕者，加橘皮二两，白术一两。如加生姜，亦须加水五升，煮取三升二合服之。 \n（丹溪）\\x肾气丸\\x 治诸疝痛。 \n小茴香（炒） 破故纸（炒） 吴茱萸（盐炒，各五钱） 胡芦巴（七钱半） 木香（三钱半） \n上为末，萝卜汁丸，桐子大。盐汤下五、七十丸。 \n《百选》\\x胡芦巴丸\\x 治小肠气 蟠肠气，奔豚，疝气，偏坠阴肿，小腹有形如卵，上下 \n来去，痛不可忍，或绞结绕脐攻刺，呕吐者。 \n胡芦巴（炒，一斤） 大巴戟（炒） 川乌（炮，去皮，各六两） 川楝子（炒，十八两） 茴香（二 \n十两） 吴茱萸（汤浸七次，炒，十两） \n上为末，酒糊丸，桐子大。每服十五丸至二十丸，空心温酒下。 \n（东垣）\\x丁香楝实丸\\x 治寒疝气血留滞。 \n当归（酒洗） 附子（炮） 川楝肉 茴香（各一两） \n以上 咀，用好酒三升同煮，酒尽焙干为末，每药末一两，入没药，丁香、木香 \n（各五分） 全蝎（十三个） 玄胡索（五钱）。 \n上俱为末，拌匀，酒糊丸，桐子大。每服三、五十丸，加至百丸，空心温酒送下。 \n\\x苦楝丸\\x 治奔豚小腹痛，神效。 \n川苦楝子 茴香（各二两） 附子（一两，炮，去皮脐） \n上三味，用酒三升，同煮尽为度，焙干为末，每药末一两，入玄胡索（二钱，一作五钱） \n全蝎（十八个，炒） 丁香（十八粒。） \n俱为末，和匀，酒糊丸，桐子大。温酒下五十丸，空心服。如痛甚，煎当归酒下。 \n《良方》\\x三层茴香丸\\x 治肾与膀胱俱虚，邪气搏结不散，遂成寒疝，脐腹疼痛，阴丸偏 \n大，肤囊壅肿，有妨行步，或瘙痒不止，时出黄水，浸成疮疡，或长怪肉，或外肾肿胀，冷 \n硬如石，日以渐大，须温导阳气，渐退寒邪，补虚消疝，暖养肾经。凡一应小肠气寒疝之疾 \n，久新不过三料。 \n第一料∶ \n舶上茴香（用盐半两，同炒焦黄，和盐秤用一两，连下共重四两） 川楝子（炮，去核） \n沙参（洗） 木香（各一两。） \n上为细末，米糊丸，桐子大。每服二、三十丸，空心温酒或盐汤下，日三服。小病一料 \n可安，病深者，一料才尽，便可用第二料。 \n第二料∶ \n如前方加荜茇（一两） 槟榔（五钱） \n上六味，共重五两半，根据前糊丸，服如前。若未愈，再服第三料 \n第三料∶ \n如前方加白茯苓（佳者，四两） 附子（炮，去皮脐，或五钱或一两） \n上八味，共重十两，丸服如前，渐加至三、四十丸。凡小肠气频发及三十年者，或大如 \n栲栳者，皆可消散，神效。 \n\\x夺命丹\\x 治远年近日小肠疝气，偏坠搐痛，脐下胀痛，以致闷乱，及外肾肿硬，日渐滋 \n长，阴间湿痒等证。 \n吴茱萸（拣净，一斤，分四分用，酒、醋、盐汤、童便各浸一宿，焙干） 泽泻（净片，二两，酒浸一宿） \n上为末，酒糊丸，桐子大。每服五十丸，食前盐酒或盐汤下。 \n《良方》\\x夺命丹\\x 方在妇人。治瘀血入胞，胀满难下。 \n（万氏）\\x夺命丹\\x 方在痘疹。治痘疮倒陷，解毒发痘。 \n《外科》\\x夺命丹\\x 方在外科。治疔疮发背，恶毒恶证，有夺命之功。 \n《局方》\\x二气丹\\x 治虚寒积冷，小便不禁，老人虚人尺脉微弱患此者。 \n硫黄（制，研细） 肉桂（各二钱半） 干姜（炮） 朱砂（研为衣，各二钱） 附子（制，半两） \n上以面糊丸，桐子大。每服二十丸，空心盐汤下。 \n《局方》\\x半硫丸\\x 治高年冷秘虚秘，及 癖冷气。《简易》曰∶此润剂也。 \n半夏（汤泡七次，焙干为末） 硫黄（明净者，研极细，用柳木槌子杀过） \n上等分，以生姜汁打糊丸，桐子大。每服五、七十丸，用无灰酒或生姜汤任下。 \n\\x养正丹\\x 治上盛下虚眩运，此药升降阴阳，及咳逆翻胃，霍乱吐泻，中风涎潮，不省人 \n事，伤寒阴盛，唇青自汗。 \n硫黄（为末） 黑锡（熔净） 水银 朱砂（研，各一两） \n上将锡熔化，入硫末，渐入渐搅为末，再入水银同擂。如硬，再于火上微 ，又擂匀放 \n冷，研极细末，糯米糊丸，绿豆大。每服三十丸，空心盐汤下。 \n《局方》\\x黑锡丹\\x 治痰气壅塞，上盛下虚，肾水亏竭，心火炎盛，或一应下虚阴寒，真 \n头痛等证，及妇人血海久冷无子，赤白带下。 \n黑锡（去滓，二两，炒末） 硫黄（二两） 肉桂（五钱） 附子（炮） 木香 沉香 舶茴香 故纸 \n阳起石（水飞） 葫芦巴（酒浸炒） 肉豆蔻（面裹煨） 金铃子（蒸，去皮核，各一两） \n上用新铁铫将锡化开，下硫黄末，提起，以木杵擂极细，放地上退火毒，同余药研一日 \n，至黑光色为度，酒糊丸，桐子大，阴干入布袋内擦令光莹，每服四十丸，空心姜盐汤下， \n女人艾枣汤下。 \n《局方》\\x红丸子\\x 和脾胃，消宿食，去膨胀，治大人小儿脾胃之证，极有神效。 \n京三棱（浸软切片） 蓬术（煨） 青皮 橘红（各五斤） 干姜（炮） 胡椒（各三斤） \n上为末，用醋糊丸，桐子大，矾红为衣。每服三十丸，食后姜汤送下。小儿临时加减与 \n服丸，治饮食所伤，中脘痞满，服之应手而愈。妊妇恶阻呕吐，全不纳食，百药不治者，惟 \n此最妙，可佐二陈汤服之。但人疑其堕胎，必不信服，每易名用之，时有神效；但恐妊妇偶 \n尔损动，未免归咎此药，是当酌而防之。 \n\\x椒囊法\\x 辟一切瘴疾时气，风寒时气。 \n红川椒（去闭口者） \n以绛纱囊贮椒两许，悬佩身傍近里衣处，则一切邪气不能侵犯。 \n\\x椒红丸\\x 治元脏伤惫，目暗耳聋。服此百日，觉身轻少睡足有力，是其效也；服及三年 \n，心智爽悟，目明倍常，面色红悦，须发光黑。 \n川椒（去目并合口者，炒出汗，捣取红一斤） 生地黄（捣自然汁，熬取浓汁，一升） \n上将生地汁熬至稀稠得所，和椒末捣丸，梧子大。每空心温酒下三、四十丸。合药时， \n勿令妇人鸡犬见。有诗曰∶其椒应五行，其仁通六义。欲知先有功，夜间无梦寐。四时去烦 \n劳，五脏调元气，明目腰不疼，身轻心健记。别更有异能，三年精自秘，回老返婴童，康强 \n不思睡，九虫顿消亡，三尸自逃避。若能久饵之，神仙应可冀。 \n\n\n\n<目录>卷之五十九宙集·古方八阵\n\n<篇名>固阵\n\n属性：《局方》\\x牡蛎散\\x 治诸虚不足，及大病后体虚，津液不固，常常自汗。 \n黄 （蜜炙） 麻黄根 牡蛎（ 淬醋中，各二钱半） \n水一钟半，加小麦百粒，煎八分，食远温服。 \n\\x牡蛎白术散\\x 治漏风证，以饮酒中风，汗多，食则汗出如洗，久而不治，必成消渴。 \n牡蛎（ ，一钱） 白术（炒） 防风（各二钱） \n水二钟，煎八分，食远温服。 \n《宣明》\\x白术散\\x 治虚风多汗，食则汗出如洗，少气痿弱，不治必为消渴证。 \n白术（二两） 防风（五两） 牡蛎（ ，六钱） \n上为末。每服一钱，温水调下，不拘时。如恶风，倍白术；如多汗而肿，倍牡蛎。按∶ \n此方虽与前同，而用法不同，故并存之。 \n\\x神效麦面汤\\x 治心虚盗汗。 \n麦面（炒黄色，一钱） 防风 白术 牡蛎（ ，醋淬） 黄 （蜜炙，一钱半） \n水一钟半，枣二枚，煎八分，调服辰砂妙香散极效。在后十五。 \n黄 汤 方在补阵。治自汗盗汗。 \n《圣惠》\\x宁肺散\\x 治新久咳嗽，肺气不通，咯唾脓血，自汗咳嗽，常年不愈者，服之立 \n止，并坐卧不安，语言不出等证。 \n乌梅肉（七分） 罂粟壳（二钱，去筋，蜜炙） \n上为细末。不拘时，乌梅汤调下。 \n《选要》\\x安眠散\\x 治上喘咳嗽久而不止。 \n款冬花 麦门冬 乌梅肉 佛耳草（各四分） 橘红（五分） 炙甘草（三分） 粟壳（蜜炙，一钱） \n上为末。水一钟，煎八分，入黄蜡如枣核许煎化，临睡温服。 \n（丹溪）\\x百药煎\\x 劫嗽立止。 \n百药煎 诃子 荆芥穗（等分） \n上为极细末，蜜丸噙化。 \n《集成》\\x三妙汤\\x 治久嗽。 \n乌梅肉（二个） 北枣（三枚） 粟壳（蜜炙，四个） \n水一钟半，煎七分，食后服。 \n\\x九仙散\\x 治一切咳嗽不已。 \n人参 款冬花 桔梗 桑白皮 五味子 阿胶 贝母 乌梅（各五分） 御粟壳（二钱，蜜炙） \n水一钟半，姜一片，枣一枚，煎七分，食远服。 \n\\x劫嗽丸\\x 治久嗽失气失声者，宜此敛之。新咳者不宜用也。 \n诃子肉 百药煎 荆芥穗（等分） \n上为细末，蜜丸噙化。 \n\\x五味子丸\\x 劫咳嗽如神。 \n五味子（五钱） 甘草（二钱半） 文蛤 风化硝（各一钱） \n上为末，炼蜜丸，芡实大。噙化。 \n\\x罂粟丸\\x 治一切久嗽劳嗽，一服即愈。 \n罂粟壳（新者一半，去蒂，切，焙干；陈者一半，泡去筋膜，炒，各一两） \n上共为末，蜜丸，弹子大。临睡嚼服一丸。一方用罂粟子半斤，淘净焙干，炒黄为末， \n沙糖丸，弹子大，每服一丸，临卧绵包含化。 \n《统旨》\\x润肺丸\\x 治咳嗽。 \n诃子 五味子 五倍子 甘草（等分） \n上为末，蜜丸噙化。久嗽者，加罂粟壳。 \n《良方》\\x辰砂妙香散\\x 治心气不足，惊痫，或精神恍惚，虚烦少气少睡，夜多盗汗，心 \n虚遗精白浊，服之安神镇心。 \n黄 山药（姜汁炒） 茯苓 茯神 远志（甘草汤制，各一两） 人参 炙甘草 桔梗（各五 \n钱） 木香（二钱） 麝香（一钱，另研） 朱砂（三钱，另研） \n上为末。每服二钱，不拘时，温酒调下，或用麦面汤调下。 \n《局方》\\x王荆公妙香散\\x 安神秘精，定心气。 \n人参 龙骨（五色者） 益智（各一两） 白茯神 白茯苓 远志（制） 甘草（炙，各五钱） 朱 \n砂（飞，二钱半） \n上为末。每服二钱，空心临卧温酒调下。 \n《本事》\\x金锁丹\\x 治梦泄遗精，关锁不固。 \n舶茴香 葫芦巴 破故（炒） 白龙骨（各一两） 木香（两半） 胡桃肉（三十个，研膏） 羊肾（三 \n对，切开，用盐半两擦，炙熟，捣膏） \n上为末，和二膏加酒浸蒸饼为丸，桐子大。每服三、五十丸，空心盐汤下。 \n《和剂》\\x金锁正元丹\\x 治真气不足，遗精盗汗，目暗耳鸣，吸吸短气，四肢酸倦， \n一切虚损等证。 \n补骨脂（一两，酒浸，炒） 肉苁蓉（酒洗，焙） 紫巴戟（去心） 葫芦巴（炒，各一斤） 文蛤 \n（八两） 茯苓（去皮，六两） 龙骨（二两） 朱砂（三两，另研） \n上为细末，酒糊丸，桐子大。每服二十丸，空心温酒、盐汤任下。 \n（万氏）\\x金锁思仙丹\\x 治男子嗜欲太过，精血不固，此涩以去脱之剂。 \n莲蕊 芡实 石莲子（各十两） 金樱膏（三斤） \n上以金樱煎膏如饧，入前三味药末和丸，桐子大。空心盐酒下三十丸。服久精神完固， \n大能延年。平时服食，忌葵菜、车前子。 \n《医林》\\x金锁匙丹\\x 治男妇精滑，遗泄不禁，梦与鬼交。 \n茯苓 茯神（各二钱） 远志（制） 龙骨（ ，各三钱） 左股 牡蛎（ ，四钱） \n上为末，酒糊丸，桐子大。每服四十丸，空心盐汤或酒下。 \n\\x玉锁丹\\x 治玉门不闭，遗精日久，如水之漏，不能关束者。 \n文蛤（八两） 白茯苓（二两） 白龙骨（一两） \n上为细末，米糊丸，桐子大。每服七十丸，空心淡盐汤下，临睡更进一服，极效。 \n《御药》\\x玉锁丹\\x 治精气虚滑，遗泄不禁。 \n龙骨 莲花蕊 鸡头子 乌梅肉（等分） \n上为末，用熟山药去皮为膏和丸，小豆大。空心米汤下三十丸。 \n\\x经验水陆二仙丹\\x 治精脱肾虚，梦遗白浊等证，与补阴药同用，甚有奇效。 \n金樱膏（一斤） \n用金樱子不拘多少，入粗麻布袋内擦去毛刺，捣烂入缸，以水没头，浸一、二宿，滤去 \n，取汁以棉滤二、三次，却入铜锅，用桑柴文火熬成膏，取起，以瓷瓶收贮听用。 \n芡实粉（一斤） \n上二味和匀，丸桐子大。每服二、三百丸，空心淡盐汤下。 \n\\x经验金樱丸\\x 治梦遗精滑，小便后遗溺。 \n金樱子 芡实（各一两） 龙骨（ ） 白莲蕊（各五钱） \n上为末，糊丸，桐子大。每服八十丸，空心盐酒下。 \n《正传》\\x经验秘真丹\\x 治肾虚遗精，梦泄白浊等证。 \n菟丝子（制） 韭子 破故（炒） 杜仲（姜汤炒） 干姜（炒，各一两） 龙骨 牡蛎（ ） 山 \n茱萸 赤石脂（各五钱） 远志 覆盆子 巴戟肉 枸杞 山药（各七钱半） 鹿角胶（一两半） 柏子 \n仁（一两） 金樱子（取黄者，去刺核，焙，净肉，二两） 黄柏（盐酒炒，七钱五分） \n上为细末，炼蜜丸，桐子大。每服百丸，空心姜盐汤下。 \n《局方》\\x锁精丸\\x 治白浊白带，小便频数。 \n破故纸 青盐 白茯苓 五味子（炒，等分） \n一方用五倍子。 \n上为末，酒糊丸，桐子大。每服三十丸，空心温酒下。 \n（东垣）\\x固真丸\\x 治精滑久不愈。 \n牡蛎（不拘多少，用砂锅内 ，醋淬七遍为末） \n上以醋糊为丸，桐子大。每服五、七十丸，空心盐汤下。 \n《良方》\\x固真散\\x 治才睡着即泄精。此二味大能涩精固真气，暖下元。 \n韭子（一合） 白龙骨（一两） \n上为细末。每服二钱，空心用酒调服。 \n《济生》\\x固精丸\\x 治下元虚损，白浊如脂，或胞气虚寒，腰重少力，小便无度并效。 \n牡蛎（ ） 菟丝子（酒浸蒸炒） 韭子（炒） 龙骨（ ） 北五味（炒） 白茯苓 桑螵蛸（ \n酒炙） 白石脂（ ，各等分） \n上为细末，酒糊丸，桐子大。每服七十丸，空心盐汤下。 \n《直指》\\x固精丸\\x 治肾虚有火，精滑，心神不安。 \n黄柏（酒炒） 知母（酒炒，各一两） 牡蛎（ ） 龙骨（ ） 莲蕊 芡实 山茱萸 远志 \n（甘草制） 茯苓（各三钱） \n上为末，山药糊丸，桐子大。每服五十丸，空心温酒下。 \n《百一》\\x固元丹\\x 治元脏久虚，遗精白浊五淋，及小肠膀胱疝气，妇人赤白带下，血崩 \n便血等疾，以小便频利为效。 \n好苍术（刮净，米泔浸咀片，一斤，择坚而小者佳，惟茅山者尤妙。分作四分制之。一分， \n用小茴香、食盐各一两同炒。一分用川椒、补骨脂各一两同炒。一分用川乌头、川楝子肉各 \n一两同炒。一分用醇醋、老酒各半斤同煮干，焙燥） \n上连炒诸药同为末，用酒煮糊丸，桐子大。每服三、五十丸，男以温酒，女以醋汤空心 \n下。此高司法方也。 \n《御药》\\x秘元丹\\x 治内虚里寒，自汗时出，小便不禁。 \n白龙骨（三两） 诃子肉 砂仁（各一两） 灵砂（二两） \n上为末，煮糯米粥丸，桐子大。每服五十丸，空心盐酒下。 \n\\x韭子丸\\x 治虚劳寒脱漏精。 \n韭子（炒） 车前子 天雄（制） 菟丝子（酒煮另捣） 龙骨（各一两） 鹿茸（酥炙） 干姜（ \n炮） 桑螵蛸（炒，各三钱） \n上为末，炼蜜丸，桐子大。每服二、三十丸，空心黄 汤下。 \n《三因》\\x家韭子丸\\x 治少长遗溺，及男子虚剧，阳气衰败，小便白浊，夜梦遗精。此药 \n补养元气，进美饮食。按∶此方当除去石斛，倍用菟丝，庶乎尤效。 \n家韭子（炒，六两） 鹿茸（酥炙，四两） 肉苁蓉（酒浸） 牛膝（酒浸） 熟地 当归（各二两） \n菟丝子（酒煮） 巴戟肉（各一两半） 杜仲（炒） 石斛 桂心 干姜（炮，各一两） \n酒糊丸，桐子大。每服五、七十丸，加至百余丸，食前温酒、盐汤任下。凡小儿遗尿者 \n，多因胞寒，亦禀受阳气不足也，作小丸服之。 \n\\x小菟丝子丸\\x 治肾气虚损，目眩耳鸣，四肢倦怠，夜梦遗精。 \n菟丝子（制，五两） 石莲肉（二两） 白茯苓（二两） 山药（炒，二两，分一半作糊） \n用山药糊丸，桐子大。每服五十丸，空心温酒、盐汤任下。一方有五味子一两，治小便多而不禁。 \n《局方》\\x大菟丝子丸\\x 治肾气虚损，五劳七伤，脚膝酸痛，面色黎黑，目眩耳鸣， \n心忡气短，时有盗汗，小便滑数。 \n菟丝子（酒制） 鹿茸（酥炙） 肉桂 石龙肉（去土） 附子（炮） 泽泻（各一两） 熟地 牛 \n膝（酒浸一宿，焙干） 山茱萸 杜仲（炒） 茯苓 肉苁蓉（酒浸，切焙） 续断 石斛 防风 \n补骨脂（酒炒） 荜茇 巴戟肉 茴香（炒） 沉香（各三两） 川芎 五味 桑螵蛸 覆盆子（各五钱） \n上为末，酒煮面糊丸，桐子大。每服三、五十丸，空心盐汤、温酒任下。 \n《济生》\\x菟丝子丸\\x 治小便多，致失禁。 \n菟丝子（制） 肉苁蓉（酒浸，各二两） 牡蛎（ ） 附子（炮） 五味子 鹿茸（酒炙，各一两） \n鸡 （炙干，五钱） 桑螵蛸（酒炙，五钱） \n上为末，酒糊丸，桐子大。每服七十丸，空心盐汤、温酒任下。 \n《局方》\\x茯菟丸\\x 治思虑太过，心肾虚损，真阳不固，尿有余沥，或小便白浊，梦寐遗精等证。 \n菟丝子（制，五两） 白茯苓（三两） 石莲肉（二两） \n酒糊丸，桐子大。每服三、五十丸，空心盐汤或米汤下。一方有北五味子四两，兼治三消。 \n\\x猪肚丸\\x 治小便频数。 \n莲子（一斤，以猪肚一个，同煮一周日，取出去皮心焙干为末） 舶茴香 破故纸 川楝子 \n母丁香（各一两） \n上为末，炼蜜丸，桐子大。每服五十丸，空心温酒送下。 \n经验猪肚丸 止梦遗泄精，进饮食，健肢体，此药神应。瘦者服之自肥，莫测其理。 \n白术（面炒，五两） 苦参（白者，三两） 牡蛎（左扇者， 研，四两） \n上为末，用雄猪肚一具，洗净，以瓷罐煮极烂，木石臼捣如泥，和药再加肚汁捣半日， \n丸如小豆大。每服四、五十丸，日进三服，米饮送下。久服自觉身肥而梦遗永止。 \n《良方》\\x三仙丸\\x 治梦遗精滑。 \n益智仁（二两，用盐二两同炒，去盐） 乌药（一两半，炒） 山药（一两，炒） \n上为末，山药煮糊丸，桐子大。每服七十丸，空心茯苓汤送下。 \n（丹溪）\\x九龙丸\\x 治肾虚精滑。 \n金樱子 枸杞 山茱萸 莲蕊 莲肉 当归 熟地 芡实 白茯苓（各等分） \n上为末，酒糊丸，桐子大。每服五、六十丸，或酒或盐汤下。 \n\\x小温金散\\x 治心肾虚热，小便赤白淋沥，或不时自汗等证。 \n人参 莲肉（去心） 巴戟肉 益智 黄 （蜜炙） 麦冬（去心） 赤茯苓 萆 （酒浸 \n炒） 炙甘草（各一钱） \n灯心十茎，枣一枚，水煎服。 \n（仁斋）\\x莲子六一散\\x 治心经虚热赤浊。 \n石莲子（六两） 炙甘草（一两） \n为末。每服三钱，灯心汤调下。 \n《和剂》\\x威喜丸\\x 治元阳虚惫，精滑白浊遗尿，及妇人血海久冷，淫带梦泄等证。 \n白茯苓（去皮，四两，切块，同猪苓二钱五分同于瓷器内煮二十余沸，取出晒干，不用猪 \n苓） 黄蜡（四两） \n上以茯苓为末，熔黄蜡搜和为丸，如弹子大。每空心细嚼，满口生津，徐徐咽服，以小 \n便清利为效。忌米醋，惟糠醋可用，尤忌气怒动性。 \n\\x五子丸\\x 治小便频数，时有白浊。 \n菟丝子（酒蒸） 家韭子（炒） 益智 茴香（炒） 蛇床子（去皮，炒） \n上各等分为末，酒糊丸，桐子大。每服七十丸，米饮、盐汤任下。 \n\\x远志丸\\x 方在补阵。治神魂恍惚，梦泄遗精。 \n《本事》\\x猪苓丸\\x 此方以行为止，治湿郁热滞，小水频数，梦遗精滑。 \n半夏（一两） 将半夏破如豆粒。用猪苓为末二两，先将一两炒半夏色黄，勿令焦，出火毒 \n，取半夏为末，糊丸桐子大，候干；用前猪苓末一半，又同炒微裂，入瓷瓶内养之。空心温 \n酒、盐汤下三、四十丸，常又服，于未申间以温酒下。 \n\\x泄泻经验方\\x 治泄泻饮食少进。 \n用糯米一升，水浸一宿沥干，慢火炒令极熟，磨细，罗如飞面，加怀山药一两，炒研末 \n，和米粉内。每日清晨用半盏，入白糖二匙，川椒末少许，将极滚汤调食，其味甚佳，且不 \n厌人，大有资补。久服之，其有精寒不能成孕者亦孕矣。 \n\\x固肠散\\x 治脾胃虚弱，内寒注泄，水谷不分，下痢脓血，赤少白多，肠滑腹痛，心腹胀 \n满，食减力乏。 \n陈米（炒，二两） 木香（一钱） 肉豆蔻（生） 粟壳（蜜炙，各二钱） 干姜（炮） 炙甘草（各二钱半） \n上为末。每服二钱，水一钟，姜三片，枣一枚，煎七分，不拘时温服。忌酒、猪肉、鱼 \n腥、生冷。 \n\\x白术圣散子\\x 方在热阵。治一切泻痢久不瘥。 \n（陈氏）\\x肉豆蔻丸\\x 方在小儿。治泻痢肠滑不止。 \n《医林》\\x固肠丸\\x 治泻痢日夜无度。 \n人参 附子（制） 阿胶（炒） 龙骨（研） 肉豆蔻（面煨） 赤石脂（煨，醋淬） 干姜（炒） \n木香（各一两） 白术（炒） 诃子肉（各二两） 沉香（五钱） \n上为末，粳米糊丸，桐子大。每服七、八十丸，米饮下。 \n《局方》\\x大断下丸\\x 治脏腑停寒，下痢不已。 \n干姜（炮） 高良姜 细辛（各两半） 附子（制） 牡蛎（ ） 龙骨（研） 赤石脂（煨） 肉豆 \n蔻（面煨） 诃子肉 枯矾 酸石榴皮（醋浸一宿，炙黄用，各一两） \n上为细末，醋煮面糊为丸，桐子大。每服五、七十丸，米饮送下。 \n（东垣）\\x椿皮散\\x 治血痢及肠风下血神效。 \n椿根白皮 枯白矾（各二两） 槐角子（四两） 炙甘草（一两） \n上为细末。每服三钱，米饮调下。 \n\\x桃花丸\\x 治肠胃虚弱，冷气乘之，脐腹搅痛，下痢肠滑不禁，日夜无度。此即仲景桃花 \n汤之法，方见热阵。 \n赤石脂（ ，醋淬） 干姜（炮，等分） \n上为末，汤浸蒸饼丸，梧子大。每服百余丸，食前米饮下，日三服。若痢久虚滑，去积 \n不已，用苍术二两，防风五钱，水一碗，煎至半碗，下此丸，小便利则安。 \n\\x生地黄汤\\x 治热痢便血，崩淋不止。 \n生地黄（五钱） 地榆（七钱半） 炙甘草（二钱半） \n上 咀。用水二钟，煎一钟，分空心日、晚二服。 \n\\x香梅丸\\x 治肠风下血，服之即止。 \n乌梅肉 白芷 百药煎（烧存性，等分） \n上为末，米糊丸，桐子大。每服五、六十丸，空心米汤下。 \n\\x胜金丸\\x 一名百药散。治肠风下血，溺血不止，及脏毒便血。 \n百药煎（三两） 生用（一两） 炒焦（一两） 烧存性（一两） \n上为末，软饭和丸，或蜜丸，桐子大。每服五、七十丸，空心米饮下，或人参汤下。 \n《济生》\\x乌梅丸\\x 治大便下血如神。 \n僵蚕（炒，一两） 乌梅肉（一两半） \n上为末，醋糊丸，桐子大。每服四、五十丸，空心醋汤下。 \n\\x缩泉丸\\x 治脬气不足，小便频多。 \n乌药 益智（等分，为末） \n酒煮山药糊为丸，桐子大。每服五、七十丸，空心盐汤下。 \n\\x四味肉苁蓉丸\\x 治禀赋虚弱，小便遗数不禁。此即《集要》四神丸。（补阵一五八）。 \n熟地（六两） 五味子（四两） 肉苁蓉（酒洗去甲，八两） 菟丝子（制，二两） \n酒煮山药糊丸，桐子大。每服七、八十丸，空心盐汤下。 \n\\x固脬丸\\x 治遗尿不觉，小便不禁。 \n菟丝子（制，三两） 茴香（一两） 桑螵蛸（炙） 制附子（各五钱） 戎盐（一钱） \n上为末，酒煮面糊丸，桐子大。每服三十丸，空心米饮下。 \n\\x牡蛎丸\\x 治小便不禁。 \n牡蛎（三两，用瓷器盛，以盐末一两铺底盖面，用炭火约五斤烧半日，取出研） 赤石脂（三 \n两，捣碎，醋拌匀湿，于铁锅内慢火炒干，研粉）。 \n上用酒糊丸，桐子大。每服五十丸，空心盐汤下。 \n《心统》\\x茴香益智丸\\x 治老人阳虚失禁，及房劳伤肾遗溺。 \n小茴香（盐炒） 益智仁（炒） 故纸（酒炒） 川乌（炮） 乌药（各一两） \n上为末，山药糊丸，桐子大。每服八十丸，盐汤下。 \n\\x溺血方\\x \n文蛤（炒为末） \n上以乌梅肉浸烂捣膏丸，桐子大。空心酒下五、六十丸。 \n\n\n\n<目录>卷之六十宙集·古方八阵\\因阵\n\n<篇名>以下眼目方\n\n属性：《原机》当归补血汤 治男妇亡血过多，以致睛珠疼痛，不能视物，羞明酸涩，眼光无 \n力，眉骨太阳酸痛。 \n当归 熟地黄（各二钱） 白芍药 牛膝 白术 生地黄 天门冬（各一钱） 川芎 防风 炙 \n甘草（各五分） \n水二钟，煎八分，稍热服。如恶心不进食者，加生姜煎。 \n\\x益气聪明汤\\x 治目中内障初起，视觉昏花，神水淡绿色或淡白色，久则不睹，渐变纯白 \n，或视物成二等证，并治耳聋耳鸣。 \n人参 黄 （各五钱） 升麻 葛根 炙甘草（各三钱） 芍药 黄柏（各二钱） 蔓荆子（钱半） \n上每服四、五钱，水二钟，煎一钟，临睡热服，五更再服。 \n（东垣）\\x蔓荆子汤\\x 治劳倦饮食不节，内障眼病，此方如神。 \n蔓荆子（二钱半） 人参 黄 （各一两） 炙甘草（八钱） 黄柏（酒拌炒四遍） 白芍药（各三钱） \n上 咀。每服四、五钱，水二盏，煎一盏，去 ，临卧温服。 \n\\x益阴肾气丸\\x 治足三阴亏损，虚火上炎，致目睛散大，视物不的，或昏花紧涩，作痛羞 \n明，或卒见非常等证，其功与六味还少丹同类。 \n熟地（二两，酒洗） 生地 归尾（酒洗） 丹皮 五味 山药 山茱萸 柴胡 茯苓 泽泻 \n（各二钱半） \n炼蜜丸，桐子大，水飞朱砂为衣。每服五、七十丸，空心淡盐汤下。 \n\\x济阴地黄丸\\x 治证同上。 \n熟地（倍用） 山药 山茱萸 当归 枸杞 巴戟肉 麦冬 肉苁蓉 五味子 甘菊花（各等分） \n炼蜜丸，桐子大。每服七、八十丸，空心白汤下。 \n\\x神效黄 汤\\x 方在补阵。治目紧缩小，及羞明畏日，视物不明。 \n《局方》\\x明目地黄丸\\x 治男妇肝肾俱虚，风邪所乘，热气上攻，翳障，目涩多泪。 \n熟地黄 生地黄（各一斤） 牛膝（三两） 石斛 枳壳 杏仁（去皮尖，炒） 防风（各四两） \n炼蜜丸，桐子大。每服七、八十丸，食前盐汤下。 \n《简易》\\x加减驻景丸\\x 治肝肾气虚，两目昏暗，视物不明。 \n熟地 当归（各五两） 菟丝子（酒煮，八两） 枸杞 车前子（炒） 五味子（各二两） 楮实子 \n川椒（炒，各一两） \n上为末，炼蜜丸，桐子大。每服七、八十丸，食前温酒下。 \n（东垣）\\x滋阴地黄丸\\x 治足三阴亏损，虚火上炎，致目睛散大，视物不的，或昏花紧涩， \n作痛羞明，兼眵多燥热赤烂者。一名干熟地黄丸。 \n熟地（一两） 归身（酒制） 黄芩（各半两） 天冬（焙） 甘草（炙） 枳壳 柴胡 五味子（各三 \n钱） 人参 地骨（各二钱） 黄连（三钱） 生地（酒洗，一两半） \n炼蜜丸，桐子大。每服百丸，食前茶汤下，日三服。 \n（谦甫）\\x还睛散\\x 治翳膜遮睛，昏涩泪出，瘀血 肉攀睛。 \n川芎 龙胆草 草决明 石决明 荆芥穗 甘菊花 茺蔚子 楮实子 白茯苓（各一两） \n白蒺藜（炒） 木贼 甘草（各七钱） 川椒（炒出汗，一钱） \n上为细末。每服二钱，食后茶清调下，日三服。忌一切鸡鱼浓味，及荞麦面热物。 \n\\x八味还睛散\\x 治肝肺停留风热，翳膜遮睛，痛涩眵泪。 \n白蒺藜（炒去刺） 防风 甘草 木贼 山栀仁（各七钱） 草决明（一两，炒） 青葙子（二钱半， \n炒） 蝉蜕（二钱） \n上为细末。每服二钱，食后麦门冬汤调服。 \n\\x还睛丸\\x 治男妇风毒上攻，眼目肿痛，怕日羞明，多眵，陷涩难开，睑 红烂，瘀肉攀 \n睛，或暴赤痛甚，又治偏正头风头痛，皆有奇效。 \n白术 菟丝子（制） 青葙子 防风 羌活 白蒺藜（炒去刺） 密蒙花 木贼 炙甘草（等分） \n炼蜜丸，弹子大。每服一丸，细嚼，白汤送下，空心食前，日二服。 \n《正传》\\x祖传固本还睛丸\\x 治远年一切目疾，内外翳膜遮睛，风弦烂眼，及老弱人目眵 \n多糊，迎风冷泪，视物昏花等症，悉皆治之。 \n天门冬（酒浸一宿，另研如泥） 麦门冬 生地黄（酒浸焙） 熟地黄（酒洗，各三两） 人参 \n白茯苓 干山药 枸杞（各两半） 川牛膝（酒洗） 石斛（酒洗） 草决明（微炒） 杏仁（去皮 \n另研） 枳壳（面炒黄） 菟丝子（酒浸煮） 甘菊花（用小金钱，各一两） 羚羊角（细锉取净末） \n乌犀角（锉用） 青葙子（微炒） 防风（去芦，各八钱） 五味子（焙干） 炙甘草 黄连（去须） \n白蒺藜（取仁） 川芎（各七钱） \n上为末，蜜丸，梧子大。每服五、七十丸，盐汤下。 \n\\x定志丸\\x 方在补阵。治阳气不足，眼目不能近视。 \n地芝丸 治目不能远视，但可近视，或并不能，乃阴气不足也，宜用此方。 \n生地黄（四两） 天冬 枳壳（面炒） 甘菊花（各一两） \n炼蜜丸，桐子大。每服百丸，茶清或温酒下。 \n（东垣）\\x助阳和血汤\\x 治眼发之后，犹有上热，白睛赤色，隐涩难开而多眵泪等证。 \n黄 当归（酒洗） 柴胡 炙甘草 防风（各五分） 升麻（七分） 白芷（三分） 蔓荆子（二分） \n水煎热服。 \n（东垣）\\x芎辛散\\x 治两眼风热，昼夜隐涩难开，羞明恶日，视物昏暗，赤肿而痛。 \n细辛（二分） 芎 蔓荆子（各五分） 甘草 白芷（各一钱） 防风（一钱半） \n上 咀。水二盏，煎一盏，临卧温服。 \n（东垣）\\x明目细辛汤\\x 治两目发赤微痛，羞明畏日，怯风，恶灯火，多眵隐涩，鼻塞流涕 \n，津唾稠粘，大便微硬。 \n细辛 麻黄 羌活 蔓荆子 防风 本 川芎 荆芥穗 白茯苓（各四分） 生地黄 归 \n尾（各八分） 花椒（七粒） \n水二钟，煎八分，食后、临卧稍热服。 \n\\x决明夜光散\\x 治眼目夜昏，虽有灯月亦不能视。 \n石决明 夜明砂（各二钱） 猪肝（一两） \n上以药为末，乃将竹刀切肝为二片，铺药于内，合定，用麻皮缚之，以米泔水一碗，用 \n砂锅煮至半碗，临卧连肝、连汁俱服之。 \n\\x石斛夜光丸\\x 治神水散大，昏如雾露，眼前黑花，睹物成二，久而光不收敛，及内障瞳 \n人淡白绿色。 \n石斛（酒洗，五钱） 人参 生地 熟地（酒洗） 麦门冬 天门冬 白茯苓 防风 草决明 \n黄连（酒炒，各一两） 羚羊角（镑） 犀角（镑） 川芎 炙甘草 枳壳（面炒） 青葙子（微炒） \n五味子（炒） 肉苁蓉（酒洗去鳞，炙，各五钱） 牛膝（酒洗） 白蒺藜（炒去刺） 菟丝子（制） \n家菊花 山药 杏仁 枸杞（各七钱） \n上为末，炼蜜丸，梧子大。每服三、五十丸，温酒、盐汤任下。 \n（东垣）\\x泻热黄连汤\\x 亦名黄连饮子。治眼暴发赤痛。 \n黄连（酒炒） 黄芩（酒炒） 龙胆草 生地 柴胡（各一钱） 升麻（五分） \n水煎。于午前，或饭后热服。 \n（东垣）\\x黄芩黄连汤\\x 治两眼血热赤痛。 \n黄芩 黄连 草龙胆（俱各酒洗，炒） 生地（酒洗） \n上等分， 咀。每用五钱，水二盏，煎一盏，去 ，热服。 \n（东垣）\\x当归龙胆汤\\x 治眼中白翳。 \n归身 龙胆草（酒洗） 黄芩（酒炒） 黄柏（酒炒） 芍药（各八分） 黄 黄连 甘草（各五 \n分） 防风 羌活 升麻 柴胡 五味子 石膏（各五分） \n水二盏，煎一盏，去 ，入酒少许。临卧热服。忌言语。 \n\\x芍药清肝散\\x 方在寒阵。治赤脉贯晴，眵多 燥，紧涩羞明，脏腑秘结。 \n\\x蝉花散\\x 治肝经风热，毒瓦斯上攻，眼目赤痛，及一切内外翳障。 \n蝉蜕 甘菊花 谷精草 羌活 甘草（炒） 白蒺藜（炒） 草决明 栀子（炒） 防风 密 \n蒙花 荆芥穗 木贼 川芎 蔓荆子 黄芩（各等分） \n上为末。每服二钱，食后茶清调下。 \n\\x五味泻白散\\x 治风热翳膜血筋，一切肺热外障。 \n当归 生地 芍药 栀子 黄芩（各等分） \n每服三、五钱，为散，为汤任服。 \n\\x明目羊肝丸\\x 治肝虚风热，冷泪赤涩，内外障眼。 \n黄连（三两） 家菊花 龙胆草 石决明（ ） 人参 当归 熟地 枸杞 麦冬 牛膝 青 \n盐黄柏 柴胡 防风 羌活（各八钱） 肉桂（四钱） 羯羊肝（一具，烙干为末） \n上为末，炼蜜丸，桐子大。每服三、四十丸，温汤下。 \n\\x黄连羊肝丸\\x 治前证。 \n单用黄连一味，同羊肝俱为末，炼蜜丸服。《济生方》用生羊肝去筋膜，同黄连捣丸， \n桐子大。每服五、六十丸，温水下。 \n\\x黄连天花粉丸\\x 治两眼赤痛，眵多 燥，紧涩羞明，赤脉贯睛，脏腑秘结。 \n黄连（酒炒） 天花粉 家菊花 川芎 薄荷叶 连翘（各一两） 黄芩 栀子（各四两） 黄柏 \n（酒炒，六两） \n上为细末，滴水丸，梧子大；或用蜜丸。每服五、七十丸，或百丸，食后、临睡茶汤下。 \n《局方》\\x密蒙花散\\x 治风气攻注，两眼昏暗，眵泪羞明，并暴赤肿翳障。 \n密蒙花 羌活 白蒺藜（炒） 木贼 石决明（各一两） 甘菊（三两） \n上为末。每服二钱，食后茶清调下。 \n\\x春雪膏\\x 点赤眼。 \n朴硝置豆腐上蒸之，待流下者，瓦器盛点之。 \n\\x玄明春雪膏\\x 治时气热眼。 \n玄明粉（半两） 月石（三钱） 冰片（三分） \n上乳无声，瓷罐密收，用时点二大 内。 \n\\x龙脑黄连膏\\x 点赤热眼。 \n龙脑（一钱） 黄连（去毛净，酒炒，八两） \n先锉黄连令碎，以水四碗贮砂锅内，入连煮至一大碗，滤去滓，入薄瓷碗内，重汤煮成 \n膏半盏许，以龙脑为引，或用时旋入尤妙。 \n\\x立消膏\\x 治浮翳宿障，雾膜遮晴。 \n雪白盐（净器中生研如尘） \n上以大灯草蘸盐少许，轻手指定浮翳点上，凡三次即没，亦不疼痛。 \n\\x黄连甘石散\\x 治眼眶破烂，畏日羞明。 \n炉甘石（制，一斤） 黄连（四两） 龙脑（量加） \n先以黄连研极细，同甘石再研，俱用细绉纱筛过收贮。用时取一、二两加入龙脑，用井 \n花水调如稠糊，临睡抹敷破烂处，不破烂者点眼内 ，勿使入眼珠内为妙。 \n\\x黄连人参膏\\x 治目赤痒痛。 \n宣黄连 人参（各五分或一钱） \n上切碎，用水一小钟同浸，饭锅蒸少顷，取出冷定，频点眼角自愈，或于临用时研入冰 \n片少许更妙。一方但用人乳浸黄连频点 中，《抱朴子》云∶治目中百病。一方用黄连少加 \n生白矾，以人乳浸蒸，点抹眼角大效。 \n\\x丹砂散\\x 点治诸眼皆妙，此李时珍方也。 \n硼砂 海螵蛸（去壳） 炉甘石（上好者， 淬童便七次，飞，各一两） 朱砂（五钱，用此则不粘） \n上为极细末，瓷瓶收贮。临用少加冰片研点极妙。 \n\\x清凉膏\\x 治眼目赤肿不能开，痛闷，热泪如雨。 \n生南星 脑荷叶（各半两） 荆芥 百药煎（如无，即用文蛤） \n上各三钱，为末，井水调成膏。点眼角上，自然清凉。 \n《正传》\\x光明丹\\x 治一切风热上壅，两目赤肿涩痛，烂弦风眼，及内外翳障。 \n制甘石（一两） 朱砂（一钱） 硼砂（二钱） 轻粉（五分） 冰片（三分） 麝香（一分） \n以上用乳钵研极细，收贮为君。如眼赤肿痛，加乳香、没药各五分；内外翳障，加珍珠 \n五分，胆矾二分。烂弦风眼，加铜绿五分，黄丹五分；或以诸药合一，以治诸般眼疾。上各 \n研为细末，并一处再研二日，用瓷器密收，勿令泄气，点、服绝妙。 \n\\x青火金针\\x 治头风牙痛赤眼。 \n火硝（一两） 青黛（一钱） 脑荷 川芎（各五分） \n上为细末。口噙冷水勿咽，用此药吹鼻。 \n\\x赤火金针\\x 治赤眼头风冷泪，鼻塞耳鸣牙疼。 \n火硝（一两） 川芎 雄黄 乳香 没药 石膏（各一钱） \n上为细末。每服一、二分；如前吹鼻，三次愈。 \n吹鼻六神散 治眼目暴发赤肿，热泪昏涩，及头脑疼痛。 \n焰硝（提净，五钱） 白芷 雄黄 乳香（制） 没药（制） 脑荷叶（各一钱） \n上为细末，瓷罐收贮。左吹左，右吹右，先令病患口含水吹之，其气上行，须臾觉效。 \n头痛吹法亦然，或两鼻皆吹之。若久患眼疾者，不可吹。 \n（东垣）\\x点盐法\\x 明目，去昏翳。大利老眼，得补法之良。 \n用海盐（二斤，拣净），以百沸汤泡，滤取清汁，于银石器内熬取雪花白盐，瓷器盛贮。每 \n早用一钱擦牙，以水漱口，用左右手指互以口内盐津细洗两眼大小 内，闭目良久，却用水 \n洗面。能洞视千里，明目坚齿，极妙之法，苏东坡手录。目赤不明，昏花老眼，惟宜此法， \n大效。 \n\\x洗烂弦风赤眼方\\x 一名万金膏。此药之效如神，人家所不可少，无目病则以施人，价廉功倍，济人甚大。 \n文蛤 黄连（去毛净） 防风 荆芥穗（各五钱） 苦参（四钱） 铜绿（五分） \n上为极细末，外以薄荷煎汤丸，弹子大。临用时以热水化开，乘热洗眼，日三次。立愈 \n神效。一方有当归、川芎各四钱。 \n\\x傅烂弦歌\\x \n烂弦百药煎为奇，研细汤澄 去之，熬作稀膏入轻粉，盐汤洗了敷之宜。 \n\\x搜风散\\x 箍风热眼及肿痛。 \n黄连 大黄 朴硝 黄丹（等分） \n上为末，以苦参煎汤，少加炼过白蜜，同调敷眼四弦，甚妙。 \n\\x拜堂散\\x 敷风赤热眼，倒睫烂弦。 \n五倍子不拘多少为末，蜜水调敷患处。 \n\\x汤泡散\\x 治肝虚风热攻眼，赤肿羞明，渐生翳膜。 \n杏仁 防风 黄连（去须） 赤芍药 归尾（各半两） 铜青（二钱） 薄荷叶（三钱） \n上锉散，每用三、四钱，沸汤泡。乘热先熏后洗，冷则再暖又洗，每日三、两次。一方 \n加白盐少许，闭目沃洗，尤能散血。 \n\\x收泪散\\x 治风泪不止。 \n海螵蛸（五分） 冰片（少许） 绿炉甘石（一钱） \n上乳极细末，点大 角，泪即收，上二药以燥湿，片脑以辛散。 \n去星 \n凡胡椒、韭菜根、橘叶、菊叶之类，皆可杵烂为丸，用棉裹塞鼻中触之，过夜则星自下。 \n眼目打伤青肿。 \n以生半夏为末，水调涂之即愈。 \n\\x明目第一方\\x 此方始于上阳子，以授鲁东门左丘明，杜子夏、左太冲，凡此诸贤皆有目 \n疾，得此皆愈。夜省看书一，减思虑二，专内视三，简外视四，晨兴迟五，夜眠早六。 \n凡此六事，熬以神火，下以气饮，蕴于胸中，纳诸方寸，修之一时，长服不已，非但明 \n目，亦可延年。 \n\n\n\n<目录>卷之六十宙集·古方八阵\\因阵\n\n<篇名>以下耳病方\n\n属性：\\x桂星散\\x 治风闭耳聋。 \n官桂 川芎 当归 石菖蒲 细辛 木通 木香 白蒺藜（炒去刺） 麻黄（去节） 甘草 \n（炙，各一钱） 白芷梢 天南星（煨裂，各钱半） \n水二钟，葱白二根，紫苏五叶，姜五片，煎八分，食后服。一方加全蝎去毒一钱。 \n《类方》\\x复元通气散\\x 治诸气闭涩耳聋，及腹痈、便痈、疮疽无头者，能止痛消肿。 \n青皮 橘红（各四两） 甘草（炙，三寸） 连翘（一两） \n上为末。热酒调服一、二钱。 \n\\x补肾丸\\x 治肾虚耳聋。 \n巴戟（去心） 干姜（炮） 白芍药 山茱萸 人参 黄 当归 熟地黄 远志（制） 肉 \n苁蓉（酒浸） 菟丝子（制） 蛇床子 牡丹皮 附子（炮） 石斛 细辛 泽泻 桂心 甘草（各 \n二两） 石菖蒲（一两） 茯苓（半两） 防风（一两半） 羊肾（二枚） \n上为末，将羊肾用酒煮，研烂，仍加酒煮面糊丸，桐子大。每服五、七十丸，空心盐酒送下。 \n聪耳益气汤 治肾虚耳聋。 \n黄 （一钱） 人参 炙甘草 当归（酒洗） 白术（各五分） 橘红 菖蒲 防风 荆芥（各三分） \n升麻 柴胡（各二分） \n上水煎服。 \n\\x肉苁蓉丸\\x 方在补阵。治肾虚耳聋。 \n\\x 耳明矾散\\x 治脓耳。 \n枯矾 龙骨（研，各二钱） 黄丹（飞，钱半） 干胭脂（七分） 麝香（少许） \n上为细末。先须以绵杖缠拭去脓，别用绵杖蘸药引入耳中。如无干胭脂，即以济宁油胭 \n脂同枯矾拌擦如粉用之。又，红玉散∶止枯矾、干胭脂、麝香三味，等分用。一方∶单用枯 \n矾，吹入即愈。 \n\\x 耳流脓方\\x \n用菖蒲根水洗净，捣取汁，先以绵 将耳中脓水搅净，然后将蒲汁灌入荡洗数次 \n，全愈最妙者。 \n\\x白龙散\\x 治小儿肾热上冲于耳，生脓作痛，或因沐浴水入耳中，亦令作脓，谓之 耳， \n久而不愈则成聋。 \n枯矾 黄丹 龙骨（各五分） 麝香（一分） \n上为极细末。先以绵杖子展尽耳内脓水，用药一字，分掺两耳，日二次。勿令风入。 \n百虫入耳。 \n用香油滴入耳中即出。《本事方》用白胶香烧烟熏耳中，暖即出。一方用葱涕灌入，活 \n者即出。一法用生姜擦猫鼻，其尿自出，取尿滴入，虫即出。或以麻油滴耳则虫死。或以炒 \n芝麻枕头，则虫亦出，但不若猫尿之捷也。 \n蜈蚣入耳。 \n用姜汁滴入，或韭汁、鸡冠血滴入俱好。 \n\\x暴聋灸法\\x \n用小苍术一块长七分，一头削尖，头截平，将尖头插入耳内，平头上用箸头大艾炷灸之 \n，轻者七壮，重者十四壮，觉耳内有热气则效。 \n又方∶用鸡心槟榔一个，将脐内剜一窝如钱眼大，实以麝香，坐于患耳内，上以艾炷灸 \n之，不过二、三次即效。 \n\\x塞耳聋\\x \n用大蒜一瓣，一头剜一坑子，好巴豆一粒，去皮，慢火炮令极熟，入在蒜内，以新绵裹定塞耳中。 \n\\x龙脑膏\\x \n龙脑（一分） 椒目（五分） 杏仁（去皮，二分） \n上件捣研匀，绵裹枣核大，塞耳中，日二易之。 \n\\x杏仁膏\\x 治耳中汁出，或痛或脓。 \n上用杏仁炒令赤黑，研成膏，绵裹内耳中，日三、四度易之，或乱发裹塞之亦妙。 \n一方治耳卒痛或水出，用杏仁炒焦为末，葱涎搜和为丸，以绵裹塞耳，又治耳聋兼有脓。 \n\\x通圣散\\x \n穿山甲（炙） 蝼蛄（各五分） 麝香（一分） \n上为细末，以葱涎和剂塞耳，或用少绵裹塞之，或用葱管盛药末塞耳中。 \n\\x通耳法\\x \n瓷石（用活者，如豆一块） 穿山甲（烧存性，为末，一字） \n上二味，用新绵裹塞患耳内，口中衔生铁少许，觉耳内如风雨声即愈。 \n\n\n\n<目录>卷之六十宙集·古方八阵\\因阵\n\n<篇名>以下面鼻方\n\n属性：《医林》\\x川芎散\\x 治风寒鼻塞。 \n川芎 本 细辛 白芷 羌活 炙甘草（各一两） 苍术（米泔浸，五两） \n上咀。每服三钱，水一盏，姜三片，葱白三寸，煎服。 \n《济生》\\x辛夷散\\x 治肺虚为四气所干，鼻内壅塞，涕出不已，或气不通，不闻香臭。 \n辛夷 川芎 细辛 白芷 升麻 防风 羌活 本 炙甘草 木通（各等分） 一方有苍耳子（减半） \n上为末。每服二钱，食后茶清调下。 \n\\x温肺散\\x 治闭塞阳明鼻塞。 \n升麻 黄 丁香（各一钱） 羌活 葛根 炙甘草 防风（各五分） 麻黄（不去节，二钱） \n水二钟，葱白二茎，煎八分，食远热服。 \n《千金》\\x细辛膏\\x 治鼻塞脑冷，清涕常流。 \n细辛 川芎 川椒 黑附子（炮，去皮脐） 干姜 吴茱萸（各二钱半） 桂心（三钱） 皂角屑（钱半） \n上将诸药用米醋浸过宿，次用猪脂二两熬油，入前药，煎附子色黄为度，以绵蘸药塞鼻中。 \n《三因》\\x苍耳散\\x 治鼻流浊涕不止，名曰鼻渊。 \n苍耳子（炒，二钱半） 辛夷仁 薄荷叶（各五钱） 白芷（一两） \n上为细末。每服二钱，葱汤或茶清食后调下。 \n\\x神愈散\\x 治风热在肺，鼻流浊涕，窒塞不通。 \n细辛白芷与防风，羌活当归半夏芎，桔梗陈皮茯苓辈，十般等分锉和同，三钱薄荷姜煎 \n服，气息调匀鼻贯通。 \n\\x醍醐散\\x 治伤风鼻塞声重。 \n细辛（半两） 川芎（一两） 薄荷（一两半） 川乌（炮，去皮脐） 白芷 甘草（各二两） \n上为细末。每服一钱，葱茶汤或薄荷汤下。 \n《良方》\\x防风汤\\x 治鼻塞不闻香臭。 \n防风 麻黄 官桂（各半两） 升麻 木通（各一两） 栀子（七枚） 石膏（三两） \n上 咀。每服水一盏，煎七分，空心温服。 \n《宣明》\\x防风汤\\x 治鼻渊脑热渗下，浊涕不止，久而不已，必成衄血之证。 \n防风（一两半） 人参 麦冬 炙甘草 川芎 黄芩（各一两） \n上为细末。每服二钱，沸汤调服，食后，日三服。 \n\\x荆芥散\\x 治肺风酒 鼻赤 。 \n荆芥穗（四两） 防风 杏仁（去皮尖） 白蒺藜（炒，去刺） 僵蚕（炒） 炙甘草（各一两） \n上为末。每服二钱，食后茶清调下。 \n《正传》\\x脑漏秘方\\x 祖传经验治鼻中时时流臭黄水，甚者脑亦时痛，俗名控脑砂，有虫食脑中。 \n用丝瓜藤近根三、五尺许，烧存性，为细末，酒调服之即愈。 \n《简易》\\x黄白散\\x 治鼻 、 肉、鼻痔等症。 \n白矾 雄黄 细辛 瓜蒂（炒，各等分） \n上为细末，以雄犬胆汁为剂，如枣核，塞鼻中。 \n\\x细辛散\\x 治鼻 有 肉，不闻香臭。 \n北细辛 瓜蒂（等分） \n上为末，棉裹如豆大，塞鼻中。 \n《御药》\\x菖蒲散\\x 治鼻内窒塞不通，不得喘息。 \n菖蒲 皂角（等分） \n上为细末，每用一钱，绵裹塞鼻中，仰卧片时。 \n\\x轻黄散\\x 治鼻中 肉。 \n轻粉 杏仁（去皮尖，各一钱） 雄黄（五钱） 麝香（少许） \n上四味，用乳钵先研杏仁如泥，后入雄、麝、轻粉同研极细，瓷盒收盖。每有患者，不 \n拘远近，于卧用箸头蘸米粒许点 肉上，隔一日卧点一次，半月见效。 \n\\x雄黄散\\x 治鼻 。 \n雄黄（五分） 瓜蒂（二个） 绿矾（一钱） 麝香（少许） \n上为末，吹入鼻中。 \n\\x千金 肉方\\x 一名瓜丁散。 \n瓜蒂 华阴细辛（等分） \n为末，绵包少许塞鼻中。 \n\\x简易 肉方\\x \n用枯白矾为末，以绵胭脂塞鼻中，数日肉随落。 \n\\x白矾散\\x 治肺风酒 鼻等疾。 \n白矾 硫黄 乳香（各等分） \n为末，绵裹擦之。或用茄汁调敷患处更妙。 \n\\x二神散\\x 治赤鼻久不瘥。 \n大黄 朴硝（等分） \n为末，津调涂鼻上。 \n\\x酒 鼻粉痔\\x 亦名硫黄散。 \n硫黄 轻粉（各一钱） 杏仁（五分） \n上为末，用蜜酒调，于卧时涂上，早洗去，效。或用津唾调搽更妙。又方∶只以铜绿为 \n末，晚时切生姜蘸擦之。 \n\\x点痣去斑\\x \n用锻石水调一碗如稠糊，拣好糯米粒全者，半置灰中，半露于外，经一宿，灰中米色变 \n如水晶。若或面或手有黑痣黑靥及纹刺者，先须针头微微拨破，置少许水晶者于其上，经半 \n日许，靥痣之汗自出，乃可去药，且勿着水，二、三日则愈。 \n\\x面鼻雀斑\\x 此连子胡同方。 \n白芷 甘菊花（各三钱，去梗） 白果（二十个） 红枣（十五个） 珠儿粉（五钱） 猪胰（一个） \n上将珠粉研细，余俱捣烂拌匀，外以蜜拌酒酿炖化，入前药蒸过，每晚搽面，早洗去。 \n\\x面疮二方\\x \n面上暴生疮∶用生杏仁捣烂，以鸡子清调如煎饼，至夜洗面敷之，旦洗去，数十次愈。 \n指甲抓破面∶用生姜自然汁调轻粉敷破处，无痕。 \n\\x止鼻衄方\\x \n龙骨为细末，吹入鼻中少许即止。凡九窍出血者，用此皆能治之。 \n\\x止鼻衄歌\\x \n石榴花瓣可以塞，萝卜藕汁可以滴，火 龙骨可以吹，水煎茅花可以吃。 \n又∶墙头苔藓可以塞，车前草汁可以滴，火烧莲房可以吹，水调锅煤可以吃。 \n\\x鼻衄蒸法\\x 治衄如涌泉不止者。 \n用草纸折十余层，井花水湿透，分发贴顶心中，以热熨斗熨之，微热不妨，久之即止。 \n\\x鼻塞不通葱熨法\\x \n但用葱头，以绳束成一把，去根头实处，切成寸长一饼。先以熨斗烙葱一面令热，置顶 \n心囟会穴处，乃以熨斗或火从上熨之，俟鼻内作葱气方住。未通，再作饼熨之。其有婴儿伤 \n风，鼻塞不能吮乳者，但用大南星为末，以生姜自然汁和作薄饼，用两掌合暖置囟上，片时 \n即通。 \n\\x硝石散\\x 治风邪犯脑，患头痛不可忍，不问年岁。 \n硝石 人中白（等分） 冰片（少许） \n上为末，用一字，吹入鼻中。 \n《良方》\\x通关散\\x 治卒然牙关紧急，腰背反张，药不能咽，或时毒痈肿，鼻塞气闭等证。 \n细辛（如无真者，不用亦可） 薄荷叶 牙皂角（等分） \n上为细末，以纸捻少许入鼻内，候得喷嚏口开，随进汤药。《圣惠》搐鼻法止用 \n二味，无薄荷。 \n（陈氏）\\x通关散\\x 方在痘疹。通心经，降心火，利小便良方。 \n\\x擦牙通关散\\x 方在小儿。治风搐关窍不通，痰塞中脘，留滞百节。 \n\n\n\n<目录>卷之六十宙集·古方八阵\\因阵\n\n<篇名>以下口舌方\n\n属性：《良方》\\x玄参散\\x 治满口并舌生疮，连齿龈烂痛。 \n玄参 黄芩 黄柏 栀子仁 大黄 前胡 独活 犀角屑 麦冬 升麻 炙甘草（各等分） \n上为咀。每服五钱，水一钟半，煎七分，不拘时温服。 \n\\x玄参升麻汤\\x 方在外科。治口舌生疮，重舌木舌，腮颊咽喉肿痛，斑疹疮疡。 \n\\x清凉饮子\\x 治上焦积热，口舌咽鼻干燥。 \n黄芩 黄连（各二钱） 薄荷 玄参 当归 芍药（各钱半） 甘草（一钱） \n水二钟，煎八分，不拘时服。大便秘结，加大黄二钱。 \n\\x清热化痰汤\\x 治上焦有热，痰盛作渴，口舌肿痛。 \n贝母 天花 枳实 桔梗（各一钱） 黄芩 黄连（各钱二分） 玄参 升麻（各七分） 甘草（五分） \n水煎服。 \n\\x甘露饮\\x 方在寒阵。治口舌生疮，咽喉肿痛，牙龈溃烂。 \n\\x龙胆泻肝汤\\x 方在寒阵。治肝火内炎，上为喉口热疮，下为小便涩痛等症。 \n\\x五福化毒丹\\x 方在外科。治咽喉牙口疮毒痈肿。 \n《良方》\\x冰柏丸\\x 治舌疮口疮。 \n薄荷叶（苏州者） 黄柏（等分） 硼砂（半之） 冰片（一分） \n上为末，生蜜丸，弹子大。每服一丸，噙化。 \n\\x上清丸\\x 治口舌生疮，咽喉肿痛，止嗽清音，宽膈化痰，极效。 \n砂仁 桔梗（各一钱） 月石（二钱） 冰片（一分） 甘草 玄明粉 诃子（各一钱） 百药煎（八钱） \n苏州薄荷叶（一两六钱） \n为极细末，炼蜜丸，芡实大。临睡含化一丸。或为小丸，茶清送下。 \n\\x硼砂丸\\x 治口疮舌疮。 \n寒水石（一两） 牙硝（四钱） 硼砂（二钱） 冰片 麝香（各一分） \n甘草膏和丸，麻子大。不时含化一丸，津咽。 \n《良方》\\x圣金散\\x 治舌上出血不止。 \n黄药子（一两） 青黛（一钱） \n上为细末。每服一钱，食后新汲水调下，日二服。 \n\\x金花煎\\x 治舌上出血如簪孔。 \n黄柏（三两） 黄连（五钱） 栀子（二十枚） \n上咀。以水二升，浸一宿，煮三沸，去滓。顿服。一方用酒浸煮。 \n\\x飞矾散\\x 治木舌渐肿大满口，若不急治即杀人。 \n白矾（飞） 百草霜（等分） \n上为细末。捻糟茄自然汁调服，若口噤，灌之妙。 \n\\x寸金散\\x 治心经烦热，动血妄行，舌上出血不止。 \n新蒲黄（三钱） 新白面（三钱） 牛黄（五分，研） 脑荷（五分，研） \n上研匀。每服一钱，生藕汁调服，食后。亦可掺舌上。 \n\\x黄柏散\\x 治舌出血不止，名曰舌衄。 \n黄柏（不拘多少，涂蜜慢火炙焦为末） \n上每服二钱，温米饮调下。 \n舌上出血重出。 \n\\x升麻黄连丸\\x 治多食肥甘，口臭秽恶。 \n升麻（半两） 黄连 黄芩（酒炒） 生姜 檀香 甘草（各二钱） 青皮（半两） \n上为细末，汤泡蒸饼丸，弹子大。每服一丸，不拘时，细嚼，白汤下。 \n\\x丁香丸\\x 治口臭秽。 \n丁香（二钱） 川芎（二钱） 白芷（五分） 炙甘草（一钱） \n上为末，炼蜜丸，弹子大。绵裹一丸噙化。 \n\\x应手散\\x 治伤寒舌出寸余，连日不收。 \n梅花冰片。 \n为末。搽舌上，应手而收，重者须用一钱方收。 \n\\x阴阳散\\x 亦名赴筵散。治口疮效。 \n黄连（一两） 干姜（炒黑，三钱） \n为细末。干掺口疮上，涎出即愈。 \n《外科》\\x阴阳散\\x 方在外科。治疮属半阴半阳者。 \n\\x绿云散\\x 治口疮烂臭久不愈。 \n黄柏（蜜炙） 青黛（等分） \n上为细末。临卧用少许掺舌咽津妙。 \n\\x细辛黄柏散\\x 治口舌疮。 \n黄柏 细辛（等分） \n上为末敷之，或掺舌上，吐涎水，再敷，须旋合之。 \n\\x白蚕黄柏散\\x 治口糜。 \n黄柏（蜜炙） 白僵蚕（直者，新瓦上烙干断丝） \n上为细末。用少许敷疮上，吐涎。 \n\\x硼砂散\\x 治口疮。 \n硼砂 青黛 龙脑薄荷 石膏（ ，各等分） \n上为极细末。每用少许，临卧敷口中。 \n\\x黄莲朴硝散\\x 治口疮绝妙。 \n黄连 朴硝 白矾（各五钱） 薄荷叶（一两） \n上为粗末，用腊月黄牛胆将药入胆内，风前挂两月取下。如遇口疮，旋将药研细敷之， \n去其热涎即愈。 \n\\x柳华散\\x 治热毒口疮。 \n黄柏（炒） 蒲黄 青黛（真者） 人中白（ ） \n上等分，为末敷之。 \n掺口疮 \n天竺黄 月石（等分） 冰片（少许） \n为末掺之。 \n\\x碧雪\\x 治一切热壅，口舌生疮，舌强腮肿，咽喉肿痛等症。 \n蒲黄 青黛 硼砂 焰硝 甘草（等分） \n上为细末。每用少许掺舌上，细细咽下，或饮凉水送下，频用之效。或用砂糖丸，芡实 \n大，每服一丸，噙化下咽妙。 \n\\x绛雪\\x 治口疮舌疮，咽喉肿痛。"}]);
})();
